UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Форма","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1033_1.png","description":"При применении Спокойствия дает Адлеру 20 уровней кармы."},{"level":2,"kind":"awakening","name":"Чувство","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1033_2.png","description":"Каждый уровень кармы дает Адлеру бонус к урону 3 %."},{"level":3,"kind":"awakening","name":"Восприятие","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1033_3.png","description":"Увеличивает щит Благословения на 20 %."},{"level":4,"kind":"awakening","name":"Формация","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1033_4.png","description":"Когда Благословение разрушается, поглощает часть избыточного урона на основании 50 % от защита Адлера."},{"level":5,"kind":"awakening","name":"Распознание","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1033_5.png","description":"При применении Спокойствия дает Адлеру 20 ед. энергии сверхспособности."},{"level":6,"kind":"awakening","name":"Все формы пусты","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1033_6.png","description":"Увеличивает длительность Благословения до 12 сек."},{"level":3,"kind":"resonance","name":"Очищение","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень навыков «Избавление», «Проклятие зла» и «Спокойствие» на 1."},{"level":6,"kind":"resonance","name":"Просвещённый хранитель","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Увеличивает урон от чар команды на 10 %, когда её защищает Благословение."}]') WHERE character_id='adler' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-27 10:18:27');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"en-Play_Vo_Char_NPC010_hobby_001","title":"Хобби","description":"Кулинария требует дисциплины… от выбора ингредиентов до получения отзыва, каждое блюдо — уникальное путешествие. Мне нравится готовить для всех в «Эйбоне», хотя лучше бы Сакири не была такой привередой.","language":"Английский","audioUrl":"/nte-meta/game-audio/121299d8b5a20b9ddd08.ogg"},{"id":"ja-Play_Vo_Char_NPC010_deploy_002","title":"Отправка I","description":"Полезно немного потренироваться.","language":"Японский","audioUrl":"/nte-meta/game-audio/339541739f878ec225b2.ogg"},{"id":"ja-Play_Vo_Char_NPC010_weather_002","title":"Дождливо","description":"Кажется, прогнозы погоды не всегда надежны. Давай найдем, где переждать дождь.","language":"Японский","audioUrl":"/nte-meta/game-audio/73a6b8eacba6bcfd12bc.ogg"},{"id":"ja-Play_Vo_Char_NPC010_dead_003","title":"Потеря сознания III","description":"Прости, что разочаровал.","language":"Японский","audioUrl":"/nte-meta/game-audio/feba75d0a2ad1e4916f0.ogg"},{"id":"ja-Play_Vo_Char_NPC010_gift_003","title":"Подарок получен III","description":"Оценщик, я всегда знал, что у вас превосходный вкус.Оценщица, я всегда знал, что у вас превосходный вкус.","language":"Японский","audioUrl":"/nte-meta/game-audio/ebc484e48a433ddcf861.ogg"},{"id":"ja-Play_Vo_Char_NPC010_talk_002","title":"Тема: этикет","description":"Опрятный внешний вид производит хорошее впечатление, но истинный этикет заключается в том, чтобы учитывать чувства других, а не насаждать свои привычки. Принуждение других следовать нашим принципам — грубейшее нарушение этикета.","language":"Японский","audioUrl":"/nte-meta/game-audio/6ae5e8c7a573472df8e4.ogg"},{"id":"voice-6dwxfr","title":"О Сакири","description":"Прямая запись английской озвучки. Расшифровку и соответствие реплики проверьте в источнике перед публикацией.","language":"Английский","audioUrl":"https://static.wikia.nocookie.net/neverness-to-everness/images/2/2d/VO_Adler_About_Sakiri.ogg/revision/latest","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"ja-Play_Vo_Char_NPC010_anomaly_003","title":"Нуллификация I","description":"Нужно что-нибудь, чтобы восстановить силы?","language":"Японский","audioUrl":"/nte-meta/game-audio/f774e0d376d6b6a8649f.ogg"},{"id":"en-Play_Vo_Char_NPC010_DodgeCombo_001","title":"Серия критических уклонений I","description":"Я кое-чему научился.","language":"Английский","audioUrl":"/nte-meta/game-audio/dad96d895ababa181ed4.ogg"},{"id":"en-Play_Vo_Char_NPC010_ug_001","title":"Вознесение персонажа I","description":"Учение не знает границ.","language":"Английский","audioUrl":"/nte-meta/game-audio/ec180b37d89ffe5eded9.ogg"},{"id":"ja-Play_Vo_Char_NPC010_meet_001","title":"Первая встреча","description":"Добро пожаловать в «Эйбон». Я Алоис фон Адлер, дворецкий. Пожалуйста, зови меня Адлер. Если что-то понадобится, дай знать. Я к твоим услугам.","language":"Японский","audioUrl":"/nte-meta/game-audio/2dc6dd20bcbce84fc460.ogg"},{"id":"ja-Play_Vo_Char_NPC010_windfall_005","title":"Неожиданная добыча V","description":"Как насчет устроить сегодня особенный ужин?","language":"Японский","audioUrl":"/nte-meta/game-audio/bc81716445a486a0dab2.ogg"},{"id":"en-Play_Vo_Char_NPC010_skill_003","title":"Навык перенаправления III","description":"Осмысли.","language":"Английский","audioUrl":"/nte-meta/game-audio/4ae643482c0863a402bb.ogg"},{"id":"en-Play_Vo_Char_NPC010_TeammateDown_002","title":"Поражен товарищ по команде – Наналли","description":"Наналли, не нагружай себя так!","language":"Английский","audioUrl":"/nte-meta/game-audio/8369a82675b8392a2efe.ogg"},{"id":"ja-Play_Vo_Char_NPC010_kill_001","title":"Убийство I","description":"Ты в порядке?","language":"Японский","audioUrl":"/nte-meta/game-audio/db88daa2b1aeabd94674.ogg"},{"id":"ja-Play_Vo_Char_NPC010_about_003","title":"О Сакири","description":"Сакири не очень хорошо выражает свои чувства. Для такой чувствительной натуры, как она, поступки говорят громче слов. Она действительно переживает, но не показывает этого. Чтобы постепенно раскрыться, ей нужно личное пространство.","language":"Японский","audioUrl":"/nte-meta/game-audio/f1a2e64c122ecbbf84ed.ogg"},{"id":"ja-Play_Vo_Char_NPC010_Parry_002","title":"Парирование II","description":"Все то же мастерство.","language":"Японский","audioUrl":"/nte-meta/game-audio/99642ad07c5bbe73b7e9.ogg"},{"id":"voice-iekw4p","title":"О Тайгедо","description":"Прямая запись английской озвучки. Расшифровку и соответствие реплики проверьте в источнике перед публикацией.","language":"Английский","audioUrl":"https://static.wikia.nocookie.net/neverness-to-everness/images/d/de/VO_Adler_About_Taygedo.ogg/revision/latest","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"ja-Play_Vo_Char_NPC010_hstruck_002","title":"Сильный урон II","description":"Непростая ситуация.","language":"Японский","audioUrl":"/nte-meta/game-audio/6a81dfd188333deabb55.ogg"},{"id":"ja-Play_Vo_Char_NPC010_windfall_001","title":"Неожиданная добыча I","description":"Стоит добавить в коллекцию.","language":"Японский","audioUrl":"/nte-meta/game-audio/e0ad3aa446ec4e0ab0e8.ogg"},{"id":"en-Play_Vo_Char_NPC010_chat_002","title":"Чат: списки","description":"Выпивка, конфеты, манга, игровые картриджи, антикоррозийное масло… да, это все.","language":"Английский","audioUrl":"/nte-meta/game-audio/e1926235014ce7b85443.ogg"},{"id":"en-Play_Vo_Char_NPC010_skill_001","title":"Навык перенаправления I","description":"Озари.","language":"Английский","audioUrl":"/nte-meta/game-audio/1b3764d86386acf8c6b3.ogg"},{"id":"en-Play_Vo_Char_NPC010_SSC_003","title":"Особое переключение — Сакири","description":"Сакири, осторожнее.","language":"Английский","audioUrl":"/nte-meta/game-audio/9a66d14749fb89b33a9c.ogg"},{"id":"ja-Play_Vo_Char_NPC010_DodgeCombo_002","title":"Серия критических уклонений II","description":"Терпение важнее спешки.","language":"Японский","audioUrl":"/nte-meta/game-audio/78eeb69fd9d1069ac22d.ogg"},{"id":"ja-Play_Vo_Char_NPC010_greet_002","title":"Дневное приветствие","description":"Что хочешь поесть? Я собираюсь готовить.","language":"Японский","audioUrl":"/nte-meta/game-audio/e0b06bf8d3e1e789f259.ogg"},{"id":"ja-Play_Vo_Char_NPC010_chat_002","title":"Чат: списки","description":"Выпивка, конфеты, манга, игровые картриджи, антикоррозийное масло… да, это все.","language":"Японский","audioUrl":"/nte-meta/game-audio/55ab8ed36b4184d90fff.ogg"},{"id":"ja-Play_Vo_Char_NPC010_weather_004","title":"Жарко","description":"Не следует слишком сильно охлаждаться в жару… может заболеть живот, что очень неприятно.","language":"Японский","audioUrl":"/nte-meta/game-audio/18b3b06bfcb6447ebe4c.ogg"},{"id":"en-Play_Vo_Char_NPC010_TeammateDown_001","title":"Поражен товарищ по команде – Хотори","description":"Госпожа! Это моя вина…","language":"Английский","audioUrl":"/nte-meta/game-audio/d511b2554afe00aa19fb.ogg"},{"id":"en-Play_Vo_Char_NPC010_chat_001","title":"Чат: бизнес","description":"Доход в этом месяце… выглядит не слишком многообещающим.","language":"Английский","audioUrl":"/nte-meta/game-audio/b72c6e7f7e28ca042054.ogg"},{"id":"en-Play_Vo_Char_NPC010_hp_003","title":"Низкий уровень здоровья III","description":"Пожалуйста, держись за моей спиной.","language":"Английский","audioUrl":"/nte-meta/game-audio/ac55b7e9e813e42749f0.ogg"},{"id":"en-Play_Vo_Char_NPC010_Switch_001","title":"Переключение I","description":"Отдохни немного.","language":"Английский","audioUrl":"/nte-meta/game-audio/12827c080e1a958acef5.ogg"},{"id":"ja-Play_Vo_Char_NPC010_self_002","title":"Обо мне: способности эспера","description":"Мне трудно сохранять нейтралитет по отношению к способностям эспера или аномалиям, ведь у меня, несомненно, есть к ним особый интерес… Большинство людей недоумевают, когда впервые встречают меня. Им непонятно, как слепой человек может воспринимать мир вокруг с такой ясностью. Когда-то я был обычным незрячим и во многом зависел от других. Озарение даровало мне способность ощущать мир, а вместе с ней и обязательство быть защитником.","language":"Японский","audioUrl":"/nte-meta/game-audio/7c1fbdeaaeb63293875c.ogg"},{"id":"ja-Play_Vo_Char_NPC010_weather_001","title":"Солнечно","description":"Отличная погода для прогулки. Приготовлю бенто-боксы для Наналли и остальных.","language":"Японский","audioUrl":"/nte-meta/game-audio/596aa31724f047a85c4f.ogg"},{"id":"en-Play_Vo_Char_NPC010_TeammateDown_005","title":"Поражен товарищ по команде – Даффодил","description":"Даффодил, спасибо за усердную работу.","language":"Английский","audioUrl":"/nte-meta/game-audio/327260b58395a2474dab.ogg"},{"id":"en-Play_Vo_Char_NPC010_weather_002","title":"Дождливо","description":"Кажется, прогнозы погоды не всегда надежны. Давай найдем, где переждать дождь.","language":"Английский","audioUrl":"/nte-meta/game-audio/011353fcfe64c7c213c7.ogg"},{"id":"ja-Play_Vo_Char_NPC010_deploy_001","title":"Отправка II","description":"Чем я могу вам помочь?","language":"Японский","audioUrl":"/nte-meta/game-audio/2ee31f7a0bf5a5fc5d06.ogg"},{"id":"ja-Play_Vo_Char_NPC010_gift_002","title":"Подарок получен II","description":"Это напомнило мне кое о чём из прошлого… Подарок мне очень понравился. Спасибо.","language":"Японский","audioUrl":"/nte-meta/game-audio/f3db86e2bd4267811ede.ogg"},{"id":"ja-Play_Vo_Char_NPC010_QTE_002","title":"Атака на входе II","description":"Закончим с этим побыстрее.","language":"Японский","audioUrl":"/nte-meta/game-audio/b7965c4ff0f22a2399ad.ogg"},{"id":"en-Play_Vo_Char_NPC010_TeammateDown_003","title":"Поражен товарищ по команде – Сакири","description":"Даже Кирумару нужно время, чтобы все переварить.","language":"Английский","audioUrl":"/nte-meta/game-audio/a04c758a2a9f8adab93f.ogg"},{"id":"ja-Play_Vo_Char_NPC010_ug_001","title":"Вознесение персонажа I","description":"Учение не знает границ.","language":"Японский","audioUrl":"/nte-meta/game-audio/cf9865603119277034e5.ogg"},{"id":"en-Play_Vo_Char_NPC010_fh_001","title":"Исцеление I","description":"Теперь мне лучше.","language":"Английский","audioUrl":"/nte-meta/game-audio/0a464cd554b7dab82ef6.ogg"},{"id":"voice-1qe3zmo","title":"Дневное приветствие","description":"Прямая запись английской озвучки. Расшифровку и соответствие реплики проверьте в источнике перед публикацией.","language":"Английский","audioUrl":"https://static.wikia.nocookie.net/neverness-to-everness/images/3/38/VO_Adler_Noon_Greeting.ogg/revision/latest","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"ja-Play_Vo_Char_NPC010_chat_003","title":"Чат: Сунья","description":"Спасибо всем за помощь сегодня.","language":"Японский","audioUrl":"/nte-meta/game-audio/a6a7dc2de305dbfd52fd.ogg"},{"id":"ja-Play_Vo_Char_NPC010_Fly_002","title":"Планирование II","description":"Очень удобный способ путешествовать.","language":"Японский","audioUrl":"/nte-meta/game-audio/d50edfd46b1de2947ebc.ogg"},{"id":"ja-Play_Vo_Char_NPC010_struck_002","title":"Урон II","description":"Осторожнее.","language":"Японский","audioUrl":"/nte-meta/game-audio/47b4934524f3240a1042.ogg"},{"id":"en-Play_Vo_Char_NPC010_containment_001","title":"Сдерживание I","description":"Я позабочусь об уборке.","language":"Английский","audioUrl":"/nte-meta/game-audio/c83645b5b14d2241460b.ogg"},{"id":"en-Play_Vo_Char_NPC010_SSC_002","title":"Особое переключение — Наналли","description":"Молодец, Наналли.","language":"Английский","audioUrl":"/nte-meta/game-audio/7e0abf8dcdd8fd39878f.ogg"},{"id":"ja-Play_Vo_Char_NPC010_about_007","title":"Об антикварном магазине Эйбон","description":"«Эйбон» не всегда был таким оживленным. Когда мы только поселились на улице Ханкаку, всё было довольно уныло. Сакири почти не разговаривала, а госпожа и Даффодил решали проблемы с утра до ночи. Ситуация изменилась, когда мы нашли Тайгедо, и ещё больше — с появлением Наналли и Эдгара. Магазин наполнился теплом и смехом. Теперь, когда ты с нами, «Эйбон» стал для нас настоящим домом.","language":"Японский","audioUrl":"/nte-meta/game-audio/33f8bb4493201a3c26cd.ogg"},{"id":"ja-Play_Vo_Char_NPC010_skill_002","title":"Навык перенаправления II","description":"Рассей.","language":"Японский","audioUrl":"/nte-meta/game-audio/4ce8a2a473fa737169c8.ogg"},{"id":"ja-Play_Vo_Char_NPC010_ug_002","title":"Вознесение персонажа II","description":"Никогда не перестану совершенствоваться.","language":"Японский","audioUrl":"/nte-meta/game-audio/33e3a21830b74eac569e.ogg"},{"id":"ja-Play_Vo_Char_NPC010_hp_002","title":"Низкий уровень здоровья II","description":"Не волнуйся, я в порядке.","language":"Японский","audioUrl":"/nte-meta/game-audio/f6cd108a5f5cb4589711.ogg"},{"id":"ja-Play_Vo_Char_NPC010_windfall_006","title":"Неожиданная добыча VI","description":"Хорошее качество. Это мы оставим себе.","language":"Японский","audioUrl":"/nte-meta/game-audio/a3ad96a4fa4654495f42.ogg"},{"id":"ja-Play_Vo_Char_NPC010_TeammateDown_001","title":"Поражен товарищ по команде – Хотори","description":"Госпожа! Это моя вина…","language":"Японский","audioUrl":"/nte-meta/game-audio/de46192ad7fbc79d454e.ogg"},{"id":"en-Play_Vo_Char_NPC010_windfall_006","title":"Неожиданная добыча VI","description":"Хорошее качество. Это мы оставим себе.","language":"Английский","audioUrl":"/nte-meta/game-audio/8b8bf36347bd66bed751.ogg"},{"id":"ja-Play_Vo_Char_NPC010_hstruck_001","title":"Сильный урон I","description":"Это может обернуться неприятностями.","language":"Японский","audioUrl":"/nte-meta/game-audio/3ad7bbe9c638035a3a3e.ogg"},{"id":"en-Play_Vo_Char_NPC010_gift_002","title":"Подарок получен II","description":"Это напомнило мне кое о чём из прошлого… Подарок мне очень понравился. Спасибо.","language":"Английский","audioUrl":"/nte-meta/game-audio/1c24b852c602e9752769.ogg"},{"id":"ja-Play_Vo_Char_NPC010_TeammateDown_004","title":"Поражен товарищ по команде – Эдгар","description":"Ты хорошо поработал, Эдгар.","language":"Японский","audioUrl":"/nte-meta/game-audio/8043554cb529a4656eb1.ogg"},{"id":"voice-q1mnrf","title":"О Даффодил","description":"Прямая запись английской озвучки. Расшифровку и соответствие реплики проверьте в источнике перед публикацией.","language":"Английский","audioUrl":"https://static.wikia.nocookie.net/neverness-to-everness/images/6/61/VO_Adler_About_Daffodill.ogg/revision/latest","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"ja-Play_Vo_Char_NPC010_fh_002","title":"Исцеление II","description":"Все хорошо.","language":"Японский","audioUrl":"/nte-meta/game-audio/e27c675160aa8fe90405.ogg"},{"id":"ja-Play_Vo_Char_NPC010_vexation_001","title":"Проблемы","description":"Проблемы? Магазин работает в убыток, госпожа купила очередную подделку под антиквариат, а махинации Наналли приводят к нам на порог разъяренных соседей. От всего этого у меня голова болит, но больше всего меня беспокоит то, как все пренебрегают своим благополучием. Как дворецкий «Эйбона» я уделяю особое внимание таким вопросам.","language":"Японский","audioUrl":"/nte-meta/game-audio/64d6a4fa92969eede129.ogg"},{"id":"ja-Play_Vo_Char_NPC010_SSC_002","title":"Особое переключение — Наналли","description":"Молодец, Наналли.","language":"Японский","audioUrl":"/nte-meta/game-audio/1595575d049412a3e9b9.ogg"},{"id":"en-Play_Vo_Char_NPC010_aoe_UI_001","title":"Сверхспособность I","description":"Все, что имеет форму, нереально.","language":"Английский","audioUrl":"/nte-meta/game-audio/70db728fcbf9002c3ee7.ogg"},{"id":"en-Play_Vo_Char_NPC010_QTE_002","title":"Атака на входе II","description":"Закончим с этим побыстрее.","language":"Английский","audioUrl":"/nte-meta/game-audio/23bd84195d1f9ed7197a.ogg"},{"id":"en-Play_Vo_Char_NPC010_weather_001","title":"Солнечно","description":"Отличная погода для прогулки. Приготовлю бенто-боксы для Наналли и остальных.","language":"Английский","audioUrl":"/nte-meta/game-audio/d09e193bcd21f17e6324.ogg"},{"id":"ja-Play_Vo_Char_NPC010_aoe_UI_002","title":"Сверхспособность II","description":"Безликое, бесформенное.","language":"Японский","audioUrl":"/nte-meta/game-audio/f214b2785a2c33142092.ogg"},{"id":"ja-Play_Vo_Char_NPC010_aoe_UI_003","title":"Сверхспособность III","description":"Желаю тебе обрести вечный покой.","language":"Японский","audioUrl":"/nte-meta/game-audio/ed83b51774c141737c88.ogg"},{"id":"ja-Play_Vo_Char_NPC010_SSC_003","title":"Особое переключение — Сакири","description":"Сакири, осторожнее.","language":"Японский","audioUrl":"/nte-meta/game-audio/ea5af4a950ec6112e595.ogg"},{"id":"en-Play_Vo_Char_NPC010_TeammateDown_004","title":"Поражен товарищ по команде – Эдгар","description":"Ты хорошо поработал, Эдгар.","language":"Английский","audioUrl":"/nte-meta/game-audio/694e56739daf2508b711.ogg"},{"id":"en-Play_Vo_Char_NPC010_QTE_003","title":"Атака на входе III","description":"Все это лишь иллюзия.","language":"Английский","audioUrl":"/nte-meta/game-audio/a5b083757340fcd25b0b.ogg"},{"id":"ja-Play_Vo_Char_NPC010_dead_001","title":"Потеря сознания I","description":"Мы можем пойти… дальше…","language":"Японский","audioUrl":"/nte-meta/game-audio/e03d32b0f6241437626a.ogg"},{"id":"ja-Play_Vo_Char_NPC010_greet_004","title":"Спокойной ночи","description":"Для поддержания хорошего здоровья необходимо высыпаться… Конечно, если ты захочешь ещё поболтать, я всегда к твоим услугам.","language":"Японский","audioUrl":"/nte-meta/game-audio/9dcdc80e791f068c62eb.ogg"},{"id":"ja-Play_Vo_Char_NPC010_hp_001","title":"Низкий уровень здоровья I","description":"Это неожиданно.","language":"Японский","audioUrl":"/nte-meta/game-audio/da987ef5dd0004a8e39e.ogg"},{"id":"en-Play_Vo_Char_NPC010_anomaly_003","title":"Нуллификация I","description":"Нужно что-нибудь, чтобы восстановить силы?","language":"Английский","audioUrl":"/nte-meta/game-audio/13725740cb659cee9141.ogg"},{"id":"voice-9ro03m","title":"Первая встреча","description":"Прямая запись английской озвучки. Расшифровку и соответствие реплики проверьте в источнике перед публикацией.","language":"Английский","audioUrl":"https://static.wikia.nocookie.net/neverness-to-everness/images/c/cd/VO_Adler_First_Meet.ogg/revision/latest","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"en-Play_Vo_Char_NPC010_self_001","title":"Обо мне: броня","description":"Это броня Озарение. Она не моя; мне просто повезло ею пользоваться. В ней обитает Сунья, облегчая домашние дела.","language":"Английский","audioUrl":"/nte-meta/game-audio/96f5646a994673eb4f89.ogg"},{"id":"ja-Play_Vo_Char_NPC010_SSC_005","title":"Особое переключение — Даффодил","description":"Смена меняется. Хорошая работа.","language":"Японский","audioUrl":"/nte-meta/game-audio/688f77d8e33d5b79ba3a.ogg"},{"id":"voice-yka0tx","title":"О Наналли","description":"Прямая запись английской озвучки. Расшифровку и соответствие реплики проверьте в источнике перед публикацией.","language":"Английский","audioUrl":"https://static.wikia.nocookie.net/neverness-to-everness/images/a/af/VO_Adler_About_Nanally.ogg/revision/latest","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"en-Play_Vo_Char_NPC010_dead_003","title":"Потеря сознания III","description":"Прости, что разочаровал.","language":"Английский","audioUrl":"/nte-meta/game-audio/58a6d7bfe41202923783.ogg"},{"id":"en-Play_Vo_Char_NPC010_hstruck_001","title":"Сильный урон I","description":"Это может обернуться неприятностями.","language":"Английский","audioUrl":"/nte-meta/game-audio/9ccc2beb6f119f41d025.ogg"},{"id":"ja-Play_Vo_Char_NPC010_fh_001","title":"Исцеление I","description":"Теперь мне лучше.","language":"Японский","audioUrl":"/nte-meta/game-audio/e9677c506f7bbfb0c7f4.ogg"},{"id":"en-Play_Vo_Char_NPC010_anomaly_004","title":"Нуллификация II","description":"Иди, отдохни. С остальным я сам разберусь.","language":"Английский","audioUrl":"/nte-meta/game-audio/963b1b4d42c1cbc22a18.ogg"},{"id":"en-Play_Vo_Char_NPC010_Fly_001","title":"Планирование I","description":"Ветер набирает силу?","language":"Английский","audioUrl":"/nte-meta/game-audio/f487ceae9e55387f89ac.ogg"},{"id":"ja-Play_Vo_Char_NPC010_windfall_003","title":"Неожиданная добыча III","description":"Незнакомый предмет коллекции… нужно взять его с собой для подробного изучения.","language":"Японский","audioUrl":"/nte-meta/game-audio/9aa825c7b5dc592b450f.ogg"},{"id":"ja-Play_Vo_Char_NPC010_containment_001","title":"Сдерживание I","description":"Я позабочусь об уборке.","language":"Японский","audioUrl":"/nte-meta/game-audio/ab39df3f301473a14dc6.ogg"},{"id":"ja-Play_Vo_Char_NPC010_self_004","title":"Обо мне: стремление к идеалу","description":"Мастер на все руки… Слишком громкое слово. Я всего лишь немного старше и видел чуть больше людей и событий. Когда я был в возрасте Наналли и остальных, по энергии и смелости я им и в подмётки не годился.","language":"Японский","audioUrl":"/nte-meta/game-audio/0f85112de1f627e3cb29.ogg"},{"id":"voice-7kbebi","title":"Утреннее приветствие","description":"Прямая запись английской озвучки. Расшифровку и соответствие реплики проверьте в источнике перед публикацией.","language":"Английский","audioUrl":"https://static.wikia.nocookie.net/neverness-to-everness/images/0/08/VO_Adler_Morning_Greeting.ogg/revision/latest","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"ja-Play_Vo_Char_NPC010_anomaly_004","title":"Нуллификация II","description":"Иди, отдохни. С остальным я сам разберусь.","language":"Японский","audioUrl":"/nte-meta/game-audio/8ea76123b6c9ec09ff05.ogg"},{"id":"ja-Play_Vo_Char_NPC010_greet_003","title":"Вечернее приветствие","description":"Эй, расслабься. Сейчас свободное время, клиенты, как правило, не приходят в эти часы.","language":"Японский","audioUrl":"/nte-meta/game-audio/e003dfc41803497d9db5.ogg"},{"id":"ja-Play_Vo_Char_NPC010_QTE_001","title":"Атака на входе I","description":"Продолжительные бои бесцельны.","language":"Японский","audioUrl":"/nte-meta/game-audio/4f3793b367ae1c92c761.ogg"},{"id":"ja-Play_Vo_Char_NPC010_Switch_001","title":"Переключение I","description":"Отдохни немного.","language":"Японский","audioUrl":"/nte-meta/game-audio/a4ba51f1eb7adc44513e.ogg"},{"id":"ja-Play_Vo_Char_NPC010_Switch_003","title":"Переключение III","description":"Я тебя не подведу!","language":"Японский","audioUrl":"/nte-meta/game-audio/2d1094ee7f4084299e9d.ogg"},{"id":"ja-Play_Vo_Char_NPC010_weather_003","title":"Холодно","description":"Должен напомнить всем, что нужно одеваться теплее. На всякий случай приготовлю лекарство от простуды.","language":"Японский","audioUrl":"/nte-meta/game-audio/19bb2791886a54b18060.ogg"},{"id":"en-Play_Vo_Char_NPC010_self_003","title":"Обо мне: очки","description":"Эти очки? Наналли купила их мне с первой зарплаты от поручений после того, как присоединилась к команде «Эйбона». Сияя от восторга, она заявила: «Вот как одеваются благородные бандиты в кино!» Она так радовалась, что я не мог не принять этот уникальный жест. Что касается её пары… она подобрала их, чтобы воплотить стиль… «босса Ити-дайме»? Такие подарки вполне в духе Наналли.","language":"Английский","audioUrl":"/nte-meta/game-audio/c33d354dcecfce35e608.ogg"},{"id":"en-Play_Vo_Char_NPC010_Switch_003","title":"Переключение III","description":"Я тебя не подведу!","language":"Английский","audioUrl":"/nte-meta/game-audio/2c6f7baf84a2e5c94f38.ogg"},{"id":"ja-Play_Vo_Char_NPC010_TeammateDown_002","title":"Поражен товарищ по команде – Наналли","description":"Наналли, не нагружай себя так!","language":"Японский","audioUrl":"/nte-meta/game-audio/54708abfc1873a83d053.ogg"},{"id":"en-Play_Vo_Char_NPC010_hstruck_002","title":"Сильный урон II","description":"Непростая ситуация.","language":"Английский","audioUrl":"/nte-meta/game-audio/c856c81c0bf7fed7b62a.ogg"},{"id":"en-Play_Vo_Char_NPC010_ug_003","title":"Вознесение персонажа III","description":"Памятный момент.","language":"Английский","audioUrl":"/nte-meta/game-audio/6717336720f06673b68b.ogg"},{"id":"ja-Play_Vo_Char_NPC010_dead_002","title":"Потеря сознания II","description":"Пожалуйста… позаботься о них…","language":"Японский","audioUrl":"/nte-meta/game-audio/3aba353ff6de4ad6cbdd.ogg"},{"id":"en-Play_Vo_Char_NPC010_Fly_002","title":"Планирование II","description":"Очень удобный способ путешествовать.","language":"Английский","audioUrl":"/nte-meta/game-audio/9009d129d5f8a83a85cc.ogg"},{"id":"en-Play_Vo_Char_NPC010_aoe_UI_002","title":"Сверхспособность II","description":"Безликое, бесформенное.","language":"Английский","audioUrl":"/nte-meta/game-audio/153b8b4415919aea74de.ogg"},{"id":"en-Play_Vo_Char_NPC010_windfall_001","title":"Неожиданная добыча I","description":"Стоит добавить в коллекцию.","language":"Английский","audioUrl":"/nte-meta/game-audio/60e0b1e262e92ab9db6b.ogg"},{"id":"ja-Play_Vo_Char_NPC010_about_002","title":"О Наналли","description":"Наналли — обычный ребенок. Благодаря ей в «Эйбоне» стало гораздо веселее. Конечно, когда что-то случается, хотелось бы, чтобы она была более… Но я не жалуюсь на шум. В этом возрасте детям нужно играть.","language":"Японский","audioUrl":"/nte-meta/game-audio/4824da27ba4fde41f2cd.ogg"},{"id":"ja-Play_Vo_Char_NPC010_self_001","title":"Обо мне: броня","description":"Это броня Озарение. Она не моя; мне просто повезло ею пользоваться. В ней обитает Сунья, облегчая домашние дела.","language":"Японский","audioUrl":"/nte-meta/game-audio/f1c5c4909794bdf5574e.ogg"},{"id":"en-Play_Vo_Char_NPC010_struck_002","title":"Урон II","description":"Осторожнее.","language":"Английский","audioUrl":"/nte-meta/game-audio/ab793a0ddaddf5249653.ogg"},{"id":"ja-Play_Vo_Char_NPC010_about_001","title":"О Хотори","description":"У госпожи столько забот… Стыдно признаться, но я могу помочь ей только с повседневными делами, хотя для меня честь взять на себя даже малую часть её ответственности.","language":"Японский","audioUrl":"/nte-meta/game-audio/c112e6ec500d45be11ad.ogg"},{"id":"ja-Play_Vo_Char_NPC010_containment_002","title":"Сдерживание II","description":"Спасибо за старания.","language":"Японский","audioUrl":"/nte-meta/game-audio/d04d5c1257a61e76a1f1.ogg"},{"id":"en-Play_Vo_Char_NPC010_chat_003","title":"Чат: Сунья","description":"Спасибо всем за помощь сегодня.","language":"Английский","audioUrl":"/nte-meta/game-audio/035099ac497610b30e94.ogg"},{"id":"en-Play_Vo_Char_NPC010_dead_002","title":"Потеря сознания II","description":"Пожалуйста… позаботься о них…","language":"Английский","audioUrl":"/nte-meta/game-audio/f607e1acf1b8cb973e64.ogg"},{"id":"ja-Play_Vo_Char_NPC010_gift_004","title":"Подарок получен IV","description":"Я буду дорожить этим подарком и тем, сколько сил вы в него вложили.","language":"Японский","audioUrl":"/nte-meta/game-audio/4301f51bad79f233f0fc.ogg"},{"id":"ja-Play_Vo_Char_NPC010_SSC_004","title":"Особое переключение — Эдгар","description":"Мне обслужить твои компьютерные детали?","language":"Японский","audioUrl":"/nte-meta/game-audio/74816839597734ce9d4a.ogg"},{"id":"ja-Play_Vo_Char_NPC010_ug_003","title":"Вознесение персонажа III","description":"Памятный момент.","language":"Японский","audioUrl":"/nte-meta/game-audio/adb6025bb505f341c40b.ogg"},{"id":"en-Play_Vo_Char_NPC010_gift_001","title":"Подарок получен I","description":"Какой прекрасный подарок. Спасибо, оценщик.Какой прекрасный подарок. Спасибо, оценщица.","language":"Английский","audioUrl":"/nte-meta/game-audio/4939b25039309475463d.ogg"},{"id":"ja-Play_Vo_Char_NPC010_Fly_001","title":"Планирование I","description":"Ветер набирает силу?","language":"Японский","audioUrl":"/nte-meta/game-audio/a7770d3e5d13d7cd2f1e.ogg"},{"id":"ja-Play_Vo_Char_NPC010_talk_003","title":"Тема: советы","description":"Секрет быстрой работы? Для повседневных задач я просто заранее готовлю списки и следую плану. Разумеется, иногда случаются неожиданности… в таком случае пригодятся терпение и немного удачи… Думаю, с опытом начинаешь замечать закономерности в том, как справляться с делами.","language":"Японский","audioUrl":"/nte-meta/game-audio/88333b6d577e87250de3.ogg"},{"id":"en-Play_Vo_Char_NPC010_gift_003","title":"Подарок получен III","description":"Оценщик, я всегда знал, что у вас превосходный вкус.Оценщица, я всегда знал, что у вас превосходный вкус.","language":"Английский","audioUrl":"/nte-meta/game-audio/4ad7a4019a2169a6292e.ogg"},{"id":"en-Play_Vo_Char_NPC010_kill_002","title":"Убийство II","description":"Я ещё не потерял хватку.","language":"Английский","audioUrl":"/nte-meta/game-audio/b190c53edb28850ebe39.ogg"},{"id":"en-Play_Vo_Char_NPC010_self_002","title":"Обо мне: способности эспера","description":"Мне трудно сохранять нейтралитет по отношению к способностям эспера или аномалиям, ведь у меня, несомненно, есть к ним особый интерес… Большинство людей недоумевают, когда впервые встречают меня. Им непонятно, как слепой человек может воспринимать мир вокруг с такой ясностью. Когда-то я был обычным незрячим и во многом зависел от других. Озарение даровало мне способность ощущать мир, а вместе с ней и обязательство быть защитником.","language":"Английский","audioUrl":"/nte-meta/game-audio/66a0870d9d1a238e5f42.ogg"},{"id":"en-Play_Vo_Char_NPC010_SSC_001","title":"Особое переключение — Хотори","description":"Я с этим разберусь, госпожа.","language":"Английский","audioUrl":"/nte-meta/game-audio/d6a0959bf0f7cc3232fc.ogg"},{"id":"ja-Play_Vo_Char_NPC010_gift_001","title":"Подарок получен I","description":"Какой прекрасный подарок. Спасибо, оценщик.Какой прекрасный подарок. Спасибо, оценщица.","language":"Японский","audioUrl":"/nte-meta/game-audio/dd49002f04175181a593.ogg"},{"id":"en-Play_Vo_Char_NPC010_deploy_001","title":"Отправка II","description":"Чем я могу вам помочь?","language":"Английский","audioUrl":"/nte-meta/game-audio/a78fcfc4c46f2b61783f.ogg"},{"id":"ja-Play_Vo_Char_NPC010_struck_001","title":"Урон I","description":"Моя ошибка.","language":"Японский","audioUrl":"/nte-meta/game-audio/c0e132bde820a333f38c.ogg"},{"id":"ja-Play_Vo_Char_NPC010_talk_001","title":"Тема: аномалии","description":"Большинство Странностей на самом деле довольно дружелюбны… просто они не умеют выражать свои мысли и чувства, а может быть способы их выражения отличаются от привычных нам. Если будет возможность, попробуй пообщаться с ними. Возможно, перед тобой откроется абсолютно новый мир.","language":"Японский","audioUrl":"/nte-meta/game-audio/c0b0d225e132af75b9ee.ogg"},{"id":"ja-Play_Vo_Char_NPC010_TeammateDown_006","title":"Поражен товарищ по команде – Ноль","description":"Ты отлично держался, оценщик. Остальное беру на себя.Ты отлично держалась, оценщица. Остальное беру на себя.","language":"Японский","audioUrl":"/nte-meta/game-audio/1195adb1316e40709d7c.ogg"},{"id":"en-Play_Vo_Char_NPC010_SSC_005","title":"Особое переключение — Даффодил","description":"Смена меняется. Хорошая работа.","language":"Английский","audioUrl":"/nte-meta/game-audio/3cd72d072f5cfdf727b5.ogg"},{"id":"ja-Play_Vo_Char_NPC010_TeammateDown_003","title":"Поражен товарищ по команде – Сакири","description":"Даже Кирумару нужно время, чтобы все переварить.","language":"Японский","audioUrl":"/nte-meta/game-audio/ed67a90495588bf5d332.ogg"},{"id":"en-Play_Vo_Char_NPC010_dead_001","title":"Потеря сознания I","description":"Мы можем пойти… дальше…","language":"Английский","audioUrl":"/nte-meta/game-audio/8e2652e46ca05fa187e3.ogg"},{"id":"ja-Play_Vo_Char_NPC010_kill_002","title":"Убийство II","description":"Я ещё не потерял хватку.","language":"Японский","audioUrl":"/nte-meta/game-audio/cc49d02153b8bb0cffbd.ogg"},{"id":"en-Play_Vo_Char_NPC010_aoe_UI_003","title":"Сверхспособность III","description":"Желаю тебе обрести вечный покой.","language":"Английский","audioUrl":"/nte-meta/game-audio/bdd2366dfdea86196e04.ogg"},{"id":"en-Play_Vo_Char_NPC010_containment_002","title":"Сдерживание II","description":"Спасибо за старания.","language":"Английский","audioUrl":"/nte-meta/game-audio/3f47c10798c22a82cd5c.ogg"},{"id":"en-Play_Vo_Char_NPC010_skill_002","title":"Навык перенаправления II","description":"Рассей.","language":"Английский","audioUrl":"/nte-meta/game-audio/f9802b18f883cb9fd87a.ogg"},{"id":"voice-lcezki","title":"Тема: аномалии","description":"Прямая запись английской озвучки. Расшифровку и соответствие реплики проверьте в источнике перед публикацией.","language":"Английский","audioUrl":"https://static.wikia.nocookie.net/neverness-to-everness/images/e/ea/VO_Adler_Topic_-_Anomalies.ogg/revision/latest","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"en-Play_Vo_Char_NPC010_weather_003","title":"Холодно","description":"Должен напомнить всем, что нужно одеваться теплее. На всякий случай приготовлю лекарство от простуды.","language":"Английский","audioUrl":"/nte-meta/game-audio/0f209c9d7bc04d3692ee.ogg"},{"id":"ja-Play_Vo_Char_NPC010_hobby_001","title":"Хобби","description":"Кулинария требует дисциплины… от выбора ингредиентов до получения отзыва, каждое блюдо — уникальное путешествие. Мне нравится готовить для всех в «Эйбоне», хотя лучше бы Сакири не была такой привередой.","language":"Японский","audioUrl":"/nte-meta/game-audio/4a29fc19a9a028c0f60a.ogg"},{"id":"en-Play_Vo_Char_NPC010_self_004","title":"Обо мне: стремление к идеалу","description":"Мастер на все руки… Слишком громкое слово. Я всего лишь немного старше и видел чуть больше людей и событий. Когда я был в возрасте Наналли и остальных, по энергии и смелости я им и в подмётки не годился.","language":"Английский","audioUrl":"/nte-meta/game-audio/708da5db72c96d992079.ogg"},{"id":"en-Play_Vo_Char_NPC010_SSC_004","title":"Особое переключение — Эдгар","description":"Мне обслужить твои компьютерные детали?","language":"Английский","audioUrl":"/nte-meta/game-audio/1c22c058f3e834fc827b.ogg"},{"id":"ja-Play_Vo_Char_NPC010_about_005","title":"О Даффодил","description":"Даффодил демонстрирует непоколебимую преданность госпоже, лично решая все её проблемы — на неё действительно можно положиться. С её поддержкой я могу сконцентрироваться на выполнении других задач… Хотя иногда мне хотелось бы, чтобы она заботилась и о себе.","language":"Японский","audioUrl":"/nte-meta/game-audio/8b28cd37bb354c700823.ogg"},{"id":"ja-Play_Vo_Char_NPC010_aoe_UI_001","title":"Сверхспособность I","description":"Все, что имеет форму, нереально.","language":"Японский","audioUrl":"/nte-meta/game-audio/54fa063cf3857bfb2c9b.ogg"},{"id":"ja-Play_Vo_Char_NPC010_SSC_001","title":"Особое переключение — Хотори","description":"Я с этим разберусь, госпожа.","language":"Японский","audioUrl":"/nte-meta/game-audio/f63ed1c3a1c4ebc177be.ogg"},{"id":"en-Play_Vo_Char_NPC010_weather_004","title":"Жарко","description":"Не следует слишком сильно охлаждаться в жару… может заболеть живот, что очень неприятно.","language":"Английский","audioUrl":"/nte-meta/game-audio/372eb9472b8cae469282.ogg"},{"id":"ja-Play_Vo_Char_NPC010_about_004","title":"Об Эдгаре","description":"Необщительность — необязательно плохо. У каждого свой стиль жизни, и сам Эдгар не страдает от сложностей в общении с другими людьми, что не может не радовать. К тому же, рядом с ним всегда Сакири и Наналли, которые понимают его лучше всего и всегда готовы его выслушать.","language":"Японский","audioUrl":"/nte-meta/game-audio/981f2e26dc94548a2175.ogg"},{"id":"en-Play_Vo_Char_NPC010_hp_002","title":"Низкий уровень здоровья II","description":"Не волнуйся, я в порядке.","language":"Английский","audioUrl":"/nte-meta/game-audio/61fc08099db3c866f0ba.ogg"},{"id":"voice-5ocvbl","title":"Тема: этикет","description":"Прямая запись английской озвучки. Расшифровку и соответствие реплики проверьте в источнике перед публикацией.","language":"Английский","audioUrl":"https://static.wikia.nocookie.net/neverness-to-everness/images/e/e5/VO_Adler_Topic_-_Etiquette.ogg/revision/latest","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"en-Play_Vo_Char_NPC010_windfall_002","title":"Неожиданная добыча II","description":"Какой приятный сюрприз… кажется, сегодня будет отличный день.","language":"Английский","audioUrl":"/nte-meta/game-audio/770270b9629faed54291.ogg"},{"id":"ja-Play_Vo_Char_NPC010_about_006","title":"О Тайгедо","description":"Я благодарен Тайгедо за постоянную помощь в магазине, особенно за его любопытные маленькие изобретения. И хотя Сакири, Наналли и даже госпожа шутят о том, чтобы продать его для погашения долгов, они все время спрашивают о нем, стоит ему отлучиться.","language":"Японский","audioUrl":"/nte-meta/game-audio/cb58291fed15bc72a599.ogg"},{"id":"ja-Play_Vo_Char_NPC010_DodgeCombo_001","title":"Серия критических уклонений I","description":"Я кое-чему научился.","language":"Японский","audioUrl":"/nte-meta/game-audio/dc2b1208dd252fbb3c3a.ogg"},{"id":"en-Play_Vo_Char_NPC010_talk_003","title":"Тема: советы","description":"Секрет быстрой работы? Для повседневных задач я просто заранее готовлю списки и следую плану. Разумеется, иногда случаются неожиданности… в таком случае пригодятся терпение и немного удачи… Думаю, с опытом начинаешь замечать закономерности в том, как справляться с делами.","language":"Английский","audioUrl":"/nte-meta/game-audio/510a56883a5f137053fb.ogg"},{"id":"ja-Play_Vo_Char_NPC010_chat_001","title":"Чат: бизнес","description":"Доход в этом месяце… выглядит не слишком многообещающим.","language":"Японский","audioUrl":"/nte-meta/game-audio/cf9b60ca1d55ff44d97a.ogg"},{"id":"ja-Play_Vo_Char_NPC010_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Я защищу тебя.","language":"Японский","audioUrl":"/nte-meta/game-audio/4a07585ed642ad05ae71.ogg"},{"id":"ja-Play_Vo_Char_NPC010_windfall_002","title":"Неожиданная добыча II","description":"Какой приятный сюрприз… кажется, сегодня будет отличный день.","language":"Японский","audioUrl":"/nte-meta/game-audio/f57e7dc3eac8c461851b.ogg"},{"id":"en-Play_Vo_Char_NPC010_windfall_003","title":"Неожиданная добыча III","description":"Незнакомый предмет коллекции… нужно взять его с собой для подробного изучения.","language":"Английский","audioUrl":"/nte-meta/game-audio/ddf87ce49da412355749.ogg"},{"id":"en-Play_Vo_Char_NPC010_QTE_001","title":"Атака на входе I","description":"Продолжительные бои бесцельны.","language":"Английский","audioUrl":"/nte-meta/game-audio/260e6d0f71b0a516cab8.ogg"},{"id":"voice-1mv2h3f","title":"О Хотори","description":"Прямая запись английской озвучки. Расшифровку и соответствие реплики проверьте в источнике перед публикацией.","language":"Английский","audioUrl":"https://static.wikia.nocookie.net/neverness-to-everness/images/7/7b/VO_Adler_About_Hotori.ogg/revision/latest","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"en-Play_Vo_Char_NPC010_vexation_001","title":"Проблемы","description":"Проблемы? Магазин работает в убыток, госпожа купила очередную подделку под антиквариат, а махинации Наналли приводят к нам на порог разъяренных соседей. От всего этого у меня голова болит, но больше всего меня беспокоит то, как все пренебрегают своим благополучием. Как дворецкий «Эйбона» я уделяю особое внимание таким вопросам.","language":"Английский","audioUrl":"/nte-meta/game-audio/9285b56ee3adddc9b8a1.ogg"},{"id":"en-Play_Vo_Char_NPC010_struck_001","title":"Урон I","description":"Моя ошибка.","language":"Английский","audioUrl":"/nte-meta/game-audio/3cbd6ba96e04d48b853b.ogg"},{"id":"ja-Play_Vo_Char_NPC010_Parry_001","title":"Парирование I","description":"Хороший выбор.","language":"Японский","audioUrl":"/nte-meta/game-audio/1ec1dfa45b7847b85975.ogg"},{"id":"ja-Play_Vo_Char_NPC010_self_003","title":"Обо мне: очки","description":"Эти очки? Наналли купила их мне с первой зарплаты от поручений после того, как присоединилась к команде «Эйбона». Сияя от восторга, она заявила: «Вот как одеваются благородные бандиты в кино!» Она так радовалась, что я не мог не принять этот уникальный жест. Что касается её пары… она подобрала их, чтобы воплотить стиль… «босса Ити-дайме»? Такие подарки вполне в духе Наналли.","language":"Японский","audioUrl":"/nte-meta/game-audio/6ed8daef1fa151c500c0.ogg"},{"id":"ja-Play_Vo_Char_NPC010_windfall_004","title":"Неожиданная добыча IV","description":"Похоже, в этом месяце мы получим прибыль.","language":"Японский","audioUrl":"/nte-meta/game-audio/18dcc020c1b343de67a1.ogg"},{"id":"voice-1oli6ym","title":"Спокойной ночи","description":"Прямая запись английской озвучки. Расшифровку и соответствие реплики проверьте в источнике перед публикацией.","language":"Английский","audioUrl":"https://static.wikia.nocookie.net/neverness-to-everness/images/7/78/VO_Adler_Good_Night.ogg/revision/latest","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"en-Play_Vo_Char_NPC010_kill_001","title":"Убийство I","description":"Ты в порядке?","language":"Английский","audioUrl":"/nte-meta/game-audio/d863ba9b2019e0de9898.ogg"},{"id":"ja-Play_Vo_Char_NPC010_greet_001","title":"Утреннее приветствие","description":"Доброе утро. Как прошёл отдых? Завтрак уже готов.","language":"Японский","audioUrl":"/nte-meta/game-audio/92829092c16f1c2cead1.ogg"},{"id":"en-Play_Vo_Char_NPC010_deploy_002","title":"Отправка I","description":"Полезно немного потренироваться.","language":"Английский","audioUrl":"/nte-meta/game-audio/58f9374d18e7292622e3.ogg"},{"id":"en-Play_Vo_Char_NPC010_Parry_002","title":"Парирование II","description":"Все то же мастерство.","language":"Английский","audioUrl":"/nte-meta/game-audio/ad9bf2edc271fa88aab8.ogg"},{"id":"en-Play_Vo_Char_NPC010_ug_002","title":"Вознесение персонажа II","description":"Никогда не перестану совершенствоваться.","language":"Английский","audioUrl":"/nte-meta/game-audio/cc3a329cde57a054b548.ogg"},{"id":"ja-Play_Vo_Char_NPC010_TeammateDown_005","title":"Поражен товарищ по команде – Даффодил","description":"Даффодил, спасибо за усердную работу.","language":"Японский","audioUrl":"/nte-meta/game-audio/15ad0297d713025e60ce.ogg"},{"id":"en-Play_Vo_Char_NPC010_Switch_002","title":"Переключение II","description":"Хорошо, что я не опоздал.","language":"Английский","audioUrl":"/nte-meta/game-audio/eddd2bd3e1fcd7494e12.ogg"},{"id":"ja-Play_Vo_Char_NPC010_hp_003","title":"Низкий уровень здоровья III","description":"Пожалуйста, держись за моей спиной.","language":"Японский","audioUrl":"/nte-meta/game-audio/4245fe33295f62ac3488.ogg"},{"id":"en-Play_Vo_Char_NPC010_gift_004","title":"Подарок получен IV","description":"Я буду дорожить этим подарком и тем, сколько сил вы в него вложили.","language":"Английский","audioUrl":"/nte-meta/game-audio/b4f44419cdb960d9617a.ogg"},{"id":"en-Play_Vo_Char_NPC010_DodgeCombo_002","title":"Серия критических уклонений II","description":"Терпение важнее спешки.","language":"Английский","audioUrl":"/nte-meta/game-audio/b77020c42024628f22c6.ogg"},{"id":"ja-Play_Vo_Char_NPC010_skill_003","title":"Навык перенаправления III","description":"Осмысли.","language":"Японский","audioUrl":"/nte-meta/game-audio/b1293d3dd8bd2e8b9413.ogg"},{"id":"voice-14zv6l0","title":"Об антикварном магазине «Эйбон»","description":"Прямая запись английской озвучки. Расшифровку и соответствие реплики проверьте в источнике перед публикацией.","language":"Английский","audioUrl":"https://static.wikia.nocookie.net/neverness-to-everness/images/1/1b/VO_Adler_About_Eibon_Antique_Shop.ogg/revision/latest","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"voice-15ui49k","title":"Вечернее приветствие","description":"Прямая запись английской озвучки. Расшифровку и соответствие реплики проверьте в источнике перед публикацией.","language":"Английский","audioUrl":"https://static.wikia.nocookie.net/neverness-to-everness/images/1/11/VO_Adler_Evening_Greeting.ogg/revision/latest","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"en-Play_Vo_Char_NPC010_Parry_001","title":"Парирование I","description":"Хороший выбор.","language":"Английский","audioUrl":"/nte-meta/game-audio/bd82f7c7353875aee3c1.ogg"},{"id":"ja-Play_Vo_Char_NPC010_Switch_002","title":"Переключение II","description":"Хорошо, что я не опоздал.","language":"Японский","audioUrl":"/nte-meta/game-audio/fa873140f832a822550a.ogg"},{"id":"en-Play_Vo_Char_NPC010_about_004","title":"Об Эдгаре","description":"Необщительность — необязательно плохо. У каждого свой стиль жизни, и сам Эдгар не страдает от сложностей в общении с другими людьми, что не может не радовать. К тому же, рядом с ним всегда Сакири и Наналли, которые понимают его лучше всего и всегда готовы его выслушать.","language":"Английский","audioUrl":"/nte-meta/game-audio/130e822647dcde0b3248.ogg"},{"id":"en-Play_Vo_Char_NPC010_fh_002","title":"Исцеление I