"},{"id":"reward-10-2","name":"После работы","quantity":"1","iconUrl":"/nte-meta/game-assets/11af55a99e5ea767a58c.webp"}]}]') WHERE character_id='akane' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 16:33:23');

