UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Табулатуры после школы","iconUrl":"/nte-meta/game-assets/2ff731e74fb90e929f38.webp","description":"Увеличивает шанс крит. удара Аканэ Рин на 12 %. Каждый раз при успешной активации «Синхронизированного резонанса» восстанавливает ОЗ в размере 100 % от её показателя базовой атаки."},{"level":2,"kind":"awakening","name":"Оконный каподастр","iconUrl":"/nte-meta/game-assets/7983fb2e7b211c9adb80.webp","description":"Снижает все виды сопротивления врагов на 7,5 %, пока они находятся под действием Обертона. Увеличивает урон активного персонажа внутри Поля реверберации на 12,5 %."},{"level":3,"kind":"awakening","name":"Капсулы тени","iconUrl":"/nte-meta/game-assets/8aaeb06bcd61b54a4b0d.webp","description":"Увеличивает множитель урона «Ритмической волны» на 150 % при нажатии кнопки для наложения Обертона. Увеличивает радиус Поля реверберации на 25 %. Аканэ Рин 1 раз стягивает врагов при удерживании кнопки навыка «Ритмическая волна» для развёртывания Поля реверберации."},{"level":4,"kind":"awakening","name":"Помехи в наушниках","iconUrl":"/nte-meta/game-assets/d0d64c6bea6d06809d9e.webp","description":"Увеличивает атаку Аканэ Рин на 16 % в течение 10 сек. после применения «Синхронизированного резонанса»."},{"level":5,"kind":"awakening","name":"Репетиционный клик","iconUrl":"/nte-meta/game-assets/21df147aca34a384d469.webp","description":"Увеличивает бонус к множителю урона базовых атак, передаваемых через Обертон, с 32,5 % до 50 %. Увеличивает бонус к урону базовых атак, передаваемых через Поле реверберации, с 36 % до 60 %."},{"level":6,"kind":"awakening","name":"Сверхновая на авансцене","iconUrl":"/nte-meta/game-assets/52c9ddc18c75b15edf2e.webp","description":"«Звёздный гимн» дополнительно увеличивает наносимый всеми союзниками урон на 10 %."},{"level":3,"kind":"resonance","name":"Диатоника","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень базовой атаки, навыка перенаправления и сверхспособности Аканэ Рин на 1. Полностью восстанавливает Струнную энергию при вступлении в бой. Увеличивает множитель урона «Синхронизированного резонанса» на фиксированные 800 %. Увеличивает множитель урона второго этапа «Звукового удара» на фиксированные 1000 %."},{"level":6,"kind":"resonance","name":"Полифония","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Возвращает 10 ед. Струнной энергии после применения «Синхронизированного резонанса». Увеличивает крит. урон Аканэ Рин на 64 % в течение 25 сек. после применения «Синхронизированного резонанса»."}]') WHERE character_id='akane' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 16:33:23');

UPDATE character_profiles SET abilities_json=json('[{"id":"f75991d9-4d92-4c86-918b-bc00f6e3036e","name":"Струнный клинок","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/23c20db8531648abd235.webp","description":"Даже самый простой удар по струнам способен пробудить бурю в душе.","attributes":[{"id":"parameter-0","label":"Базовый множитель урона 1-го удара «Струнным клинком» и получаемая Струнная энергия","value":"1: 14.9 % *2, 1 · 2: 16.1 % *2, 1 · 3: 17.4 % *2, 1 · 4: 18.8 % *2, 1 · 5: 20.3 % *2, 1 · 6: 21.9 % *2, 1 · 7: 23.6 % *2, 1 · 8: 25.5 % *2, 1 · 9: 27.6 % *2, 1 · 10: 29.8 % *2, 1 · 11: 32.2 % *2, 1 · 12: 34.7 % *2, 1 · 13: 37.5 % *2, 1"},{"id":"parameter-1","label":"Базовый множитель урона 2-го удара «Струнным клинком» и получаемая Струнная энергия","value":"1: 21.9 % *2, 1 · 2: 23.7 % *2, 1 · 3: 25.5 % *2, 1 · 4: 27.6 % *2, 1 · 5: 29.8 % *2, 1 · 6: 32.2 % *2, 1 · 7: 34.8 % *2, 1 · 8: 37.5 % *2, 1 · 9: 40.5 % *2, 1 · 10: 43.8 % *2, 1 · 11: 47.3 % *2, 1 · 12: 51.1 % *2, 1 · 13: 55.1 % *2, 1"},{"id":"parameter-2","label":"Базовый множитель урона 3-го удара «Струнным клинком» и получаемая Струнная энергия","value":"1: 10.3 % *3 + 13.5 % *4, 2 · 2: 11.1 % *3 + 14.6 % *4, 2 · 3: 12 % *3 + 15.7 % *4, 2 · 4: 13 % *3 + 17 % *4, 2 · 5: 14 % *3 + 18.4 % *4, 2 · 6: 15.1 % *3 + 19.8 % *4, 2 · 7: 16.3 % *3 + 21.4 % *4, 2 · 8: 17.7 % *3 + 23.1 % *4, 2 · 9: 19.1 % *3 + 25 % *4, 2 · 10: 20.6 % *3 + 27 % *4, 2 · 11: 22.2 % *3 + 29.1 % *4, 2 · 12: 24 % *3 + 31.5 % *4, 2 · 13: 25.9 % *3 + 34 % *4, 2"},{"id":"parameter-3","label":"Базовый множитель урона 4-го удара «Струнным клинком» и получаемая Струнная энергия","value":"1: 424.7 %, 6 · 2: 458.7 %, 6 · 3: 495.4 %, 6 · 4: 535 %, 6 · 5: 577.8 %, 6 · 6: 624 %, 6 · 7: 673.9 %, 6 · 8: 727.9 %, 6 · 9: 786.1 %, 6 · 10: 849 %, 6 · 11: 916.9 %, 6 · 12: 990.2 %, 6 · 13: 1069.5 %, 6"},{"id":"parameter-5","label":"Множитель урона атаки в падении & полученная Струнная энергия","value":"1: 62.5 %, 1 · 2: 67.5 %, 1 · 3: 72.9 %, 1 · 4: 78.7 %, 1 · 5: 85 %, 1 · 6: 91.8 %, 1 · 7: 99.2 %, 1 · 8: 107.1 %, 1 · 9: 115.7 %, 1 · 10: 124.9 %, 1 · 11: 134.9 %, 1 · 12: 145.7 %, 1 · 13: 157.4 %, 1"},{"id":"parameter-6","label":"Множитель критического контрудара и получаемая Струнная энергия","value":"1: 137.5 %, 2 · 2: 148.5 %, 2 · 3: 160.4 %, 2 · 4: 173.2 %, 2 · 5: 187.1 %, 2 · 6: 202 %, 2 · 7: 218.2 %, 2 · 8: 235.7 %, 2 · 9: 254.5 %, 2 · 10: 274.9 %, 2 · 11: 296.9 %, 2 · 12: 320.6 %, 2 · 13: 346.2 %, 2"}]},{"id":"GA_Akane_Skill_Gitar_name","name":"Играть по слуху","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/f009892b425f141ccc05.webp","description":"В открытом мире Аканэ Рин может в любой момент взять в руки гитару и сыграть любую мелодию, которая придёт ей в голову.","attributes":[]},{"id":"GA_Akane_Passive1_name","name":"Абсолютный слух","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/a153c7ecd5c868b57040.webp","description":"Усиление Реморы: когда отряд впервые активирует эффект «Ремора», Аканэ Рин получает усиление, которое действует до тех пор, пока она не покинет бой. Каждые 3 сек. накладывает Ремору на цель под действием Обертона и на всех врагов внутри Поля реверберации.\n\nКаждый раз, когда отряд повторно накладывает Ремору на уже поражённую цель, Аканэ Рин наносит урон лакшаны (считается уроном от навыка перенаправления) в размере 150 % от показателя атаки Аканэ Рин. Этот урон увеличивается на 20 % за каждую 1 сек. оставшегося времени действия Реморы на цели (максимальное увеличение — 160 %).\n\nОставшееся время действия Реморы рассчитывается для каждой цели индивидуально. Этот урон может срабатывать на одной цели не чаще одного раза в 1 сек.","attributes":[]},{"id":"GA_Akane_QTE_name","name":"Альтерированный аккорд","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/e528a3ac414ad4ce9546.webp","description":"Аканэ Рин мощно проводит по струнам и 1 раз наносит урон лакшаны.","attributes":[{"id":"parameter-0","label":"Множитель урона и получаемая Струнная энергия","value":"1: 200 %, 4 · 2: 216 %, 4 · 3: 233.3 %, 4 · 4: 251.9 %, 4 · 5: 272.1 %, 4 · 6: 293.9 %, 4 · 7: 317.4 %, 4 · 8: 342.8 %, 4 · 9: 370.2 %, 4 · 10: 399.8 %, 4 · 11: 431.8 %, 4 · 12: 466.3 %, 4 · 13: 503.6 %, 4"}]},{"id":"GA_Akane_UltraSkill_End_name","name":"Звуковой удар","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/fef649cbf515bb5b2cc6.webp","description":"Аканэ Рин применяет первый этап «Звукового удара», нанося несколько ударов с огромным уроном лакшаны врагам в целевой области, и входит в состояние «Сольная каденция» на 20 сек. Пока это состояние активно, её устойчивость к прерываниям повышается.\n\nСпустя 4 сек. после применения «Сольной каденции» повторное нажатие кнопки навыка «Звуковой удар» позволяет в любой момент применить второй этап навыка, что досрочно завершает действие «Сольной каденции» и наносит 1 удар с огромным уроном лакшаны врагам в целевой области. Второй этап необходимо применять вручную. По окончании «Сольной каденции» он не применяется автоматически. Если второй этап не был применён до завершения «Сольной каденции», он становится недоступным.\n\n«Сольная каденция» действует независимо от Обертона и Поля реверберации и не снимает и не заменяет ни один из этих эффектов.\n\nНаходясь вне боя, Аканэ Рин восстанавливает по 3 ед. энергии сверхспособности в секунду.","attributes":[{"id":"parameter-0","label":"Множитель урона 1-го этапа","value":"1: 64.8 % *10 · 2: 70 % *10 · 3: 75.6 % *10 · 4: 81.6 % *10 · 5: 88.2 % *10 · 6: 95.2 % *10 · 7: 102.8 % *10 · 8: 111.1 % *10 · 9: 119.9 % *10 · 10: 129.5 % *10 · 11: 139.9 % *10 · 12: 151.1 % *10 · 13: 163.2 % *10"},{"id":"parameter-1","label":"Множитель урона 2-го этапа","value":"1: 918 % · 2: 991.4 % · 3: 1070.8 % · 4: 1156.4 % · 5: 1248.9 % · 6: 1348.8 % · 7: 1456.8 % · 8: 1573.3 % · 9: 1699.2 % · 10: 1835.1 % · 11: 1981.9 % · 12: 2140.4 % · 13: 2311.7 %"}]},{"id":"f66d9ae1-f9be-42a8-872d-bc4678c13675","name":"Ритмическая волна","type":"Навык","iconUrl":"/nte-meta/game-assets/f009892b425f141ccc05.webp","description":"Навык «Ритмическая волна» Аканэ Рин можно применять двумя способами. Нажатие: накладывает Обертон на цель на 25 сек. и наносит урон лакшаны. Когда Аканэ Рин выполняет базовую атаку, Обертон резонирует: базовая атака переносится на дальнее расстояние и поражает цель под этим эффектом, при этом множитель урона перенесённой базовой атаки увеличивается на 32,5 %. Удерживание: создаёт Поле реверберации на 25 сек. и наносит урон лакшаны врагам в радиусе действия. Когда Аканэ Рин выполняет базовую атаку, Поле реверберации резонирует: базовая атака передаётся через поле, нанося 1 удар урона базовой атаки всем врагам в радиусе действия, при этом урон перенесённой базовой атаки увеличивается ещё на 36 %. На поле боя может существовать только один эффект — либо Обертон, либо Поле реверберации. Успешное создание новой формы заменяет собой предыдущую. Оба способа активации имеют общую перезарядку. Как только время перезарядки истекает, вы можете снова выбрать любую из форм. Доступ к навыку «Синхронизированный резонанс» открывается, когда Струнная энергия достигает 30 ед. и действует Обертон или Поле реверберации. Активирует усиленный эффект в зависимости от текущей формы: Обертон: наносит 1 удар огромного урона лакшаны по одной цели. Поле реверберации: наносит 1 удар усиленного урона лакшаны с эффектом разброса врагам в радиусе действия. Попадание «Синхронизированным резонансом» расходует 30 ед. Струнной энергии; в случае промаха энергия не тратится. При этом текущий Обертон или Поле реверберации сохраняются, но оставшееся время их действия не обновляется. «Синхронизированный резонанс» не имеет собственной перезарядки и не влияет на обычную перезарядку «Ритмической волны». «Синхронизированный резонанс» невозможно применить, если не активен ни Обертон, ни Поле реверберации — сначала необходимо создать один из эффектов с помощью «Ритмической волны».","attributes":[{"id":"parameter-0","label":"Множитель урона Обертона и получаемая Струнная энергия","value":"1: 360 %, 6 · 2: 388.8 %, 6 · 3: 419.9 %, 6 · 4: 453.5 %, 6 · 5: 489.8 %, 6 · 6: 529 %, 6 · 7: 571.3 %, 6 · 8: 617 %, 6 · 9: 666.3 %, 6 · 10: 719.6 %, 6 · 11: 777.2 %, 6 · 12: 839.4 %, 6 · 13: 906.5 %, 6"},{"id":"parameter-2","label":"Множитель урона Поля реверберации и получаемая Струнная энергия","value":"1: 162 % *2, 6 · 2: 175 % *2, 6 · 3: 189 % *2, 6 · 4: 204.1 % *2, 6 · 5: 220.4 % *2, 6 · 6: 238 % *2, 6 · 7: 257.1 % *2, 6 · 8: 277.6 % *2, 6 · 9: 299.9 % *2, 6 · 10: 323.8 % *2, 6 · 11: 349.7 % *2, 6 · 12: 377.7 % *2, 6 · 13: 407.9 % *2, 6"},{"id":"parameter-4","label":"Обертон: множитель урона «Синхронизированного резонанса»","value":"1: 1125 % · 2: 1215 % · 3: 1312.2 % · 4: 1417.2 % · 5: 1530.6 % · 6: 1653 % · 7: 1785.2 % · 8: 1928.1 % · 9: 2082.3 % · 10: 2248.9 % · 11: 2428.8 % · 12: 2623.1 % · 13: 2832.9 %"},{"id":"parameter-7","label":"Поле реверберации: множитель урона «Синхронизированного резонанса»","value":"1: 1012.5 % · 2: 1093.5 % · 3: 1181 % · 4: 1275.5 % · 5: 1377.5 % · 6: 1487.7 % · 7: 1606.7 % · 8: 1735.2 % · 9: 1874.1 % · 10: 2024 % · 11: 2185.9 % · 12: 2360.8 % · 13: 2549.6 %"}]},{"id":"GA_Akane_Passive2_name","name":"Звёздный гимн","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/a153c7ecd5c868b57040.webp","description":"Увеличивает атаку Аканэ Рин на 20 % в течение 20 сек. после применения «Звукового удара». Эффект не складывается. При повторном срабатывании длительность обновляется.","attributes":[]},{"id":"GA_Akane_Skill_instead_name","name":"Синхронизированный резонанс","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/f009892b425f141ccc05.webp","description":"Доступ к навыку «Синхронизированный резонанс» открывается, когда Струнная энергия достигает 30 ед. и действует Обертон или Поле реверберации. Нажмите кнопку навыка перенаправления, чтобы применить «Синхронизированный резонанс» и активировать усиленные эффекты в зависимости от текущей формы:\n\nОбертон: наносит 1 удар с огромным уроном лакшаны по цели под этим эффектом.\n\nПоле реверберации: наносит 1 удар с огромным уроном лакшаны всем врагам в радиусе действия.\n\nПопадание «Синхронизированным резонансом» расходует 30 ед. Струнной энергии; в случае промаха энергия не тратится. При этом существующий эффект — Обертон или Поле реверберации — сохраняется, но оставшееся время его действия не обновляется. Даёт Аканэ Рин неуязвимость и иммунитет к прерыванию во время применения «Синхронизированного резонанса».\n\n«Синхронизированный резонанс» не имеет собственной перезарядки и не влияет на обычную перезарядку «Ритмической волны».\n\n«Синхронизированный резонанс» невозможно применить, если не активен ни Обертон, ни Поле реверберации — сначала необходимо создать один из эффектов с помощью нажатия или удерживания кнопки навыка «Ритмическая волна».","attributes":[{"id":"parameter-0","label":"Обертон: множитель урона «Синхронизированного резонанса»","value":"1: 1012.5 % · 2: 1093.5 % · 3: 1181 % · 4: 1275.5 % · 5: 1377.5 % · 6: 1487.7 % · 7: 1606.7 % · 8: 1735.2 % · 9: 1874.1 % · 10: 2024 % · 11: 2185.9 % · 12: 2360.8 % · 13: 2549.6 %"}]},{"id":"City_Ability_Akane_01","name":"Фирменный коктейль","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/2ec38429b2b7dc4bfe65.webp","description":"Аканэ Рин увеличивает поток посетителей на 18.","attributes":[{"id":"city-0","label":"Уровень 1","value":"Аканэ Рин увеличивает поток посетителей на 18."},{"id":"city-1","label":"Уровень 2","value":"Аканэ Рин снижает скорость расхода ингредиентов на 1 %."},{"id":"city-2","label":"Уровень 3","value":"Аканэ Рин увеличивает поток посетителей на 18."},{"id":"city-3","label":"Уровень 4","value":"Аканэ Рин снижает скорость расхода ингредиентов на 1 %."},{"id":"city-4","label":"Уровень 5","value":"Аканэ Рин увеличивает поток посетителей на 27."}]},{"id":"City_Ability_Akane_02","name":"Блистательный кумир","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/e3dcd8b30da1ff381602.webp","description":"«Суперзвук» расходует на 1 ед. больше выносливости в городе за один забег.","attributes":[{"id":"city-0","label":"Уровень 1","value":"«Суперзвук» расходует на 1 ед. больше выносливости в городе за один забег."},{"id":"city-1","label":"Уровень 2","value":"«Суперзвук» расходует на 1 ед. больше выносливости в городе за один забег."}]}]') WHERE character_id='akane' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 16:33:23');

