UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Глаз","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1054_1.png","description":"Увеличивает урон «Резонанса» союзников на 100 % и разрушение на 250 % за каждое применение навыка поддержки."},{"level":2,"kind":"awakening","name":"Механический марш","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1054_2.png","description":"Наносит цели высокий урон, накладывает разрушение и полностью заряжает Финал последней атакой, если Призрачному шагу не удаётся нанести ответный удар цели."},{"level":3,"kind":"awakening","name":"Собрание творений","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1054_3.png","description":"Не позволяет снять наложенную Проницательность, за исключением случаев, когда цель нейтрализована или выходит из боя. Позволяет суммировать эффект при повторном наложении до 2 раз."},{"level":4,"kind":"awakening","name":"В укрытии","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1054_4.png","description":"Урон от разрушения Даффодил увеличивается на 15 % за каждый уровень Проницательности, если цель входит в состояние разрушения, находясь под действием Проницательности."},{"level":5,"kind":"awakening","name":"Идеальная истина","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1054_5.png","description":"Наносит 1 дополнительный экземпляр урона от разрушения за каждый уровень Проницательности, если цель входит в состояние разрушения, находясь под действием Проницательности."},{"level":6,"kind":"awakening","name":"Цветок на озере","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1054_6.png","description":"При нанесении урона игнорирует 15 % защиты цели."},{"level":3,"kind":"resonance","name":"Секретная операция","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Увеличивает уровень навыков «Спокойные воды», «Резонанс» и «Финал» на 1."},{"level":6,"kind":"resonance","name":"Свет солнца и убежище","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Снижает сопротивление хаосу цели на 15 %, когда цель входит в состояние разрушения."}]') WHERE character_id='daffodill' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-17 22:04:33');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"en-Play_Vo_Char_NPC013_gift_001","title":"Подарок получен I","description":"Кажется, я тебе ещё не говорила, но… мне очень нравится. Спасибо.","language":"Английский","audioUrl":"/nte-meta/game-audio/d96f1315ec8476a4fba9.ogg"},{"id":"ja-Play_Vo_Char_NPC013_about_003","title":"О Наналли","description":"Эта девчонка постоянно подсматривает за мной, когда я тренируюсь. Я несколько раз её ловила, но она просто находит другое место и продолжает… Что ж, пока она мне не мешает, пусть.","language":"Японский","audioUrl":"/nte-meta/game-audio/53021b2e2289a0734280.ogg"},{"id":"ja-Play_Vo_Char_NPC013_ug_003","title":"Вознесение персонажа III","description":"Таким образом, твоя безопасность гарантирована.","language":"Японский","audioUrl":"/nte-meta/game-audio/b7d3d3c9e46a9db28771.ogg"},{"id":"en-Play_Vo_Char_NPC013_deploy_001","title":"Отправка I","description":"Новое поручение?","language":"Английский","audioUrl":"/nte-meta/game-audio/d65567e3816a53dab1c2.ogg"},{"id":"ja-Play_Vo_Char_NPC013_Switch_002","title":"Переключение II","description":"Предоставь это мне.","language":"Японский","audioUrl":"/nte-meta/game-audio/aa2ca5232603a1142fbb.ogg"},{"id":"ja-Play_Vo_Char_NPC013_greet_003","title":"Вечернее приветствие","description":"Мы можем ещё немного потренироваться. Хочешь присоединиться?","language":"Японский","audioUrl":"/nte-meta/game-audio/8da4369b67ee7942a2eb.ogg"},{"id":"ja-Play_Vo_Char_NPC013_about_006","title":"Об антикварном магазине Эйбон","description":"«Эйбон» не похож на те места, к которым я привыкла. Здесь приходится иметь дело со сложными клиентами, чтобы заработать на жизнь, и твои друзья все время здесь, от них столько шума… но, по крайней мере, я могу спать, ни о чем не волнуясь.","language":"Японский","audioUrl":"/nte-meta/game-audio/c3a4fc703eafeab43a4f.ogg"},{"id":"ja-Play_Vo_Char_NPC013_TeammateDown_002","title":"Поражен товарищ по команде – Адлер","description":"Это ещё не конец.","language":"Японский","audioUrl":"/nte-meta/game-audio/ca531fe8cf33d9ccb582.ogg"},{"id":"en-Play_Vo_Char_NPC013_anomaly_003","title":"Нуллификация II","description":"Кризис предотвращён.","language":"Английский","audioUrl":"/nte-meta/game-audio/536d8551b68d977ab886.ogg"},{"id":"en-Play_Vo_Char_NPC013_vexation_001","title":"Проблемы","description":"С некоторыми клиентами сложнее, чем с аномалиями, но Хотори говорит, нужно всегда улыбаться ради благополучия «Эйбона»… А? Думаешь, процент успешно выполненных поручений в последнее время снизился? Кхм… это совершенно не так.","language":"Английский","audioUrl":"/nte-meta/game-audio/17a02b586d7ede0346fd.ogg"},{"id":"ja-Play_Vo_Char_NPC013_gift_002","title":"Подарок получен II","description":"Для меня это бесценно. Огромное спасибо.","language":"Японский","audioUrl":"/nte-meta/game-audio/608a50cfa752e6212209.ogg"},{"id":"ja-Play_Vo_Char_NPC013_ug_001","title":"Вознесение персонажа I","description":"Упорный труд приносит результат.","language":"Японский","audioUrl":"/nte-meta/game-audio/3e61bdbc721d5526e580.ogg"},{"id":"en-Play_Vo_Char_NPC013_about_004","title":"О Занку","description":"Она очень опасна. По возможности лучше избегать любого контакта с ней.","language":"Английский","audioUrl":"/nte-meta/game-audio/192668190c800764a543.ogg"},{"id":"en-Play_Vo_Char_NPC013_self_001","title":"Обо мне: способности эспера","description":"Просто обмен на часть моего зрения, не сильно влияет на повседневную жизнь. Иногда слышишь больше, чем видишь.","language":"Английский","audioUrl":"/nte-meta/game-audio/83fb29b3383b5504bcab.ogg"},{"id":"en-Play_Vo_Char_NPC013_hstruck_002","title":"Сильный урон II","description":"Опять.","language":"Английский","audioUrl":"/nte-meta/game-audio/1c2d66e23d1ea9f27021.ogg"},{"id":"en-Play_Vo_Char_NPC013_talk_002","title":"Тема: тренировки","description":"Я не считаю ежедневные тренировки утомительными. Без боли не бывает результата, так? Единственный способ не облажаться — стать сильнее.","language":"Английский","audioUrl":"/nte-meta/game-audio/21fa62a7e3bba12c8d52.ogg"},{"id":"en-Play_Vo_Char_NPC013_windfall_005","title":"Неожиданная добыча V","description":"Приятный сюрприз.","language":"Английский","audioUrl":"/nte-meta/game-audio/7574122bc108f4c8dd01.ogg"},{"id":"en-Play_Vo_Char_NPC013_Switch_003","title":"Переключение III","description":"Вот я.","language":"Английский","audioUrl":"/nte-meta/game-audio/e8254507a681ac9264f6.ogg"},{"id":"ja-Play_Vo_Char_NPC013_dead_001","title":"Потеря сознания I","description":"Прости… Я тебя подвела…","language":"Японский","audioUrl":"/nte-meta/game-audio/061984ae9edb7f29fbaa.ogg"},{"id":"en-Play_Vo_Char_NPC013_skill_002","title":"Навык перенаправления II","description":"Никакой пощады!","language":"Английский","audioUrl":"/nte-meta/game-audio/afc35431f8dc9ec61380.ogg"},{"id":"en-Play_Vo_Char_NPC013_ug_002","title":"Вознесение персонажа II","description":"Я могу стать сильнее.","language":"Английский","audioUrl":"/nte-meta/game-audio/0a97594c9ed07429b4b8.ogg"},{"id":"en-Play_Vo_Char_NPC013_windfall_001","title":"Неожиданная добыча I","description":"Давай отнесем это обратно в «Эйбон».","language":"Английский","audioUrl":"/nte-meta/game-audio/a8d6a651d9a455c997d0.ogg"},{"id":"ja-Play_Vo_Char_NPC013_about_002","title":"О Хотори: первая встреча","description":"Когда мы впервые встретились, она была пьяна. Я просто решила, что она какая-то странная женщина. Но почему‑то… рядом с ней было так спокойно, и я ей доверилась. Полагаю, поэтому я сейчас здесь.","language":"Японский","audioUrl":"/nte-meta/game-audio/6af0117d6842e2060dbc.ogg"},{"id":"ja-Play_Vo_Char_NPC013_fh_002","title":"Исцеление II","description":"Восстанавливаю силы.","language":"Японский","audioUrl":"/nte-meta/game-audio/4a000560fef101aa3a10.ogg"},{"id":"ja-Play_Vo_Char_NPC013_gift_001","title":"Подарок получен I","description":"Кажется, я тебе ещё не говорила, но… мне очень нравится. Спасибо.","language":"Японский","audioUrl":"/nte-meta/game-audio/e6315d2d0f5eab4b6d89.ogg"},{"id":"ja-Play_Vo_Char_NPC013_Parry_001","title":"Парирование I","description":"Предсказуемо.","language":"Японский","audioUrl":"/nte-meta/game-audio/ee657dae8002ff73f891.ogg"},{"id":"en-Play_Vo_Char_NPC013_Parry_002","title":"Парирование II","description":"Будь начеку.","language":"Английский","audioUrl":"/nte-meta/game-audio/dd6564e6cc89e387e94f.ogg"},{"id":"ja-Play_Vo_Char_NPC013_ug_002","title":"Вознесение персонажа II","description":"Я могу стать сильнее.","language":"Японский","audioUrl":"/nte-meta/game-audio/bca3cfc22bf9c847f5d2.ogg"},{"id":"en-Play_Vo_Char_NPC013_SSC_004","title":"Особое переключение — Наналли","description":"Отличная работа.","language":"Английский","audioUrl":"/nte-meta/game-audio/a09eb4374dc39ef89081.ogg"},{"id":"en-Play_Vo_Char_NPC013_windfall_006","title":"Неожиданная добыча VI","description":"Как раз то, что нам нужно.","language":"Английский","audioUrl":"/nte-meta/game-audio/04e1ff97fe6ffb50a37f.ogg"},{"id":"ja-Play_Vo_Char_NPC013_skill_003","title":"Навык перенаправления III","description":"Зачистка!","language":"Японский","audioUrl":"/nte-meta/game-audio/97a935c8d7c128c09ee6.ogg"},{"id":"ja-Play_Vo_Char_NPC013_vexation_001","title":"Проблемы","description":"С некоторыми клиентами сложнее, чем с аномалиями, но Хотори говорит, нужно всегда улыбаться ради благополучия «Эйбона»… А? Думаешь, процент успешно выполненных поручений в последнее время снизился? Кхм… это совершенно не так.","language":"Японский","audioUrl":"/nte-meta/game-audio/9c9e92d661f7c5adc19c.ogg"},{"id":"ja-Play_Vo_Char_NPC013_aoe_UI_002","title":"Сверхспособность II","description":"Перед тобой иллюзия!","language":"Японский","audioUrl":"/nte-meta/game-audio/c16c1bfd0d058438cde5.ogg"},{"id":"en-Play_Vo_Char_NPC013_about_005","title":"Об Адлере","description":"Адлер — весьма уважаемый человек. До того, как я встретила Хотори, он всегда был рядом с ней. Мне предстоит многому у него научиться.","language":"Английский","audioUrl":"/nte-meta/game-audio/0505c00d1eeea0e3ed57.ogg"},{"id":"en-Play_Vo_Char_NPC013_self_003","title":"Обо мне: имя","description":"Похоже, это означает «нарцисс». На каждом стебле распускается только один цветок. Хотори сказала, что он есть в озере возле моего дома, хотя я его никогда не видела. Если можно, я бы предпочла, чтобы вы называли меня Даффодил, а не… кхм.","language":"Английский","audioUrl":"/nte-meta/game-audio/2cf209c9a80b8004e791.ogg"},{"id":"ja-Play_Vo_Char_NPC013_anomaly_002","title":"Нуллификация I","description":"Готово.","language":"Японский","audioUrl":"/nte-meta/game-audio/0f5c67bf9d6bb310aed8.ogg"},{"id":"ja-Play_Vo_Char_NPC013_self_001","title":"Обо мне: способности эспера","description":"Просто обмен на часть моего зрения, не сильно влияет на повседневную жизнь. Иногда слышишь больше, чем видишь.","language":"Японский","audioUrl":"/nte-meta/game-audio/3e4400a7c2ab4ba620ca.ogg"},{"id":"en-Play_Vo_Char_NPC013_Parry_001","title":"Парирование I","description":"Предсказуемо.","language":"Английский","audioUrl":"/nte-meta/game-audio/79cba6cef3d206ae98d6.ogg"},{"id":"en-Play_Vo_Char_NPC013_talk_001","title":"Тема: аномалии","description":"Истина нередко прячется среди лжи. И люди, и аномалии — не то, чем кажутся на первый взгляд. Одного лишь «смотреть» недостаточно. Нужно понимать, чувствовать и анализировать. Лишь когда ты смотришь на всё как через калейдоскоп, с множества ракурсов… ты сможешь постичь саму истину.","language":"Английский","audioUrl":"/nte-meta/game-audio/0bc21156b83bbf5041c1.ogg"},{"id":"en-Play_Vo_Char_NPC013_windfall_004","title":"Неожиданная добыча IV","description":"Береги это.","language":"Английский","audioUrl":"/nte-meta/game-audio/26533d2d56beefcbcc77.ogg"},{"id":"en-Play_Vo_Char_NPC013_containment_001","title":"Сдерживание I","description":"Нужно сопровождение в Бюро?","language":"Английский","audioUrl":"/nte-meta/game-audio/c76b851cb97c0a2b14ce.ogg"},{"id":"en-Play_Vo_Char_NPC013_meet_001","title":"Первая встреча","description":"Привет, я Даффодил, телохранитель Хотори… Слишком просто? Извини, беседы — не мой конек. Если что-то понадобится, обращайся в антикварный магазин «Эйбон».","language":"Английский","audioUrl":"/nte-meta/game-audio/bd853b9c65a8e9ea05e9.ogg"},{"id":"ja-Play_Vo_Char_NPC013_chat_003","title":"Чат: приветствия","description":"Уважаемый клиент… добро… добро пожаловать. Ш-ш.","language":"Японский","audioUrl":"/nte-meta/game-audio/f22859fed6a711075d4c.ogg"},{"id":"ja-Play_Vo_Char_NPC013_weather_001","title":"Солнечно","description":"Хорошая погода. Время потренироваться на свежем воздухе.","language":"Японский","audioUrl":"/nte-meta/game-audio/010702a97d73156f5b45.ogg"},{"id":"en-Play_Vo_Char_NPC013_kill_002","title":"Убийство II","description":"Какая хрупкость.","language":"Английский","audioUrl":"/nte-meta/game-audio/419ade85fb48a7499f1d.ogg"},{"id":"ja-Play_Vo_Char_NPC013_about_004","title":"О Занку","description":"Она очень опасна. По возможности лучше избегать любого контакта с ней.","language":"Японский","audioUrl":"/nte-meta/game-audio/22bcbed66b7da731f0a8.ogg"},{"id":"ja-Play_Vo_Char_NPC013_aoe_UI_001","title":"Сверхспособность I","description":"Негде спрятаться!","language":"Японский","audioUrl":"/nte-meta/game-audio/96a8680b3efd5c5399c7.ogg"},{"id":"ja-Play_Vo_Char_NPC013_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Передохни немного, оценщик.Передохни немного, оценщица.","language":"Японский","audioUrl":"/nte-meta/game-audio/0792f2a34fbd5e22cec9.ogg"},{"id":"en-Play_Vo_Char_NPC013_about_002","title":"О Хотори: первая встреча","description":"Когда мы впервые встретились, она была пьяна. Я просто решила, что она какая-то странная женщина. Но почему‑то… рядом с ней было так спокойно, и я ей доверилась. Полагаю, поэтому я сейчас здесь.","language":"Английский","audioUrl":"/nte-meta/game-audio/b159f851c3329688f754.ogg"},{"id":"ja-Play_Vo_Char_NPC013_weather_003","title":"Холодно","description":"Холод сковывает тело и притупляет чувства… В такой момент, наверное, охотник и добыча могут поменяться местами.","language":"Японский","audioUrl":"/nte-meta/game-audio/6a6094d91a20a2a950d0.ogg"},{"id":"ja-Play_Vo_Char_NPC013_windfall_002","title":"Неожиданная добыча II","description":"Когда-нибудь пригодится.","language":"Японский","audioUrl":"/nte-meta/game-audio/908965474e1dfe036d94.ogg"},{"id":"en-Play_Vo_Char_NPC013_about_003","title":"О Наналли","description":"Эта девчонка постоянно подсматривает за мной, когда я тренируюсь. Я несколько раз её ловила, но она просто находит другое место и продолжает… Что ж, пока она мне не мешает, пусть.","language":"Английский","audioUrl":"/nte-meta/game-audio/3cb3adaf8e94975d05ba.ogg"},{"id":"ja-Play_Vo_Char_NPC013_DodgeCombo_001","title":"Серия критических уклонений I","description":"Двигаешься как попало.","language":"Японский","audioUrl":"/nte-meta/game-audio/6d791f6cfed6d6983e5b.ogg"},{"id":"ja-Play_Vo_Char_NPC013_Fly_002","title":"Планирование II","description":"Аааа…","language":"Японский","audioUrl":"/nte-meta/game-audio/495f5d3cff171fbd072b.ogg"},{"id":"ja-Play_Vo_Char_NPC013_Switch_003","title":"Переключение III","description":"Вот я.","language":"Японский","audioUrl":"/nte-meta/game-audio/c9f755872b121411fa61.ogg"},{"id":"en-Play_Vo_Char_NPC013_gift_004","title":"Подарок получен IV","description":"Хотори сказала, что подарки от друзей нужно принимать с радостью. Что ж… я с радостью его принимаю.","language":"Английский","audioUrl":"/nte-meta/game-audio/5a2043fc366ddc61195e.ogg"},{"id":"en-Play_Vo_Char_NPC013_hp_002","title":"Низкий уровень здоровья II","description":"Не волнуйся.","language":"Английский","audioUrl":"/nte-meta/game-audio/396ccea78488b80f4d7e.ogg"},{"id":"en-Play_Vo_Char_NPC013_SSC_005","title":"Особое переключение — Эдгар","description":"Передохни немного.","language":"Английский","audioUrl":"/nte-meta/game-audio/8a19551b77196c706e50.ogg"},{"id":"ja-Play_Vo_Char_NPC013_Fly_001","title":"Планирование I","description":"Это место…","language":"Японский","audioUrl":"/nte-meta/game-audio/1d8944e6774dbea52795.ogg"},{"id":"ja-Play_Vo_Char_NPC013_hobby_001","title":"Хобби","description":"Не могу сказать, что у меня есть какие-то предпочтения, еда нужна мне просто для выживания. Прессованные конфеты легко носить с собой, и они дают много энергии, так что они всегда со мной на всякий случай. А их вкус для меня не особо важен.","language":"Японский","audioUrl":"/nte-meta/game-audio/2a1d85ff2d6c0e84ddaf.ogg"},{"id":"ja-Play_Vo_Char_NPC013_skill_SE_002","title":"Навык перенаправления V","description":"Приговор!","language":"Японский","audioUrl":"/nte-meta/game-audio/46bb51689f0cb0dd8dd6.ogg"},{"id":"en-Play_Vo_Char_NPC013_TeammateDown_004","title":"Поражен товарищ по команде – Наналли","description":"Ты сделал всё, что мог, остальное оставь мне.","language":"Английский","audioUrl":"/nte-meta/game-audio/c3fc69453fdd92bd7ad7.ogg"},{"id":"ja-Play_Vo_Char_NPC013_talk_001","title":"Тема: аномалии","description":"Истина нередко прячется среди лжи. И люди, и аномалии — не то, чем кажутся на первый взгляд. Одного лишь «смотреть» недостаточно. Нужно понимать, чувствовать и анализировать. Лишь когда ты смотришь на всё как через калейдоскоп, с множества ракурсов… ты сможешь постичь саму истину.","language":"Японский","audioUrl":"/nte-meta/game-audio/734f883c1d7ec3d5c73c.ogg"},{"id":"ja-Play_Vo_Char_NPC013_TeammateDown_007","title":"Поражен товарищ по команде – Ноль","description":"Я тебя не брошу.","language":"Японский","audioUrl":"/nte-meta/game-audio/6fcc0233961412fc030c.ogg"},{"id":"en-Play_Vo_Char_NPC013_anomaly_002","title":"Нуллификация I","description":"Готово.","language":"Английский","audioUrl":"/nte-meta/game-audio/0ee84fb6442ff30d8652.ogg"},{"id":"en-Play_Vo_Char_NPC013_Fly_001","title":"Планирование I","description":"Это место…","language":"Английский","audioUrl":"/nte-meta/game-audio/95e9153621bf445c1830.ogg"},{"id":"en-Play_Vo_Char_NPC013_Switch_002","title":"Переключение II","description":"Предоставь это мне.","language":"Английский","audioUrl":"/nte-meta/game-audio/c88096865d943214dbc1.ogg"},{"id":"en-Play_Vo_Char_NPC013_TeammateDown_006","title":"Поражен товарищ по команде – Эдгар","description":"Не переживай, я возьму это на себя.","language":"Английский","audioUrl":"/nte-meta/game-audio/67fbbf8d67c56f8070e0.ogg"},{"id":"ja-Play_Vo_Char_NPC013_self_002","title":"Обо мне: темные цвета","description":"Интересно, почему я все время в темной одежде..? Не потому, что мне нравится, а потому что она лучше скрывает раны и обманывает врагов.","language":"Японский","audioUrl":"/nte-meta/game-audio/37dd6d87c8d5cc430c5b.ogg"},{"id":"ja-Play_Vo_Char_NPC013_self_003","title":"Обо мне: имя","description":"Похоже, это означает «нарцисс». На каждом стебле распускается только один цветок. Хотори сказала, что он есть в озере возле моего дома, хотя я его никогда не видела. Если можно, я бы предпочла, чтобы вы называли меня Даффодил, а не… кхм.","language":"Японский","audioUrl":"/nte-meta/game-audio/8acb781d32b58a049045.ogg"},{"id":"ja-Play_Vo_Char_NPC013_SSC_004","title":"Особое переключение — Наналли","description":"Отличная работа.","language":"Японский","audioUrl":"/nte-meta/game-audio/c4ee663978608902deb1.ogg"},{"id":"en-Play_Vo_Char_NPC013_dead_002","title":"Потеря сознания II","description":"Если я чем-то могу помочь…","language":"Английский","audioUrl":"/nte-meta/game-audio/e78d65098ebc2fe16a9b.ogg"},{"id":"en-Play_Vo_Char_NPC013_hstruck_001","title":"Сильный урон I","description":"Просто царапина.","language":"Английский","audioUrl":"/nte-meta/game-audio/d1ae843848237bd936e0.ogg"},{"id":"en-Play_Vo_Char_NPC013_skill_003","title":"Навык перенаправления III","description":"Зачистка!","language":"Английский","audioUrl":"/nte-meta/game-audio/713bc0a6d2534fabb916.ogg"},{"id":"ja-Play_Vo_Char_NPC013_hstruck_002","title":"Сильный урон II","description":"Опять.","language":"Японский","audioUrl":"/nte-meta/game-audio/2b71eab3f702882a5087.ogg"},{"id":"ja-Play_Vo_Char_NPC013_skill_SE_001","title":"Навык перенаправления IV","description":"Тщетная попытка.","language":"Японский","audioUrl":"/nte-meta/game-audio/da1da48cb68a1728829b.ogg"},{"id":"en-Play_Vo_Char_NPC013_chat_002","title":"Чат: оружие","description":"Даже лучшему оружию требуется регулярная заточка, чтобы сохранять остроту, то же касается и людей.","language":"Английский","audioUrl":"/nte-meta/game-audio/e85f5bee01901b8f97f6.ogg"},{"id":"en-Play_Vo_Char_NPC013_greet_001","title":"Утреннее приветствие","description":"Доброе утро, какие планы на сегодня?","language":"Английский","audioUrl":"/nte-meta/game-audio/c2cb1b3614a99ba864a6.ogg"},{"id":"ja-Play_Vo_Char_NPC013_chat_001","title":"Чат: отдых","description":"Займись чем-нибудь. Сидеть без движения вредно для здоровья.","language":"Японский","audioUrl":"/nte-meta/game-audio/a275f41d0775aeec49ac.ogg"},{"id":"ja-Play_Vo_Char_NPC013_containment_002","title":"Сдерживание II","description":"Сдерживание завершено.","language":"Японский","audioUrl":"/nte-meta/game-audio/10ca7abcdf84dfc500d5.ogg"},{"id":"ja-Play_Vo_Char_NPC013_DodgeCombo_002","title":"Серия критических уклонений II","description":"Ты, похоже, вообще не умеешь сдаваться.","language":"Японский","audioUrl":"/nte-meta/game-audio/416c8a433842e96eb505.ogg"},{"id":"en-Play_Vo_Char_NPC013_DodgeCombo_002","title":"Серия критических уклонений II","description":"Ты, похоже, вообще не умеешь сдаваться.","language":"Английский","audioUrl":"/nte-meta/game-audio/77000384238c66225f62.ogg"},{"id":"en-Play_Vo_Char_NPC013_greet_004","title":"Спокойной ночи","description":"Отдыхай, ночью «Эйбон» в безопасности.","language":"Английский","audioUrl":"/nte-meta/game-audio/15dd8fdb6ffccdecdd70.ogg"},{"id":"en-Play_Vo_Char_NPC013_hp_001","title":"Низкий уровень здоровья I","description":"Я в порядке.","language":"Английский","audioUrl":"/nte-meta/game-audio/6cc4340f258f29a43993.ogg"},{"id":"en-Play_Vo_Char_NPC013_QTE_003","title":"Атака на входе III","description":"Передача завершена.","language":"Английский","audioUrl":"/nte-meta/game-audio/6262260cbe37b39da0f7.o