UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Глаза Бездны","iconUrl":"/nte-meta/game-assets/45d35865455c513062d9.webp","description":"После пробуждения позволяет навыкам «Бушующий огонь», «Мерцающая тень», «Шаг сквозь пустоту», а также усиленным версиям «Кровавого рывка» и «Перекрестья душ» распространять эффекты периодического урона. Постоянно даёт Занку усиления «Охота» и «Наваждение». Поддерживает оба усиления активными без задержки снятия и предотвращает их потерю, когда Занку покидает поле боя или меняет формы. Эти эффекты снимаются только в случае гибели Занку.\n\nБонус урона, предоставляемый Занку эффектом «Охота», увеличивается до 40 %. Бонус крит. урона от эффектов периодического урона, предоставляемый всей команде эффектом «Наваждение», увеличивается до 50 %."},{"level":2,"kind":"awakening","name":"Поцелуй Бездны","iconUrl":"/nte-meta/game-assets/721cd887c44428aaf395.webp","description":"Когда Занку участвует в Цикле, вызывающем «Ожог» или «Колдовство», в качестве одной из двух сторон, она может накапливать «Разжигание», повышая итоговый урон следующей «Сверхспособности: Адское фламенко» на 150 %; «Разжигание» можно накапливать заранее, ещё до того, как станет доступна «Сверхспособность: Адское фламенко», максимум до 1 заряда."},{"level":3,"kind":"awakening","name":"Поцелуй внутри кошмара","iconUrl":"/nte-meta/game-assets/3c61f3bc9863398c4c8b.webp","description":"«Охота» дополнительно увеличивает устойчивость Занку к прерыванию на 50 %. «Наваждение» дополнительно восстанавливает ей каждую секунду ОЗ в размере 4 % от её макс. ОЗ."},{"level":4,"kind":"awakening","name":"Цветение кошмара","iconUrl":"/nte-meta/game-assets/be1f41392c4a9ad9bb7e.webp","description":"Занку мгновенно активирует «Грёзы о кровавом пире», как только «Адское фламенко» становится доступно.\n\nПрименяет бонус к урону от «Разжигания» к навыку «Грёзы о кровавом пире», который использует те же уровни «Разжигания», что и «Адское фламенко»."},{"level":5,"kind":"awakening","name":"Цветение в крови","iconUrl":"/nte-meta/game-assets/b7b268d47977761c212e.webp","description":"Гарантированно переводит в сломленное состояние первую поражённую усиленным «Кровавым рывком» цель, которую можно сломить. Срабатывает только один раз за бой для каждой цели и не влияет на боссов в режиме балансировки персонажей.\n\nКогда Занку находится в команде, урон от разрушения всех союзников увеличивается на 300 %."},{"level":6,"kind":"awakening","name":"Залитые кровью глаза","iconUrl":"/nte-meta/game-assets/d223bb44c092c93b74ad.webp","description":"Увеличивает урон финального удара «Забвения» по одиночной цели на 12 % за каждый уровень эффекта периодического урона на этой цели, вплоть до 240 %. При попадании по нескольким противникам бонус к урону рассчитывается отдельно для каждого из них, исходя из общего количества уровней эффектов периодического урона на каждой цели."},{"level":3,"kind":"resonance","name":"Алый пир","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень навыков «Бушующий огонь», «Кошмарный вальс», «Кровавый рывок», «Перекрестье душ», «Адское фламенко» и «Грёзы о кровавом пире» на 1. Увеличивает множители урона «Грёз о кровавом пире» и «Адского фламенко» на 20 %."},{"level":6,"kind":"resonance","name":"Ядовитое пламя","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Увеличивает атаку Занку на 40 % в течение 20 сек. при нанесении урона. Эффект не складывается. При повторном срабатывании длительность обновляется.\n\nПосле победы над целью с эффектом «Ожог» Занку получает усиление на 60 сек. Во время действия этого усиления наложение Занку эффектов периодического урона мгновенно повышает количество уровней «Ожога» на цели до максимума. Победа над другой целью с эффектом «Ожог» обновляет длительность усиления."}]') WHERE character_id='zankou' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 03:56:00');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"ja-Play_Vo_Char_NPC022_chat_001","title":"Чат: поступь одиночки","description":"Теперь мне уже всё равно, где я…","language":"Японский","audioUrl":"/nte-meta/game-audio/9a3b74c1caf6a7254e30.ogg"},{"id":"ja-Play_Vo_Char_NPC022_Parry_001","title":"Парирование I","description":"Я отплачу сторицей!","language":"Японский","audioUrl":"/nte-meta/game-audio/3758133f2f9d78a80df9.ogg"},{"id":"ja-Play_Vo_Char_NPC022_ultraskill_UI_001","title":"Сверхспособность I","description":"Я чувствую твой страх.","language":"Японский","audioUrl":"/nte-meta/game-audio/bf4795f467a886661073.ogg"},{"id":"ja-Play_Vo_Char_NPC022_DodgeCombo_002","title":"Серия критических уклонений II","description":"Какая досада.","language":"Японский","audioUrl":"/nte-meta/game-audio/763110aaad9c71689207.ogg"},{"id":"ja-Play_Vo_Char_NPC022_skill_SE_001","title":"Навык перенаправления IV","description":"Увядай.","language":"Японский","audioUrl":"/nte-meta/game-audio/91f673f4e9de7b7f0bdb.ogg"},{"id":"ja-Play_Vo_Char_NPC022_hstruck_001","title":"Сильный урон I","description":"Какой настырный.","language":"Японский","audioUrl":"/nte-meta/game-audio/967f9eb9464fda8dbad2.ogg"},{"id":"ja-Play_Vo_Char_NPC022_TeammateDown_001","title":"Поражен товарищ по команде – Ноль","description":"Ты способен на большее…Ты способна на большее…","language":"Японский","audioUrl":"/nte-meta/game-audio/4b5640ca509000f5b18c.ogg"},{"id":"ja-Play_Vo_Char_NPC022_windfall_004","title":"Неожиданная добыча IV","description":"Доволен? Или мало? Довольна? Или мало?","language":"Японский","audioUrl":"/nte-meta/game-audio/a8cfceeb194a4e8aca63.ogg"},{"id":"ja-Play_Vo_Char_NPC022_gift_002","title":"Подарок получен II","description":"Я не понимаю тебя… Но спасибо за подарок.","language":"Японский","audioUrl":"/nte-meta/game-audio/d8ec47ff948986a2dd62.ogg"},{"id":"ja-Play_Vo_Char_NPC022_skill_SE_003","title":"Навык перенаправления VI","description":"Умри!","language":"Японский","audioUrl":"/nte-meta/game-audio/ea37ab199f22f5128de1.ogg"},{"id":"ja-Play_Vo_Char_NPC022_about_003","title":"О Хотори","description":"Не думала, что в захудалой антикварной лавке прячется сама Ведьма времени… Теперь понятно, почему лучшая убийца из «Алого символа» так размякла. Эта ведьма, должно быть, просто нечто… Но не переживай: твоя драгоценная хозяйка меня не интересует, и я не собираюсь мешать вам с моей сестрой играть в дочки-матери.","language":"Японский","audioUrl":"/nte-meta/game-audio/7cd83616163a35a96476.ogg"},{"id":"ja-Play_Vo_Char_NPC022_vexation_001","title":"Проблемы","description":"…Это в прошлом. Теперь это неважно.","language":"Японский","audioUrl":"/nte-meta/game-audio/9f230db55df1faf495c6.ogg"},{"id":"ja-Play_Vo_Char_NPC022_hstruck_002","title":"Сильный урон II","description":"…Хочешь умереть?","language":"Японский","audioUrl":"/nte-meta/game-audio/867218e2b63b6b087c98.ogg"},{"id":"ja-Play_Vo_Char_NPC022_struck_001","title":"Урон I","description":"Пустяки…","language":"Японский","audioUrl":"/nte-meta/game-audio/63ee89587538587e8cbe.ogg"},{"id":"ja-Play_Vo_Char_NPC022_weather_003","title":"Холодно","description":"Подойди. Загляни мне в глаза. Тебе больше не будет холодно…","language":"Японский","audioUrl":"/nte-meta/game-audio/7e3f3dcf1570f2996006.ogg"},{"id":"ja-Play_Vo_Char_NPC022_windfall_005","title":"Неожиданная добыча V","description":"Это твоё.","language":"Японский","audioUrl":"/nte-meta/game-audio/28711b3a2d4997662fb0.ogg"},{"id":"ja-Play_Vo_Char_NPC022_QTE_001","title":"Атака на входе I","description":"Я ждала!","language":"Японский","audioUrl":"/nte-meta/game-audio/040c2075b3ee991de828.ogg"},{"id":"ja-Play_Vo_Char_NPC022_ug_003","title":"Вознесение персонажа III","description":"Ты принял опасное решение, и я с тобой до конца.Ты приняла опасное решение, и я с тобой до конца.","language":"Японский","audioUrl":"/nte-meta/game-audio/db514adf4bf6398ad876.ogg"},{"id":"ja-Play_Vo_Char_NPC022_anomaly_004","title":"Нуллификация II","description":"Кто следующий?","language":"Японский","audioUrl":"/nte-meta/game-audio/9ef4e71e1fc55c09b8df.ogg"},{"id":"ja-Play_Vo_Char_NPC022_windfall_003","title":"Неожиданная добыча III","description":"Всё твоё.","language":"Японский","audioUrl":"/nte-meta/game-audio/bfba3e7ac393fb00c4f1.ogg"},{"id":"ja-Play_Vo_Char_NPC022_hp_002","title":"Низкий уровень здоровья II","description":"Шутки кончились.","language":"Японский","audioUrl":"/nte-meta/game-audio/86ef3f2a2bdc93ab1326.ogg"},{"id":"ja-Play_Vo_Char_NPC022_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Проблемы?","language":"Японский","audioUrl":"/nte-meta/game-audio/357c7963e8c6ba28a8e6.ogg"},{"id":"ja-Play_Vo_Char_NPC022_weather_001","title":"Солнечно","description":"В такую погоду цветы будут расти как надо.","language":"Японский","audioUrl":"/nte-meta/game-audio/6d0370c1f5f25b9fe107.ogg"},{"id":"ja-Play_Vo_Char_NPC022_skill02_SE_002","title":"Навык перенаправления XI","description":"Ни формы, ни тени.","language":"Японский","audioUrl":"/nte-meta/game-audio/ac45f23705a99f4735e3.ogg"},{"id":"ja-Play_Vo_Char_NPC022_hp_003","title":"Низкий уровень здоровья III","description":"Танцую на лезвии…","language":"Японский","audioUrl":"/nte-meta/game-audio/e9a3735d0d67984bdbef.ogg"},{"id":"ja-Play_Vo_Char_NPC022_skill02_001","title":"Навык перенаправления VII","description":"Мерещится?","language":"Японский","audioUrl":"/nte-meta/game-audio/c5d3d444b9615fc3992f.ogg"},{"id":"ja-Play_Vo_Char_NPC022_kill_002","title":"Убийство II","description":"Минус один.","language":"Японский","audioUrl":"/nte-meta/game-audio/64fce1f0e0747d7bc8de.ogg"},{"id":"ja-Play_Vo_Char_NPC022_about_006","title":"Об «Алом символе»","description":"Когда я состояла в «Алом символе», Инанна отбирала детей с потенциалом и прогоняла их через «испытания» — по сути пытки. Выживали считаные единицы. Тем немногим, кому это удалось, она поручала важные задания и давала цветочные имена… например, Даффодил, что значит «нарцисс», и «Красный паслён». Эти два имени когда-то вселяли ужас. Ах да, у Пуансетт тоже было цветочное имя — «Пуансеттия». Но она, казалось, не выдержит испытаний. Полагаю, она выбралась благодаря паре хитрых трюков.","language":"Японский","audioUrl":"/nte-meta/game-audio/5fb36e19de0888a46f2b.ogg"},{"id":"ja-Play_Vo_Char_NPC022_meet_001","title":"Первая встреча","description":"Я — скелет в твоём шкафу, я — твоя иллюзия, я — твой кошмарный сон… Обними меня — и утонешь.","language":"Японский","audioUrl":"/nte-meta/game-audio/247f2ec418e8f111534c.ogg"},{"id":"ja-Play_Vo_Char_NPC022_about_004","title":"О Пуансетт","description":"Пойнти занятная. Эмоции читать не умеет, но всегда подстраивалась под мамино переменчивое настроение. Неудивительно, что мама держала её при себе. Она меня боялась. Иногда я нарочно её пугала — просто чтобы посмотреть, как на её лице появляется заискивающая улыбочка, а в маленькой головке — паника и судорожные попытки сообразить, что ответить, как у крошечной мышки, несущейся по лабиринту… По плану Инанны она должна была умереть от твоей руки, но ты её спас. Не сомневаюсь, она верит в то, что обязана тебе жизнью.Пойнти занятная. Эмоции читать не умеет, но всегда подстраивалась под мамино переменчивое настроение. Неудивительно, что мама держала её при себе. Она меня боялась. Иногда я нарочно её пугала — просто чтобы посмотреть, как на её лице появляется заискивающая улыбочка, а в маленькой головке — паника и судорожные попытки сообразить, что ответить, как у крошечной мышки, несущейся по лабиринту… По плану Инанны она должна была умереть от твоей руки, но ты её спасла. Не сомневаюсь, он","language":"Японский","audioUrl":"/nte-meta/game-audio/7702a24ab7638f124498.ogg"},{"id":"ja-Play_Vo_Char_NPC022_deploy_001","title":"Отправка I","description":"Хе, мысли читаешь.","language":"Японский","audioUrl":"/nte-meta/game-audio/9ffdb09a0b0b377f59de.ogg"},{"id":"ja-Play_Vo_Char_NPC022_windfall_002","title":"Неожиданная добыча II","description":"Вот, держи. Мне это ни к чему.","language":"Японский","audioUrl":"/nte-meta/game-audio/ce71cc0ff350b63a5118.ogg"},{"id":"ja-Play_Vo_Char_NPC022_fh_001","title":"Исцеление I","description":"Отлично.","language":"Японский","audioUrl":"/nte-meta/game-audio/7210c5b78edbc09baa6e.ogg"},{"id":"ja-Play_Vo_Char_NPC022_ultraskill_HJ_UI_002","title":"Сверхспособность VIII","description":"Время веселья. Потанцуем!","language":"Японский","audioUrl":"/nte-meta/game-audio/6b936bb6d39bc278e4d2.ogg"},{"id":"ja-Play_Vo_Char_NPC022_ultraskill_SE_UI_002","title":"Сверхспособность V","description":"Обрати их в пепел!","language":"Японский","audioUrl":"/nte-meta/game-audio/ed6a53557b355ba78d6d.ogg"},{"id":"ja-Play_Vo_Char_NPC022_skill02_SE_003","title":"Навык перенаправления XII","description":"Лишь пустая мечта.","language":"Японский","audioUrl":"/nte-meta/game-audio/5d4463c2682f6384e64a.ogg"},{"id":"ja-Play_Vo_Char_NPC022_Switch_002","title":"Переключение II","description":"Отойди. Я сама разберусь.","language":"Японский","audioUrl":"/nte-meta/game-audio/8460dde8cb7eb364e942.ogg"},{"id":"ja-Play_Vo_Char_NPC022_ug_002","title":"Вознесение персонажа II","description":"Оно жаждет большего и никак не насытится…","language":"Японский","audioUrl":"/nte-meta/game-audio/192c5492dcdaa3c479d7.ogg"},{"id":"ja-Play_Vo_Char_NPC022_Switch_001","title":"Переключение I","description":"Скукота…","language":"Японский","audioUrl":"/nte-meta/game-audio/38e2628b0a9ae95a19ef.ogg"},{"id":"ja-Play_Vo_Char_NPC022_greet_002","title":"Дневное приветствие","description":"Как уютно… Если хочешь, вздремни. Не буду тебе мешать.","language":"Японский","audioUrl":"/nte-meta/game-audio/d45f871585595affa914.ogg"},{"id":"ja-Play_Vo_Char_NPC022_talk_002","title":"Тема: старая история","description":"Мир — это не только солнце и радуга. В тёмных закоулках многие зарабатывают клинком: охотятся на слабых и без конца режут друг друга из-за сокровищ, аномалий или какого-нибудь эспера. Что до Инанны… до того как высокомерие затуманило её разум, она была проницательной, расчётливой и честолюбивой. Она принесла «Алому символу» богатство и дурную славу. Мы с Даффодил разбирались с её врагами… которые не слишком отличались от неё.","language":"Японский","audioUrl":"/nte-meta/game-audio/37c7c3c81de84014c388.ogg"},{"id":"ja-Play_Vo_Char_NPC022_ultraskill_UI_002","title":"Сверхспособность II","description":"Дарую тебе благословение.","language":"Японский","audioUrl":"/nte-meta/game-audio/fdabe90bfd1dc7bd23bd.ogg"},{"id":"ja-Play_Vo_Char_NPC022_greet_004","title":"Спокойной ночи","description":"Лишь глубокой ночью люди показывают своё истинное «я»… Оценщик, не хочешь поговорить по душам? Лишь глубокой ночью люди показывают своё истинное «я»… Оценщица, не хочешь поговорить по душам?","language":"Японский","audioUrl":"/nte-meta/game-audio/4176e4366ff441df944c.ogg"},{"id":"ja-Play_Vo_Char_NPC022_QTE_003","title":"Атака на входе III","description":"С дороги.","language":"Японский","audioUrl":"/nte-meta/game-audio/e8209542e8e8fc5a6a18.ogg"},{"id":"ja-Play_Vo_Char_NPC022_Parry_002","title":"Парирование II","description":"Вижу тебя насквозь!","language":"Японский","audioUrl":"/nte-meta/game-audio/c6e03df7462abfade5f9.ogg"},{"id":"ja-Play_Vo_Char_NPC022_containment_002","title":"Сдерживание II","description":"Сдерживание завершено. Что дальше?","language":"Японский","audioUrl":"/nte-meta/game-audio/384b1b3a6a6b13a1b58d.ogg"},{"id":"ja-Play_Vo_Char_NPC022_skill02_003","title":"Навык перенаправления IX","description":"Ты витаешь в облаках!","language":"Японский","audioUrl":"/nte-meta/game-audio/bdbe539e0bb501ae4559.ogg"},{"id":"ja-Play_Vo_Char_NPC022_ultraskill_SE_UI_003","title":"Сверхспособность VI","description":"Жалкие попытки веселят меня!","language":"Японский","audioUrl":"/nte-meta/game-audio/aded95b0bea9aa22c53b.ogg"},{"id":"ja-Play_Vo_Char_NPC022_windfall_001","title":"Неожиданная добыча I","description":"Неплохо.","language":"Японский","audioUrl":"/nte-meta/game-audio/fc7fcfd62015bb4e78ce.ogg"},{"id":"ja-Play_Vo_Char_NPC022_Fly_001","title":"Планирование I","description":"Куда мы летим?","language":"Японский","audioUrl":"/nte-meta/game-audio/4a55810579d8c254e2c0.ogg"},{"id":"ja-Play_Vo_Char_NPC022_gift_003","title":"Подарок получен III","description":"Вместо подарка лучше расскажи мне секрет. Вот чего я хочу.","language":"Японский","audioUrl":"/nte-meta/game-audio/3c3e4096b024ee9f1087.ogg"},{"id":"ja-Play_Vo_Char_NPC022_greet_001","title":"Утреннее приветствие","description":"Доброе утро, оценщик… Что, никак не привыкнешь? Доброе утро, оценщица… Что, никак не привыкнешь?","language":"Японский","audioUrl":"/nte-meta/game-audio/d2fb6a028e8619f1e093.ogg"},{"id":"ja-Play_Vo_Char_NPC022_weather_002","title":"Дождливо","description":"Никакому дождю не смыть старые пятна крови.","language":"Японский","audioUrl":"/nte-meta/game-audio/de4372284c22b2cd64cd.ogg"},{"id":"ja-Play_Vo_Char_NPC022_weather_004","title":"Жарко","description":"Ну и жара…","language":"Японский","audioUrl":"/nte-meta/game-audio/36b56c4531c100f82145.ogg"},{"id":"ja-Play_Vo_Char_NPC022_skill_SE_002","title":"Навык перенаправления V","description":"Сгинь.","language":"Японский","audioUrl":"/nte-meta/game-audio/e5485ccdfab7e47f676f.ogg"},{"id":"ja-Play_Vo_Char_NPC022_talk_001","title":"Тема: семья","description":"Когда мама была в дурном настроении, она проводила «тренировки», чтобы наказывать нас физически. А потом, наказав, начинала лить фальшивые слёзы и приговаривать: «Мама тебя прощает». Так она нас и растила. Нас было четверо… Но Даффодил была из железа. Хоть кнутом хлещи — она и глазом не моргнёт. Маму я видела насквозь, так что меня это, конечно, не трогало. А Пуансетт… её фальшивые слёзы были убедительнее, чем у Инанны. Наблюдать, как эти двое разыгрывают спектакль «мать и дочь», было одним из моих любимых способов убить время.","language":"Японский","audioUrl":"/nte-meta/game-audio/5361d6d93fc004102012.ogg"},{"id":"ja-Play_Vo_Char_NPC022_ug_001","title":"Вознесение персонажа I","description":"Такой азарт… Давненько не ощущала ничего подобного.","language":"Японский","audioUrl":"/nte-meta/game-audio/b84c09591ae98c4747f4.ogg"},{"id":"ja-Play_Vo_Char_NPC022_ultraskill_HJ_UI_003","title":"Сверхспособность IX","description":"Ослепительный алый фантом…","language":"Японский","audioUrl":"/nte-meta/game-audio/e888496978ddc6f4cd5b.ogg"},{"id":"ja-Play_Vo_Char_NPC022_skill_003","title":"Навык перенаправления III","description":"Словно роса, словно молния.","language":"Японский","audioUrl":"/nte-meta/game-audio/07c7c192eacb7f473642.ogg"},{"id":"ja-Play_Vo_Char_NPC022_hobby_001","title":"Хобби","description":"Что ж. Позволь мне потешить твоё любопытство. Мои хобби — чай, вино и флористика. Немного этим увлекаюсь. Но если выбирать любимое, то это охота. Обожаю играть с добычей, смотреть, как она тешит себя иллюзией безопасности, мечется и прячется по углам до тех пор, пока не поймёт, что бежать некуда, и не лишится последней крупицы воли к жизни… Хочешь попробовать? Поохотишься со мной… или, может, станешь моей добычей?","language":"Японский","audioUrl":"/nte-meta/game-audio/70bbee76bf91a76d2355.ogg"},{"id":"ja-Play_Vo_Char_NPC022_QTE_002","title":"Атака на входе II","description":"Слабовато.","language":"Японский","audioUrl":"/nte-meta/game-audio/b841a9b06264ae034420.ogg"},{"id":"ja-Play_Vo_Char_NPC022_gift_004","title":"Подарок получен IV","description":"Если понадобится решить проблему, просто скажи.","language":"Японский","audioUrl":"/nte-meta/game-audio/470b9071539674233a36.ogg"},{"id":"ja-Play_Vo_Char_NPC022_SSC_DFDE_001","title":"Особое переключение — Даффодил","description":"Прямо как в старые добрые времена, сестра.","language":"Японский","audioUrl":"/nte-meta/game-audio/46812fbaa2068f145399.ogg"},{"id":"ja-Play_Vo_Char_NPC022_TeammateDown_002","title":"Поражен товарищ по команде – Даффодил","description":"Сестра, похоже, ты забросила тренировки.","language":"Японский","audioUrl":"/nte-meta/game-audio/443441aa782887b7959b.ogg"},{"id":"ja-Play_Vo_Char_NPC022_DodgeCombo_001","title":"Серия критических уклонений I","description":"Слишком медленно!","language":"Японский","audioUrl":"/nte-meta/game-audio/e6d082330207cef88bf8.ogg"},{"id":"ja-Play_Vo_Char_NPC022_about_001","title":"О Даффодил","description":"У неё чистая душа — как ровное белое пламя, которое не гаснет даже среди крови и насилия. Много лет мы были напарницами, и я не чувствовала в ней ничего дурного. Но однажды, склонившись над врагом, умолявшим о пощаде, она замешкалась. В ту ночь девушка, которая никогда не делилась своими чувствами, сама пришла ко мне поговорить. Я решила, что она слабеет, и, хотя её перемена меня тревожила, какая-то часть меня хотела стать для неё опорой… А потом случилось предательство. Я никогда не забуду ту бурю, выражение её лица, когда она бежала, и цвет, горевший в её душе… Цвет, которого я никогда не видела прежде.","language":"Японский","audioUrl":"/nte-meta/game-audio/f331d30bc739c5d54ea2.ogg"},{"id":"ja-Play_Vo_Char_NPC022_struck_002","title":"Урон II","description":"Даже не больно.","language":"Японский","audioUrl":"/nte-meta/game-audio/ebd751e26aaeca275e54.ogg"},{"id":"ja-Play_Vo_Char_NPC022_ultraskill_UI_003","title":"Сверхспособность III","description":"Потанцуем?","language":"Японский","audioUrl":"/nte-meta/game-audio/92c749d1ad55642f3da9.ogg"},{"id":"ja-Play_Vo_Char_NPC022_anomaly_003","title":"Нуллификация I","description":"Мне привычнее цели, похожие на людей.","language":"Японский","audioUrl":"/nte-meta/game-audio/54fd077e6dfaa0cdab82.ogg"},{"id":"ja-Play_Vo_Char_NPC022_skill02_002","title":"Навык перенаправления VIII","description":"Не моргай!","language":"Японский","audioUrl":"/nte-meta/game-audio/7d3d6a0aeb8a56e41e3a.ogg"},{"id":"ja-Play_Vo_Char_NPC022_TeammateDown_003","title":"Поражен товарищ по команде – Хотори","description":"Даже у ведьмы заканчивается время?","language":"Японский","audioUrl":"/nte-meta/game-audio/b5748a479aa7a549fc1e.ogg"},{"id":"ja-Play_Vo_Char_NPC022_self_001","title":"Обо мне: способности эспера","description":"Это «Око наваждения». Оно умеет считывать эмоции, путать разум и разъедать рассудок, делая человека импульсивным и уязвимым, затягивая в водоворот чувств. С небольшой подготовкой оно может создавать иллюзии и даже ловить в них добычу. Что до цены… каждый раз, когда я использую способность эспера, око становится беспокойным, оно жаждет чужих негативных эмоций. Ах да, если слишком долго смотреть мне в глаза, твой разум может истощиться… и ты станешь игрушкой, которой я смогу вертеть как хочу. Ну же, не отводи взгляд. Это просто шутка.","language":"Японский","audioUrl":"/nte-meta/game-audio/e3471e00350fe97d1997.ogg"},{"id":"ja-Play_Vo_Char_NPC022_ultraskill_HJ_UI_001","title":"Сверхспособность VII","description":"Кошмар, утонувший в вечности…","language":"Японский","audioUrl":"/nte-meta/game-audio/aeaad875613b698c95bf.ogg"},{"id":"ja-Play_Vo_Char_NPC022_skill02_SE_001","title":"Навык перенаправления X","description":"Дым и миражи.","language":"Японский","audioUrl":"/nte-meta/game-audio/4b2d571ecd0c66d18ff4.ogg"},{"id":"ja-Play_Vo_Char_NPC022_SSC_XUN_001","title":"Особое переключение — Хотори","description":"Неплохой клинок.","language":"Японский","audioUrl":"/nte-meta/game-audio/028d16cddc8f0fa15e4f.ogg"},{"id":"ja-Play_Vo_Char_NPC022_skill_001","title":"Навык перенаправления I","description":"Вмиг…","language":"Японский","audioUrl":"/nte-meta/game-audio/682dcdb6eefbef2cb4e5.ogg"},{"id":"ja-Play_Vo_Char_NPC022_kill_001","title":"Убийство I","description":"(*Смеётся*)","language":"Японский","audioUrl":"/nte-meta/game-audio/d7b1d5d0f1927e5a93c0.ogg"},{"id":"ja-Play_Vo_Char_NPC022_self_002","title":"Обо мне: цветовосприятие","description":"В ранних воспоминаниях мир был чёрно-белым. Когда пробудилась моя сила, пустоту заполнил третий цвет. Он прятался под серыми оболочками. То ослепительный, то мутный, но всегда яркий, всегда тёплый… Ты опять хмуришься. Как думаешь, я когда-нибудь увижу, какой цвет скрывается за твоим безупречным лицом, оценщик?..В ранних воспоминаниях мир был чёрно-белым. Когда пробудилась моя сила, пустоту заполнил третий цвет. Он прятался под серыми оболочками. То ослепительный, то мутный, но всегда яркий, всегда тёплый… Ты опять хмуришься. Как думаешь, я когда-нибудь увижу, какой цвет скрывается за твоим безупречным лицом, оценщица?..","language":"Японский","audioUrl":"/nte-meta/game-audio/da539d3f4fdf8ae3a60b.ogg"},{"id":"ja-Play_Vo_Char_NPC022_windfall_006","title":"Неожиданная добыча VI","description":"Всё цело.","language":"Японский","audioUrl":"/nte-meta/game-audio/c9a505b7d88722f481b7.ogg"},{"id":"ja-Play_Vo_Char_NPC022_dead_003","title":"Потеря сознания III","description":"Я уйду первой, сестра…","language":"Японский","audioUrl":"/nte-meta/game-audio/5690320a1a034638cfc9.ogg"},{"id":"ja-Play_Vo_Char_NPC022_self_003","title":"Обо мне: наблюдение","description":"Иногда я притворяюсь кем-то другим и скрываюсь в толпе, наблюдая за городом… Он такой открытый, такой свободный, почти каждый, кто тут оседает, убеждает себя, что нашёл своё место под солнцем. Некоторые и вовсе отказываются от собственной природы, забывают её — лишь бы сохранить ощущение дома… Оценщик, ты тоже из их числа? Иногда я притворяюсь кем-то другим и скрываюсь в толпе, наблюдая за городом… Он такой открытый, такой свободный, почти каждый, кто тут оседает, убеждает себя, что нашёл своё место под солнцем. Некоторые и вовсе отказываются от собственной природы, забывают её — лишь бы сохранить ощущение дома… Оценщица, ты тоже из их числа?","language":"Японский","audioUrl":"/nte-meta/game-audio/cb975d06761942f487da.ogg"},{"id":"ja-Play_Vo_Char_NPC022_skill_002","title":"Навык перенаправления II","description":"Потанцуем.","language":"Японский","audioUrl":"/nte-meta/game-audio/471417127ea8286ce89d.ogg"},{"id":"ja-Play_Vo_Char_NPC022_talk_003","title":"Тема: оружие","description":"Это Ткач судеб. Ещё одна вещь из маминой коллекции. Он создаёт живые, будто тканевые драпировки. Я выбрала его потому, что среди кучи тусклых клинков он сразу бросился мне в глаза. В те времена Даффодил обожала ухаживать за оружием. Когда она впервые увидела мой меч, то решила, что лезвие в крови, и хотела научить меня полировать и чистить его… Но нет, клинок с самого начала был кроваво-красным. Сколько ни оттирай, цвет не изменится.","language":"Японский","audioUrl":"/nte-meta/game-audio/54e4e4f6c2f01e070ac1.ogg"},{"id":"ja-Play_Vo_Char_NPC022_hp_001","title":"Низкий уровень здоровья I","description":"Плохо дело.","language":"Японский","audioUrl":"/nte-meta/game-audio/705ffd8be82b32299683.ogg"},{"id":"ja-Play_Vo_Char_NPC022_ultraskill_SE_UI_001","title":"Сверхспособность IV","description":"Цвети для меня! Увядай для меня!","language":"Японский","audioUrl":"/nte-meta/game-audio/1b2b566047414ff8f569.ogg"},{"id":"ja-Play_Vo_Char_NPC022_dead_001","title":"Потеря сознания I","description":"Я… никогда…","language":"Японский","audioUrl":"/nte-meta/game-audio/a79062dc6dc3c94bd3f8.ogg"},{"id":"ja-Play_Vo_Char_NPC022_dead_002","title":"Потеря сознания II","description":"Я просчиталась…","language":"Японский","audioUrl":"/nte-meta/game-audio/1bbb5806eb4b95e8158e.ogg"},{"id":"ja-Play_Vo_Char_NPC022_gift_001","title":"Подарок получен I","description":"Хм… Оценщик, что ты затеваешь? Хм… Оценщица, что ты затеваешь?","language":"Японский","audioUrl":"/nte-meta/game-audio/9a5c3ea3a9f3cf33efa1.ogg"},{"id":"ja-Play_Vo_Char_NPC022_about_002","title":"Об Инанне","description":"Инанна взяла к себе многих детей, но никогда о нас не заботилась. Для неё мы были инструментами, ценными предметами или разменной монетой — смотря что ей было нужно. Я? Я была инструментом для расчистки пути, тем, кому она доверяла больше других… Её высокомерие смешило меня, но за все эти годы она дала мне место, которое я могла назвать своим, и позволила мне быть собой и обрести семью… Я до сих пор скучаю по ней — особенно по тому, как она выглядела, испуская последний вздох.","language":"Японский","audioUrl":"/nte-meta/game-audio/354fa7442ad4f09b4480.ogg"},{"id":"ja-Play_Vo_Char_NPC022_chat_002","title":"Чат: дурная слава","description":"Если наткнёшься на важных шишек, скажи что-нибудь про «Красный паслён». Увидишь, как у них глаза забегают.","language":"Японский","audioUrl":"/nte-meta/game-audio/ff43cee28cca9abafe1a.ogg"},{"id":"ja-Play_Vo_Char_NPC022_Fly_002","title":"Планирование II","description":"Дрейфую на ветру…","language":"Японский","audioUrl":"/nte-meta/game-audio/64b510afddb8e075bea8.ogg"},{"id":"ja-Play_Vo_Char_NPC022_greet_003","title":"Вечернее приветствие","description":"Уже поздно… Ты отлично проводишь время.","language":"Японский","audioUrl":"/nte-meta/game-audio/131be3f4101dcb586740.ogg"},{"id":"ja-Play_Vo_Char_NPC022_Switch_003","title":"Переключение III","description":"Ещё немного, и я бы начала волноваться.","language":"Японский","audioUrl":"/nte-meta/game-audio/ad1d1cfcdff898d76874.ogg"},{"id":"ja-Play_Vo_Char_NPC022_containment_001","title":"Сдерживание I","description":"Теперь что будем делать?","language":"Японский","audioUrl":"/nte-meta/game-audio/fb3f96ef028856fcf034.ogg"},{"id":"ja-Play_Vo_Char_NPC022_chat_003","title":"Чат: наблюдения","description":"На аукционах мамы я повстречала немало почтенных, безупречно воспитанных людей. Я видела их потаённые желания. Они жаждут богатства, грезят о бессмертии, стремятся к власти или мечтают увидеть чудо… Но всё это — пустые иллюзии и затёртые клише. А вот когда им некуда идти и впереди лишь тупик, возникает настоящее, неприкрытое отчаяние… вот это уже интересно.","language":"Японский","audioUrl":"/nte-meta/game-audio/75427e34e2f1f64a917c.ogg"},{"id":"ja-Play_Vo_Char_NPC022_fh_002","title":"Исцеление II","description":"Хорошая работа.","language":"Японский","audioUrl":"/nte-meta/game-audio/2f1f88cbbe0e1d20ee18.ogg"},{"id":"ja-Play_Vo_Char_NPC022_about_005","title":"О Ноле","description":"У тебя столько секретов, твои эмоции восхитительны. И всё же мне не дано разглядеть твою душу. Она как тлеющий огонь — пламени не видно, но даёт сильный жар… Ты исключение даже среди эсперов. А значит, тебе не обязательно подчиняться правилам Бюро. Они никогда не умели принимать то, что не могут контролировать. Однажды они начнут тебя бояться, сторониться, попытаются тебя ограничить… Но я всегда буду готова снять с тебя оковы и принять всё, что в тебе есть: твою истинную природу, всё, что ты любишь и ненавидишь, даже гнев, что сейчас пылает в тебе… я обожаю всё это.","language":"Японский","audioUrl":"/nte-meta/game-audio/e08c8a66e699ae17e6ff.ogg"},{"id":"ja-Play_Vo_Char_NPC022_deploy_002","title":"Отправка II","description":"Кто цель?","language":"Японский","audioUrl":"/nte-meta/game-audio/269c2e8e40f2cdc433d6.ogg"}]') WHERE character_id='zankou' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 03:56:00');

UPDATE character_profiles SET abilities_json=json('[{"id":"GA_Zankou_Skill","name":"Кровавый рывок","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/43c3dba4ba01a7adb840.webp","description":"Навык перенаправления: Кровавый рывок\nПосле успешного применения «Кровавого рывка» в «Форме реальности» Занку переходит в «Иллюзорную форму». На некоторое время открывает усиленный «Кровавый рывок» после 4-го или 5-го удара «Бушующего огня», а также после применения «Мерцающей тени» или «Шага сквозь пустоту». Накладывает эффект «Душевная мука» на поражённые цели и активирует «Смятение», значительно снижая показатель разрушения врагов в большой области. При переходе в «Иллюзорную форму» с помощью «Кровавого рывка» задерживает снятие эффекта «Охота» «Формы реальности». Не позволяет переключиться между формами, если навык прерван до завершения.\n\nНавык перенаправления: Перекрестье душ\nЗанку переходит в «Форму реальности» после успешного применения «Перекрестья душ» в «Иллюзорной форме». Позволяет активировать усиленное «Перекрестье душ» незадолго до окончания действия «Иллюзорной формы». Занку наносит огромный урон врагам в большой области, накладывает эффект «Душевная мука» на поражённые цели и вызывает «Забвение», активируя «Грёзы о кровавом пире».\n\n«Иллюзорная форма» действует в течение определённого времени. Завершает «Иллюзорную форму» и возвращает Занку в «Форму реальности» при успешном применении «Перекрестья душ» или «Грёз о кровавом пире», по истечении времени действия эффекта или когда Занку покидает поле боя. Задерживает снятие эффекта «Наваждение» «Иллюзорной формы» при переключении в «Форму реальности» с помощью «Перекрестья душ». Весь урон, наносимый базовой и усиленной версиями «Перекрестья душ», считается уроном последующей атаки. Препятствует смене формы, если применение навыка было прервано до его завершения.\n\nТебе ещё рано просыпаться — кошмар только начинается.","attributes":[{"id":"parameter-0","label":"Множитель урона «Кровавого рывка»","value":"1: 22.5 % *4 + 60 % · 2: 24.3 % *4 + 64.8 % · 3: 26.2 % *4 + 70 % · 4: 28.3 % *4 + 75.6 % · 5: 30.6 % *4 + 81.6 % · 6: 33.1 % *4 + 88.2 % · 7: 35.7 % *4 + 95.2 % · 8: 38.6 % *4 + 102.8 % · 9: 41.6 % *4 + 111.1 % · 10: 45 % *4 + 119.9 % · 11: 48.6 % *4 + 129.5 % · 12: 52.5 % *4 + 139.9 % · 13: 56.7 % *4 + 151.1 %"},{"id":"parameter-1","label":"Усил. «Кровавый рывок»: множитель урона","value":"1: 26.3 % *4 + 70 % · 2: 28.4 % *4 + 75.6 % · 3: 30.7 % *4 + 81.6 % · 4: 33.1 % *4 + 88.2 % · 5: 35.8 % *4 + 95.2 % · 6: 38.6 % *4 + 102.9 % · 7: 41.7 % *4 + 111.1 % · 8: 45.1 % *4 + 120 % · 9: 48.7 % *4 + 129.6 % · 10: 52.6 % *4 + 139.9 % · 11: 56.8 % *4 + 151.1 % · 12: 61.3 % *4 + 163.2 % · 13: 66.2 % *4 + 176.3 %"},{"id":"parameter-2","label":"Множитель урона «Перекрестья душ»","value":"1: 13.2 % *2 + 26.8 % *4 + 166.5 % · 2: 14.3 % *2 + 28.9 % *4 + 179.8 % · 3: 15.4 % *2 + 31.3 % *4 + 194.2 % · 4: 16.6 % *2 + 33.8 % *4 + 209.7 % · 5: 18 % *2 + 36.5 % *4 + 226.5 % · 6: 19.4 % *2 + 39.4 % *4 + 244.6 % · 7: 20.9 % *2 + 42.5 % *4 + 264.2 % · 8: 22.6 % *2 + 45.9 % *4 + 285.4 % · 9: 24.4 % *2 + 49.6 % *4 + 308.2 % · 10: 26.4 % *2 + 53.6 % *4 + 332.8 % · 11: 28.5 % *2 + 57.9 % *4 + 359.5 % · 12: 30.8 % *2 + 62.5 % *4 + 388.2 % · 13: 33.2 % *2 + 67.5 % *4 + 419.3 %"},{"id":"parameter-3","label":"Усил. «Перекрестье душ»: множитель урона","value":"1: 19.8 % *2 + 40.1 % *4 + 249.8 % · 2: 21.4 % *2 + 43.3 % *4 + 269.8 % · 3: 23.1 % *2 + 46.8 % *4 + 291.4 % · 4: 24.9 % *2 + 50.5 % *4 + 314.7 % · 5: 26.9 % *2 + 54.6 % *4 + 339.9 % · 6: 29.1 % *2 + 58.9 % *4 + 367 % · 7: 31.4 % *2 + 63.6 % *4 + 396.4 % · 8: 33.9 % *2 + 68.7 % *4 + 428.1 % · 9: 36.6 % *2 + 74.2 % *4 + 462.4 % · 10: 39.6 % *2 + 80.2 % *4 + 499.4 % · 11: 42.7 % *2 + 86.6 % *4 + 539.3 % · 12: 46.2 % *2 + 93.5 % *4 + 582.4 % · 13: 49.9 % *2 + 101 % *4 + 629 %"}]},{"id":"GA_Zankou_Passive1","name":"Тихий закат","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/cac6034338176f50df06.webp","description":"Усиление ожога: эффект может складываться до 3 раз. Каждый раз, когда союзники накладывают эффект периодического урона на цель с эффектом «Ожог», Занку накладывает 1 уровень «Ожога» за каждый наложенный эффект периодического урона. Этот эффект заменяет урон, тип и длительность уже существующего на цели «Ожога» параметрами нового наложенного эффекта. «Ожог», наложенный этим эффектом, не может повторно запустить этот эффект.\n\nБесчисленные огни сливаются в безмолвное солнце, выжигая в каждом взоре один и тот же цвет.","attributes":[]},{"id":"GA_Zankou_InvisibleSkill","name":"Потеря фокуса","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/d541eccd7e80de97435c.webp","description":"«Незрима и недосягаема».\n\nИспользование особого навыка «Потеря фокуса» вне боя переводит Занку в состояние «Невидимость» на 20 сек. В состоянии «Невидимость» скорость движения увеличивается на 50 %, а враги теряют способность обнаружить Занку.\n\nВсё началось с мимолётного взгляда. А затем мир вокруг медленно потерял очертания.","attributes":[]},{"id":"GA_Zankou_Passive2","name":"Багровые грёзы","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/6f460f438c90cdb0d146.webp","description":"При вступлении в бой устанавливает значение энергии цикла Занку на 100. Перезарядка: 30 сек. Срабатывает только один раз за бой. Увеличивает интенсивность цикла Занку на 100, когда она находится в команде.\n\nРастворись в пьянящей багровой бездне её взгляда — и больше никогда не просыпайся.","attributes":[]},{"id":"GA_Zankou_QTE","name":"Разожжённое пламя","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/36f00d3f7b9afd974b25.webp","description":"Занку использует свой клинок для атаки, нанося 1 удар урона от чар.\n\nСтрах — лучшее топливо.","attributes":[{"id":"parameter-0","label":"Множитель урона «Разожжённого пламени»","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"}]},{"id":"GA_Zankou_Melee","name":"Бушующий огонь","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/f0ffbcd346506f17fac4.webp","description":"Базовая атака: Бушующий огонь\nВ «Форме реальности» Занку использует свой клинок и выполняет до 5 последовательных атак, нанося урон от чар. При 5-м ударе базовой атаки притягивает цели в радиусе действия. На время атаки получает усиление «Охота».\n\nБазовая атака: Кошмарный вальс\nВ «Иллюзорной форме» Занку взмахивает клинком, натягивая шёлк, и выполняет до 4 последовательных атак, нанося урон от чар и накладывая 1 уровень эффекта «Душевная мука» при попадании. При 3-м ударе базовой атаки она притягивает цели в радиусе действия. Каждая атака «Кошмарного вальса» распространяет до 4 эффектов периодического урона с цели на всех врагов в зоне поражения, включая саму цель. На время атаки Занку получает усиление «Наваждение». Урон от «Кошмарного вальса» считается уроном последующей атаки.\n\nБазовая атака: Мерцающая тень\nУдерживайте кнопку базовой атаки во время 1-го или 2-го удара «Бушующего огня» в «Форме реальности», чтобы активировать «Мерцающую тень», наносящую урон от чар.\n\nБазовая атака: Падение луны\nУдерживайте кнопку базовой атаки во время 1-го или 2-го удара «Кошмарного вальса» в «Иллюзорной форме», чтобы активировать «Падение луны», наносящее урон от чар. При попадании Занку накладывает 1 уровень эффекта «Душевная мука». Урон от «Падения луны» считается уроном последующей атаки.\n\nБазовая атака: Сломанные ветки\nНажмите кнопку базовой атаки в воздухе, чтобы выполнить атаку в падении. При приземлении Занку наносит 1 удар урона от чар по области. Урон увеличивается в зависимости от высоты падения; максимальное увеличение составляет 100 %.\n\nКритический контрудар: Шаг сквозь пустоту\nСрабатывает при нажатии кнопки базовой атаки после критического уклонения. Занку наносит урон от чар и снижает показатель разрушения.\n\nКошмар подступает ближе, и отчаяние сжигает изнутри.","attributes":[{"id":"parameter-0","label":"Множитель урона 1-го удара «Бушующего огня»","value":"1: 15.8 % + 27.4 % · 2: 17.1 % + 29.6 % · 3: 18.4 % + 32 % · 4: 19.9 % + 34.5 % · 5: 21.5 % + 37.3 % · 6: 23.2 % + 40.3 % · 7: 25.1 % + 43.5 % · 8: 27.1 % + 47 % · 9: 29.2 % + 50.7 % · 10: 31.6 % + 54.8 % · 11: 34.1 % + 59.2 % · 12: 36.8 % + 63.9 % · 13: 39.8 % + 69 %"},{"id":"parameter-1","label":"Множитель урона 2-го удара «Бушующего огня»","value":"1: 35.2 % · 2: 38 % · 3: 41.1 % · 4: 44.3 % · 5: 47.9 % · 6: 51.7 % · 7: 55.9 % · 8: 60.3 % · 9: 65.2 % · 10: 70.4 % · 11: 76 % · 12: 82.1 % · 13: 88.6 %"},{"id":"parameter-2","label":"Множитель урона 3-го удара «Бушующего огня»","value":"1: 57.8 % + 18.3 % + 35.3 % · 2: 62.4 % + 19.8 % + 38.1 % · 3: 67.4 % + 21.3 % + 41.2 % · 4: 72.8 % + 23.1 % + 44.5 % · 5: 78.6 % + 24.9 % + 48 % · 6: 84.9 % + 26.9 % + 51.9 % · 7: 91.7 % + 29 % + 56 % · 8: 99.1 % + 31.4 % + 60.5 % · 9: 107 % + 33.9 % + 65.3 % · 10: 115.5 % + 36.6 % + 70.6 % · 11: 124.8 % + 39.5 % + 76.2 % · 12: 134.8 % + 42.7 % + 82.3 % · 13: 145.6 % + 46.1 % + 88.9 %"},{"id":"parameter-3","label":"Множитель урона 4-го удара «Бушующего огня»","value":"1: 68.2 % + 24.7 % + 22.8 % + 52.2 % + 10.3 % · 2: 73.7 % + 26.7 % + 24.6 % + 56.4 % + 11.1 % · 3: 79.5 % + 28.8 % + 26.6 % + 60.9 % + 12 % · 4: 85.9 % + 31.1 % + 28.7 % + 65.8 % + 13 % · 5: 92.8 % + 33.6 % + 31 % + 71 % + 14 % · 6: 100.2 % + 36.3 % + 33.5 % + 76.7 % + 15.1 % · 7: 108.2 % + 39.2 % + 36.2 % + 82.8 % + 16.3 % · 8: 116.9 % + 42.3 % + 39.1 % + 89.5 % + 17.7 % · 9: 126.2 % + 45.7 % + 42.2 % + 96.6 % + 19.1 % · 10: 136.3 % + 49.4 % + 45.6 % + 104.3 % + 20.6 % · 11: 147.2 % + 53.3 % + 49.2 % + 112.7 % + 22.2 % · 12: 159 % + 57.6 % + 53.2 % + 121.7 % + 24 % · 13: 171.7 % + 62.2 % + 57.4 % + 131.4 % + 25.9 %"},{"id":"parameter-4","label":"Множитель урона 5-го удара «Бушующего огня»","value":"1: 36.4 % *2 + 12.6 % *2 + 96.5 % + 63.4 % · 2: 39.3 % *2 + 13.6 % *2 + 104.2 % + 68.5 % · 3: 42.5 % *2 + 14.7 % *2 + 112.6 % + 73.9 % · 4: 45.9 % *2 + 15.9 % *