UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Итерированная дилемма заключённого","iconUrl":"/nte-meta/game-assets/d116e099e66564db56cd.webp","description":"Восстанавливает 3 ед. Воображения в секунду, пока Ирой находится вне поля боя.\n\nУвеличивает скорость накопления Воображения на 30 % и полностью восполняет запас Воображения Ирой при вступлении в бой."},{"level":2,"kind":"awakening","name":"Стратегия: Око за око","iconUrl":"/nte-meta/game-assets/f69a867a2d2c939302f9.webp","description":"Когда союзник применяет навык, Ирой случайным образом призывает Морфея, Икела или Фантаса. Призванный ягнёнок совершает 1 совместную атаку и наносит урон в размере 200 % от показателя атаки Ирой. Восстанавливает всем членам команды ОЗ в размере 120 % от показателя атаки Ирой. Перезарядка: 5 сек."},{"level":3,"kind":"awakening","name":"Черта: готовность к сотрудничеству","iconUrl":"/nte-meta/game-assets/5dee31e299f4f440f8f7.webp","description":"Увеличивает эффективность лечения Ирой на 36 %."},{"level":4,"kind":"awakening","name":"Черта: мстительность","iconUrl":"/nte-meta/game-assets/eb4153d24a3b0cd281e5.webp","description":"Увеличивает множитель атаки ягнят, заменяющих союзников в состоянии Регрессии.\n\nМорфей:\n\nСладкие сны: увеличение — 30 % от базового множителя\n\nГлубокий сон: увеличение — 30 % от базового множителя\n\nИкел:\n\nНебольшой укол: увеличение — 30 % от базового множителя\n\nДвойная доза: увеличение — 30 % от базового множителя\n\nФантас:\n\nВремя колыбельной: увеличение — 30 % от базового множителя\n\nФальшь: увеличение — 30 % от базового множителя"},{"level":5,"kind":"awakening","name":"Черта: открытость","iconUrl":"/nte-meta/game-assets/7201bb3ccf3009e1f0d5.webp","description":"Дополнительный эффект «Симпатических нервов»: на 20 сек. увеличивает атаку всех членов команды на величину, равную 15 % базового показателя атаки Ирой."},{"level":6,"kind":"awakening","name":"Черта: всепрощение","iconUrl":"/nte-meta/game-assets/e44accb8b0b736c8d059.webp","description":"Персонаж, воскрешённый после применения Ирой «Миража сроком 3,8 миллиарда лет», восстанавливает 100 % ОЗ и получает 50 ед. энергии цикла и 50 ед. энергии сверхспособности."},{"level":3,"kind":"resonance","name":"Примат над всем сущим","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень навыков «Сотрудничество», «Непрерывность будущего „я“» и «Мираж сроком 3,8 миллиарда лет» на 1.\n\nУвеличивает защиту всех членов команды на 30 %, когда Ирой находится в команде."},{"level":6,"kind":"resonance","name":"Самопровозглашённый венец творения","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Увеличивает крит. урон всех членов команды на 25 %, когда Ирой находится в команде. За каждого союзника в состоянии Регрессии увеличивает наносимый Ирой урон на 15 %, а её шанс крит. удара — на 5 %."}]') WHERE character_id='iroi' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 03:56:00');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"ja-Play_Vo_Char_NPC028_Switch_001","title":"Переключение I","description":"А, уже моя очередь?","language":"Японский","audioUrl":"/nte-meta/game-audio/bff55f7b7a7bae196beb.ogg"},{"id":"ja-Play_Vo_Char_NPC028_windfall_001","title":"Неожиданная добыча I","description":"Как неожиданно!","language":"Японский","audioUrl":"/nte-meta/game-audio/76ac509b6825b41b45af.ogg"},{"id":"en-Play_Vo_Char_NPC028_ug_001","title":"Вознесение персонажа I","description":"Я буду стараться дальше!","language":"Английский","audioUrl":"/nte-meta/game-audio/094a504c2e9bc9272d76.ogg"},{"id":"ja-Play_Vo_Char_NPC028_ug_003","title":"Вознесение персонажа III","description":"Пожалуй, это мой предел… Спасибо за помощь.","language":"Японский","audioUrl":"/nte-meta/game-audio/8ecf421a78072ca2ccbc.ogg"},{"id":"en-Play_Vo_Char_NPC028_TeammateDown_002","title":"Поражён товарищ по команде – Шинку","description":"Ох, ну вот опять…","language":"Английский","audioUrl":"/nte-meta/game-audio/08c7cd49a226da53cd10.ogg"},{"id":"ja-Play_Vo_Char_NPC028_QTE_001","title":"Атака на входе I","description":"Вперёд!","language":"Японский","audioUrl":"/nte-meta/game-audio/2eb252bbf99b06df1cc6.ogg"},{"id":"ja-Play_Vo_Char_NPC028_SSC_ZH_002","title":"Особое переключение — Шинку","description":"Ой-ой, Шинку, неужели ты сама с этим не справишься?","language":"Японский","audioUrl":"/nte-meta/game-audio/bb2d9a9522dd81acacdd.ogg"},{"id":"en-Play_Vo_Char_NPC028_SSC_ZH_002","title":"Особое переключение — Шинку","description":"Ой-ой, Шинку, неужели ты сама с этим не справишься?","language":"Английский","audioUrl":"/nte-meta/game-audio/4ac7a64c76bb8f8a5f01.ogg"},{"id":"en-Play_Vo_Char_NPC028_Switch_002","title":"Переключение II","description":"Ребятки, настало наше время сиять!","language":"Английский","audioUrl":"/nte-meta/game-audio/344686e29542c104cb8b.ogg"},{"id":"ja-Play_Vo_Char_NPC028_weather_001","title":"Солнечно","description":"Солнце светит, и цветы распускаются…","language":"Японский","audioUrl":"/nte-meta/game-audio/1466e0ecbe179f8d39d0.ogg"},{"id":"en-Play_Vo_Char_NPC028_struck_001","title":"Урон I","description":"Ох!","language":"Английский","audioUrl":"/nte-meta/game-audio/7ffb21f2f7e533199fd2.ogg"},{"id":"en-Play_Vo_Char_NPC028_TeammateDown_001","title":"Поражен товарищ по команде – Минт","description":"Минт-сенпай потеряла сознание? Я разберусь!","language":"Английский","audioUrl":"/nte-meta/game-audio/a41845e86e0b52cd2c3c.ogg"},{"id":"en-Play_Vo_Char_NPC028_weather_004","title":"Жарко","description":"Хочу поскорее убраться от этого пекла.","language":"Английский","audioUrl":"/nte-meta/game-audio/729aed6113de87d0f539.ogg"},{"id":"ja-Play_Vo_Char_NPC028_containment_001","title":"Сдерживание I","description":"Слушай внимательно: оставайся здесь и ни в коем случае не убегай!","language":"Японский","audioUrl":"/nte-meta/game-audio/9185299fe0e92d16f440.ogg"},{"id":"ja-Play_Vo_Char_NPC028_windfall_005","title":"Неожиданная добыча V","description":"Я такого ещё не видела.","language":"Японский","audioUrl":"/nte-meta/game-audio/87e440b222cf898899c3.ogg"},{"id":"ja-Play_Vo_Char_NPC028_weather_002","title":"Дождливо","description":"У меня хвост промок…","language":"Японский","audioUrl":"/nte-meta/game-audio/092c1e0885ca62284097.ogg"},{"id":"ja-Play_Vo_Char_NPC028_vexation_001","title":"Проблемы","description":"Мои ребятки — Морфей, Икел и Фантас — вечно влипают в неприятности. Интересно, есть ли способ удержать их в узде…","language":"Японский","audioUrl":"/nte-meta/game-audio/e500c1a9162eaceaa8d7.ogg"},{"id":"ja-Play_Vo_Char_NPC028_windfall_004","title":"Неожиданная добыча IV","description":"Морфей, ну-ка прекрати!","language":"Японский","audioUrl":"/nte-meta/game-audio/90e8ec68c65b3ea76457.ogg"},{"id":"en-Play_Vo_Char_NPC028_aoe_UI_003","title":"Сверхспособность III","description":"Приятных снов… Вернее, кошмаров!","language":"Английский","audioUrl":"/nte-meta/game-audio/92f229ad7f25ce4e8203.ogg"},{"id":"en-Play_Vo_Char_NPC028_greet_003","title":"Вечернее приветствие","description":"Вот и скрылся мистер Солнце.","language":"Английский","audioUrl":"/nte-meta/game-audio/1d065ed4ec5b5262aa42.ogg"},{"id":"en-Play_Vo_Char_NPC028_windfall_002","title":"Неожиданная добыча II","description":"Класс!","language":"Английский","audioUrl":"/nte-meta/game-audio/d6107394f8d6b3182e25.ogg"},{"id":"en-Play_Vo_Char_NPC028_windfall_003","title":"Неожиданная добыча III","description":"Что за вкусняшки на этот раз?","language":"Английский","audioUrl":"/nte-meta/game-audio/270abf8aa2a4f4bcca6f.ogg"},{"id":"ja-Play_Vo_Char_NPC028_ug_002","title":"Вознесение персонажа II","description":"Хм… как далеко я смогу зайти?","language":"Японский","audioUrl":"/nte-meta/game-audio/96817bf97d87e04c5591.ogg"},{"id":"en-Play_Vo_Char_NPC028_about_003","title":"О Шинку II","description":"Сейчас мы в ладах. Эта скептичная дракониха просто меня не так поняла. По крайней мере, Минт говорит, что мы с Шинку теперь «души не чаем» друг в друге!","language":"Английский","audioUrl":"/nte-meta/game-audio/4aa58b7fb2d81f44e121.ogg"},{"id":"en-Play_Vo_Char_NPC028_chat_001","title":"Чат: пинать камушки","description":"Когда вижу мелкие камушки, прям тянет пнуть их… всё дальше и дальше, пока они не исчезнут там, где я их больше не увижу. Ты тоже так делаешь?","language":"Английский","audioUrl":"/nte-meta/game-audio/53b80f43f44c80dd7c7a.ogg"},{"id":"en-Play_Vo_Char_NPC028_Parry_002","title":"Парирование II","description":"Рука. Ноет.","language":"Английский","audioUrl":"/nte-meta/game-audio/61b047b468258eff6271.ogg"},{"id":"en-Play_Vo_Char_NPC028_self_003","title":"Обо мне: способность эспера","description":"Оболочка по имени Онейрой ожила лишь после пробуждения способности эспера. Но это не настоящая я, понимаешь? Настоящая я — та, что сейчас видит сон. А та, что говорит с тобой — лишь подделка, играющая роль «хорошей девочки»!","language":"Английский","audioUrl":"/nte-meta/game-audio/070209ace35025708e0e.ogg"},{"id":"en-Play_Vo_Char_NPC028_weather_002","title":"Дождливо","description":"У меня хвост промок…","language":"Английский","audioUrl":"/nte-meta/game-audio/f58584a759e66cb539dd.ogg"},{"id":"en-Play_Vo_Char_NPC028_anomaly_003","title":"Нуллификация I","description":"Тех, кто не способен учиться, придётся нуллифицировать… Прости!","language":"Английский","audioUrl":"/nte-meta/game-audio/adddf0528e860a9d04b6.ogg"},{"id":"ja-Play_Vo_Char_NPC028_chat_002","title":"Чат: школа","description":"Мои друзья вечно рассказывают что-то интересное про школу, а я училась дома, и у меня не было одноклассников. Жаль, что я так и не узнала, что такое настоящая школьная жизнь.","language":"Японский","audioUrl":"/nte-meta/game-audio/5d9f6ed936c6f3e40137.ogg"},{"id":"ja-Play_Vo_Char_NPC028_Fly_001","title":"Планирование I","description":"Я что, правда лечу?..","language":"Японский","audioUrl":"/nte-meta/game-audio/93a4fbeb97e72141ddd9.ogg"},{"id":"en-Play_Vo_Char_NPC028_about_004","title":"О Наналли","description":"Наналли ведь немного младше меня, да? Я ей даже чуточку завидую — в её-то годы она уже точно знает, чего хочет от жизни!","language":"Английский","audioUrl":"/nte-meta/game-audio/ee6cb2e429c2e48d9393.ogg"},{"id":"en-Play_Vo_Char_NPC028_Parry_001","title":"Парирование I","description":"Я смогла это парировать!","language":"Английский","audioUrl":"/nte-meta/game-audio/4581f6189e3e2935e6d0.ogg"},{"id":"en-Play_Vo_Char_NPC028_talk_001","title":"Тема: овцы","description":"Слышала, в некоторых культурах коз считают воплощением зла… Ребятки, а вы сами-то считаете себя плохишами? Ой, нет? Ребята, ложь только портит нашу репутацию!","language":"Английский","audioUrl":"/nte-meta/game-audio/bc1ccd32d09f654b0012.ogg"},{"id":"ja-Play_Vo_Char_NPC028_chat_001","title":"Чат: пинать камушки","description":"Когда вижу мелкие камушки, прям тянет пнуть их… всё дальше и дальше, пока они не исчезнут там, где я их больше не увижу. Ты тоже так делаешь?","language":"Японский","audioUrl":"/nte-meta/game-audio/a45c118e86808e163271.ogg"},{"id":"en-Play_Vo_Char_NPC028_fh_001","title":"Исцеление I","description":"Глоток свежего воздуха!","language":"Английский","audioUrl":"/nte-meta/game-audio/68899d20dff67457fc6d.ogg"},{"id":"ja-Play_Vo_Char_NPC028_about_003","title":"О Шинку II","description":"Сейчас мы в ладах. Эта скептичная дракониха просто меня не так поняла. По крайней мере, Минт говорит, что мы с Шинку теперь «души не чаем» друг в друге!","language":"Японский","audioUrl":"/nte-meta/game-audio/8e5eaea6738acd963f91.ogg"},{"id":"ja-Play_Vo_Char_NPC028_hp_001","title":"Низкий уровень здоровья I","description":"Холодно… очень холодно…","language":"Японский","audioUrl":"/nte-meta/game-audio/98672fd07b013b0e4350.ogg"},{"id":"en-Play_Vo_Char_NPC028_windfall_006","title":"Неожиданная добыча VI","description":"Вау, а это можно взять с собой в сон?","language":"Английский","audioUrl":"/nte-meta/game-audio/322629b97b0fd6104c10.ogg"},{"id":"ja-Play_Vo_Char_NPC028_Fly_002","title":"Планирование II","description":"Ура!","language":"Японский","audioUrl":"/nte-meta/game-audio/22f51c6542af19bd69a0.ogg"},{"id":"ja-Play_Vo_Char_NPC028_SSC_BH_001","title":"Особое переключение — Минт","description":"Минт-сенпай, я тут!","language":"Японский","audioUrl":"/nte-meta/game-audio/f638b2d435005d65bf1a.ogg"},{"id":"en-Play_Vo_Char_NPC028_anomaly_004","title":"Нуллификация II","description":"Может, мы ещё увидимся.","language":"Английский","audioUrl":"/nte-meta/game-audio/138b6c4ecb7facce6529.ogg"},{"id":"en-Play_Vo_Char_NPC028_dead_001","title":"Потеря сознания I","description":"В этом небе… нет просветов.","language":"Английский","audioUrl":"/nte-meta/game-audio/4aa380b19655eb7d2e2e.ogg"},{"id":"ja-Play_Vo_Char_NPC028_dead_002","title":"Потеря сознания II","description":"Мне… можно наконец вернуться?","language":"Японский","audioUrl":"/nte-meta/game-audio/2e86902db44fbbeff081.ogg"},{"id":"ja-Play_Vo_Char_NPC028_weather_004","title":"Жарко","description":"Хочу поскорее убраться от этого пекла.","language":"Японский","audioUrl":"/nte-meta/game-audio/c6524458cdd7589a9c3f.ogg"},{"id":"ja-Play_Vo_Char_NPC028_windfall_003","title":"Неожиданная добыча III","description":"Что за вкусняшки на этот раз?","language":"Японский","audioUrl":"/nte-meta/game-audio/e60822a66d420b114e6f.ogg"},{"id":"ja-Play_Vo_Char_NPC028_deploy_002","title":"Отправка II","description":"Я сделаю всё, что смогу!","language":"Японский","audioUrl":"/nte-meta/game-audio/da5d3b045dd9bb6ebe01.ogg"},{"id":"ja-Play_Vo_Char_NPC028_skill_002","title":"Навык перенаправления II","description":"Пора встава-а-ать!","language":"Японский","audioUrl":"/nte-meta/game-audio/beb41182da824d679728.ogg"},{"id":"ja-Play_Vo_Char_NPC028_struck_001","title":"Урон I","description":"Ох!","language":"Японский","audioUrl":"/nte-meta/game-audio/d446f9e4fd7f41d2cdbe.ogg"},{"id":"en-Play_Vo_Char_NPC028_SSC_BH_001","title":"Особое переключение — Минт","description":"Минт-сенпай, я тут!","language":"Английский","audioUrl":"/nte-meta/game-audio/56efa91dc130b709a8be.ogg"},{"id":"ja-Play_Vo_Char_NPC028_about_001","title":"О Минт","description":"У Минт сенпай столько энергии и страсти. Я тоже хочу быть как она! Я вру? Нет-нет-нет, с чего ты взял? Я серьёзно! У Минт сенпай столько энергии и страсти. Я тоже хочу быть как она! Я вру? Нет-нет-нет, с чего ты взяла? Я серьёзно!","language":"Японский","audioUrl":"/nte-meta/game-audio/93085149fe0b46039c47.ogg"},{"id":"ja-Play_Vo_Char_NPC028_dead_003","title":"Потеря сознания III","description":"Снаружи… становится тихо.","language":"Японский","audioUrl":"/nte-meta/game-audio/80d81fe42f696e11bd2d.ogg"},{"id":"ja-Play_Vo_Char_NPC028_self_004","title":"Обо… мне?","description":"Моё тело медленно разрушалось, но способность эспера позволила мне жить. Я — это не она. Она живёт вместо меня. Жива ли я до сих пор? Я… не знаю","language":"Японский","audioUrl":"/nte-meta/game-audio/2801c4fafb42f3bf5ef3.ogg"},{"id":"en-Play_Vo_Char_NPC028_SSC_zero_003","title":"Особое переключение — Ноль","description":"Оценщик, я пришла на помощь! Оценщица, я пришла на помощь!","language":"Английский","audioUrl":"/nte-meta/game-audio/9b68865cfdf22adbf320.ogg"},{"id":"en-Play_Vo_Char_NPC028_weather_003","title":"Холодно","description":"Я уже не чувствую ни рук, ни ног.","language":"Английский","audioUrl":"/nte-meta/game-audio/d5a29b09da43cf15c3e6.ogg"},{"id":"ja-Play_Vo_Char_NPC028_anomaly_004","title":"Нуллификация II","description":"Может, мы ещё увидимся.","language":"Японский","audioUrl":"/nte-meta/game-audio/f0657a7d39befb2fa56f.ogg"},{"id":"ja-Play_Vo_Char_NPC028_DodgeCombo_002","title":"Серия критических уклонений II","description":"Фух! Пронесло.","language":"Японский","audioUrl":"/nte-meta/game-audio/58e30d36bd65bd5763a0.ogg"},{"id":"en-Play_Vo_Char_NPC028_greet_001","title":"Утреннее приветствие","description":"(Зевок) Доброе утро!","language":"Английский","audioUrl":"/nte-meta/game-audio/e7b6e58bbd23c6adcd79.ogg"},{"id":"ja-Play_Vo_Char_NPC028_aoe_UI_003","title":"Сверхспособность III","description":"Приятных снов… Вернее, кошмаров!","language":"Японский","audioUrl":"/nte-meta/game-audio/d6fc904cb4cd14031d74.ogg"},{"id":"en-Play_Vo_Char_NPC028_hp_001","title":"Низкий уровень здоровья I","description":"Холодно… очень холодно…","language":"Английский","audioUrl":"/nte-meta/game-audio/96ed00edc892c08fae49.ogg"},{"id":"en-Play_Vo_Char_NPC028_windfall_004","title":"Неожиданная добыча IV","description":"Морфей, ну-ка прекрати!","language":"Английский","audioUrl":"/nte-meta/game-audio/fc3e017515fd46ed3cbf.ogg"},{"id":"en-Play_Vo_Char_NPC028_fh_002","title":"Исцеление II","description":"Я снова в деле!","language":"Английский","audioUrl":"/nte-meta/game-audio/f6cfe04fac762460fe4d.ogg"},{"id":"en-Play_Vo_Char_NPC028_gift_003","title":"Подарок получен III","description":"Я это ценю!","language":"Английский","audioUrl":"/nte-meta/game-audio/3f71c2ca6db081fab951.ogg"},{"id":"en-Play_Vo_Char_NPC028_hp_002","title":"Низкий уровень здоровья II","description":"Ноги совсем не слушаются.","language":"Английский","audioUrl":"/nte-meta/game-audio/1d2b9160f0d4ce8d63a5.ogg"},{"id":"en-Play_Vo_Char_NPC028_Switch_001","title":"Переключение I","description":"А, уже моя очередь?","language":"Английский","audioUrl":"/nte-meta/game-audio/9efc6df77fdaae9df60d.ogg"},{"id":"en-Play_Vo_Char_NPC028_ug_002","title":"Вознесение персонажа II","description":"Хм… как далеко я смогу зайти?","language":"Английский","audioUrl":"/nte-meta/game-audio/cd2d6ef9bfa72706e12c.ogg"},{"id":"ja-Play_Vo_Char_NPC028_gift_004","title":"Подарок получен IV","description":"Какой классный подарок!","language":"Японский","audioUrl":"/nte-meta/game-audio/b612cb313e3c6ec2dc50.ogg"},{"id":"ja-Play_Vo_Char_NPC028_QTE_002","title":"Атака на входе II","description":"Ребятковый луч!","language":"Японский","audioUrl":"/nte-meta/game-audio/f8fb3f5ab2ba681a4885.ogg"},{"id":"ja-Play_Vo_Char_NPC028_ug_001","title":"Вознесение персонажа I","description":"Я буду стараться дальше!","language":"Японский","audioUrl":"/nte-meta/game-audio/80a09aa457d967310081.ogg"},{"id":"ja-Play_Vo_Char_NPC028_gift_001","title":"Подарок получен I","description":"О… ого! Мне очень нравится! Спасибо тебе большое!","language":"Японский","audioUrl":"/nte-meta/game-audio/8720df1fb63b75cee25b.ogg"},{"id":"ja-Play_Vo_Char_NPC028_about_002","title":"О Шинку I","description":"После того как я затащила Шинку в свои сны, она начала меня ненавидеть. Ей не понравилось то, что я ей показала? Или… она о чём-то догадалась?","language":"Японский","audioUrl":"/nte-meta/game-audio/8f4cf82c12e5312b0c5a.ogg"},{"id":"ja-Play_Vo_Char_NPC028_kill_001","title":"Убийство I","description":"Ой, забыла попрощаться!","language":"Японский","audioUrl":"/nte-meta/game-audio/841d32963eda6803d3a0.ogg"},{"id":"ja-Play_Vo_Char_NPC028_skill_001","title":"Навык перенаправления I","description":"Время кошмара!","language":"Японский","audioUrl":"/nte-meta/game-audio/a2a27f450f2487f33819.ogg"},{"id":"en-Play_Vo_Char_NPC028_about_002","title":"О Шинку I","description":"После того как я затащила Шинку в свои сны, она начала меня ненавидеть. Ей не понравилось то, что я ей показала? Или… она о чём-то догадалась?","language":"Английский","audioUrl":"/nte-meta/game-audio/67647672e01847b78718.ogg"},{"id":"en-Play_Vo_Char_NPC028_gift_004","title":"Подарок получен IV","description":"Какой классный подарок!","language":"Английский","audioUrl":"/nte-meta/game-audio/18a92a8bd7f4b716f537.ogg"},{"id":"ja-Play_Vo_Char_NPC028_DodgeCombo_001","title":"Серия критических уклонений I","description":"Хех, и как ты умудрился проглядеть?","language":"Японский","audioUrl":"/nte-meta/game-audio/504984a10c9ec443ba06.ogg"},{"id":"ja-Play_Vo_Char_NPC028_meet_001","title":"Первая встреча","description":"Привет! Меня зовут Онейрой. Выговорить трудновато, так что зови просто Ирой! Если что понадобится — только дай знать. Увидимся!","language":"Японский","audioUrl":"/nte-meta/game-audio/24e2f5ef76490d8ce8bf.ogg"},{"id":"ja-Play_Vo_Char_NPC028_Switch_002","title":"Переключение II","description":"Ребятки, настало наше время сиять!","language":"Японский","audioUrl":"/nte-meta/game-audio/9ad783e4c9fa65d2f7ea.ogg"},{"id":"ja-Play_Vo_Char_NPC028_weather_003","title":"Холодно","description":"Я уже не чувствую ни рук, ни ног.","language":"Японский","audioUrl":"/nte-meta/game-audio/3b238d4f0c6f4a79e51e.ogg"},{"id":"en-Play_Vo_Char_NPC028_DodgeCombo_001","title":"Серия критических уклонений I","description":"Хех, и как ты умудрился проглядеть?","language":"Английский","audioUrl":"/nte-meta/game-audio/3611b2861143ac5969b8.ogg"},{"id":"en-Play_Vo_Char_NPC028_TeammateDown_003","title":"Поражен товарищ по команде – Ноль","description":"А?.. Оценщика… одолели? А?.. Оценщицу… одолели?","language":"Английский","audioUrl":"/nte-meta/game-audio/2793d29b90341c516d29.ogg"},{"id":"ja-Play_Vo_Char_NPC028_dead_001","title":"Потеря сознания I","description":"В этом небе… нет просветов.","language":"Японский","audioUrl":"/nte-meta/game-audio/ac5f1258d0352545c936.ogg"},{"id":"en-Play_Vo_Char_NPC028_weather_001","title":"Солнечно","description":"Солнце светит, и цветы распускаются…","language":"Английский","audioUrl":"/nte-meta/game-audio/cd8607b93e5cbb25c59a.ogg"},{"id":"ja-Play_Vo_Char_NPC028_greet_004","title":"Спокойной ночи","description":"Ночь. Пришла.","language":"Японский","audioUrl":"/nte-meta/game-audio/fef637ba70bb875dae71.ogg"},{"id":"ja-Play_Vo_Char_NPC028_Parry_001","title":"Парирование I","description":"Я смогла это парировать!","language":"Японский","audioUrl":"/nte-meta/game-audio/b845018c0ce35685490a.ogg"},{"id":"en-Play_Vo_Char_NPC028_talk_003","title":"Тема: миры грёз","description":"Тебе нравится видеть сны? Хочешь взглянуть на мои? Только пройди через ворота с бычьими рогами. Если пройдёшь через ворота из слоновой кости — я не смогу тебя вытащить. Тебе придётся заново прожить весь путь: от эмбриона до нынешнего себя! Тебе нравится видеть сны? Хочешь взглянуть на мои? Только пройди через ворота с бычьими рогами. Если пройдёшь через ворота из слоновой кости — я не смогу тебя вытащить. Тебе придётся заново прожить весь путь: от эмбриона до нынешней себя!","language":"Английский","audioUrl":"/nte-meta/game-audio/63c5900f727e8c6ab3f3.ogg"},{"id":"ja-Play_Vo_Char_NPC028_hp_002","title":"Низкий уровень здоровья II","description":"Ноги совсем не слушаются.","language":"Японский","audioUrl":"/nte-meta/game-audio/c81a0ad5f04bb5ced5ba.ogg"},{"id":"ja-Play_Vo_Char_NPC028_talk_003","title":"Тема: миры грёз","description":"Тебе нравится видеть сны? Хочешь взглянуть на мои? Только пройди через ворота с бычьими рогами. Если пройдёшь через ворота из слоновой кости — я не смогу тебя вытащить. Тебе придётся заново прожить весь путь: от эмбриона до нынешнего себя! Тебе нравится видеть сны? Хочешь взглянуть на мои? Только пройди через ворота с бычьими рогами. Если пройдёшь через ворота из слоновой кости — я не смогу тебя вытащить. Тебе придётся заново прожить весь путь: от эмбриона до нынешней себя!","language":"Японский","audioUrl":"/nte-meta/game-audio/55803b8b74ee8ef95cb4.ogg"},{"id":"en-Play_Vo_Char_NPC028_hobby_001","title":"Хобби","description":"Что мне нравится? Да всё то же, что и остальным! Погоди, ты хочешь сказать, что есть люди, которым нравится то, что другие ненавидят? Ну, тогда пусть подерутся, а я примкну к победителю!","language":"Английский","audioUrl":"/nte-meta/game-audio/0b1fba24ced8faf4e86b.ogg"},{"id":"ja-Play_Vo_Char_NPC028_about_004","title":"О Наналли","description":"Наналли ведь немного младше меня, да? Я ей даже чуточку завидую — в её-то годы она уже точно знает, чего хочет от жизни!","language":"Японский","audioUrl":"/nte-meta/game-audio/fe4356ba10456f479c1c.ogg"},{"id":"ja-Play_Vo_Char_NPC028_fh_002","title":"Исцеление II","description":"Я снова в деле!","language":"Японский","audioUrl":"/nte-meta/game-audio/a074ed0e2717b68b22f0.ogg"},{"id":"en-Play_Vo_Char_NPC028_deploy_002","title":"Отправка II","description":"Я сделаю всё, что смогу!","language":"Английский","audioUrl":"/nte-meta/game-audio/41b397708e881372c1a2.ogg"},{"id":"en-Play_Vo_Char_NPC028_ug_003","title":"Вознесение персонажа III","description":"Пожалуй, это мой предел… Спасибо за помощь.","language":"Английский","audioUrl":"/nte-meta/game-audio/ee3775427c4da8c2878a.ogg"},{"id":"ja-Play_Vo_Char_NPC028_hobby_001","title":"Хобби","description":"Что мне нравится? Да всё то же, что и остальным! Погоди, ты хочешь сказать, что есть люди, которым нравится то, что другие ненавидят? Ну, тогда пусть подерутся, а я примкну к победителю!","language":"Японский","audioUrl":"/nte-meta/game-audio/70b6a4ae4090ebba82b2.ogg"},{"id":"en-Play_Vo_Char_NPC028_containment_002","title":"Сдерживание II","description":"Сдерживание завершено!","language":"Английский","audioUrl":"/nte-meta/game-audio/307f90b7734f43e993c4.ogg"},{"id":"ja-Play_Vo_Char_NPC028_deploy_001","title":"Отправка I","description":"Ирой здесь — готова к бою!","language":"Японский","audioUrl":"/nte-meta/game-audio/199b8c469be46540bf20.ogg"},{"id":"ja-Play_Vo_Char_NPC028_greet_003","title":"Вечернее приветствие","description":"Вот и скрылся мистер Солнце.","language":"Японский","audioUrl":"/nte-meta/game-audio/54cab160e701d01e5fae.ogg"},{"id":"en-Play_Vo_Char_NPC028_about_001","title":"О Минт","description":"У Минт сенпай столько энергии и страсти. Я тоже хочу быть как она! Я вру? Нет-нет-нет, с чего ты взял? Я серьёзно! У Минт сенпай столько энергии и страсти. Я тоже хочу быть как она! Я вру? Нет-нет-нет, с чего ты взяла? Я серьёзно!","language":"Английский","audioUrl":"/nte-meta/game-audio/de97ea808ff8940efcac.ogg"},{"id":"en-Play_Vo_Char_NPC028_meet_001","title":"Первая встреча","description":"Привет! Меня зовут Онейрой. Выговорить трудновато, так что зови просто Ирой! Если что понадобится — только дай знать. Увидимся!","language":"Английский","audioUrl":"/nte-meta/game-audio/0c1af16c604e7f5e56a0.ogg"},{"id":"ja-Play_Vo_Char_NPC028_containment_002","title":"Сдерживание II","description":"Сдерживание завершено!","language":"Японский","audioUrl":"/nte-meta/game-audio/c651e9fdeabce4c8209a.ogg"},{"id":"ja-Play_Vo_Char_NPC028_self_001","title":"Обо мне: семья","description":"Родители очень меня любят и столько для меня сделали. Они просто хотят, чтобы я была счастлива. Я им очень благодарна, но иногда не могу отделаться от мысли… если бы на моем месте родился ребенок поздоровее…","language":"Японский","audioUrl":"/nte-meta/game-audio/860f70494ef9c7b08222.ogg"},{"id":"en-Play_Vo_Char_NPC028_vexation_001","title":"Проблемы","description":"Мои ребятки — Морфей, Икел и Фантас — вечно влипают в неприятности. Интересно, есть ли способ удержать их в узде…","language":"Английский","audioUrl":"/nte-meta/game-audio/7b0a9a244aa5469afdc5.ogg"},{"id":"ja-Play_Vo_Char_NPC028_gift_002","title":"Подарок получен II","description":"Это мне? С радостью приму, спасибо!","language":"Японский","audioUrl":"/nte-meta/game-audio/d05415f96653bbb9f3fc.ogg"},{"id":"ja-Play_Vo_Char_NPC028_greet_001","title":"Утреннее приветствие","description":"(Зевок) Доброе утро!","language":"Японский","audioUrl":"/nte-meta/game-audio/5a497d994d702569f09e.ogg"},{"id":"en-Play_Vo_Char_NPC028_chat_003","title":"Чат: теория эволюции","description":"«Естественный отбор — это выживание сильнейших…» — это всё, что моя учительница сказала о теории эволюции. Ей не пришлось объяснять: это был первый сон, который «я» увидела в своей жизни…","language":"Английский","audioUrl":"/nte-meta/game-audio/ee06457a6b43abf272dc.ogg"},{"id":"en-Play_Vo_Char_NPC028_greet_002","title":"Дневное приветствие","description":"Пора вздремнуть.","language":"Английский","audioUrl":"/nte-meta/game-audio/b38fc8a0ffbba5ed19eb.ogg"},{"id":"en-Play_Vo_Char_NPC028_kill_002","title":"Убийство II","description":"Ого, неужели уже всё?","language":"Английский","audioUrl":"/nte-meta/game-audio/232d2f3ff10139951cea.ogg"},{"id":"en-Play_Vo_Char_NPC028_Switch_003","title":"Переключение III","description":"А, я? Уже бегу!","language":"Английский","audioUrl":"/nte-meta/game-audio/dedea88ea82e6d76e6c0.ogg"},{"id":"en-Play_Vo_Char_NPC028_dead_003","title":"Потеря сознания III","description":"Снаружи… становится тихо.","language":"Английский","audioUrl":"/nte-meta/game-audio/4845b70a873c0fcfcc90.ogg"},{"id":"en-Play_Vo_Char_NPC028_hstruck_001","title":"Сильный урон I","description":"Ай, ай, ай…","language":"Английский","audioUrl":"/nte-meta/game-audio/ddd764e037fe17fc0a0a.ogg"},{"id":"ja-Play_Vo_Char_NPC028_fh_001","title":"Исцеление I","description":"Глоток свежего воздуха!","language":"Японский","audioUrl":"/nte-meta/game-audio/a7af35784c5a7d218da9.ogg"},{"id":"en-Play_Vo_Char_NPC028_greet_004","title":"Спокойной ночи","description":"Ночь. Пришла.","language":"Английский","audioUrl":"/nte-meta/game-audio/1ec571a73b9511771f01.ogg"},{"id":"ja-Play_Vo_Char_NPC028_QTE_003","title":"Атака на входе III","description":"Прицел… Огонь!","language":"Японский","audioUrl":"/nte-meta/game-audio/049e9f8bf4a1d9141a61.ogg"},{"id":"ja-Play_Vo_Char_NPC028_self_002","title":"Обо мне: сон","description":"Кажется, я всегда спала. Даже когда бодра и полна сил, я всё равно блуждаю во сне!","language":"Японский","audioUrl":"/nte-meta/game-audio/7a2363cac969fcec0cbe.ogg"},{"id":"en-Play_Vo_Char_NPC028_DodgeCombo_002","title":"Серия критических уклонений II","description":"Фух! Пронесло.","language":"Английский","audioUrl":"/nte-meta/game-audio/d44171b70b0e5415b742.ogg"},{"id":"en-Play_Vo_Char_NPC028_self_004","title":"Обо… мне?","description":"Моё тело медленно разрушалось, но способность эспера позволила мне жить. Я — это не она. Она живёт вместо меня. Жива ли я до сих пор? Я… не знаю","language":"Английский","audioUrl":"/nte-meta/game-audio/35728aa2132dfc2acea9.ogg"},{"id":"ja-Play_Vo_Char_NPC028_hstruck_001","title":"Сильный урон I","description":"Ай, ай, ай…","language":"Японский","audioUrl":"/nte-meta/game-audio/b6f0a4da417d2ca2e9a0.ogg"},{"id":"ja-Play_Vo_Char_NPC028_TeammateDown_003","title":"Поражен товарищ по команде – Ноль","description":"А?.. Оценщика… одолели? А?.. Оценщицу… одолели?","language":"Японский","audioUrl":"/nte-meta/game-audio/ca5084a65a5d446fb36c.ogg"},{"id":"en-Play_Vo_Char_NPC028_Fly_001","title":"Планирование I","description":"Я что, правда лечу?..","language":"Английский","audioUrl":"/nte-meta/game-audio/ad237437f97006b981db.ogg"},{"id":"en-Play_Vo_Char_NPC028_gift_001","title":"Подарок получен I","description":"О… ого! Мне очень нравится! Спасибо тебе большое!","language":"Английский","audioUrl":"/nte-meta/game-audio/8b15f32453ed610c982d.ogg"},{"id":"en-Play_Vo_Char_NPC028_struck_002","title":"Урон II","description":"Ой!","language":"Английский","audioUrl":"/nte-meta/game-audio/86b379b8c592cfbb7295.ogg"},{"id":"en-Play_Vo_Char_NPC028_windfall_001","title":"Неожиданная добыча I","description":"Как неожиданно!","language":"Английский","audioUrl":"/nte-meta/game-audio/84179daf769d4f135194.ogg"},{"id":"ja-Play_Vo_Char_NPC028_TeammateDown_002","title":"Поражён товарищ по команде – Шинку","description":"Ох, ну вот опять…","language":"Японский","audioUrl":"/nte-meta/game-audio/78e8e5a4e8b7d4892ebb.ogg"},{"id":"en-Play_Vo_Char_NPC028_hstruck_002","title":"Сильный урон II","description":"Я поранилась…","language":"Английский","audioUrl":"/nte-meta/game-audio/5f24c6cfb19ce082445a.ogg"},{"id":"en-Play_Vo_Char_NPC028_talk_002","title":"Тема: комната","description":"В детстве я проводила кучу времени в больницах, потому что постоянно болела. Тогда я думала, что абсолютно все спят в белых кроватях под писк и тиканье этих медицинских аппаратов. Когда я рассказала об этом коллегам из благотворительного фонда, они решили, что я жила в комнате с привидениями!","language":"Английский","audioUrl":"/nte-meta/game-audio/b4fa361675eb7e26f84c.ogg"},{"id":"ja-Play_Vo_Char_NPC028_windfall_006","title":"Неожиданная добыча VI","description":"Вау, а это можно взять с собой в сон?","language":"Японский","audioUrl":"/nte-meta/game-audio/1f882531c774a1fb6162.ogg"},{"id":"en-Play_Vo_Char_NPC028_containment_001","title":"Сдерживание I","description":"Слушай внимательно: оставайся здесь и ни в коем случае не убегай!","language":"Английский","audioUrl":"/nte-meta/game-audio/b2ffaba9312bb9068280.ogg"},{"id":"en-Play_Vo_Char_NPC028_dead_002","title":"Потеря сознания II","description":"Мне… можно наконец вернуться?","language":"Английский","audioUrl":"/nte-meta/game-audio/43bd7f1e63c18fe8da16.ogg"},{"id":"en-Play_Vo_Char_NPC028_windfall_005","title":"Неожиданная добыча V","description":"Я такого ещё не видела.","language":"Английский","audioUrl":"/nte-meta/game-audio/4df4e6da9a71d2afe89e.ogg"},{"id":"ja-Play_Vo_Char_NPC028_hp_003","title":"Низкий уровень здоровья III","description":"Тело. Болит.","language":"Японский","audioUrl":"/nte-meta/game-audio/65fa7b9067408809674e.ogg"},{"id":"ja-Play_Vo_Char_NPC028_SSC_zero_003","title":"Особое переключение — Ноль","description":"Оценщик, я пришла на помощь! Оценщица, я пришла на помощь!","language":"Японский","audioUrl":"/nte-meta/game-audio/35d350ffee2db9e62d17.ogg"},{"id":"ja-Play_Vo_Char_NPC028_windfall_002","title":"Неожиданная добыча II","description":"Класс!","language":"Японский","audioUrl":"/nte-meta/game-audio/a5424c99a1489e8b0a6e.ogg"},{"id":"en-Play_Vo_Char_NPC028_hp_003","title":"Низкий уровень здоровья III","description":"Тело. Болит.","language":"Английский","audioUrl":"/nte-meta/game-audio/d7e9d56fdd8e81ac708d.ogg"},{"id":"ja-Play_Vo_Char_NPC028_anomaly_003","title":"Нуллификация I","description":"Тех, кто не способен учиться, придётся нуллифицировать… Прости!","language":"Японский","audioUrl":"/nte-meta/game-audio/70c9f4be12cde5fb1d0b.ogg"},{"id":"ja-Play_Vo_Char_NPC028_greet_002","title":"Дневное приветствие","description":"Пора вздремнуть.","language":"Японский","audioUrl":"/nte-meta/game-audio/f4e672b71fe0c3261d65.ogg"},{"id":"en-Play_Vo_Char_NPC028_kill_001","title":"Убийство I","description":"Ой, забыла попрощаться!","language":"Английский","audioUrl":"/nte-meta/game-audio/4b615c12827fc94935da.ogg"},{"id":"en-Play_Vo_Char_NPC028_self_001","title":"Обо мне: семья","description":"Родители очень меня любят и столько для меня сделали. Они просто хотят, чтобы я была счастлива. Я им очень благодарна, но иногда не могу отделаться от мысли… если бы на моем месте родился ребенок поздоровее…","language":"Английский","audioUrl":"/nte-meta/game-audio/daa2b9ffc091ee454fcb.ogg"},{"id":"ja-Play_Vo_Char_NPC028_aoe_UI_001","title":"Сверхспособность I","description":"А теперь, ребята, давайте-ка все поползём обратно в мамин животик!","language":"Японский","audioUrl":"/nte-meta/game-audio/c01ae660c5cf4c6b57ee.ogg"},{"id":"ja-Play_Vo_Char_NPC028_aoe_UI_002","title":"Сверхспособность II","description":"Мои сны жутко страшные!","language":"Японский","audioUrl":"/nte-meta/game-audio/941e1d0a339ee1d78845.ogg"},{"id":"ja-Play_Vo_Char_NPC028_gift_003","title":"Подарок получен III","description":"Я это ценю!","language":"Японский","audioUrl":"/nte-meta/game-audio/9a23d6c3b7f1636b8e34.ogg"},{"id":"en-Play_Vo_Char_NPC028_deploy_001","title":"Отправка I","description":"Ирой здесь — готова к бою!","language":"Английский","audioUrl":"/nte-meta/game-audio/8ae4e34b96dcd4993bdb.ogg"},{"id":"en-Play_Vo_Char_NPC028_self_002","title":"Обо мне: сон","description":"Кажется, я всегда спала. Даже когда бодра и полна сил, я всё равно блуждаю во сне!","language":"Английский","audioUrl":"/nte-meta/game-audio/6181bb3044e4ac944893.ogg"},{"id":"ja-Play_Vo_Char_NPC028_skill_003","title":"Навык перенаправления III","description":"Ребятки, по моей команде!","language":"Японский","audioUrl":"/nte-meta/game-audio/6db670135ed3ccb137eb.ogg"},{"id":"ja-Play_Vo_Char_NPC028_TeammateDown_001","title":"Поражен товарищ по команде – Минт","description":"Минт-сенпай потеряла сознание? Я разберусь!","language":"Японский","audioUrl":"/nte-meta/game-audio/8e3bbdf5cc9e0c062984.ogg"},{"id":"ja-Play_Vo_Char_NPC028_talk_001","title":"Тема: овцы","description":"Слышала, в некоторых культурах коз считают воплощением зла… Ребятки, а вы сами-то считаете себя плохишами? Ой, нет? Ребята, ложь только портит нашу репутацию!","language":"Японский","audioUrl":"/nte-meta/game-audio/ddc508fca47d62c7b512.ogg"},{"id":"en-Play_Vo_Char_NPC028_aoe_UI_002","title":"Сверхспособность II","description":"Мои сны жутко страшные!","language":"Английский","audioUrl":"/nte-meta/game-audio/b8caac9559b2d3393437.ogg"},{"id":"en-Play_Vo_Char_NPC028_Fly_002","title":"Планирование II","description":"Ура!","language":"Английский","audioUrl":"/nte-meta/game-audio/9e97e367cda2246a45a5.ogg"},{"id":"ja-Play_Vo_Char_NPC028_hstruck_002","title":"Сильный урон II","description":"Я поранилась…","language":"Японский","audioUrl":"/nte-meta/game-audio/fb05dbacfded8151c9c3.ogg"},{"id":"ja-Play_Vo_Char_NPC028_self_003","title":"Обо мне: способность эспера","description":"Оболочка по имени Онейрой ожила лишь после пробуждения способности эспера. Но это не настоящая я, понимаешь? Настоящая я — та, что сейчас видит сон. А та, что говорит с тобой — лишь подделка, играющая роль «хорошей девочки»!","language":"Японский","audioUrl":"/nte-meta/game-audio/77abe67523962d25f7d2.ogg"},{"id":"ja-Play_Vo_Char_NPC028_struck_002","title":"Урон II","description":"Ой!","language":"Японский","audioUrl":"/nte-meta/game-audio/bf771c4a8df5ad9626f5.ogg"},{"id":"en-Play_Vo_Char_NPC028_gift_002","title":"Подарок получен II","description":"Это мне? С радостью приму, спасибо!","language":"Английский","audioUrl":"/nte-meta/game-audio/22185c61f14934ba2f93.ogg"},{"id":"ja-Play_Vo_Char_NPC028_chat_003","title":"Чат: теория эволюции","description":"«Естественный отбор — это выживание сильнейших…» — это всё, что моя учительница сказала о теории эволюции. Ей не пришлось объяснять: это был первый сон, который «я» увидела в своей жизни…","language":"Японский","audioUrl":"/nte-meta/game-audio/4d5fbc62ba6d375d7659.ogg"},{"id":"ja-Play_Vo_Char_NPC028_kill_002","title":"Убийство II","description":"Ого, неужели уже всё?","language":"Японский","audioUrl":"/nte-meta/game-audio/884712ea904fb24b452c.ogg"},{"id":"ja-Play_Vo_Char_NPC028_Switch_003","title":"Переключение III","description":"А, я? Уже бегу!","language":"Японский","audioUrl":"/nte-meta/game-audio/ba4442848119bb9a6071.ogg"},{"id":"en-Play_Vo_Char_NPC028_aoe_UI_001","title":"Сверхспособность I","description":"А теперь, ребята, давайте-ка все поползём обратно в мамин животик!","language":"Английский","audioUrl":"/nte-meta/game-audio/dff559a6117e69f62a42.ogg"},{"id":"en-Play_Vo_Char_NPC028_chat_002","title":"Чат: школа","description":"Мои друзья вечно рассказывают что-то интересное про школу, а я училась дома, и у меня не было одноклассников. Жаль, что я так и не узнала, что такое настоящая школьная жизнь.","language":"Английский","audioUrl":"/nte-meta/game-audio/90053a4d6b1c97fd2e4e.ogg"},{"id":"ja-Play_Vo_Char_NPC028_Parry_002","title":"Парирование II","description":"Рука. Ноет.","language":"Японский","audioUrl":"/nte-meta/game-audio/fcd350e09a6fb551fbc0.ogg"},{"id":"ja-Play_Vo_Char_NPC028_talk_002","title":"Тема: комната","description":"В детстве я проводила кучу времени в больницах, потому что постоянно болела. Тогда я думала, что абсолютно все спят в белых кроватях под писк и тиканье этих медицинских аппаратов. Когда я рассказала об этом коллегам из благотворительного фонда, они решили, что я жила в комнате с привидениями!","language":"Японский","audioUrl":"/nte-meta/game-audio/4f6c633a0431ce4b69eb.ogg"}]') WHERE character_id='iroi' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 03:56:00');

UPDATE character_profiles SET abilities_json=json('[{"id":"GA_Oneiroi_Passive_2","name":"Симпатические нервы","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/77c8dfdd70f637465889.webp","description":"Когда Ирой выполняет исцеление, все члены команды дополнительно игнорируют 5 % защиты в течение 20 сек.\n\nМоё покрытое шрамами тело преданно продолжает жить и никогда не жалуется.","attributes":[]},{"id":"GA_Oneiroi_QTE","name":"Бах!","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/601ab067daa17d5c86ea.webp","description":"Как раз вовремя! Ирой подхватывает Морфея и атакует перед собой. Она один раз наносит урон анимы, исцеляет всех членов команды и накапливает Воображение.\n\nТы поверишь, если я скажу, что это звук Большого взрыва?","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"},{"id":"parameter-1","label":"Множитель лечения","value":"1: 60 % · 2: 64.8 % · 3: 70 % · 4: 75.6 % · 5: 81.7 % · 6: 88.2 % · 7: 95.3 % · 8: 102.9 % · 9: 111.1 % · 10: 120 % · 11: 129.6 % · 12: 140 % · 13: 151.2 %"}]},{"id":"GA_Oneiroi_Melee","name":"Сотрудничество","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/6c243362f2148a7e4dcc.webp","description":"Базовая атака: Сотрудничество\nПризывает ягнят, которые совершают до 5 последовательных атак и наносят урон анимы. При попадании накапливает Воображение.\n\nБазовая атака: Грёза\nУдерживайте базовую атаку для зарядки. В зависимости от длительности зарядки расходуется Воображение, что позволяет провести до 3 ударов «Грёзы», наносящих урон анимы.\n\nУдерживайте базовую атаку во время навыков «Рефлекторная реакция», «Бах!», «Непрерывность будущего „я“» и «Мираж сроком 3,8 миллиарда лет», чтобы израсходовать Воображение и провести 3-й удар «Грёзы», наносящий урон анимы.\n\nБазовая атака: Осознанный сон\nСнова удерживайте кнопку базовой атаки после того, как Ирой применит базовую атаку «Грёза», чтобы израсходовать Воображение, призвать Морфея и открыть непрерывный огонь, наносящий урон анимы.\n\nБазовая атака: Пора встава-а-ать!\nНажмите кнопку базовой атаки в воздухе, чтобы выполнить атаку в падении. При приземлении Ирой наносит 1 удар урона анимы по области. Урон увеличивается в зависимости от высоты падения; максимальное увеличение составляет 100 %. При попадании Ирой накапливает Воображение.\n\nРефлекторная реакция\nСрабатывает при использовании базовой атаки «Сотрудничество» после критического уклонения. Ирой бросает Морфея в цель, наносит 1 удар урона анимы и снижает показатель разрушения. При попадании Ирой накапливает Воображение.\n\n…Бз-з… Бз-з… Бз-з-з… Бз-з-з-з…","attributes":[{"id":"parameter-0","label":"«Сотрудничество»: множитель урона 1-го удара и накопление Воображения","value":"1: 76 %, 2 · 2: 82.1 %, 2 · 3: 88.6 %, 2 · 4: 95.7 %, 2 · 5: 103.4 %, 2 · 6: 111.7 %, 2 · 7: 120.6 %, 2 · 8: 130.3 %, 2 · 9: 140.7 %, 2 · 10: 151.9 %, 2 · 11: 164.1 %, 2 · 12: 177.2 %, 2 · 13: 191.4 %, 2"},{"id":"parameter-1","label":"«Сотрудничество»: множитель урона 2-го удара и накопление Воображения","value":"1: 15.9 % *3, 3 · 2: 17.2 % *3, 3 · 3: 18.5 % *3, 3 · 4: 20 % *3, 3 · 5: 21.6 % *3, 3 · 6: 23.4 % *3, 3 · 7: 25.2 % *3, 3 · 8: 27.2 % *3, 3 · 9: 29.4 % *3, 3 · 10: 31.8 % *3, 3 · 11: 34.3 % *3, 3 · 12: 37.1 % *3, 3 · 13: 40 % *3, 3"},{"id":"parameter-2","label":"«Сотрудничество»: множитель урона 3-го удара и накопление Воображения","value":"1: 10.3 % *8, 3 · 2: 11.1 % *8, 3 · 3: 12 % *8, 3 · 4: 13 % *8, 3 · 5: 14 % *8, 3 · 6: 15.1 % *8, 3 · 7: 16.3 % *8, 3 · 8: 17.7 % *8, 3 · 9: 19.1 % *8, 3 · 10: 20.6 % *8, 3 · 11: 22.2 % *8, 3 · 12: 24 % *8, 3 · 13: 25.9 % *8, 3"},{"id":"parameter-3","label":"«Сотрудничество»: множитель урона 4-го удара и накопление Воображения","value":"1: 70.2 %, 4 · 2: 75.8 %, 4 · 3: 81.9 %, 4 · 4: 88.4 %, 4 · 5: 95.5 %, 4 · 6: 103.1 %, 4 · 7: 111.4 %, 4 · 8: 120.3 %, 4 · 9: 129.9 %, 4 · 10: 140.3 %, 4 · 11: 151.6 %, 4 · 12: 163.7 %, 4 · 13: 176.8 %, 4"},{"id":"parameter-4","label":"«Сотрудничество»: множитель урона 5-го удара и накопление Воображения","value":"1: 25.8 % *3, 8 · 2: 27.9 % *3, 8 · 3: 30.1 % *3, 8 · 4: 32.5 % *3, 8 · 5: 35.1 % *3, 8 · 6: 37.9 % *3, 8 · 7: 40.9 % *3, 8 · 8: 44.2 % *3, 8 · 9: 47.8 % *3, 8 · 10: 51.6 % *3, 8 · 11: 55.7 % *3, 8 · 12: 60.2 % *3, 8 · 13: 65 % *3, 8"},{"id":"parameter-6","label":"Множитель урона атаки в падении и накопление Воображения","value":"1: 36 %, 2 · 2: 38.9 %, 2 · 3: 42 %, 2 · 4: 45.3 %, 2 · 5: 49 %, 2 · 6: 52.9 %, 2 · 7: 57.1 %, 2 · 8: 61.7 %, 2 · 9: 66.6 %, 2 · 10: 72 %, 2 · 11: 77.7 %, 2 · 12: 83.9 %, 2 · 13: 90.7 %, 2"},{"id":"parameter-7","label":"«Грёза»: множитель урона 1-го удара","value":"1: 36.8 % *3 · 2: 39.7 % *3 · 3: 42.9 % *3 · 4: 46.4 % *3 · 5: 50.1 % *3 · 6: 54.1 % *3 · 7: 58.4 % *3 · 8: 63.1 % *3 · 9: 68.1 % *3 · 10: 73.6 % *3 · 11: 79.4 % *3 · 12: 85.8 % *3 · 13: 92.7 % *3"},{"id":"parameter-8","label":"«Грёза»: множитель урона 2-го удара","value":"1: 88.4 % · 2: 95.5 % · 3: 103.1 % · 4: 111.4 % · 5: 120.3 % · 6: 129.9 % · 7: 140.3 % · 8: 151.5 % · 9: 163.6 % · 10: 176.7 % · 11: 190.8 % · 12: 206.1 % · 13: 222.6 %"},{"id":"parameter-9","label":"«Грёза»: множитель урона 3-го удара","value":"1: 39.8 % · 2: 43 % · 3: 46.4 % · 4: 50.1 % · 5: 54.1 % · 6: 58.5 % · 7: 63.2 % · 8: 68.2 % · 9: 73.7 % · 10: 79.6 % · 11: 85.9 % · 12: 92.8 % · 13: 100.2 %"},{"id":"parameter-11","label":"«Осознанный сон»: множитель урона и затраты Воображения","value":"1: 23.7 % *35, 10 · 2: 25.6 % *35, 10 · 3: 27.6 % *35, 10 · 4: 29.9 % *35, 10 · 5: 32.2 % *35, 10 · 6: 34.8 % *35, 10 · 7: 37.6 % *35, 10 · 8: 40.6 % *35, 10 · 9: 43.9 % *35, 10 · 10: 47.4 % *35, 10 · 11: 51.2 % *35, 10 · 12: 55.3 % *35, 10 · 13: 59.7 % *35, 10"},{"id":"parameter-12","label":"Множитель критического контрудара и накопление Воображения","value":"1: 134 %, 4 · 2: 144.7 %, 4 · 3: 156.3 %, 4 · 4: 168.8 %, 4 · 5: 182.3 %, 4 · 6: 196.9 %, 4 · 7: 212.6 %, 4 · 8: 229.7 %, 4 · 9: 248 %, 4 · 10: 267.9 %, 4 · 11: 289.3 %, 4 · 12: 312.4 %, 4 · 13: 337.4 %, 4"}]},{"id":"GA_Oneiroi_Skill","name":"Непрерывность будущего «я»","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/c0f5c194af00c5c26df1.webp","description":"Расширение самоидентичности\nНажмите кнопку, чтобы применить навык. Ирой призывает ягнят, которые один раз исцеляют всех членов команды и дают им бонус к атаке, зависящий от базового показателя атаки Ирой.\n\nТри ягнёнка атакуют по отдельности, наносят урон анимы и притягивают ближайших врагов.\n\nПри использовании навыка Ирой накапливает Воображение.\n\nНепрерывность будущего «я»\nУдерживайте кнопку, чтобы активировать. Ирой создаёт сновидческие иллюзии во время боя, из-за чего 3 союзника входят в состояние Регрессии и помогают в сражении. Состояние Регрессии автоматически снимается после выхода из боя.\n\nПассивный навык\nПока Ирой находится в команде и ведёт бой, любой павший союзник входит в состояние Регрессии.\n\nИрой накапливает Воображение, когда любой павший союзник входит в состояние Регрессии.\n\nВ ночь перед днём рождения мне нельзя засыпать. Я верю, что если усну, кто-то придёт за мной прежней и оставит вместо неё новую меня, повзрослевшую.","attributes":[{"id":"parameter-0","label":"Навык перенаправления: множитель атаки трёх ягнят","value":"1: 150 % + 17.9 % *7 + 125 % · 2: 162 % + 19.3 % *7 + 135 % · 3: 175 % + 20.9 % *7 + 145.8 % · 4: 189 % + 22.5 % *7 + 157.5 % · 5: 204.1 % + 24.4 % *7 + 170.1 % · 6: 220.4 % + 26.3 % *7 + 183.7 % · 7: 238 % + 28.4 % *7 + 198.4 % · 8: 257.1 % + 30.7 % *7 + 214.2 % · 9: 277.6 % + 33.1 % *7 + 231.4 % · 10: 299.9 % + 35.8 % *7 + 249.9 % · 11: 323.8 % + 38.6 % *7 + 269.9 % · 12: 349.7 % + 41.7 % *7 + 291.5 % · 13: 377.7 % + 45.1 % *7 + 314.8 %"},{"id":"parameter-1","label":"Коэфф. бонуса от базовой атаки Ирой","value":"1: 20 % · 2: 20 % · 3: 20 % · 4: 20 % · 5: 20 % · 6: 20 % · 7: 20 % · 8: 20 % · 9: 20 % · 10: 20 % · 11: 20 % · 12: 20 % · 13: 20 %"},{"id":"parameter-2","label":"Длительность усиления атаки","value":"1: 20 сек. · 2: 20 сек. · 3: 20 сек. · 4: 20 сек. · 5: 20 сек. · 6: 20 сек. · 7: 20 сек. · 8: 20 сек. · 9: 20 сек. · 10: 20 сек. · 11: 20 сек. · 12: 20 сек. · 13: 20 сек."},{"id":"parameter-3","label":"Множитель лечения","value":"1: 94.3 % · 2: 101.8 % · 3: 110 % · 4: 118.8 % · 5: 128.3 % · 6: 138.6 % · 7: 149.6 % · 8: 161.6 % · 9: 174.5 % · 10: 188.5 % · 11: 203.6 % · 12: 219.9 % · 13: 237.5 %"},{"id":"parameter-8","label":"«Регрессия: Морфей — Сладкие сны»: базовый множитель атаки","value":"1: 55.5 % · 2: 59.9 % · 3: 64.7 % · 4: 69.9 % · 5: 75.5 % · 6: 81.5 % · 7: 88.1 % · 8: 95.1 % · 9: 102.7 % · 10: 110.9 % · 11: 119.8 % · 12: 129.4 % · 13: 139.8 %"},{"id":"parameter-9","label":"«Регрессия: Морфей — Глубокий сон»: базовый множитель атаки","value":"1: 41.6 % *5 · 2: 44.9 % *5 · 3: 48.5 % *5 · 4: 52.4 % *5 · 5: 56.6 % *5 · 6: 61.1 % *5 · 7: 66 % *5 · 8: 71.3 % *5 · 9: 77 % *5 · 10: 83.2 % *5 · 11: 89.8 % *5 · 12: 97 % *5 · 13: 104.8 % *5"},{"id":"parameter-10","label":"«Регрессия: Икел — Небольшой укол»: базовый множитель атаки","value":"1: 89.2 % · 2: 96.3 % · 3: 104 % · 4: 112.4 % · 5: 121.4 % · 6: 131.1 % · 7: 141.5 % · 8: 152.9 % · 9: 165.1 % · 10: 178.3 % · 11: 192.6 % · 12: 208 % · 13: 224.6 %"},{"id":"parameter-11","label":"«Регрессия: Икел — Двойная доза»: базовый множитель атаки","value":"1: 178.4 % · 2: 192.7 % · 3: 208.1 % · 4: 224.7 % · 5: 242.7 % · 6: 262.1 % · 7: 283.1 % · 8: 305.7 % · 9: 330.2 % · 10: 356.6 % · 11: 385.2 % · 12: 416 % · 13: 449.2 %"},{"id":"parameter-12","label":"«Регрессия: Фантас — Время колыбельной»: базовый множитель атаки","value":"1: 94.2 % · 2: 101.7 % · 3: 109.9 % · 4: 118.7 % · 5: 128.2 % · 6: 138.4 % · 7: 149.5 % · 8: 161.4 % · 9: 174.4 % · 10: 188.3 % · 11: 203.4 % · 12: 219.6 % · 13: 237.2 %"},{"id":"parameter-13","label":"«Регрессия: Фантас — Фальшь»: базовый множитель атаки","value":"1: 188.4 % · 2: 203.5 % · 3: 219.7 % · 4: 237.3 % · 5: 256.3 % · 6: 276.8 % · 7: 299 % · 8: 322.9 % · 9: 348.7 % · 10: 376.6 % · 11: 406.7 % · 12: 439.3 % · 13: 474.4 %"},{"id":"parameter-14","label":"Регрессия: множитель навыка поддержки ягнят","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"}]},{"id":"GA_Oneiroi_Passive_3","name":"Разделённые 95 миллионами лет","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/fe802a6b5de7c57b3eec.webp","description":"Когда Ирой взаимодействует с мелким животным в открытом мире, она получает случайный предмет развития. Эффект может сработать до 3 раз в день, но не более 999 раз всего.\n\nПо какому пути мне пойти?","attributes":[]},{"id":"GA_Oneiroi_Passive_1","name":"Зеркальное отражение","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/83317b6d64cd28f89adf.webp","description":"Усиление цветения: Создаёт копию Бутона жизни, если текущий Бутон жизни существует уже 3 сек. После исчезновения копии новая копия не создаётся. Копия не учитывается в лимите Бутонов жизни. Копия производит 20 скопированных Пестиков жизни. Каждые 0,5 сек. один скопированный Пестик жизни летит в цель в радиусе поражения и взрывается, нанося 37,5 % от урона оригинального Пестика жизни.\n\nИногда моя тень приходит на место раньше меня.","attributes":[]},{"id":"GA_Oneiroi_UltraSkill","name":"Мираж сроком 3","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/8f61c23ff0a4e43f18fc.webp","description":"Возвращение к первому сну. Ирой открывает врата сна и активирует разные эффекты в зависимости от количества накопленного Воображения.\n\nВоображение ниже порога: Ирой открывает Сон Роговых врат и непрерывно исцеляет всю команду.\n\nВоображение достигло порога: Ирой открывает Сон Слоновых врат, непрерывно исцеляет всю команду и наносит урон анимы врагам внутри сна. Во время действия эффекта нажмите и удерживайте аватар члена команды в состоянии Регрессии, чтобы временно воскресить его и восстановить часть ОЗ. За один сон можно воскресить не более 1 персонажа.\n\nСон непрерывно расходует Воображение. Когда оно заканчивается, сон завершается, а воскрешённый персонаж возвращается в состояние Регрессии.\n\nПока сон активен, Воображение нельзя накапливать, однако применение «Грёзы» и «Осознанного сна» не расходует Воображение.\n\nЯ слышала этот звон на обоих концах сна: один раз в начале, один раз в конце. Но колокол прозвонил лишь единожды. Этот ужасный перезвон преследовал всё живое — от жителей гидротермальных источников в морских глубинах до обитателей небоскрёбов на суше. Ох, он звенит уже 3,8 миллиарда лет.","attributes":[{"id":"parameter-0","label":"Множитель лечения после применения","value":"1: 141.3 % · 2: 152.6 % · 3: 164.8 % · 4: 178 % · 5: 192.3 % · 6: 207.6 % · 7: 224.3 % · 8: 242.2 % · 9: 261.6 % · 10: 282.5 % · 11: 305.1 % · 12: 329.5 % · 13: 355.9 %"},{"id":"parameter-1","label":"Множитель продолжительного лечения","value":"1: 31.4 % · 2: 33.9 % · 3: 36.6 % · 4: 39.6 % · 5: 42.7 % · 6: 46.2 % · 7: 49.9 % · 8: 53.8 % · 9: 58.1 % · 10: 62.8 % · 11: 67.8 % · 12: 73.2 % · 13: 79.1 %"},{"id":"parameter-2","label":"Множитель урона после применения","value":"1: 300 % · 2: 324 % · 3: 349.9 % · 4: 377.9 % · 5: 408.1 % · 6: 440.8 % · 7: 476.1 % · 8: 514.1 % · 9: 555.3 % · 10: 599.7 % · 11: 647.7 % · 12: 699.5 % · 13: 755.5 %"},{"id":"parameter-3","label":"Множитель периодического урона","value":"1: 25 % · 2: 27 % · 3: 29.2 % · 4: 31.5 % · 5: 34 % · 6: 36.7 % · 7: 39.7 % · 8: 42.8 % · 9: 46.3 % · 10: 50 % · 11: 54 % · 12: 58.3 % · 13: 63 %"}]},{"id":"City_Ability_Oneiroi_02","name":"Чат совместной поездки","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/5e7a7f75007b9821b0b6.webp","description":"В «Быстром такси» базовый тариф каждого заказа увеличивается на 1000 фонсов.","attributes":[{"id":"city-0","label":"Уровень 1","value":"В «Быстром такси» базовый тариф каждого заказа увеличивается на 1000 фонсов."},{"id":"city-1","label":"Уровень 2","value":"В «Быстром такси» максимальная удовлетворённость каждого клиента увеличивается на 25 очков."}]},{"id":"City_Ability_Oneiroi_01","name":"Заходите!","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/23e161055b6b5cba8e22.webp","description":"Ирой увеличивает поток на 18.","attributes":[{"id":"city-0","label":"Уровень 1","value":"Ирой увеличивает поток на 18."},{"id":"city-1","label":"Уровень 2","value":"Ирой снижает скорость расхода ингредиентов на 1 %."},{"id":"city-2","label":"Уровень 3","value":"Ирой увеличивает поток на 18."},{"id":"city-3","label":"Уровень 4","value":"Ирой снижает скорость расхода ингредиентов на 1 %."},{"id":"city-4","label":"Уровень 5","value":"Ирой увеличивает поток на 27."}]}]') WHERE character_id='iroi' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 03:56:00');

UPDATE character_profiles SET skins_json=json('[{"id":"Fashion_1075_nighty","name":"Звёздная ночь","description":"Небосвод терял луну целую тысячу раз. И неужели с тех пор прошла лишь тысяча ночей?","imageUrl":"/nte-meta/game-assets/81dec425781f710480c0.webp"},{"id":"Fashion_1075_rpg_level1","name":"Поддержание заклинания…","description":"Магические искры порхают по её рукам, пока Ирой выводит на бумаге первую страницу ещё не дописанного сна.","imageUrl":"/nte-meta/game-assets/bb99f840023dc67aefcd.webp"},{"id":"Fashion_1075_1","name":"Летний сон","description":"Притаившись посреди сочных красок мира грёз, она провожает взглядом уходящие дни долгого лета.","imageUrl":"/nte-meta/game-assets/8fab1c0411d8bf1f442d.webp"},{"id":"Fashion_1075_rpg_level3","name":"Ткач снов","description":"Она вплетает звёзды в ткань сновидений.\n\nПока Ирой спит, тяжесть целой вселенной невесомо покоится на её плечах.","imageUrl":"/nte-meta/game-assets/e1215ec52db11a56b7cb.webp"},{"id":"Fashion_1075_0","name":"Считать овечек","description":"Овцы по своей природе — существа кроткие, и счастливее всего они в своём стаде.","imageUrl":"/nte-meta/game-assets/81ddd061314ee1832a18.webp"},{"id":"Fashion_1075_rpg_level2","name":"Архимаг","description":"Песнопение не смолкает, и границы сна тихонько расширяются ещё на шаг.","imageUrl":"/nte-meta/game-assets/bc2902dca7f0d6b102d4.webp"}]') WHERE character_id='iroi' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 03:56:00');

