UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Отсроченное милосердие","iconUrl":"/nte-meta/game-assets/9a53b8e3c3e7400b0944.webp","description":"Повышает множитель урона Кошмара до 8 % на текущем уровне навыка."},{"level":2,"kind":"awakening","name":"Проснись и пой","iconUrl":"/nte-meta/game-assets/6cb64005b70965ff9375.webp","description":"Увеличивает наносимый Лакримозой урон на 15 % на 15 сек., когда она использует навык поддержки на входе."},{"level":3,"kind":"awakening","name":"Расплавленное мороженое","iconUrl":"/nte-meta/game-assets/ca61ccb66d522b398021.webp","description":"Запускает все накопленные эффекты Кошмара на цели сразу, когда наносится 5-й удар Томатного металла или Томатной перкуссии."},{"level":4,"kind":"awakening","name":"Всемогущий повелитель томатов","iconUrl":"/nte-meta/game-assets/7dc1149a2f674a252c50.webp","description":"Увеличивает длительность Кошмара до 6 сек."},{"level":5,"kind":"awakening","name":"Приговор закалённого стекла","iconUrl":"/nte-meta/game-assets/455f4449722b918d72cb.webp","description":"При нанесении урона Кошмаром уменьшает макс. ОЗ цели на 200 % от нанесённого урона Кошмаром. Каждые 3 сек. восстанавливает свои ОЗ в зависимости от урона Кошмаром, нанесённого за этот период; количество восстановленных ОЗ равно 1,5 % от общего урона Кошмаром. Уровни Кошмара не снимаются при исцелении цели."},{"level":6,"kind":"awakening","name":"Утреннее заклинание","iconUrl":"/nte-meta/game-assets/186dfd3a57790df4ba1f.webp","description":"Позволяет Лакримозе автоматически применить навык поддержки и без накопления энергии цикла запустить соответствующий цикл, когда вы в течение 5 сек. после применения Дьявольского подарка переключаетесь на неё с любого персонажа, способного запустить цикл эспера: «Нова», «Ожог» или «Диссонанс». Срабатывает не чаще 1 раза в 5 сек."},{"level":3,"kind":"resonance","name":"Вялое пламя сердца","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень навыков «Сладкое и кислое», «Утренний томат», «Дьявольский подарок» и «Приговор рабочего дня» на 1. Снижает расход выносливости во время полёта в облике летучей мыши до 85 %."},{"level":6,"kind":"resonance","name":"Колыбельная","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Урон Лакримозы игнорирует 20 % от защиты цели. Снижает расход выносливости во время полёта в облике летучей мыши до 70 %."}]') WHERE character_id='lacrimosa' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 12:51:29');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"ja-Play_Vo_Char_NPC004_greet_004","title":"Спокойной ночи","description":"Стемнело… Спокойной ночи, оценщик.Стемнело… Спокойной ночи, оценщица.","language":"Японский","audioUrl":"/nte-meta/game-audio/d6f6b0c8c3a97c63d844.ogg"},{"id":"en-Play_Vo_Char_NPC004_talk_002","title":"Тема: таймер-помидор","description":"Есть какой-то… «таймер-помидор»… Лакримоза хотела попробовать… Пёсик сказал, таймер-помидор — это не еда… он для работы, делит время на помидоры… «один помидор, два помидора…»\\n Помидор… не для еды, а для работы… Бедный помидор, плохой человек.","language":"Английский","audioUrl":"/nte-meta/game-audio/3b50ac9e0e7fd61b7092.ogg"},{"id":"ja-Play_Vo_Char_NPC004_chat_002","title":"Чат: бессонница","description":"Бес-сон-ни-ца…? Бессонница? Хм-м… «проблемы со сном»? А…? Сон — это легко… просто закрой глаза… хр-р-р…","language":"Японский","audioUrl":"/nte-meta/game-audio/f23e728275c1e4d1a6cb.ogg"},{"id":"ja-Play_Vo_Char_NPC004_Parry_001","title":"Парирование I","description":"Сейчас.","language":"Японский","audioUrl":"/nte-meta/game-audio/46696cffccddd607c46e.ogg"},{"id":"en-Play_Vo_Char_NPC004_about_006","title":"О Ханиэль","description":"«Сетевая подруга с длинным именем» тоже любит «Герцога К»… следим за обновлениями, вместе, весело. Но… никогда не встречались лично… Однажды Лакримоза пыталась встретиться с «Сетевой подругой с длинным именем», но ничего не получилось. Лакримоза пришла не в тот день…","language":"Английский","audioUrl":"/nte-meta/game-audio/caaba1880a0b74e63fbe.ogg"},{"id":"ja-Play_Vo_Char_NPC004_gift_001","title":"Подарок получен I","description":"Лакримозе… очень, очень, очень нравится. Спасибо, оценщик.Лакримозе… очень, очень, очень нравится. Спасибо, оценщица.","language":"Японский","audioUrl":"/nte-meta/game-audio/64a7288cee9b444032b5.ogg"},{"id":"ja-Play_Vo_Char_NPC004_struck_001","title":"Урон I","description":"Ай. Больно…","language":"Японский","audioUrl":"/nte-meta/game-audio/ddbc07378959d8b082bd.ogg"},{"id":"en-Play_Vo_Char_NPC004_self_003","title":"Обо мне: привередливость","description":"Помидоры… Лакримоза любит помидоры… Однажды Лакримоза поднимется с помидорной кровати и заживет своей жизнью в томатном замке. Другая еда не нужна… Разве что мороженое.","language":"Английский","audioUrl":"/nte-meta/game-audio/4821547828132fd58266.ogg"},{"id":"ja-Play_Vo_Char_NPC004_TeammateDown_003","title":"Поражен товарищ по команде – Фадия","description":"Фадия, устала играть?","language":"Японский","audioUrl":"/nte-meta/game-audio/4ca79e1e5e795d532032.ogg"},{"id":"en-Play_Vo_Char_NPC004_skill_002","title":"Навык перенаправления II","description":"Идем.","language":"Английский","audioUrl":"/nte-meta/game-audio/78303cf60288efbd4e33.ogg"},{"id":"en-Play_Vo_Char_NPC004_Switch_003","title":"Переключение III","description":"Меняется смена… теперь можно и отдохнуть.","language":"Английский","audioUrl":"/nte-meta/game-audio/6912779999b41452ed42.ogg"},{"id":"en-Play_Vo_Char_NPC004_ug_002","title":"Вознесение персонажа II","description":"Лакримоза теперь сильнее. Счастлива.","language":"Английский","audioUrl":"/nte-meta/game-audio/6220bc14e91a5065a5d3.ogg"},{"id":"ja-Play_Vo_Char_NPC004_about_002","title":"О Байканге","description":"Работа… стекло… Байканг… плохо…","language":"Японский","audioUrl":"/nte-meta/game-audio/b9d2e3484c6833fe31e2.ogg"},{"id":"ja-Play_Vo_Char_NPC004_self_002","title":"Обо мне: разрушение","description":"Стекло… Враг Лакримозы. Лакримоза всегда врезается в стекло. Человек-ящерица сказал, эм, он заменил стекло… в бюро. Теперь стекло не ломается. И Лакримозе больно.","language":"Японский","audioUrl":"/nte-meta/game-audio/38017a62ff9b589736e4.ogg"},{"id":"ja-Play_Vo_Char_NPC004_skill_002","title":"Навык перенаправления II","description":"Идем.","language":"Японский","audioUrl":"/nte-meta/game-audio/c4222fc0fc5f70dbf5e8.ogg"},{"id":"en-Play_Vo_Char_NPC004_aoe_UI_002","title":"Сверхспособность II","description":"…Лакримоза сердится.","language":"Английский","audioUrl":"/nte-meta/game-audio/d4e4c6f94a31b33d0d69.ogg"},{"id":"en-Play_Vo_Char_NPC004_containment_001","title":"Сдерживание I","description":"Зевок… С работы, дом, кровать, сон…","language":"Английский","audioUrl":"/nte-meta/game-audio/b499bed3643de306ff68.ogg"},{"id":"ja-Play_Vo_Char_NPC004_windfall_002","title":"Неожиданная добыча II","description":"…Хм? Кто это уронил?","language":"Японский","audioUrl":"/nte-meta/game-audio/3dd54d2a49ad212a9e0f.ogg"},{"id":"en-Play_Vo_Char_NPC004_dead_003","title":"Потеря сознания III","description":"Разбуди меня… позже…","language":"Английский","audioUrl":"/nte-meta/game-audio/de7343c4a9c0c196a2a9.ogg"},{"id":"en-Play_Vo_Char_NPC004_windfall_003","title":"Неожиданная добыча III","description":"Что-то нашла… Ах, лучше отдам команде.","language":"Английский","audioUrl":"/nte-meta/game-audio/e4b4124fa9d7287f01a0.ogg"},{"id":"en-Play_Vo_Char_NPC004_windfall_005","title":"Неожиданная добыча V","description":"Кажется… полезным?","language":"Английский","audioUrl":"/nte-meta/game-audio/b5c8ace2b05a74c9eb7b.ogg"},{"id":"ja-Play_Vo_Char_NPC004_deploy_002","title":"Отправка I","description":"…Сделаем это и пойдем домой.","language":"Японский","audioUrl":"/nte-meta/game-audio/a0b81d3296ef06ffb941.ogg"},{"id":"en-Play_Vo_Char_NPC004_hp_002","title":"Низкий уровень здоровья II","description":"Лакримоза устала…","language":"Английский","audioUrl":"/nte-meta/game-audio/2fcb02bc7c8cf4feb686.ogg"},{"id":"en-Play_Vo_Char_NPC004_Parry_001","title":"Парирование I","description":"Сейчас.","language":"Английский","audioUrl":"/nte-meta/game-audio/1c7080ade592a38d1677.ogg"},{"id":"en-Play_Vo_Char_NPC004_vexation_001","title":"Проблемы","description":"Байканг пакостит. Ския бесится. Фадия не помогает, и все ругаются громче и громче… Лакримоза сказала им: «Не обижайте… пёсика…» Байканг и Фадия засмеялись ещё громче… Лакримоза не понимает.","language":"Английский","audioUrl":"/nte-meta/game-audio/fc1e109895503f42bea2.ogg"},{"id":"en-Play_Vo_Char_NPC004_kill_002","title":"Убийство II","description":"Сейчас тихо…","language":"Английский","audioUrl":"/nte-meta/game-audio/dc34b495c34967cbfb0f.ogg"},{"id":"en-Play_Vo_Char_NPC004_QTE_002","title":"Атака на входе II","description":"М-м… вовремя.","language":"Английский","audioUrl":"/nte-meta/game-audio/c1042d5394a532497ca0.ogg"},{"id":"en-Play_Vo_Char_NPC004_talk_003","title":"Тема: потерянные предметы","description":"Где… пропуск… Лакримозы…? А… Сзади… перевернулся. Спасибо…","language":"Английский","audioUrl":"/nte-meta/game-audio/9ca17e94e4426f5cb2bf.ogg"},{"id":"en-Play_Vo_Char_NPC004_weather_004","title":"Жарко","description":"Мороженое… тает… Лакримоза… тает…","language":"Английский","audioUrl":"/nte-meta/game-audio/24a3919603ebafe80cc4.ogg"},{"id":"ja-Play_Vo_Char_NPC004_skill_001","title":"Навык перенаправления I","description":"Апчхи!","language":"Японский","audioUrl":"/nte-meta/game-audio/eb34ebf7efd769db4fff.ogg"},{"id":"en-Play_Vo_Char_NPC004_about_001","title":"Об Альфарде","description":"Директор, холодная, с глазами змеи. Директор приходит, работа приходит. Лакримозе не нравится… но догго говорит, не зли директора.","language":"Английский","audioUrl":"/nte-meta/game-audio/5d2ce82428de7feb8cbc.ogg"},{"id":"en-Play_Vo_Char_NPC004_containment_002","title":"Сдерживание II","description":"Аномалия. Веди себя хорошо.","language":"Английский","audioUrl":"/nte-meta/game-audio/a18717f54756a4fed52e.ogg"},{"id":"en-Play_Vo_Char_NPC004_greet_001","title":"Утреннее приветствие","description":"Оценщик, доброе утро. Лакримоза, злое утро… Работа, раздражает.Оценщица, доброе утро. Лакримоза, злое утро… Работа, раздражает.","language":"Английский","audioUrl":"/nte-meta/game-audio/cc97ae4008210dc674ac.ogg"},{"id":"en-Play_Vo_Char_NPC004_skill_mon_01","title":"Навык перенаправления IV","description":"Лакримоза… может это сделать.","language":"Английский","audioUrl":"/nte-meta/game-audio/e897e737025821f0ff52.ogg"},{"id":"en-Play_Vo_Char_NPC004_windfall_002","title":"Неожиданная добыча II","description":"…Хм? Кто это уронил?","language":"Английский","audioUrl":"/nte-meta/game-audio/56d5454b39be39bc140f.ogg"},{"id":"ja-Play_Vo_Char_NPC004_windfall_004","title":"Неожиданная добыча IV","description":"Нельзя… разбрасываться вещами.","language":"Японский","audioUrl":"/nte-meta/game-audio/9e787b2d69eb4e3e9c22.ogg"},{"id":"ja-Play_Vo_Char_NPC004_about_001","title":"Об Альфарде","description":"Директор, холодная, с глазами змеи. Директор приходит, работа приходит. Лакримозе не нравится… но догго говорит, не зли директора.","language":"Японский","audioUrl":"/nte-meta/game-audio/00e1d5002c9373fd9662.ogg"},{"id":"ja-Play_Vo_Char_NPC004_anomaly_003","title":"Нуллификация I","description":"Ах, исчезло.","language":"Японский","audioUrl":"/nte-meta/game-audio/17273e02c231d86bcf46.ogg"},{"id":"en-Play_Vo_Char_NPC004_anomaly_003","title":"Нуллификация I","description":"Ах, исчезло.","language":"Английский","audioUrl":"/nte-meta/game-audio/7c8eb22224e16e86a4ed.ogg"},{"id":"en-Play_Vo_Char_NPC004_aoe_UI_003","title":"Сверхспособность III","description":"Давайте сегодня все пойдем домой пораньше…","language":"Английский","audioUrl":"/nte-meta/game-audio/dd38e308724e51308273.ogg"},{"id":"en-Play_Vo_Char_NPC004_Fly_001","title":"Планирование I","description":"Осторожнее, стекло.","language":"Английский","audioUrl":"/nte-meta/game-audio/dead93040606a6cfdcba.ogg"},{"id":"en-Play_Vo_Char_NPC004_windfall_006","title":"Неожиданная добыча VI","description":"Лакримоза нашла блестяшку…","language":"Английский","audioUrl":"/nte-meta/game-audio/44c600790aef8da98b12.ogg"},{"id":"ja-Play_Vo_Char_NPC004_chat_003","title":"Чат: манга","description":"Герцог К сильный… Герцог К тоже ломает вещи, и его за это ругают… все, как у Лакримозы.","language":"Японский","audioUrl":"/nte-meta/game-audio/8894a21335c18e7e0c48.ogg"},{"id":"ja-Play_Vo_Char_NPC004_windfall_003","title":"Неожиданная добыча III","description":"Что-то нашла… Ах, лучше отдам команде.","language":"Японский","audioUrl":"/nte-meta/game-audio/b8ae765ac402eabcd593.ogg"},{"id":"en-Play_Vo_Char_NPC004_gift_001","title":"Подарок получен I","description":"Лакримозе… очень, очень, очень нравится. Спасибо, оценщик.Лакримозе… очень, очень, очень нравится. Спасибо, оценщица.","language":"Английский","audioUrl":"/nte-meta/game-audio/4e3937f316374dee7f06.ogg"},{"id":"en-Play_Vo_Char_NPC004_greet_004","title":"Спокойной ночи","description":"Стемнело… Спокойной ночи, оценщик.Стемнело… Спокойной ночи, оценщица.","language":"Английский","audioUrl":"/nte-meta/game-audio/0e201154fc1f2c98a80c.ogg"},{"id":"en-Play_Vo_Char_NPC004_meet_001","title":"Первая встреча","description":"Привет… М-м-м… Ах. Лакримоза не спит. Не спит…","language":"Английский","audioUrl":"/nte-meta/game-audio/bad8585ef4af4f89abf8.ogg"},{"id":"en-Play_Vo_Char_NPC004_ug_003","title":"Вознесение персонажа III","description":"Лакримоза, стала лучше?","language":"Английский","audioUrl":"/nte-meta/game-audio/d06f9270338e195a88c3.ogg"},{"id":"ja-Play_Vo_Char_NPC004_about_007","title":"О Бюро по борьбе с аномалиями","description":"В кафе нет кетчупа, нехорошо… но в торговом автомате есть кетчуп. Лакримоза не будет голодать… Да, и диван очень удобный. Мягкий… Лакримоза может спать на нем. Только бы не попасться.","language":"Японский","audioUrl":"/nte-meta/game-audio/71bb445966f4580d062d.ogg"},{"id":"en-Play_Vo_Char_NPC004_anomaly_004","title":"Нуллификация II","description":"Все закончилось. Пока-пока.","language":"Английский","audioUrl":"/nte-meta/game-audio/48b05c08f09c84fa8809.ogg"},{"id":"en-Play_Vo_Char_NPC004_greet_002","title":"Дневное приветствие","description":"Много… работы… Лакримоза… голодна…","language":"Английский","audioUrl":"/nte-meta/game-audio/a2559dfe065eb8264b2a.ogg"},{"id":"en-Play_Vo_Char_NPC004_self_002","title":"Обо мне: разрушение","description":"Стекло… Враг Лакримозы. Лакримоза всегда врезается в стекло. Человек-ящерица сказал, эм, он заменил стекло… в бюро. Теперь стекло не ломается. И Лакримозе больно.","language":"Английский","audioUrl":"/nte-meta/game-audio/af56537df14cf85c4c00.ogg"},{"id":"en-Play_Vo_Char_NPC004_windfall_001","title":"Неожиданная добыча I","description":"Ой. Что это..?","language":"Английский","audioUrl":"/nte-meta/game-audio/58831e4830918bc754c0.ogg"},{"id":"en-Play_Vo_Char_NPC004_windfall_004","title":"Неожиданная добыча IV","description":"Нельзя… разбрасываться вещами.","language":"Английский","audioUrl":"/nte-meta/game-audio/9e1196f368c2ffdc6186.ogg"},{"id":"ja-Play_Vo_Char_NPC004_anomaly_004","title":"Нуллификация II","description":"Все закончилось. Пока-пока.","language":"Японский","audioUrl":"/nte-meta/game-audio/ae8d3e0549957f9a853b.ogg"},{"id":"ja-Play_Vo_Char_NPC004_SSC_002","title":"Особое переключение — Ския","description":"Песик, нужна помощь?","language":"Японский","audioUrl":"/nte-meta/game-audio/63442eae988fc1ff286d.ogg"},{"id":"ja-Play_Vo_Char_NPC004_talk_003","title":"Тема: потерянные предметы","description":"Где… пропуск… Лакримозы…? А… Сзади… перевернулся. Спасибо…","language":"Японский","audioUrl":"/nte-meta/game-audio/a39ca9446880741fd147.ogg"},{"id":"en-Play_Vo_Char_NPC004_about_005","title":"О Минт","description":"Минт… всегда сияет, легко увидеть… обнимает больше всех… теплая…","language":"Английский","audioUrl":"/nte-meta/game-audio/ae0f832b3b57c9502497.ogg"},{"id":"en-Play_Vo_Char_NPC004_skill_001","title":"Навык перенаправления I","description":"Апчхи!","language":"Английский","audioUrl":"/nte-meta/game-audio/90b1e0dc679938247fe1.ogg"},{"id":"ja-Play_Vo_Char_NPC004_dead_003","title":"Потеря сознания III","description":"Разбуди меня… позже…","language":"Японский","audioUrl":"/nte-meta/game-audio/b3efba899156dbc6ea4a.ogg"},{"id":"ja-Play_Vo_Char_NPC004_fh_001","title":"Исцеление I","description":"Хм-м… перерыв окончен.","language":"Японский","audioUrl":"/nte-meta/game-audio/f0103009333c498c8ddd.ogg"},{"id":"ja-Play_Vo_Char_NPC004_greet_003","title":"Вечернее приветствие","description":"Солнце… похоже на помидор. Круглое. Яркое. Какое оно на вкус…?","language":"Японский","audioUrl":"/nte-meta/game-audio/decf29bc3ade0860b9a7.ogg"},{"id":"en-Play_Vo_Char_NPC004_dead_002","title":"Потеря сознания II","description":"…Глаза не открываются…","language":"Английский","audioUrl":"/nte-meta/game-audio/92a38a2a66df1fb3e99e.ogg"},{"id":"en-Play_Vo_Char_NPC004_SSC_004","title":"Особое переключение — Минт","description":"Не… обижай Минт.","language":"Английский","audioUrl":"/nte-meta/game-audio/5451f1a5795df1867505.ogg"},{"id":"ja-Play_Vo_Char_NPC004_self_001","title":"Обо мне: способности эспера","description":"Способность эспера Лакримозы… Такая… превратить в твёрдый предмет, расплющить плохую аномалию, а затем спать…","language":"Японский","audioUrl":"/nte-meta/game-audio/0c6f47d86d5d249760b2.ogg"},{"id":"en-Play_Vo_Char_NPC004_about_004","title":"О Скии","description":"Догго… пушистый, приятный на ощупь… высокий, быстро ходит, не успеваю… но догго приседает, когда говорит с Лакримозой, так что не нужно смотреть вверх… догго, хороший.","language":"Английский","audioUrl":"/nte-meta/game-audio/218607b39fee0c5d2028.ogg"},{"id":"en-Play_Vo_Char_NPC004_chat_003","title":"Чат: манга","description":"Герцог К сильный… Герцог К тоже ломает вещи, и его за это ругают… все, как у Лакримозы.","language":"Английский","audioUrl":"/nte-meta/game-audio/8319e2374eacd2daa551.ogg"},{"id":"en-Play_Vo_Char_NPC004_greet_003","title":"Вечернее приветствие","description":"Солнце… похоже на помидор. Круглое. Яркое. Какое оно на вкус…?","language":"Английский","audioUrl":"/nte-meta/game-audio/eef5b8a6debc49de6c19.ogg"},{"id":"ja-Play_Vo_Char_NPC004_deploy_001","title":"Отправка II","description":"Пора вставать…?","language":"Японский","audioUrl":"/nte-meta/game-audio/df5a5251626485c2cd69.ogg"},{"id":"ja-Play_Vo_Char_NPC004_SSC_004","title":"Особое переключение — Минт","description":"Не… обижай Минт.","language":"Японский","audioUrl":"/nte-meta/game-audio/b2e8809bdd72b1e67d7d.ogg"},{"id":"en-Play_Vo_Char_NPC004_struck_001","title":"Урон I","description":"Ай. Больно…","language":"Английский","audioUrl":"/nte-meta/game-audio/17f69034042de2ba03ed.ogg"},{"id":"ja-Play_Vo_Char_NPC004_aoe_UI_001","title":"Сверхспособность I","description":"…Оставайся здесь.","language":"Японский","audioUrl":"/nte-meta/game-audio/157905d86b69a71a7566.ogg"},{"id":"ja-Play_Vo_Char_NPC004_greet_002","title":"Дневное приветствие","description":"Много… работы… Лакримоза… голодна…","language":"Японский","audioUrl":"/nte-meta/game-audio/2d94e6de1bca751cf9b3.ogg"},{"id":"ja-Play_Vo_Char_NPC004_hstruck_002","title":"Сильный урон II","description":"Ах…","language":"Японский","audioUrl":"/nte-meta/game-audio/bc2200fa7094567f657f.ogg"},{"id":"ja-Play_Vo_Char_NPC004_QTE_001","title":"Атака на входе I","description":"Лакримоза помогает.","language":"Японский","audioUrl":"/nte-meta/game-audio/e991578a5c25ac9809a6.ogg"},{"id":"en-Play_Vo_Char_NPC004_about_003","title":"О Фадии","description":"Фадия никогда не заставляет Лакримозу работать… хорошо… Фадия всегда щиплет Лакримозу за щеки… плохо…","language":"Английский","audioUrl":"/nte-meta/game-audio/15adf29a36c2a5899478.ogg"},{"id":"en-Play_Vo_Char_NPC004_QTE_001","title":"Атака на входе I","description":"Лакримоза помогает.","language":"Английский","audioUrl":"/nte-meta/game-audio/b2dfc80fff3954fd23bc.ogg"},{"id":"en-Play_Vo_Char_NPC004_DodgeCombo_002","title":"Серия критических уклонений II","description":"Лакримоза… быстрее!","language":"Английский","audioUrl":"/nte-meta/game-audio/bf01753dceb103eac987.ogg"},{"id":"en-Play_Vo_Char_NPC004_gift_002","title":"Подарок получен II","description":"Вау… оценщик… гений в отправке подарков.Вау… оценщица… гений в отправке подарков.","language":"Английский","audioUrl":"/nte-meta/game-audio/fe9d4b79f151ee613fec.ogg"},{"id":"en-Play_Vo_Char_NPC004_SSC_001","title":"Особое переключение — Байканг","description":"Байканг, осторожнее.","language":"Английский","audioUrl":"/nte-meta/game-audio/653a62a3cf3da7c02a0b.ogg"},{"id":"ja-Play_Vo_Char_NPC004_about_003","title":"О Фадии","description":"Фадия никогда не заставляет Лакримозу работать… хорошо… Фадия всегда щиплет Лакримозу за щеки… плохо…","language":"Японский","audioUrl":"/nte-meta/game-audio/e0b14fb51cd6c1340ffa.ogg"},{"id":"en-Play_Vo_Char_NPC004_fh_002","title":"Исцеление II","description":"Лакримоза полна энергии…","language":"Английский","audioUrl":"/nte-meta/game-audio/ebe2f2ddb541295a724f.ogg"},{"id":"ja-Play_Vo_Char_NPC004_gift_004","title":"Подарок получен IV","description":"Этот подарок… Лакримоза будет беречь.","language":"Японский","audioUrl":"/nte-meta/game-audio/1c5009f7cae0c511c7c2.ogg"},{"id":"ja-Play_Vo_Char_NPC004_self_003","title":"Обо мне: привередливость","description":"Помидоры… Лакримоза любит помидоры… Однажды Лакримоза поднимется с помидорной кровати и заживет своей жизнью в томатном замке. Другая еда не нужна… Разве что мороженое.","language":"Японский","audioUrl":"/nte-meta/game-audio/b34b0db6a13d5771f1e7.ogg"},{"id":"ja-Play_Vo_Char_NPC004_talk_002","title":"Тема: таймер-помидор","description":"Есть какой-то… «таймер-помидор»… Лакримоза хотела попробовать… Пёсик сказал, таймер-помидор — это не еда… он для работы, делит время на помидоры… «один помидор, два помидора…»\\n Помидор… не для еды, а для работы… Бедный помидор, плохой человек.","language":"Японский","audioUrl":"/nte-meta/game-audio/0c19ec2324fb2ceaa083.ogg"},{"id":"ja-Play_Vo_Char_NPC004_TeammateDown_001","title":"Поражен товарищ по команде – Байканг","description":"Байканг, спать пока нельзя.","language":"Японский","audioUrl":"/nte-meta/game-audio/08798e4cd6351fbb69af.ogg"},{"id":"en-Play_Vo_Char_NPC004_talk_001","title":"Тема: аномалии","description":"Лакримоза не любит солнце. Но Лакримозе нравится, как солнце пахнет… Пушистик всегда лежит на солнце и вкусно пахнет. Лакримоза любит Пушистика. Лакримоза любит спать с Пушистиком…","language":"Английский","audioUrl":"/nte-meta/game-audio/2fcf175fe3f842dfbc47.ogg"},{"id":"ja-Play_Vo_Char_NPC004_aoe_UI_002","title":"Сверхспособность II","description":"…Лакримоза сердится.","language":"Японский","audioUrl":"/nte-meta/game-audio/eed8e1f2b616c109890e.ogg"},{"id":"ja-Play_Vo_Char_NPC004_aoe_UI_003","title":"Сверхспособность III","description":"Давайте сегодня все пойдем домой пораньше…","language":"Японский","audioUrl":"/nte-meta/game-audio/89c7c1171d4dd503b9e7.ogg"},{"id":"ja-Play_Vo_Char_NPC004_containment_001","title":"Сдерживание I","description":"Зевок… С работы, дом, кровать, сон…","language":"Японский","audioUrl":"/nte-meta/game-audio/9209d584df9acd675656.ogg"},{"id":"ja-Play_Vo_Char_NPC004_DodgeCombo_001","title":"Серия критических уклонений I","description":"Фух, от всех получилось увернуться.","language":"Японский","audioUrl":"/nte-meta/game-audio/294f8d8b95f83a739fd8.ogg"},{"id":"ja-Play_Vo_Char_NPC004_Parry_002","title":"Парирование II","description":"Лакримоза не проиграет.","language":"Японский","audioUrl":"/nte-meta/game-audio/8d4092934f3efb7b4062.ogg"},{"id":"ja-Play_Vo_Char_NPC004_skill_mon_02","title":"Навык перенаправления V","description":"Хм-м.","language":"Японский","audioUrl":"/nte-meta/game-audio/e1151749c257af04b180.ogg"},{"id":"en-Play_Vo_Char_NPC004_TeammateDown_003","title":"Поражен товарищ по команде – Фадия","description":"Фадия, устала играть?","language":"Английский","audioUrl":"/nte-meta/game-audio/6c9826ba9de4e4c10ac8.ogg"},{"id":"ja-Play_Vo_Char_NPC004_dead_002","title":"Потеря сознания II","description":"…Глаза не открываются…","language":"Японский","audioUrl":"/nte-meta/game-audio/5ba6efda444b6687fcf6.ogg"},{"id":"ja-Play_Vo_Char_NPC004_vexation_001","title":"Проблемы","description":"Байканг пакостит. Ския бесится. Фадия не помогает, и все ругаются громче и громче… Лакримоза сказала им: «Не обижайте… пёсика…» Байканг и Фадия засмеялись ещё громче… Лакримоза не понимает.","language":"Японский","audioUrl":"/nte-meta/game-audio/85559e65177352cfbf10.ogg"},{"id":"ja-Play_Vo_Char_NPC004_containment_002","title":"Сдерживание II","description":"Аномалия. Веди себя хорошо.","language":"Японский","audioUrl":"/nte-meta/game-audio/4b9575e3a847648c781f.ogg"},{"id":"ja-Play_Vo_Char_NPC004_skill_003","title":"Навык перенаправления III","description":"Не беги.","language":"Японский","audioUrl":"/nte-meta/game-audio/c9c726098d92b5d476c4.ogg"},{"id":"en-Play_Vo_Char_NPC004_chat_002","title":"Чат: бессонница","description":"Бес-сон-ни-ца…? Бессонница? Хм-м… «проблемы со сном»? А…? Сон — это легко… просто закрой глаза… хр-р-р…","language":"Английский","audioUrl":"/nte-meta/game-audio/7bb8d8edbc70d12dea5b.ogg"},{"id":"en-Play_Vo_Char_NPC004_fh_001","title":"Исцеление I","description":"Хм-м… перерыв окончен.","language":"Английский","audioUrl":"/nte-meta/game-audio/f32d686d00dfdf936556.ogg"},{"id":"ja-Play_Vo_Char_NPC004_chat_001","title":"Чат: естественность","description":"Ой…! Лакримоза… наступила на шнурок… ох. Пол, холодный… удобный.","language":"Японский","audioUrl":"/nte-meta/game-audio/551a2b5a3394ac4ee261.ogg"},{"id":"ja-Play_Vo_Char_NPC004_Fly_001","title":"Планирование I","description":"Осторожнее, стекло.","language":"Японский","audioUrl":"/nte-meta/game-audio/183dfa8cab6076e59b76.ogg"},{"id":"ja-Play_Vo_Char_NPC004_QTE_002","title":"Атака на входе II","description":"М-м… вовремя.","language":"Японский","audioUrl":"/nte-meta/game-audio/10809a47fbd71d7e1fcc.ogg"},{"id":"ja-Play_Vo_Char_NPC004_talk_001","title":"Тема: аномалии","description":"Лакримоза не любит солнце. Но Лакримозе нравится, как солнце пахнет… Пушистик всегда лежит на солнце и вкусно пахнет. Лакримоза любит Пушистика. Лакримоза любит спать с Пушистиком…","language":"Японский","audioUrl":"/nte-meta/game-audio/e0306ed66bc68da536fb.ogg"},{"id":"ja-Play_Vo_Char_NPC004_greet_001","title":"Утреннее приветствие","description":"Оценщик, доброе утро. Лакримоза, злое утро… Работа, раздражает.Оценщица, доброе утро. Лакримоза, злое утро… Работа, раздражает.","language":"Японский","audioUrl":"/nte-meta/game-audio/bfd523867ca7629444