UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Операция целевой группы","iconUrl":"/nte-meta/game-assets/b5f945f829b9698b5486.webp","description":"Сбрасывает перезарядку сверхспособности: Суперкогти, когда «Карамельный хруст» попадает по врагу. Срабатывает только раз в 3 сек."},{"level":2,"kind":"awakening","name":"Повторный осмотр","iconUrl":"/nte-meta/game-assets/05ac14a6997137ce43d1.webp","description":"Урон от навыка перенаправления — сверхспособность «Суперкогти» увеличивается на 40 %."},{"level":3,"kind":"awakening","name":"Бонус за посещаемость","iconUrl":"/nte-meta/game-assets/47391bd7b0073d468836.webp","description":"Когда у любого персонажа срабатывает Цветение или Колдовство против врага, атака Минт увеличивается на 15 % на 15 сек."},{"level":4,"kind":"awakening","name":"Перерыв на обед","iconUrl":"/nte-meta/game-assets/eb0f30c46e4c006553a3.webp","description":"Когда Минт наносит урон последнему противнику на поле боя, увеличивает шанс критического удара Минт на 12 %."},{"level":5,"kind":"awakening","name":"Первый инстинкт","iconUrl":"/nte-meta/game-assets/79bb30d9b7e602cb5c0d.webp","description":"После применения навыка перенаправления — сверхспособность «Суперкогти» крит. урон Минт увеличивается на 25 % на 6 сек."},{"level":6,"kind":"awakening","name":"Элитный участник","iconUrl":"/nte-meta/game-assets/339b9a055f86ecdf5c82.webp","description":"Урон Минт врагам, у которых осталось меньше 40 % ОЗ, увеличивается на 15 %."},{"level":3,"kind":"resonance","name":"Мятный бабл-чай","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень навыков «Идеальное сдерживание», «Сверхспособность: Суперкогти» и «Сверхспособность: Громоудар вихря» на 1."},{"level":6,"kind":"resonance","name":"Пушистый мусс","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"После успешного применения умения «Сверхспособность: Суперкогти» Минт получает дополнительно 2 ед. энергии цикла."}]') WHERE character_id='mint' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-17 20:03:39');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"ja-Play_Vo_Char_NPC001_dead_002","title":"Потеря сознания II","description":"Ветер… прекратился…","language":"Японский","audioUrl":"/nte-meta/game-audio/dd8a30dae94a77575ccd.ogg"},{"id":"ja-Play_Vo_Char_NPC001_self_003","title":"Обо мне: друзья","description":"Когда я провожу время с друзьями, то ощущаю уют и просто заряжаюсь энергией! Как бы я ни была вымотана, немного дружеского тепла… ах… и бам! Я вновь готова на подвиги — вот так!","language":"Японский","audioUrl":"/nte-meta/game-audio/2d06ccd1a07eda84bc41.ogg"},{"id":"ja-Play_Vo_Char_NPC001_SSC_yly_001","title":"Особое переключение: Ирой","description":"Чайана, позволь Минт-сенпай взять всё на себя!","language":"Японский","audioUrl":"/nte-meta/game-audio/b565b5e39d596e0454dc.ogg"},{"id":"ja-Play_Vo_Char_NPC001_gift_004","title":"Подарок получен IV","description":"Надо бы угомонить свой хвост… Он так счастлив, что не перестаёт вилять!","language":"Японский","audioUrl":"/nte-meta/game-audio/ab781f53273a5dae29d3.ogg"},{"id":"ja-Play_Vo_Char_NPC001_QTE","title":"Атака на входе I","description":"Вот оно!","language":"Японский","audioUrl":"/nte-meta/game-audio/35c907a3b2283da968da.ogg"},{"id":"ja-Play_Vo_Char_NPC001_windfall_003","title":"Неожиданная добыча III","description":"Хм-м? Неужели я только что наткнулась на нечто невероятное?","language":"Японский","audioUrl":"/nte-meta/game-audio/6189ee30cae0dd9251cc.ogg"},{"id":"en-Play_Vo_Char_NPC001_DodgeCombo_002","title":"Серия критических уклонений II","description":"Быстрее ветра!","language":"Английский","audioUrl":"/nte-meta/game-audio/0da46d4d4d5601743f5f.ogg"},{"id":"en-Play_Vo_Char_NPC001_talk_001","title":"Тема: аномалии","description":"Тебе случалось задумываться о той рамке, которую мы нуллифицировали вместе? Её Нексус по-прежнему поражает меня. Как будто ей требовалось лишь немного похвалы, чтобы оставить все позади… Заставляет задуматься — вдруг эти странные аномалии просто ищут здесь что-то… удивительно простое.","language":"Английский","audioUrl":"/nte-meta/game-audio/9f5259ecf645cda0cec5.ogg"},{"id":"en-Play_Vo_Char_NPC001_windfall_006","title":"Неожиданная добыча VI","description":"Ага! Ещё один удачный день!..","language":"Английский","audioUrl":"/nte-meta/game-audio/d258c4ba2195f4e8debd.ogg"},{"id":"ja-Play_Vo_Char_NPC001_gift_003","title":"Подарок получен III","description":"Ого, спасибо, Какао!","language":"Японский","audioUrl":"/nte-meta/game-audio/8544021f35c6c2a4f4ff.ogg"},{"id":"ja-Play_Vo_Char_NPC001_greet_003","title":"Вечернее приветствие","description":"Ночная жизнь Этеро — целый новый мир! Хе-хе, я тебе все покажу!","language":"Японский","audioUrl":"/nte-meta/game-audio/1bb0670a4ccc585602af.ogg"},{"id":"ja-Play_Vo_Char_NPC001_meet_001","title":"Первая встреча","description":"Привет, Какао, я Минт, твоя верная помощница из ОС-2. Нужна поддержка? Просто позвони!","language":"Японский","audioUrl":"/nte-meta/game-audio/608f5cb7dc2aba78517d.ogg"},{"id":"ja-Play_Vo_Char_NPC001_TeammateDown_005","title":"Поражён товарищ по команде — Ирой","description":"Чайана, не надрывайся!","language":"Японский","audioUrl":"/nte-meta/game-audio/1d61f0c1221d6db45991.ogg"},{"id":"en-Play_Vo_Char_NPC001_about_007","title":"О Лакримозе","description":"Угадайте, кто здесь Клубничное молоко? Хе-хе, спорю, не сможете — это наша единственная и неповторимая Лакримоза-сенпай! Удивлены? Почему не запах томата? Ну, просто так. И вам не кажется, что мечтательная сенпай отлично сочетается с клубничным молоком?","language":"Английский","audioUrl":"/nte-meta/game-audio/7417b43e57aaef7deab8.ogg"},{"id":"en-Play_Vo_Char_NPC001_QTE_002","title":"Атака на входе II","description":"Осторожно!","language":"Английский","audioUrl":"/nte-meta/game-audio/5e4664c248f24b6145b5.ogg"},{"id":"ja-Play_Vo_Char_NPC001_fh_002","title":"Исцеление II","description":"Минт снова в игре!","language":"Японский","audioUrl":"/nte-meta/game-audio/77d1d61e0cf47f29791c.ogg"},{"id":"ja-Play_Vo_Char_NPC001_skill_002","title":"Навык перенаправления II","description":"Убирайся с дороги!","language":"Японский","audioUrl":"/nte-meta/game-audio/3e246ccda704b17e3fb8.ogg"},{"id":"ja-Play_Vo_Char_NPC001_windfall_004","title":"Неожиданная добыча IV","description":"Спасибо ветрам, что указывают путь!","language":"Японский","audioUrl":"/nte-meta/game-audio/753094d2e6480cf6978e.ogg"},{"id":"ja-Play_Vo_Char_NPC001_windfall_005","title":"Неожиданная добыча V","description":"Столько добра, что карманы лопаются!","language":"Японский","audioUrl":"/nte-meta/game-audio/f50c745de637d022e330.ogg"},{"id":"en-Play_Vo_Char_NPC001_kill_001","title":"Убийство I","description":"Те, кто меня недооценивают, дорого заплатят за это.","language":"Английский","audioUrl":"/nte-meta/game-audio/62c509b6fa2a4e37f09b.ogg"},{"id":"en-Play_Vo_Char_NPC001_about_005","title":"О Наналли","description":"Наналли тайком взяла высокоуровневое поручение и вместе с Сакири и Эдгаром пробралась в дико опасное аномальное измерение! По её словам, они были на волоске от гибели! Хорошо ещё, что у неё был тот приём — «Предельный Теневой Пустотный Удар Колуччи», иначе живыми бы они оттуда не выбрались! Потом она на какое-то время пропала — говорят, что Хотори за это посадила её под домашний арест… Эх, гениев никогда не ценят по достоинству.","language":"Английский","audioUrl":"/nte-meta/game-audio/c5a0c1fbd6b09c2950f0.ogg"},{"id":"en-Play_Vo_Char_NPC001_kill_002","title":"Убийство II","description":"У тебя неприятный запах.","language":"Английский","audioUrl":"/nte-meta/game-audio/01e9ff554560361dafae.ogg"},{"id":"ja-Play_Vo_Char_NPC001_gift_001","title":"Подарок получен I","description":"Какао знает меня лучше всех!","language":"Японский","audioUrl":"/nte-meta/game-audio/502f34e84364f207aa24.ogg"},{"id":"ja-Play_Vo_Char_NPC001_QTE_002","title":"Атака на входе II","description":"Осторожно!","language":"Японский","audioUrl":"/nte-meta/game-audio/f2a3303015b517966997.ogg"},{"id":"ja-Play_Vo_Char_NPC001_vexation_001","title":"Проблемы","description":"Снова провалила экзамен… Если так пойдет дальше, могу лишиться зарплаты! Я выучила все правила, но текст на экзамене такой сложный, что все вылетело из головы!","language":"Японский","audioUrl":"/nte-meta/game-audio/f89e479b93085d11ff46.ogg"},{"id":"en-Play_Vo_Char_NPC001_greet_001","title":"Утреннее приветствие","description":"Доброе утро! С-с-с… отлично, Сила Какао! Полный заряд!","language":"Английский","audioUrl":"/nte-meta/game-audio/d143db404b1f50269f2c.ogg"},{"id":"en-Play_Vo_Char_NPC001_weather_004","title":"Жарко","description":"Какая жара… Когда вернусь, подам заявление на премию за работу в такую погоду!","language":"Английский","audioUrl":"/nte-meta/game-audio/7094dfa92b3daaf44950.ogg"},{"id":"en-Play_Vo_Char_NPC001_greet_002","title":"Дневное приветствие","description":"Если не можешь решить, что съесть, пойдем со мной на Танцующие такояки в «Будорию»! Но напомни, чтобы я вначале на них подула!","language":"Английский","audioUrl":"/nte-meta/game-audio/24259bcdbb747af303d5.ogg"},{"id":"en-Play_Vo_Char_NPC001_TeammateDown_002","title":"Поражен товарищ по команде – Лакримоза","description":"Лакримоза-сенпай, тебе нужно отдохнуть!","language":"Английский","audioUrl":"/nte-meta/game-audio/5105f8998a266d43a88d.ogg"},{"id":"ja-Play_Vo_Char_NPC001_about_011","title":"Об ОС","description":"Поначалу работа в отряде сдерживания казалась мне американскими горками. Я постоянно попадала в неприятности, но старички были со мной, смеялись над моими слезами, но задерживались, чтобы помочь. Моя цель — стать надежным и жизнерадостным сердцем команды, такой же крепкой, как любой Элитный исполнитель!","language":"Японский","audioUrl":"/nte-meta/game-audio/6c83e59c98a793213f47.ogg"},{"id":"ja-Play_Vo_Char_NPC001_hstruck_002","title":"Сильный урон II","description":"…Соберись, соберись…","language":"Японский","audioUrl":"/nte-meta/game-audio/8b33f5404ef6517e4e6f.ogg"},{"id":"ja-Play_Vo_Char_NPC001_Parry_002","title":"Парирование II","description":"Смотри!","language":"Японский","audioUrl":"/nte-meta/game-audio/729481cc013873cf440b.ogg"},{"id":"ja-Play_Vo_Char_NPC001_TeammateDown_001","title":"Поражен товарищ по команде – Ноль","description":"Какао! Ты слишком на себя давишь!","language":"Японский","audioUrl":"/nte-meta/game-audio/d878eb06fa454e61dc21.ogg"},{"id":"en-Play_Vo_Char_NPC001_containment_001","title":"Сдерживание I","description":"Ладно, давай вставим эту штуку… Ух! Ф-фух! Весь день работы может пойти насмарку! Нужно быть осторожнее…","language":"Английский","audioUrl":"/nte-meta/game-audio/39d18416a213256ac2c8.ogg"},{"id":"en-Play_Vo_Char_NPC001_dead_002","title":"Потеря сознания II","description":"Ветер… прекратился…","language":"Английский","audioUrl":"/nte-meta/game-audio/54b0fb2f34be197824fd.ogg"},{"id":"en-Play_Vo_Char_NPC001_greet_003","title":"Вечернее приветствие","description":"Ночная жизнь Этеро — целый новый мир! Хе-хе, я тебе все покажу!","language":"Английский","audioUrl":"/nte-meta/game-audio/1ff6ba1acbb83f86727f.ogg"},{"id":"ja-Play_Vo_Char_NPC001_chat_002","title":"Чат: мороженое","description":"«Снежок» выпустил новое мороженое! Не терпится попробовать его после миссии!","language":"Японский","audioUrl":"/nte-meta/game-audio/2e533da030aee7ff2f62.ogg"},{"id":"ja-Play_Vo_Char_NPC001_SSC_001","title":"Особое переключение — Ноль","description":"Я здесь, Какао!","language":"Японский","audioUrl":"/nte-meta/game-audio/f05c686130419cc2037b.ogg"},{"id":"en-Play_Vo_Char_NPC001_hstruck_002","title":"Сильный урон II","description":"…Соберись, соберись…","language":"Английский","audioUrl":"/nte-meta/game-audio/68cbc08c2995dd92c8e8.ogg"},{"id":"en-Play_Vo_Char_NPC001_meet_001","title":"Первая встреча","description":"Привет, Какао, я Минт, твоя верная помощница из ОС-2. Нужна поддержка? Просто позвони!","language":"Английский","audioUrl":"/nte-meta/game-audio/b88af0caff4dda1fecad.ogg"},{"id":"ja-Play_Vo_Char_NPC001_aoe_UI_001","title":"Сверхспособность I","description":"Осторожнее, не моргай!","language":"Японский","audioUrl":"/nte-meta/game-audio/b068802ba6c2938d5882.ogg"},{"id":"en-Play_Vo_Char_NPC001_fh_002","title":"Исцеление II","description":"Минт снова в игре!","language":"Английский","audioUrl":"/nte-meta/game-audio/3f0d4f890d4680488871.ogg"},{"id":"ja-Play_Vo_Char_NPC001_TeammateDown_002","title":"Поражен товарищ по команде – Лакримоза","description":"Лакримоза-сенпай, тебе нужно отдохнуть!","language":"Японский","audioUrl":"/nte-meta/game-audio/bf0fb1f9f1c8d43ed61c.ogg"},{"id":"en-Play_Vo_Char_NPC001_SSC_006","title":"Особое переключение — Наналли","description":"Почетный член семьи Колуччи спешит на помощь!","language":"Английский","audioUrl":"/nte-meta/game-audio/41fa78a1a2a2ed815f83.ogg"},{"id":"en-Play_Vo_Char_NPC001_Fly_002","title":"Планирование II","description":"Верхом на ветре!","language":"Английский","audioUrl":"/nte-meta/game-audio/f52fbe3b5eddf71138cb.ogg"},{"id":"ja-Play_Vo_Char_NPC001_chat_001","title":"Чат: табель успеваемости","description":"Я снова провалилась? У-у-у… Мне сказали, я сдам, если надену этот амулет…","language":"Японский","audioUrl":"/nte-meta/game-audio/2530ec32e7587eb34eb7.ogg"},{"id":"ja-Play_Vo_Char_NPC001_containment_001","title":"Сдерживание I","description":"Ладно, давай вставим эту штуку… Ух! Ф-фух! Весь день работы может пойти насмарку! Нужно быть осторожнее…","language":"Японский","audioUrl":"/nte-meta/game-audio/3db875c59ec4774106a0.ogg"},{"id":"en-Play_Vo_Char_NPC001_about_009","title":"О ТОИ","description":"«Каждый человек — целая армия». Разве не захватывающе? ТОИ — не только для чудаков. Это крутые и необычные люди, но это не значит, что они не могут быть милыми!","language":"Английский","audioUrl":"/nte-meta/game-audio/7f3b47240f84372cb82a.ogg"},{"id":"ja-Play_Vo_Char_NPC001_hp_001","title":"Низкий уровень здоровья I","description":"Ах… Я устала…","language":"Японский","audioUrl":"/nte-meta/game-audio/7b045da3fdb8e4ff29a7.ogg"},{"id":"ja-Play_Vo_Char_NPC001_skill_003","title":"Навык перенаправления III","description":"Стой на своем!","language":"Японский","audioUrl":"/nte-meta/game-audio/e4a5ca06e3e41e3d0139.ogg"},{"id":"ja-Play_Vo_Char_NPC001_about_003","title":"Об Альфарде","description":"Директор такая страшная! Только учую ее, и мех на хвосте встает дыбом! А если встречусь с ней взглядом… Ой! Ужас! Лучше неделю буду работать на выездах летом, чем пойду к ней в офис!","language":"Японский","audioUrl":"/nte-meta/game-audio/8f7d03db3292531399b6.ogg"},{"id":"en-Play_Vo_Char_NPC001_gift_002","title":"Подарок получен II","description":"Мне очень нравится, Какао!","language":"Английский","audioUrl":"/nte-meta/game-audio/867c723eb417556869b8.ogg"},{"id":"ja-Play_Vo_Char_NPC001_TeammateDown_003","title":"Поражен товарищ по команде – Фадия","description":"Фадия-сенпай! Какая бешеная одержимость… может, немного сбавить обороты?","language":"Японский","audioUrl":"/nte-meta/game-audio/553279afc56fe1715306.ogg"},{"id":"ja-Play_Vo_Char_NPC001_TeammateDown_004","title":"Поражен товарищ по команде – Наналли","description":"Это ты вредишь боссу Колуччи! Минт не позволит тебе уйти!","language":"Японский","audioUrl":"/nte-meta/game-audio/00890b79383404459c03.ogg"},{"id":"en-Play_Vo_Char_NPC001_weather_003","title":"Холодно","description":"С такой погодой я скоро превращусь в ходячую и говорящую грелку для рук сенпая…","language":"Английский","audioUrl":"/nte-meta/game-audio/06438a2017e9d26e5bd0.ogg"},{"id":"ja-Play_Vo_Char_NPC001_anomaly_004","title":"Нуллификация II","description":"По сравнению с экзаменами это легкотня.","language":"Японский","audioUrl":"/nte-meta/game-audio/9f23399ef47cdee4fe90.ogg"},{"id":"ja-Play_Vo_Char_NPC001_kill_002","title":"Убийство II","description":"У тебя неприятный запах.","language":"Японский","audioUrl":"/nte-meta/game-audio/a719cfe497ad87b5184c.ogg"},{"id":"en-Play_Vo_Char_NPC001_Fly_001","title":"Планирование I","description":"Ю-ху!","language":"Английский","audioUrl":"/nte-meta/game-audio/cdf344ce6443f1491e57.ogg"},{"id":"en-Play_Vo_Char_NPC001_ug_002","title":"Вознесение персонажа II","description":"Теперь я слышу шепот ветра яснее.","language":"Английский","audioUrl":"/nte-meta/game-audio/608772a9d85c2366db81.ogg"},{"id":"ja-Play_Vo_Char_NPC001_dead_001","title":"Потеря сознания I","description":"Если бы я только… была немного быстрее…","language":"Японский","audioUrl":"/nte-meta/game-audio/b2e495c187c23ea587b4.ogg"},{"id":"en-Play_Vo_Char_NPC001_about_008","title":"Об антикварном магазине Эйбон","description":"«Эйбон» — активные ребята, в душе все они — одна большая и дружная семья! Уверена, «Эйбон» станет для тебя отличным домом!","language":"Английский","audioUrl":"/nte-meta/game-audio/b2d3ae0480ac746cebd9.ogg"},{"id":"en-Play_Vo_Char_NPC001_SSC_005","title":"Особое переключение — Фадия","description":"Фадия-сенпай! Я постараюсь наслаждаться боем, как ты!","language":"Английский","audioUrl":"/nte-meta/game-audio/87c64cc6f2f51764fc11.ogg"},{"id":"en-Play_Vo_Char_NPC001_struck_002","title":"Урон II","description":"Следующего раза не будет!","language":"Английский","audioUrl":"/nte-meta/game-audio/27b11f012b0b93528ae4.ogg"},{"id":"ja-Play_Vo_Char_NPC001_containment_002","title":"Сдерживание II","description":"Ладно, давай вставим эту штуку… ух! Главное — не уронить! А то лишусь премии!","language":"Японский","audioUrl":"/nte-meta/game-audio/076713874102899ab7c9.ogg"},{"id":"en-Play_Vo_Char_NPC001_about_006","title":"Об Адлере","description":"Господин Адлер? Надежный и уверенный! Всегда придет на помощь, как коллега, который протянет тебе новый карандаш именно в тот момент, когда выясняется, что твой остался дома, а экзамен уже начался. Как там называется этот запах? Господин Адлер говорил мне… А, да, кедр!","language":"Английский","audioUrl":"/nte-meta/game-audio/32303f279e459ef3c488.ogg"},{"id":"en-Play_Vo_Char_NPC001_talk_002","title":"Тема: изысканная еда","description":"Хочется есть, но не знаешь, что выбрать? Положись на меня! Я — твой главный гид по самым вкусным местам Этеро: от прославленных заведений до секретных уличных закусочных. Дорогие рестораны? Пока мало что знаю… но подожди! Моя карьера в ББА пойдёт в гору, и скоро я стану королевой гурманов всего города!","language":"Английский","audioUrl":"/nte-meta/game-audio/df10d3b8b7192d8b4441.ogg"},{"id":"ja-Play_Vo_Char_NPC001_fh_001","title":"Исцеление I","description":"Ф-фух…! Я жива!","language":"Японский","audioUrl":"/nte-meta/game-audio/7332c79c285804331f9e.ogg"},{"id":"ja-Play_Vo_Char_NPC001_gift_002","title":"Подарок получен II","description":"Мне очень нравится, Какао!","language":"Японский","audioUrl":"/nte-meta/game-audio/42a2aa10827895b2ab2b.ogg"},{"id":"ja-Play_Vo_Char_NPC001_Switch_003","title":"Переключение III","description":"Ура!","language":"Японский","audioUrl":"/nte-meta/game-audio/6074f4ad88f36a801c3c.ogg"},{"id":"en-Play_Vo_Char_NPC001_about_002","title":"О Хотори","description":"Хотори-сенпай? Я… я ничего не знаю! А-а-а… Дело не в том, что я плохой друг, я просто не хочу, чтобы меня вывели из «Эйбона» за ухо в следующий раз… Самое трудное в этом мире — сдавать экзамены и врать ей! Она видит все насквозь!","language":"Английский","audioUrl":"/nte-meta/game-audio/2da5e330a765ee23b046.ogg"},{"id":"en-Play_Vo_Char_NPC001_dead_003","title":"Потеря сознания III","description":"Извините… Я опять всех задержала…","language":"Английский","audioUrl":"/nte-meta/game-audio/35b9c4d7c4c229f39520.ogg"},{"id":"en-Play_Vo_Char_NPC001_Parry_001","title":"Парирование I","description":"Есть!","language":"Английский","audioUrl":"/nte-meta/game-audio/86457061d6f03c70cfe4.ogg"},{"id":"en-Play_Vo_Char_NPC001_windfall_005","title":"Неожиданная добыча V","description":"Столько добра, что карманы лопаются!","language":"Английский","audioUrl":"/nte-meta/game-audio/d02e826a3035625e46c6.ogg"},{"id":"ja-Play_Vo_Char_NPC001_about_009","title":"О ТОИ","description":"«Каждый человек — целая армия». Разве не захватывающе? ТОИ — не только для чудаков. Это крутые и необычные люди, но это не значит, что они не могут быть милыми!","language":"Японский","audioUrl":"/nte-meta/game-audio/5cc21413fe43594967ab.ogg"},{"id":"ja-Play_Vo_Char_NPC001_anomaly_003","title":"Нуллификация I","description":"Отлично, на шаг ближе к тому, чтобы стать надежной сенпай!","language":"Японский","audioUrl":"/nte-meta/game-audio/4bb4b4e23f3161e8e171.ogg"},{"id":"en-Play_Vo_Char_NPC001_self_001","title":"Обо мне: способности эспера","description":"Я как-то услышала, что мои товарищи в беседе с Лавандой сказали, будто я «как летний бриз на свидании» — растрёпанные волосы, а на лице улыбка, настоящий парадокс. Как думаешь, Какао? Это ведь комплимент, да?","language":"Английский","audioUrl":"/nte-meta/game-audio/8a1413f24cb6d484461f.ogg"},{"id":"en-Play_Vo_Char_NPC001_about_011","title":"Об ОС","description":"Поначалу работа в отряде сдерживания казалась мне американскими горками. Я постоянно попадала в неприятности, но старички были со мной, смеялись над моими слезами, но задерживались, чтобы помочь. Моя цель — стать надежным и жизнерадостным сердцем команды, такой же крепкой, как любой Элитный исполнитель!","language":"Английский","audioUrl":"/nte-meta/game-audio/903d7b29e448d831a48f.ogg"},{"id":"en-Play_Vo_Char_NPC001_hp_003","title":"Низкий уровень здоровья III","description":"А? Почему я вижу звезды?","language":"Английский","audioUrl":"/nte-meta/game-audio/f26ca555892e1397dbd8.ogg"},{"id":"en-Play_Vo_Char_NPC001_aoe_UI_002","title":"Сверхспособность II","description":"А вот и вихрь!","language":"Английский","audioUrl":"/nte-meta/game-audio/bbe450fc49d14d5522ab.ogg"},{"id":"en-Play_Vo_Char_NPC001_Switch_002","title":"Переключение II","description":"Все сделаю!","language":"Английский","audioUrl":"/nte-meta/game-audio/4726c5a698ee174e51ad.ogg"},{"id":"ja-Play_Vo_Char_NPC001_deploy_001","title":"Отправка I","description":"Итак, на сцене Первоклассный сдерживатель!","language":"Японский","audioUrl":"/nte-meta/game-audio/a8efc8f3608f6a64610a.ogg"},{"id":"ja-Play_Vo_Char_NPC001_SSC_003","title":"Особое переключение — Байканг","description":"Я тебя не подведу, Байканг-сенпай!","language":"Японский","audioUrl":"/nte-meta/game-audio/8cfc814155dd338f5bf6.ogg"},{"id":"ja-Play_Vo_Char_NPC001_windfall_001","title":"Неожиданная добыча I","description":"Эм, ничего такого. Легче легкого.","language":"Японский","audioUrl":"/nte-meta/game-audio/b14c236d3cf6cfb2eb3a.ogg"},{"id":"ja-Play_Vo_Char_NPC001_Fly_002","title":"Планирование II","description":"Верхом на ветре!","language":"Японский","audioUrl":"/nte-meta/game-audio/2d6219821bbc72c16400.ogg"},{"id":"en-Play_Vo_Char_NPC001_SSC_001","title":"Особое переключение — Ноль","description":"Я здесь, Какао!","language":"Английский","audioUrl":"/nte-meta/game-audio/7313d1a767e7ca822b28.ogg"},{"id":"ja-Play_Vo_Char_NPC001_dead_003","title":"Потеря сознания III","description":"Извините… Я опять всех задержала…","language":"Японский","audioUrl":"/nte-meta/game-audio/fa393161c89bdbea8605.ogg"},{"id":"ja-Play_Vo_Char_NPC001_greet_001","title":"Утреннее приветствие","description":"Доброе утро! С-с-с… отлично, Сила Какао! Полный заряд!","language":"Японский","audioUrl":"/nte-meta/game-audio/f20ce5876a97aea202a2.ogg"},{"id":"ja-Play_Vo_Char_NPC001_hstruck_001","title":"Сильный урон I","description":"Ай!","language":"Японский","audioUrl":"/nte-meta/game-audio/0ac2b8b44c3cda2f180a.ogg"},{"id":"en-Play_Vo_Char_NPC001_about_010","title":"О Бюро по борьбе с аномалиями","description":"Поболтать с коллегами — вот что самое лучшее! Мы в Бюро по борьбе с аномалиями решаем сверхважные вопросы, но все мы люди — жалуемся на непослушных детей или слишком большие счета. Маленькие радости, такие как дополнительный выходной или внезапный чай с молоком от руководителя группы, способны поднять настроение на весь день!","language":"Английский","audioUrl":"/nte-meta/game-audio/573d3101069faf55c4f1.ogg"},{"id":"en-Play_Vo_Char_NPC001_dead_001","title":"Потеря сознания I","description":"Если бы я только… была немного быстрее…","language":"Английский","audioUrl":"/nte-meta/game-audio/1b9cfb0b0009fb787603.ogg"},{"id":"en-Play_Vo_Char_NPC001_windfall_003","title":"Неожиданная добыча III","description":"Хм-м? Неужели я только что наткнулась на нечто невероятное?","language":"Английский","audioUrl":"/nte-meta/game-audio/e9d93c30f16df42cfdde.ogg"},{"id":"ja-Play_Vo_Char_NPC001_kill_001","title":"Убийство I","description":"Те, кто меня недооценивают, дорого заплатят за это.","language":"Японский","audioUrl":"/nte-meta/game-audio/f660430efaecfb349fa5.ogg"},{"id":"en-Play_Vo_Char_NPC001_anomaly_004","title":"Нуллификация II","description":"По сравнению с экзаменами это легкотня.","language":"Английский","audioUrl":"/nte-meta/game-audio/c88d961b373e48b041e1.ogg"},{"id":"ja-Play_Vo_Char_NPC001_about_010","title":"О Бюро по борьбе с аномалиями","description":"Поболтать с коллегами — вот что самое лучшее! Мы в Бюро по борьбе с аномалиями решаем сверхважные вопросы, но все мы люди — жалуемся на непослушных детей или слишком большие счета. Маленькие радости, такие как дополнительный выходной или внезапный чай с молоком от руководителя группы, способны поднять настроение на весь день!","language":"Японский","audioUrl":"/nte-meta/game-audio/ab769c8ec0219568270e.ogg"},{"id":"ja-Play_Vo_Char_NPC001_aoe_UI_004","title":"Сверхспособность IV","description":"Сможешь угнаться за ветром?","language":"Японский","audioUrl":"/nte-meta/game-audio/6f1708e7a3b24c52a945.ogg"},{"id":"ja-Play_Vo_Char_NPC001_SSC_005","title":"Особое переключение — Фадия","description":"Фадия-сенпай! Я постараюсь наслаждаться боем, как ты!","language":"Японский","audioUrl":"/nte-meta/game-audio/b89230845867dabf00c6.ogg"},{"id":"ja-Play_Vo_Char_NPC001_weather_004","title":"Жарко","description":"Какая жара… Когда вернусь, подам заявление на премию за работу в такую погоду!","language":"Японский","audioUrl":"/nte-meta/game-audio/dfa0821a1531ec498517.ogg"},{"id":"en-Play_Vo_Char_NPC001_QTE","title":"Атака на входе I","description":"Вот оно!","language":"Английский","audioUrl":"/nte-meta/game-audio/7bc6f41df141c5863227.ogg"},{"id":"ja-Play_Vo_Char_NPC001_hobby_001","title":"Хобби","description":"Что мне нравится? Шопинг! Эм… звучит так себе. Неважно! Я люблю разглядывать витрины и открывать для себя новые места. Ещё лучше поболтать с хозяином магазина и другими покупателями! Хе-хе… хочешь со мной в следующий раз? Тебя ждет много интересного!","language":"Японский","audioUrl":"/nte-meta/game-audio/9b982f611caac28f707c.ogg"},{"id":"ja-Play_Vo_Char_NPC001_hp_002","title":"Низкий уровень здоровья II","description":"Ой… дело принимает серьезный оборот!","language":"Японский","audioUrl":"/nte-meta/game-audio/e11034bacb99f6362bd5.ogg"},{"id":"ja-Play_Vo_Char_NPC001_struck_002","title":"Урон II","description":"Следующего раза не будет!","language":"Японский","audioUrl":"/nte-meta/game-audio/b389d5d2425f5b22e0b5.ogg"},{"id":"ja-Play_Vo_Char_NPC001_skill_001","title":"Навык перенаправления I","description":"Не сомневайся во мне!","language":"Японский","audioUrl":"/nte-meta/game-audio/b3c6cc454a9b76da5298.ogg"},{"id":"en-Play_Vo_Char_NPC001_fh_001","title":"Исцеление I","description":"Ф-фух…! Я жива!","language":"Английский","audioUrl":"/nte-meta/game-audio/503e1982d5328519cf46.ogg"},{"id":"en-Play_Vo_Char_NPC001_self_002","title":"Обо мне: нэкодзита","description":"Каждый раз, когда заказываю рамен или такояки, говорю себе: «Не ешь горячим!» Но потом кто-то начинает беседу, и — бац! Я забываю и — ой — снова обожглась! А-а-а… Даже ты смеёшься, Какао…","language":"Английский","audioUrl":"/nte-meta/game-audio/47535a30c38871ae6b5f.ogg"},{"id":"en-Play_Vo_Char_NPC001_struck_001","title":"Урон I","description":"Т-с… ошибочка.","language":"Английский","audioUrl":"/nte-meta/game-audio/33b87069f18aa5a384b7.ogg"},{"id":"ja-Play_Vo_Char_NPC001_about_001","title":"О Нелли","description":"Лаванда просто ПОТРЯСАЮЩАЯ — поддерживает идеальный порядок и следит за расписанием директора. И она всегда так добра ко мне, даже несмотря на плотный график! Конечно, было бы лучше, если бы она перестала «случайно проходить мимо» каждый раз, когда я опаздываю!","language":"Японский","audioUrl":"/nte-meta/game-audio/1641e99ecb69f9cf491e.ogg"},{"id":"ja-Play_Vo_Char_NPC001_about_007","title":"О Лакримозе","description":"Угадайте, кто здесь Клубничное молоко? Хе-хе, спорю, не сможете — это наша единственная и неповторимая Лакримоза-сенпай! Удивлены? Почему не запах томата? Ну, просто так. И вам не кажется, что мечтательная сенпай отлично сочетается с клубничным молоком?","language":"Японский","audioUrl":"/nte-meta/game-audio/e155b3cdaa5aee01b6bd.ogg"},{"id":"ja-Play_Vo_Char_NPC001_talk_002","title":"Тема: изысканная еда","description":"Хочется есть, но не знаешь, что выбрать? Положись на меня! Я — твой главный гид по самым вкусным местам Этеро: от прославленных заведений до секретных уличных закусочных. Дорогие рестораны? Пока мало что знаю… но подожди! Моя карьера в ББА пойдёт в гору, и скоро я стану королевой гурманов всего города!","language":"Японский","audioUrl":"/nte-meta/game-audio/3685755546a466bc2141.ogg"},{"id":"en-Play_Vo_Char_NPC001_chat_003","title":"Чат: информация","description":"Брифинг по этой операции сдерживания отправлен по эл. почте… Ой… столько страниц…","language":"Английский","audioUrl":"/nte-meta/game-audio/4f55cb63f97f48b6788c.ogg"},{"id":"en-Play_Vo_Char_NPC001_TeammateDown_003","title":"Поражен товарищ по команде – Фадия","description":"Фадия-сенпай! Какая бешеная одержимость… может, немного сбавить обороты?","language":"Английский","audioUrl":"/nte-meta/game-audio/f8b21979b876af90751c.ogg"},{"id":"en-Play_Vo_Char_NPC001_ug_003","title":"Вознесение персонажа III","description":"Это Минт! Первоклассный сдерживатель!","language":"Английский","audioUrl":"/nte-meta/game-audio/ab039e73ef9e0b5465a5.ogg"},{"id":"en-Play_Vo_Char_NPC001_windfall_004","title":"Неожиданная добыча IV","description":"Спасибо ветрам, что указывают путь!","language":"Английский","audioUrl":"/nte-meta/game-audio/ceda3f6ccb857f321bf4.ogg"},{"id":"ja-Play_Vo_Char_NPC001_DodgeCombo_002","title":"Серия критических уклонений II","description":"Быстрее ветра!","language":"Японский","audioUrl":"/nte-meta/game-audio/e5d2a35ecbed8efaee56.ogg"},{"id":"ja-Play_Vo_Char_NPC001_weather_003","title":"Холодно","description":"С такой погодой я скоро превращусь в ходячую и говорящую грелку для рук сенпая…","language":"Японский","audioUrl":"/nte-meta/game-audio/cec5e36bd6545ead1372.ogg"},{"id":"en-Play_Vo_Char_NPC001_QTE_003","title":"Атака на входе III","description":"Хочешь охладиться?","language":"Английский","audioUrl":"/nte-meta/game-audio/f88dabf9ae15a03093da.ogg"},{"id":"ja-Play_Vo_Char_NPC001_self_002","title":"Обо мне: нэкодзита","description":"Каждый раз, когда заказываю рамен или такояки, говорю себе: «Не ешь горячим!» Но потом кто-то начинает беседу, и — бац! Я забываю и — ой — снова обожглась! А-а-а… Даже ты смеёшься, Какао…","language":"Японский","audioUrl":"/nte-meta/game-audio/d721be179ffded5bb15b.ogg"},{"id":"en-Play_Vo_Char_NPC001_aoe_UI_003","title":"Сверхспособность III","description":"Сверхспособность Минт: Супер дупер ультра 360 удар вихря!","language":"Английский","audioUrl":"/nte-meta/game-audio/b7828a9972f4bcb0ca75.ogg"},{"id":"ja-Play_Vo_Char_NPC001_about_006","title":"Об Адлере","description":"Господин Адлер? Надежный и уверенный! Всегда придет на помощь, как коллега, который протянет тебе новый карандаш именно в тот момент, когда выясняется, что твой остался дома, а экзамен уже начался. Как там называется этот запах? Господин Адлер говорил мне… А, да, кедр!","language":"Японский","audioUrl":"/nte-meta/game-audio/9da6213a252783bc5b8d.ogg"},{"id":"en-Play_Vo_Char_NPC001_aoe_UI_004","title":"Сверхспособность IV","description":"Сможешь угнаться за ветром?","language":"Английский","audioUrl":"/nte-meta/game-audio/e58aa4457463eb238a3d.ogg"},{"id":"en-Play_Vo_Char_NPC001_self_003","title":"Обо мне: друзья","description":"Когда я провожу время с друзьями, то ощущаю уют и просто заряжаюсь энергией! Как бы я ни была вымотана, немного дружеского тепла… ах… и бам! Я вновь готова на подвиги — вот так!","language":"Английский","audioUrl":"/nte-meta/game-audio/559ea73dd1de8f417386.ogg"},{"id":"ja-Play_Vo_Char_NPC001_self_001","title":"Обо мне: способности эспера","description":"Я как-то услышала, что мои товарищи в беседе с Лавандой сказали, будто я «как летний бриз на свидании» — растрёпанные волосы, а на лице улыбка, настоящий парадокс. Как думаешь, Какао? Это ведь комплимент, да?","language":"Японский","audioUrl":"/nte-meta/game-audio/3f7f85e12df0c5a8d8e3.ogg"},{"id":"en-Play_Vo_Char_NPC001_about_001","title":"О Нелли","description":"Лаванда просто ПОТРЯСАЮЩАЯ — поддерживает идеальный порядок и следит за расписанием директора. И она всегда так добра ко мне, даже несмотря на плотный график! Конечно, было бы лучше, если бы она перестала «случайно проходить мимо» каждый раз, когда я опаздываю!","language":"Английский","audioUrl":"/nte-meta/game-audio/7294780210d947645908.ogg"},{"id":"en-Play_Vo_Char_NPC001_vexation_001","title":"Проблемы","description":"Снова провалила экзамен… Если так пойдет дальше, могу лишиться зарплаты! Я выучила все правила, но текст на экзамене такой сложный, что все вылетело из головы!","language":"Английский","audioUrl":"/nte-meta/game-audio/4b8e34caf2d89a843aac.ogg"},{"id":"ja-Play_Vo_Char_NPC001_SSC_004","title":"Особое переключение — Ския","description":"Я постараюсь, Ския-сенпай!","language":"Японский","audioUrl":"/nte-meta/game-audio/d978113fcd07bd522b16.ogg"},{"id":"en-Play_Vo_Char_NPC001_containment_002","title":"Сдерживание II","description":"Ладно, давай вставим эту штуку… ух! Главное — не уронить! А то лишусь премии!","language":"Английский","audioUrl":"/nte-meta/game-audio/699ca422ebd03b52bd49.ogg"},{"id":"ja-Play_Vo_Char_NPC001_greet_002","title":"Дневное приветствие","description":"Если не можешь решить, что съесть, пойдем со мной на Танцующие такояки в «Будорию»! Но напомни, чтобы я вначале на них подула!","language":"Японский","audioUrl":"/nte-meta/game-audio/d3ba5dca7bdf55d6bf5e.ogg"},{"id":"ja-Play_Vo_Char_NPC001_talk_001","title":"Тема: аномалии","description":"Тебе случалось задумываться о той рамке, которую мы нуллифицировали вместе? Её Нексус по-прежнему поражает меня. Как будто ей требовалось лишь немного похвалы, чтобы оставить все позади… Заставляет задуматься — вдруг эти странные аномалии просто ищут здесь что-то… удивительно простое.","language":"Японский","audioUrl":"/nte-meta/game-audio/5932eebda9ce7e6d3f01.ogg"},{"id":"ja-Play_Vo_Char_NPC001_TeammateDown_006","title":"Поражён товарищ по команде – Шинку","description":"Тая, ты опять себя загоняешь!","language":"Японский","audioUrl":"/nte-meta/game-audio/d718600f15c26ca2aa9a.ogg"},{"id":"ja-Play_Vo_Char_NPC001_windfall_006","title":"Неожиданная добыча VI","description":"Ага! Ещё один удачный день!..","language":"Японский","audioUrl":"/nte-meta/game-audio/50c3df965514301c9fd7.ogg"},{"id":"en-Play_Vo_Char_NPC001_skill_001","title":"Навык перенаправления I","description":"Не сомневайся во мне!","language":"Английский","audioUrl":"/nte-meta/game-audio/4accd24c7630f3f6ac2e.ogg"},{"id":"en-Play_Vo_Char_NPC001_Switch_003","title":"Переключение III","description":"Ура!","language":"Английский","audioUrl":"/nte-meta/game-audio/bcd0b787a4fe2bb66e67.ogg"},{"id":"en-Play_Vo_Char_NPC001_skill_002","title":"Навык перенаправления II","description":"Убирайся с дороги!","language":"Английский","audioUrl":"/nte-meta/game-audio/fc7849e26b63bba60db1.ogg"},{"id":"en-Play_Vo_Char_NPC001_gift_003","title":"Подарок получен III","description":"Ого, спасибо, Какао!","language":"Английский","audioUrl":"/nte-meta/game-audio/655c887ca8b0b60df87d.ogg"},{"id":"en-Play_Vo_Char_NPC001_weather_001","title":"Солнечно","description":"М-м-м, какой день! Идеален для работы в городе… то есть для самого настоящего патруля. Никакого безделья, обещаю!","language":"Английский","audioUrl":"/nte-meta/game-audio/52cad68ae93b2ce10b3b.ogg"},{"id":"ja-Play_Vo_Char_NPC001_about_008","title":"Об антикварном магазине Эйбон","description":"«Эйбон» — активные ребята, в душе все они — одна большая и дружная семья! Уверена, «Эйбон» станет для тебя отличным домом!","language":"Японский","audioUrl":"/nte-meta/game-audio/0125d2e7fdf0c587bbca.ogg"},{"id":"en-Play_Vo_Char_NPC001_gift_004","title":"Подарок получен IV","description":"Надо бы угомонить свой хвост… Он так счастлив, что не перестаёт вилять!","language":"Английский","audioUrl":"/nte-meta/game-audio/c5a139c0b2860e489a52.ogg"},{"id":"en-Play_Vo_Char_NPC001_Parry_002","title":"Парирование II","description":"Смотри!","language":"Английский","audioUrl":"/nte-meta/game-audio/b7fc320161bac52da0e6.ogg"},{"id":"ja-Play_Vo_Char_NPC001_Fly_001","title":"Планирование I","description":"Ю-ху!","language":"Японский","audioUrl":"/nte-meta/game-audio/ebfe93a71e42c5b2805e.ogg"},{"id":"en-Play_Vo_Char_NPC001_deploy_001","title":"Отправка I","description":"Итак, на сцене Первоклассный сдерживатель!","language":"Английский","audioUrl":"/nte-meta/game-audio/ad00b45d5cc9beaaec6c.ogg"},{"id":"ja-Play_Vo_Char_NPC001_SSC_zh_001","title":"Особое переключение — Шинку","description":"Тая, я здесь, чтобы помочь!","language":"Японский","audioUrl":"/nte-meta/game-audio/ade8987be84b581a1802.ogg"},{"id":"ja-Play_Vo_Char_NPC001_weather_002","title":"Дождливо","description":"Ах… От дождя шерсть на хвосте слипается…","language":"Японский","audioUrl":"/nte-meta/game-audio/3cf1af1c55f187efcdc6.ogg"},{"id":"en-Play_Vo_Char_NPC001_chat_002","title":"Чат: мороженое","description":"«Снежок» выпустил новое мороженое! Не терпится попробовать его после миссии!","language":"Английский","audioUrl":"/nte-meta/game-audio/3ffb51293c4540a06c6c.ogg"},{"id":"en-Play_Vo_Char_NPC001_hobby_001","title":"Хобби","description":"Что мне нравится? Шопинг! Эм… звучит так себе. Неважно! Я люблю разглядывать витрины и открывать для себя новые места. Ещё лучше поболтать с хозяином магазина и другими покупателями! Хе-хе… хочешь со мной в следующий раз? Тебя ждет много интересного!","language":"Английский","audioUrl":"/nte-meta/game-audio/31b357dc7c98fd1efde3.ogg"},{"id":"en-Play_Vo_Char_NPC001_skill_003","title":"Навык перенаправления III","description":"Стой на своем!","language":"Английский","audioUrl":"/nte-meta/game-audio/bc34435a70371829662b.ogg"},{"id":"en-Play_Vo_Char_NPC001_weather_002","title":"Дождливо","description":"Ах… От дождя шерсть на хвосте слипается…","language":"Английский","audioUrl":"/nte-meta/game-audio/f425f049be5476938886.ogg"},{"id":"ja-Play_Vo_Char_NPC001_SSC_006","title":"Особое переключение — Наналли","description":"Почетный член семьи Колуччи спешит на помощь!","language":"Японский","audioUrl":"/nte-meta/game-audio/00523fd474c802febb54.ogg"},{"id":"ja-Play_Vo_Char_NPC001_ug_001","title":"Вознесение персонажа I","description":"Бам! Новая и улучшенная Минт!","language":"Японский","audioUrl":"/nte-meta/game-audio/a0205dc6c05c705deb03.ogg"},{"id":"en-Play_Vo_Char_NPC001_about_003","title":"Об Альфарде","description":"Директор такая страшная! Только учую ее, и мех на хвосте встает дыбом! А если встречусь с ней взглядом… Ой! Ужас! Лучше неделю буду работать на выездах летом, чем пойду к ней в офис!","language":"Английский","audioUrl":"/nte-meta/game-audio/cdc84cbd3b07ee7bcc3a.ogg"},{"id":"en-Play_Vo_Char_NPC001_DodgeCombo_001","title":"Серия критических уклонений I","description":"Ого! Вот это я молодец!","language":"Английский","audioUrl":"/nte-meta/game-audio/d281059ae36890e3504a.ogg"},{"id":"en-Play_Vo_Char_NPC001_greet_004","title":"Спокойной ночи","description":"Ой, уже так поздно? А я полна сил!","language":"Английский","audioUrl":"/nte-meta/game-audio/3ef9ed81c25484059e7b.ogg"},{"id":"ja-Play_Vo_Char_NPC001_talk_003","title":"Тема: удача, кроме экзаменов","description":"Вот, возьми эту газировку! Только что получила бутылку бесплатно! В последнее время удача на моей стороне — однажды даже выиграла ваучер на обед в «Будории»! И почему мне так не везет на экзаменах? Что ж, сенпаи списывают все на Закон сохранения удачи…","language":"Японский","audioUrl":"/nte-meta/game-audio/f2960e8ad4ba09204593.ogg"},{"id":"en-Play_Vo_Char_NPC001_hp_001","title":"Низкий уровень здоровья I","description":"Ах… Я устала…","language":"Английский","audioUrl":"/nte-meta/game-audio/dbb7fa113b8667ed403d.ogg"},{"id":"en-Play_Vo_Char_NPC001_ug_001","title":"Вознесение персонажа I","description":"Бам! Новая и улучшенная Минт!","language":"Английский","audioUrl":"/nte-meta/game-audio/624f1898eab17def12fc.ogg"},{"id":"ja-Play_Vo_Char_NPC001_Parry_001","title":"Парирование I","description":"Есть!","language":"Японский","audioUrl":"/nte-meta/game-audio/73608e974a09fdd9bf29.ogg"},{"id":"ja-Play_Vo_Char_NPC001_windfall_002","title":"Неожиданная добыча II","description":"Хех, везет как никогда!","language":"Японский","audioUrl":"/nte-meta/game-audio/ae83f474204f5f814754.ogg"},{"id":"en-Play_Vo_Char_NPC001_chat_001","title":"Чат: табель успеваемости","description":"Я снова провалилась? У-у-у… Мне сказали, я сдам, если надену этот амулет…","language":"Английский","audioUrl":"/nte-meta/game-audio/cefc050fbc58a42f8df0.ogg"},{"id":"en-Play_Vo_Char_NPC001_windfall_002","title":"Неожиданная добыча II","description":"Хех, везет как никогда!","language":"Английский","audioUrl":"/nte-meta/game-audio/953aa87d88ab6c799689.ogg"},{"id":"ja-Play_Vo_Char_NPC001_aoe_UI_003","title":"Сверхспособность III","description":"Сверхспособность Минт: Супер дупер ультра 360 удар вихря!","language":"Японский","audioUrl":"/nte-meta/game-audio/1652aec61c7a49b26467.ogg"},{"id":"ja-Play_Vo_Char_NPC001_about_004","title":"О Тайгедо","description":"Тайгедо — мой самый верный союзник. Мы пообещали поддерживать друг друга в Дневнике супергероя и подняться на вершину таблицы лидеров! Нужно тренироваться, чтобы стать сильнее, так? Ой, это напомнило мне о той эпической ночной гонке на пятьдесят кругов… что нас опять задержало?","language":"Японский","audioUrl":"/nte-meta/game-audio/c35f9a298dc689d1ce8c.ogg"},{"id":"en-Play_Vo_Char_NPC001_hp_002","title":"Низкий уровень здоровья II","description":"Ой… дело принимает серьезный оборот!","language":"Английский","audioUrl":"/nte-meta/game-audio/3c847b3fe88585ba2214.ogg"},{"id":"ja-Play_Vo_Char_NPC001_SSC_002","title":"Особое переключение — Лакримоза","description":"Игрок Минт заменяет Лакримозу-сенпай!","language":"Японский","audioUrl":"/nte-meta/game-audio/5e194c99d2d888f77a5d.ogg"},{"id":"ja-Play_Vo_Char_NPC001_ug_002","title":"Вознесение персонажа II","description":"Теперь я слышу шепот ветра яснее.","language":"Японский","audioUrl":"/nte-meta/game-audio/ec08d205eee69996da52.ogg"},{"id":"en-Play_Vo_Char_NPC001_about_004","title":"О Тайгедо","description":"Тайгедо — мой самый верный союзник. Мы пообещали поддерживать друг друга в Дневнике супергероя и подняться на вершину таблицы лидеров! Нужно тренироваться, чтобы стать сильнее, так? Ой, это напомнило мне о той эпической ночной гонке на пятьдесят кругов… что нас опять задержало?","language":"Английский","audioUrl":"/nte-meta/game-audio/bc31948baab5262838b8.ogg"},{"id":"en-Play_Vo_Char_NPC001_TeammateDown_001","title":"Поражен товарищ по команде – Ноль","description":"Какао! Ты слишком на себя давишь!","language":"Английский","audioUrl":"/nte-meta/game-audio/9825a524495ac9af7e93.ogg"},{"id":"ja-Play_Vo_Char_NPC001_hp_003","title":"Низкий уровень здоровья III","description":"А? Почему я вижу звезды?","language":"Японский","audioUrl":"/nte-meta/game-audio/9d4e9a66d668fb4506f7.ogg"},{"id":"en-Play_Vo_Char_NPC001_hstruck_001","title":"Сильный урон I","description":"Ай!","language":"Английский","audioUrl":"/nte-meta/game-audio/438a4f5f8a9012c70557.ogg"},{"id":"en-Play_Vo_Char_NPC001_SSC_004","title":"Особое переключение — Ския","description":"Я постараюсь, Ския-сенпай!","language":"Английский","audioUrl":"/nte-meta/game-audio/0f9eed0664a0abc57ebe.ogg"},{"id":"ja-Play_Vo_Char_NPC001_about_002","title":"О Хотори","description":"Хотори-сенпай? Я… я ничего не знаю! А-а-а… Дело не в том, что я плохой друг, я просто не хочу, чтобы меня вывели из «Эйбона» за ухо в следующий раз… Самое трудное в этом мире — сдавать экзамены и врать ей! Она видит все насквозь!","language":"Японский","audioUrl":"/nte-meta/game-audio/50f691141e2f6cd75b44.ogg"},{"id":"ja-Play_Vo_Char_NPC001_aoe_UI_002","title":"Сверхспособность II","description":"А вот и вихрь!","language":"Японский","audioUrl":"/nte-meta/game-audio/b001e190d6cab33df267.ogg"},{"id":"ja-Play_Vo_Char_NPC001_ug_003","title":"Вознесение персонажа III","description":"Это Минт! Первоклассный сдерживатель!","language":"Японский","audioUrl":"/nte-meta/game-audio/ff2ea819566a15852940.ogg"},{"id":"en-Play_Vo_Char_NPC001_SSC_002","title":"Особое переключение — Лакримоза","description":"Игрок Минт заменяет Лакримозу-сенпай!","language":"Английский","audioUrl":"/nte-meta/game-audio/53b56d0ce2e2bf7dda93.ogg"},{"id":"en-Play_Vo_Char_NPC001_windfall_001","title":"Неожиданная добыча I","description":"Эм, ничего такого. Легче легкого.","language":"Английский","audioUrl":"/nte-meta/game-audio/c884cd46ef79d2a32b9d.ogg"},{"id":"ja-Play_Vo_Char_NPC001_Switch_002","title":"Переключение II","description":"Все сделаю!","language":"Японский","audioUrl":"/nte-meta/game-audio/122ec09b908afe85540b.ogg"},{"id":"en-Play_Vo_Char_NPC001_gift_001","title":"Подарок получен I","description":"Какао знает меня лучше всех!","language":"Английский","audioUrl":"/nte-meta/game-audio/160c9bafa0dd6619d35a.ogg"},{"id":"en-Play_Vo_Char_NPC001_SSC_003","title":"Особое переключение — Байканг","description":"Я тебя не подведу, Байканг-сенпай!","language":"Английский","audioUrl":"/nte-meta/game-audio/220dd875a758f33ca182.ogg"},{"id":"en-Play_Vo_Char_NPC001_talk_003","title":"Тема: удача, кроме экзаменов","description":"Вот, возьми эту газировку! Только что получила бутылку бесплатно! В последнее время удача на моей стороне — однажды даже выиграла ваучер на обед в «Будории»! И почему мне так не везет на экзаменах? Что ж, сенпаи списывают все на Закон сохранения удачи…","language":"Английский","audioUrl":"/nte-meta/game-audio/2347613e91f481d82d58.ogg"},{"id":"ja-Play_Vo_Char_NPC001_DodgeCombo_001","title":"Серия критических уклонений I","description":"Ого! Вот это я молодец!","language":"Японский","audioUrl":"/nte-meta/game-audio/770105d77d4f13fad105.ogg"},{"id":"en-Play_Vo_Char_NPC001_deploy_002","title":"Отправка II","description":"Хех, вперед!","language":"Английский","audioUrl":"/nte-meta/game-audio/23375b4eca6237d17b8a.ogg"},{"id":"ja-Play_Vo_Char_NPC001_deploy_002","title":"Отправка II","description":"Хех, вперед!","language":"Японский","audioUrl":"/nte-meta/game-audio/6e822cdee4b1cd4d1541.ogg"},{"id":"en-Play_Vo_Char_NPC001_anomaly_003","title":"Нуллификация I","description":"Отлично, на шаг ближе к тому, чтобы стать надежной сенпай!","language":"Английский","audioUrl":"/nte-meta/game-audio/d909ac7524f0cfe30a12.ogg"},{"id":"ja-Play_Vo_Char_NPC001_about_005","title":"О Наналли","description":"Наналли тайком взяла высокоуровневое поручение и вместе с Сакири и Эдгаром пробралась в дико опасное аномальное измерение! По её словам, они были на волоске от гибели! Хорошо ещё, что у неё был тот приём — «Предельный Теневой Пустотный Удар Колуччи», иначе живыми бы они оттуда не выбрались! Потом она на какое-то время пропала — говорят, что Хотори за это посадила её под домашний арест… Эх, гениев никогда не ценят по достоинству.","language":"Японский","audioUrl":"/nte-meta/game-audio/7e31355c5cfebc2605f7.ogg"},{"id":"en-Play_Vo_Char_NPC001_TeammateDown_004","title":"Поражен товарищ по команде – Наналли","description":"Это ты вредишь боссу Колуччи! Минт не позволит тебе уйти!","language":"Английский","audioUrl":"/nte-meta/game-audio/ee19455d2bc853d205ef.ogg"},{"id":"ja-Play_Vo_Char_NPC001_chat_003","title":"Чат: информация","description":"Брифинг по этой операции сдерживания отправлен по эл. почте… Ой… столько страниц…","language":"Японский","audioUrl":"/nte-meta/game-audio/f8fc4e1b77fc0ed69c86.ogg"},{"id":"en-Play_Vo_Char_NPC001_aoe_UI_001","title":"Сверхспособность I","description":"Осторожнее, не моргай!","language":"Английский","audioUrl":"/nte-meta/game-audio/b59463d01e756e677904.ogg"},{"id":"en-Play_Vo_Char_NPC001_Switch_001","title":"Переключение I","description":"Я здесь, чтобы помочь!","language":"Английский","audioUrl":"/nte-meta/game-audio/924d5d0f815d6816e00d.ogg"},{"id":"ja-Play_Vo_Char_NPC001_greet_004","title":"Спокойной ночи","description":"Ой, уже так поздно? А я полна сил!","language":"Японский","audioUrl":"/nte-meta/game-audio/79d5bb2d3d55e393d6cb.ogg"},{"id":"ja-Play_Vo_Char_NPC001_QTE_003","title":"Атака на входе III","description":"Хочешь охладиться?","language":"Японский","audioUrl":"/nte-meta/game-audio/8bb2d4fb9779a3fadd49.ogg"},{"id":"ja-Play_Vo_Char_NPC001_struck_001","title":"Урон I","description":"Т-с… ошибочка.","language":"Японский","audioUrl":"/nte-meta/game-audio/83654e21e71a532fbc08.ogg"},{"id":"ja-Play_Vo_Char_NPC001_Switch_001","title":"Переключение I","description":"Я здесь, чтобы помочь!","language":"Японский","audioUrl":"/nte-meta/game-audio/6cf5aa0117bab5593696.ogg"},{"id":"ja-Play_Vo_Char_NPC001_weather_001","title":"Солнечно","description":"М-м-м, какой день! Идеален для работы в городе… то есть для самого настоящего патруля. Никакого безделья, обещаю!","language":"Японский","audioUrl":"/nte-meta/game-audio/1f37da38947b73c5e029.ogg"}]') WHERE character_id='mint' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-17 20:03:39');

UPDATE character_profiles SET abilities_json=json('[{"id":"6ce9ed1e-6b90-4800-b61d-c8d2093083b3","name":"Идеальное сдерживание","type":"Базовая атака","iconUrl":"https://ntewiki.org/images/characters/source/Mint/Mint_Melee.png","description":"Проводит до 5 последовательных атак своим оружием, нанося урон анимы.\n\nБазовые значения:\nКоэфф. 1-го экземпляра: 10.4％+23.1％\\nКоэфф. 2-го экземпляра: 17％\\nКоэфф. 3-го экземпляра: 26.2％+34.1％\\nКоэфф. 4-го экземпляра: 18.4％\\nКоэфф. 5-го экземпляра: 25.5％+52.3％\\nКоэффициент урона пике: 65％\\nЭнергия циклов: 19\\nПоказатель критического контрудара: 174％\\nКоэфф. урона прыжка: 28.3％×3+46.7％\\n長押し通常攻撃ダメージ倍率: Каждый экземпляр: 13.3％\\n通常攻撃を長押すると、毎秒：38\\n通常攻撃を長押すると、: 6сек.","attributes":[{"id":"parameter-0","label":"Множитель 1-го удара","value":"1: 10.4 %+23.1 % · 2: 11.2 %+24.9 % · 3: 12.1 %+26.9 % · 4: 13.1 %+29.1 % · 5: 14.1 %+31.4 % · 6: 15.3 %+33.9 % · 7: 16.5 %+36.7 % · 8: 17.8 %+39.6 % · 9: 19.2 %+42.8 % · 10: 20.8 %+46.2 % · 11: 22.5 %+49.9 % · 12: 24.2 %+53.9 % · 13: 26.2 %+58.2 %"},{"id":"parameter-1","label":"Множитель 2-го удара","value":"1: 17 % · 2: 18.4 % · 3: 19.8 % · 4: 21.4 % · 5: 23.1 % · 6: 25 % · 7: 27 % · 8: 29.1 % · 9: 31.5 % · 10: 34 % · 11: 36.7 % · 12: 39.6 % · 13: 42.8 %"},{"id":"parameter-2","label":"Множитель 3-го удара","value":"1: 26.2 %+34.1 % · 2: 28.3 %+36.8 % · 3: 30.6 %+39.8 % · 4: 33 %+43 % · 5: 35.6 %+46.4 % · 6: 38.5 %+50.1 % · 7: 41.6 %+54.1 % · 8: 44.9 %+58.4 % · 9: 48.5 %+63.1 % · 10: 52.4 %+68.2 % · 11: 56.6 %+73.6 % · 12: 61.1 %+79.5 % · 13: 66 %+85.9 %"},{"id":"parameter-3","label":"Множитель 4-го удара","value":"1: 18.4 % · 2: 19.9 % · 3: 21.5 % · 4: 23.2 % · 5: 25 % · 6: 27 % · 7: 29.2 % · 8: 31.5 % · 9: 34.1 % · 10: 36.8 % · 11: 39.7 % · 12: 42.9 % · 13: 46.3 %"},{"id":"parameter-4","label":"Множитель 5-го удара","value":"1: 25.5 %+52.3 % · 2: 27.5 %+56.5 % · 3: 29.7 %+61 % · 4: 32.1 %+65.9 % · 5: 34.7 %+71.2 % · 6: 37.5 %+76.8 % · 7: 40.5 %+83 % · 8: 43.7 %+89.6 % · 9: 47.2 %+96.8 % · 10: 51 %+104.5 % · 11: 55.1 %+112.9 % · 12: 59.5 %+121.9 % · 13: 64.2 %+131.7 %"},{"id":"parameter-5","label":"Множитель урона атаки в падении","value":"1: 65 % · 2: 70.2 % · 3: 75.8 % · 4: 81.9 % · 5: 88.4 % · 6: 95.5 % · 7: 103.1 % · 8: 111.4 % · 9: 120.3 % · 10: 129.9 % · 11: 140.3 % · 12: 151.6 % · 13: 163.7 %"},{"id":"parameter-7","label":"Множитель критического контрудара","value":"1: 174 % · 2: 187.9 % · 3: 203 % · 4: 219.2 % · 5: 236.7 % · 6: 255.7 % · 7: 276.1 % · 8: 298.2 % · 9: 322.1 % · 10: 347.8 % · 11: 375.7 % · 12: 405.7 % · 13: 438.2 %"},{"id":"parameter-8","label":"Множитель урона прыжка","value":"1: 28.3 %*3+46.7 % · 2: 30.6 %*3+50.4 % · 3: 33 %*3+54.5 % · 4: 35.6 %*3+58.8 % · 5: 38.5 %*3+63.5 % · 6: 41.6 %*3+68.6 % · 7: 44.9 %*3+74.1 % · 8: 48.5 %*3+80 % · 9: 52.4 %*3+86.4 % · 10: 56.6 %*3+93.4 % · 11: 61.1 %*3+100.8 % · 12: 66 %*3+108.9 % · 13: 71.3 %*3+117.6 %"},{"id":"parameter-9","label":"Множитель урона базовой атаки при удержании","value":"1: Каждый удар: 13.3 % · 2: Каждый удар: 14.4 % · 3: Каждый удар: 15.5 % · 4: Каждый удар: 16.8 % · 5: Каждый удар: 18.1 % · 6: Каждый удар: 19.5 % · 7: Каждый удар: 21.1 % · 8: Каждый удар: 22.8 % · 9: Каждый удар: 24.6 % · 10: Каждый удар: 26.6 % · 11: Каждый удар: 28.7 % · 12: Каждый удар: 31 % · 13: Каждый удар: 33.5 %"}]},{"id":"GA_Mint_Passive_1","name":"Трансформируйся! Супер Минт!","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/b2c3ea75404debed679b.webp","description":"Усиление цветения: расширяет область урона Пестиков жизни при ударе.\n\n«Теперь смотри внимательно! Я уже не та, что раньше! Теперь ты лицом к лицу с элитным оперативником!»","attributes":[]},{"id":"GA_Mint_Passive_3","name":"Базовая атака: Мятный вихрь","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/43eec181782723b7199b.webp","description":"Удерживайте базовую атаку, чтобы Минт танцевала и вращалась, формируя торнадо, который непрерывно снижает выносливость и постоянно наносит урон анимы окружающим врагам.","attributes":[]},{"id":"50d4353d-8b31-4764-81e3-63a97968b45c","name":"Сверхспособность: Суперкогти","type":"Навык","iconUrl":"https://ntewiki.org/images/characters/source/Mint/Mint_Skill.png","description":"Пора остудить пыл! Совершает рывок вперед с возвратом в исходную позицию, нанося 2 экземпляра урона анимы по области всем врагам на пути.\n\nБазовые значения:\nКоэфф. урона: 90％×2\\nЭнергия циклов: 5","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 90 %*2 · 2: 97.2 %*2 · 3: 105 %*2 · 4: 113.4 %*2 · 5: 122.4 %*2 · 6: 132.2 %*2 · 7: 142.8 %*2 · 8: 154.2 %*2 · 9: 166.6 %*2 · 10: 179.9 %*2 · 11: 194.3 %*2 · 12: 209.8 %*2 · 13: 226.6 %*2"}]},{"id":"GA_Mint_Passive_2","name":"Бинго! Мы здесь закончили!","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/3308d813f50bf7809486.webp","description":"Пока Минт находится на поле боя, её защита увеличивается на 20 %, а устойчивость к прерываниям на 30 %.\n\nКогда работа почти закончена, всегда ощущается дополнительный прилив сил, особенно когда в магазинах появляются новинки…\n\n«Пять минут до закрытия! Постройтесь в очередь на обнуление!»","attributes":[]},{"id":"048a3dee-4221-4e7e-b54a-77a80ac7736b","name":"Сверхспособность: Могучий торнадо","type":"Навык поддержки","iconUrl":"https://ntewiki.org/images/characters/source/Mint/Mint_QTE.png","description":"Идеальная завершающая работа от элитного участника команды! Прыгает в воздух с разгона и проводит пробивающую атаку по врагам, нанося 1 экземпляр урона анимы по области.\n\nБазовые значения:\nКоэфф. урона: 200％","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"}]},{"id":"c26976cb-5452-4efa-bfdd-f5edd2d2e1c7","name":"Сверхспособность: Громоудар вихря","type":"Сверхспособность","iconUrl":"https://ntewiki.org/images/characters/source/Mint/Mint_UltraSkill.png","description":"Вы готовы? Собирает окружающий ветер в свои клинки, превращая их в ветряные лезвия, которые наносят многократный урон анимы по области. Финальный удар при приземлении наносит огромный урон анимы по области.\n\nБазовые значения:\nКоэффициент ударного урона: 132.6％\\nКоэфф. комбо когтя: 58.8％×5\\nКоэфф. рубящих ударов: 373.5％","attributes":[{"id":"parameter-0","label":"Множитель урона при ударе","value":"1: 132.6 % · 2: 143.2 % · 3: 154.7 % · 4: 167 % · 5: 180.4 % · 6: 194.8 % · 7: 210.4 % · 8: 227.3 % · 9: 245.4 % · 10: 265.1 % · 11: 286.3 % · 12: 309.2 % · 13: 333.9 %"},{"id":"parameter-1","label":"Множитель комбо когтя","value":"1: 58.8 %*5 · 2: 63.5 %*5 · 3: 68.6 %*5 · 4: 74.1 %*5 · 5: 80 %*5 · 6: 86.4 %*5 · 7: 93.3 %*5 · 8: 100.8 %*5 · 9: 108.8 %*5 · 10: 117.5 %*5 · 11: 126.9 %*5 · 12: 137.1 %*5 · 13: 148.1 %*5"},{"id":"parameter-2","label":"Множитель рубящих ударов","value":"1: 373.5 % · 2: 403.4 % · 3: 435.7 % · 4: 470.5 % · 5: 508.1 % · 6: 548.8 % · 7: 592.7 % · 8: 640.1 % · 9: 691.3 % · 10: 746.6 % · 11: 806.4 % · 12: 870.9 % · 13: 940.5 %"}]},{"id":"1bd4a48a-146f-4658-a31d-23ce5e6e51b0","name":"Торнадо Минт","type":"Повседневный навык","iconUrl":"https://i2.wp.com/images.genshin-builds.com/nte/characters/player_019.webp?strip=all&quality=100&w=520","description":"Описание требует проверки в игре.","attributes":[]}]') WHERE character_id='mint' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-17 20:03:39');

UPDATE character_profiles SET skins_json=json('[{"id":"Fashion_1019_swimsuit","name":"Солёная ириска","description":"Блестящий фантик сверкает на солнце и переливается всеми цветами радуги. Эта конфета мятная.","imageUrl":"/nte-meta/game-assets/ae3eeaff53d6b77d72f5.webp"},{"id":"da44e03e-3623-429d-a297-31d65828676a","name":"Безмятежный отдых","description":"Открывается за 10 уровень симпатии с Минт.","imageUrl":"https://img.game8.co/4491905/342f87550282672e8583a2c347ec8e75.png/original"},{"id":"Fashion_1019_rpg_level2","name":"Лесной охотник","description":"От первого опавшего листа до последнего следа — охота никогда не заканчивается.","imageUrl":"/nte-meta/game-assets/62b045cee771c6fb9ab4.webp"},{"id":"a3582df6-e87d-4232-a6e1-133455eb18e8","name":"Надежда ОС","description":"Стандартный наряд.","imageUrl":"https://img.game8.co/4491900/2248539d5a46cc297475d48669f5e435.png/original"},{"id":"Fashion_1019_rpg_level1","name":"Словно вольный ветер","description":"Стоит тебе побежать, как шлейф свободы устремится по дороге впереди твоих шагов.","imageUrl":"/nte-meta/game-assets/73305b6192c4107fc83f.webp"},{"id":"Fashion_1019_rpg_level3","name":"Пламя Авроры","description":"Словно призрачное пламя в диких просторах, дочь ветра рождена, чтобы странствовать свободно и без оков.","imageUrl":"/nte-meta/game-assets/312160f9b2fdb417f2bb.webp"},{"id":"8c1fc38e-470a-4173-81d7-8ff9b871acad","name":"Для Мэри","description":"Покупается за 3,000,000 фонов","imageUrl":"https://img.game8.co/4491904/d69e5ad15643eb912f9f894a3a484db1.png/original"}]') WHERE character_id='mint' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-17 20:03:39');

