UPDATE character_profiles SET gifts_json=json('[{"id":"Food_018","name":"Чайный сад Боба","iconUrl":"https://www.neverness.app/assets/codex/likeability/Food_018.webp","effect":"Симпатия +100"},{"id":"Food_045","name":"Лавабургер «Кликки»","iconUrl":"https://www.neverness.app/assets/codex/likeability/Food_045.webp","effect":"Симпатия +100"},{"id":"Food_062","name":"Песнь гладиатора","iconUrl":"https://www.neverness.app/assets/codex/likeability/Food_062.webp","effect":"Симпатия +100"},{"id":"SmallPoster002","name":"Крик!","iconUrl":"/nte-meta/game-assets/9d735f9506a467cf22c5.webp","effect":"Симпатия +200"},{"id":"SmallPoster005","name":"Остынь","iconUrl":"/nte-meta/game-assets/fb6ad82dc9bcee9c55a8.webp","effect":"Симпатия +200"},{"id":"SmallPoster006","name":"Секреты сумки…","iconUrl":"https://www.neverness.app/assets/codex/likeability/SmallPoster006.webp","effect":"Симпатия +200"},{"id":"Furniture_Light_007","name":"Белая нефритовая лампа","iconUrl":"https://www.neverness.app/assets/codex/likeability/Furniture_Light_007.webp","effect":"Симпатия +400"},{"id":"SpecialGift_ticket","name":"Билет в кинотеатр «Флоу»","iconUrl":"/nte-meta/game-assets/99060c23d3e0fef0599d.webp","effect":"Симпатия +400"},{"id":"SpecialGift_letter","name":"Рукописное письмо","iconUrl":"/nte-meta/game-assets/3deebe64fe65e4e200c3.webp","effect":"Симпатия +2000"}]') WHERE character_id='skia' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:22:54');

