UPDATE character_profiles SET friendship_json=json('[{"level":1,"rewardName":"","rewardIconUrl":"","description":"Опыт симпатии для уровня: 100","rewards":[{"id":"reward-1-0","name":"Аннулит","quantity":"10","iconUrl":"/nte-meta/game-assets/f710b1307783401a82e7.webp"},{"id":"reward-1-1","name":"Руководство старшего охотника","quantity":"3","iconUrl":"/nte-meta/game-assets/460ddc552a6a84394b65.webp"}]},{"level":2,"rewardName":"","rewardIconUrl":"","description":"Опыт симпатии для уровня: 500","rewards":[{"id":"reward-2-0","name":"Аннулит","quantity":"10","iconUrl":"/nte-meta/game-assets/f710b1307783401a82e7.webp"},{"id":"reward-2-1","name":"Хаотическая краска","quantity":"2","iconUrl":"/nte-meta/game-assets/082935d88b3d0b811a23.webp"},{"id":"reward-2-2","name":"Велосипедный пропуск: Ския","quantity":"1","iconUrl":"/nte-meta/game-assets/280218e5b12d4c96ec10.webp"}]},{"level":3,"rewardName":"","rewardIconUrl":"","description":"Опыт симпатии для уровня: 1000","rewards":[{"id":"reward-3-0","name":"Аннулит","quantity":"10","iconUrl":"/nte-meta/game-assets/f710b1307783401a82e7.webp"},{"id":"reward-3-1","name":"Руководство элитного охотника","quantity":"2","iconUrl":"/nte-meta/game-assets/99d235eaf500fbed5b33.webp"}]},{"level":4,"rewardName":"","rewardIconUrl":"","description":"Опыт симпатии для уровня: 2000","rewards":[{"id":"reward-4-0","name":"Аннулит","quantity":"10","iconUrl":"/nte-meta/game-assets/f710b1307783401a82e7.webp"},{"id":"reward-4-1","name":"Руководство элитного охотника","quantity":"3","iconUrl":"/nte-meta/game-assets/99d235eaf500fbed5b33.webp"}]},{"level":5,"rewardName":"","rewardIconUrl":"","description":"Опыт симпатии для уровня: 3500","rewards":[{"id":"reward-5-0","name":"Аннулит","quantity":"20","iconUrl":"/nte-meta/game-assets/f710b1307783401a82e7.webp"},{"id":"reward-5-1","name":"Семя без снов","quantity":"5","iconUrl":"/nte-meta/game-assets/a9c2a5ad8768d6b3454c.webp"},{"id":"reward-5-2","name":"Я — это я","quantity":"1","iconUrl":"/nte-meta/game-assets/6493ae533adfbb5126b1.webp"}]},{"level":6,"rewardName":"","rewardIconUrl":"","description":"Опыт симпатии для уровня: 5000","rewards":[{"id":"reward-6-0","name":"Аннулит","quantity":"20","iconUrl":"/nte-meta/game-assets/f710b1307783401a82e7.webp"},{"id":"reward-6-1","name":"Жук-монета","quantity":"20000","iconUrl":"/nte-meta/game-assets/b4a8b7d8447e5faa8103.webp"}]},{"level":7,"rewardName":"","rewardIconUrl":"","description":"Опыт симпатии для уровня: 7000","rewards":[{"id":"reward-7-0","name":"Жук-монета","quantity":"20000","iconUrl":"/nte-meta/game-assets/b4a8b7d8447e5faa8103.webp"},{"id":"reward-7-1","name":"Пахать как лошадь","quantity":"1","iconUrl":"/nte-meta/game-assets/6a28e25da4bcfca6077f.webp"}]},{"level":8,"rewardName":"","rewardIconUrl":"","description":"Опыт симпатии для уровня: 9000","rewards":[{"id":"reward-8-0","name":"Жук-монета","quantity":"30000","iconUrl":"/nte-meta/game-assets/b4a8b7d8447e5faa8103.webp"},{"id":"reward-8-1","name":"яикС","quantity":"1","iconUrl":"/nte-meta/game-assets/8caf679dbb50dc37f0e9.webp"}]},{"level":9,"rewardName":"","rewardIconUrl":"","description":"Опыт симпатии для уровня: 12000","rewards":[{"id":"reward-9-0","name":"Жук-монета","quantity":"40000","iconUrl":"/nte-meta/game-assets/b4a8b7d8447e5faa8103.webp"},{"id":"reward-9-1","name":"Кроме плоти и облика","quantity":"1","iconUrl":"/nte-meta/game-assets/da37bd94a9bfc35ac033.webp"}]},{"level":10,"rewardName":"","rewardIconUrl":"","description":"Опыт симпатии для уровня: 16000","rewards":[{"id":"reward-10-0","name":"Жук-монета","quantity":"50000","iconUrl":"/nte-meta/game-assets/b4a8b7d8447e5faa8103.webp"},{"id":"reward-10-1","name":"Корпоративный стандарт","quantity":"1","iconUrl":"/nte-meta/game-assets/ffd2e3da8edbe55f4f14.webp"}]}]') WHERE character_id='skia' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:22:54');

