UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Процесс устранения","iconUrl":"/nte-meta/game-assets/15b926dfea260688f512.webp","description":"Повышает множитель урона автоатаки для Удара клыком на 60 %."},{"level":2,"kind":"awakening","name":"Закон и порядок","iconUrl":"/nte-meta/game-assets/5701fe22fde5283099ac.webp","description":"После применения Погони теневой гончей увеличивает для Скии шанс крит. удара на 10 % и устойчивость к прерываниям на 50 % на 15 сек."},{"level":3,"kind":"awakening","name":"Решение","iconUrl":"/nte-meta/game-assets/40bdd99b492237858f32.webp","description":"Урон Скии по отмеченным Ударом клыком целям увеличивается на 4 %.\n\nЕсли на поле боя только одна цель отмечена Ударом клыком, урон Скии по ней увеличивается ещё на 4 %."},{"level":4,"kind":"awakening","name":"Резолюция","iconUrl":"/nte-meta/game-assets/0abb56c18934dfd08d9e.webp","description":"Увеличивает длительность Слежения до 12 сек. Повышает урон от присоединения на 2 % за каждую секунду присоединения к цели, до 40 %."},{"level":5,"kind":"awakening","name":"Социальный контракт","iconUrl":"/nte-meta/game-assets/1c293ed2e77e4fb45822.webp","description":"Увеличивает массу цели на 50 ед. и снижает скорость движения на 20 % для каждого Удара клыком, нацеленного на неё."},{"level":6,"kind":"awakening","name":"Беззаботное появление","iconUrl":"/nte-meta/game-assets/fce57c73abafc9d43eb1.webp","description":"В режиме Укус теневой гончей повышает множитель дополнительного урона Удара клыком на 20 %, когда Ския касается врага, уже выбранного целью Удара клыком."},{"level":3,"kind":"resonance","name":"Руководство по выживанию в кубикле","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень навыков «Искусство ареста», «Погоня теневой гончей» и «Стая» на 1."},{"level":6,"kind":"resonance","name":"Сотрудник месяца","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Снижает сопротивление отмеченных целей урону лакшаны на 2 % на каждый Удар клыком, до 6 %."}]') WHERE character_id='skia' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:22:54');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"ja-Play_Vo_Char_NPC005_DodgeCombo_002","title":"Серия критических уклонений II","description":"Тебе не поймать тень.","language":"Японский","audioUrl":"/nte-meta/game-audio/4726013b4c18d6dc2c5d.ogg"},{"id":"ja-Play_Vo_Char_NPC005_meet_001","title":"Первая встреча","description":"Лейтенант Ския, Отряд 4, Тактический отдел исполнения. Возможно, мы ещё встретимся по работе в будущем.","language":"Японский","audioUrl":"/nte-meta/game-audio/0b846676c69a8f3c0d78.ogg"},{"id":"ja-Play_Vo_Char_NPC005_skill_001","title":"Навык перенаправления I","description":"Отбой!","language":"Японский","audioUrl":"/nte-meta/game-audio/31139977ca304c25b4f3.ogg"},{"id":"ja-Play_Vo_Char_NPC005_TeammateDown_003","title":"Поражен товарищ по команде – Лакримоза","description":"Лакримоза, иди поспи. Остальное я сделаю.","language":"Японский","audioUrl":"/nte-meta/game-audio/97a8ec767fc3d64d6780.ogg"},{"id":"ja-Play_Vo_Char_NPC005_SSC_002","title":"Особое переключение II — Байканг","description":"Байканг, будь начеку.","language":"Японский","audioUrl":"/nte-meta/game-audio/d3f3f5b391e38e08e90b.ogg"},{"id":"en-Play_Vo_Char_NPC005_dead_003","title":"Потеря сознания III","description":"Команда… отходим…","language":"Английский","audioUrl":"/nte-meta/game-audio/0a7c110d6d9968e6fdf2.ogg"},{"id":"en-Play_Vo_Char_NPC005_SSC_004","title":"Особое переключение II — Фадия","description":"Фадия, не перенапрягайся.","language":"Английский","audioUrl":"/nte-meta/game-audio/389427c52344044bc472.ogg"},{"id":"en-Play_Vo_Char_NPC005_TeammateDown_002","title":"Поражен товарищ по команде – Фадия","description":"Фадия, не перетрудись. Я тебя прикрою.","language":"Английский","audioUrl":"/nte-meta/game-audio/9294507eca7cdfb78f26.ogg"},{"id":"ja-Play_Vo_Char_NPC005_hp_002","title":"Низкий уровень здоровья II","description":"Где наша поддержка?!","language":"Японский","audioUrl":"/nte-meta/game-audio/697b9714ba2793758084.ogg"},{"id":"ja-Play_Vo_Char_NPC005_weather_003","title":"Холодно","description":"Мне не холодно… но не рассчитывай на меня как на источник тепла.","language":"Японский","audioUrl":"/nte-meta/game-audio/89c05fcacc3afaa78b01.ogg"},{"id":"en-Play_Vo_Char_NPC005_Fly_002","title":"Планирование II","description":"Хм-м… отсюда хороший обзор.","language":"Английский","audioUrl":"/nte-meta/game-audio/d724b098a2e18d4711fd.ogg"},{"id":"en-Play_Vo_Char_NPC005_gift_001","title":"Подарок получен I","description":"Практичный, уместный и продуманный подарок. Спасибо, оценщик.Практичный, уместный и продуманный подарок. Спасибо, оценщица.","language":"Английский","audioUrl":"/nte-meta/game-audio/cc984ccd4fd9b86b6933.ogg"},{"id":"en-Play_Vo_Char_NPC005_windfall_002","title":"Неожиданная добыча II","description":"Пусть этим займется отдел логистики.","language":"Английский","audioUrl":"/nte-meta/game-audio/95b24d83a77427793101.ogg"},{"id":"en-Play_Vo_Char_NPC005_about_005","title":"О Бюро по борьбе с аномалиями","description":"Раньше я думал, что лучший путь для меня — стабильная руководящая должность в крупной корпорации, идеально упорядоченная жизнь. Я и представить себе не мог, что окажусь в такой организации, как бюро по разрешению чрезвычайных ситуаций. Жизнь непредсказуема — ряд неожиданных поворотов привел меня сюда, а теперь ежедневная рутина по устранению того, что выбивается из нормы, стала моим новым ощущением порядка…","language":"Английский","audioUrl":"/nte-meta/game-audio/4050955ca6f7def61fc1.ogg"},{"id":"en-Play_Vo_Char_NPC005_SSC_006","title":"Особое переключение II — Лакримоза","description":"Лакримоза, иди отдохни.","language":"Английский","audioUrl":"/nte-meta/game-audio/494b887475790529e174.ogg"},{"id":"ja-Play_Vo_Char_NPC005_aoe_UI_003","title":"Сверхспособность III","description":"Время стать жестче.","language":"Японский","audioUrl":"/nte-meta/game-audio/8d554f37e6ac8beb5ed3.ogg"},{"id":"ja-Play_Vo_Char_NPC005_chat_003","title":"Чат: встреча","description":"Если увидишь Байканга, можешь попросить его как можно быстрее ответить на мое сообщение? Я составил протокол собрания, которое он пропустил, и отправил на его телефон. Нужно, чтобы он ПРОЧИТАЛ его до конца дня.","language":"Японский","audioUrl":"/nte-meta/game-audio/74de57431960007e31ea.ogg"},{"id":"ja-Play_Vo_Char_NPC005_TeammateDown_002","title":"Поражен товарищ по команде – Фадия","description":"Фадия, не перетрудись. Я тебя прикрою.","language":"Японский","audioUrl":"/nte-meta/game-audio/703a13b8e93813a991bb.ogg"},{"id":"en-Play_Vo_Char_NPC005_fh_002","title":"Исцеление II","description":"Спасибо за помощь.","language":"Английский","audioUrl":"/nte-meta/game-audio/19a5bd50e3437ad406d2.ogg"},{"id":"en-Play_Vo_Char_NPC005_aoe_UI_002","title":"Сверхспособность II","description":"Обычная работа!","language":"Английский","audioUrl":"/nte-meta/game-audio/12505a784d15fe787649.ogg"},{"id":"en-Play_Vo_Char_NPC005_greet_003","title":"Вечернее приветствие","description":"В ТОИ нет фиксированного времени окончания рабочего дня — мы должны быть готовы к заданию в любое время. Обязательно позвони мне, если что-то случится.","language":"Английский","audioUrl":"/nte-meta/game-audio/47cb557dd093cb0b64c2.ogg"},{"id":"ja-Play_Vo_Char_NPC005_skill_003","title":"Навык перенаправления III","description":"Не вляпайся в неприятности!","language":"Японский","audioUrl":"/nte-meta/game-audio/818ddcc7879b6991654e.ogg"},{"id":"ja-Play_Vo_Char_NPC005_dead_001","title":"Потеря сознания I","description":"Ах… Простите.","language":"Японский","audioUrl":"/nte-meta/game-audio/00faab7ef9a8df910829.ogg"},{"id":"en-Play_Vo_Char_NPC005_gift_003","title":"Подарок получен III","description":"Понимаю. Это часть поддержания хороших отношений. Спасибо.","language":"Английский","audioUrl":"/nte-meta/game-audio/82740cf4d7cec24d9cd1.ogg"},{"id":"en-Play_Vo_Char_NPC005_ug_002","title":"Вознесение персонажа II","description":"Постоянство и методичность.","language":"Английский","audioUrl":"/nte-meta/game-audio/1afe9ebb08fbe0cc07dc.ogg"},{"id":"ja-Play_Vo_Char_NPC005_greet_004","title":"Спокойной ночи","description":"Ты отлично потрудился сегодня. Отдохни.Ты отлично потрудилась сегодня. Отдохни.","language":"Японский","audioUrl":"/nte-meta/game-audio/978745fd7a3701161c98.ogg"},{"id":"ja-Play_Vo_Char_NPC005_talk_001","title":"Тема: аномалия — Мисс Фэй","description":"У кофе мисс Фэй… уникальный аромат, но он бодрит. Ничего не имею против. Она обижается, если мы завариваем чай на работе, так что мы выходим для этого на улицу.","language":"Японский","audioUrl":"/nte-meta/game-audio/047084c88f77f39fa4b2.ogg"},{"id":"en-Play_Vo_Char_NPC005_hp_001","title":"Низкий уровень здоровья I","description":"Это выходит из-под контроля…","language":"Английский","audioUrl":"/nte-meta/game-audio/1bec197c688a0df20440.ogg"},{"id":"en-Play_Vo_Char_NPC005_meet_001","title":"Первая встреча","description":"Лейтенант Ския, Отряд 4, Тактический отдел исполнения. Возможно, мы ещё встретимся по работе в будущем.","language":"Английский","audioUrl":"/nte-meta/game-audio/34bb39a56219ceae9d88.ogg"},{"id":"en-Play_Vo_Char_NPC005_QTE_001","title":"Атака на входе I","description":"Фасс.","language":"Английский","audioUrl":"/nte-meta/game-audio/24579c30eaba47bfeb4d.ogg"},{"id":"ja-Play_Vo_Char_NPC005_chat_002","title":"Чат: ритм жизни","description":"Ты прибыл в этот город без предварительных знаний или подготовки, так что, думаю, твою жизнь здесь определит «Эйбон». Как считаешь? Подходит тебе такая жизнь? Ты прибыла в этот город без предварительных знаний или подготовки, так что, думаю, твою жизнь здесь определит «Эйбон». Как считаешь? Подходит тебе такая жизнь?","language":"Японский","audioUrl":"/nte-meta/game-audio/2384eea5fdedac60a023.ogg"},{"id":"ja-Play_Vo_Char_NPC005_greet_002","title":"Дневное приветствие","description":"Еду в кафе в Бюро нельзя назвать хорошей или плохой. Система очередей и питания, безусловно, эффективна, но если обедать там каждый день, то, естественно, устаешь.","language":"Японский","audioUrl":"/nte-meta/game-audio/f9a594007d7d2fb182d7.ogg"},{"id":"en-Play_Vo_Char_NPC005_aoe_UI_001","title":"Сверхспособность I","description":"Подавить цель!","language":"Английский","audioUrl":"/nte-meta/game-audio/4ec9f29af89369c6706d.ogg"},{"id":"en-Play_Vo_Char_NPC005_hstruck_002","title":"Сильный урон II","description":"Враг у ворот…","language":"Английский","audioUrl":"/nte-meta/game-audio/d101c8903c1361dd5c68.ogg"},{"id":"ja-Play_Vo_Char_NPC005_containment_002","title":"Сдерживание II","description":"Я помогу с уборкой.","language":"Японский","audioUrl":"/nte-meta/game-audio/201a7e0ee9f0b7cb927b.ogg"},{"id":"ja-Play_Vo_Char_NPC005_QTE_003","title":"Атака на входе III","description":"Я тебя прикрою!","language":"Японский","audioUrl":"/nte-meta/game-audio/c6cd20ec55525ce31014.ogg"},{"id":"en-Play_Vo_Char_NPC005_Parry_002","title":"Парирование II","description":"Сдавайся немедленно!","language":"Английский","audioUrl":"/nte-meta/game-audio/caa45d98ba7bda1ef1b9.ogg"},{"id":"en-Play_Vo_Char_NPC005_Switch_001","title":"Переключение I","description":"Иду первым.","language":"Английский","audioUrl":"/nte-meta/game-audio/a9d7b2298b3da9e84ed7.ogg"},{"id":"en-Play_Vo_Char_NPC005_windfall_006","title":"Неожиданная добыча VI","description":"Неожиданная добыча.","language":"Английский","audioUrl":"/nte-meta/game-audio/63ae65b447647a997691.ogg"},{"id":"ja-Play_Vo_Char_NPC005_about_006","title":"О ТОИ","description":"В прошлом я бы не потерпел подчиненных, лишенных командного духа или слишком тянущих одеяло на себя. Но сейчас, здесь… те, кто не может сработаться с яркими личностями, судя по всему, не подходят для этой работы.","language":"Японский","audioUrl":"/nte-meta/game-audio/3b74001f86b632d8e662.ogg"},{"id":"en-Play_Vo_Char_NPC005_containment_001","title":"Сдерживание I","description":"Все готово. Теперь этим займется ОС.","language":"Английский","audioUrl":"/nte-meta/game-audio/110cfb670c977fc4d164.ogg"},{"id":"en-Play_Vo_Char_NPC005_QTE_002","title":"Атака на входе II","description":"Я словно тень…","language":"Английский","audioUrl":"/nte-meta/game-audio/fc0ad35e25cb264e2a6f.ogg"},{"id":"en-Play_Vo_Char_NPC005_gift_004","title":"Подарок получен IV","description":"Я запомню твой подарок и отвечу тебе взаимностью.","language":"Английский","audioUrl":"/nte-meta/game-audio/02c1cfd679fa31065440.ogg"},{"id":"en-Play_Vo_Char_NPC005_TeammateDown_001","title":"Поражен товарищ по команде – Байканг","description":"Отлично сработано, капитан… Дальше действовать буду я.","language":"Английский","audioUrl":"/nte-meta/game-audio/5036db4d5966a9bb50bb.ogg"},{"id":"en-Play_Vo_Char_NPC005_weather_002","title":"Дождливо","description":"Влажная погода серьезно влияет на работу за пределами офиса, и дело не только в скользких поверхностях. Обязательно следи за аномалиями, которые адаптируют свое поведение, когда погода меняется.","language":"Английский","audioUrl":"/nte-meta/game-audio/abedb8b30ec80aa74f56.ogg"},{"id":"en-Play_Vo_Char_NPC005_weather_004","title":"Жарко","description":"Такая погода раздражает, но я не собака — ты не увидишь меня с высунутым языком!","language":"Английский","audioUrl":"/nte-meta/game-audio/f8dbd90645cd2e2a0c02.ogg"},{"id":"ja-Play_Vo_Char_NPC005_windfall_002","title":"Неожиданная добыча II","description":"Пусть этим займется отдел логистики.","language":"Японский","audioUrl":"/nte-meta/game-audio/aee9ae653a86060454ac.ogg"},{"id":"en-Play_Vo_Char_NPC005_dead_002","title":"Потеря сознания II","description":"За пределами моих возможностей…","language":"Английский","audioUrl":"/nte-meta/game-audio/afc226a46eec8c230797.ogg"},{"id":"en-Play_Vo_Char_NPC005_talk_003","title":"Тема: резюме","description":"Да, я работал в компании… довольно известной. Затем на какое-то время погрузился в преступный мир, а сейчас стал сотрудником государственного института. Кто-то скажет, что у меня необычное резюме, но, оглядываясь назад… может я просто искал свое место методом проб и ошибок.","language":"Английский","audioUrl":"/nte-meta/game-audio/bb4eecd37638ecb6198b.ogg"},{"id":"en-Play_Vo_Char_NPC005_vexation_001","title":"Проблемы","description":"Проблемы?… С Байкангом или Фадией?.. Я ещё могу понять, когда Лакримоза капризничает и вызывает небольшие затруднения… Но эти двое — взрослые люди, которые отлынивают от работы и провоцируют неприятности. У меня от них голова болит.","language":"Английский","audioUrl":"/nte-meta/game-audio/6461c6d83cd927e18632.ogg"},{"id":"ja-Play_Vo_Char_NPC005_dead_003","title":"Потеря сознания III","description":"Команда… отходим…","language":"Японский","audioUrl":"/nte-meta/game-audio/9984f21c31fa4aee7c13.ogg"},{"id":"ja-Play_Vo_Char_NPC005_talk_003","title":"Тема: резюме","description":"Да, я работал в компании… довольно известной. Затем на какое-то время погрузился в преступный мир, а сейчас стал сотрудником государственного института. Кто-то скажет, что у меня необычное резюме, но, оглядываясь назад… может я просто искал свое место методом проб и ошибок.","language":"Японский","audioUrl":"/nte-meta/game-audio/a45a00bdf3041125ae5f.ogg"},{"id":"en-Play_Vo_Char_NPC005_windfall_005","title":"Неожиданная добыча V","description":"Это я пока придержу.","language":"Английский","audioUrl":"/nte-meta/game-audio/1a997a9b2a13d1dc25a6.ogg"},{"id":"ja-Play_Vo_Char_NPC005_dead_002","title":"Потеря сознания II","description":"За пределами моих возможностей…","language":"Японский","audioUrl":"/nte-meta/game-audio/307a28827fbfded593b5.ogg"},{"id":"ja-Play_Vo_Char_NPC005_self_001","title":"Обо мне: способности эспера","description":"Интересно, почему темперамент моей тени отличается от моего, хотя именно я управляю ей..? Объяснение может показаться немного абстрактным. Скажем так, после пробуждения моей способности эспера, когда я глубже понял свою роль, я осознал, что не нужно постоянно быть в напряжении. Именно тогда моя тень стала энергичнее, чем раньше.","language":"Японский","audioUrl":"/nte-meta/game-audio/5526b1f1ea46bac0dd8d.ogg"},{"id":"ja-Play_Vo_Char_NPC005_ug_003","title":"Вознесение персонажа III","description":"На работе всегда можно научиться чему-то новому.","language":"Японский","audioUrl":"/nte-meta/game-audio/1104c9230ed575095e57.ogg"},{"id":"ja-Play_Vo_Char_NPC005_anomaly_003","title":"Нуллификация II","description":"Цель нейтрализована.","language":"Японский","audioUrl":"/nte-meta/game-audio/06b5997aa42a258552ee.ogg"},{"id":"ja-Play_Vo_Char_NPC005_deploy_001","title":"Отправка II","description":"Давайте возьмемся за дело.","language":"Японский","audioUrl":"/nte-meta/game-audio/1bbe0adebc6a201f3b89.ogg"},{"id":"ja-Play_Vo_Char_NPC005_Fly_002","title":"Планирование II","description":"Хм-м… отсюда хороший обзор.","language":"Японский","audioUrl":"/nte-meta/game-audio/80f372f355c1b644f6aa.ogg"},{"id":"ja-Play_Vo_Char_NPC005_hobby_001","title":"Хобби","description":"Трудно сказать, какие у меня хобби. Если выбирать, наверное, я бы предпочел… видеть, как все мои задачи стабильно прогрессируют в сторону выполнения.","language":"Японский","audioUrl":"/nte-meta/game-audio/209d65c5a9e9d3af1c49.ogg"},{"id":"ja-Play_Vo_Char_NPC005_kill_002","title":"Убийство II","description":"Медленно, но верно.","language":"Японский","audioUrl":"/nte-meta/game-audio/81a6cf6ccda8ff217df5.ogg"},{"id":"ja-Play_Vo_Char_NPC005_talk_002","title":"Тема: аномалия — Агент.УДАЧА","description":"Агент.УДАЧА выполняет в Бюро всю бумажную работу, за которую больше никто не берется. Какой бы нудной и бесконечной она ни была. Он упорно верит, что его хозяин вернется домой, как только все будет закончено… Наблюдая за его прилежной работой, я вспоминаю того сотрудника, который исчез среди огней и по сей день не найден, и все нерешенные задачи, с которыми мы до сих пор не можем разобраться…","language":"Японский","audioUrl":"/nte-meta/game-audio/8aa660fd7da0b0ae559e.ogg"},{"id":"en-Play_Vo_Char_NPC005_talk_001","title":"Тема: аномалия — Мисс Фэй","description":"У кофе мисс Фэй… уникальный аромат, но он бодрит. Ничего не имею против. Она обижается, если мы завариваем чай на работе, так что мы выходим для этого на улицу.","language":"Английский","audioUrl":"/nte-meta/game-audio/90ffe65db1dacf428a42.ogg"},{"id":"en-Play_Vo_Char_NPC005_ug_001","title":"Вознесение персонажа I","description":"Чувствую себя отлично.","language":"Английский","audioUrl":"/nte-meta/game-audio/859e7e4edba7d44040ea.ogg"},{"id":"ja-Play_Vo_Char_NPC005_gift_003","title":"Подарок получен III","description":"Понимаю. Это часть поддержания хороших отношений. Спасибо.","language":"Японский","audioUrl":"/nte-meta/game-audio/ce38976fcb8dec7a5a7a.ogg"},{"id":"ja-Play_Vo_Char_NPC005_QTE_002","title":"Атака на входе II","description":"Я словно тень…","language":"Японский","audioUrl":"/nte-meta/game-audio/7dbc3ed354176ae7acdd.ogg"},{"id":"ja-Play_Vo_Char_NPC005_windfall_003","title":"Неожиданная добыча III","description":"Вначале убедимся, что это безопасно.","language":"Японский","audioUrl":"/nte-meta/game-audio/13d19226772214cdce3a.ogg"},{"id":"en-Play_Vo_Char_NPC005_deploy_001","title":"Отправка II","description":"Давайте возьмемся за дело.","language":"Английский","audioUrl":"/nte-meta/game-audio/2b14eeb34769f43b17b2.ogg"},{"id":"ja-Play_Vo_Char_NPC005_TeammateDown_001","title":"Поражен товарищ по команде – Байканг","description":"Отлично сработано, капитан… Дальше действовать буду я.","language":"Японский","audioUrl":"/nte-meta/game-audio/9b1455dde7b6c3b7bb69.ogg"},{"id":"en-Play_Vo_Char_NPC005_Fly_001","title":"Планирование I","description":"Я воспользуюсь возможностью осмотреться…","language":"Английский","audioUrl":"/nte-meta/game-audio/1a76547f27ae8bc4b5b6.ogg"},{"id":"ja-Play_Vo_Char_NPC005_anomaly_002","title":"Нуллификация I","description":"Хм-м, горькая пилюля.","language":"Японский","audioUrl":"/nte-meta/game-audio/5e730b9f495956a2f36d.ogg"},{"id":"ja-Play_Vo_Char_NPC005_weather_001","title":"Солнечно","description":"Когда солнце прямо над головой, моей тени труднее простираться у моих ног. Однако… на коротких расстояниях сжатая четкая тень бывает ещё эффективнее.","language":"Японский","audioUrl":"/nte-meta/game-audio/594be154fa13e78efc64.ogg"},{"id":"en-Play_Vo_Char_NPC005_anomaly_003","title":"Нуллификация II","description":"Цель нейтрализована.","language":"Английский","audioUrl":"/nte-meta/game-audio/277bdb608d53b9bde1b2.ogg"},{"id":"en-Play_Vo_Char_NPC005_gift_002","title":"Подарок получен II","description":"Я был так завален работой, что совсем не было времени это купить. Не ожидал, что ты достанешь это для меня…","language":"Английский","audioUrl":"/nte-meta/game-audio/f06f1b631d4b60c48ded.ogg"},{"id":"en-Play_Vo_Char_NPC005_self_002","title":"Обо мне: аниморфность","description":"Пробуждение способности эспера часто сопровождается аниморфными характеристиками, но, как видишь, в моем случае физическая трансформация прошла куда жестче, чем у других. В тот день я изо всех сил старался сохранять спокойствие, заниматься обычными делами со свойственной мне учтивостью и рациональностью. Но, разумеется, я лишился места среди «элиты»… Видимо, это была «цена», которую мне пришлось заплатить.","language":"Английский","audioUrl":"/nte-meta/game-audio/683b7771a76779cd8b91.ogg"},{"id":"ja-Play_Vo_Char_NPC005_hstruck_001","title":"Сильный урон I","description":"Нельзя терять бдительность.","language":"Японский","audioUrl":"/nte-meta/game-audio/d9048063db5b0fe8a153.ogg"},{"id":"ja-Play_Vo_Char_NPC005_weather_002","title":"Дождливо","description":"Влажная погода серьезно влияет на работу за пределами офиса, и дело не только в скользких поверхностях. Обязательно следи за аномалиями, которые адаптируют свое поведение, когда погода меняется.","language":"Японский","audioUrl":"/nte-meta/game-audio/c0ff552c358b7f5a7cd6.ogg"},{"id":"en-Play_Vo_Char_NPC005_hstruck_001","title":"Сильный урон I","description":"Нельзя терять бдительность.","language":"Английский","audioUrl":"/nte-meta/game-audio/44edfc75df8de51347f0.ogg"},{"id":"en-Play_Vo_Char_NPC005_windfall_003","title":"Неожиданная добыча III","description":"Вначале убедимся, что это безопасно.","language":"Английский","audioUrl":"/nte-meta/game-audio/856decd222cc8779f8a6.ogg"},{"id":"en-Play_Vo_Char_NPC005_hp_002","title":"Низкий уровень здоровья II","description":"Где наша поддержка?!","language":"Английский","audioUrl":"/nte-meta/game-audio/b590ca9957a25afa98c6.ogg"},{"id":"ja-Play_Vo_Char_NPC005_self_003","title":"Обо мне: «элита»","description":"После этого был период, когда мне казалось, будто основы моей жизни действительно пошатнулись… Но сейчас все хорошо — меня давно не волнует та работа и её стандарты.","language":"Японский","audioUrl":"/nte-meta/game-audio/f00b7e859d570d193c83.ogg"},{"id":"ja-Play_Vo_Char_NPC005_windfall_006","title":"Неожиданная добыча VI","description":"Неожиданная добыча.","language":"Японский","audioUrl":"/nte-meta/game-audio/c169c05888416990b51c.ogg"},{"id":"en-Play_Vo_Char_NPC005_TeammateDown_003","title":"Поражен товарищ по команде – Лакримоза","description":"Лакримоза, иди поспи. Остальное я сделаю.","language":"Английский","audioUrl":"/nte-meta/game-audio/26a4299449b9f96d4478.ogg"},{"id":"en-Play_Vo_Char_NPC005_windfall_001","title":"Неожиданная добыча I","description":"Неожиданное открытие.","language":"Английский","audioUrl":"/nte-meta/game-audio/daafab7eef64ff6e003c.ogg"},{"id":"ja-Play_Vo_Char_NPC005_fh_001","title":"Исцеление I","description":"Как раз вовремя.","language":"Японский","audioUrl":"/nte-meta/game-audio/c053945dcd76bd06b3d5.ogg"},{"id":"ja-Play_Vo_Char_NPC005_weather_004","title":"Жарко","description":"Такая погода раздражает, но я не собака — ты не увидишь меня с высунутым языком!","language":"Японский","audioUrl":"/nte-meta/game-audio/1838e04cafaf18c6093b.ogg"},{"id":"en-Play_Vo_Char_NPC005_self_001","title":"Обо мне: способности эспера","description":"Интересно, почему темперамент моей тени отличается от моего, хотя именно я управляю ей..? Объяснение может показаться немного абстрактным. Скажем так, после пробуждения моей способности эспера, когда я глубже понял свою роль, я осознал, что не нужно постоянно быть в напряжении. Именно тогда моя тень стала энергичнее, чем раньше.","language":"Английский","audioUrl":"/nte-meta/game-audio/f7e141c62208416dd27e.ogg"},{"id":"ja-Play_Vo_Char_NPC005_gift_004","title":"Подарок получен IV","description":"Я запомню твой подарок и отвечу тебе взаимностью.","language":"Японский","audioUrl":"/nte-meta/game-audio/f01556c075f6333ec490.ogg"},{"id":"ja-Play_Vo_Char_NPC005_Parry_001","title":"Парирование I","description":"Никогда!","language":"Японский","audioUrl":"/nte-meta/game-audio/87525e944519deeee845.ogg"},{"id":"ja-Play_Vo_Char_NPC005_windfall_001","title":"Неожиданная добыча I","description":"Неожиданное открытие.","language":"Японский","audioUrl":"/nte-meta/game-audio/d5e0d4532f239f7303fc.ogg"},{"id":"ja-Play_Vo_Char_NPC005_about_001","title":"Об Альфарде","description":"Директор — целеустремленный лидер. Однако её не сильно волнует поведение подчиненных, она фокусируется лишь на результатах… Может быть, поэтому ТОИ так снисходителен к свободомыслию…","language":"Японский","audioUrl":"/nte-meta/game-audio/538d8d8d73c158cf0a13.ogg"},{"id":"ja-Play_Vo_Char_NPC005_gift_001","title":"Подарок получен I","description":"Практичный, уместный и продуманный подарок. Спасибо, оценщик.Практичный, уместный и продуманный подарок. Спасибо, оценщица.","language":"Японский","audioUrl":"/nte-meta/game-audio/7bb1671985a927798bc5.ogg"},{"id":"en-Play_Vo_Char_NPC005_chat_002","title":"Чат: ритм жизни","description":"Ты прибыл в этот город без предварительных знаний или подготовки, так что, думаю, твою жизнь здесь определит «Эйбон». Как считаешь? Подходит тебе такая жизнь? Ты прибыла в этот город без предварительных знаний или подготовки, так что, думаю, твою жизнь здесь определит «Эйбон». Как считаешь? Подходит тебе такая жизнь?","language":"Английский","audioUrl":"/nte-meta/game-audio/eefcbed9cb55ee9de2ce.ogg"},{"id":"en-Play_Vo_Char_NPC005_containment_002","title":"Сдерживание II","description":"Я помогу с уборкой.","language":"Английский","audioUrl":"/nte-meta/game-audio/6032dd90123b48ddf1d1.ogg"},{"id":"en-Play_Vo_Char_NPC005_greet_002","title":"Дневное приветствие","description":"Еду в кафе в Бюро нельзя назвать хорошей или плохой. Система очередей и питания, безусловно, эффективна, но если обедать там каждый день, то, естественно, устаешь.","language":"Английский","audioUrl":"/nte-meta/game-audio/7dfc815e2828f636f531.ogg"},{"id":"ja-Play_Vo_Char_NPC005_kill_001","title":"Убийство I","description":"Я помогу с уборкой.","language":"Японский","audioUrl":"/nte-meta/game-audio/8c98e2cb7fc6c8d20b94.ogg"},{"id":"ja-Play_Vo_Char_NPC005_self_002","title":"Обо мне: аниморфность","description":"Пробуждение способности эспера часто сопровождается аниморфными характеристиками, но, как видишь, в моем случае физическая трансформация прошла куда жестче, чем у других. В тот день я изо всех сил старался сохранять спокойствие, заниматься обычными делами со свойственной мне учтивостью и рациональностью. Но, разумеется, я лишился места среди «элиты»… Видимо, это была «цена», которую мне пришлось заплатить.","language":"Японский","audioUrl":"/nte-meta/game-audio/e5756e9d34d9ce80d3ad.ogg"},{"id":"en-Play_Vo_Char_NPC005_SSC_005","title":"Особое переключение I — Лакримоза","description":"Защищать команду — моя обязанность.","language":"Английский","audioUrl":"/nte-meta/game-audio/2c83de122287a635c041.ogg"},{"id":"ja-Play_Vo_Char_NPC005_skill_002","title":"Навык перенаправления II","description":"Получай!","language":"Японский","audioUrl":"/nte-meta/game-audio/768e6d2afea76600a665.ogg"},{"id":"en-Play_Vo_Char_NPC005_kill_001","title":"Убийство I","description":"Я помогу с уборкой.","language":"Английский","audioUrl":"/nte-meta/game-audio/641c974d4ceeda2322e2.ogg"},{"id":"ja-Play_Vo_Char_NPC005_about_003","title":"О Фадии","description":"Однажды… на задании с Фадией… я встретил старого знакомого. Мы немного поболтали… и парень спросил, «честная ли у меня работа»… К вопросу о том, как публичный имидж коллег может серьезно влиять на то, как к нашей организации и работе относятся другие… Я устал от этого…","language":"Японский","audioUrl":"/nte-meta/game-audio/596a76c00c3375cd10a5.ogg"},{"id":"en-Play_Vo_Char_NPC005_skill_003","title":"Навык перенаправления III","description":"Не вляпайся в неприятности!","language":"Английский","audioUrl":"/nte-meta/game-audio/e7027377d52d52ed4f24.ogg"},{"id":"ja-Play_Vo_Char_NPC005_hp_003","title":"Низкий уровень здоровья III","description":"Сохраняем спокойствие. Шанс ещё есть.","language":"Японский","audioUrl":"/nte-meta/game-audio/deec4b562bda74521b78.ogg"},{"id":"ja-Play_Vo_Char_NPC005_ug_002","title":"Вознесение персонажа II","description":"Постоянство и методичность.","language":"Японский","audioUrl":"/nte-meta/game-audio/6421ecae76690d92d813.ogg"},{"id":"en-Play_Vo_Char_NPC005_chat_001","title":"Чат: рабочая среда","description":"В учебе или работе каждый испытывает на себе глубокое влияние окружения и подсознательно становится его частью — это работает в обе стороны.","language":"Английский","audioUrl":"/nte-meta/game-audio/b9f327d538db80cef300.ogg"},{"id":"en-Play_Vo_Char_NPC005_DodgeCombo_002","title":"Серия критических уклонений II","description":"Тебе не поймать тень.","language":"Английский","audioUrl":"/nte-meta/game-audio/ef404425c96be6a0b349.ogg"},{"id":"ja-Play_Vo_Char_NPC005_Switch_002","title":"Переключение II","description":"Я помогу.","language":"Японский","audioUrl":"/nte-meta/game-audio/bfad4a0962328dd5bbeb.ogg"},{"id":"ja-Play_Vo_Char_NPC005_vexation_001","title":"Проблемы","description":"Проблемы?… С Байкангом или Фадией?.. Я ещё могу понять, когда Лакримоза капризничает и вызывает небольшие затруднения… Но эти двое — взрослые люди, которые отлынивают от работы и провоцируют неприятности. У меня от них голова болит.","language":"Японский","audioUrl":"/nte-meta/game-audio/9db879a47fcd398fe61f.ogg"},{"id":"en-Play_Vo_Char_NPC005_Parry_001","title":"Парирование I","description":"Никогда!","language":"Английский","audioUrl":"/nte-meta/game-audio/420d23647e15cd30fbd7.ogg"},{"id":"en-Play_Vo_Char_NPC005_weather_001","title":"Солнечно","description":"Когда солнце прямо над головой, моей тени труднее простираться у моих ног. Однако… на коротких расстояниях сжатая четкая тень бывает ещё эффективнее.","language":"Английский","audioUrl":"/nte-meta/game-audio/a0795d7bd5b9e364f8b0.ogg"},{"id":"ja-Play_Vo_Char_NPC005_greet_003","title":"Вечернее приветствие","description":"В ТОИ нет фиксированного времени окончания рабочего дня — мы должны быть готовы к заданию в любое время. Обязательно позвони мне, если что-то случится.","language":"Японский","audioUrl":"/nte-meta/game-audio/1d0f5b086421efcb6d1b.ogg"},{"id":"en-Play_Vo_Char_NPC005_anomaly_002","title":"Нуллификация I","description":"Хм-м, горькая пилюля.","language":"Английский","audioUrl":"/nte-meta/game-audio/a9ff037342004ad1ecbb.ogg"},{"id":"en-Play_Vo_Char_NPC005_self_003","title":"Обо мне: «элита»","description":"После этого был период, когда мне казалось, будто основы моей жизни действительно пошатнулись… Но сейчас все хорошо — меня давно не волнует та работа и её стандарты.","language":"Английский","audioUrl":"/nte-meta/game-audio/a706191517defd72fb32.ogg"},{"id":"ja-Play_Vo_Char_NPC005_about_004","title":"О Лакримозе","description":"Если я не подвезу Лакримозу или не встречу её заранее… её могут вообще не пустить внутрь, потому что у неё нет ID. В сравнении с этим вероятность проспать или потеряться — лишь мелкие неурядицы.","language":"Японский","audioUrl":"/nte-meta/game-audio/75658853de6613706f58.ogg"},{"id":"ja-Play_Vo_Char_NPC005_SSC_004","title":"Особое переключение II — Фадия","description":"Фадия, не перенапрягайся.","language":"Японский","audioUrl":"/nte-meta/game-audio/35a3a5b0237b8cd0d6aa.ogg"},{"id":"en-Play_Vo_Char_NPC005_dead_001","title":"Потеря сознания I","description":"Ах… Простите.","language":"Английский","audioUrl":"/nte-meta/game-audio/627e1201480d1508c838.ogg"},{"id":"en-Play_Vo_Char_NPC005_SSC_002","title":"Особое переключение II — Байканг","description":"Байканг, будь начеку.","language":"Английский","audioUrl":"/nte-meta/game-audio/03bc478ade27d679cb3e.ogg"},{"id":"ja-Play_Vo_Char_NPC005_hp_001","title":"Низкий уровень здоровья I","description":"Это выходит из-под контроля…","language":"Японский","audioUrl":"/nte-meta/game-audio/1a03e4974b931d568c5c.ogg"},{"id":"ja-Play_Vo_Char_NPC005_containment_001","title":"Сдерживание I","description":"Все готово. Теперь этим займется ОС.","language":"Японский","audioUrl":"/nte-meta/game-audio/7c25f45f02ef691f2c3e.ogg"},{"id":"ja-Play_Vo_Char_NPC005_Switch_001","title":"Переключение I","description":"Иду первым.","language":"Японский","audioUrl":"/nte-meta/game-audio/03b68adfccf7414beb48.ogg"},{"id":"ja-Play_Vo_Char_NPC005_windfall_005","title":"Неожиданная добыча V","description":"Это я пока придержу.","language":"Японский","audioUrl":"/nte-meta/game-audio/2c9f3da0ea0392530c25.ogg"},{"id":"en-Play_Vo_Char_NPC005_about_006","title":"О ТОИ","description":"В прошлом я бы не потерпел подчиненных, лишенных командного духа или слишком тянущих одеяло на себя. Но сейчас, здесь… те, кто не может сработаться с яркими личностями, судя по всему, не подходят для этой работы.","language":"Английский","audioUrl":"/nte-meta/game-audio/93f9d976b5322e6101a2.ogg"},{"id":"en-Play_Vo_Char_NPC005_skill_002","title":"Навык перенаправления II","description":"Получай!","language":"Английский","audioUrl":"/nte-meta/game-audio/2b6fc4dad993125d5333.ogg"},{"id":"en-Play_Vo_Char_NPC005_ug_003","title":"Вознесение персонажа III","description":"На работе всегда можно научиться чему-то новому.","language":"Английский","audioUrl":"/nte-meta/game-audio/eb9928f56e1cf92cecbf.ogg"},{"id":"en-Play_Vo_Char_NPC005_deploy_002","title":"Отправка I","description":"ТОИ-4 уже здесь.","language":"Английский","audioUrl":"/nte-meta/game-audio/7e0e0f0577221b153023.ogg"},{"id":"en-Play_Vo_Char_NPC005_greet_001","title":"Утреннее приветствие","description":"Доброе утро. С чего сегодня начнем?","language":"Английский","audioUrl":"/nte-meta/game-audio/1520c1dc48dc555d584d.ogg"},{"id":"ja-Play_Vo_Char_NPC005_about_005","title":"О Бюро по борьбе с аномалиями","description":"Раньше я думал, что лучший путь для меня — стабильная руководящая должность в крупной корпорации, идеально упорядоченная жизнь. Я и представить себе не мог, что окажусь в такой организации, как бюро по разрешению чрезвычайных ситуаций. Жизнь непредсказуема — ряд неожиданных поворотов привел меня сюда, а теперь ежедневная рутина по устранению того, что выбивается из нормы, стала моим новым ощущением порядка…","language":"Японский","audioUrl":"/nte-meta/game-audio/e5c70836e135e5456500.ogg"},{"id":"ja-Play_Vo_Char_NPC005_SSC_001","title":"Особое переключение I — Байканг","description":"ТОИ-4 на месте.","language":"Японский","audioUrl":"/nte-meta/game-audio/dac30daf7e243e3fa3c7.ogg"},{"id":"ja-Play_Vo_Char_NPC005_windfall_004","title":"Неожиданная добыча IV","description":"Стоило усилий.","language":"Японский","audioUrl":"/nte-meta/game-audio/dc0c59acfc61240d3d66.ogg"},{"id":"en-Play_Vo_Char_NPC005_talk_002","title":"Тема: аномалия — Агент.УДАЧА","description":"Агент.УДАЧА выполняет в Бюро всю бумажную работу, за которую больше никто не берется. Какой бы нудной и бесконечной она ни была. Он упорно верит, что его хозяин вернется домой, как только все будет закончено… Наблюдая за его прилежной работой, я вспоминаю того сотрудника, который исчез среди огней и по сей день не найден, и все нерешенные задачи, с которыми мы до сих пор не можем разобраться…","language":"Английский","audioUrl":"/nte-meta/game-audio/60f0372b7b54863f799a.ogg"},{"id":"ja-Play_Vo_Char_NPC005_chat_001","title":"Чат: рабочая среда","description":"В учебе или работе каждый испытывает на себе глубокое влияние окружения и подсознательно становится его частью — это работает в обе стороны.","language":"Японский","audioUrl":"/nte-meta/game-audio/2d14873eb7d1eaadfddd.ogg"},{"id":"ja-Play_Vo_Char_NPC005_SSC_005","title":"Особое переключение I — Лакримоза","description":"Защищать команду — моя обязанность.","language":"Японский","audioUrl":"/nte-meta/game-audio/4aaefed23c5d30cbfaa6.ogg"},{"id":"en-Play_Vo_Char_NPC005_about_003","title":"О Фадии","description":"Однажды… на задании с Фадией… я встретил старого знакомого. Мы немного поболтали… и парень спросил, «честная ли у меня работа»… К вопросу о том, как публичный имидж коллег может серьезно влиять на то, как к нашей организации и работе относятся другие… Я устал от этого…","language":"Английский","audioUrl":"/nte-meta/game-audio/1fc8fd0ce2e93fb817ba.ogg"},{"id":"en-Play_Vo_Char_NPC005_skill_001","title":"Навык перенаправления I","description":"Отбой!","language":"Английский","audioUrl":"/nte-meta/game-audio/6afa05e88c399f921f93.ogg"},{"id":"en-Play_Vo_Char_NPC005_hobby_001","title":"Хобби","description":"Трудно сказать, какие у меня хобби. Если выбирать, наверное, я бы предпочел… видеть, как все мои задачи стабильно прогрессируют в сторону выполнения.","language":"Английский","audioUrl":"/nte-meta/game-audio/927032dd3d6a73f4f0e6.ogg"},{"id":"ja-Play_Vo_Char_NPC005_SSC_006","title":"Особое переключение II — Лакримоза","description":"Лакримоза, иди отдохни.","language":"Японский","audioUrl":"/nte-meta/game-audio/3c5dea2c503f5df40d23.ogg"},{"id":"ja-Play_Vo_Char_NPC005_aoe_UI_001","title":"Сверхспособность I","description":"Подавить цель!","language":"Японский","audioUrl":"/nte-meta/game-audio/002849fb6a2841f908d8.ogg"},{"id":"ja-Play_Vo_Char_NPC005_aoe_UI_002","title":"Сверхспособность II","description":"Обычная работа!","language":"Японский","audioUrl":"/nte-meta/game-audio/ad2b1a10d86af67ef0b3.ogg"},{"id":"ja-Play_Vo_Char_NPC005_hstruck_002","title":"Сильный урон II","description":"Враг у ворот…","language":"Японский","audioUrl":"/nte-meta/game-audio/00c2c1df76cc8f5af59e.ogg"},{"id":"ja-Play_Vo_Char_NPC005_ug_001","title":"Вознесение персонажа I","description":"Чувствую себя отлично.","language":"Японский","audioUrl":"/nte-meta/game-audio/e7fa219a8b8ccbc12517.ogg"},{"id":"en-Play_Vo_Char_NPC005_about_004","title":"О Лакримозе","description":"Если я не подвезу Лакримозу или не встречу её заранее… её могут вообще не пустить внутрь, потому что у неё нет ID. В сравнении с этим вероятность проспать или потеряться — лишь мелкие неурядицы.","language":"Английский","audioUrl":"/nte-meta/game-audio/7d33e5f3650b3a067c8d.ogg"},{"id":"en-Play_Vo_Char_NPC005_chat_003","title":"Чат: встреча","description":"Если увидишь Байканга, можешь попросить его как можно быстрее ответить на мое сообщение? Я составил протокол собрания, которое он пропустил, и отправил на его телефон. Нужно, чтобы он ПРОЧИТАЛ его до конца дня.","language":"Английский","audioUrl":"/nte-meta/game-audio/f1f75271f6d7082dc967.ogg"},{"id":"en-Play_Vo_Char_NPC005_struck_002","title":"Урон II","description":"И говорить не стоит.","language":"Английский","audioUrl":"/nte-meta/game-audio/324e798f276840d914af.ogg"},{"id":"ja-Play_Vo_Char_NPC005_QTE_001","title":"Атака на входе I","description":"Фасс.","language":"Японский","audioUrl":"/nte-meta/game-audio/7686a116ebfeb68f9c0a.ogg"},{"id":"ja-Play_Vo_Char_NPC005_struck_002","title":"Урон II","description":"И говорить не стоит.","language":"Японский","audioUrl":"/nte-meta/game-audio/bd65bae310af9d4d7c06.ogg"},{"id":"en-Play_Vo_Char_NPC005_kill_002","title":"Убийство II","description":"Медленно, но верно.","language":"Английский","audioUrl":"/nte-meta/game-audio/18e02aed36ae663d54d9.ogg"},{"id":"en-Play_Vo_Char_NPC005_about_002","title":"О Байканге","description":"Если Байканг говорит, что «он истощен», «ему конец» или «он серьезно ранен»… лучше не тратить на него силы… Если он разговаривает, значит в достаточной степени жив и здоров. Говорю по опыту.","language":"Английский","audioUrl":"/nte-meta/game-audio/6b1acefdb25058b0d1e3.ogg"},{"id":"ja-Play_Vo_Char_NPC005_fh_002","title":"Исцеление II","description":"Спасибо за помощь.","language":"Японский","audioUrl":"/nte-meta/game-audio/8379dc271c6928749098.ogg"},{"id":"ja-Play_Vo_Char_NPC005_SSC_FDY_001","title":"Особое переключение I — Фадия","description":"ТОИ-4 на месте.","language":"Японский","audioUrl":"/nte-meta/game-audio/345e663a7cbdcf23c8fe.ogg"},{"id":"en-Play_Vo_Char_NPC005_about_001","title":"Об Альфарде","description":"Директор — целеустремленный лидер. Однако её не сильно волнует поведение подчиненных, она фокусируется лишь на результатах… Может быть, поэтому ТОИ так снисходителен к свободомыслию…","language":"Английский","audioUrl":"/nte-meta/game-audio/a1cdea095e8b575eebb7.ogg"},{"id":"en-Play_Vo_Char_NPC005_windfall_004","title":"Неожиданная добыча IV","description":"Стоило усилий.","language":"Английский","audioUrl":"/nte-meta/game-audio/2282a54552d0064d3194.ogg"},{"id":"en-Play_Vo_Char_NPC005_QTE_003","title":"Атака на входе III","description":"Я тебя прикрою!","language":"Английский","audioUrl":"/nte-meta/game-audio/b2ace50b043d8e81c239.ogg"},{"id":"en-Play_Vo_Char_NPC005_struck_001","title":"Урон I","description":"Просто царапина.","language":"Английский","audioUrl":"/nte-meta/game-audio/77acae77dea4b52910b6.ogg"},{"id":"ja-Play_Vo_Char_NPC005_struck_001","title":"Урон I","description":"Просто царапина.","language":"Японский","audioUrl":"/nte-meta/game-audio/34477c022ec821939c5a.ogg"},{"id":"en-Play_Vo_Char_NPC005_greet_004","title":"Спокойной ночи","description":"Ты отлично потрудился сегодня. Отдохни.Ты отлично потрудилась сегодня. Отдохни.","language":"Английский","audioUrl":"/nte-meta/game-audio/d0e7bafbed6dde10e58d.ogg"},{"id":"en-Play_Vo_Char_NPC005_SSC_FDY_001","title":"Особое переключение I — Фадия","description":"ТОИ-4 на месте.","language":"Английский","audioUrl":"/nte-meta/game-audio/4f2b5e5aa97d3049a0d4.ogg"},{"id":"ja-Play_Vo_Char_NPC005_DodgeCombo_001","title":"Серия критических уклонений I","description":"В тебе нет ничего особенного.","language":"Японский","audioUrl":"/nte-meta/game-audio/bf4b0520ccacf386c8b9.ogg"},{"id":"ja-Play_Vo_Char_NPC005_greet_001","title":"Утреннее приветствие","description":"Доброе утро. С чего сегодня начнем?","language":"Японский","audioUrl":"/nte-meta/game-audio/1b1e20b1ce516baf1abc.ogg"},{"id":"en-Play_Vo_Char_NPC005_Switch_003","title":"Переключение III","description":"В бой!","language":"Английский","audioUrl":"/nte-meta/game-audio/1f398d18a21057ce168a.ogg"},{"id":"ja-Play_Vo_Char_NPC005_about_002","title":"О Байканге","description":"Если Байканг говорит, что «он истощен», «ему конец» или «он серьезно ранен»… лучше не тратить на него силы… Если он разговаривает, значит в достаточной степени жив и здоров. Говорю по опыту.","language":"Японский","audioUrl":"/nte-meta/game-audio/fae9db18102af206be3e.ogg"},{"id":"en-Play_Vo_Char_NPC005_aoe_UI_003","title":"Сверхспособность III","description":"Время стать жестче.","language":"Английский","audioUrl":"/nte-meta/game-audio/212d9244105098eed965.ogg"},{"id":"en-Play_Vo_Char_NPC005_SSC_001","title":"Особое переключение I — Байканг","description":"ТОИ-4 на месте.","language":"Английский","audioUrl":"/nte-meta/game-audio/4f2b5e5aa97d3049a0d4.ogg"},{"id":"ja-Play_Vo_Char_NPC005_Fly_001","title":"Планирование I","description":"Я воспользуюсь возможностью осмотреться…","language":"Японский","audioUrl":"/nte-meta/game-audio/bbbdd27b6ae2ab3cfedd.ogg"},{"id":"en-Play_Vo_Char_NPC005_Switch_002","title":"Переключение II","description":"Я помогу.","language":"Английский","audioUrl":"/nte-meta/game-audio/f199bba864a262520290.ogg"},{"id":"ja-Play_Vo_Char_NPC005_Parry_002","title":"Парирование II","description":"Сдавайся немедленно!","language":"Японский","audioUrl":"/nte-meta/game-audio/3029770a11145c0491d0.ogg"},{"id":"en-Play_Vo_Char_NPC005_DodgeCombo_001","title":"Серия критических уклонений I","description":"В тебе нет ничего особенного.","language":"Английский","audioUrl":"/nte-meta/game-audio/54fd9ad005aa5753e67f.ogg"},{"id":"en-Play_Vo_Char_NPC005_weather_003","title":"Холодно","description":"Мне не холодно… но не рассчитывай на меня как на источник тепла.","language":"Английский","audioUrl":"/nte-meta/game-audio/d0274160d675768b3b95.ogg"},{"id":"ja-Play_Vo_Char_NPC005_deploy_002","title":"Отправка I","description":"ТОИ-4 уже здесь.","language":"Японский","audioUrl":"/nte-meta/game-audio/e79a517962d58ba9559c.ogg"},{"id":"en-Play_Vo_Char_NPC005_fh_001","title":"Исцеление I","description":"Как раз вовремя.","language":"Английский","audioUrl":"/nte-meta/game-audio/53371475fa676ea71b70.ogg"},{"id":"en-Play_Vo_Char_NPC005_hp_003","title":"Низкий уровень здоровья III","description":"Сохраняем спокойствие. Шанс ещё есть.","language":"Английский","audioUrl":"/nte-meta/game-audio/e1db097c382d7b891111.ogg"},{"id":"ja-Play_Vo_Char_NPC005_gift_002","title":"Подарок получен II","description":"Я был так завален работой, что совсем не было времени это купить. Не ожидал, что ты достанешь это для меня…","language":"Японский","audioUrl":"/nte-meta/game-audio/9a8922b1211d0bb8ae7a.ogg"},{"id":"ja-Play_Vo_Char_NPC005_Switch_003","title":"Переключение III","description":"В бой!","language":"Японский","audioUrl":"/nte-meta/game-audio/6d845738cce498209cbc.ogg"},{"id":"d498b0a3-6bad-4890-9211-196be2f37dc1","title":"Skia Voice Records / Profile Voice Lines — Английский","language":"Английский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=Qo3o25KqARM","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."},{"id":"c032487d-929e-4989-bba0-ba9f933d38d3","title":"Skia Voice Records / Profile Voice Lines — Японский","language":"Японский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=Qo3o25KqARM","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."},{"id":"766e4bc7-8174-4103-9aa6-42c0fac8d632","title":"Skia Voice Records / Profile Voice Lines — Корейский","language":"Корейский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=Qo3o25KqARM","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."},{"id":"baee3a6a-e2c6-4708-a840-72ecdf31dc7d","title":"Skia Voice Records / Profile Voice Lines — Китайский","language":"Китайский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=Qo3o25KqARM","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."}]') WHERE character_id='skia' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:22:54');

UPDATE character_profiles SET abilities_json=json('[{"id":"GA_Skia_Passive_1","name":"Подавление","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/b0b4b10dee92ea3116d8.webp","description":"Усиление реморы: когда Удар клыком фиксируется на цели в состоянии Реморы, на эту цель накладывается дополнительный эффект Реморы.\n\nОбычно физическое вмешательство не требуется – чтобы усмирить цель и не повредить помещение, Ския может просто воспользоваться своей тенью. Кроме того, он помогает с уборкой… Согласно проведённому в столовой ББА опросу, 84 % сотрудников рады видеть Скию на своём рабочем месте – так им меньше хлопот!","attributes":[]},{"id":"GA_Skia_Passive_3","name":"Теневая гончая","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/80238e4b2c1ed9eb5bc2.webp","description":"Удерживайте кнопки движения и уклонения, чтобы войти в режим Теневой гончей.\n\nТеневая гончая\n\nСкрывается в собственной тени, получая способность передвигаться по земле и стенам.\n\nНе обнаруживается врагами.\n\nДаёт иммунитет к некоторым типам атак, но прерывается при получении урона от наземных атак.\n\nНажатие кнопки базовой атаки или смена персонажа отменяет этот режим.\n\nПри достижении края платформы дальнейшее движение вперёд отменяет данный режим.\n\nОднажды Фадия спросила Скию, в каком положении ощущается его тело, когда оно погружено в тени. Не сумев это описать, Ския предложил ей воспользоваться воображением. Он предпочёл бы не знать, какие образы тогда возникли у неё в голове.","attributes":[]},{"id":"GA_Skia_QTE","name":"Ордер на арест","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/884d396d94680a4f25b6.webp","description":"Неотступные тени не дадут уйти. Направляет тень, словно ищейку, чтобы та вцепилась в цель, нанося 1 удар урона лакшаны по области.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"}]},{"id":"GA_Skia_Melee","name":"Искусство ареста","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/262a872eb2233781fb16.webp","description":"Базовая атака: Искусство ареста\nИспользует приёмы боевых искусств, чтобы провести до 5 последовательных атак, нанося урон лакшаны.\n\nОт его тени отделяется 1 Удар клыком и преследует каждую поражённую цель. На каждую цель одновременно может быть направлено до 3 Ударов клыком.\n\nБазовая атака: Контроль над территорией\nНаносит удары в воздухе и пикирует, нанося 1 удар урона лакшаны по области при ударе. Урон увеличивается в зависимости от высоты падения (максимальное увеличение — 100 %).\n\nУдар клыком\nОсколки теней, отделившиеся от тени Скии, напоминают клыки исполинского зверя. Они автоматически преследуют цели, присоединяются к ним и исчезают после того, как нанесут 1 удар урона лакшаны.\n\nКритический контрудар: Перо на бумаге\nСрабатывает при использовании Искусства ареста после критического уклонения. Атакует врагов тенями, разбрызгивающими чернила, нанося 1 удар урона лакшаны по области и снижая Разрушение.\n\n«Пёсик… Эта тёмная штука выходит с ударами пёсика… довольно впечатляюще».","attributes":[{"id":"parameter-0","label":"Множитель 1-го удара","value":"1: 30.4 % · 2: 32.8 % · 3: 35.5 % · 4: 38.3 % · 5: 41.4 % · 6: 44.7 % · 7: 48.2 % · 8: 52.1 % · 9: 56.3 % · 10: 60.8 % · 11: 65.6 % · 12: 70.9 % · 13: 76.6 %"},{"id":"parameter-1","label":"Множитель 2-го удара","value":"1: 3.7 %*2+18.9 % · 2: 4 %*2+20.4 % · 3: 4.3 %*2+22 % · 4: 4.7 %*2+23.8 % · 5: 5 %*2+25.7 % · 6: 5.4 %*2+27.8 % · 7: 5.9 %*2+30 % · 8: 6.3 %*2+32.4 % · 9: 6.8 %*2+35 % · 10: 7.4 %*2+37.8 % · 11: 8 %*2+40.8 % · 12: 8.6 %*2+44.1 % · 13: 9.3 %*2+47.6 %"},{"id":"parameter-2","label":"Множитель 3-го удара","value":"1: 32.1 %+45.9 % · 2: 34.7 %+49.6 % · 3: 37.4 %+53.5 % · 4: 40.4 %+57.8 % · 5: 43.7 %+62.4 % · 6: 47.2 %+67.4 % · 7: 50.9 %+72.8 % · 8: 55 %+78.7 % · 9: 59.4 %+85 % · 10: 64.2 %+91.8 % · 11: 69.3 %+99.1 % · 12: 74.8 %+107 % · 13: 80.8 %+115.6 %"},{"id":"parameter-3","label":"Множитель 4-го удара","value":"1: 39.1 % · 2: 42.2 % · 3: 45.6 % · 4: 49.3 % · 5: 53.2 % · 6: 57.5 % · 7: 62 % · 8: 67 % · 9: 72.4 % · 10: 78.2 % · 11: 84.4 % · 12: 91.2 % · 13: 98.5 %"},{"id":"parameter-4","label":"Множитель 5-го удара","value":"1: 29.4 %+55.4 % · 2: 31.8 %+59.8 % · 3: 34.3 %+64.6 % · 4: 37 %+69.8 % · 5: 40 %+75.4 % · 6: 43.2 %+81.4 % · 7: 46.7 %+87.9 % · 8: 50.4 %+94.9 % · 9: 54.4 %+102.5 % · 10: 58.8 %+110.7 % · 11: 63.5 %+119.6 % · 12: 68.6 %+129.2 % · 13: 74 %+139.5 %"},{"id":"parameter-5","label":"Множитель урона атаки в падении","value":"1: 100 % · 2: 108 % · 3: 116.6 % · 4: 126 % · 5: 136 % · 6: 146.9 % · 7: 158.7 % · 8: 171.4 % · 9: 185.1 % · 10: 199.9 % · 11: 215.9 % · 12: 233.2 % · 13: 251.8 %"},{"id":"parameter-6","label":"Множитель урона Удара клыком","value":"1: 10 % · 2: 10.8 % · 3: 11.7 % · 4: 12.6 % · 5: 13.6 % · 6: 14.7 % · 7: 15.9 % · 8: 17.1 % · 9: 18.5 % · 10: 20 % · 11: 21.6 % · 12: 23.3 % · 13: 25.2 %"},{"id":"parameter-8","label":"Множитель критического контрудара","value":"1: 208 % · 2: 224.6 % · 3: 242.6 % · 4: 262 % · 5: 283 % · 6: 305.6 % · 7: 330.1 % · 8: 356.5 % · 9: 385 % · 10: 415.8 % · 11: 449.1 % · 12: 485 % · 13: 523.8 %"}]},{"id":"GA_Skia_Skill","name":"Погоня теневой гончей","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/f6340e1b35ce688dc36e.webp","description":"Рабочая рутина, предназначенная для преследования. Переходит в состояние Слежение, скрывается в собственной тени и наносит 6 ударов урона лакшаны по области. Отделяет 3 Удара клыком от тени для каждой поражённой цели, затем переходит в режим Укус теневой гончей.\n\nСлежение\n\nПредотвращает исчезновение Ударов клыком после нанесения урона целям в этом состоянии.\n\nУкус теневой гончей\n\nПозволяет передвигаться по земле и стенам, аналогично режиму Теневой гончей.\n\nПриближение к вражеским целям остаётся незаметным.\n\nДаёт иммунитет к некоторым типам атак, но прерывается при получении урона от наземных атак.\n\nЗапускает дополнительные атаки Ударами клыком, касаясь врага, уже помеченного ударами.\n\nНажмите базовую атаку или переключите персонажа для выхода из этого режима во время его действия.\n\nПри достижении края платформы дальнейшее движение вперёд также отменяет этот режим.\n\nНаносит 1 удар урона лакшаны по области при выходе из режима.\n\nНекоторые проворные нарушители спокойствия думают, что могут уйти от погони ТОИ… Пусть проверят, что скрывается у них под ногами.","attributes":[{"id":"parameter-0","label":"Множитель урона четырёх ударов","value":"1: 30 % *4 · 2: 32.4 % *4 · 3: 35 % *4 · 4: 37.8 % *4 · 5: 40.8 % *4 · 6: 44.1 % *4 · 7: 47.6 % *4 · 8: 51.4 % *4 · 9: 55.5 % *4 · 10: 60 % *4 · 11: 64.8 % *4 · 12: 69.9 % *4 · 13: 75.5 % *4"},{"id":"parameter-1","label":"Множитель урона атаки в падении","value":"1: 4.6 %+25.4 % · 2: 5 %+27.4 % · 3: 5.4 %+29.6 % · 4: 5.8 %+32 % · 5: 6.3 %+34.6 % · 6: 6.8 %+37.3 % · 7: 7.3 %+40.3 % · 8: 7.9 %+43.5 % · 9: 8.5 %+47 % · 10: 9.2 %+50.8 % · 11: 9.9 %+54.8 % · 12: 10.7 %+59.2 % · 13: 11.6 %+64 %"},{"id":"parameter-2","label":"Длительность Слежения","value":"6 сек."},{"id":"parameter-3","label":"Множитель доп. урона «Удара клыком»","value":"1: 55 % · 2: 59.4 % · 3: 64.2 % · 4: 69.3 % · 5: 74.8 % · 6: 80.8 % · 7: 87.3 % · 8: 94.3 % · 9: 101.8 % · 10: 109.9 % · 11: 118.7 % · 12: 128.2 % · 13: 138.5 %"},{"id":"parameter-4","label":"Интервал дополнительного урона Удара клыком","value":"0.35 сек."},{"id":"parameter-5","label":"Длительность Укуса теневой гончей","value":"5 сек."},{"id":"parameter-6","label":"Множитель урона при выходе из «Укуса теневой гончей»","value":"1: 50 % · 2: 54 % · 3: 58.3 % · 4: 63 % · 5: 68 % · 6: 73.5 % · 7: 79.3 % · 8: 85.7 % · 9: 92.5 % · 10: 100 % · 11: 107.9 % · 12: 116.6 % · 13: 125.9 %"}]},{"id":"GA_Skia_UltraSkill","name":"Стая","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/e8e4c8350d4c473b8674.webp","description":"Рабочая рутина, предназначенная для подавления. Бросает вращающуюся зажигалку, за счёт чего его тень расплывается по земле во всех направлениях, нанося 1 удар урона лакшаны по области.\n\nПодобно хорошо обученным псам, несколько теней собираются в одном месте, нанося 3 удара урона лакшаны по области.\n\nПовышает урон Удара клыком после применения «Стаи» (включая урон от столкновений в режиме Укуса теневой гончей) и каждой атакой накладывает на цели эффект контроля.\n\nПоследствия «несоблюдения»","attributes":[{"id":"parameter-0","label":"Множитель урона разброса","value":"1: 290.2 % · 2: 313.4 % · 3: 338.5 % · 4: 365.6 % · 5: 394.8 % · 6: 426.4 % · 7: 460.5 % · 8: 497.4 % · 9: 537.1 % · 10: 580.1 % · 11: 626.5 % · 12: 676.6 % · 13: 730.8 %"},{"id":"parameter-1","label":"Множитель урона сбора","value":"1: 69.9 %*3 · 2: 75.5 %*3 · 3: 81.5 %*3 · 4: 88.1 %*3 · 5: 95.1 %*3 · 6: 102.7 %*3 · 7: 110.9 %*3 · 8: 119.8 %*3 · 9: 129.4 %*3 · 10: 139.7 %*3 · 11: 150.9 %*3 · 12: 163 %*3 · 13: 176 %*3"},{"id":"parameter-2","label":"Повышение урона удара клыком","value":"10 %"},{"id":"parameter-3","label":"Длительность увеличения урона","value":"15 сек."},{"id":"parameter-4","label":"Время контроля удара клыком","value":"0.75 сек."}]},{"id":"GA_Skia_Passive_2","name":"Задержание","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/0270d060d840b729f122.webp","description":"Повышает урон от Удара клыком на 10 % в течение 15 сек. после применения Стаи, включая урон от столкновений в режиме Укуса теневой гончей.\n\nВаше тело свободно, а вот тень зажата в железной хватке, так что вы не можете сдвинуться с места. Весьма своеобразное ощущение.","attributes":[]},{"id":"City_Ability_skia_01","name":"Менеджер среднего звена","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/450e7949d9f846c7410a.webp","description":"Ския увеличивает поток на 18.","attributes":[{"id":"city-0","label":"Уровень 1","value":"Ския увеличивает поток на 18."},{"id":"city-1","label":"Уровень 2","value":"Ския снижает скорость расхода ингредиентов на 1 %."},{"id":"city-2","label":"Уровень 3","value":"В режиме подборки владельца терпение клиента повышается на 50 %."},{"id":"city-3","label":"Уровень 4","value":"Ския снижает скорость расхода ингредиентов на 1 %."},{"id":"city-4","label":"Уровень 5","value":"Ския увеличивает поток на 27."}]}]') WHERE character_id='skia' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:22:54');

UPDATE character_profiles SET skins_json=json('[{"id":"Fashion_1008_0","name":"Рабочее время","description":"Практичный наряд, по дизайну напоминающий костюм, но адаптированный для удобства движения. Ския ушёл из предыдущей компании, но всё ещё предпочитает одеваться в том же стиле.","imageUrl":"/nte-meta/game-assets/1d248fb14ec01aafba42.webp"}]') WHERE character_id='skia' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:22:54');

