UPDATE character_profiles SET gifts_json=json('[{"id":"Food_011","name":"Освежающая тайна","iconUrl":"https://www.neverness.app/assets/codex/likeability/Food_011.webp","effect":"Симпатия +100"},{"id":"Food_060","name":"Глубины сердца","iconUrl":"https://www.neverness.app/assets/codex/likeability/Food_060.webp","effect":"Симпатия +100"},{"id":"Food_085","name":"Классическое трио","iconUrl":"https://www.neverness.app/assets/codex/likeability/Food_085.webp","effect":"Симпатия +100"},{"id":"Flower0000","name":"Золотой источник","iconUrl":"/nte-meta/game-assets/3d3fca122d07738632d9.webp","effect":"Симпатия +200"},{"id":"Furniture_draw_005","name":"Баланс","iconUrl":"https://www.neverness.app/assets/codex/likeability/Furniture_draw_005.webp","effect":"Симпатия +200"},{"id":"Furniture_FlowerPot_005","name":"Мерцающий лед","iconUrl":"/nte-meta/game-assets/2be2e12bf86bdb2f6873.webp","effect":"Симпатия +400"},{"id":"SpecialGift_ticket","name":"Билет в кинотеатр «Флоу»","iconUrl":"/nte-meta/game-assets/99060c23d3e0fef0599d.webp","effect":"Симпатия +400"},{"id":"SpecialGift_letter","name":"Рукописное письмо","iconUrl":"/nte-meta/game-assets/3deebe64fe65e4e200c3.webp","effect":"Симпатия +2000"}]') WHERE character_id='fadia' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 12:54:29');

