UPDATE character_profiles SET voice_actors_json=json('[{"language":"Китайский","name":"裴致莹"},{"language":"Английский","name":"Amber Lee Connors"},{"language":"Японский","name":"真堂圭"},{"language":"Корейский","name":"조현정"},{"language":"Японский","name":"Kei Shindo (真堂圭)"},{"language":"Китайский","name":"Pei Zhiying (裴致莹)"},{"language":"Корейский","name":"Jo Hyeonjeong (조현정)"}]') WHERE character_id='fadia' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 12:54:29');

UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Отступник","iconUrl":"/nte-meta/game-assets/1e530b5e9fdf53776c6f.webp","description":"Коэффициент перенаправления урона Фадии повышается до 75 %."},{"level":2,"kind":"awakening","name":"Инстинкт","iconUrl":"/nte-meta/game-assets/edf826bbefefc0ef6e41.webp","description":"Повышает показатель урона, получаемого врагами от Разрушительного опыта, до 600 %, а лимит урона — до 25 % от макс. ОЗ Фадии. Когда Разрушительный опыт снимается, он немедленно наносит урон, равный разнице между уже полученным уроном и предельным уроном."},{"level":3,"kind":"awakening","name":"Проклятие благословений","iconUrl":"/nte-meta/game-assets/87333eb8e8c2d7bcc1f2.webp","description":"Вступая в бой, Фадия увеличивает базовые макс. ОЗ на 30 %. После выхода из боя она теряет полученную прибавку к макс. ОЗ."},{"level":4,"kind":"awakening","name":"Нарушитель табу","iconUrl":"/nte-meta/game-assets/f4d59f08b0c830988c4b.webp","description":"Повышает коэффициент лечения Фадии в состоянии Лилит до 30 % от макс. ОЗ. Дополнительно повышает коэффициент лечения до 60 % от макс. ОЗ, если Фадия потеряла ОЗ не меньше, чем Разрушительный порог."},{"level":5,"kind":"awakening","name":"Выживание в смерти","iconUrl":"/nte-meta/game-assets/bee74eeb7e32efaef614.webp","description":"Увеличивает шанс крит. удара Фадии на 50 % в состоянии Лилит."},{"level":6,"kind":"awakening","name":"Несущий любовь и смерть","iconUrl":"/nte-meta/game-assets/185d1339f81a9c3ac89c.webp","description":"Накладывает Разрушительный опыт макс. на 10 целей в области действия. Длительность действия и лимит урона для каждого экземпляра Разрушительного опыта рассчитываются отдельно."},{"level":3,"kind":"resonance","name":"Неуважительный святой","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень навыков «Безмолвный отказ», «Существование» и «От агонии к эйфории» на 1."},{"level":6,"kind":"resonance","name":"Единый святой","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Когда Фадия в команде, даёт всем членам команды 10 % к макс. ОЗ."}]') WHERE character_id='fadia' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 12:54:29');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"en-Play_Vo_Char_NPC003_about_006","title":"О ТОИ","description":"Одна сторона обращена к ясному и понятному миру, другая — к тому, что люди отрицают и проклинают. Может быть именно поэтому ей удалось объединить нас в ТОИ-4.","language":"Английский","audioUrl":"/nte-meta/game-audio/a6f918d9d5c54b380656.ogg"},{"id":"en-Play_Vo_Char_NPC003_gift_001","title":"Подарок получен I","description":"Самое ценное не подарок… а ты! ♥","language":"Английский","audioUrl":"/nte-meta/game-audio/11603c53e7a4dadd0d78.ogg"},{"id":"ja-Play_Vo_Char_NPC003_Switch_001","title":"Переключение I","description":"Самое время.","language":"Японский","audioUrl":"/nte-meta/game-audio/fd82dca8881822272d55.ogg"},{"id":"ja-Play_Vo_Char_NPC003_TeammateDown_003","title":"Поражен товарищ по команде – Лакримоза","description":"Моза, спрячься ненадолго.","language":"Японский","audioUrl":"/nte-meta/game-audio/822da5f36db7ee4de98e.ogg"},{"id":"en-Play_Vo_Char_NPC003_weather_003","title":"Холодно","description":"Я всегда заряжена и готова!","language":"Английский","audioUrl":"/nte-meta/game-audio/6b9e339fdf958ce7dc87.ogg"},{"id":"ja-Play_Vo_Char_NPC003_DodgeCombo_002","title":"Серия критических уклонений II","description":"Просто мчишься вперёд… теряя темп.","language":"Японский","audioUrl":"/nte-meta/game-audio/0f7e25ac6aea52ffc76a.ogg"},{"id":"ja-Play_Vo_Char_NPC003_self_002","title":"Обо мне: популярность","description":"Что ж, их одержимость невозможно сдерживать!","language":"Японский","audioUrl":"/nte-meta/game-audio/c445b67fe9548c34408f.ogg"},{"id":"en-Play_Vo_Char_NPC003_TeammateDown_003","title":"Поражен товарищ по команде – Лакримоза","description":"Моза, спрячься ненадолго.","language":"Английский","audioUrl":"/nte-meta/game-audio/a2ff30b35d430a908ff4.ogg"},{"id":"ja-Play_Vo_Char_NPC003_greet_002","title":"Дневное приветствие","description":"Не угостишь меня выпивкой? Сейчас полдень — самое время немного развлечься и взбодриться.","language":"Японский","audioUrl":"/nte-meta/game-audio/657876c0b465ba540467.ogg"},{"id":"ja-Play_Vo_Char_NPC003_weather_004","title":"Жарко","description":"Моя одежда… липнет ко мне.","language":"Японский","audioUrl":"/nte-meta/game-audio/5fea7ed94de7a3fbb64c.ogg"},{"id":"en-Play_Vo_Char_NPC003_chat_002","title":"Чат: прохожий","description":"Интересно, какие желания скрываются под этими ничем не примечательными оболочками?","language":"Английский","audioUrl":"/nte-meta/game-audio/31ab865b5b7951abf8cd.ogg"},{"id":"ja-Play_Vo_Char_NPC003_SSC_002","title":"Особое переключение — Байканг","description":"Уже на смене? Быстро. Ну, это на тебя похоже.","language":"Японский","audioUrl":"/nte-meta/game-audio/c1e631defb004326d34f.ogg"},{"id":"en-Play_Vo_Char_NPC003_gift_002","title":"Подарок получен II","description":"Ты подарил мне это, потому что тебе понравилось? Как мило.Ты подарила мне это, потому что тебе понравилось? Как мило.","language":"Английский","audioUrl":"/nte-meta/game-audio/0b8fa624896e9bb4897d.ogg"},{"id":"en-Play_Vo_Char_NPC003_ug_001","title":"Вознесение персонажа I","description":"Эта… эта боль!","language":"Английский","audioUrl":"/nte-meta/game-audio/a16f9facab44fe1339df.ogg"},{"id":"en-Play_Vo_Char_NPC003_aoe_UI_001","title":"Сверхспособность I","description":"Я провожу тебя.","language":"Английский","audioUrl":"/nte-meta/game-audio/a82579fc04ae57102b46.ogg"},{"id":"en-Play_Vo_Char_NPC003_gift_004","title":"Подарок получен IV","description":"…Признаёшь свою Л-Ю-Б-О-В-Ь ко мне. Что ж, я принимаю.","language":"Английский","audioUrl":"/nte-meta/game-audio/b9e8345a8d42182461a1.ogg"},{"id":"ja-Play_Vo_Char_NPC003_about_002","title":"Об Альфарде","description":"О чем только думает эта гадюка, когда вылавливает опасных эсперов с Острова Грот для использования в собственных целях? Насколько нам известно, она может представлять не меньшую опасность, чем монстры с этого острова.","language":"Японский","audioUrl":"/nte-meta/game-audio/bef6501d59449fb66886.ogg"},{"id":"ja-Play_Vo_Char_NPC003_kill_001","title":"Убийство I","description":"Какая хрупкость.","language":"Японский","audioUrl":"/nte-meta/game-audio/567eff6be46f785c1419.ogg"},{"id":"ja-Play_Vo_Char_NPC003_TeammateDown_004","title":"Поражен товарищ по команде – Минт","description":"Так, на всякий случай напомню… у кошек девять жизней.","language":"Японский","audioUrl":"/nte-meta/game-audio/741bd17fdd3a45092f74.ogg"},{"id":"en-Play_Vo_Char_NPC003_Fly_002","title":"Планирование II","description":"Растяжка помогает снять мышечную боль.","language":"Английский","audioUrl":"/nte-meta/game-audio/09382a15567f45bfe21c.ogg"},{"id":"en-Play_Vo_Char_NPC003_TeammateDown_004","title":"Поражен товарищ по команде – Минт","description":"Так, на всякий случай напомню… у кошек девять жизней.","language":"Английский","audioUrl":"/nte-meta/game-audio/40db278f04a7d150d7e8.ogg"},{"id":"en-Play_Vo_Char_NPC003_anomaly_004","title":"Нуллификация II","description":"Болит?","language":"Английский","audioUrl":"/nte-meta/game-audio/e10cebd5db3aa7c1207a.ogg"},{"id":"en-Play_Vo_Char_NPC003_talk_003","title":"Тема: желания","description":"Людей разделяет пропасть, и желание — идеальный инструмент избавления от одиночества. Смерть отбрасывает тени страха и искушения между нами — прислушайся, она шепчет, она манит рисковать вновь и вновь.\\nБездну желания невозможно заполнить, невозможно удовлетворить — это тяготит не только тебя и меня, но все человечество. Так скажи мне, какие желания ты подавляешь прямо сейчас? Давай, покажи мне… чуть-чуть.","language":"Английский","audioUrl":"/nte-meta/game-audio/6dc1a49392e4f6269039.ogg"},{"id":"en-Play_Vo_Char_NPC003_windfall_002","title":"Неожиданная добыча II","description":"Кажется, придется повеселиться самой.","language":"Английский","audioUrl":"/nte-meta/game-audio/684ca6e5ca1b7c346199.ogg"},{"id":"ja-Play_Vo_Char_NPC003_self_003","title":"Обо мне: терпение","description":"Терпение охотника — довольно опасный знак… Хорошие охотники проявляют терпение только при преследовании добычи… прямо как я в случае с тобой. Ха-ха, вот и попались.","language":"Японский","audioUrl":"/nte-meta/game-audio/64b01d7266f93a589b11.ogg"},{"id":"en-Play_Vo_Char_NPC003_containment_002","title":"Сдерживание II","description":"Может, шанс на искупление…?","language":"Английский","audioUrl":"/nte-meta/game-audio/1d103f1f09cf4f23f488.ogg"},{"id":"en-Play_Vo_Char_NPC003_struck_002","title":"Урон II","description":"Какое разочарование.","language":"Английский","audioUrl":"/nte-meta/game-audio/6ea627df1f328824bfe1.ogg"},{"id":"ja-Play_Vo_Char_NPC003_gift_002","title":"Подарок получен II","description":"Ты подарил мне это, потому что тебе понравилось? Как мило.Ты подарила мне это, потому что тебе понравилось? Как мило.","language":"Японский","audioUrl":"/nte-meta/game-audio/5d6d22719f99ef9aedd7.ogg"},{"id":"ja-Play_Vo_Char_NPC003_hp_001","title":"Низкий уровень здоровья I","description":"Немного боли не повредит!","language":"Японский","audioUrl":"/nte-meta/game-audio/dc851f9476f5ec101242.ogg"},{"id":"ja-Play_Vo_Char_NPC003_talk_002","title":"Тема: Остров Грот","description":"Ты тоже здесь не впервые, да? Так скажи мне — это ужасная тюрьма, полная отчаяния, или священный рай для безумцев?","language":"Японский","audioUrl":"/nte-meta/game-audio/51fc938e0b6be97932e0.ogg"},{"id":"en-Play_Vo_Char_NPC003_windfall_003","title":"Неожиданная добыча III","description":"Меня не так легко расположить к себе.","language":"Английский","audioUrl":"/nte-meta/game-audio/7b42a1bd689ef227927a.ogg"},{"id":"en-Play_Vo_Char_NPC003_DodgeCombo_001","title":"Серия критических уклонений I","description":"Посмотри на себя — вечно куда-то несёшься.","language":"Английский","audioUrl":"/nte-meta/game-audio/60c8b08188b5b3ab511c.ogg"},{"id":"en-Play_Vo_Char_NPC003_greet_003","title":"Вечернее приветствие","description":"Ночь уже близко, может, пойдем куда-нибудь, где будет лучше в темноте?","language":"Английский","audioUrl":"/nte-meta/game-audio/38757958955261c278f3.ogg"},{"id":"en-Play_Vo_Char_NPC003_hstruck_001","title":"Сильный урон I","description":"Точно!","language":"Английский","audioUrl":"/nte-meta/game-audio/1f18fd2b143d39f85d5e.ogg"},{"id":"en-Play_Vo_Char_NPC003_SSC_004","title":"Особое переключение — Минт","description":"Лучшие лакомства нужно есть, пока они ещё тёплые.","language":"Английский","audioUrl":"/nte-meta/game-audio/9afd82d432f4a0006378.ogg"},{"id":"en-Play_Vo_Char_NPC003_fh_002","title":"Исцеление II","description":"Я ещё не насытилась этой агонией…","language":"Английский","audioUrl":"/nte-meta/game-audio/7fbbd46081ba1f8dbb8a.ogg"},{"id":"en-Play_Vo_Char_NPC003_SSC_002","title":"Особое переключение — Байканг","description":"Уже на смене? Быстро. Ну, это на тебя похоже.","language":"Английский","audioUrl":"/nte-meta/game-audio/985a4bf35af04a59c542.ogg"},{"id":"en-Play_Vo_Char_NPC003_about_004","title":"О Лакримозе","description":"Ни о чем не беспокоиться, должно быть, приятно… Оставайся невинной, пока можешь, маленькая милая Моза.","language":"Английский","audioUrl":"/nte-meta/game-audio/3e6ee7456b0a5207be07.ogg"},{"id":"ja-Play_Vo_Char_NPC003_dead_003","title":"Потеря сознания III","description":"Этот момент… он ускользает…","language":"Японский","audioUrl":"/nte-meta/game-audio/a30c3b16e4864d293dd9.ogg"},{"id":"ja-Play_Vo_Char_NPC003_greet_003","title":"Вечернее приветствие","description":"Ночь уже близко, может, пойдем куда-нибудь, где будет лучше в темноте?","language":"Японский","audioUrl":"/nte-meta/game-audio/945b4eea7bcef45dc529.ogg"},{"id":"en-Play_Vo_Char_NPC003_weather_004","title":"Жарко","description":"Моя одежда… липнет ко мне.","language":"Английский","audioUrl":"/nte-meta/game-audio/0e3b796aa7a16bfcf287.ogg"},{"id":"ja-Play_Vo_Char_NPC003_Fly_001","title":"Планирование I","description":"Давай переведём дух перед посадкой.","language":"Японский","audioUrl":"/nte-meta/game-audio/25476b44e6e57ef5726a.ogg"},{"id":"en-Play_Vo_Char_NPC003_greet_004","title":"Спокойной ночи","description":"Эй, рассвет ещё далеко, соня.","language":"Английский","audioUrl":"/nte-meta/game-audio/a5e8ce24e0692d60a01d.ogg"},{"id":"en-Play_Vo_Char_NPC003_self_002","title":"Обо мне: популярность","description":"Что ж, их одержимость невозможно сдерживать!","language":"Английский","audioUrl":"/nte-meta/game-audio/930cffdf933bedf5f8cc.ogg"},{"id":"en-Play_Vo_Char_NPC003_skill_003","title":"Навык перенаправления III","description":"Молодец.","language":"Английский","audioUrl":"/nte-meta/game-audio/5d16e386a7251b5ea707.ogg"},{"id":"ja-Play_Vo_Char_NPC003_TeammateDown_002","title":"Поражен товарищ по команде – Байканг","description":"Опять филонишь?","language":"Японский","audioUrl":"/nte-meta/game-audio/eba26d5bf2a309936fa3.ogg"},{"id":"ja-Play_Vo_Char_NPC003_hp_002","title":"Низкий уровень здоровья II","description":"Вот… что значит быть живой!","language":"Японский","audioUrl":"/nte-meta/game-audio/1b93cdf65d6f2e27f56c.ogg"},{"id":"ja-Play_Vo_Char_NPC003_ug_003","title":"Вознесение персонажа III","description":"Взбираться наверх без капли достоинства…? Хех, чего ты вообще добиваешься?","language":"Японский","audioUrl":"/nte-meta/game-audio/afda7373ce7cb4a7bca1.ogg"},{"id":"ja-Play_Vo_Char_NPC003_aoe_UI_002","title":"Сверхспособность II","description":"Близость через боль.","language":"Японский","audioUrl":"/nte-meta/game-audio/06bfa1ce83eadd983b9a.ogg"},{"id":"ja-Play_Vo_Char_NPC003_Parry_002","title":"Парирование II","description":"Скука.","language":"Японский","audioUrl":"/nte-meta/game-audio/36c724b9600beb6dadd9.ogg"},{"id":"en-Play_Vo_Char_NPC003_ug_002","title":"Вознесение персонажа II","description":"Я вижу… Я…","language":"Английский","audioUrl":"/nte-meta/game-audio/0ab5ed5f01eea83fcdc0.ogg"},{"id":"ja-Play_Vo_Char_NPC003_about_001","title":"О Байканге","description":"Всегда ведет себя, как бездельник, но этот парень… в глубине души настоящий святой.","language":"Японский","audioUrl":"/nte-meta/game-audio/ec42b436c23f3622aeda.ogg"},{"id":"ja-Play_Vo_Char_NPC003_skill_003","title":"Навык перенаправления III","description":"Молодец.","language":"Японский","audioUrl":"/nte-meta/game-audio/878309ea9b031ffd0ae0.ogg"},{"id":"ja-Play_Vo_Char_NPC003_SSC_001","title":"Особое переключение — Ския","description":"Это было совсем не удовлетворительно.","language":"Японский","audioUrl":"/nte-meta/game-audio/b2fd22abf0371aaf10ba.ogg"},{"id":"en-Play_Vo_Char_NPC003_gift_003","title":"Подарок получен III","description":"Подарки — это проявление привязанности. А значит, ты…","language":"Английский","audioUrl":"/nte-meta/game-audio/d05426fd9cfc551af6f6.ogg"},{"id":"ja-Play_Vo_Char_NPC003_chat_002","title":"Чат: прохожий","description":"Интересно, какие желания скрываются под этими ничем не примечательными оболочками?","language":"Японский","audioUrl":"/nte-meta/game-audio/a1d4c847603ad82fb21c.ogg"},{"id":"ja-Play_Vo_Char_NPC003_kill_002","title":"Убийство II","description":"Уже сломалось?","language":"Японский","audioUrl":"/nte-meta/game-audio/f3bcbd3ef34af84baf18.ogg"},{"id":"ja-Play_Vo_Char_NPC003_Parry_001","title":"Парирование I","description":"Маловато желания!","language":"Японский","audioUrl":"/nte-meta/game-audio/02173ffc24b4a309208c.ogg"},{"id":"en-Play_Vo_Char_NPC003_kill_002","title":"Убийство II","description":"Уже сломалось?","language":"Английский","audioUrl":"/nte-meta/game-audio/471da7c0c48e539719c6.ogg"},{"id":"en-Play_Vo_Char_NPC003_QTE_003","title":"Атака на входе III","description":"Меня ждёшь?","language":"Английский","audioUrl":"/nte-meta/game-audio/af78011c3777b964f37b.ogg"},{"id":"en-Play_Vo_Char_NPC003_hobby_001","title":"Хобби","description":"Если это приносит удовольствие, мне это нравится.","language":"Английский","audioUrl":"/nte-meta/game-audio/48fe6b4c034a72533e7d.ogg"},{"id":"ja-Play_Vo_Char_NPC003_DodgeCombo_001","title":"Серия критических уклонений I","description":"Посмотри на себя — вечно куда-то несёшься.","language":"Японский","audioUrl":"/nte-meta/game-audio/452a3811cc2d3005f726.ogg"},{"id":"ja-Play_Vo_Char_NPC003_hp_003","title":"Низкий уровень здоровья III","description":"Жизнь… лучше, когда она пылает дотла!","language":"Японский","audioUrl":"/nte-meta/game-audio/b1c14ed214d5b0eac486.ogg"},{"id":"ja-Play_Vo_Char_NPC003_QTE_001","title":"Атака на входе I","description":"Не стой у меня на пути!","language":"Японский","audioUrl":"/nte-meta/game-audio/986c0967f2da35984936.ogg"},{"id":"en-Play_Vo_Char_NPC003_self_003","title":"Обо мне: терпение","description":"Терпение охотника — довольно опасный знак… Хорошие охотники проявляют терпение только при преследовании добычи… прямо как я в случае с тобой. Ха-ха, вот и попались.","language":"Английский","audioUrl":"/nte-meta/game-audio/43a9c28a9e7077e2d6a0.ogg"},{"id":"ja-Play_Vo_Char_NPC003_struck_001","title":"Урон I","description":"Сильнее.","language":"Японский","audioUrl":"/nte-meta/game-audio/9b7882e405aef7f54c77.ogg"},{"id":"en-Play_Vo_Char_NPC003_dead_002","title":"Потеря сознания II","description":"Ха, значит, это…","language":"Английский","audioUrl":"/nte-meta/game-audio/ee00d1dcbd921cf4d604.ogg"},{"id":"en-Play_Vo_Char_NPC003_Fly_001","title":"Планирование I","description":"Давай переведём дух перед посадкой.","language":"Английский","audioUrl":"/nte-meta/game-audio/f2acd9368d9c3e178cbe.ogg"},{"id":"en-Play_Vo_Char_NPC003_greet_002","title":"Дневное приветствие","description":"Не угостишь меня выпивкой? Сейчас полдень — самое время немного развлечься и взбодриться.","language":"Английский","audioUrl":"/nte-meta/game-audio/1ffa8aca914b8843b370.ogg"},{"id":"ja-Play_Vo_Char_NPC003_greet_001","title":"Утреннее приветствие","description":"У тебя растрепанный вид, так сильно хотелось меня увидеть?","language":"Японский","audioUrl":"/nte-meta/game-audio/cdf344087e64a7971f28.ogg"},{"id":"ja-Play_Vo_Char_NPC003_skill_001","title":"Навык перенаправления I","description":"Хочешь еще?","language":"Японский","audioUrl":"/nte-meta/game-audio/f7ad3e0b9dd7f7786045.ogg"},{"id":"ja-Play_Vo_Char_NPC003_weather_003","title":"Холодно","description":"Я всегда заряжена и готова!","language":"Японский","audioUrl":"/nte-meta/game-audio/d033d50549534d2e06a0.ogg"},{"id":"ja-Play_Vo_Char_NPC003_windfall_006","title":"Неожиданная добыча VI","description":"Кто это тут оставил? Как жалко.","language":"Японский","audioUrl":"/nte-meta/game-audio/a3fbc712a14599472f55.ogg"},{"id":"en-Play_Vo_Char_NPC003_deploy_002","title":"Отправка I","description":"Поставь их на колени.","language":"Английский","audioUrl":"/nte-meta/game-audio/cfc5c8b85e511f25fb5e.ogg"},{"id":"en-Play_Vo_Char_NPC003_talk_001","title":"Тема: Гипервортекс","description":"Смотреть друг другу в глаза под небесами, прекрасными, как сама смерть… Окунуться в бесконечную пустоту, даже если это означает, что тебя разорвут на части, поглотят и низвергнут в ничто прямо здесь и сейчас… Как можно жаловаться?","language":"Английский","audioUrl":"/nte-meta/game-audio/ef7d88e787fa4c094d47.ogg"},{"id":"ja-Play_Vo_Char_NPC003_anomaly_003","title":"Нуллификация I","description":"Устрой мне шоу в следующий раз.","language":"Японский","audioUrl":"/nte-meta/game-audio/80b3e877d5b1a2dd182f.ogg"},{"id":"ja-Play_Vo_Char_NPC003_struck_002","title":"Урон II","description":"Какое разочарование.","language":"Японский","audioUrl":"/nte-meta/game-audio/71f36d445efcd6e988c9.ogg"},{"id":"en-Play_Vo_Char_NPC003_about_005","title":"О Бюро по борьбе с аномалиями","description":"В какой-то степени это место даже не вызывает у меня ненависти. В сравнении с полным хаосом прошлого так называемая непоколебимая рациональность здесь лишь узаконивает трансгрессии и табу под маской благородных намерений и красивых фасадов.","language":"Английский","audioUrl":"/nte-meta/game-audio/a0be5373587651614e55.ogg"},{"id":"en-Play_Vo_Char_NPC003_Switch_003","title":"Переключение III","description":"С чего начнём твои мучения?","language":"Английский","audioUrl":"/nte-meta/game-audio/346e6a30fbf2d49583dd.ogg"},{"id":"en-Play_Vo_Char_NPC003_containment_001","title":"Сдерживание I","description":"Могут ли аномалии любить?","language":"Английский","audioUrl":"/nte-meta/game-audio/df0398ef2a9c71f8ab7c.ogg"},{"id":"en-Play_Vo_Char_NPC003_SSC_003","title":"Особое переключение — Лакримоза","description":"Освобождать… это у меня получается лучше всего.","language":"Английский","audioUrl":"/nte-meta/game-audio/5cfaa0d62f835e85da68.ogg"},{"id":"en-Play_Vo_Char_NPC003_weather_001","title":"Солнечно","description":"Солнце ослепляет… Как будто на меня смотрят обжигающие глаза…","language":"Английский","audioUrl":"/nte-meta/game-audio/64fc1645008a2641b88a.ogg"},{"id":"en-Play_Vo_Char_NPC003_windfall_004","title":"Неожиданная добыча IV","description":"Так себе.","language":"Английский","audioUrl":"/nte-meta/game-audio/a2724283f7a104e8c83f.ogg"},{"id":"ja-Play_Vo_Char_NPC003_SSC_003","title":"Особое переключение — Лакримоза","description":"Освобождать… это у меня получается лучше всего.","language":"Японский","audioUrl":"/nte-meta/game-audio/eb06bced4bed45536e94.ogg"},{"id":"en-Play_Vo_Char_NPC003_deploy_001","title":"Отправка II","description":"Меня не интересуют слабаки.","language":"Английский","audioUrl":"/nte-meta/game-audio/a4c0cc6a622f978bdb62.ogg"},{"id":"ja-Play_Vo_Char_NPC003_deploy_002","title":"Отправка I","description":"Поставь их на колени.","language":"Японский","audioUrl":"/nte-meta/game-audio/779ba1f13edd27867a42.ogg"},{"id":"ja-Play_Vo_Char_NPC003_deploy_001","title":"Отправка II","description":"Меня не интересуют слабаки.","language":"Японский","audioUrl":"/nte-meta/game-audio/d2bcc59a293a6bcaa0c5.ogg"},{"id":"en-Play_Vo_Char_NPC003_chat_001","title":"Чат: работа","description":"Миссии? Расследования?.. Какая прелесть. С тем же успехом ТОИ мог бы работать под началом ассоциации жителей.","language":"Английский","audioUrl":"/nte-meta/game-audio/4a1a80029e235185cec9.ogg"},{"id":"en-Play_Vo_Char_NPC003_vexation_001","title":"Проблемы","description":"Если бы не этот сторожевой пес, миссии были бы намного веселее.","language":"Английский","audioUrl":"/nte-meta/game-audio/f69b557d8dc6da454feb.ogg"},{"id":"ja-Play_Vo_Char_NPC003_gift_004","title":"Подарок получен IV","description":"…Признаёшь свою Л-Ю-Б-О-В-Ь ко мне. Что ж, я принимаю.","language":"Японский","audioUrl":"/nte-meta/game-audio/3dfb50a73e7f34eec5a9.ogg"},{"id":"en-Play_Vo_Char_NPC003_struck_001","title":"Урон I","description":"Сильнее.","language":"Английский","audioUrl":"/nte-meta/game-audio/015b03306502eeef4506.ogg"},{"id":"ja-Play_Vo_Char_NPC003_fh_001","title":"Исцеление I","description":"Разве ты не волнуешься за меня?","language":"Японский","audioUrl":"/nte-meta/game-audio/30671cfd8cd8f12dfad9.ogg"},{"id":"ja-Play_Vo_Char_NPC003_aoe_UI_001","title":"Сверхспособность I","description":"Я провожу тебя.","language":"Японский","audioUrl":"/nte-meta/game-audio/160241847126a9936024.ogg"},{"id":"ja-Play_Vo_Char_NPC003_Switch_002","title":"Переключение II","description":"Очаровашка, начинаем игру.","language":"Японский","audioUrl":"/nte-meta/game-audio/dbb7912880882897c3e7.ogg"},{"id":"ja-Play_Vo_Char_NPC003_ug_002","title":"Вознесение персонажа II","description":"Я вижу… Я…","language":"Японский","audioUrl":"/nte-meta/game-audio/a32480b774ca8666ad42.ogg"},{"id":"ja-Play_Vo_Char_NPC003_windfall_002","title":"Неожиданная добыча II","description":"Кажется, придется повеселиться самой.","language":"Японский","audioUrl":"/nte-meta/game-audio/53aeabd5d9beede74596.ogg"},{"id":"en-Play_Vo_Char_NPC003_skill_002","title":"Навык перенаправления II","description":"Лучше привыкай.","language":"Английский","audioUrl":"/nte-meta/game-audio/aa360027ef6981b7bc3b.ogg"},{"id":"ja-Play_Vo_Char_NPC003_self_001","title":"Обо мне: способности эспера","description":"Для бренной увядающей плоти нет ничего лучше боли. Она живет, она процветает и в головокружительном трепете и ошеломительной жестокости приближает нас к смерти.","language":"Японский","audioUrl":"/nte-meta/game-audio/a843ed91a0c1e7c49a60.ogg"},{"id":"en-Play_Vo_Char_NPC003_talk_002","title":"Тема: Остров Грот","description":"Ты тоже здесь не впервые, да? Так скажи мне — это ужасная тюрьма, полная отчаяния, или священный рай для безумцев?","language":"Английский","audioUrl":"/nte-meta/game-audio/41da57ed3f108c203245.ogg"},{"id":"en-Play_Vo_Char_NPC003_anomaly_003","title":"Нуллификация I","description":"Устрой мне шоу в следующий раз.","language":"Английский","audioUrl":"/nte-meta/game-audio/d066128666d6a63d6446.ogg"},{"id":"en-Play_Vo_Char_NPC003_aoe_UI_003","title":"Сверхспособность III","description":"Я оправдаю твои ожидания","language":"Английский","audioUrl":"/nte-meta/game-audio/27fc3875b926aa0991d3.ogg"},{"id":"ja-Play_Vo_Char_NPC003_SSC_004","title":"Особое переключение — Минт","description":"Лучшие лакомства нужно есть, пока они ещё тёплые.","language":"Японский","audioUrl":"/nte-meta/game-audio/92491a8dcf51f5d97d2c.ogg"},{"id":"ja-Play_Vo_Char_NPC003_Switch_003","title":"Переключение III","description":"С чего начнём твои мучения?","language":"Японский","audioUrl":"/nte-meta/game-audio/036dd8c459537b0d33c1.ogg"},{"id":"en-Play_Vo_Char_NPC003_about_003","title":"О Скии","description":"Когда не хочется слушать его болтовню, достаточно отвлечь его с помощью небольшого… трюка. Пес ставит контроль над ситуацией выше собственных мыслей и чувств.","language":"Английский","audioUrl":"/nte-meta/game-audio/5f6d9468c7eb3ddd1126.ogg"},{"id":"ja-Play_Vo_Char_NPC003_chat_001","title":"Чат: работа","description":"Миссии? Расследования?.. Какая прелесть. С тем же успехом ТОИ мог бы работать под началом ассоциации жителей.","language":"Японский","audioUrl":"/nte-meta/game-audio/bf437aea396ca5ab1e10.ogg"},{"id":"ja-Play_Vo_Char_NPC003_windfall_005","title":"Неожиданная добыча V","description":"Кое-что, чтобы заполнить пробелы.","language":"Японский","audioUrl":"/nte-meta/game-audio/53eb2fd0e339d1dee94c.ogg"},{"id":"en-Play_Vo_Char_NPC003_chat_003","title":"Чат: наблюдение","description":"Хех, эти дурачки из Фраксинуса… Каждый раз приходится притворяться, что я не замечаю их… такая морока.","language":"Английский","audioUrl":"/nte-meta/game-audio/38f849efd1657db3af50.ogg"},{"id":"en-Play_Vo_Char_NPC003_SSC_001","title":"Особое переключение — Ския","description":"Это было совсем не удовлетворительно.","language":"Английский","audioUrl":"/nte-meta/game-audio/a760b4a9ecdcc59fc02d.ogg"},{"id":"ja-Play_Vo_Char_NPC003_containment_001","title":"Сдерживание I","description":"Могут ли аномалии любить?","language":"Японский","audioUrl":"/nte-meta/game-audio/49b031ada2f29185fd66.ogg"},{"id":"en-Play_Vo_Char_NPC003_windfall_006","title":"Неожиданная добыча VI","description":"Кто это тут оставил? Как жалко.","language":"Английский","audioUrl":"/nte-meta/game-audio/2a91f183f96d96940470.ogg"},{"id":"ja-Play_Vo_Char_NPC003_Fly_002","title":"Планирование II","description":"Растяжка помогает снять мышечную боль.","language":"Японский","audioUrl":"/nte-meta/game-audio/9c7d7a738723011987a7.ogg"},{"id":"ja-Play_Vo_Char_NPC003_greet_004","title":"Спокойной ночи","description":"Эй, рассвет ещё далеко, соня.","language":"Японский","audioUrl":"/nte-meta/game-audio/6e18686f89dfdf8bf512.ogg"},{"id":"en-Play_Vo_Char_NPC003_dead_003","title":"Потеря сознания III","description":"Этот момент… он ускользает…","language":"Английский","audioUrl":"/nte-meta/game-audio/c6b998bfe6565734eff4.ogg"},{"id":"en-Play_Vo_Char_NPC003_fh_001","title":"Исцеление I","description":"Разве ты не волнуешься за меня?","language":"Английский","audioUrl":"/nte-meta/game-audio/f62cd8ae15c9be9fe591.ogg"},{"id":"en-Play_Vo_Char_NPC003_hp_003","title":"Низкий уровень здоровья III","description":"Жизнь… лучше, когда она пылает дотла!","language":"Английский","audioUrl":"/nte-meta/game-audio/44f635daee075df44c95.ogg"},{"id":"ja-Play_Vo_Char_NPC003_containment_002","title":"Сдерживание II","description":"Может, шанс на искупление…?","language":"Японский","audioUrl":"/nte-meta/game-audio/0a4a34a9eee3ecec6fe4.ogg"},{"id":"en-Play_Vo_Char_NPC003_hp_002","title":"Низкий уровень здоровья II","description":"Вот… что значит быть живой!","language":"Английский","audioUrl":"/nte-meta/game-audio/2778726aacb58b61b163.ogg"},{"id":"en-Play_Vo_Char_NPC003_windfall_005","title":"Неожиданная добыча V","description":"Кое-что, чтобы заполнить пробелы.","language":"Английский","audioUrl":"/nte-meta/game-audio/2d055d9a8edca84b6c24.ogg"},{"id":"en-Play_Vo_Char_NPC003_aoe_UI_002","title":"Сверхспособность II","description":"Близость через боль.","language":"Английский","audioUrl":"/nte-meta/game-audio/3549d4a0fad15c06b240.ogg"},{"id":"en-Play_Vo_Char_NPC003_Parry_002","title":"Парирование II","description":"Скука.","language":"Английский","audioUrl":"/nte-meta/game-audio/e4064307b1e6284cc434.ogg"},{"id":"en-Play_Vo_Char_NPC003_Switch_002","title":"Переключение II","description":"Очаровашка, начинаем игру.","language":"Английский","audioUrl":"/nte-meta/game-audio/650963529a6b79b11016.ogg"},{"id":"ja-Play_Vo_Char_NPC003_about_006","title":"О ТОИ","description":"Одна сторона обращена к ясному и понятному миру, другая — к тому, что люди отрицают и проклинают. Может быть именно поэтому ей удалось объединить нас в ТОИ-4.","language":"Японский","audioUrl":"/nte-meta/game-audio/6a8bf92016adc9274024.ogg"},{"id":"en-Play_Vo_Char_NPC003_hstruck_002","title":"Сильный урон II","description":"Обожаю!","language":"Английский","audioUrl":"/nte-meta/game-audio/19457865e731254367d0.ogg"},{"id":"en-Play_Vo_Char_NPC003_QTE_001","title":"Атака на входе I","description":"Не стой у меня на пути!","language":"Английский","audioUrl":"/nte-meta/game-audio/bdc53de209fa67c95c57.ogg"},{"id":"ja-Play_Vo_Char_NPC003_fh_002","title":"Исцеление II","description":"Я ещё не насытилась этой агонией…","language":"Японский","audioUrl":"/nte-meta/game-audio/d74f389a594f124db7a6.ogg"},{"id":"ja-Play_Vo_Char_NPC003_ug_001","title":"Вознесение персонажа I","description":"Эта… эта боль!","language":"Японский","audioUrl":"/nte-meta/game-audio/d263ce285440b0724c31.ogg"},{"id":"en-Play_Vo_Char_NPC003_hp_001","title":"Низкий уровень здоровья I","description":"Немного боли не повредит!","language":"Английский","audioUrl":"/nte-meta/game-audio/ccc9586d2f4b9bbd6c66.ogg"},{"id":"en-Play_Vo_Char_NPC003_ug_003","title":"Вознесение персонажа III","description":"Взбираться наверх без капли достоинства…? Хех, чего ты вообще добиваешься?","language":"Английский","audioUrl":"/nte-meta/game-audio/b63b43d75fa57e959a7c.ogg"},{"id":"ja-Play_Vo_Char_NPC003_about_003","title":"О Скии","description":"Когда не хочется слушать его болтовню, достаточно отвлечь его с помощью небольшого… трюка. Пес ставит контроль над ситуацией выше собственных мыслей и чувств.","language":"Японский","audioUrl":"/nte-meta/game-audio/eff5a70751a4df89ebea.ogg"},{"id":"ja-Play_Vo_Char_NPC003_talk_001","title":"Тема: Гипервортекс","description":"Смотреть друг другу в глаза под небесами, прекрасными, как сама смерть… Окунуться в бесконечную пустоту, даже если это означает, что тебя разорвут на части, поглотят и низвергнут в ничто прямо здесь и сейчас… Как можно жаловаться?","language":"Японский","audioUrl":"/nte-meta/game-audio/8e05297d863a154b2d46.ogg"},{"id":"ja-Play_Vo_Char_NPC003_talk_003","title":"Тема: желания","description":"Людей разделяет пропасть, и желание — идеальный инструмент избавления от одиночества. Смерть отбрасывает тени страха и искушения между нами — прислушайся, она шепчет, она манит рисковать вновь и вновь.\\nБездну желания невозможно заполнить, невозможно удовлетворить — это тяготит не только тебя и меня, но все человечество. Так скажи мне, какие желания ты подавляешь прямо сейчас? Давай, покажи мне… чуть-чуть.","language":"Японский","audioUrl":"/nte-meta/game-audio/f1e871d49d833ef35c2b.ogg"},{"id":"ja-Play_Vo_Char_NPC003_QTE_002","title":"Атака на входе II","description":"Идеальная сцена.","language":"Японский","audioUrl":"/nte-meta/game-audio/3d205d4a3a795dc7685e.ogg"},{"id":"ja-Play_Vo_Char_NPC003_about_005","title":"О Бюро по борьбе с аномалиями","description":"В какой-то степени это место даже не вызывает у меня ненависти. В сравнении с полным хаосом прошлого так называемая непоколебимая рациональность здесь лишь узаконивает трансгрессии и табу под маской благородных намерений и красивых фасадов.","language":"Японский","audioUrl":"/nte-meta/game-audio/9667ef685fd92f058436.ogg"},{"id":"en-Play_Vo_Char_NPC003_Parry_001","title":"Парирование I","description":"Маловато желания!","language":"Английский","audioUrl":"/nte-meta/game-audio/651d0488858447f3fac6.ogg"},{"id":"ja-Play_Vo_Char_NPC003_vexation_001","title":"Проблемы","description":"Если бы не этот сторожевой пес, миссии были бы намного веселее.","language":"Японский","audioUrl":"/nte-meta/game-audio/01a56dc73b33e58e6026.ogg"},{"id":"ja-Play_Vo_Char_NPC003_aoe_UI_003","title":"Сверхспособность III","description":"Я оправдаю твои ожидания","language":"Японский","audioUrl":"/nte-meta/game-audio/4f0ed289d57b224c5047.ogg"},{"id":"ja-Play_Vo_Char_NPC003_hobby_001","title":"Хобби","description":"Если это приносит удовольствие, мне это нравится.","language":"Японский","audioUrl":"/nte-meta/game-audio/32f94a5746fdbca56b07.ogg"},{"id":"en-Play_Vo_Char_NPC003_greet_001","title":"Утреннее приветствие","description":"У тебя растрепанный вид, так сильно хотелось меня увидеть?","language":"Английский","audioUrl":"/nte-meta/game-audio/93fb72fcd0a3016dadbc.ogg"},{"id":"en-Play_Vo_Char_NPC003_weather_002","title":"Дождливо","description":"Забавно видеть этих чопорных и благопристойных кукол в таком беспорядке, по лицам стекают капли дождя.","language":"Английский","audioUrl":"/nte-meta/game-audio/fc84edae99d94a2435c8.ogg"},{"id":"en-Play_Vo_Char_NPC003_windfall_001","title":"Неожиданная добыча I","description":"Это всё, что у тебя есть?","language":"Английский","audioUrl":"/nte-meta/game-audio/f52e63a516fd60e37802.ogg"},{"id":"ja-Play_Vo_Char_NPC003_about_004","title":"О Лакримозе","description":"Ни о чем не беспокоиться, должно быть, приятно… Оставайся невинной, пока можешь, маленькая милая Моза.","language":"Японский","audioUrl":"/nte-meta/game-audio/63ec04f7bad502c214d0.ogg"},{"id":"ja-Play_Vo_Char_NPC003_chat_003","title":"Чат: наблюдение","description":"Хех, эти дурачки из Фраксинуса… Каждый раз приходится притворяться, что я не замечаю их… такая морока.","language":"Японский","audioUrl":"/nte-meta/game-audio/cc6393b9cc75004c1848.ogg"},{"id":"ja-Play_Vo_Char_NPC003_gift_001","title":"Подарок получен I","description":"Самое ценное не подарок… а ты! ♥","language":"Японский","audioUrl":"/nte-meta/game-audio/9928046a3628cc0b8986.ogg"},{"id":"ja-Play_Vo_Char_NPC003_meet_001","title":"Первая встреча","description":"Это Фадия. Как видишь, сейчас я… на испытательном сроке… в этом месте, полном норм и правил. Моя интуиция подсказывает, что мы будем видеться часто. Лучше запомни меня, а не то…","language":"Японский","audioUrl":"/nte-meta/game-audio/ca00358b2dfaa1c4ae42.ogg"},{"id":"ja-Play_Vo_Char_NPC003_windfall_003","title":"Неожиданная добыча III","description":"Меня не так легко расположить к себе.","language":"Японский","audioUrl":"/nte-meta/game-audio/7f3cac327f9c4fcd3015.ogg"},{"id":"en-Play_Vo_Char_NPC003_DodgeCombo_002","title":"Серия критических уклонений II","description":"Просто мчишься вперёд… теряя темп.","language":"Английский","audioUrl":"/nte-meta/game-audio/a1fa7fcb73645204c722.ogg"},{"id":"en-Play_Vo_Char_NPC003_TeammateDown_001","title":"Поражен товарищ по команде – Ския","description":"Каждый должен защищать животных.","language":"Английский","audioUrl":"/nte-meta/game-audio/c79a5aac50c2166a6b48.ogg"},{"id":"ja-Play_Vo_Char_NPC003_gift_003","title":"Подарок получен III","description":"Подарки — это проявление привязанности. А значит, ты…","language":"Японский","audioUrl":"/nte-meta/game-audio/8af9d5ba818fb5e1beca.ogg"},{"id":"ja-Play_Vo_Char_NPC003_TeammateDown_001","title":"Поражен товарищ по команде – Ския","description":"Каждый должен защищать животных.","language":"Японский","audioUrl":"/nte-meta/game-audio/cc242c6c237e43b905a4.ogg"},{"id":"ja-Play_Vo_Char_NPC003_windfall_004","title":"Неожиданная добыча IV","description":"Так себе.","language":"Японский","audioUrl":"/nte-meta/game-audio/5df7bdf77db984e25739.ogg"},{"id":"en-Play_Vo_Char_NPC003_skill_001","title":"Навык перенаправления I","description":"Хочешь еще?","language":"Английский","audioUrl":"/nte-meta/game-audio/5bb32b3d66fe08ada917.ogg"},{"id":"ja-Play_Vo_Char_NPC003_dead_001","title":"Потеря сознания I","description":"Какое яростное проявление любви…","language":"Японский","audioUrl":"/nte-meta/game-audio/c9a8e7fde9d34f95ed1e.ogg"},{"id":"ja-Play_Vo_Char_NPC003_dead_002","title":"Потеря сознания II","description":"Ха, значит, это…","language":"Японский","audioUrl":"/nte-meta/game-audio/b455d3743c9515db73b0.ogg"},{"id":"en-Play_Vo_Char_NPC003_meet_001","title":"Первая встреча","description":"Это Фадия. Как видишь, сейчас я… на испытательном сроке… в этом месте, полном норм и правил. Моя интуиция подсказывает, что мы будем видеться часто. Лучше запомни меня, а не то…","language":"Английский","audioUrl":"/nte-meta/game-audio/928f31de1422eb2ad1d6.ogg"},{"id":"en-Play_Vo_Char_NPC003_Switch_001","title":"Переключение I","description":"Самое время.","language":"Английский","audioUrl":"/nte-meta/game-audio/ced21f41575ae8270468.ogg"},{"id":"ja-Play_Vo_Char_NPC003_weather_001","title":"Солнечно","description":"Солнце ослепляет… Как будто на меня смотрят обжигающие глаза…","language":"Японский","audioUrl":"/nte-meta/game-audio/3e3f223aecd8824417c2.ogg"},{"id":"en-Play_Vo_Char_NPC003_about_001","title":"О Байканге","description":"Всегда ведет себя, как бездельник, но этот парень… в глубине души настоящий святой.","language":"Английский","audioUrl":"/nte-meta/game-audio/a22cf8584d3414e28a92.ogg"},{"id":"en-Play_Vo_Char_NPC003_dead_001","title":"Потеря сознания I","description":"Какое яростное проявление любви…","language":"Английский","audioUrl":"/nte-meta/game-audio/5bb642318d652a80c3f7.ogg"},{"id":"en-Play_Vo_Char_NPC003_QTE_002","title":"Атака на входе II","description":"Идеальная сцена.","language":"Английский","audioUrl":"/nte-meta/game-audio/23d0c4f8a114c98331c9.ogg"},{"id":"en-Play_Vo_Char_NPC003_self_001","title":"Обо мне: способности эспера","description":"Для бренной увядающей плоти нет ничего лучше боли. Она живет, она процветает и в головокружительном трепете и ошеломительной жестокости приближает нас к смерти.","language":"Английский","audioUrl":"/nte-meta/game-audio/76bf49bbd399da820c99.ogg"},{"id":"ja-Play_Vo_Char_NPC003_anomaly_004","title":"Нуллификация II","description":"Болит?","language":"Японский","audioUrl":"/nte-meta/game-audio/87a15aa807ca06e9b1f3.ogg"},{"id":"ja-Play_Vo_Char_NPC003_weather_002","title":"Дождливо","description":"Забавно видеть этих чопорных и благопристойных кукол в таком беспорядке, по лицам стекают капли дождя.","language":"Японский","audioUrl":"/nte-meta/game-audio/49a2ccd539aa6ad0bf8d.ogg"},{"id":"en-Play_Vo_Char_NPC003_TeammateDown_002","title":"Поражен товарищ по команде – Байканг","description":"Опять филонишь?","language":"Английский","audioUrl":"/nte-meta/game-audio/dbe03f8333758ea0cdf5.ogg"},{"id":"ja-Play_Vo_Char_NPC003_hstruck_001","title":"Сильный урон I","description":"Точно!","language":"Японский","audioUrl":"/nte-meta/game-audio/2c445d1c8d3ca5d12b63.ogg"},{"id":"ja-Play_Vo_Char_NPC003_hstruck_002","title":"Сильный урон II","description":"Обожаю!","language":"Японский","audioUrl":"/nte-meta/game-audio/160c30a08df89809144d.ogg"},{"id":"ja-Play_Vo_Char_NPC003_windfall_001","title":"Неожиданная добыча I","description":"Это всё, что у тебя есть?","language":"Японский","audioUrl":"/nte-meta/game-audio/c3f06cfa97481fd5d144.ogg"},{"id":"en-Play_Vo_Char_NPC003_about_002","title":"Об Альфарде","description":"О чем только думает эта гадюка, когда вылавливает опасных эсперов с Острова Грот для использования в собственных целях? Насколько нам известно, она может представлять не меньшую опасность, чем монстры с этого острова.","language":"Английский","audioUrl":"/nte-meta/game-audio/91102253850c94fb4a43.ogg"},{"id":"en-Play_Vo_Char_NPC003_kill_001","title":"Убийство I","description":"Какая хрупкость.","language":"Английский","audioUrl":"/nte-meta/game-audio/3226e7a25cd4b2b1cb08.ogg"},{"id":"ja-Play_Vo_Char_NPC003_QTE_003","title":"Атака на входе III","description":"Меня ждёшь?","language":"Японский","audioUrl":"/nte-meta/game-audio/735e672952d6e17759d3.ogg"},{"id":"ja-Play_Vo_Char_NPC003_skill_002","title":"Навык перенаправления II","description":"Лучше привыкай.","language":"Японский","audioUrl":"/nte-meta/game-audio/e50555bc7f871a18b954.ogg"}]') WHERE character_id='fadia' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 12:54:29');

UPDATE character_profiles SET abilities_json=json('[{"id":"GA_Fadia_Passive_1","name":"Горнило вины","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/8beb047d89a07aa9edb7.webp","description":"Усиление Новы: позволяет всем союзникам высасывать макс. ОЗ из цели по завершении «Новы». Цель теряет макс. ОЗ, равные 200 % от базовых макс. ОЗ Фадии, а каждый союзник получает макс. ОЗ, равные 10 % от базовых макс. ОЗ Фадии. Общий объём не может превышать 50 % от базовых макс. ОЗ Фадии. При выходе из боя показатели обеих сторон восстанавливаются.\n\nЕще… ЕЩЕ! Заполни эту пустоту – если сможешь!","attributes":[]},{"id":"GA_Fadia_QTE","name":"Чужак","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/41bdad38cab35f1e6c6f.webp","description":"Взмахивает крестообразным щитом, нанося 1 удар урона психики по области.\n\nОтойди, ты загораживаешь камеру!","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"}]},{"id":"GA_Fadia_Skill","name":"Существование","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/5802ec1527b7d3a98abe.webp","description":"Подходи, попробуй это на вкус. Фадия наносит 1 удар урона психики по области и на некоторое время накладывает Разрушительный опыт на врага с наибольшими макс. ОЗ в зоне поражения.\n\nНа протяжении действия эффекта, когда Фадия получает урон, цель получает определённый процент от нанесённого Фадии урона.\n\nРазрушительный опыт прекращается по окончании времени действия, при достижении предела перенаправленного урона, полученного целью посредством Разрушительного опыта, или если цель и Фадия выходят из боя.\n\n«Кстати, дружеский совет от её товарища по команде. Нападать на неё прямо сейчас – не самое разумное решение…»","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 1.6 % + 2.5 % + 2.5 % макс. ОЗ · 2: 1.7 % + 2.7 % + 2.7 % макс. ОЗ · 3: 1.9 % + 2.9 % + 2.9 % макс. ОЗ · 4: 2 % + 3.1 % + 3.1 % макс. ОЗ · 5: 2.2 % + 3.4 % + 3.4 % макс. ОЗ · 6: 2.4 % + 3.7 % + 3.7 % макс. ОЗ · 7: 2.5 % + 4 % + 4 % макс. ОЗ · 8: 2.7 % + 4.3 % + 4.3 % макс. ОЗ · 9: 3 % + 4.6 % + 4.6 % макс. ОЗ · 10: 3.2 % + 5 % + 5 % макс. ОЗ · 11: 3.5 % + 5.4 % + 5.4 % макс. ОЗ · 12: 3.7 % + 5.8 % + 5.8 % макс. ОЗ · 13: 4 % + 6.3 % + 6.3 % макс. ОЗ"}]},{"id":"GA_Fadia_Melee","name":"Безмолвный отказ","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/ba5f3c3f45d18aea13d1.webp","description":"Безмолвный отказ\nПроводит до 5 последовательных атак подряд своим крестовым щитом, нанося Урон психики.\n\nВсе взгляды на мне\nПока значение текущих ОЗ Фадии превышает 1, она до всех эффектов щита перенаправляет на себя часть урона, получаемого товарищами по команде. Перенаправленный урон нельзя перераспределять дальше.\n\nКогда значение текущих ОЗ Фадии снижается до 1, она перестает перенаправлять урон. Если в это время Фадия получает урон, она до всех эффектов щита делит его с выжившими товарищами по команде, а оставшийся урон поглощает сама.\n\nПадающее презрение\nРазмахивает крестовым щитом в воздухе и пикирует, нанося 1 удар урона психики по области при ударе. Урон увеличивается в зависимости от высоты падения (до 100 %).\n\nКритический контрудар: срабатывание уклонения\nАктивируется при применении «Безмолвного отказа» после срабатывания критического уклонения. Устремляется к цели на высокой скорости и наносит 1 удар урона психики по области и снижает показатель разрушения.\n\nСамое смешное в живых – это то, как вы преклоняетесь перед очевидными смыслами и подчиняетесь власти приказов. Так почему бы и не посмеяться над такими жалкими червями?","attributes":[{"id":"parameter-0","label":"Множитель 1-го удара","value":"1: 43.3 % · 2: 46.8 % · 3: 50.5 % · 4: 54.5 % · 5: 58.9 % · 6: 63.6 % · 7: 68.7 % · 8: 74.2 % · 9: 80.1 % · 10: 86.6 % · 11: 93.5 % · 12: 101 % · 13: 109 %"},{"id":"parameter-1","label":"Множитель 2-го удара","value":"1: 29.7 %+36 % · 2: 32.1 %+38.9 % · 3: 34.6 %+42 % · 4: 37.4 %+45.3 % · 5: 40.4 %+49 % · 6: 43.6 %+52.9 % · 7: 47.1 %+57.1 % · 8: 50.9 %+61.7 % · 9: 55 %+66.6 % · 10: 59.4 %+72 % · 11: 64.1 %+77.7 % · 12: 69.2 %+83.9 % · 13: 74.8 %+90.7 %"},{"id":"parameter-2","label":"Множитель 3-го удара","value":"1: 77.1 % · 2: 83.3 % · 3: 89.9 % · 4: 97.1 % · 5: 104.9 % · 6: 113.3 % · 7: 122.3 % · 8: 132.1 % · 9: 142.7 % · 10: 154.1 % · 11: 166.5 % · 12: 179.8 % · 13: 194.2 %"},{"id":"parameter-3","label":"Множитель 4-го удара","value":"1: 28.3 %+33.2 % · 2: 30.6 %+35.9 % · 3: 33 %+38.7 % · 4: 35.6 %+41.8 % · 5: 38.5 %+45.2 % · 6: 41.6 %+48.8 % · 7: 44.9 %+52.7 % · 8: 48.5 %+56.9 % · 9: 52.4 %+61.5 % · 10: 56.6 %+66.4 % · 11: 61.1 %+71.7 % · 12: 66 %+77.4 % · 13: 71.3 %+83.6 %"},{"id":"parameter-4","label":"Множитель 5-го удара","value":"1: 27.3 %+80.3 % · 2: 29.5 %+86.7 % · 3: 31.8 %+93.7 % · 4: 34.4 %+101.2 % · 5: 37.1 %+109.2 % · 6: 40.1 %+118 % · 7: 43.3 %+127.4 % · 8: 46.8 %+137.6 % · 9: 50.5 %+148.6 % · 10: 54.6 %+160.5 % · 11: 58.9 %+173.4 % · 12: 63.7 %+187.2 % · 13: 68.7 %+202.2 %"},{"id":"parameter-5","label":"Множитель урона атаки в падении","value":"1: 60 % · 2: 64.8 % · 3: 70 % · 4: 75.6 % · 5: 81.6 % · 6: 88.2 % · 7: 95.2 % · 8: 102.8 % · 9: 111.1 % · 10: 119.9 % · 11: 129.5 % · 12: 139.9 % · 13: 151.1 %"},{"id":"parameter-8","label":"Множитель критического контрудара","value":"1: 178 % · 2: 192.2 % · 3: 207.6 % · 4: 224.2 % · 5: 242.2 % · 6: 261.5 % · 7: 282.5 % · 8: 305.1 % · 9: 329.5 % · 10: 355.8 % · 11: 384.3 % · 12: 415 % · 13: 448.2 %"}]},{"id":"GA_Fadia_Passive_2","name":"Отрицание и грабёж","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/4c64f977a190bf9bf96b.webp","description":"Словно младенец, так жаждущий материнского молока. Когда Фадия в команде, макс. ОЗ у команды увеличиваются на 10 %.\n\nЕсли хочешь, бери.","attributes":[]},{"id":"GA_Fadia_UltraSkill","name":"От агонии к эйфории","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/4b9ce1a02cc12571c2b2.webp","description":"Без боли жизнь замыкается на самой себе. Фадия входит в состояние Лилит, нанося 6 ударов ментального урона и восстанавливая ОЗ. Повторно примените Безмолвный отказ в состоянии Лилит, чтобы провести до 5 последующих атак, каждая из которых наносит ментальный урон.\n\nКогда потеря ОЗ достигает Разрушительного порога, полностью восстанавливает энергию сверхспособности «От агонии к эйфории». Увеличивает урон и восстановление ОЗ сверхспособности «От агонии к эйфории», если она применяется, когда потеря ОЗ больше или равна Разрушительному порогу.\n\nФадия выходит из состояния Лилит, когда заканчивается время действия, проводятся все 5 последующих атак, происходит смена персонажа или используются другие навыки Фадии.\n\n«Раз уж директор решила использовать нестабильность, мой долг – наблюдать и ограничивать ее, чтобы столь опасная волатильность оставалась в управляемых пределах».","attributes":[{"id":"parameter-0","label":"Множитель 1-го удара","value":"1: 3.9 % макс. ОЗ · 2: 4.2 % макс. ОЗ · 3: 4.5 % макс. ОЗ · 4: 4.9 % макс. ОЗ · 5: 5.3 % макс. ОЗ · 6: 5.7 % макс. ОЗ · 7: 6.2 % макс. ОЗ · 8: 6.7 % макс. ОЗ · 9: 7.2 % макс. ОЗ · 10: 7.8 % макс. ОЗ · 11: 8.4 % макс. ОЗ · 12: 9.1 % макс. ОЗ · 13: 9.8 % макс. ОЗ"},{"id":"parameter-1","label":"Множитель 2-го удара","value":"1: 1.2 % *4 макс. ОЗ · 2: 1.3 % *4 макс. ОЗ · 3: 1.4 % *4 макс. ОЗ · 4: 1.5 % *4 макс. ОЗ · 5: 1.6 % *4 макс. ОЗ · 6: 1.8 % *4 макс. ОЗ · 7: 1.9 % *4 макс. ОЗ · 8: 2.1 % *4 макс. ОЗ · 9: 2.2 % *4 макс. ОЗ · 10: 2.4 % *4 макс. ОЗ · 11: 2.6 % *4 макс. ОЗ · 12: 2.8 % *4 макс. ОЗ · 13: 3 % *4 макс. ОЗ"},{"id":"parameter-2","label":"Множитель 3-го удара","value":"1: 6.3 % макс. ОЗ · 2: 6.8 % макс. ОЗ · 3: 7.3 % макс. ОЗ · 4: 7.9 % макс. ОЗ · 5: 8.6 % макс. ОЗ · 6: 9.3 % макс. ОЗ · 7: 10 % макс. ОЗ · 8: 10.8 % макс. ОЗ · 9: 11.7 % макс. ОЗ · 10: 12.6 % макс. ОЗ · 11: 13.6 % макс. ОЗ · 12: 14.7 % макс. ОЗ · 13: 15.9 % макс. ОЗ"},{"id":"parameter-3","label":"Множитель 1-й последующей атаки","value":"1: 2 % макс. ОЗ · 2: 2.2 % макс. ОЗ · 3: 2.3 % макс. ОЗ · 4: 2.5 % макс. ОЗ · 5: 2.7 % макс. ОЗ · 6: 2.9 % макс. ОЗ · 7: 3.2 % макс. ОЗ · 8: 3.4 % макс. ОЗ · 9: 3.7 % макс. ОЗ · 10: 4 % макс. ОЗ · 11: 4.3 % макс. ОЗ · 12: 4.7 % макс. ОЗ · 13: 5 % макс. ОЗ"},{"id":"parameter-4","label":"Множитель 2-й последующей атаки","value":"1: 3.2 %+3.6 % макс. ОЗ · 2: 3.5 %+3.9 % макс. ОЗ · 3: 3.7 %+4.2 % макс. ОЗ · 4: 4 %+4.5 % макс. ОЗ · 5: 4.4 %+4.9 % макс. ОЗ · 6: 4.7 %+5.3 % макс. ОЗ · 7: 5.1 %+5.7 % макс. ОЗ · 8: 5.5 %+6.2 % макс. ОЗ · 9: 5.9 %+6.7 % макс. ОЗ · 10: 6.4 %+7.2 % макс. ОЗ · 11: 6.9 %+7.8 % макс. ОЗ · 12: 7.5 %+8.4 % макс. ОЗ · 13: 8.1 %+9.1 % макс. ОЗ"},{"id":"parameter-5","label":"Множитель 3-й последующей атаки","value":"1: 0.9 %*2+1.5 % макс. ОЗ · 2: 1 %*2+1.6 % макс. ОЗ · 3: 1 %*2+1.7 % макс. ОЗ · 4: 1.1 %*2+1.9 % макс. ОЗ · 5: 1.2 %*2+2 % макс. ОЗ · 6: 1.3 %*2+2.2 % макс. ОЗ · 7: 1.4 %*2+2.4 % макс. ОЗ · 8: 1.5 %*2+2.6 % макс. ОЗ · 9: 1.7 %*2+2.8 % макс. ОЗ · 10: 1.8 %*2+3 % макс. ОЗ · 11: 1.9 %*2+3.2 % макс. ОЗ · 12: 2.1 %*2+3.5 % макс. ОЗ · 13: 2.3 %*2+3.8 % макс. ОЗ"},{"id":"parameter-6","label":"Множитель 4-й последующей атаки","value":"1: 2.3 %*5+5.6 % макс. ОЗ · 2: 2.5 %*5+6 % макс. ОЗ · 3: 2.7 %*5+6.5 % макс. ОЗ · 4: 2.9 %*5+7.1 % макс. ОЗ · 5: 3.1 %*5+7.6 % макс. ОЗ · 6: 3.4 %*5+8.2 % макс. ОЗ · 7: 3.6 %*5+8.9 % макс. ОЗ · 8: 3.9 %*5+9.6 % макс. ОЗ · 9: 4.3 %*5+10.4 % макс. ОЗ · 10: 4.6 %*5+11.2 % макс. ОЗ · 11: 5 %*5+12.1 % макс. ОЗ · 12: 5.4 %*5+13.1 % макс. ОЗ · 13: 5.8 %*5+14.1 % макс. ОЗ"},{"id":"parameter-7","label":"Множитель 5-й последующей атаки","value":"1: 5.9 % макс. ОЗ · 2: 6.4 % макс. ОЗ · 3: 6.9 % макс. ОЗ · 4: 7.4 % макс. ОЗ · 5: 8 % макс. ОЗ · 6: 8.7 % макс. ОЗ · 7: 9.4 % макс. ОЗ · 8: 10.1 % макс. ОЗ · 9: 10.9 % макс. ОЗ · 10: 11.8 % макс. ОЗ · 11: 12.7 % макс. ОЗ · 12: 13.8 % макс. ОЗ · 13: 14.9 % макс. ОЗ"}]},{"id":"GA_Fadia_Passive_3","name":"Очаровательная королева","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/e2c20a74dda933e618a8.webp","description":"Позволяет Фадии получать во время прогулки по городу особые подарки от продавцов, которым она понравилась.\n\nКогда Ския и Лакримоза после задания проходили по улице Тамамочи, Лакримоза зашла в мини-маркет «2-Four». Она думала, что выйдет оттуда с охапкой бесплатных пакетов кетчупа, как Фадия, которую всегда осыпают подарками…\n\nВ итоге все, что она получила, – это награда, за которую пришлось заплатить Ские.","attributes":[]},{"id":"City_Ability_fadia_02","name":"Хорошее вождение","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/3da5b878c41674baae00.webp","description":"Даёт дополнительно 1000 фонсов чаевых за каждый заказ в «Быстром такси».","attributes":[{"id":"city-0","label":"Уровень 1","value":"Даёт дополнительно 1000 фонсов чаевых за каждый заказ в «Быстром такси»."},{"id":"city-1","label":"Уровень 2","value":"В «Быстром такси» итоговая удовлетворённость от заказов дополнительно повышается на 25 очков."},{"id":"city-2","label":"Уровень 3","value":"Даёт дополнительно 1000 фонсов чаевых за каждый заказ в «Быстром такси»."},{"id":"city-3","label":"Уровень 4","value":"В «Быстром такси» итоговая удовлетворённость от заказов дополнительно повышается на 25 очков."},{"id":"city-4","label":"Уровень 5","value":"В «Быстром такси» максимальная удовлетворённость каждого клиента повышается на 50 очков."}]}]') WHERE character_id='fadia' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 12:54:29');

UPDATE character_profiles SET skins_json=json('[{"id":"Fashion_1039_nighty","name":"Ночные сказки","description":"Домашняя одежда Фадии. Комфорт для неё не столь важен, скорее она предпочитает одежду, которая подчёркивает таинственность ночи.\n\n«Тьма сохранит наши секреты».","imageUrl":"/nte-meta/game-assets/53001112ea3933091773.webp"},{"id":"Fashion_1039_0","name":"Тягучий соблазн","description":"Соблазнительный облегающий наряд с цветками желания, распускающимися на груди. Постарайтесь не засматриваться.","imageUrl":"/nte-meta/game-assets/19ba5643a23506ac2618.webp"}]') WHERE character_id='fadia' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 12:54:29');

