UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Я тут новенькая! Встречайте отличницу по обмену!","iconUrl":"/nte-meta/game-assets/22f11c5f5dbd22a98664.webp","description":"Увеличивает максимальное количество зарядов Сюжетной брони до 6 и лимит отскоков Паранормальной пушки до 6."},{"level":2,"kind":"awakening","name":"Всё, как в аниме! Задняя парта у окошка!","iconUrl":"/nte-meta/game-assets/d82115fb08e7d8cd3a3a.webp","description":"Увеличивает длительность действия Фили на 4 сек."},{"level":3,"kind":"awakening","name":"Общий сбор! Герой созвал союзников!","iconUrl":"/nte-meta/game-assets/2b0a7ef7bf98e0308a5d.webp","description":"В состоянии Паранормального аса шанс крит. удара Ханиэль увеличивается на 20 %."},{"level":4,"kind":"awakening","name":"Морской бриз! Пляжный эпизод!","iconUrl":"/nte-meta/game-assets/f5275168594a38f2c610.webp","description":"После того как Ханиэль активирует Ансамбль в состоянии Паранормального аса, дополнительный урон от следующей атаки Ханиэль увеличивается на 100 %."},{"level":5,"kind":"awakening","name":"Катастрофа! Доверие рушится!","iconUrl":"/nte-meta/game-assets/e290b7e8bd62f02011cf.webp","description":"Будучи в состоянии Паранормального аса, Ханиэль наносит на 30 % больше урона психики."},{"level":6,"kind":"awakening","name":"Финал! Во имя рассвета!","iconUrl":"/nte-meta/game-assets/c331086ff60731c00d55.webp","description":"Уменьшает перезарядку Фили на 4 сек."},{"level":3,"kind":"resonance","name":"Приквел","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень навыков «Техника Генесса», «Хранитель лунного леса» и «Мелодия в честь Ханиэль» на 1."},{"level":6,"kind":"resonance","name":"Сиквел","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Увеличивает крит. урон команды на 12 % в состоянии Паранормального аса."}]') WHERE character_id='haniel' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:28:54');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"en-Play_Vo_Char_NPC014_vexation_001","title":"Проблемы","description":"Большие проблемы? Таких нет. Мелкие неурядицы? Много домашки, шумный Иллика, непонятные адреса доставки, привередливые клиенты… Ничего, что нельзя было бы решить хорошей едой и сном. Ханиэль всегда полна сил на следующий день!","language":"Английский","audioUrl":"/nte-meta/game-audio/be3499f8eb9f8bd51d14.ogg"},{"id":"ja-Play_Vo_Char_NPC014_talk_002","title":"Тема: манеры","description":"Ножи слева, вилки справа, и не хлюпать супом? Если нельзя наслаждаться едой, в чем смысл? Как пряные палочки — их нужно класть на позолоченную тарелку под звуки скрипки… но ничто не сравнится с тем, чтобы просто съесть их прямо из пакета.","language":"Японский","audioUrl":"/nte-meta/game-audio/9b063775a14af7f53583.ogg"},{"id":"ja-Play_Vo_Char_NPC014_dead_001","title":"Потеря сознания I","description":"Так не должно было закончиться…","language":"Японский","audioUrl":"/nte-meta/game-audio/edab8989d15265f29c39.ogg"},{"id":"ja-Play_Vo_Char_NPC014_about_003","title":"Об Иллике","description":"Ах, этот шумный Глупыш! Знала бы я, что мы опять окажемся вместе в «Стерри Экспресс», ни за что не стала бы писать столько всего в его выпускном альбоме… Хотя в моем тоже многое написал. Даже подарил мне на выпускной гарнитуру, о которой я сто лет мечтала. Так что… я отпустила ситуацию.","language":"Японский","audioUrl":"/nte-meta/game-audio/dca40da5c26a283e1c29.ogg"},{"id":"ja-Play_Vo_Char_NPC014_Switch_002","title":"Переключение II","description":"Пора сменить ритм!","language":"Японский","audioUrl":"/nte-meta/game-audio/392acf67a68862a856cb.ogg"},{"id":"en-Play_Vo_Char_NPC014_DodgeCombo_002","title":"Серия критических уклонений II","description":"Тск-тск, слишком медленно!","language":"Английский","audioUrl":"/nte-meta/game-audio/f8dbece3aa96b5188e1c.ogg"},{"id":"ja-Play_Vo_Char_NPC014_gift_002","title":"Подарок получен II","description":"Как ты догадался, что мне это нравится? Ты что, ещё и чужие вкусы умеешь «оценивать»? Это так круто! Как ты догадалась, что мне это нравится? Ты что, ещё и чужие вкусы умеешь «оценивать»? Это так круто!","language":"Японский","audioUrl":"/nte-meta/game-audio/34d338222ea5a5c1c5a0.ogg"},{"id":"ja-Play_Vo_Char_NPC014_greet_003","title":"Вечернее приветствие","description":"Добрый вечер! Я иду на прогулку. Хочешь со мной?","language":"Японский","audioUrl":"/nte-meta/game-audio/a4d2af5a6f40879a2a9f.ogg"},{"id":"ja-Play_Vo_Char_NPC014_Parry_001","title":"Парирование I","description":"Ритм-игры — моя специализация!","language":"Японский","audioUrl":"/nte-meta/game-audio/0cede660e844a63f34bc.ogg"},{"id":"en-Play_Vo_Char_NPC014_about_006","title":"Об антикварном магазине Эйбон","description":"Скрытый от посторонних глаз антикварный магазин на тенистой улице против работающей под прикрытием у всех на виду компании экспресс-доставки… этот сюжет просто создан для кино!","language":"Английский","audioUrl":"/nte-meta/game-audio/cfe69982d58a47e884ba.ogg"},{"id":"en-Play_Vo_Char_NPC014_hobby_001","title":"Хобби","description":"Моя цель? Заполучить каждую гарнитуру из лимитированной коллекции! Новые можно купить сразу после выпуска, но с винтажными требуется терпение. Конечно, даже лучшие старые гарнитуры не сравнятся с современными дешевками по качеству звука… но классические саундтреки и нужно слушать с аналоговым потрескиванием. Когда-нибудь покажу тебе свою коллекцию.","language":"Английский","audioUrl":"/nte-meta/game-audio/228abbcfd52740055ab7.ogg"},{"id":"ja-Play_Vo_Char_NPC014_ug_001","title":"Вознесение персонажа I","description":"Так значит ЭТО… сила?","language":"Японский","audioUrl":"/nte-meta/game-audio/c4f6aaafa61052fd5958.ogg"},{"id":"en-Play_Vo_Char_NPC014_self_003","title":"Обо мне: свобода","description":"«Некоторые птицы отлично чувствуют себя в клетке — их яркие перья распушаются от корма и воды. Но другие не созданы для того, чтобы быть взаперти. Их крылья сияют только в открытом небе». Я? Мне нужны теплый дом и свобода. Может, я жадина, но мне нравится моя жизнь.","language":"Английский","audioUrl":"/nte-meta/game-audio/a8668ba04739ce3a8973.ogg"},{"id":"en-Play_Vo_Char_NPC014_about_001","title":"О Цзююань","description":"Работа в «Стерри Экспресс» не мешает учебе, хорошо оплачивается и идет в комплекте с миссией по спасению мира! Кроме того, Цзююань очень щедра на премии — на что тут можно жаловаться? Я, Ханиэль, стану лучшим курьером «Стерри»! Если бы только Цзююань так не злилась… стресс вызывает морщины, знаешь ли… кхм.","language":"Английский","audioUrl":"/nte-meta/game-audio/8a7638dda919ce714099.ogg"},{"id":"en-Play_Vo_Char_NPC014_aoe_UI_001","title":"Сверхспособность I","description":"Моя очередь!","language":"Английский","audioUrl":"/nte-meta/game-audio/90be35565945571ec8bd.ogg"},{"id":"en-Play_Vo_Char_NPC014_deploy_002","title":"Отправка II","description":"Охо-хо, чую, кто‑то тут скучает по Ханиэль!","language":"Английский","audioUrl":"/nte-meta/game-audio/6b7556d8ef58265bdb09.ogg"},{"id":"en-Play_Vo_Char_NPC014_greet_001","title":"Утреннее приветствие","description":"Доброе утро! Начинается новый день!","language":"Английский","audioUrl":"/nte-meta/game-audio/16541a4811cb00803f26.ogg"},{"id":"ja-Play_Vo_Char_NPC014_greet_004","title":"Спокойной ночи","description":"Ночь — отличное время для аниме. Не волнуйся, всего одна серия перед сном! Наверное…","language":"Японский","audioUrl":"/nte-meta/game-audio/2aa88428e71a609020e2.ogg"},{"id":"en-Play_Vo_Char_NPC014_QTE_002","title":"Атака на входе II","description":"Эй, ты куда смотришь?","language":"Английский","audioUrl":"/nte-meta/game-audio/91bc01866d876d6aef7e.ogg"},{"id":"en-Play_Vo_Char_NPC014_weather_001","title":"Солнечно","description":"Такой прекрасный солнечный день. Идеален для сна… или чего угодно.","language":"Английский","audioUrl":"/nte-meta/game-audio/466696eb732ca861459a.ogg"},{"id":"ja-Play_Vo_Char_NPC014_anomaly_001","title":"Нуллификация I","description":"Не забудь поставить мне пять звёзд!","language":"Японский","audioUrl":"/nte-meta/game-audio/76adb8c4f1db75edadeb.ogg"},{"id":"ja-Play_Vo_Char_NPC014_skill_003","title":"Навык перенаправления III","description":"Ну не будь занудой!","language":"Японский","audioUrl":"/nte-meta/game-audio/d26d63019455e75d4b03.ogg"},{"id":"en-Play_Vo_Char_NPC014_TeammateDown_003","title":"Поражен товарищ по команде – Наналли","description":"Мы не можем сдаться в такой момент!","language":"Английский","audioUrl":"/nte-meta/game-audio/69aab7fc47925499fecf.ogg"},{"id":"ja-Play_Vo_Char_NPC014_chat_003","title":"Чат: кошачья еда","description":"Нужно принести корм с новым вкусом, когда буду навещать котят в эти выходные.","language":"Японский","audioUrl":"/nte-meta/game-audio/3f75f8d8c370c80e78eb.ogg"},{"id":"ja-Play_Vo_Char_NPC014_SSC_003","title":"Особое переключение — Наналли","description":"Зажигаем! Рычащая тигрица!","language":"Японский","audioUrl":"/nte-meta/game-audio/4cfd68a35a37c08ca886.ogg"},{"id":"en-Play_Vo_Char_NPC014_hp_001","title":"Низкий уровень здоровья I","description":"Я совсем без сил…","language":"Английский","audioUrl":"/nte-meta/game-audio/5876d9cd81899033459a.ogg"},{"id":"ja-Play_Vo_Char_NPC014_aoe_UI_002","title":"Сверхспособность II","description":"Теперь мой звёздный час!","language":"Японский","audioUrl":"/nte-meta/game-audio/665137c30a8b2fd53765.ogg"},{"id":"ja-Play_Vo_Char_NPC014_talk_003","title":"Тема: коллеги-энтузиасты","description":"Поразительно, как люди сходятся друг с другом. Общая любовь к какому-нибудь персонажу — и вот два незнакомца уже лучшие друзья. Есть вещи, которые я не могу рассказать друзьям в реальной жизни, но которыми без проблем поделюсь с кем-нибудь в сети. У меня есть одна особенная онлайн-подруга… надеюсь, мы когда-нибудь встретимся вживую.","language":"Японский","audioUrl":"/nte-meta/game-audio/5081977c2cc5ad582403.ogg"},{"id":"en-Play_Vo_Char_NPC014_dead_003","title":"Потеря сознания III","description":"Простите, теперь всё зависит от вас…","language":"Английский","audioUrl":"/nte-meta/game-audio/d5bf3bd5a0cefcd7ac7a.ogg"},{"id":"en-Play_Vo_Char_NPC014_SSC_001","title":"Особое переключение — Цзююань","description":"Цзююань! Я с этим справлюсь!","language":"Английский","audioUrl":"/nte-meta/game-audio/8154f5e04f678e974cd3.ogg"},{"id":"en-Play_Vo_Char_NPC014_windfall_005","title":"Неожиданная добыча V","description":"М-м-м! Это заслуживает праздничного поста в Bagel!","language":"Английский","audioUrl":"/nte-meta/game-audio/4dfc5098af0c1469b1fc.ogg"},{"id":"ja-Play_Vo_Char_NPC014_Parry_002","title":"Парирование II","description":"Лови ритм!","language":"Японский","audioUrl":"/nte-meta/game-audio/6506c83d0a325d972978.ogg"},{"id":"ja-Play_Vo_Char_NPC014_self_003","title":"Обо мне: свобода","description":"«Некоторые птицы отлично чувствуют себя в клетке — их яркие перья распушаются от корма и воды. Но другие не созданы для того, чтобы быть взаперти. Их крылья сияют только в открытом небе». Я? Мне нужны теплый дом и свобода. Может, я жадина, но мне нравится моя жизнь.","language":"Японский","audioUrl":"/nte-meta/game-audio/c0419656c18627e98e0a.ogg"},{"id":"ja-Play_Vo_Char_NPC014_struck_002","title":"Урон II","description":"Небольшая ошибочка!","language":"Японский","audioUrl":"/nte-meta/game-audio/a96a207b9e38a4a858af.ogg"},{"id":"en-Play_Vo_Char_NPC014_weather_004","title":"Жарко","description":"Спокойно, спокойно, спокойно… Ф-фух… 72-я попытка медитации Ханиэль… провалилась.","language":"Английский","audioUrl":"/nte-meta/game-audio/ba78dd8e56d3e9cdde82.ogg"},{"id":"ja-Play_Vo_Char_NPC014_chat_001","title":"Чат: ограниченная продажа","description":"Будильник — проверено! Wi-Fi — проверено! В этот раз я точно урву лимитированную новинку!","language":"Японский","audioUrl":"/nte-meta/game-audio/fbf3cd6c912baa5b8d12.ogg"},{"id":"ja-Play_Vo_Char_NPC014_skill_002","title":"Навык перенаправления II","description":"Может, немного разнообразия?","language":"Японский","audioUrl":"/nte-meta/game-audio/77591172d041073b8730.ogg"},{"id":"en-Play_Vo_Char_NPC014_about_003","title":"Об Иллике","description":"Ах, этот шумный Глупыш! Знала бы я, что мы опять окажемся вместе в «Стерри Экспресс», ни за что не стала бы писать столько всего в его выпускном альбоме… Хотя в моем тоже многое написал. Даже подарил мне на выпускной гарнитуру, о которой я сто лет мечтала. Так что… я отпустила ситуацию.","language":"Английский","audioUrl":"/nte-meta/game-audio/edfa37183199d97dcc0b.ogg"},{"id":"en-Play_Vo_Char_NPC014_containment_002","title":"Сдерживание II","description":"Не переживай! Мои навыки упаковки на высшем уровне… Уф… всё в порядке, н-ничего страшного.","language":"Английский","audioUrl":"/nte-meta/game-audio/130b905836527edf6c4c.ogg"},{"id":"en-Play_Vo_Char_NPC014_gift_001","title":"Подарок получен I","description":"Тс-с, слышишь?.. Уровень симпатии Ханиэль взлетел до небес!","language":"Английский","audioUrl":"/nte-meta/game-audio/40184ae4757b67181f2d.ogg"},{"id":"en-Play_Vo_Char_NPC014_greet_004","title":"Спокойной ночи","description":"Ночь — отличное время для аниме. Не волнуйся, всего одна серия перед сном! Наверное…","language":"Английский","audioUrl":"/nte-meta/game-audio/b806dfffb68c620cfa7c.ogg"},{"id":"ja-Play_Vo_Char_NPC014_Fly_002","title":"Планирование II","description":"Приготовься! Время для сногсшибательного выхода!","language":"Японский","audioUrl":"/nte-meta/game-audio/a867d848a9dcfcf3143e.ogg"},{"id":"ja-Play_Vo_Char_NPC014_self_002","title":"Обо мне: способности эспера","description":"Раньше я завидовала эсперам. Как герои в аниме — избранные, спасают мир. Но когда пришла моя очередь, я поняла: я не хочу быть главным героем. Я хочу обладать силой, чтобы защитить других. Если бы я тогда была чуть сильнее… может, он бы выжил, как другие котята. Но я не хочу тебя расстраивать. Давай как-нибудь вместе сходим. Там действительно мило.","language":"Японский","audioUrl":"/nte-meta/game-audio/6fde3111a43a07a9bfa8.ogg"},{"id":"ja-Play_Vo_Char_NPC014_ug_003","title":"Вознесение персонажа III","description":"Теперь мои перышки выглядят лучше!","language":"Японский","audioUrl":"/nte-meta/game-audio/224c64a16e1e1e68d1a8.ogg"},{"id":"en-Play_Vo_Char_NPC014_about_004","title":"О Хатор","description":"Я очень хочу покататься на мотоцикле Хатор. Это, наверное, незабываемо! Говорят, она кажется холодной… но только тем, кто её плохо знает. Когда я рядом, даже всплески способности эспера нестрашны! Вперед, Ханиэль! Не бойся!","language":"Английский","audioUrl":"/nte-meta/game-audio/f04e18960e7240290680.ogg"},{"id":"ja-Play_Vo_Char_NPC014_gift_001","title":"Подарок получен I","description":"Тс-с, слышишь?.. Уровень симпатии Ханиэль взлетел до небес!","language":"Японский","audioUrl":"/nte-meta/game-audio/369818c5edbaff49c4f1.ogg"},{"id":"ja-Play_Vo_Char_NPC014_hp_002","title":"Низкий уровень здоровья II","description":"Батарея вот-вот сядет…","language":"Японский","audioUrl":"/nte-meta/game-audio/7645d8ef9ff757ca8e98.ogg"},{"id":"ja-Play_Vo_Char_NPC014_kill_002","title":"Убийство II","description":"Узрите мощь мастера!","language":"Японский","audioUrl":"/nte-meta/game-audio/1601fae8e6516ca17333.ogg"},{"id":"ja-Play_Vo_Char_NPC014_QTE_003","title":"Атака на входе III","description":"Третий страйк — ты вылетаешь!","language":"Японский","audioUrl":"/nte-meta/game-audio/4df83ab92c2962c5ddb1.ogg"},{"id":"ja-Play_Vo_Char_NPC014_windfall_001","title":"Неожиданная добыча I","description":"За это расписываться не надо, да?","language":"Японский","audioUrl":"/nte-meta/game-audio/b026de1c3099cb08e2c7.ogg"},{"id":"en-Play_Vo_Char_NPC014_windfall_001","title":"Неожиданная добыча I","description":"За это расписываться не надо, да?","language":"Английский","audioUrl":"/nte-meta/game-audio/eced05e7ae5b5a620ce5.ogg"},{"id":"en-Play_Vo_Char_NPC014_anomaly_002","title":"Нуллификация II","description":"Вот и всё!","language":"Английский","audioUrl":"/nte-meta/game-audio/fa9d89db98bb89626d38.ogg"},{"id":"en-Play_Vo_Char_NPC014_hstruck_001","title":"Сильный урон I","description":"Ай, больно!","language":"Английский","audioUrl":"/nte-meta/game-audio/3fc3926aecc7a246a27f.ogg"},{"id":"en-Play_Vo_Char_NPC014_struck_002","title":"Урон II","description":"Небольшая ошибочка!","language":"Английский","audioUrl":"/nte-meta/game-audio/1056b391da673ba59d2b.ogg"},{"id":"ja-Play_Vo_Char_NPC014_struck_001","title":"Урон I","description":"Ай!","language":"Японский","audioUrl":"/nte-meta/game-audio/57c9e9779cd4eb86c04a.ogg"},{"id":"en-Play_Vo_Char_NPC014_chat_003","title":"Чат: кошачья еда","description":"Нужно принести корм с новым вкусом, когда буду навещать котят в эти выходные.","language":"Английский","audioUrl":"/nte-meta/game-audio/3fde178f8fed2159c285.ogg"},{"id":"en-Play_Vo_Char_NPC014_QTE_001","title":"Атака на входе I","description":"Идеальный бросок!","language":"Английский","audioUrl":"/nte-meta/game-audio/d0a11f4620ecdbf91faf.ogg"},{"id":"ja-Play_Vo_Char_NPC014_gift_004","title":"Подарок получен IV","description":"В следующий раз, когда от «Эйбона» придёт запрос, я бесплатно поставлю ему пометку «Срочно».","language":"Японский","audioUrl":"/nte-meta/game-audio/49263d1c57b13e95482e.ogg"},{"id":"en-Play_Vo_Char_NPC014_SSC_003","title":"Особое переключение — Наналли","description":"Зажигаем! Рычащая тигрица!","language":"Английский","audioUrl":"/nte-meta/game-audio/9c9dd53f26020fe9e9e5.ogg"},{"id":"en-Play_Vo_Char_NPC014_talk_003","title":"Тема: коллеги-энтузиасты","description":"Поразительно, как люди сходятся друг с другом. Общая любовь к какому-нибудь персонажу — и вот два незнакомца уже лучшие друзья. Есть вещи, которые я не могу рассказать друзьям в реальной жизни, но которыми без проблем поделюсь с кем-нибудь в сети. У меня есть одна особенная онлайн-подруга… надеюсь, мы когда-нибудь встретимся вживую.","language":"Английский","audioUrl":"/nte-meta/game-audio/0163c38d19b941990944.ogg"},{"id":"ja-Play_Vo_Char_NPC014_windfall_004","title":"Неожиданная добыча IV","description":"Посмотрим, что у нас есть интересного!","language":"Японский","audioUrl":"/nte-meta/game-audio/3ee2316e7c880d8b9b94.ogg"},{"id":"ja-Play_Vo_Char_NPC014_dead_003","title":"Потеря сознания III","description":"Простите, теперь всё зависит от вас…","language":"Японский","audioUrl":"/nte-meta/game-audio/cb3c7c4203b39e5c5c5a.ogg"},{"id":"ja-Play_Vo_Char_NPC014_ug_002","title":"Вознесение персонажа II","description":"Готов спасти мир? Готова спасти мир?","language":"Японский","audioUrl":"/nte-meta/game-audio/6a686cbc50185589019b.ogg"},{"id":"ja-Play_Vo_Char_NPC014_windfall_002","title":"Неожиданная добыча II","description":"Ох? Скрытая награда?","language":"Японский","audioUrl":"/nte-meta/game-audio/d350a46e00672ff9cc3c.ogg"},{"id":"en-Play_Vo_Char_NPC014_deploy_001","title":"Отправка I","description":"Нанять элитного курьера — удовольствие не из дешёвых, знаешь ли!","language":"Английский","audioUrl":"/nte-meta/game-audio/b1e87e837c6539c45e15.ogg"},{"id":"ja-Play_Vo_Char_NPC014_anomaly_002","title":"Нуллификация II","description":"Вот и всё!","language":"Японский","audioUrl":"/nte-meta/game-audio/2d6aa42f184b456329f2.ogg"},{"id":"ja-Play_Vo_Char_NPC014_containment_001","title":"Сдерживание I","description":"Отбой! Очередное дело прошло как по мас… м-м-м… сделано гладко!","language":"Японский","audioUrl":"/nte-meta/game-audio/ba184a12debcec3191fa.ogg"},{"id":"ja-Play_Vo_Char_NPC014_Fly_001","title":"Планирование I","description":"Вжух! Хай-я! Взлетаем!","language":"Японский","audioUrl":"/nte-meta/game-audio/d81b024603291d5afe92.ogg"},{"id":"ja-Play_Vo_Char_NPC014_hstruck_002","title":"Сильный урон II","description":"С посылкой же всё в порядке, да?","language":"Японский","audioUrl":"/nte-meta/game-audio/86a35b41fb7376abca0d.ogg"},{"id":"ja-Play_Vo_Char_NPC014_vexation_001","title":"Проблемы","description":"Большие проблемы? Таких нет. Мелкие неурядицы? Много домашки, шумный Иллика, непонятные адреса доставки, привередливые клиенты… Ничего, что нельзя было бы решить хорошей едой и сном. Ханиэль всегда полна сил на следующий день!","language":"Японский","audioUrl":"/nte-meta/game-audio/57d4f5491db4893345c3.ogg"},{"id":"en-Play_Vo_Char_NPC014_dead_001","title":"Потеря сознания I","description":"Так не должно было закончиться…","language":"Английский","audioUrl":"/nte-meta/game-audio/adcbb77ef88c30364db4.ogg"},{"id":"en-Play_Vo_Char_NPC014_weather_003","title":"Холодно","description":"Морозно! Время для хот-пота! Суперострого, разумеется!","language":"Английский","audioUrl":"/nte-meta/game-audio/e14db21cfdc382d1c1f7.ogg"},{"id":"ja-Play_Vo_Char_NPC014_fh_002","title":"Исцеление II","description":"Непобедимая Ханиэль вернулась!","language":"Японский","audioUrl":"/nte-meta/game-audio/2ff3c488098e5fa33a56.ogg"},{"id":"ja-Play_Vo_Char_NPC014_hstruck_001","title":"Сильный урон I","description":"Ай, больно!","language":"Японский","audioUrl":"/nte-meta/game-audio/52576645e95e62c5df3e.ogg"},{"id":"en-Play_Vo_Char_NPC014_windfall_002","title":"Неожиданная добыча II","description":"Ох? Скрытая награда?","language":"Английский","audioUrl":"/nte-meta/game-audio/cc0c112f6085daa05db2.ogg"},{"id":"ja-Play_Vo_Char_NPC014_aoe_UI_001","title":"Сверхспособность I","description":"Моя очередь!","language":"Японский","audioUrl":"/nte-meta/game-audio/070472a04ce89fb8b2b2.ogg"},{"id":"ja-Play_Vo_Char_NPC014_chat_002","title":"Чат: заклинания","description":"Ха-ухей! Шула-хула! Сверхзаряженный ультрабластер ударных волн — именем Ханиэль, я призываю тебя!","language":"Японский","audioUrl":"/nte-meta/game-audio/b9e4d5427a19813debbd.ogg"},{"id":"en-Play_Vo_Char_NPC014_containment_001","title":"Сдерживание I","description":"Отбой! Очередное дело прошло как по мас… м-м-м… сделано гладко!","language":"Английский","audioUrl":"/nte-meta/game-audio/f694c5f7e520ccd0d671.ogg"},{"id":"en-Play_Vo_Char_NPC014_meet_001","title":"Первая встреча","description":"Привет! Я Ханиэль Крессвелл, но ты можешь называть меня просто Ханиэль. Если что-то понадобится, просто прокричи мое имя! Клянусь У.Х.О, если это твой голос, я всегда услышу его!","language":"Английский","audioUrl":"/nte-meta/game-audio/1a5b430adb4fd839b11d.ogg"},{"id":"en-Play_Vo_Char_NPC014_skill_003","title":"Навык перенаправления III","description":"Ну не будь занудой!","language":"Английский","audioUrl":"/nte-meta/game-audio/db366dd52073f0540f34.ogg"},{"id":"ja-Play_Vo_Char_NPC014_QTE_001","title":"Атака на входе I","description":"Идеальный бросок!","language":"Японский","audioUrl":"/nte-meta/game-audio/aa91accf35a51014f135.ogg"},{"id":"en-Play_Vo_Char_NPC014_gift_003","title":"Подарок получен III","description":"Это мне? Спасибо, спасибо, спасибо, спасибо, спасибо!","language":"Английский","audioUrl":"/nte-meta/game-audio/7d5f56c75300565a2efb.ogg"},{"id":"en-Play_Vo_Char_NPC014_Parry_001","title":"Парирование I","description":"Ритм-игры — моя специализация!","language":"Английский","audioUrl":"/nte-meta/game-audio/6e4b888a6d77aa05c720.ogg"},{"id":"ja-Play_Vo_Char_NPC014_dead_002","title":"Потеря сознания II","description":"А если в режиме «Новая игра плюс»…","language":"Японский","audioUrl":"/nte-meta/game-audio/212dd8d7053c2481b2cd.ogg"},{"id":"ja-Play_Vo_Char_NPC014_deploy_001","title":"Отправка I","description":"Нанять элитного курьера — удовольствие не из дешёвых, знаешь ли!","language":"Японский","audioUrl":"/nte-meta/game-audio/f0e0e61a7375f65130d4.ogg"},{"id":"en-Play_Vo_Char_NPC014_chat_002","title":"Чат: заклинания","description":"Ха-ухей! Шула-хула! Сверхзаряженный ультрабластер ударных волн — именем Ханиэль, я призываю тебя!","language":"Английский","audioUrl":"/nte-meta/game-audio/813d59b17088e3e64721.ogg"},{"id":"ja-Play_Vo_Char_NPC014_SSC_002","title":"Особое переключение — Хатор","description":"Хатор! Пора заступать на смену!","language":"Японский","audioUrl":"/nte-meta/game-audio/af584fec5987aff0a770.ogg"},{"id":"en-Play_Vo_Char_NPC014_greet_003","title":"Вечернее приветствие","description":"Добрый вечер! Я иду на прогулку. Хочешь со мной?","language":"Английский","audioUrl":"/nte-meta/game-audio/a46ae6065c1ce378b6b3.ogg"},{"id":"en-Play_Vo_Char_NPC014_self_002","title":"Обо мне: способности эспера","description":"Раньше я завидовала эсперам. Как герои в аниме — избранные, спасают мир. Но когда пришла моя очередь, я поняла: я не хочу быть главным героем. Я хочу обладать силой, чтобы защитить других. Если бы я тогда была чуть сильнее… может, он бы выжил, как другие котята. Но я не хочу тебя расстраивать. Давай как-нибудь вместе сходим. Там действительно мило.","language":"Английский","audioUrl":"/nte-meta/game-audio/106dbf9047fe5be2ad5e.ogg"},{"id":"ja-Play_Vo_Char_NPC014_Switch_001","title":"Переключение I","description":"Готова спасти положение!","language":"Японский","audioUrl":"/nte-meta/game-audio/f1f8bc0b4677cffb0f80.ogg"},{"id":"en-Play_Vo_Char_NPC014_self_001","title":"Обо мне: жилет","description":"Что самое худшее в серии? Огромные паузы. Хочется запереть автора в комнате до тех пор, пока он не закончит! Но когда приходит моя очередь писать… хех. Вот для чего нужны альтернативные аккаунты! Я не пропускаю обновления… я жду вдохновения!","language":"Английский","audioUrl":"/nte-meta/game-audio/d73d844523466e9cfa8c.ogg"},{"id":"ja-Play_Vo_Char_NPC014_skill_001","title":"Навык перенаправления I","description":"Волна Кошачьего концерта!","language":"Японский","audioUrl":"/nte-meta/game-audio/fca3cff94dda9576e67b.ogg"},{"id":"ja-Play_Vo_Char_NPC014_windfall_005","title":"Неожиданная добыча V","description":"М-м-м! Это заслуживает праздничного поста в Bagel!","language":"Японский","audioUrl":"/nte-meta/game-audio/0fa71ab886595e9fa0ed.ogg"},{"id":"en-Play_Vo_Char_NPC014_chat_001","title":"Чат: ограниченная продажа","description":"Будильник — проверено! Wi-Fi — проверено! В этот раз я точно урву лимитированную новинку!","language":"Английский","audioUrl":"/nte-meta/game-audio/440c6a2d39d721f6816c.ogg"},{"id":"en-Play_Vo_Char_NPC014_talk_001","title":"Тема: аномалии","description":"Старики рассказывали, что раньше люди, эсперы и аномалии постоянно враждовали. Но к моменту моего рождения аномалии уже стали почти семьей — типа домашних животных. Конечно, не все идеально, но большинство аномалий очень милые!","language":"Английский","audioUrl":"/nte-meta/game-audio/a1f48a43283041b8fda0.ogg"},{"id":"ja-Play_Vo_Char_NPC014_about_004","title":"О Хатор","description":"Я очень хочу покататься на мотоцикле Хатор. Это, наверное, незабываемо! Говорят, она кажется холодной… но только тем, кто её плохо знает. Когда я рядом, даже всплески способности эспера нестрашны! Вперед, Ханиэль! Не бойся!","language":"Японский","audioUrl":"/nte-meta/game-audio/0ee6ca00995dd65a28a9.ogg"},{"id":"ja-Play_Vo_Char_NPC014_talk_001","title":"Тема: аномалии","description":"Старики рассказывали, что раньше люди, эсперы и аномалии постоянно враждовали. Но к моменту моего рождения аномалии уже стали почти семьей — типа домашних животных. Конечно, не все идеально, но большинство аномалий очень милые!","language":"Японский","audioUrl":"/nte-meta/game-audio/3cf80ff9c94086a283a9.ogg"},{"id":"ja-Play_Vo_Char_NPC014_TeammateDown_001","title":"Поражен товарищ по команде – Цзююань","description":"Как ты смеешь издеваться над Цзююань!","language":"Японский","audioUrl":"/nte-meta/game-audio/7b22662e71fcf443f8e3.ogg"},{"id":"ja-Play_Vo_Char_NPC014_windfall_003","title":"Неожиданная добыча III","description":"Вот бы удача не покидала меня на следующем розыгрыше гачи!","language":"Японский","audioUrl":"/nte-meta/game-audio/d5ba19a8f8b630b0d55d.ogg"},{"id":"en-Play_Vo_Char_NPC014_fh_001","title":"Исцеление I","description":"Идеально!","language":"Английский","audioUrl":"/nte-meta/game-audio/2d6aee9e8173c6bd5795.ogg"},{"id":"en-Play_Vo_Char_NPC014_greet_002","title":"Дневное приветствие","description":"Добрый день! Есть планы на обед? Нужна рекомендация?","language":"Английский","audioUrl":"/nte-meta/game-audio/19cbb4746c41686a4b63.ogg"},{"id":"ja-Play_Vo_Char_NPC014_SSC_001","title":"Особое переключение — Цзююань","description":"Цзююань! Я с этим справлюсь!","language":"Японский","audioUrl":"/nte-meta/game-audio/5f1e972c6d115008d97a.ogg"},{"id":"ja-Play_Vo_Char_NPC014_containment_002","title":"Сдерживание II","description":"Не переживай! Мои навыки упаковки на высшем уровне… Уф… всё в порядке, н-ничего страшного.","language":"Японский","audioUrl":"/nte-meta/game-audio/bf5bf1bcbd12d6100633.ogg"},{"id":"ja-Play_Vo_Char_NPC014_hobby_001","title":"Хобби","description":"Моя цель? Заполучить каждую гарнитуру из лимитированной коллекции! Новые можно купить сразу после выпуска, но с винтажными требуется терпение. Конечно, даже лучшие старые гарнитуры не сравнятся с современными дешевками по качеству звука… но классические саундтреки и нужно слушать с аналоговым потрескиванием. Когда-нибудь покажу тебе свою коллекцию.","language":"Японский","audioUrl":"/nte-meta/game-audio/696967caf4308b15e4fb.ogg"},{"id":"ja-Play_Vo_Char_NPC014_TeammateDown_002","title":"Поражен товарищ по команде – Хатор","description":"Хатор! Не пытайся сделать всё в одиночку!","language":"Японский","audioUrl":"/nte-meta/game-audio/a5aa18abe0c14ad43e5b.ogg"},{"id":"ja-Play_Vo_Char_NPC014_about_001","title":"О Цзююань","description":"Работа в «Стерри Экспресс» не мешает учебе, хорошо оплачивается и идет в комплекте с миссией по спасению мира! Кроме того, Цзююань очень щедра на премии — на что тут можно жаловаться? Я, Ханиэль, стану лучшим курьером «Стерри»! Если бы только Цзююань так не злилась… стресс вызывает морщины, знаешь ли… кхм.","language":"Японский","audioUrl":"/nte-meta/game-audio/cd09f43118a542befadc.ogg"},{"id":"ja-Play_Vo_Char_NPC014_DodgeCombo_002","title":"Серия критических уклонений II","description":"Тск-тск, слишком медленно!","language":"Японский","audioUrl":"/nte-meta/game-audio/c99946e64de2ad79403f.ogg"},{"id":"ja-Play_Vo_Char_NPC014_TeammateDown_003","title":"Поражен товарищ по команде – Наналли","description":"Мы не можем сдаться в такой момент!","language":"Японский","audioUrl":"/nte-meta/game-audio/d22105abbd8c2b6d0637.ogg"},{"id":"en-Play_Vo_Char_NPC014_QTE_003","title":"Атака на входе III","description":"Третий страйк — ты вылетаешь!","language":"Английский","audioUrl":"/nte-meta/game-audio/fa4cddf83ac62dae1048.ogg"},{"id":"ja-Play_Vo_Char_NPC014_self_001","title":"Обо мне: жилет","description":"Что самое худшее в серии? Огромные паузы. Хочется запереть автора в комнате до тех пор, пока он не закончит! Но когда приходит моя очередь писать… хех. Вот для чего нужны альтернативные аккаунты! Я не пропускаю обновления… я жду вдохновения!","language":"Японский","audioUrl":"/nte-meta/game-audio/d6530c3e3284ed7be869.ogg"},{"id":"ja-Play_Vo_Char_NPC014_weather_002","title":"Дождливо","description":"Как насчет расслабляющей музыки? Ох, надеюсь в этот раз гарнитура не закоротит.","language":"Японский","audioUrl":"/nte-meta/game-audio/00d760a0b0bfb33a07c0.ogg"},{"id":"ja-Play_Vo_Char_NPC014_weather_004","title":"Жарко","description":"Спокойно, спокойно, спокойно… Ф-фух… 72-я попытка медитации Ханиэль… провалилась.","language":"Японский","audioUrl":"/nte-meta/game-audio/ba05d377c2ef73bf5530.ogg"},{"id":"en-Play_Vo_Char_NPC014_hp_002","title":"Низкий уровень здоровья II","description":"Батарея вот-вот сядет…","language":"Английский","audioUrl":"/nte-meta/game-audio/0810f1ef6d985a55f21a.ogg"},{"id":"en-Play_Vo_Char_NPC014_skill_002","title":"Навык перенаправления II","description":"Может, немного разнообразия?","language":"Английский","audioUrl":"/nte-meta/game-audio/9e3dd7e0560d01a8c012.ogg"},{"id":"en-Play_Vo_Char_NPC014_TeammateDown_001","title":"Поражен товарищ по команде – Цзююань","description":"Как ты смеешь издеваться над Цзююань!","language":"Английский","audioUrl":"/nte-meta/game-audio/97cafcad113d21a0186e.ogg"},{"id":"ja-Play_Vo_Char_NPC014_aoe_UI_003","title":"Сверхспособность III","description":"Аккомпанемент на мне!","language":"Японский","audioUrl":"/nte-meta/game-audio/38f8099a49e2a9ce359d.ogg"},{"id":"ja-Play_Vo_Char_NPC014_greet_002","title":"Дневное приветствие","description":"Добрый день! Есть планы на обед? Нужна рекомендация?","language":"Японский","audioUrl":"/nte-meta/game-audio/2b635169fe64206151e8.ogg"},{"id":"ja-Play_Vo_Char_NPC014_QTE_002","title":"Атака на входе II","description":"Эй, ты куда смотришь?","language":"Японский","audioUrl":"/nte-meta/game-audio/a1ffdf70caaf44ae493b.ogg"},{"id":"en-Play_Vo_Char_NPC014_Parry_002","title":"Парирование II","description":"Лови ритм!","language":"Английский","audioUrl":"/nte-meta/game-audio/e6fd613aeed5bf260979.ogg"},{"id":"en-Play_Vo_Char_NPC014_about_002","title":"О Дженсоне","description":"Когда впервые увидела Дженсона, подумала: «Вау, он крутой!» Как надежный взрослый из аниме! Спроси его о чем угодно, у него есть ответ! Не может быть, чтобы он был простым хозяином магазина… готова поспорить, он скрывает какую-то тайную личность. Именно так всегда бывает в сериалах!","language":"Английский","audioUrl":"/nte-meta/game-audio/381138b9d8b4b0b5d78b.ogg"},{"id":"ja-Play_Vo_Char_NPC014_hp_001","title":"Низкий уровень здоровья I","description":"Я совсем без сил…","language":"Японский","audioUrl":"/nte-meta/game-audio/fe7e6706bc3947bb4772.ogg"},{"id":"ja-Play_Vo_Char_NPC014_meet_001","title":"Первая встреча","description":"Привет! Я Ханиэль Крессвелл, но ты можешь называть меня просто Ханиэль. Если что-то понадобится, просто прокричи мое имя! Клянусь У.Х.О, если это твой голос, я всегда услышу его!","language":"Японский","audioUrl":"/nte-meta/game-audio/725872abfd41170c543d.ogg"},{"id":"ja-Play_Vo_Char_NPC014_about_005","title":"О «Стерри Экспресс»","description":"Я спасла Хатор, когда её способности эспера дали сбой. После этого Цзююань привела меня в «Стерри Экспресс». Потом я познакомилась с Дженсоном, Иллика опять появился… Прямо как начало «Хроник Ханиэль»… нет, подожди, может «Курьер X Стерри»? «Курьер в маске»? Надо поработать над этим.","language":"Японский","audioUrl":"/nte-meta/game-audio/1c15418ec974c1036f40.ogg"},{"id":"en-Play_Vo_Char_NPC014_kill_001","title":"Убийство I","description":"Проще простого!","language":"Английский","audioUrl":"/nte-meta/game-audio/a389eb26855634120168.ogg"},{"id":"en-Play_Vo_Char_NPC014_SSC_002","title":"Особое переключение — Хатор","description":"Хатор! Пора заступать на смену!","language":"Английский","audioUrl":"/nte-meta/game-audio/a439e27d3c7b2ee8e11e.ogg"},{"id":"ja-Play_Vo_Char_NPC014_greet_001","title":"Утреннее приветствие","description":"Доброе утро! Начинается новый день!","language":"Японский","audioUrl":"/nte-meta/game-audio/7382fa1c558ffd9b8804.ogg"},{"id":"ja-Play_Vo_Char_NPC014_kill_001","title":"Убийство I","description":"Проще простого!","language":"Японский","audioUrl":"/nte-meta/game-audio/c1179214de8cab2ae782.ogg"},{"id":"en-Play_Vo_Char_NPC014_weather_002","title":"Дождливо","description":"Как насчет расслабляющей музыки? Ох, надеюсь в этот раз гарнитура не закоротит.","language":"Английский","audioUrl":"/nte-meta/game-audio/f88a3faa41a0f3b71140.ogg"},{"id":"ja-Play_Vo_Char_NPC014_Switch_003","title":"Переключение III","description":"Я услышала твой зов!","language":"Японский","audioUrl":"/nte-meta/game-audio/9094b60ed0be217b8e17.ogg"},{"id":"en-Play_Vo_Char_NPC014_gift_002","title":"Подарок получен II","description":"Как ты догадался, что мне это нравится? Ты что, ещё и чужие вкусы умеешь «оценивать»? Это так круто! Как ты догадалась, что мне это нравится? Ты что, ещё и чужие вкусы умеешь «оценивать»? Это так круто!","language":"Английский","audioUrl":"/nte-meta/game-audio/432bf3fd9bb84db09615.ogg"},{"id":"en-Play_Vo_Char_NPC014_Fly_002","title":"Планирование II","description":"Приготовься! Время для сногсшибательного выхода!","language":"Английский","audioUrl":"/nte-meta/game-audio/00125d7491bd92c07aad.ogg"},{"id":"en-Play_Vo_Char_NPC014_skill_001","title":"Навык перенаправления I","description":"Волна Кошачьего концерта!","language":"Английский","audioUrl":"/nte-meta/game-audio/dde1b555435ee90022d4.ogg"},{"id":"en-Play_Vo_Char_NPC014_Switch_003","title":"Переключение III","description":"Я услышала твой зов!","language":"Английский","audioUrl":"/nte-meta/game-audio/00afdc80ef9465dd10cf.ogg"},{"id":"en-Play_Vo_Char_NPC014_TeammateDown_002","title":"Поражен товарищ по команде – Хатор","description":"Хатор! Не пытайся сделать всё в одиночку!","language":"Английский","audioUrl":"/nte-meta/game-audio/e29223f1d280b25c4865.ogg"},{"id":"en-Play_Vo_Char_NPC014_ug_002","title":"Вознесение персонажа II","description":"Готов спасти мир? Готова спасти мир?","language":"Английский","audioUrl":"/nte-meta/game-audio/606d7186d8d65c9a6ae3.ogg"},{"id":"en-Play_Vo_Char_NPC014_Fly_001","title":"Планирование I","description":"Вжух! Хай-я! Взлетаем!","language":"Английский","audioUrl":"/nte-meta/game-audio/5757f8f18ff8f116a391.ogg"},{"id":"en-Play_Vo_Char_NPC014_windfall_004","title":"Неожиданная добыча IV","description":"Посмотрим, что у нас есть интересного!","language":"Английский","audioUrl":"/nte-meta/game-audio/bccc1bf5c148434c5239.ogg"},{"id":"en-Play_Vo_Char_NPC014_aoe_UI_002","title":"Сверхспособность II","description":"Теперь мой звёздный час!","language":"Английский","audioUrl":"/nte-meta/game-audio/b456ae84f012891bdbc8.ogg"},{"id":"en-Play_Vo_Char_NPC014_aoe_UI_003","title":"Сверхспособность III","description":"Аккомпанемент на мне!","language":"Английский","audioUrl":"/nte-meta/game-audio/2e725227c4f7ba126b68.ogg"},{"id":"en-Play_Vo_Char_NPC014_Switch_001","title":"Переключение I","description":"Готова спасти положение!","language":"Английский","audioUrl":"/nte-meta/game-audio/a14a6a2f99829fa646fc.ogg"},{"id":"ja-Play_Vo_Char_NPC014_windfall_006","title":"Неожиданная добыча VI","description":"Я же знала, что сегодня мне повезёт!","language":"Японский","audioUrl":"/nte-meta/game-audio/7579211cf9abdb83c1cf.ogg"},{"id":"en-Play_Vo_Char_NPC014_windfall_006","title":"Неожиданная добыча VI","description":"Я же знала, что сегодня мне повезёт!","language":"Английский","audioUrl":"/nte-meta/game-audio/3de80a06b60dd013bf5a.ogg"},{"id":"ja-Play_Vo_Char_NPC014_about_006","title":"Об антикварном магазине Эйбон","description":"Скрытый от посторонних глаз антикварный магазин на тенистой улице против работающей под прикрытием у всех на виду компании экспресс-доставки… этот сюжет просто создан для кино!","language":"Японский","audioUrl":"/nte-meta/game-audio/7d5b89703fcbfb68d90c.ogg"},{"id":"en-Play_Vo_Char_NPC014_windfall_003","title":"Неожиданная добыча III","description":"Вот бы удача не покидала меня на следующем розыгрыше гачи!","language":"Английский","audioUrl":"/nte-meta/game-audio/ff4f1dad0bbb0f848299.ogg"},{"id":"en-Play_Vo_Char_NPC014_fh_002","title":"Исцеление II","description":"Непобедимая Ханиэль вернулась!","language":"Английский","audioUrl":"/nte-meta/game-audio/6a08e9f276a38d3d3c98.ogg"},{"id":"en-Play_Vo_Char_NPC014_hstruck_002","title":"Сильный урон II","description":"С посылкой же всё в порядке, да?","language":"Английский","audioUrl":"/nte-meta/game-audio/38e4120de13b394865fe.ogg"},{"id":"en-Play_Vo_Char_NPC014_Switch_002","title":"Переключение II","description":"Пора сменить ритм!","language":"Английский","audioUrl":"/nte-meta/game-audio/41221bfbc76f5f080d66.ogg"},{"id":"en-Play_Vo_Char_NPC014_ug_001","title":"Вознесение персонажа I","description":"Так значит ЭТО… сила?","language":"Английский","audioUrl":"/nte-meta/game-audio/22276e4c28ecd835bf1b.ogg"},{"id":"ja-Play_Vo_Char_NPC014_DodgeCombo_001","title":"Серия критических уклонений I","description":"Хе-хе, я прокачала навык уклонения до максимума!","language":"Японский","audioUrl":"/nte-meta/game-audio/403713699a1460c0ab07.ogg"},{"id":"ja-Play_Vo_Char_NPC014_weather_001","title":"Солнечно","description":"Такой прекрасный солнечный день. Идеален для сна… или чего угодно.","language":"Японский","audioUrl":"/nte-meta/game-audio/fa2b9e6e1501e2fad338.ogg"},{"id":"en-Play_Vo_Char_NPC014_about_005","title":"О «Стерри Экспресс»","description":"Я спасла Хатор, когда её способности эспера дали сбой. После этого Цзююань привела меня в «Стерри Экспресс». Потом я познакомилась с Дженсоном, Иллика опять появился… Прямо как начало «Хроник Ханиэль»… нет, подожди, может «Курьер X Стерри»? «Курьер в маске»? Надо поработать над этим.","language":"Английский","audioUrl":"/nte-meta/game-audio/21fa60af5c0d39043326.ogg"},{"id":"en-Play_Vo_Char_NPC014_anomaly_001","title":"Нуллификация I","description":"Не забудь поставить мне пять звёзд!","language":"Английский","audioUrl":"/nte-meta/game-audio/709874138e57a74e3b08.ogg"},{"id":"en-Play_Vo_Char_NPC014_hp_003","title":"Низкий уровень здоровья III","description":"Нужна срочная поставка припасов!","language":"Английский","audioUrl":"/nte-meta/game-audio/dcb633c44cfd6fa2afe0.ogg"},{"id":"en-Play_Vo_Char_NPC014_kill_002","title":"Убийство II","description":"Узрите мощь мастера!","language":"Английский","audioUrl":"/nte-meta/game-audio/c72ecc1246f48cea3c16.ogg"},{"id":"ja-Play_Vo_Char_NPC014_weather_003","title":"Холодно","description":"Морозно! Время для хот-пота! Суперострого, разумеется!","language":"Японский","audioUrl":"/nte-meta/game-audio/30b05ff19ae7204d5836.ogg"},{"id":"en-Play_Vo_Char_NPC014_talk_002","title":"Тема: манеры","description":"Ножи слева, вилки справа, и не хлюпать супом? Если нельзя наслаждаться едой, в чем смысл? Как пряные палочки — их нужно класть на позолоченную тарелку под звуки скрипки… но ничто не сравнится с тем, чтобы просто съесть их прямо из пакета.","language":"Английский","audioUrl":"/nte-meta/game-audio/d24fba51ecb45b898af6.ogg"},{"id":"en-Play_Vo_Char_NPC014_ug_003","title":"Вознесение персонажа III","description":"Теперь мои перышки выглядят лучше!","language":"Английский","audioUrl":"/nte-meta/game-audio/9a167f84ffb2d1279250.ogg"},{"id":"ja-Play_Vo_Char_NPC014_fh_001","title":"Исцеление I","description":"Идеально!","language":"Японский","audioUrl":"/nte-meta/game-audio/b855f855c68cf73d737b.ogg"},{"id":"en-Play_Vo_Char_NPC014_dead_002","title":"Потеря сознания II","description":"А если в режиме «Новая игра плюс»…","language":"Английский","audioUrl":"/nte-meta/game-audio/8dfab41ca2e16528dc61.ogg"},{"id":"en-Play_Vo_Char_NPC014_DodgeCombo_001","title":"Серия критических уклонений I","description":"Хе-хе, я прокачала навык уклонения до максимума!","language":"Английский","audioUrl":"/nte-meta/game-audio/93698b18483b12d82d3d.ogg"},{"id":"en-Play_Vo_Char_NPC014_gift_004","title":"Подарок получен IV","description":"В следующий раз, когда от «Эйбона» придёт запрос, я бесплатно поставлю ему пометку «Срочно».","language":"Английский","audioUrl":"/nte-meta/game-audio/48145a32d78c55d667ff.ogg"},{"id":"ja-Play_Vo_Char_NPC014_about_002","title":"О Дженсоне","description":"Когда впервые увидела Дженсона, подумала: «Вау, он крутой!» Как надежный взрослый из аниме! Спроси его о чем угодно, у него есть ответ! Не может быть, чтобы он был простым хозяином магазина… готова поспорить, он скрывает какую-то тайную личность. Именно так всегда бывает в сериалах!","language":"Японский","audioUrl":"/nte-meta/game-audio/3d8ffce6c002b5f3d2ce.ogg"},{"id":"ja-Play_Vo_Char_NPC014_gift_003","title":"Подарок получен III","description":"Это мне? Спасибо, спасибо, спасибо, спасибо, спасибо!","language":"Японский","audioUrl":"/nte-meta/game-audio/dfa6feb5cc7eb9716a2d.ogg"},{"id":"en-Play_Vo_Char_NPC014_struck_001","title":"Урон I","description":"Ай!","language":"Английский","audioUrl":"/nte-meta/game-audio/f8f6165593f6d214585d.ogg"},{"id":"ja-Play_Vo_Char_NPC014_deploy_002","title":"Отправка II","description":"Охо-хо, чую, кто‑то тут скучает по Ханиэль!","language":"Японский","audioUrl":"/nte-meta/game-audio/d92e80fab053e61b0e4c.ogg"},{"id":"ja-Play_Vo_Char_NPC014_hp_003","title":"Низкий уровень здоровья III","description":"Нужна срочная поставка припасов!","language":"Японский","audioUrl":"/nte-meta/game-audio/2281d58364979fe8e91d.ogg"}]') WHERE character_id='haniel' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:28:54');

UPDATE character_profiles SET abilities_json=json('[{"id":"GA_Haniel_Passive_1","name":"Победила дружба!","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/5e1045e47d23da0bf27d.webp","description":"Усиление Новы: позволяет всем союзникам высасывать АТК из цели по завершении «Новы». Цель теряет АТК, равную 4 % от базовой АТК Ханиэль, а каждый союзник получает АТК, равную 8 % от базовой АТК Ханиэль. Общий объём не может превышать 16 % от базовой АТК Ханиэль, а цель не может потерять более 20 % от своей исходной АТК. При выходе из боя показатели обеих сторон восстанавливаются.\n\nХаниэль с куда большим удовольствием слушает забавные байки о дружбе, чем сказания об одиноких героях. Даже если друзья — те ещё дурачки, это все равно интереснее!","attributes":[]},{"id":"GA_Haniel_Passive_2","name":"Связь душ!","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/0da4194119fd4668bd41.webp","description":"Ханиэль получает 1 заряд Сюжетной брони, когда текущий персонаж активирует Ансамбль, что увеличивает количество отскоков снарядов Паранормальной пушки. За каждое срабатывание Ансамбля Ханиэль получает 1 заряд Сюжетной брони.\n\nВ состоянии Паранормального аса за каждое срабатывание Ансамбля Ханиэль получает 2 заряда Сюжетной брони.\n\nТаким образом можно накопить не более 4 зарядов Сюжетной брони.\n\nСмотришь аниме про спорт — и хочется заняться спортом. Смотришь аниме про группу — и хочется научиться на чем-нибудь играть. Смотришь аниме-боевик… Ну, такое лучше не повторять.","attributes":[]},{"id":"GA_Haniel_Skill","name":"Хранитель лунного леса","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/e74b1e7b5b73c6be66fb.webp","description":"Хранитель лунного леса\n«О, сова из тихих лесных глубин, залитых лунным светом, ответь на мой зов!» Бросает портативную колонку Филю, нанося урон психики по области.\n\nПока Филя активна, даёт команде бонус АТК, зависящий от базового показателя АТК Ханиэль.\n\nКогда текущий персонаж атакует, Филя получает 1 заряд Аккорда из четырёх нот, но не более 1 заряда каждые 0,5 сек. При накоплении 4 зарядов Аккорда из четырёх нот срабатывает Ансамбль, наносящий урон психики врагам в области вокруг Фили.\n\nОдновременно может существовать только 1 Филя. Повторное применение навыка обновляет время действия Фили. Филя остаётся на поле боя при смене персонажей.\n\nО, сова из тихих глубин залитого лунным светом леса, я, Ханиэль, заключаю с тобой договор!.. Ну же, Филя, подыграй мне.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 100 % *2 · 2: 108 % *2 · 3: 116.6 % *2 · 4: 126 % *2 · 5: 136 % *2 · 6: 146.9 % *2 · 7: 158.7 % *2 · 8: 171.4 % *2 · 9: 185.1 % *2 · 10: 199.9 % *2 · 11: 215.9 % *2 · 12: 233.2 % *2 · 13: 251.8 % *2"},{"id":"parameter-1","label":"Множитель урона разброса","value":"1: 20 % · 2: 21.6 % · 3: 23.3 % · 4: 25.2 % · 5: 27.2 % · 6: 29.4 % · 7: 31.7 % · 8: 34.3 % · 9: 37 % · 10: 40 % · 11: 43.2 % · 12: 46.6 % · 13: 50.4 %"},{"id":"parameter-2","label":"Коэфф. бонуса атаки","value":"1: 10 % · 2: 11 % · 3: 12 % · 4: 13 % · 5: 14 % · 6: 15 % · 7: 16 % · 8: 17 % · 9: 18 % · 10: 19 % · 11: 20 % · 12: 21 % · 13: 22 %"},{"id":"parameter-3","label":"Длительность","value":"1: 8 сек. · 2: 8 сек. · 3: 8 сек. · 4: 8 сек. · 5: 8 сек. · 6: 8 сек. · 7: 8 сек. · 8: 8 сек. · 9: 8 сек. · 10: 8 сек. · 11: 8 сек. · 12: 8 сек. · 13: 8 сек."}]},{"id":"GA_Haniel_QTE","name":"Пасхалки","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/f191b0e1a2833beb2353.webp","description":"Ну это же скука смертная! И никаких пасхалок не будет? Выстреливает во врага 1 волшебным зарядом, наносящим 1 удар урона психики.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"}]},{"id":"GA_Haniel_UltraSkill","name":"Мелодия в честь Ханиэль","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/762c2caf99c3c351cf56.webp","description":"Отдел паранормальных явлений при Академии для девочек Генесса берётся за дело! Создаёт вокруг себя магическое поле и на некоторое время переходит в состояние Паранормального аса.\n\nДаёт всей команде бонус к АТК, определяемый базовой АТК Ханиэль.\n\nПри активации Ансамбля во время действия способности вокруг персонажа дополнительно срабатывает эффект «Ансамбль — Симфония», обладающий увеличенным радиусом и уроном. Срабатывание эффекта «Ансамбль — Симфония» не даёт Ханиэль заряды Сюжетной брони. Также после активации Ансамбля следующая атака текущего активного персонажа, выполненная в течение 3 сек., нанесёт доп. урон. Эффект не складывается.\n\nОбратный отсчёт до исчезновения Фили останавливается до тех пор, пока Ханиэль не покинет состояние Паранормального аса.\n\nАкадемию для девочек в Генессе не найдешь ни на одной карте Этеро, как не найдешь на картах и Отдел паранормальных явлений. Эта история начнется с первого выпуска новой новеллы Ханиэль…","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 300 % · 2: 324 % · 3: 349.9 % · 4: 377.9 % · 5: 408.1 % · 6: 440.8 % · 7: 476.1 % · 8: 514.1 % · 9: 555.3 % · 10: 599.7 % · 11: 647.7 % · 12: 699.5 % · 13: 755.5 %"},{"id":"parameter-1","label":"Множитель урона разброса","value":"1: 30 % · 2: 32.4 % · 3: 35 % · 4: 37.8 % · 5: 40.8 % · 6: 44.1 % · 7: 47.6 % · 8: 51.4 % · 9: 55.5 % · 10: 60 % · 11: 64.8 % · 12: 69.9 % · 13: 75.5 %"},{"id":"parameter-2","label":"Множитель урона усиленной атаки","value":"1: 30 % · 2: 32.4 % · 3: 35 % · 4: 37.8 % · 5: 40.8 % · 6: 44.1 % · 7: 47.6 % · 8: 51.4 % · 9: 55.5 % · 10: 60 % · 11: 64.8 % · 12: 69.9 % · 13: 75.5 %"},{"id":"parameter-3","label":"Коэфф. бонуса атаки","value":"1: 10 % · 2: 11 % · 3: 12 % · 4: 13 % · 5: 14 % · 6: 15 % · 7: 16 % · 8: 17 % · 9: 18 % · 10: 19 % · 11: 20 % · 12: 21 % · 13: 22 %"},{"id":"parameter-4","label":"Длительность","value":"1: 10 сек. · 2: 10 сек. · 3: 10 сек. · 4: 10 сек. · 5: 10 сек. · 6: 10 сек. · 7: 10 сек. · 8: 10 сек. · 9: 10 сек. · 10: 10 сек. · 11: 10 сек. · 12: 10 сек. · 13: 10 сек."}]},{"id":"GA_Haniel_Melee","name":"Техника Генесс","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/f0a8c77152b2d5eed795.webp","description":"Базовая атака: Техника Генесса\nПроводит до 5 последовательных атак волшебными снарядами, наносящих Урон психики.\n\nБазовая атака: Паранормальная пушка\nУдерживайте базовую атаку во время 1-го удара, чтобы накопить заряд, а затем выстрелите вперёд одним заряженным пушечным снарядом.\n\nБазовая атака: Паранормальный проход\nБудучи в воздухе, нажмите базовую атаку, чтобы устремиться вниз и нанести 1 удар урона психики по области при приземлении. Урон увеличивается в зависимости от высоты падения (макс. 100 %).\n\nКритический контрудар: идеальный заезд\nАктивируется при применении «Техники Генесса» после критического уклонения. «Будешь так тормозить — на нас клиенты жаловаться начнут!» Уклоняется от атаки и выпускает по цели ракету, нанося 1 удар урона психики и снижая её показатель разрушения.\n\nЧем фокусы отличаются от настоящей магии? Любой трюк — магия, если ты в это веришь… Например, сотворение сфер голыми руками!","attributes":[{"id":"parameter-0","label":"Множитель 1-го удара","value":"1: 41.9 % · 2: 45.3 % · 3: 48.9 % · 4: 52.8 % · 5: 57 % · 6: 61.6 % · 7: 66.5 % · 8: 71.8 % · 9: 77.6 % · 10: 83.8 % · 11: 90.5 % · 12: 97.7 % · 13: 105.5 %"},{"id":"parameter-1","label":"Множитель 2-го удара","value":"1: 11.2 % *2 · 2: 12.1 % *2 · 3: 13.1 % *2 · 4: 14.1 % *2 · 5: 15.2 % *2 · 6: 16.5 % *2 · 7: 17.8 % *2 · 8: 19.2 % *2 · 9: 20.7 % *2 · 10: 22.4 % *2 · 11: 24.2 % *2 · 12: 26.1 % *2 · 13: 28.2 % *2"},{"id":"parameter-2","label":"Множитель 3-го удара","value":"1: 58.2 % · 2: 62.9 % · 3: 67.9 % · 4: 73.3 % · 5: 79.2 % · 6: 85.5 % · 7: 92.4 % · 8: 99.7 % · 9: 107.7 % · 10: 116.3 % · 11: 125.6 % · 12: 135.7 % · 13: 146.6 %"},{"id":"parameter-3","label":"Множитель 4-го удара","value":"1: 15.6 % *4 · 2: 16.8 % *4 · 3: 18.2 % *4 · 4: 19.7 % *4 · 5: 21.2 % *4 · 6: 22.9 % *4 · 7: 24.8 % *4 · 8: 26.7 % *4 · 9: 28.9 % *4 · 10: 31.2 % *4 · 11: 33.7 % *4 · 12: 36.4 % *4 · 13: 39.3 % *4"},{"id":"parameter-4","label":"Множитель 5-го удара","value":"1: 52.8 % · 2: 57 % · 3: 61.6 % · 4: 66.5 % · 5: 71.8 % · 6: 77.6 % · 7: 83.8 % · 8: 90.5 % · 9: 97.7 % · 10: 105.5 % · 11: 114 % · 12: 123.1 % · 13: 133 %"},{"id":"parameter-5","label":"Множитель урона атаки в падении","value":"1: 82 % · 2: 88.6 % · 3: 95.6 % · 4: 103.3 % · 5: 111.6 % · 6: 120.5 % · 7: 130.1 % · 8: 140.5 % · 9: 151.8 % · 10: 163.9 % · 11: 177 % · 12: 191.2 % · 13: 206.5 %"},{"id":"parameter-6","label":"Множитель урона последующей атаки","value":"1: 36 % · 2: 38.9 % · 3: 42 % · 4: 45.3 % · 5: 49 % · 6: 52.9 % · 7: 57.1 % · 8: 61.7 % · 9: 66.6 % · 10: 72 % · 11: 77.7 % · 12: 83.9 % · 13: 90.7 %"},{"id":"parameter-7","label":"Множитель критического контрудара","value":"1: 105.2 % · 2: 113.6 % · 3: 122.7 % · 4: 132.5 % · 5: 143.1 % · 6: 154.6 % · 7: 166.9 % · 8: 180.3 % · 9: 194.7 % · 10: 210.3 % · 11: 227.1 % · 12: 245.3 % · 13: 264.9 %"}]},{"id":"City_Ability_Haniel_01","name":"Профи за работой","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/4839a8e3f878deb009d6.webp","description":"Ханиэль дополнительно увеличивает цены блюд на 0","attributes":[{"id":"city-0","label":"Уровень 1","value":"Ханиэль дополнительно увеличивает цены блюд на 0"},{"id":"city-1","label":"Уровень 2","value":"Ханиэль снижает скорость расхода ингредиентов на 1 %."},{"id":"city-2","label":"Уровень 3","value":"Ханиэль дополнительно увеличивает цены блюд на 0"},{"id":"city-3","label":"Уровень 4","value":"Ханиэль снижает скорость расхода ингредиентов на 1 %."},{"id":"city-4","label":"Уровень 5","value":"Ханиэль дополнительно увеличивает цены блюд на 0"}]}]') WHERE character_id='haniel' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:28:54');

