UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Пронзительное чутьё","iconUrl":"/nte-meta/game-assets/0ee0bd632631ee6d1310.webp","description":"Даёт дополнительные 40 % Преступления при атаке врагов с Розыском."},{"level":2,"kind":"awakening","name":"Обвинение / Грех","iconUrl":"/nte-meta/game-assets/ed7bfba120460f4b2f80.webp","description":"Игнорирует 20 % защиты цели при атаке врагов с Розыском."},{"level":3,"kind":"awakening","name":"Тлеющая вспышка","iconUrl":"/nte-meta/game-assets/81f1de973913f310b659.webp","description":"После использования Возмездия увеличивает крит. урон на 30 % на 20 сек. При повторном срабатывании длительность обновляется."},{"level":4,"kind":"awakening","name":"Тонущий прилив","iconUrl":"/nte-meta/game-assets/03aff0f9f45ec1c5b3f3.webp","description":"При убийстве цели с Розыском передаёт Розыск ближайшей неотмеченной цели и пересчитывает его длительность."},{"level":5,"kind":"awakening","name":"Взор в бездну","iconUrl":"/nte-meta/game-assets/319ea474d8a779cb0545.webp","description":"Увеличивает урон по цели на 20 %, если на поле осталась только 1 цель с Розыском."},{"level":6,"kind":"awakening","name":"Ложное происхождение","iconUrl":"/nte-meta/game-assets/f66b246ef6732ced43e0.webp","description":"Мгновенно восстанавливает Преступление до предела после применения Возмездия."},{"level":3,"kind":"resonance","name":"Правосудие / Истина","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень навыков «Погоня», «Метка сомнения» и «Возмездие» на 1."},{"level":6,"kind":"resonance","name":"Свет / Рассвет","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Снижает сопротивление лакшане у врагов с Розыском на 10 %."}]') WHERE character_id='chaos' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 12:50:16');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"en-Play_Vo_Char_NPC024_greet_004","title":"Спокойной ночи","description":"Спокойной ночи. Ложись пораньше — вырастешь повыше.","language":"Английский","audioUrl":"/nte-meta/game-audio/ee45566f88d1cccdfa45.ogg"},{"id":"en-Play_Vo_Char_NPC024_QTE_002","title":"Атака на входе II","description":"Не вздумай бежать!","language":"Английский","audioUrl":"/nte-meta/game-audio/a73d098adcdbf5b51ae8.ogg"},{"id":"en-Play_Vo_Char_NPC024_windfall_005","title":"Неожиданная добыча V","description":"Забираем это!","language":"Английский","audioUrl":"/nte-meta/game-audio/90b024cde48a0411a0f0.ogg"},{"id":"ja-Play_Vo_Char_NPC024_kill_001","title":"Убийство I","description":"Выспись хорошенько.","language":"Японский","audioUrl":"/nte-meta/game-audio/32266991efbc5835d363.ogg"},{"id":"ja-Play_Vo_Char_NPC024_talk_002","title":"Тема: оружие","description":"С помощью моих способностей я могу создавать оружие простой конструкции — вроде мечей и клинков, — но с огнестрелом уже сложнее. Не то чтобы совсем не могу, просто придется запоминать все компоненты… Ладно, не могу.","language":"Японский","audioUrl":"/nte-meta/game-audio/dcf3421dfbe195c7cb31.ogg"},{"id":"ja-Play_Vo_Char_NPC024_dead_001","title":"Потеря сознания I","description":"Прощай…","language":"Японский","audioUrl":"/nte-meta/game-audio/13095393fb9e60cae2fe.ogg"},{"id":"ja-Play_Vo_Char_NPC024_talk_001","title":"Тема: шрам","description":"Способность тела к самоисцелению ограничена. Если повреждений слишком много, оно уже не восстановится. Увы.","language":"Японский","audioUrl":"/nte-meta/game-audio/51c7ba57cd59d60b5cf0.ogg"},{"id":"ja-Play_Vo_Char_NPC024_Parry_001","title":"Парирование I","description":"Посмотрим, кто сильнее!","language":"Японский","audioUrl":"/nte-meta/game-audio/02af736f45c6b71818b9.ogg"},{"id":"en-Play_Vo_Char_NPC024_SSC_LK_002","title":"Особое переключение — Линко","description":"Малышка, на других тоже можно немного положиться!","language":"Английский","audioUrl":"/nte-meta/game-audio/0865c17a88956c9f4578.ogg"},{"id":"en-Play_Vo_Char_NPC024_weather_002","title":"Дождливо","description":"Есть зонтик? Хочешь, дам свою куртку?","language":"Английский","audioUrl":"/nte-meta/game-audio/2521316c555deaa262a8.ogg"},{"id":"ja-Play_Vo_Char_NPC024_self_001","title":"Обо мне: способности эспера","description":"Моя способность? Я придаю разные формы клубам дыма, взявшимся бог весть откуда. По сравнению с теми, кто способен напрямую менять природу, это, конечно, так себе, да? Зато я научился во всех делах рассчитывать только на себя. А это уже неплохо!","language":"Японский","audioUrl":"/nte-meta/game-audio/9e18477b6a005f2ac759.ogg"},{"id":"ja-Play_Vo_Char_NPC024_Switch_002","title":"Переключение II","description":"Не волнуйся. Это я!","language":"Японский","audioUrl":"/nte-meta/game-audio/e77efcad7cd5fe31fbf8.ogg"},{"id":"ja-Play_Vo_Char_NPC024_vexation_001","title":"Проблемы","description":"Телефоны сейчас слишком навороченные. Мне просто нужен телефон, чтобы звонить, писать сообщения и… а, ну да, ещё в «Тетрамино» играть!","language":"Японский","audioUrl":"/nte-meta/game-audio/cb04caac3a51584b7759.ogg"},{"id":"en-Play_Vo_Char_NPC024_kill_002","title":"Убийство II","description":"Хватит быть злодеем.","language":"Английский","audioUrl":"/nte-meta/game-audio/903540812f45cd800785.ogg"},{"id":"ja-Play_Vo_Char_NPC024_QTE_001","title":"Атака на входе I","description":"Попался!","language":"Японский","audioUrl":"/nte-meta/game-audio/941a5200a77e37a4f0e6.ogg"},{"id":"en-Play_Vo_Char_NPC024_kill_001","title":"Убийство I","description":"Выспись хорошенько.","language":"Английский","audioUrl":"/nte-meta/game-audio/a5ff42503c7f726ccfa7.ogg"},{"id":"en-Play_Vo_Char_NPC024_Parry_001","title":"Парирование I","description":"Посмотрим, кто сильнее!","language":"Английский","audioUrl":"/nte-meta/game-audio/5ea563cd730c55e37d8d.ogg"},{"id":"en-Play_Vo_Char_NPC024_ug_001","title":"Вознесение персонажа I","description":"Ага! Моё тело стало сильнее!","language":"Английский","audioUrl":"/nte-meta/game-audio/a98114321ba8ca2ef52a.ogg"},{"id":"en-Play_Vo_Char_NPC024_deploy_002","title":"Отправка II","description":"Ещё один бой. Ну давай!","language":"Английский","audioUrl":"/nte-meta/game-audio/7e2f8e16a70d301d6daa.ogg"},{"id":"en-Play_Vo_Char_NPC024_windfall_001","title":"Неожиданная добыча I","description":"Что это? Похоже, редкая штука.","language":"Английский","audioUrl":"/nte-meta/game-audio/26a8f12394f9b60022a3.ogg"},{"id":"ja-Play_Vo_Char_NPC024_aoe_UI_002","title":"Сверхспособность II","description":"Я всё очищу!","language":"Японский","audioUrl":"/nte-meta/game-audio/f2713955c7139ae0fa96.ogg"},{"id":"ja-Play_Vo_Char_NPC024_talk_003","title":"Тема: пророчество","description":"Я провёл несколько лет в глуши, вдали от города, где люди жили по «воле Божьей». Эта воля всегда оказывалась права — потому что её всегда можно было истолковать так, как кому надо. С пророчествами всё примерно так же. Найдёшь удачную трактовку — и веришь в неё.","language":"Японский","audioUrl":"/nte-meta/game-audio/fca431986b1893797b9d.ogg"},{"id":"en-Play_Vo_Char_NPC024_about_008","title":"О ТОИ-6","description":"Чувствую, ТОИ-6 — не такая уж сплочённая команда. У каждого свои проблемы. Ну, этого требовать я от них не могу. Главное, чтобы делали свою работу.","language":"Английский","audioUrl":"/nte-meta/game-audio/2fceae8afb5f1ab74d52.ogg"},{"id":"en-Play_Vo_Char_NPC024_Switch_003","title":"Переключение III","description":"Получай!","language":"Английский","audioUrl":"/nte-meta/game-audio/5747faa2f5ce71e2eaf9.ogg"},{"id":"ja-Play_Vo_Char_NPC024_containment_001","title":"Сдерживание I","description":"Оставайся здесь. Не уходи.","language":"Японский","audioUrl":"/nte-meta/game-audio/27d8090e427618f7eb18.ogg"},{"id":"ja-Play_Vo_Char_NPC024_containment_002","title":"Сдерживание II","description":"Ха-ха, попался!","language":"Японский","audioUrl":"/nte-meta/game-audio/a0c76c265b2fb7cd52fe.ogg"},{"id":"en-Play_Vo_Char_NPC024_greet_001","title":"Утреннее приветствие","description":"Доброе утро! Начинается новый день!","language":"Английский","audioUrl":"/nte-meta/game-audio/c70df09d4918a2b0414d.ogg"},{"id":"ja-Play_Vo_Char_NPC024_DodgeCombo_001","title":"Серия критических уклонений I","description":"Ха, я в ударе.","language":"Японский","audioUrl":"/nte-meta/game-audio/a98c2523f5da5551cf08.ogg"},{"id":"en-Play_Vo_Char_NPC024_anomaly_003","title":"Нуллификация I","description":"Прощай…","language":"Английский","audioUrl":"/nte-meta/game-audio/4f96d24aef0e7679fa19.ogg"},{"id":"en-Play_Vo_Char_NPC024_greet_003","title":"Вечернее приветствие","description":"(Зевает)… Спать хочется.","language":"Английский","audioUrl":"/nte-meta/game-audio/e4795b67a5e7761b5f0d.ogg"},{"id":"ja-Play_Vo_Char_NPC024_hp_002","title":"Низкий уровень здоровья II","description":"Чёрт, тяжко.","language":"Японский","audioUrl":"/nte-meta/game-audio/d6ef3be84cdaea085a0c.ogg"},{"id":"ja-Play_Vo_Char_NPC024_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Оценщик, нужна помощь? Оценщица, нужна помощь?","language":"Японский","audioUrl":"/nte-meta/game-audio/f91b0cfa8160958ac57a.ogg"},{"id":"ja-Play_Vo_Char_NPC024_weather_004","title":"Жарко","description":"Я сейчас испарюсь!","language":"Японский","audioUrl":"/nte-meta/game-audio/2d17c5bc478dd139f191.ogg"},{"id":"en-Play_Vo_Char_NPC024_Fly_001","title":"Планирование I","description":"Йу-ху!","language":"Английский","audioUrl":"/nte-meta/game-audio/302cc51892c9e0778d8b.ogg"},{"id":"en-Play_Vo_Char_NPC024_struck_001","title":"Урон I","description":"Больно.","language":"Английский","audioUrl":"/nte-meta/game-audio/159f87a1b3d24755a730.ogg"},{"id":"en-Play_Vo_Char_NPC024_hp_001","title":"Низкий уровень здоровья I","description":"Хм… оказалось сложнее, чем я думал.","language":"Английский","audioUrl":"/nte-meta/game-audio/43709552c9c1e05d098a.ogg"},{"id":"en-Play_Vo_Char_NPC024_hstruck_001","title":"Сильный урон I","description":"Не хочется огрести за так…","language":"Английский","audioUrl":"/nte-meta/game-audio/aeaf2281bafc8f4736e7.ogg"},{"id":"en-Play_Vo_Char_NPC024_self_002","title":"Обо мне: происхождение","description":"В далёком маленьком приморском городке появился на свет малыш. Тогда он ещё этого не знал, но 27 лет спустя он вырастет в 27-летнего парня… Что? Я же ничего такого не сказал, да?","language":"Английский","audioUrl":"/nte-meta/game-audio/a8eb55e72d5d437cd5cc.ogg"},{"id":"ja-Play_Vo_Char_NPC024_about_005","title":"О Даффодил","description":"Даффодил слишком уж корит себя — даже за то, что от неё никак не зависит… Она удивительная. Она выросла не в самых лучших условиях, но смогла сохранить доброе сердце. Хозяйка «Эйбона»… наверное, сильно на неё повлияла.","language":"Японский","audioUrl":"/nte-meta/game-audio/856b8564be87a37955c1.ogg"},{"id":"ja-Play_Vo_Char_NPC024_skill_001","title":"Навык перенаправления I","description":"Да сдавайся уже!","language":"Японский","audioUrl":"/nte-meta/game-audio/21c5282f53ddcc0431c3.ogg"},{"id":"ja-Play_Vo_Char_NPC024_windfall_006","title":"Неожиданная добыча VI","description":"Может пригодиться, да?","language":"Японский","audioUrl":"/nte-meta/game-audio/492883e80a10d987ab2e.ogg"},{"id":"ja-Play_Vo_Char_NPC024_Switch_001","title":"Переключение I","description":"А вот и я!","language":"Японский","audioUrl":"/nte-meta/game-audio/e5e4a17e96112aa07482.ogg"},{"id":"en-Play_Vo_Char_NPC024_dead_001","title":"Потеря сознания I","description":"Прощай…","language":"Английский","audioUrl":"/nte-meta/game-audio/696498551f3aa3a1245d.ogg"},{"id":"ja-Play_Vo_Char_NPC024_about_007","title":"Об Острове Грот","description":"На острове Грот… я работал, тренировался, отточил интуицию, превратив её в технику, и научился отличать добро от зла. Я благодарен им за то, что дали мне там остаться. Кроме этого — особых чувств нет.","language":"Японский","audioUrl":"/nte-meta/game-audio/f4f73c82c09a577f7dc8.ogg"},{"id":"ja-Play_Vo_Char_NPC024_windfall_003","title":"Неожиданная добыча III","description":"О-о-о, а это что?","language":"Японский","audioUrl":"/nte-meta/game-audio/9b4684649604aa452ff4.ogg"},{"id":"en-Play_Vo_Char_NPC024_greet_002","title":"Дневное приветствие","description":"Пора выбирать. Что бы взять на обед?","language":"Английский","audioUrl":"/nte-meta/game-audio/10e94026c3cf8b47d501.ogg"},{"id":"ja-Play_Vo_Char_NPC024_gift_002","title":"Подарок получен II","description":"О-о-о! Всегда об этом мечтал! Спасибо огромное!","language":"Японский","audioUrl":"/nte-meta/game-audio/4b68e2a442bfeb8da0e6.ogg"},{"id":"ja-Play_Vo_Char_NPC024_about_008","title":"О ТОИ-6","description":"Чувствую, ТОИ-6 — не такая уж сплочённая команда. У каждого свои проблемы. Ну, этого требовать я от них не могу. Главное, чтобы делали свою работу.","language":"Японский","audioUrl":"/nte-meta/game-audio/9a38b37496a62c3a95ef.ogg"},{"id":"ja-Play_Vo_Char_NPC024_dead_003","title":"Потеря сознания III","description":"Не прощаемся.","language":"Японский","audioUrl":"/nte-meta/game-audio/3f0a8c6f628b4a932875.ogg"},{"id":"en-Play_Vo_Char_NPC024_dead_002","title":"Потеря сознания II","description":"Неужели это и правда конец пути…","language":"Английский","audioUrl":"/nte-meta/game-audio/9800408ac0f306b3074f.ogg"},{"id":"en-Play_Vo_Char_NPC024_ug_003","title":"Вознесение персонажа III","description":"Ха-ха, наконец-то я могу выложиться по полной!","language":"Английский","audioUrl":"/nte-meta/game-audio/7493823953d45a6a9362.ogg"},{"id":"ja-Play_Vo_Char_NPC024_Fly_001","title":"Планирование I","description":"Йу-ху!","language":"Японский","audioUrl":"/nte-meta/game-audio/7379b7f45e71d63fe73a.ogg"},{"id":"ja-Play_Vo_Char_NPC024_greet_004","title":"Спокойной ночи","description":"Спокойной ночи. Ложись пораньше — вырастешь повыше.","language":"Японский","audioUrl":"/nte-meta/game-audio/0ca6471bd1ca0566f46c.ogg"},{"id":"ja-Play_Vo_Char_NPC024_hobby_001","title":"Хобби","description":"«Тетрамино» — это так весело! Обожаю, когда все линии разом исчезают!","language":"Японский","audioUrl":"/nte-meta/game-audio/5e9d25f4d1eabe8882eb.ogg"},{"id":"en-Play_Vo_Char_NPC024_gift_003","title":"Подарок получен III","description":"Спасибо большое!","language":"Английский","audioUrl":"/nte-meta/game-audio/9e04ce97de19801221ca.ogg"},{"id":"en-Play_Vo_Char_NPC024_talk_002","title":"Тема: оружие","description":"С помощью моих способностей я могу создавать оружие простой конструкции — вроде мечей и клинков, — но с огнестрелом уже сложнее. Не то чтобы совсем не могу, просто придется запоминать все компоненты… Ладно, не могу.","language":"Английский","audioUrl":"/nte-meta/game-audio/cf1471205a16aca8c483.ogg"},{"id":"ja-Play_Vo_Char_NPC024_QTE_002","title":"Атака на входе II","description":"Не вздумай бежать!","language":"Японский","audioUrl":"/nte-meta/game-audio/c5ffbb1bbbb66b331e05.ogg"},{"id":"ja-Play_Vo_Char_NPC024_self_002","title":"Обо мне: происхождение","description":"В далёком маленьком приморском городке появился на свет малыш. Тогда он ещё этого не знал, но 27 лет спустя он вырастет в 27-летнего парня… Что? Я же ничего такого не сказал, да?","language":"Японский","audioUrl":"/nte-meta/game-audio/da1d40331680916462c2.ogg"},{"id":"en-Play_Vo_Char_NPC024_QTE_001","title":"Атака на входе I","description":"Попался!","language":"Английский","audioUrl":"/nte-meta/game-audio/7ebaed4a6cfba20d22d2.ogg"},{"id":"ja-Play_Vo_Char_NPC024_Fly_002","title":"Планирование II","description":"Погнали!","language":"Японский","audioUrl":"/nte-meta/game-audio/d95fa55be326eb964a01.ogg"},{"id":"en-Play_Vo_Char_NPC024_gift_004","title":"Подарок получен IV","description":"Это мне? Спасибо!","language":"Английский","audioUrl":"/nte-meta/game-audio/cfa03c58832c577fdd82.ogg"},{"id":"en-Play_Vo_Char_NPC024_TeammateDown_002","title":"Поражён товарищ по команде – Линко","description":"Опять прощаемся?","language":"Английский","audioUrl":"/nte-meta/game-audio/291f6a85251ae6c86ba1.ogg"},{"id":"ja-Play_Vo_Char_NPC024_weather_003","title":"Холодно","description":"Тебе холодно? Ты дрожишь.","language":"Японский","audioUrl":"/nte-meta/game-audio/cda85e87ab090525084e.ogg"},{"id":"ja-Play_Vo_Char_NPC024_windfall_004","title":"Неожиданная добыча IV","description":"Нашёл кое-что стоящее.","language":"Японский","audioUrl":"/nte-meta/game-audio/d3d6c97b06ef430404ea.ogg"},{"id":"ja-Play_Vo_Char_NPC024_windfall_005","title":"Неожиданная добыча V","description":"Забираем это!","language":"Японский","audioUrl":"/nte-meta/game-audio/4f06deb4484aea286b8e.ogg"},{"id":"en-Play_Vo_Char_NPC024_about_007","title":"Об Острове Грот","description":"На острове Грот… я работал, тренировался, отточил интуицию, превратив её в технику, и научился отличать добро от зла. Я благодарен им за то, что дали мне там остаться. Кроме этого — особых чувств нет.","language":"Английский","audioUrl":"/nte-meta/game-audio/9027488d4513811fdef8.ogg"},{"id":"en-Play_Vo_Char_NPC024_QTE_003","title":"Атака на входе III","description":"Вы арестованы!","language":"Английский","audioUrl":"/nte-meta/game-audio/34f077eaf6dbe7f78f30.ogg"},{"id":"en-Play_Vo_Char_NPC024_skill_002","title":"Навык перенаправления II","description":"Тиндалос!","language":"Английский","audioUrl":"/nte-meta/game-audio/bacf4c6b898496a2745c.ogg"},{"id":"ja-Play_Vo_Char_NPC024_aoe_UI_003","title":"Сверхспособность III","description":"Я… всё исправлю.","language":"Японский","audioUrl":"/nte-meta/game-audio/c355966c773e9db0dabb.ogg"},{"id":"ja-Play_Vo_Char_NPC024_chat_001","title":"Чат: маска","description":"Почему я ношу маску? Всем говорю, что так в бою эффективнее. Но настоящая причина… Правда хочешь знать? Ну… по-моему, смотрится круто. Ладно, хватит так на меня пялиться. Я правда думаю, что она крутая…","language":"Японский","audioUrl":"/nte-meta/game-audio/a7798bc7ca928c1ec50f.ogg"},{"id":"ja-Play_Vo_Char_NPC024_greet_003","title":"Вечернее приветствие","description":"(Зевает)… Спать хочется.","language":"Японский","audioUrl":"/nte-meta/game-audio/c560edc7356a812fa3d8.ogg"},{"id":"ja-Play_Vo_Char_NPC024_chat_002","title":"Чат: проблемный кадр","description":"Миссия кажется слишком хлопотной? Не переживай. Если разбираться со всем шаг за шагом, всё получится. Это убеждение помогло мне сделать немало вещей, которые поначалу казались невозможными, если не считать… ну, неважно.","language":"Японский","audioUrl":"/nte-meta/game-audio/a96f667b6ffffba3365b.ogg"},{"id":"ja-Play_Vo_Char_NPC024_windfall_002","title":"Неожиданная добыча II","description":"Ого, годная вещь!","language":"Японский","audioUrl":"/nte-meta/game-audio/b852d2565ad54225d0c9.ogg"},{"id":"en-Play_Vo_Char_NPC024_skill_001","title":"Навык перенаправления I","description":"Да сдавайся уже!","language":"Английский","audioUrl":"/nte-meta/game-audio/8b7eba6a3f9489a33fb8.ogg"},{"id":"en-Play_Vo_Char_NPC024_self_001","title":"Обо мне: способности эспера","description":"Моя способность? Я придаю разные формы клубам дыма, взявшимся бог весть откуда. По сравнению с теми, кто способен напрямую менять природу, это, конечно, так себе, да? Зато я научился во всех делах рассчитывать только на себя. А это уже неплохо!","language":"Английский","audioUrl":"/nte-meta/game-audio/3a9599afa15ff55668ff.ogg"},{"id":"ja-Play_Vo_Char_NPC024_gift_004","title":"Подарок получен IV","description":"Это мне? Спасибо!","language":"Японский","audioUrl":"/nte-meta/game-audio/17a1415f2121714a6ff1.ogg"},{"id":"ja-Play_Vo_Char_NPC024_hp_001","title":"Низкий уровень здоровья I","description":"Хм… оказалось сложнее, чем я думал.","language":"Японский","audioUrl":"/nte-meta/game-audio/d90c7ee08d8696727262.ogg"},{"id":"en-Play_Vo_Char_NPC024_vexation_001","title":"Проблемы","description":"Телефоны сейчас слишком навороченные. Мне просто нужен телефон, чтобы звонить, писать сообщения и… а, ну да, ещё в «Тетрамино» играть!","language":"Английский","audioUrl":"/nte-meta/game-audio/24489b4e31937e5c77ff.ogg"},{"id":"en-Play_Vo_Char_NPC024_weather_003","title":"Холодно","description":"Тебе холодно? Ты дрожишь.","language":"Английский","audioUrl":"/nte-meta/game-audio/06536078c79791f2fe0f.ogg"},{"id":"ja-Play_Vo_Char_NPC024_kill_002","title":"Убийство II","description":"Хватит быть злодеем.","language":"Японский","audioUrl":"/nte-meta/game-audio/6e6fd6ab9e089f050352.ogg"},{"id":"ja-Play_Vo_Char_NPC024_weather_002","title":"Дождливо","description":"Есть зонтик? Хочешь, дам свою куртку?","language":"Японский","audioUrl":"/nte-meta/game-audio/d31fd96f3eec352e029d.ogg"},{"id":"en-Play_Vo_Char_NPC024_weather_001","title":"Солнечно","description":"У меня настроение такое же солнечное, как само солнце!","language":"Английский","audioUrl":"/nte-meta/game-audio/3c7255f7be5c0b97133c.ogg"},{"id":"en-Play_Vo_Char_NPC024_windfall_002","title":"Неожиданная добыча II","description":"Ого, годная вещь!","language":"Английский","audioUrl":"/nte-meta/game-audio/f17110706a3fe2c635c1.ogg"},{"id":"ja-Play_Vo_Char_NPC024_greet_001","title":"Утреннее приветствие","description":"Доброе утро! Начинается новый день!","language":"Японский","audioUrl":"/nte-meta/game-audio/f06e3809f1c413a5bca2.ogg"},{"id":"en-Play_Vo_Char_NPC024_talk_001","title":"Тема: шрам","description":"Способность тела к самоисцелению ограничена. Если повреждений слишком много, оно уже не восстановится. Увы.","language":"Английский","audioUrl":"/nte-meta/game-audio/75bffc78238547dd5382.ogg"},{"id":"ja-Play_Vo_Char_NPC024_about_006","title":"О Занку","description":"Она странная. Почти такая же странная, как преступники с острова Грот. Если честно, ей там самое место.","language":"Японский","audioUrl":"/nte-meta/game-audio/ea5c6ba30f948c8675c4.ogg"},{"id":"ja-Play_Vo_Char_NPC024_ug_003","title":"Вознесение персонажа III","description":"Ха-ха, наконец-то я могу выложиться по полной!","language":"Японский","audioUrl":"/nte-meta/game-audio/b7ff018a8c90997d4b6c.ogg"},{"id":"en-Play_Vo_Char_NPC024_gift_001","title":"Подарок получен I","description":"Ого, это мне? Точно? Как приятно!","language":"Английский","audioUrl":"/nte-meta/game-audio/839524b71d6e9de71c38.ogg"},{"id":"ja-Play_Vo_Char_NPC024_anomaly_004","title":"Нуллификация II","description":"На сегодня всё.","language":"Японский","audioUrl":"/nte-meta/game-audio/b227724768522af1caeb.ogg"},{"id":"ja-Play_Vo_Char_NPC024_struck_002","title":"Урон II","description":"Интересно.","language":"Японский","audioUrl":"/nte-meta/game-audio/2ba145111c09821910f6.ogg"},{"id":"ja-Play_Vo_Char_NPC024_TeammateDown_002","title":"Поражён товарищ по команде – Линко","description":"Опять прощаемся?","language":"Японский","audioUrl":"/nte-meta/game-audio/4a3e0a5b7ed740d164f3.ogg"},{"id":"en-Play_Vo_Char_NPC024_dead_003","title":"Потеря сознания III","description":"Не прощаемся.","language":"Английский","audioUrl":"/nte-meta/game-audio/5b8dbb89572fe345c716.ogg"},{"id":"en-Play_Vo_Char_NPC024_hp_002","title":"Низкий уровень здоровья II","description":"Чёрт, тяжко.","language":"Английский","audioUrl":"/nte-meta/game-audio/b866100e168c6951985a.ogg"},{"id":"en-Play_Vo_Char_NPC024_meet_001","title":"Первая встреча","description":"Приветствую. Это Хаос из ТОИ-6. Рад познакомиться. С нетерпением жду… Эй, я же просто пытаюсь вести себя вежливо, хватит смеяться!","language":"Английский","audioUrl":"/nte-meta/game-audio/6fa380d36caa6ac45d1a.ogg"},{"id":"en-Play_Vo_Char_NPC024_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Оценщик, нужна помощь? Оценщица, нужна помощь?","language":"Английский","audioUrl":"/nte-meta/game-audio/b35b0c652c0f66843167.ogg"},{"id":"ja-Play_Vo_Char_NPC024_windfall_001","title":"Неожиданная добыча I","description":"Что это? Похоже, редкая штука.","language":"Японский","audioUrl":"/nte-meta/game-audio/f76de91fef218a8bc85e.ogg"},{"id":"ja-Play_Vo_Char_NPC024_fh_001","title":"Исцеление I","description":"Ого, уже лучше.","language":"Японский","audioUrl":"/nte-meta/game-audio/1c322152a676f16c4746.ogg"},{"id":"ja-Play_Vo_Char_NPC024_anomaly_003","title":"Нуллификация I","description":"Прощай…","language":"Японский","audioUrl":"/nte-meta/game-audio/e8f8dd4fb4556a5a9451.ogg"},{"id":"ja-Play_Vo_Char_NPC024_deploy_002","title":"Отправка II","description":"Ещё один бой. Ну давай!","language":"Японский","audioUrl":"/nte-meta/game-audio/5e5563478200b4bb1dce.ogg"},{"id":"ja-Play_Vo_Char_NPC024_self_003","title":"Обо мне: прощание","description":"Не хочу хвастаться, я, наверное, больше раз сказал «прощай», чем ты — «доброе утро». Дрейфуя в открытом море, я всё думал: у мира ведь нет границ, так что, может, те, с кем я попрощался… может, я ещё с ними встречусь.","language":"Японский","audioUrl":"/nte-meta/game-audio/cf592d1d1eaf60d7894b.ogg"},{"id":"ja-Play_Vo_Char_NPC024_fh_002","title":"Исцеление II","description":"Спасибо, помогло!","language":"Японский","audioUrl":"/nte-meta/game-audio/251b53a10f728d075936.ogg"},{"id":"ja-Play_Vo_Char_NPC024_ug_001","title":"Вознесение персонажа I","description":"Ага! Моё тело стало сильнее!","language":"Японский","audioUrl":"/nte-meta/game-audio/a05342d996d24cc7e39b.ogg"},{"id":"en-Play_Vo_Char_NPC024_DodgeCombo_001","title":"Серия критических уклонений I","description":"Ха, я в ударе.","language":"Английский","audioUrl":"/nte-meta/game-audio/5ad6a4d5f76c8bd657e2.ogg"},{"id":"en-Play_Vo_Char_NPC024_ug_002","title":"Вознесение персонажа II","description":"Я на подъёме! Но могу и лучше.","language":"Английский","audioUrl":"/nte-meta/game-audio/e9c7152db3f8c8ca4930.ogg"},{"id":"en-Play_Vo_Char_NPC024_Fly_002","title":"Планирование II","description":"Погнали!","language":"Английский","audioUrl":"/nte-meta/game-audio/615520ebaefea1018788.ogg"},{"id":"en-Play_Vo_Char_NPC024_gift_002","title":"Подарок получен II","description":"О-о-о! Всегда об этом мечтал! Спасибо огромное!","language":"Английский","audioUrl":"/nte-meta/game-audio/ce14562d7961f7480661.ogg"},{"id":"ja-Play_Vo_Char_NPC024_deploy_001","title":"Отправка I","description":"Мои противники обычно плохо кончают.","language":"Японский","audioUrl":"/nte-meta/game-audio/053f5f61947520c4aefd.ogg"},{"id":"ja-Play_Vo_Char_NPC024_hp_003","title":"Низкий уровень здоровья III","description":"Фух… фух…","language":"Японский","audioUrl":"/nte-meta/game-audio/62356d26a1f238ef797e.ogg"},{"id":"ja-Play_Vo_Char_NPC024_struck_001","title":"Урон I","description":"Больно.","language":"Японский","audioUrl":"/nte-meta/game-audio/5d1a7ffd0fa7da10151c.ogg"},{"id":"en-Play_Vo_Char_NPC024_hp_003","title":"Низкий уровень здоровья III","description":"Фух… фух…","language":"Английский","audioUrl":"/nte-meta/game-audio/be3c1231d0d9147f2a10.ogg"},{"id":"en-Play_Vo_Char_NPC024_talk_003","title":"Тема: пророчество","description":"Я провёл несколько лет в глуши, вдали от города, где люди жили по «воле Божьей». Эта воля всегда оказывалась права — потому что её всегда можно было истолковать так, как кому надо. С пророчествами всё примерно так же. Найдёшь удачную трактовку — и веришь в неё.","language":"Английский","audioUrl":"/nte-meta/game-audio/9e571b656199acd79521.ogg"},{"id":"en-Play_Vo_Char_NPC024_aoe_UI_002","title":"Сверхспособность II","description":"Я всё очищу!","language":"Английский","audioUrl":"/nte-meta/game-audio/328eed0f72ebfff26eba.ogg"},{"id":"en-Play_Vo_Char_NPC024_hobby_001","title":"Хобби","description":"«Тетрамино» — это так весело! Обожаю, когда все линии разом исчезают!","language":"Английский","audioUrl":"/nte-meta/game-audio/5d67c179c48216739869.ogg"},{"id":"en-Play_Vo_Char_NPC024_windfall_003","title":"Неожиданная добыча III","description":"О-о-о, а это что?","language":"Английский","audioUrl":"/nte-meta/game-audio/25c131b0c0c50acec390.ogg"},{"id":"ja-Play_Vo_Char_NPC024_DodgeCombo_002","title":"Серия критических уклонений II","description":"Эй-эй, сперва прицелься, потом уже бей!","language":"Японский","audioUrl":"/nte-meta/game-audio/7e938e54cb1aac9aa682.ogg"},{"id":"en-Play_Vo_Char_NPC024_windfall_006","title":"Неожиданная добыча VI","description":"Может пригодиться, да?","language":"Английский","audioUrl":"/nte-meta/game-audio/66befa44a6a24e96a331.ogg"},{"id":"en-Play_Vo_Char_NPC024_aoe_UI_003","title":"Сверхспособность III","description":"Я… всё исправлю.","language":"Английский","audioUrl":"/nte-meta/game-audio/b845d87625024d224554.ogg"},{"id":"en-Play_Vo_Char_NPC024_chat_002","title":"Чат: проблемный кадр","description":"Миссия кажется слишком хлопотной? Не переживай. Если разбираться со всем шаг за шагом, всё получится. Это убеждение помогло мне сделать немало вещей, которые поначалу казались невозможными, если не считать… ну, неважно.","language":"Английский","audioUrl":"/nte-meta/game-audio/b2f2c0176bac03120722.ogg"},{"id":"en-Play_Vo_Char_NPC024_windfall_004","title":"Неожиданная добыча IV","description":"Нашёл кое-что стоящее.","language":"Английский","audioUrl":"/nte-meta/game-audio/756dc536b4990254107c.ogg"},{"id":"ja-Play_Vo_Char_NPC024_about_003","title":"О Линко","description":"Не знаю, что творится у Линко в голове. Ладно, не так уж это и важно. Если ищешь человека или аномалию, можешь просто положиться на её чутьё. Одна беда — она вечно забредает в какие-то странные места. У одной моей маленькой приятельницы была та же беда. Хотя, честно говоря, моя приятельница не такая сообразительная, как Линко…","language":"Японский","audioUrl":"/nte-meta/game-audio/c103238a3af7436b6b46.ogg"},{"id":"ja-Play_Vo_Char_NPC024_Parry_002","title":"Парирование II","description":"Хех, простенькая атака.","language":"Японский","audioUrl":"/nte-meta/game-audio/1831769b64521d12144f.ogg"},{"id":"ja-Play_Vo_Char_NPC024_ug_002","title":"Вознесение персонажа II","description":"Я на подъёме! Но могу и лучше.","language":"Японский","audioUrl":"/nte-meta/game-audio/99bfd5fde92217e31057.ogg"},{"id":"en-Play_Vo_Char_NPC024_deploy_001","title":"Отправка I","description":"Мои противники обычно плохо кончают.","language":"Английский","audioUrl":"/nte-meta/game-audio/c407ecc20e6e92898ca2.ogg"},{"id":"en-Play_Vo_Char_NPC024_fh_002","title":"Исцеление II","description":"Спасибо, помогло!","language":"Английский","audioUrl":"/nte-meta/game-audio/aac0c585008fa2023c17.ogg"},{"id":"en-Play_Vo_Char_NPC024_Switch_001","title":"Переключение I","description":"А вот и я!","language":"Английский","audioUrl":"/nte-meta/game-audio/8e88e9ac205372dac803.ogg"},{"id":"en-Play_Vo_Char_NPC024_Switch_002","title":"Переключение II","description":"Не волнуйся. Это я!","language":"Английский","audioUrl":"/nte-meta/game-audio/524d9626f15353e280c1.ogg"},{"id":"ja-Play_Vo_Char_NPC024_dead_002","title":"Потеря сознания II","description":"Неужели это и правда конец пути…","language":"Японский","audioUrl":"/nte-meta/game-audio/076efa5802a647bb28ec.ogg"},{"id":"ja-Play_Vo_Char_NPC024_gift_003","title":"Подарок получен III","description":"Спасибо большое!","language":"Японский","audioUrl":"/nte-meta/game-audio/01e22329803f139fa075.ogg"},{"id":"ja-Play_Vo_Char_NPC024_QTE_003","title":"Атака на входе III","description":"Вы арестованы!","language":"Японский","audioUrl":"/nte-meta/game-audio/fc4682eae2aba5144c62.ogg"},{"id":"en-Play_Vo_Char_NPC024_aoe_UI_001","title":"Сверхспособность I","description":"Со злом нужно покончить…!","language":"Английский","audioUrl":"/nte-meta/game-audio/61e52ff8c3ded1a215fa.ogg"},{"id":"en-Play_Vo_Char_NPC024_chat_003","title":"Чат: гончая","description":"У меня нет собаки, но если ты про «гончую», то это моя способность Эспера. Хм, а вот настоящую собаку я бы, пожалуй, не прочь завести…","language":"Английский","audioUrl":"/nte-meta/game-audio/0dd23c3a4d749de40fb1.ogg"},{"id":"en-Play_Vo_Char_NPC024_hstruck_002","title":"Сильный урон II","description":"Ух…","language":"Английский","audioUrl":"/nte-meta/game-audio/58d9f17d1fd600d713f3.ogg"},{"id":"en-Play_Vo_Char_NPC024_skill_003","title":"Навык перенаправления III","description":"Цель подтверждена.","language":"Английский","audioUrl":"/nte-meta/game-audio/b6d687a65135909486d4.ogg"},{"id":"en-Play_Vo_Char_NPC024_weather_004","title":"Жарко","description":"Я сейчас испарюсь!","language":"Английский","audioUrl":"/nte-meta/game-audio/556af1849d613546583e.ogg"},{"id":"en-Play_Vo_Char_NPC024_containment_002","title":"Сдерживание II","description":"Ха-ха, попался!","language":"Английский","audioUrl":"/nte-meta/game-audio/339d67624e00a35bbc89.ogg"},{"id":"en-Play_Vo_Char_NPC024_self_003","title":"Обо мне: прощание","description":"Не хочу хвастаться, я, наверное, больше раз сказал «прощай», чем ты — «доброе утро». Дрейфуя в открытом море, я всё думал: у мира ведь нет границ, так что, может, те, с кем я попрощался… может, я ещё с ними встречусь.","language":"Английский","audioUrl":"/nte-meta/game-audio/f75da6f256beb27db9ef.ogg"},{"id":"ja-Play_Vo_Char_NPC024_gift_001","title":"Подарок получен I","description":"Ого, это мне? Точно? Как приятно!","language":"Японский","audioUrl":"/nte-meta/game-audio/7adee1230e05822fbd1a.ogg"},{"id":"ja-Play_Vo_Char_NPC024_aoe_UI_001","title":"Сверхспособность I","description":"Со злом нужно покончить…!","language":"Японский","audioUrl":"/nte-meta/game-audio/118e5e67c309c14e2031.ogg"},{"id":"ja-Play_Vo_Char_NPC024_skill_002","title":"Навык перенаправления II","description":"Тиндалос!","language":"Японский","audioUrl":"/nte-meta/game-audio/d806ec0cfea56cebab98.ogg"},{"id":"en-Play_Vo_Char_NPC024_Parry_002","title":"Парирование II","description":"Хех, простенькая атака.","language":"Английский","audioUrl":"/nte-meta/game-audio/95600184c5d43cc1d2e6.ogg"},{"id":"ja-Play_Vo_Char_NPC024_weather_001","title":"Солнечно","description":"У меня настроение такое же солнечное, как само солнце!","language":"Японский","audioUrl":"/nte-meta/game-audio/617c20949f2ea6cc3054.ogg"},{"id":"en-Play_Vo_Char_NPC024_chat_001","title":"Чат: маска","description":"Почему я ношу маску? Всем говорю, что так в бою эффективнее. Но настоящая причина… Правда хочешь знать? Ну… по-моему, смотрится круто. Ладно, хватит так на меня пялиться. Я правда думаю, что она крутая…","language":"Английский","audioUrl":"/nte-meta/game-audio/d965ff8043db3cd91350.ogg"},{"id":"ja-Play_Vo_Char_NPC024_chat_003","title":"Чат: гончая","description":"У меня нет собаки, но если ты про «гончую», то это моя способность Эспера. Хм, а вот настоящую собаку я бы, пожалуй, не прочь завести…","language":"Японский","audioUrl":"/nte-meta/game-audio/9e7602c97cf792e80ef7.ogg"},{"id":"ja-Play_Vo_Char_NPC024_greet_002","title":"Дневное приветствие","description":"Пора выбирать. Что бы взять на обед?","language":"Японский","audioUrl":"/nte-meta/game-audio/17f6a79e3184c06e47c4.ogg"},{"id":"ja-Play_Vo_Char_NPC024_skill_003","title":"Навык перенаправления III","description":"Цель подтверждена.","language":"Японский","audioUrl":"/nte-meta/game-audio/9ae45fc44e8a0c459b53.ogg"},{"id":"en-Play_Vo_Char_NPC024_DodgeCombo_002","title":"Серия критических уклонений II","description":"Эй-эй, сперва прицелься, потом уже бей!","language":"Английский","audioUrl":"/nte-meta/game-audio/01b14177cf28e8a5987e.ogg"},{"id":"ja-Play_Vo_Char_NPC024_SSC_LK_002","title":"Особое переключение — Линко","description":"Малышка, на других тоже можно немного положиться!","language":"Японский","audioUrl":"/nte-meta/game-audio/c51ae4d663cc8eab6daf.ogg"},{"id":"ja-Play_Vo_Char_NPC024_Switch_003","title":"Переключение III","description":"Получай!","language":"Японский","audioUrl":"/nte-meta/game-audio/fbf32bd983e80290b6a4.ogg"},{"id":"en-Play_Vo_Char_NPC024_anomaly_004","title":"Нуллификация II","description":"На сегодня всё.","language":"Английский","audioUrl":"/nte-meta/game-audio/be21ef0e4e866193c658.ogg"},{"id":"ja-Play_Vo_Char_NPC024_hstruck_001","title":"Сильный урон I","description":"Не хочется огрести за так…","language":"Японский","audioUrl":"/nte-meta/game-audio/0131be297cdccbc7cec2.ogg"},{"id":"ja-Play_Vo_Char_NPC024_hstruck_002","title":"Сильный урон II","description":"Ух…","language":"Японский","audioUrl":"/nte-meta/game-audio/7a89070bfcfe35928d98.ogg"},{"id":"en-Play_Vo_Char_NPC024_containment_001","title":"Сдерживание I","description":"Оставайся здесь. Не уходи.","language":"Английский","audioUrl":"/nte-meta/game-audio/b4138a8516e20cb3cdb0.ogg"},{"id":"en-Play_Vo_Char_NPC024_fh_001","title":"Исцеление I","description":"Ого, уже лучше.","language":"Английский","audioUrl":"/nte-meta/game-audio/213eb33c0ee5d26e8213.ogg"},{"id":"en-Play_Vo_Char_NPC024_struck_002","title":"Урон II","description":"Интересно.","language":"Английский","audioUrl":"/nte-meta/game-audio/6b04dfd9bf77175e3155.ogg"},{"id":"ja-Play_Vo_Char_NPC024_meet_001","title":"Первая встреча","description":"Приветствую. Это Хаос из ТОИ-6. Рад познакомиться. С нетерпением жду… Эй, я же просто пытаюсь вести себя вежливо, хватит смеяться!","language":"Японский","audioUrl":"/nte-meta/game-audio/e04d3722644293a6e6e5.ogg"}]') WHERE character_id='chaos' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 12:50:16');

UPDATE character_profiles SET abilities_json=json('[{"id":"GA_Chaos_Passive_1","name":"Своевременное правосудие","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/ece1a5db9115ea3f6767.webp","description":"Усиление Реморы: когда Ремора заканчивается, наносит цели урон лакшаны в размере 800 % от АТК в зависимости от длительности Реморы. Каждая секунда сверх базовой длительности в 5 секунд увеличивает урон на 45 % (до 300 %). При повторной активации длительность Реморы сбрасывается.\n\nВсё ещё думаешь, что за любым верным решением стоит свет?","attributes":[]},{"id":"GA_Chaos071_UltraSkill","name":"Возмездие","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/617e6907e14e5d88a924.webp","description":"Призывает гончую для подавления врагов рядом, накладывая Розыск на всех противников и входя в состояние «Эхо ужаса». Пока Хаос в состоянии Эха ужаса и является активным персонажем, Преступление стремительно копится, позволяя чаще использовать Окончательный приговор и наносить огромный итоговый урон.\n\nГлубоко внутри ты понимаешь, что добро и зло кружат в бесконечном цикле, и ничему из этого не приходит истинный конец.","attributes":[{"id":"parameter-0","label":"Множитель урона Подавления","value":"1: 127.3 % *4 + 290.9 % · 2: 137.5 % *4 + 314.2 % · 3: 148.5 % *4 + 339.3 % · 4: 160.4 % *4 + 366.5 % · 5: 173.2 % *4 + 395.8 % · 6: 187 % *4 + 427.4 % · 7: 202 % *4 + 461.6 % · 8: 218.2 % *4 + 498.6 % · 9: 235.6 % *4 + 538.4 % · 10: 254.5 % *4 + 581.5 % · 11: 274.8 % *4 + 628 % · 12: 296.8 % *4 + 678.3 % · 13: 320.6 % *4 + 732.5 %"},{"id":"parameter-1","label":"Длительность Эха ужаса","value":"12 сек."},{"id":"parameter-3","label":"Длительность Розыска","value":"15 сек."}]},{"id":"GA_Chaos071_QTE","name":"Натиск","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/79dccd883a2e16d3c8e4.webp","description":"Натиск\nИ не надейся сбежать! Бьёт косой снизу вверх, нанося 1 удар урона лакшаны.\n\nОбъединённые общей целью, несмотря ни на что — как и прежде.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"}]},{"id":"GA_Chaos_Passive_2","name":"Главная цель","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/c174f57492efd6c2b670.webp","description":"Увеличивает бонус к урону от Розыска до 30 %.\n\n«Документы оформлены. Разрешения выданы.»","attributes":[]},{"id":"GA_Chaos071_Passive_3","name":"Пепельная тень","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/abf88e0ea4481dc95976.webp","description":"Находясь в открытом мире, удерживайте кнопку прицеливания, чтобы оставить его гончую позади в качестве маячка для перемещения. При телепортации с карты гончая прорезает проход сквозь пространство, позволяя Хаосу вернуться к маячку.\n\nНо за тенью прошлого тебе не угнаться.","attributes":[]},{"id":"GA_Chaos071_Skill","name":"Метка сомнения","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/28656e35722888312641.webp","description":"Метка сомнения\nХарактеристики цели подтверждены. Стреляет по врагам спереди и призывает гончую, чтобы та набросилась на цель. Гончая кусает цель дважды, мечась из стороны в сторону. При попадании накладывает максимум на 2 врагов Розыск на 15 сек. При атаке целей с Розыском увеличивает урон на 20 %.\n\nХаос не помнит, откуда взялась гончая. Только то, что очень скучал по домашней собачке — и вдруг она уже здесь.","attributes":[{"id":"parameter-0","label":"Множитель урона укуса","value":"1: 82.5 % + 217.5 % · 2: 89.1 % + 234.9 % · 3: 96.2 % + 253.7 % · 4: 103.9 % + 274 % · 5: 112.2 % + 295.9 % · 6: 121.2 % + 319.6 % · 7: 130.9 % + 345.1 % · 8: 141.4 % + 372.8 % · 9: 152.7 % + 402.6 % · 10: 164.9 % + 434.8 % · 11: 178.1 % + 469.6 % · 12: 192.4 % + 507.1 % · 13: 207.7 % + 547.7 %"},{"id":"parameter-5","label":"Длительность Розыска","value":"15 сек."}]},{"id":"GA_Chaos071_Melee","name":"Погоня","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/e683634a0b5e4bb7edd6.webp","description":"Базовая атака: Погоня\nПроводит до 5 последовательных атак подряд своим оружием, нанося урон лакшаны и накапливая Преступление.\n\nБазовая атака: Окончательный приговор\nВаша вина очевидна. Удерживайте кнопку базовой атаки, чтобы применить Окончательный приговор. Если текущее Преступление достигло предела (1000), расходует весь запас Преступления, добавляет 2-й удар к Окончательному приговору и наносит высокий итоговый урон. Если Преступление не достигло предела, выполняет только 1-й удар Окончательного приговора, нанося урон 2 раза.\n\nБазовая атака: Переворот\nНажмите базовую атаку, находясь в воздухе, чтобы устремиться вниз, нанося 1 удар урона лакшаны по области. Урон увеличивается в зависимости от высоты падения (максимум на 100 %). При этом Хаос концентрирует разум и обостряет охотничье чутьё: обнаруживает врагов поблизости на короткое время. Замеченные цели подсвечиваются контуром.\n\nКритический контрудар: Интуиция / Инстинкт\nСрабатывает при использовании Погони после критического уклонения. Хаос наносит удар топором по цели, нанося 1 удар урона лакшаны и снижая показатель разрушения.\n\nОтточено годами тренировок.","attributes":[{"id":"parameter-0","label":"Множитель урона 1-го удара","value":"1: 18.2 % · 2: 19.7 % · 3: 21.2 % · 4: 22.9 % · 5: 24.8 % · 6: 26.7 % · 7: 28.9 % · 8: 31.2 % · 9: 33.7 % · 10: 36.4 % · 11: 39.3 % · 12: 42.4 % · 13: 45.8 %"},{"id":"parameter-1","label":"Множитель урона 2-го удара","value":"1: 15.1 % + 39 % · 2: 16.3 % + 42.1 % · 3: 17.6 % + 45.5 % · 4: 19 % + 49.1 % · 5: 20.5 % + 53.1 % · 6: 22.2 % + 57.3 % · 7: 24 % + 61.9 % · 8: 25.9 % + 66.8 % · 9: 27.9 % + 72.2 % · 10: 30.2 % + 78 % · 11: 32.6 % + 84.2 % · 12: 35.2 % + 90.9 % · 13: 38 % + 98.2 %"},{"id":"parameter-2","label":"Множитель урона 3-го удара","value":"1: 14.4 % *2 · 2: 15.6 % *2 · 3: 16.8 % *2 · 4: 18.1 % *2 · 5: 19.6 % *2 · 6: 21.2 % *2 · 7: 22.9 % *2 · 8: 24.7 % *2 · 9: 26.7 % *2 · 10: 28.8 % *2 · 11: 31.1 % *2 · 12: 33.6 % *2 · 13: 36.3 % *2"},{"id":"parameter-3","label":"Множитель урона 4-го удара","value":"1: 26.8 % + 10.2 % *2 + 86 % · 2: 28.9 % + 11 % *2 + 92.9 % · 3: 31.3 % + 11.9 % *2 + 100.3 % · 4: 33.8 % + 12.8 % *2 + 108.3 % · 5: 36.5 % + 13.9 % *2 + 117 % · 6: 39.4 % + 15 % *2 + 126.4 % · 7: 42.5 % + 16.2 % *2 + 136.5 % · 8: 45.9 % + 17.5 % *2 + 147.4 % · 9: 49.6 % + 18.9 % *2 + 159.2 % · 10: 53.6 % + 20.4 % *2 + 171.9 % · 11: 57.9 % + 22 % *2 + 185.7 % · 12: 62.5 % + 23.8 % *2 + 200.5 % · 13: 67.5 % + 25.7 % *2 + 216.6 %"},{"id":"parameter-4","label":"Множитель урона 5-го удара","value":"1: 24.9 % *2 + 79.8 % · 2: 26.9 % *2 + 86.2 % · 3: 29 % *2 + 93.1 % · 4: 31.4 % *2 + 100.5 % · 5: 33.9 % *2 + 108.6 % · 6: 36.6 % *2 + 117.3 % · 7: 39.5 % *2 + 126.6 % · 8: 42.7 % *2 + 136.8 % · 9: 46.1 % *2 + 147.7 % · 10: 49.8 % *2 + 159.5 % · 11: 53.8 % *2 + 172.3 % · 12: 58.1 % *2 + 186.1 % · 13: 62.7 % *2 + 200.9 %"},{"id":"parameter-5","label":"Множитель урона атаки в падении","value":"1: 45 % · 2: 48.6 % · 3: 52.5 % · 4: 56.7 % · 5: 61.2 % · 6: 66.1 % · 7: 71.4 % · 8: 77.1 % · 9: 83.3 % · 10: 90 % · 11: 97.2 % · 12: 104.9 % · 13: 113.3 %"},{"id":"parameter-6","label":"Множитель урона 1-го удара последующей атаки","value":"1: 57.5 % *2 · 2: 62.1 % *2 · 3: 67.1 % *2 · 4: 72.4 % *2 · 5: 78.2 % *2 · 6: 84.5 % *2 · 7: 91.2 % *2 · 8: 98.5 % *2 · 9: 106.4 % *2 · 10: 114.9 % *2 · 11: 124.1 % *2 · 12: 134.1 % *2 · 13: 144.8 % *2"},{"id":"parameter-7","label":"Множитель итогового урона 2-го удара последующей атаки","value":"1: 400 % *2 · 2: 432 % *2 · 3: 466.6 % *2 · 4: 503.9 % *2 · 5: 544.2 % *2 · 6: 587.7 % *2 · 7: 634.7 % *2 · 8: 685.5 % *2 · 9: 740.4 % *2 · 10: 799.6 % *2 · 11: 863.6 % *2 · 12: 932.7 % *2 · 13: 1007.3 % *2"},{"id":"parameter-8","label":"Множитель критического контрудара","value":"1: 106 % · 2: 114.5 % · 3: 123.6 % · 4: 133.5 % · 5: 144.2 % · 6: 155.7 % · 7: 168.2 % · 8: 181.7 % · 9: 196.2 % · 10: 211.9 % · 11: 228.8 % · 12: 247.2 % · 13: 266.9 %"}]},{"id":"City_Ability_Chaos_sp01","name":"Память / Якорь","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/d01658e49670c943e7b5.webp","description":"Увеличивает лимит размещения Якорей телепортации до 2.","attributes":[{"id":"city-0","label":"Уровень 1","value":"Увеличивает лимит размещения Якорей телепортации до 2."}]},{"id":"City_Ability_Chaos_01","name":"Мастер-удильщик","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/fa32baac5ca4571d7744.webp","description":"Добавляет 1 вид рыбы в ежедневный список выкупа по высокой цене на рыбном рынке в «Морском удильщике».","attributes":[{"id":"city-0","label":"Уровень 1","value":"Добавляет 1 вид рыбы в ежедневный список выкупа по высокой цене на рыбном рынке в «Морском удильщике»."},{"id":"city-1","label":"Уровень 2","value":"Увеличивает эффекты специальной наживки в «Морском удильщике» на 25 %."},{"id":"city-2","label":"Уровень 3","value":"Уменьшает выносливость ценной и редкой рыбы в «Морском удильщике» на 1."},{"id":"city-3","label":"Уровень 4","value":"Добавляет 1 вид рыбы в ежедневный список выкупа по высокой цене на рыбном рынке в «Морском удильщике»."},{"id":"city-4","label":"Уровень 5","value":"Уменьшает выносливость всей рыбы в «Морском удильщике» на 1."}]}]') WHERE character_id='chaos' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 12:50:16');

UPDATE character_profiles SET skins_json=json('[{"id":"Fashion_1071_swimsuit","name":"Курс сквозь волны","description":"Тёмная фигура мчится по волнам, прокладывая собственный курс. Куда он приведёт? Разберётся по ходу.","imageUrl":"/nte-meta/game-assets/1045a9af6c863a21b2f8.webp"},{"id":"Fashion_1071_0","name":"Преследователь","description":"Тёмный наряд, окутанный ночью.","imageUrl":"/nte-meta/game-assets/59492efe665868d2d70e.webp"},{"id":"Fashion_1071_1","name":"Чистое небо","description":"Повседневный уличный стиль, сочетающий простые вещи с яркими аксессуарами, чтобы подчеркнуть индивидуальность.","imageUrl":"/nte-meta/game-assets/0aebe4f7b06b4ec522eb.webp"},{"id":"Fashion_1071_nighty","name":"Не пропускать","description":"Я всегда в форме, даже в выходные.","imageUrl":"/nte-meta/game-assets/449838f10e0d9d439c95.webp"}]') WHERE character_id='chaos' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 12:50:16');

