UPDATE character_profiles SET voice_actors_json=json('[{"language":"Китайский","name":"洪海天"},{"language":"Английский","name":"Allegra Clark"},{"language":"Японский","name":"市ノ瀬加那"},{"language":"Корейский","name":"이다은"},{"language":"Японский","name":"Kana Ichinose (市ノ瀬加那)"},{"language":"Китайский","name":"Hong Haitian (洪海天)"},{"language":"Корейский","name":"Lee Daeun (이다은)"}]') WHERE character_id='hathor' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:08:06');

UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Элитный курьер","iconUrl":"/nte-meta/game-assets/0d547ae103d238262248.webp","description":"Первое удержание кнопки навыка перенаправления в бою мгновенно даёт 6 ур. Силы экспресс-доставки."},{"level":2,"kind":"awakening","name":"Царство шипов","iconUrl":"/nte-meta/game-assets/4ce2af8ab5f787137f08.webp","description":"Даёт Хатор Силу экспресс-доставки, когда Блокировка отличного рейтинга и Пятизвездочное отслеживание заканчиваются самостоятельно."},{"level":3,"kind":"awakening","name":"Потерянные крылья","iconUrl":"/nte-meta/game-assets/fa7c324156e4c63d8f54.webp","description":"Урон Хатор не являющимся боссами целям увеличивается на 15 %."},{"level":4,"kind":"awakening","name":"Резонанс двигателя","iconUrl":"/nte-meta/game-assets/daed7c8bbc535d9b1e9e.webp","description":"Каждый раз, когда в состоянии Срочной доставки успешно применяется Удар циклона, шанс крит. удара следующего Удара циклона увеличивается на 25 %. Эффект сбрасывается после окончания текущего состояния Срочной доставки."},{"level":5,"kind":"awakening","name":"Обычный сэндвич","iconUrl":"/nte-meta/game-assets/6d79b5e1fd0d7df49073.webp","description":"За каждый полученный уровень Силы экспресс-доставки урон по целям увеличивается на 1 %. Эффект суммируется до 15 % и сбрасывается после выхода из боя."},{"level":6,"kind":"awakening","name":"Руководство по повседневной жизни","iconUrl":"/nte-meta/game-assets/a0752197a1c28a001b9d.webp","description":"В состоянии Срочной доставки критический урон увеличивается на 30 %."},{"level":3,"kind":"resonance","name":"Удвоенная вместимость","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Уровень навыков «Быстрая доставка», «Воздушное командование» и «Быстрый скакун» увеличивается на 1."},{"level":6,"kind":"resonance","name":"Беспрепятственный проход","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"В состоянии Срочной доставки игнорирует 10 % защиты цели."}]') WHERE character_id='hathor' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:08:06');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"en-Play_Vo_Char_NPC016_weather_001","title":"Солнечно","description":"Уведомление о доставке… без риска повреждений на солнце. Погода отличная.","language":"Английский","audioUrl":"/nte-meta/game-audio/1270587ef58352f71a16.ogg"},{"id":"ja-Play_Vo_Char_NPC016_containment_001","title":"Сдерживание I","description":"Доставка выполнена. День в день.","language":"Японский","audioUrl":"/nte-meta/game-audio/0233b1613124510fc590.ogg"},{"id":"en-Play_Vo_Char_NPC016_gift_003","title":"Подарок получен III","description":"По идее, мне следовало бы сначала зарегистрировать этот подарок в магазине…","language":"Английский","audioUrl":"/nte-meta/game-audio/785602924235f7d773ee.ogg"},{"id":"en-Play_Vo_Char_NPC016_windfall_001","title":"Неожиданная добыча I","description":"Стоит сохранить.","language":"Английский","audioUrl":"/nte-meta/game-audio/4bb540b2738a05d2b5b8.ogg"},{"id":"ja-Play_Vo_Char_NPC016_self_002","title":"Обо мне: крылья","description":"Когда моя способность пробудилась, у меня на спине появилось крыло, и я могу чувствовать его как руку или ногу. Почему лишь одно крыло…? Оно не сломано. Просто недоразвито. Врачи говорят, если я научусь управлять своей способностью, в конце концов оно может стать полноценным.","language":"Японский","audioUrl":"/nte-meta/game-audio/ea8f31165b59bfd5c867.ogg"},{"id":"en-Play_Vo_Char_NPC016_containment_002","title":"Сдерживание II","description":"Куда это направлено?","language":"Английский","audioUrl":"/nte-meta/game-audio/9a3c5f2962094d0d1d66.ogg"},{"id":"en-Play_Vo_Char_NPC016_hstruck_001","title":"Сильный урон I","description":"Я не упаду.","language":"Английский","audioUrl":"/nte-meta/game-audio/b9d85ab3c667fe954a9f.ogg"},{"id":"ja-Play_Vo_Char_NPC016_windfall_003","title":"Неожиданная добыча III","description":"Их не может быть слишком много.","language":"Японский","audioUrl":"/nte-meta/game-audio/242965a01bd6e1cc6dc7.ogg"},{"id":"ja-Play_Vo_Char_NPC016_windfall_005","title":"Неожиданная добыча V","description":"Отклониться от пути — это не всегда плохо.","language":"Японский","audioUrl":"/nte-meta/game-audio/56b134f979a4551c6a51.ogg"},{"id":"en-Play_Vo_Char_NPC016_deploy_002","title":"Отправка I","description":"Отлично себя чувствую. Начнем работу.","language":"Английский","audioUrl":"/nte-meta/game-audio/9d72c94385f10f0dd337.ogg"},{"id":"ja-Play_Vo_Char_NPC016_aoe_UI_001","title":"Сверхспособность I","description":"Маршрут защищен.","language":"Японский","audioUrl":"/nte-meta/game-audio/34468f1eb00162d18c8e.ogg"},{"id":"en-Play_Vo_Char_NPC016_containment_001","title":"Сдерживание I","description":"Доставка выполнена. День в день.","language":"Английский","audioUrl":"/nte-meta/game-audio/429dbdf4f7144dcbd107.ogg"},{"id":"en-Play_Vo_Char_NPC016_greet_001","title":"Утреннее приветствие","description":"Маршрут подтвержден. Вперед.","language":"Английский","audioUrl":"/nte-meta/game-audio/3859896c548865ca45b6.ogg"},{"id":"ja-Play_Vo_Char_NPC016_chat_002","title":"Чат: элитный курьер","description":"Я отвечаю в основном за доставки аномалий класса III, сбор разведданных для заданий с высокой степенью риска и экстренное реагирование. Взрывы, автомобильные погони, воздушные пируэты…? Ханиэль преувеличивает. Ей нравятся киношные трюки. В реальности я лишь пытаюсь обогнать хаос.","language":"Японский","audioUrl":"/nte-meta/game-audio/6e78612d5723ac498940.ogg"},{"id":"ja-Play_Vo_Char_NPC016_skill_002","title":"Навык перенаправления II","description":"Время пришло.","language":"Японский","audioUrl":"/nte-meta/game-audio/1633d63093fae016bab6.ogg"},{"id":"ja-Play_Vo_Char_NPC016_skill_003","title":"Навык перенаправления III","description":"Я займусь этим.","language":"Японский","audioUrl":"/nte-meta/game-audio/7c53de892fb537d4d752.ogg"},{"id":"ja-Play_Vo_Char_NPC016_aoe_UI_003","title":"Сверхспособность III","description":"Идеальный тайминг.","language":"Японский","audioUrl":"/nte-meta/game-audio/404ada112f5202044350.ogg"},{"id":"en-Play_Vo_Char_NPC016_aoe_UI_003","title":"Сверхспособность III","description":"Идеальный тайминг.","language":"Английский","audioUrl":"/nte-meta/game-audio/0a729593994ff2fbd0be.ogg"},{"id":"en-Play_Vo_Char_NPC016_dead_003","title":"Потеря сознания III","description":"Все ещё недостаточно сильна…","language":"Английский","audioUrl":"/nte-meta/game-audio/cec34902974dda37cffa.ogg"},{"id":"en-Play_Vo_Char_NPC016_self_003","title":"Обо мне: колючки","description":"Судя по записям наставницы, каждый раз когда моя сила пробуждается, повсюду лезут шипы. Я сжала их до минимально возможного стабильного диапазона, но все ещё не могу контролировать полностью.","language":"Английский","audioUrl":"/nte-meta/game-audio/e8f2ec4ee25d1eef3b11.ogg"},{"id":"ja-Play_Vo_Char_NPC016_dead_002","title":"Потеря сознания II","description":"Я проиграла…","language":"Японский","audioUrl":"/nte-meta/game-audio/a578a2a5bb4f33d8dbd2.ogg"},{"id":"ja-Play_Vo_Char_NPC016_kill_001","title":"Убийство I","description":"Отличный прогресс.","language":"Японский","audioUrl":"/nte-meta/game-audio/b9a2e4ecdb60dae8ef78.ogg"},{"id":"ja-Play_Vo_Char_NPC016_vexation_001","title":"Проблемы","description":"С того момента, как наставница попросила меня узнать больше о жизни молодежи, Ханиэль делится самым разным контентом. Кое-что весьма интересно, но некоторые идеи… «Зачем быть серьезной, если можно сходить с ума?» или «Назад! Моя сила сейчас вырвется из-под контроля!»… Я не понимаю их. Нет ничего хорошего в силе, которой ты не можешь управлять.","language":"Японский","audioUrl":"/nte-meta/game-audio/07018f020cf453ee6ea1.ogg"},{"id":"en-Play_Vo_Char_NPC016_aoe_UI_001","title":"Сверхспособность I","description":"Маршрут защищен.","language":"Английский","audioUrl":"/nte-meta/game-audio/7608cf6c80d5b21e6435.ogg"},{"id":"en-Play_Vo_Char_NPC016_Parry_002","title":"Парирование II","description":"Достаточно одного мгновения.","language":"Английский","audioUrl":"/nte-meta/game-audio/be9ddbffcf48f53d0f31.ogg"},{"id":"en-Play_Vo_Char_NPC016_self_002","title":"Обо мне: крылья","description":"Когда моя способность пробудилась, у меня на спине появилось крыло, и я могу чувствовать его как руку или ногу. Почему лишь одно крыло…? Оно не сломано. Просто недоразвито. Врачи говорят, если я научусь управлять своей способностью, в конце концов оно может стать полноценным.","language":"Английский","audioUrl":"/nte-meta/game-audio/f0da2c11dbdd77aba266.ogg"},{"id":"ja-Play_Vo_Char_NPC016_about_004","title":"Об Иллике","description":"Что бы он ни делал, он всегда воодушевлен и всегда выдает странные фразы. Если знать, что он сейчас смотрит, то можно примерно понять, о чем он говорит.","language":"Японский","audioUrl":"/nte-meta/game-audio/e2dfcc56f973e7704b21.ogg"},{"id":"ja-Play_Vo_Char_NPC016_Switch_003","title":"Переключение III","description":"Придерживаемся плана.","language":"Японский","audioUrl":"/nte-meta/game-audio/60e4104d49ce0962ad8e.ogg"},{"id":"en-Play_Vo_Char_NPC016_about_002","title":"О Цзююань","description":"С момента основания «Стерри» нагрузка на наставницу все растет. У неё часто горит свет до поздней ночи. Я хочу стать сильнее. Достаточно сильной, чтобы облегчить её ношу.","language":"Английский","audioUrl":"/nte-meta/game-audio/be50ef38a5ec41ec9d81.ogg"},{"id":"en-Play_Vo_Char_NPC016_about_005","title":"О «Стерри Экспресс»","description":"Раньше я контактировала только со своей наставницей. Она и Дженсон основали «Стерри». В старые времена даже небольшие объемы доставок казались неподъемными. После того, как к нам присоединились Ханиэль и Иллика, дела пошли на лад, и место стало немного более… живым.","language":"Английский","audioUrl":"/nte-meta/game-audio/7d3b20c2bc8370f0dfb4.ogg"},{"id":"en-Play_Vo_Char_NPC016_chat_002","title":"Чат: элитный курьер","description":"Я отвечаю в основном за доставки аномалий класса III, сбор разведданных для заданий с высокой степенью риска и экстренное реагирование. Взрывы, автомобильные погони, воздушные пируэты…? Ханиэль преувеличивает. Ей нравятся киношные трюки. В реальности я лишь пытаюсь обогнать хаос.","language":"Английский","audioUrl":"/nte-meta/game-audio/a1ca2436a0f057fd4c7f.ogg"},{"id":"en-Play_Vo_Char_NPC016_ug_001","title":"Вознесение персонажа I","description":"Будь начеку.","language":"Английский","audioUrl":"/nte-meta/game-audio/0c8cbaaaaccccac79638.ogg"},{"id":"ja-Play_Vo_Char_NPC016_Fly_002","title":"Планирование II","description":"Сохраняй равновесие.","language":"Японский","audioUrl":"/nte-meta/game-audio/5c2035bb46e3ae847296.ogg"},{"id":"ja-Play_Vo_Char_NPC016_greet_003","title":"Вечернее приветствие","description":"Добрый вечер. Не время прохлаждаться.","language":"Японский","audioUrl":"/nte-meta/game-audio/652030aebb550b319956.ogg"},{"id":"ja-Play_Vo_Char_NPC016_about_002","title":"О Цзююань","description":"С момента основания «Стерри» нагрузка на наставницу все растет. У неё часто горит свет до поздней ночи. Я хочу стать сильнее. Достаточно сильной, чтобы облегчить её ношу.","language":"Японский","audioUrl":"/nte-meta/game-audio/85a625026b2304654afa.ogg"},{"id":"ja-Play_Vo_Char_NPC016_chat_001","title":"Чат: тормозные колодки","description":"Керамические тормозные колодки сохраняют производительность при сверхвысоких температурах, идеальны для быстрого отклика в экстренных ситуациях. Полуметаллические колодки быстрее охлаждаются и стоят меньше, это отличный вариант для повседневной езды. Колодки из спёченного металла выдерживают длительное интенсивное торможение и прекрасно подходят для горных маршрутов. Выбор правильного типа в правильных обстоятельствах сводит к минимуму задержки при доставке и обеспечивает своевременность выполнения задач.","language":"Японский","audioUrl":"/nte-meta/game-audio/ef3aa2fc4e44947d376b.ogg"},{"id":"ja-Play_Vo_Char_NPC016_QTE_003","title":"Атака на входе III","description":"Прямо сейчас.","language":"Японский","audioUrl":"/nte-meta/game-audio/021d2821b1374e657089.ogg"},{"id":"ja-Play_Vo_Char_NPC016_windfall_002","title":"Неожиданная добыча II","description":"Чистое получение.","language":"Японский","audioUrl":"/nte-meta/game-audio/b22621111d355df0f6c7.ogg"},{"id":"ja-Play_Vo_Char_NPC016_chat_003","title":"Чат: защечные мешки","description":"Некоторые содержащиеся под контролем аномалии требуют жёстких условий хранения — даже небольшое изменение температуры может изменить их поведение. Хранение в Защёчном мешке стабилизирует их. Это как маленький карман-питомец: капризный и привередливый, но никогда не подводит.","language":"Японский","audioUrl":"/nte-meta/game-audio/cd33cdfb417fec57b773.ogg"},{"id":"ja-Play_Vo_Char_NPC016_struck_001","title":"Урон I","description":"Продолжай.","language":"Японский","audioUrl":"/nte-meta/game-audio/46b5574ce5ddb806fe6d.ogg"},{"id":"en-Play_Vo_Char_NPC016_Fly_002","title":"Планирование II","description":"Сохраняй равновесие.","language":"Английский","audioUrl":"/nte-meta/game-audio/4d0f2d22601d4931c5fc.ogg"},{"id":"en-Play_Vo_Char_NPC016_TeammateDown_001","title":"Поражен товарищ по команде – Цзююань","description":"Я внимательно с этим разберусь.","language":"Английский","audioUrl":"/nte-meta/game-audio/864eeb5ac19a7b8d8d2b.ogg"},{"id":"en-Play_Vo_Char_NPC016_windfall_003","title":"Неожиданная добыча III","description":"Их не может быть слишком много.","language":"Английский","audioUrl":"/nte-meta/game-audio/0807f24ebe7e0fefaf78.ogg"},{"id":"ja-Play_Vo_Char_NPC016_fh_001","title":"Исцеление I","description":"Точно в срок.","language":"Японский","audioUrl":"/nte-meta/game-audio/82049bba9ebc69d36d59.ogg"},{"id":"ja-Play_Vo_Char_NPC016_ug_003","title":"Вознесение персонажа III","description":"Похоже, упорный труд правда приносит плоды.","language":"Японский","audioUrl":"/nte-meta/game-audio/5b78a86c6869a3acca72.ogg"},{"id":"ja-Play_Vo_Char_NPC016_weather_002","title":"Дождливо","description":"Крылья и машины не очень хорошо переносят дождь. Сегодняшние доставки должны стартовать на 25 минут раньше.","language":"Японский","audioUrl":"/nte-meta/game-audio/f52edbfac3ab0bb63284.ogg"},{"id":"ja-Play_Vo_Char_NPC016_weather_004","title":"Жарко","description":"Мотоцикл перегревается. Сделаем небольшой перерыв.","language":"Японский","audioUrl":"/nte-meta/game-audio/cc925f4f1e2e551e2642.ogg"},{"id":"en-Play_Vo_Char_NPC016_about_003","title":"О Ханиэль","description":"Мы встретились случайно. В то время я не умела контролировать свою силу. Ханиэль помогла мне стабилизироваться. Потом она присоединилась к «Стерри» и научила меня многому из жизни современной молодежи… Она говорит, что мы не учительница и ученица, а просто подруги. Наша последняя встреча? Наверное, на конвенции по аниме… Она была… энергичной.","language":"Английский","audioUrl":"/nte-meta/game-audio/60b1efaecac18a0f6ab8.ogg"},{"id":"ja-Play_Vo_Char_NPC016_aoe_UI_002","title":"Сверхспособность II","description":"Пробуксовка — и путь свободен.","language":"Японский","audioUrl":"/nte-meta/game-audio/8f1783259a5591c5820d.ogg"},{"id":"ja-Play_Vo_Char_NPC016_dead_003","title":"Потеря сознания III","description":"Все ещё недостаточно сильна…","language":"Японский","audioUrl":"/nte-meta/game-audio/14350453bb51fdd8a7e5.ogg"},{"id":"ja-Play_Vo_Char_NPC016_greet_002","title":"Дневное приветствие","description":"Сделай перерыв. Будь начеку.","language":"Японский","audioUrl":"/nte-meta/game-audio/7b4c7372a600b5f3226f.ogg"},{"id":"en-Play_Vo_Char_NPC016_about_004","title":"Об Иллике","description":"Что бы он ни делал, он всегда воодушевлен и всегда выдает странные фразы. Если знать, что он сейчас смотрит, то можно примерно понять, о чем он говорит.","language":"Английский","audioUrl":"/nte-meta/game-audio/de54b036d6dcfb307352.ogg"},{"id":"en-Play_Vo_Char_NPC016_hp_001","title":"Низкий уровень здоровья I","description":"Выглядит не очень…","language":"Английский","audioUrl":"/nte-meta/game-audio/1a0c51c3452393d695b6.ogg"},{"id":"ja-Play_Vo_Char_NPC016_about_005","title":"О «Стерри Экспресс»","description":"Раньше я контактировала только со своей наставницей. Она и Дженсон основали «Стерри». В старые времена даже небольшие объемы доставок казались неподъемными. После того, как к нам присоединились Ханиэль и Иллика, дела пошли на лад, и место стало немного более… живым.","language":"Японский","audioUrl":"/nte-meta/game-audio/4d07f258038768782607.ogg"},{"id":"ja-Play_Vo_Char_NPC016_ug_001","title":"Вознесение персонажа I","description":"Будь начеку.","language":"Японский","audioUrl":"/nte-meta/game-audio/d06f8b4de2b547a0228e.ogg"},{"id":"en-Play_Vo_Char_NPC016_meet_001","title":"Первая встреча","description":"Привет. Я Хатор, элитный курьер «Стерри Экспресс». Пожалуйста, подтвердите доставку и поставьте подпись в Подтверждении получения. Комиссия будет списана после подтверждения получения.","language":"Английский","audioUrl":"/nte-meta/game-audio/faa95140fe8527636ef5.ogg"},{"id":"ja-Play_Vo_Char_NPC016_anomaly_004","title":"Нуллификация II","description":"Спасибо за оценку.","language":"Японский","audioUrl":"/nte-meta/game-audio/b04ca69a0232cbaadef3.ogg"},{"id":"ja-Play_Vo_Char_NPC016_hstruck_001","title":"Сильный урон I","description":"Я не упаду.","language":"Японский","audioUrl":"/nte-meta/game-audio/e7c8847ac82b383f88e4.ogg"},{"id":"ja-Play_Vo_Char_NPC016_weather_003","title":"Холодно","description":"Противоскользящие шины… цепи… всё готово.","language":"Японский","audioUrl":"/nte-meta/game-audio/66b03787de9be6ade4be.ogg"},{"id":"en-Play_Vo_Char_NPC016_greet_002","title":"Дневное приветствие","description":"Сделай перерыв. Будь начеку.","language":"Английский","audioUrl":"/nte-meta/game-audio/9895f4437f1578b0ac1e.ogg"},{"id":"ja-Play_Vo_Char_NPC016_deploy_002","title":"Отправка I","description":"Отлично себя чувствую. Начнем работу.","language":"Японский","audioUrl":"/nte-meta/game-audio/ffeb5189a2560aac932e.ogg"},{"id":"ja-Play_Vo_Char_NPC016_Parry_001","title":"Парирование I","description":"Как и следовало ожидать.","language":"Японский","audioUrl":"/nte-meta/game-audio/e17afe5538eb87e8f7c3.ogg"},{"id":"en-Play_Vo_Char_NPC016_Switch_001","title":"Переключение I","description":"Я обеспечу поддержку.","language":"Английский","audioUrl":"/nte-meta/game-audio/13c8c6a55301795b7a24.ogg"},{"id":"ja-Play_Vo_Char_NPC016_windfall_001","title":"Неожиданная добыча I","description":"Стоит сохранить.","language":"Японский","audioUrl":"/nte-meta/game-audio/1570922d3d4ae8aa707a.ogg"},{"id":"ja-Play_Vo_Char_NPC016_struck_002","title":"Урон II","description":"Я просто разогреваюсь.","language":"Японский","audioUrl":"/nte-meta/game-audio/8d2337e7d8c46e9484e2.ogg"},{"id":"ja-Play_Vo_Char_NPC016_about_001","title":"О Дженсоне","description":"Большую часть времени его здесь нет. Если не можешь с ним связаться, он, наверное, в каком-нибудь баре.","language":"Японский","audioUrl":"/nte-meta/game-audio/cf36ad611e4865040277.ogg"},{"id":"en-Play_Vo_Char_NPC016_anomaly_003","title":"Нуллификация I","description":"Спасибо за поддержку.","language":"Английский","audioUrl":"/nte-meta/game-audio/4558b8b8436d6de9abc3.ogg"},{"id":"ja-Play_Vo_Char_NPC016_gift_003","title":"Подарок получен III","description":"По идее, мне следовало бы сначала зарегистрировать этот подарок в магазине…","language":"Японский","audioUrl":"/nte-meta/game-audio/983df0e90162e2f4e3c0.ogg"},{"id":"en-Play_Vo_Char_NPC016_weather_004","title":"Жарко","description":"Мотоцикл перегревается. Сделаем небольшой перерыв.","language":"Английский","audioUrl":"/nte-meta/game-audio/2e1215184985a337d93d.ogg"},{"id":"en-Play_Vo_Char_NPC016_QTE_001","title":"Атака на входе I","description":"Некуда бежать.","language":"Английский","audioUrl":"/nte-meta/game-audio/4f076e06934cb0a3f1f5.ogg"},{"id":"en-Play_Vo_Char_NPC016_vexation_001","title":"Проблемы","description":"С того момента, как наставница попросила меня узнать больше о жизни молодежи, Ханиэль делится самым разным контентом. Кое-что весьма интересно, но некоторые идеи… «Зачем быть серьезной, если можно сходить с ума?» или «Назад! Моя сила сейчас вырвется из-под контроля!»… Я не понимаю их. Нет ничего хорошего в силе, которой ты не можешь управлять.","language":"Английский","audioUrl":"/nte-meta/game-audio/fee5615f5653fadc9e3e.ogg"},{"id":"ja-Play_Vo_Char_NPC016_fh_002","title":"Исцеление II","description":"…Я твоя должница.","language":"Японский","audioUrl":"/nte-meta/game-audio/9eac742d5a992f2c8392.ogg"},{"id":"ja-Play_Vo_Char_NPC016_greet_004","title":"Спокойной ночи","description":"Отдохни. Я займусь этим.","language":"Японский","audioUrl":"/nte-meta/game-audio/16d91901584759d021c3.ogg"},{"id":"en-Play_Vo_Char_NPC016_fh_002","title":"Исцеление II","description":"…Я твоя должница.","language":"Английский","audioUrl":"/nte-meta/game-audio/ef44489854d4b4853cea.ogg"},{"id":"en-Play_Vo_Char_NPC016_greet_004","title":"Спокойной ночи","description":"Отдохни. Я займусь этим.","language":"Английский","audioUrl":"/nte-meta/game-audio/8f30ac196505261a088c.ogg"},{"id":"en-Play_Vo_Char_NPC016_Switch_002","title":"Переключение II","description":"Я займусь этим.","language":"Английский","audioUrl":"/nte-meta/game-audio/124223e6cbf822a6d08d.ogg"},{"id":"en-Play_Vo_Char_NPC016_kill_002","title":"Убийство II","description":"Ничего страшного.","language":"Английский","audioUrl":"/nte-meta/game-audio/da526d1722de8266b969.ogg"},{"id":"en-Play_Vo_Char_NPC016_QTE_003","title":"Атака на входе III","description":"Прямо сейчас.","language":"Английский","audioUrl":"/nte-meta/game-audio/cf53158e6e1a35a1c20d.ogg"},{"id":"en-Play_Vo_Char_NPC016_anomaly_004","title":"Нуллификация II","description":"Спасибо за оценку.","language":"Английский","audioUrl":"/nte-meta/game-audio/327c411b99d06a51398b.ogg"},{"id":"en-Play_Vo_Char_NPC016_DodgeCombo_001","title":"Серия критических уклонений I","description":"Ещё раз. Тот же результат.","language":"Английский","audioUrl":"/nte-meta/game-audio/71c0a10619e2781fec0b.ogg"},{"id":"en-Play_Vo_Char_NPC016_ug_003","title":"Вознесение персонажа III","description":"Похоже, упорный труд правда приносит плоды.","language":"Английский","audioUrl":"/nte-meta/game-audio/574d0248d4f040558c78.ogg"},{"id":"ja-Play_Vo_Char_NPC016_weather_001","title":"Солнечно","description":"Уведомление о доставке… без риска повреждений на солнце. Погода отличная.","language":"Японский","audioUrl":"/nte-meta/game-audio/848739480840c2beb23f.ogg"},{"id":"en-Play_Vo_Char_NPC016_kill_001","title":"Убийство I","description":"Отличный прогресс.","language":"Английский","audioUrl":"/nte-meta/game-audio/f6452f72b3ad352ccaf0.ogg"},{"id":"ja-Play_Vo_Char_NPC016_dead_001","title":"Потеря сознания I","description":"Моя последняя доставка…","language":"Японский","audioUrl":"/nte-meta/game-audio/d961a5891682c0d4671c.ogg"},{"id":"en-Play_Vo_Char_NPC016_about_001","title":"О Дженсоне","description":"Большую часть времени его здесь нет. Если не можешь с ним связаться, он, наверное, в каком-нибудь баре.","language":"Английский","audioUrl":"/nte-meta/game-audio/e4184f43112173e00248.ogg"},{"id":"en-Play_Vo_Char_NPC016_aoe_UI_002","title":"Сверхспособность II","description":"Пробуксовка — и путь свободен.","language":"Английский","audioUrl":"/nte-meta/game-audio/b8784119526130be41cf.ogg"},{"id":"en-Play_Vo_Char_NPC016_gift_002","title":"Подарок получен II","description":"Я доставила подарки множеству людей, но сама получаю их не так уж часто.","language":"Английский","audioUrl":"/nte-meta/game-audio/a2068719b89441829d03.ogg"},{"id":"en-Play_Vo_Char_NPC016_greet_003","title":"Вечернее приветствие","description":"Добрый вечер. Не время прохлаждаться.","language":"Английский","audioUrl":"/nte-meta/game-audio/54b30ba62b7e7a46df1b.ogg"},{"id":"en-Play_Vo_Char_NPC016_SSC_001","title":"Особое переключение — Цзююань","description":"Принято к сведению.","language":"Английский","audioUrl":"/nte-meta/game-audio/5ac559aceca84e1fc056.ogg"},{"id":"ja-Play_Vo_Char_NPC016_talk_002","title":"Тема: шоссейный велоспорт","description":"В свободное от работы время я иногда езжу по горным дорогам, без цели… Просто катаюсь. Если интересуешься живописными маршрутами, я потом вышлю тебе путеводитель… Пришлю файлом в Bagel.","language":"Японский","audioUrl":"/nte-meta/game-audio/5561924e647a2a00d7d8.ogg"},{"id":"en-Play_Vo_Char_NPC016_struck_002","title":"Урон II","description":"Я просто разогреваюсь.","language":"Английский","audioUrl":"/nte-meta/game-audio/ffced6005cd2421a4bf7.ogg"},{"id":"en-Play_Vo_Char_NPC016_chat_001","title":"Чат: тормозные колодки","description":"Керамические тормозные колодки сохраняют производительность при сверхвысоких температурах, идеальны для быстрого отклика в экстренных ситуациях. Полуметаллические колодки быстрее охлаждаются и стоят меньше, это отличный вариант для повседневной езды. Колодки из спёченного металла выдерживают длительное интенсивное торможение и прекрасно подходят для горных маршрутов. Выбор правильного типа в правильных обстоятельствах сводит к минимуму задержки при доставке и обеспечивает своевременность выполнения задач.","language":"Английский","audioUrl":"/nte-meta/game-audio/7f2d1a3659ff6848ee1e.ogg"},{"id":"ja-Play_Vo_Char_NPC016_hp_003","title":"Низкий уровень здоровья III","description":"Сохраняй спокойствие.","language":"Японский","audioUrl":"/nte-meta/game-audio/38a924066a7832a2fa68.ogg"},{"id":"en-Play_Vo_Char_NPC016_skill_003","title":"Навык перенаправления III","description":"Я займусь этим.","language":"Английский","audioUrl":"/nte-meta/game-audio/12482693fa4bc37a734f.ogg"},{"id":"ja-Play_Vo_Char_NPC016_self_003","title":"Обо мне: колючки","description":"Судя по записям наставницы, каждый раз когда моя сила пробуждается, повсюду лезут шипы. Я сжала их до минимально возможного стабильного диапазона, но все ещё не могу контролировать полностью.","language":"Японский","audioUrl":"/nte-meta/game-audio/f6a4faaa93aa4eec6e68.ogg"},{"id":"ja-Play_Vo_Char_NPC016_SSC_002","title":"Особое переключение — Ханиэль","description":"Не волнуйтесь, я разберусь.","language":"Японский","audioUrl":"/nte-meta/game-audio/bcde50a7514a6ed96b95.ogg"},{"id":"en-Play_Vo_Char_NPC016_skill_001","title":"Навык перенаправления I","description":"Цель подтверждена.","language":"Английский","audioUrl":"/nte-meta/game-audio/efaeffa9ea751b99999c.ogg"},{"id":"ja-Play_Vo_Char_NPC016_hp_002","title":"Низкий уровень здоровья II","description":"Надо переосмыслить план…","language":"Японский","audioUrl":"/nte-meta/game-audio/0c61a8d0af68d9abd80f.ogg"},{"id":"ja-Play_Vo_Char_NPC016_Switch_001","title":"Переключение I","description":"Я обеспечу поддержку.","language":"Японский","audioUrl":"/nte-meta/game-audio/d2a35bebb90dc7ffc0e6.ogg"},{"id":"en-Play_Vo_Char_NPC016_deploy_001","title":"Отправка II","description":"Срочное задание. Я готова.","language":"Английский","audioUrl":"/nte-meta/game-audio/09074c54fd5fd288e580.ogg"},{"id":"en-Play_Vo_Char_NPC016_windfall_006","title":"Неожиданная добыча VI","description":"То, что надо.","language":"Английский","audioUrl":"/nte-meta/game-audio/4ebd8a421dcb1de4d338.ogg"},{"id":"ja-Play_Vo_Char_NPC016_DodgeCombo_001","title":"Серия критических уклонений I","description":"Ещё раз. Тот же результат.","language":"Японский","audioUrl":"/nte-meta/game-audio/68c231f0b23a3ad12541.ogg"},{"id":"ja-Play_Vo_Char_NPC016_meet_001","title":"Первая встреча","description":"Привет. Я Хатор, элитный курьер «Стерри Экспресс». Пожалуйста, подтвердите доставку и поставьте подпись в Подтверждении получения. Комиссия будет списана после подтверждения получения.","language":"Японский","audioUrl":"/nte-meta/game-audio/b7907d51915d567a1394.ogg"},{"id":"ja-Play_Vo_Char_NPC016_talk_003","title":"Тема: еда","description":"У меня нет определенных предпочтений в плане еды. Для меня еда — просто топливо. Но если выбирать, я бы выбрала… сэндвичи. Много калорий, стабильная структура, идеальны для работы.","language":"Японский","audioUrl":"/nte-meta/game-audio/6823384f55bba0086a88.ogg"},{"id":"en-Play_Vo_Char_NPC016_windfall_002","title":"Неожиданная добыча II","description":"Чистое получение.","language":"Английский","audioUrl":"/nte-meta/game-audio/47d031928113a5fca6d3.ogg"},{"id":"ja-Play_Vo_Char_NPC016_SSC_001","title":"Особое переключение — Цзююань","description":"Принято к сведению.","language":"Японский","audioUrl":"/nte-meta/game-audio/06e931d9047590c99c20.ogg"},{"id":"en-Play_Vo_Char_NPC016_gift_001","title":"Подарок получен I","description":"Куда это доставить? О… так получатель — я?","language":"Английский","audioUrl":"/nte-meta/game-audio/2d8d0929da2321d12edc.ogg"},{"id":"en-Play_Vo_Char_NPC016_hp_002","title":"Низкий уровень здоровья II","description":"Надо переосмыслить план…","language":"Английский","audioUrl":"/nte-meta/game-audio/e72ea6f9b2ec8ef340cb.ogg"},{"id":"en-Play_Vo_Char_NPC016_weather_002","title":"Дождливо","description":"Крылья и машины не очень хорошо переносят дождь. Сегодняшние доставки должны стартовать на 25 минут раньше.","language":"Английский","audioUrl":"/nte-meta/game-audio/9992b5529bc7f799a29e.ogg"},{"id":"ja-Play_Vo_Char_NPC016_Fly_001","title":"Планирование I","description":"Периметр свободен.","language":"Японский","audioUrl":"/nte-meta/game-audio/b75327322cbf8dde42b7.ogg"},{"id":"ja-Play_Vo_Char_NPC016_windfall_004","title":"Неожиданная добыча IV","description":"Отличный прогресс.","language":"Японский","audioUrl":"/nte-meta/game-audio/90b59e6d774bc90861ab.ogg"},{"id":"ja-Play_Vo_Char_NPC016_kill_002","title":"Убийство II","description":"Ничего страшного.","language":"Японский","audioUrl":"/nte-meta/game-audio/13d9eda24a93a20229d2.ogg"},{"id":"ja-Play_Vo_Char_NPC016_self_001","title":"Обо мне: способности эспера","description":"Иногда моя способность выходит из-под контроля, и я теряю разум. Говорят, я угроза для города, и меня нужно ограничить. В прошлом лишь моя наставница смогла меня стабилизировать. Она поручилась за меня и всегда была рядом. После упорных тренировок я научилась контролировать себя намного лучше. Но если я потеряю контроль во время миссии, и ни наставницы, ни Ханиэль не окажется рядом… прикончи меня. Не сомневайся.","language":"Японский","audioUrl":"/nte-meta/game-audio/52d7dec169218fc2222b.ogg"},{"id":"ja-Play_Vo_Char_NPC016_deploy_001","title":"Отправка II","description":"Срочное задание. Я готова.","language":"Японский","audioUrl":"/nte-meta/game-audio/2760e074c26784209776.ogg"},{"id":"ja-Play_Vo_Char_NPC016_greet_001","title":"Утреннее приветствие","description":"Маршрут подтвержден. Вперед.","language":"Японский","audioUrl":"/nte-meta/game-audio/872d2c04b81d36d01bfe.ogg"},{"id":"en-Play_Vo_Char_NPC016_gift_004","title":"Подарок получен IV","description":"Я буду его беречь.","language":"Английский","audioUrl":"/nte-meta/game-audio/d2064a0b5d1c7dbd4a97.ogg"},{"id":"en-Play_Vo_Char_NPC016_Parry_001","title":"Парирование I","description":"Как и следовало ожидать.","language":"Английский","audioUrl":"/nte-meta/game-audio/bd59d0c7c7f87354f3b0.ogg"},{"id":"en-Play_Vo_Char_NPC016_windfall_004","title":"Неожиданная добыча IV","description":"Отличный прогресс.","language":"Английский","audioUrl":"/nte-meta/game-audio/6dd5096503df7a045528.ogg"},{"id":"en-Play_Vo_Char_NPC016_SSC_002","title":"Особое переключение — Ханиэль","description":"Не волнуйтесь, я разберусь.","language":"Английский","audioUrl":"/nte-meta/game-audio/3752f064c0ec4f6c17cb.ogg"},{"id":"ja-Play_Vo_Char_NPC016_skill_001","title":"Навык перенаправления I","description":"Цель подтверждена.","language":"Японский","audioUrl":"/nte-meta/game-audio/aa23fea94bc39f5b3856.ogg"},{"id":"ja-Play_Vo_Char_NPC016_TeammateDown_002","title":"Поражен товарищ по команде – Ханиэль","description":"Я тебя прикрою. Ты пока лечись.","language":"Японский","audioUrl":"/nte-meta/game-audio/6bfc3db0a8f68ad19fcc.ogg"},{"id":"en-Play_Vo_Char_NPC016_dead_001","title":"Потеря сознания I","description":"Моя последняя доставка…","language":"Английский","audioUrl":"/nte-meta/game-audio/14328a52490f8eee94ed.ogg"},{"id":"en-Play_Vo_Char_NPC016_hobby_001","title":"Хобби","description":"Сейчас главный приоритет — выполнить поручение моей наставницы.","language":"Английский","audioUrl":"/nte-meta/game-audio/bc88eef15952aade30be.ogg"},{"id":"ja-Play_Vo_Char_NPC016_containment_002","title":"Сдерживание II","description":"Куда это направлено?","language":"Японский","audioUrl":"/nte-meta/game-audio/303db8d0124b3ff8c17c.ogg"},{"id":"ja-Play_Vo_Char_NPC016_gift_001","title":"Подарок получен I","description":"Куда это доставить? О… так получатель — я?","language":"Японский","audioUrl":"/nte-meta/game-audio/018d7f6d7197892ca10a.ogg"},{"id":"ja-Play_Vo_Char_NPC016_gift_004","title":"Подарок получен IV","description":"Я буду его беречь.","language":"Японский","audioUrl":"/nte-meta/game-audio/0c2822f3e91c79309196.ogg"},{"id":"en-Play_Vo_Char_NPC016_Switch_003","title":"Переключение III","description":"Придерживаемся плана.","language":"Английский","audioUrl":"/nte-meta/game-audio/e51ad3c9c6a7095af35f.ogg"},{"id":"en-Play_Vo_Char_NPC016_TeammateDown_002","title":"Поражен товарищ по команде – Ханиэль","description":"Я тебя прикрою. Ты пока лечись.","language":"Английский","audioUrl":"/nte-meta/game-audio/ae9d60317ef10e62e9cc.ogg"},{"id":"ja-Play_Vo_Char_NPC016_Switch_002","title":"Переключение II","description":"Я займусь этим.","language":"Японский","audioUrl":"/nte-meta/game-audio/f113f6a641ada5e65ef4.ogg"},{"id":"en-Play_Vo_Char_NPC016_fh_001","title":"Исцеление I","description":"Точно в срок.","language":"Английский","audioUrl":"/nte-meta/game-audio/dcb754d16c9960aceb39.ogg"},{"id":"en-Play_Vo_Char_NPC016_chat_003","title":"Чат: защечные мешки","description":"Некоторые содержащиеся под контролем аномалии требуют жёстких условий хранения — даже небольшое изменение температуры может изменить их поведение. Хранение в Защёчном мешке стабилизирует их. Это как маленький карман-питомец: капризный и привередливый, но никогда не подводит.","language":"Английский","audioUrl":"/nte-meta/game-audio/dd7a137c5e50f1583a1f.ogg"},{"id":"en-Play_Vo_Char_NPC016_skill_002","title":"Навык перенаправления II","description":"Время пришло.","language":"Английский","audioUrl":"/nte-meta/game-audio/2d69521f54d0091f025e.ogg"},{"id":"en-Play_Vo_Char_NPC016_weather_003","title":"Холодно","description":"Противоскользящие шины… цепи… всё готово.","language":"Английский","audioUrl":"/nte-meta/game-audio/093f8f850c1bc70c4633.ogg"},{"id":"ja-Play_Vo_Char_NPC016_talk_001","title":"Тема: маршруты доставки","description":"Приоритет определяется срочностью и уровнем риска, затем пересечением маршрутов. При окончательном выборе пути следования учитываются погодные условия, дорожные условия и зоны активности высокоуровневых аномалий.","language":"Японский","audioUrl":"/nte-meta/game-audio/cdf12762f5062cb0a561.ogg"},{"id":"ja-Play_Vo_Char_NPC016_QTE_001","title":"Атака на входе I","description":"Некуда бежать.","language":"Японский","audioUrl":"/nte-meta/game-audio/c29fe39e424c6c367c4f.ogg"},{"id":"ja-Play_Vo_Char_NPC016_Parry_002","title":"Парирование II","description":"Достаточно одного мгновения.","language":"Японский","audioUrl":"/nte-meta/game-audio/85db1b084b6e44d29cb7.ogg"},{"id":"en-Play_Vo_Char_NPC016_QTE_002","title":"Атака на входе II","description":"Никаких недоделок.","language":"Английский","audioUrl":"/nte-meta/game-audio/81e4f9800ae39cce47a0.ogg"},{"id":"en-Play_Vo_Char_NPC016_talk_001","title":"Тема: маршруты доставки","description":"Приоритет определяется срочностью и уровнем риска, затем пересечением маршрутов. При окончательном выборе пути следования учитываются погодные условия, дорожные условия и зоны активности высокоуровневых аномалий.","language":"Английский","audioUrl":"/nte-meta/game-audio/664be91ea1c1c0d7bd97.ogg"},{"id":"ja-Play_Vo_Char_NPC016_hp_001","title":"Низкий уровень здоровья I","description":"Выглядит не очень…","language":"Японский","audioUrl":"/nte-meta/game-audio/337511037e9930c46f33.ogg"},{"id":"en-Play_Vo_Char_NPC016_windfall_005","title":"Неожиданная добыча V","description":"Отклониться от пути — это не всегда плохо.","language":"Английский","audioUrl":"/nte-meta/game-audio/3a6e2892522b0e693bf4.ogg"},{"id":"ja-Play_Vo_Char_NPC016_gift_002","title":"Подарок получен II","description":"Я доставила подарки множеству людей, но сама получаю их не так уж часто.","language":"Японский","audioUrl":"/nte-meta/game-audio/9bd6fbe16e1e0d8f955c.ogg"},{"id":"ja-Play_Vo_Char_NPC016_hstruck_002","title":"Сильный урон II","description":"Осторожно.","language":"Японский","audioUrl":"/nte-meta/game-audio/97f5dd9b880aa93db608.ogg"},{"id":"en-Play_Vo_Char_NPC016_DodgeCombo_002","title":"Серия критических уклонений II","description":"Вижу брешь в защите.","language":"Английский","audioUrl":"/nte-meta/game-audio/1158b4aa00dd8f83f012.ogg"},{"id":"ja-Play_Vo_Char_NPC016_QTE_002","title":"Атака на входе II","description":"Никаких недоделок.","language":"Японский","audioUrl":"/nte-meta/game-audio/145c74a46eb5ecb3b4d2.ogg"},{"id":"ja-Play_Vo_Char_NPC016_ug_002","title":"Вознесение персонажа II","description":"Мой контроль улучшился.","language":"Японский","audioUrl":"/nte-meta/game-audio/9e9bcbfdeefba04d2b4a.ogg"},{"id":"ja-Play_Vo_Char_NPC016_windfall_006","title":"Неожиданная добыча VI","description":"То, что надо.","language":"Японский","audioUrl":"/nte-meta/game-audio/ffa87bfea509ab218e3b.ogg"},{"id":"en-Play_Vo_Char_NPC016_hp_003","title":"Низкий уровень здоровья III","description":"Сохраняй спокойствие.","language":"Английский","audioUrl":"/nte-meta/game-audio/335f17f9c94372e8994c.ogg"},{"id":"en-Play_Vo_Char_NPC016_talk_002","title":"Тема: шоссейный велоспорт","description":"В свободное от работы время я иногда езжу по горным дорогам, без цели… Просто катаюсь. Если интересуешься живописными маршрутами, я потом вышлю тебе путеводитель… Пришлю файлом в Bagel.","language":"Английский","audioUrl":"/nte-meta/game-audio/6548eb870a3284613b0d.ogg"},{"id":"en-Play_Vo_Char_NPC016_talk_003","title":"Тема: еда","description":"У меня нет определенных предпочтений в плане еды. Для меня еда — просто топливо. Но если выбирать, я бы выбрала… сэндвичи. Много калорий, стабильная структура, идеальны для работы.","language":"Английский","audioUrl":"/nte-meta/game-audio/6eb6b3634a4f021db28b.ogg"},{"id":"ja-Play_Vo_Char_NPC016_anomaly_003","title":"Нуллификация I","description":"Спасибо за поддержку.","language":"Японский","audioUrl":"/nte-meta/game-audio/84d6cd06745d5592862f.ogg"},{"id":"ja-Play_Vo_Char_NPC016_DodgeCombo_002","title":"Серия критических уклонений II","description":"Вижу брешь в защите.","language":"Японский","audioUrl":"/nte-meta/game-audio/623cb3f20c42dc58a5a0.ogg"},{"id":"en-Play_Vo_Char_NPC016_hstruck_002","title":"Сильный урон II","description":"Осторожно.","language":"Английский","audioUrl":"/nte-meta/game-audio/e297b5a18e93ca12005c.ogg"},{"id":"en-Play_Vo_Char_NPC016_struck_001","title":"Урон I","description":"Продолжай.","language":"Английский","audioUrl":"/nte-meta/game-audio/7fe93a1be8852187d686.ogg"},{"id":"en-Play_Vo_Char_NPC016_Fly_001","title":"Планирование I","description":"Периметр свободен.","language":"Английский","audioUrl":"/nte-meta/game-audio/bfd9192ad626c7dac585.ogg"},{"id":"ja-Play_Vo_Char_NPC016_about_003","title":"О Ханиэль","description":"Мы встретились случайно. В то время я не умела контролировать свою силу. Ханиэль помогла мне стабилизироваться. Потом она присоединилась к «Стерри» и научила меня многому из жизни современной молодежи… Она говорит, что мы не учительница и ученица, а просто подруги. Наша последняя встреча? Наверное, на конвенции по аниме… Она была… энергичной.","language":"Японский","audioUrl":"/nte-meta/game-audio/0d4cf2b41d406df4f26a.ogg"},{"id":"ja-Play_Vo_Char_NPC016_TeammateDown_001","title":"Поражен товарищ по команде – Цзююань","description":"Я внимательно с этим разберусь.","language":"Японский","audioUrl":"/nte-meta/game-audio/ca6dcdd112083cb29b6b.ogg"},{"id":"en-Play_Vo_Char_NPC016_dead_002","title":"Потеря сознания II","description":"Я проиграла…","language":"Английский","audioUrl":"/nte-meta/game-audio/8463e5d54c06552b23ac.ogg"},{"id":"en-Play_Vo_Char_NPC016_self_001","title":"Обо мне: способности эспера","description":"Иногда моя способность выходит из-под контроля, и я теряю разум. Говорят, я угроза для города, и меня нужно ограничить. В прошлом лишь моя наставница смогла меня стабилизировать. Она поручилась за меня и всегда была рядом. После упорных тренировок я научилась контролировать себя намного лучше. Но если я потеряю контроль во время миссии, и ни наставницы, ни Ханиэль не окажется рядом… прикончи меня. Не сомневайся.","language":"Английский","audioUrl":"/nte-meta/game-audio/61c4cd52d93fe4e9f438.ogg"},{"id":"en-Play_Vo_Char_NPC016_ug_002","title":"Вознесение персонажа II","description":"Мой контроль улучшился.","language":"Английский","audioUrl":"/nte-meta/game-audio/b0a97bdd5508fc6e7aec.ogg"},{"id":"ja-Play_Vo_Char_NPC016_hobby_001","title":"Хобби","description":"Сейчас главный приоритет — выполнить поручение моей наставницы.","language":"Японский","audioUrl":"/nte-meta/game-audio/e6c99fa24abf00f3ac7d.ogg"},{"id":"585f1bd5-e520-4544-b2c4-60cd5f226fea","title":"Hathor Voice Records / Profile Voice Lines — Английский","language":"Английский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=Ywp_xIiIVHY","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."},{"id":"5ed69ab5-ffa3-4941-8c03-ad7cc4d4130d","title":"Hathor Voice Records / Profile Voice Lines — Японский","language":"Японский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=Ywp_xIiIVHY","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."},{"id":"12c39b61-d267-4eb6-8abf-7c92b1d5ac40","title":"Hathor Voice Records / Profile Voice Lines — Корейский","language":"Корейский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=Ywp_xIiIVHY","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."},{"id":"5224a7e6-4b3a-4bb7-bbe0-af76b71037eb","title":"Hathor Voice Records / Profile Voice Lines — Китайский","language":"Китайский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=Ywp_xIiIVHY","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."}]') WHERE character_id='hathor' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:08:06');

UPDATE character_profiles SET abilities_json=json('[{"id":"GA_Hathor_UltraSkill","name":"Быстрый скакун","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/e200d309ad7b6e017f1a.webp","description":"Прочь с дороги. Призывает мотоцикл из шипов и начинает кружить вокруг целей, наезжая на врагов. Затем поднимается в воздух и обрушивается на землю, нанося 1 удар урона лакшаны по области.\n\nПосле активации навыка на некоторое время входит в состояние Срочной доставки и прекращает накапливать силу экспресс-доставки. В этом состоянии «Воздушное командование» превращается в «Удар циклона». Повышает скорость передвижения и даёт бонус к Атаке в зависимости от уровня силы экспресс-доставки. При переключении персонажей активное состояние Срочной доставки мгновенно заканчивается.\n\n«Быстрее. Быстрее! Ещё быстрее!»","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 96.2 %*2+507.6 % · 2: 103.9 %*2+548.2 % · 3: 112.2 %*2+592.1 % · 4: 121.2 %*2+639.4 % · 5: 130.9 %*2+690.6 % · 6: 141.3 %*2+745.8 % · 7: 152.7 %*2+805.5 % · 8: 164.9 %*2+869.9 % · 9: 178.1 %*2+939.5 % · 10: 192.3 %*2+1014.7 % · 11: 207.7 %*2+1095.9 % · 12: 224.3 %*2+1183.5 % · 13: 242.2 %*2+1278.2 %"}]},{"id":"GA_Hathor_Passive_2","name":"Повышение эффективности","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/d4dc0e37b6be3f41a033.webp","description":"Даёт 1 уровень Силы экспресс-доставки после победы над целью.\n\nЯ могу быстрее.","attributes":[]},{"id":"GA_Hathor_QTE","name":"Выбор точки воздействия","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/1a96f9983c544a8d2b5e.webp","description":"Время пришло. Наносит удар с воздуха, отбрасывая цель для создания взрывного импульса, и наносит 2 удара урона лакшаны по области.\n\nПрямо сейчас.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 63.9 %+136.1 % · 2: 69 %+147 % · 3: 74.5 %+158.7 % · 4: 80.5 %+171.4 % · 5: 86.9 %+185.2 % · 6: 93.9 %+200 % · 7: 101.4 %+216 % · 8: 109.5 %+233.3 % · 9: 118.3 %+251.9 % · 10: 127.7 %+272.1 % · 11: 138 %+293.8 % · 12: 149 %+317.3 % · 13: 160.9 %+342.7 %"}]},{"id":"GA_Hathor_Skill2","name":"Навык перенаправления: Удар циклона","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/9c2a472ffa626f39f396.webp","description":"Навык перенаправления: Воздушное командование\nЦель на мушке. Пора заканчивать. Совершает атаку в прыжке и, находясь в воздухе, использует крылья для удара по целям перед собой. После применения получает 2 ур. Силы экспресс-доставки.\n\nУдерживайте для перехода в состояние зарядки, которое усиливает мощность навыка «Воздушное командование» и накладывает на все цели в области действия эффект «Пятизвездочное отслеживание». Зарядка длится до 5 сек. В это время Хатор непрерывно наносит урон лакшаны по области, которая постепенно расширяется. Отпустите кнопку навыка, чтобы завершить зарядку.\n\n«Пятизвездочное отслеживание»\n\nДействует 5 сек. Если пораженная цель атакует Хатор или союзника либо попадает по ним, Хатор получит 3 ур. Силы экспресс-доставки.\n\nНавык перенаправления: Удар циклона\nНаходясь в состоянии Срочной доставки, тратит силу экспресс-доставки для использования этого навыка. Призывает мотоцикл из шипов и проводит серию быстрых комбо-атак по цели. Пока навык активен, увеличивает ЗЩТ.\n\nЧтобы обеспечить доставку в срок, одним из основных принципов работы является принудительное уничтожение врагов на пути.","attributes":[{"id":"parameter-12","label":"Увеличивает ЗЩТ во время «Удара циклона».","value":"1 %"}]},{"id":"GA_Hathor_Skill","name":"Воздушное командование","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/5d469bc89061e9d88752.webp","description":"Навык перенаправления: Воздушное командование\nЦель на мушке. Пора заканчивать. Совершает атаку в прыжке и, находясь в воздухе, использует крылья для удара по целям перед собой. После применения получает 2 ур. Силы экспресс-доставки.\n\nУдерживайте для перехода в состояние зарядки, которое усиливает мощность навыка «Воздушное командование» и накладывает на все цели в области действия эффект «Пятизвездочное отслеживание». Зарядка длится до 5 сек. В это время Хатор непрерывно наносит урон лакшаны по области, которая постепенно расширяется. Отпустите кнопку навыка, чтобы завершить зарядку.\n\n«Пятизвездочное отслеживание»\n\nДействует 5 сек. Если пораженная цель атакует Хатор или союзника либо попадает по ним, Хатор получит 3 ур. Силы экспресс-доставки.\n\nНавык перенаправления: Удар циклона\nНаходясь в состоянии Срочной доставки, тратит силу экспресс-доставки для использования этого навыка. Призывает мотоцикл из шипов и проводит серию быстрых комбо-атак по цели. Пока навык активен, увеличивает ЗЩТ.\n\nЧтобы обеспечить доставку в срок, одним из основных принципов работы является принудительное уничтожение врагов на пути.","attributes":[{"id":"parameter-0","label":"Множитель «Воздушного командования» при нажатии","value":"1: 100 %*2+100 % · 2: 108 %*2+108 % · 3: 116.6 %*2+116.6 % · 4: 126 %*2+126 % · 5: 136 %*2+136 % · 6: 146.9 %*2+146.9 % · 7: 158.7 %*2+158.7 % · 8: 171.4 %*2+171.4 % · 9: 185.1 %*2+185.1 % · 10: 199.9 %*2+199.9 % · 11: 215.9 %*2+215.9 % · 12: 233.2 %*2+233.2 % · 13: 251.8 %*2+251.8 %"},{"id":"parameter-1","label":"Множитель «Воздушного командования» при удержании","value":"1: 10.2 % *4 + 122.5 % + 55.2 % *5 · 2: 11 % *4 + 132.3 % + 59.6 % *5 · 3: 11.9 % *4 + 142.9 % + 64.4 % *5 · 4: 12.8 % *4 + 154.3 % + 69.5 % *5 · 5: 13.9 % *4 + 166.7 % + 75.1 % *5 · 6: 15 % *4 + 180 % + 81.1 % *5 · 7: 16.2 % *4 + 194.4 % + 87.6 % *5 · 8: 17.5 % *4 + 209.9 % + 94.6 % *5 · 9: 18.9 % *4 + 226.7 % + 102.2 % *5 · 10: 20.4 % *4 + 244.9 % + 110.3 % *5 · 11: 22 % *4 + 264.5 % + 119.2 % *5 · 12: 23.8 % *4 + 285.6 % + 128.7 % *5 · 13: 25.7 % *4 + 308.5 % + 139 % *5"},{"id":"parameter-2","label":"Множитель периодического урона","value":"1: Каждый удар: 55.6 % · 2: Каждый удар: 60 % · 3: Каждый удар: 64.9 % · 4: Каждый удар: 70 % · 5: Каждый удар: 75.6 % · 6: Каждый удар: 81.7 % · 7: Каждый удар: 88.2 % · 8: Каждый удар: 95.3 % · 9: Каждый удар: 102.9 % · 10: Каждый удар: 111.1 % · 11: Каждый удар: 120 % · 12: Каждый удар: 129.6 % · 13: Каждый удар: 140 %"},{"id":"parameter-3","label":"Макс. время зарядки","value":"4.5 сек."},{"id":"parameter-6","label":"Множитель 1-го удара Удара циклона","value":"1: 42.9 %*7 · 2: 46.3 %*7 · 3: 50 %*7 · 4: 54 %*7 · 5: 58.4 %*7 · 6: 63 %*7 · 7: 68.1 %*7 · 8: 73.5 %*7 · 9: 79.4 %*7 · 10: 85.8 %*7 · 11: 92.6 %*7 · 12: 100 %*7 · 13: 108 %*7"},{"id":"parameter-7","label":"Множитель 2-го удара Удара циклона","value":"1: 143.2 %+113.6 %+143.2 % · 2: 154.7 %+122.7 %+154.7 % · 3: 167 %+132.5 %+167 % · 4: 180.4 %+143.1 %+180.4 % · 5: 194.8 %+154.6 %+194.8 % · 6: 210.4 %+166.9 %+210.4 % · 7: 227.2 %+180.3 %+227.2 % · 8: 245.4 %+194.7 %+245.4 % · 9: 265.1 %+210.3 %+265.1 % · 10: 286.3 %+227.1 %+286.3 % · 11: 309.2 %+245.3 %+309.2 % · 12: 333.9 %+264.9 %+333.9 % · 13: 360.6 %+286.1 %+360.6 %"},{"id":"parameter-8","label":"Множитель 3-го удара Удара циклона","value":"1: 196.9 %+353.1 % · 2: 212.7 %+381.3 % · 3: 229.7 %+411.9 % · 4: 248 %+444.8 % · 5: 267.9 %+480.4 % · 6: 289.3 %+518.8 % · 7: 312.5 %+560.3 % · 8: 337.5 %+605.2 % · 9: 364.4 %+653.6 % · 10: 393.6 %+705.8 % · 11: 425.1 %+762.3 % · 12: 459.1 %+823.3 % · 13: 495.8 %+889.2 %"},{"id":"parameter-12","label":"Увеличивает ЗЩТ во время «Удара циклона».","value":"100 %"}]},{"id":"GA_Hathor_Passive_1","name":"Предупреждение о задержке","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/8fc3069bc24879aaf635.webp","description":"Усиление реморы: увеличивает длительность эффекта «Ремора» на цели до 12 сек. и повышает шанс крит. удара всех участников отряда на 10 %, когда они атакуют цель под действием «Реморы».\n\nЗадержек быть не должно. Я этим займусь.","attributes":[]},{"id":"GA_Hathor_Passive_3","name":"Блокировка отличного рейтинга","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/dd8db8594b7821e15b2a.webp","description":"Когда Хатор в команде, а враги остаются рядом более 5 сек., срабатывает Блокировка отличного рейтинга.\n\nБлокировка отличного рейтинга: после активации длится 5 сек. Если пораженная цель сама атакует вашу команду, Блокировка отличного рейтинга снимается, а Хатор получает 1 уровень Силы экспресс-доставки (максимум 6 уровней).\n\nНужно справляться со всеми рисками, чтобы результат был идеальным.","attributes":[]},{"id":"GA_Hathor_Melee","name":"Быстрая доставка","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/7094eaf4a96a669826db.webp","description":"Базовая атака: Быстрая доставка\nДемонстрирует выдающееся мастерство боевых искусств, чтобы провести до 5 последовательных атак, нанося урон лакшаны.\n\nБазовая атака: Последняя отправка\nПикирует, нанося 1 удар урона лакшаны по области при ударе. Урон увеличивается в зависимости от высоты падения (до 100 %).\n\nБазовая атака: В небеса\nУдерживайте базовую атаку, чтобы активировать. Стремительно кружит вокруг цели, чтобы подбросить её в воздух, затем сковывает её и пикирует, нанося 1 удар урона лакшаны по области при ударе. Если цель невосприимчива к подбрасыванию, вместо этого выполняет Последнюю отправку.\n\nКритический контрудар: Работа без ошибок\nСрабатывает при использовании Быстрой доставки после критического уклонения. Совершает молниеносную контратаку, нанося 1 удар урона лакшаны по области, снижая шкалу разрушения и получая Силу экспресс-доставки при попадании (не чаще 1 раза в 5 сек.).\n\nЛегенды рассказывают о тайном искусстве, которым владеют только элитные курьеры, выполнившие десятки тысяч безупречных доставок. Нанося удары в почти инстинктивном ритме, они прорываются через любые препятствия на своем пути, чтобы выполнить очередную успешную доставку, не нарушая обещаний и не подрывая доверия клиентов.","attributes":[{"id":"parameter-0","label":"Множитель 1-го удара","value":"1: 24.3 % · 2: 26.2 % · 3: 28.3 % · 4: 30.6 % · 5: 33.1 % · 6: 35.7 % · 7: 38.6 % · 8: 41.6 % · 9: 45 % · 10: 48.6 % · 11: 52.5 % · 12: 56.7 % · 13: 61.2 %"},{"id":"parameter-1","label":"Множитель 2-го удара","value":"1: 16.1 %+13.6 %*4 · 2: 17.4 %+14.7 %*4 · 3: 18.8 %+15.9 %*4 · 4: 20.3 %+17.1 %*4 · 5: 21.9 %+18.5 %*4 · 6: 23.7 %+20 %*4 · 7: 25.5 %+21.6 %*4 · 8: 27.6 %+23.3 %*4 · 9: 29.8 %+25.2 %*4 · 10: 32.2 %+27.2 %*4 · 11: 34.8 %+29.4 %*4 · 12: 37.5 %+31.7 %*4 · 13: 40.5 %+34.2 %*4"},{"id":"parameter-2","label":"Множитель 3-го удара","value":"1: 13.3 %*2 · 2: 14.4 %*2 · 3: 15.5 %*2 · 4: 16.8 %*2 · 5: 18.1 %*2 · 6: 19.5 %*2 · 7: 21.1 %*2 · 8: 22.8 %*2 · 9: 24.6 %*2 · 10: 26.6 %*2 · 11: 28.7 %*2 · 12: 31 %*2 · 13: 33.5 %*2"},{"id":"parameter-3","label":"Множитель 4-го удара","value":"1: 22.4 %+47.9 %+99.4 % · 2: 24.2 %+51.7 %+107.4 % · 3: 26.1 %+55.9 %+115.9 % · 4: 28.2 %+60.3 %+125.2 % · 5: 30.5 %+65.2 %+135.2 % · 6: 32.9 %+70.4 %+146.1 % · 7: 35.5 %+76 %+157.7 % · 8: 38.4 %+82.1 %+170.4 % · 9: 41.5 %+88.7 %+184 % · 10: 44.8 %+95.8 %+198.7 % · 11: 48.4 %+103.4 %+214.6 % · 12: 52.2 %+111.7 %+231.8 % · 13: 56.4 %+120.6 %+250.3 %"},{"id":"parameter-4","label":"Множитель 5-го удара","value":"1: 44.1 %+109.9 % · 2: 47.6 %+118.7 % · 3: 51.4 %+128.2 % · 4: 55.6 %+138.4 % · 5: 60 %+149.5 % · 6: 64.8 %+161.5 % · 7: 70 %+174.4 % · 8: 75.6 %+188.3 % · 9: 81.6 %+203.4 % · 10: 88.2 %+219.7 % · 11: 95.2 %+237.3 % · 12: 102.8 %+256.2 % · 13: 111.1 %+276.7 %"},{"id":"parameter-5","label":"Множитель урона атаки в падении","value":"1: 125 % · 2: 135 % · 3: 145.8 % · 4: 157.5 % · 5: 170.1 % · 6: 183.7 % · 7: 198.4 % · 8: 214.2 % · 9: 231.4 % · 10: 249.9 % · 11: 269.9 % · 12: 291.5 % · 13: 314.8 %"},{"id":"parameter-6","label":"Множитель урона последующей атаки","value":"1: 240 % · 2: 259.2 % · 3: 279.9 % · 4: 302.3 % · 5: 326.5 % · 6: 352.6 % · 7: 380.8 % · 8: 411.3 % · 9: 444.2 % · 10: 479.8 % · 11: 518.1 % · 12: 559.6 % · 13: 604.4 %"},{"id":"parameter-8","label":"Множитель критического контрудара","value":"1: 68 %+130 % · 2: 73.4 %+140.4 % · 3: 79.3 %+151.6 % · 4: 85.7 %+163.8 % · 5: 92.5 %+176.9 % · 6: 99.9 %+191 % · 7: 107.9 %+206.3 % · 8: 116.5 %+222.8 % · 9: 125.9 %+240.6 % · 10: 135.9 %+259.9 % · 11: 146.8 %+280.7 % · 12: 158.6 %+303.1 % · 13: 171.2 %+327.4 %"}]},{"id":"City_Ability_Hathor_01","name":"Элитный курьер","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/2dd9891caf1e38746a9c.webp","description":"Увеличивает количество пунктов доставки в городской доставке на 2 в день.","attributes":[{"id":"city-0","label":"Уровень 1","value":"Увеличивает количество пунктов доставки в городской доставке на 2 в день."},{"id":"city-1","label":"Уровень 2","value":"Повышает удовлетворенность клиентов городской доставки ещё на 10 очков."},{"id":"city-2","label":"Уровень 3","value":"Увеличивает количество пунктов доставки в городской доставке на 2 в день."},{"id":"city-3","label":"Уровень 4","value":"Повышает удовлетворенность клиентов городской доставки ещё на 10 очков."},{"id":"city-4","label":"Уровень 5","value":"Хатор может помочь выполнить 1 городскую доставку в день напрямую и получить награду."}]},{"id":"City_Ability_Hathor_02","name":"Забор отправлений","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/4cddd355f22b094ab0dd.webp","description":"Описание требует проверки в игре.","attributes":[{"id":"city-0","label":"Уровень 1","value":"「粉爪大劫案」中哈索尔有x %的概率回收掉落物品。"},{"id":"city-1","label":"Уровень 2","value":"「粉爪大劫案」中哈索尔被监控附电灵发现所需的时间增加x %。"},{"id":"city-2","label":"Уровень 3","value":"「粉爪大劫案」中哈索尔回收掉落物品的概率增加x %。"},{"id":"city-3","label":"Уровень 4","value":"「粉爪大劫案」中哈索尔被监控附电灵发现所需的时间增加x %。"},{"id":"city-4","label":"Уровень 5","value":"「粉爪大劫案」中哈索尔回收掉落物品的概率增加x %。"}]}]') WHERE character_id='hathor' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:08:06');

