UPDATE character_profiles SET materials_json=json('[{"id":"hotori-lost-whispers","name":"Потерянный шёпот","iconUrl":"/nte-meta/game-assets/bf3dee55c5620981128e.webp","amount":"×17","source":"Материалы прорыва до ур. 80; источник: GameWith RU."},{"id":"gold","name":"Фонсы","iconUrl":"","amount":"525000","source":"Уровень возвышения → количество: 30: 25000 · 40: 50000 · 50: 75000 · 60: 100000 · 70: 125000 · 80: 150000"},{"id":"hotori-confessional-flower-seed","name":"Семя исповедального цветка","iconUrl":"/nte-meta/game-assets/7b3c91c8cf6dbe55afc1.webp","amount":"×86","source":"Материалы прорыва до ур. 80; источник: GameWith RU."},{"id":"hotori-obscure-whispers","name":"Неясный шёпот","iconUrl":"/nte-meta/game-assets/1f31f59c21f38ae44a9e.webp","amount":"×18","source":"Материалы прорыва до ур. 80; источник: GameWith RU."},{"id":"hotori-paradoxical-whispers","name":"Парадоксальный шёпот","iconUrl":"/nte-meta/game-assets/bceebcbdfa15a83f4707.webp","amount":"×15","source":"Материалы прорыва до ур. 80; источник: GameWith RU."}]') WHERE character_id='hotori' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-23 13:53:58');

