UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Красочный финт","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1052_1.png","description":"Увеличивает урон Хотори во время остановки времени на 12 % за каждый записанный навык поддержки или навык перенаправления."},{"level":2,"kind":"awakening","name":"Далекие воспоминания","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1052_2.png","description":"Во время остановки времени Хотори наносит на 20 % больше урона."},{"level":3,"kind":"awakening","name":"Мгновенный взгляд","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1052_3.png","description":"Восстанавливает энергию, затраченную на Настоящее воспроизведение, после использования навыка и завершения записи. Запускается не чаще одного раза в 60 сек. Восстановление энергии прерывается, если вы расходуете энергию во время процесса."},{"level":4,"kind":"awakening","name":"Разрозненные реликвии","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1052_4.png","description":"Дополнительно дает 10 ед. энергии Незакрытым часам за каждую 1 цель в то время, пока стрелка часов не идет назад; максимум 3 раза. Применение Мирового прилива сбрасывает счетчик."},{"level":5,"kind":"awakening","name":"Всевидение","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1052_5.png","description":"Когда Хотори в команде, если на поле есть только 1 враг, урон всей команды по этой цели увеличивается на 15 %. Этот эффект теряется, если Хотори терпит поражение."},{"level":6,"kind":"awakening","name":"Время все забирает","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1052_6.png","description":"Во время остановки времени Хотори игнорирует 30 % от защита цели."},{"level":3,"kind":"resonance","name":"Разбитая вечность","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень навыков «Лунный стиль Мисти», «Настоящее воспроизведение» и «Мировой прилив» на 1."},{"level":6,"kind":"resonance","name":"Величайшее сокровище ясного понимания","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Когда Хотори в команде и жива, даёт всем членам команды 30 % к атаке."}]') WHERE character_id='hotori' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-23 13:53:58');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"en-Play_Vo_Char_NPC009_anomaly_004","title":"Нуллификация II","description":"Ещё одно задание выполнено.","language":"Английский","audioUrl":"/nte-meta/game-audio/bc44ecb52607d7c540de.ogg"},{"id":"en-Play_Vo_Char_NPC009_self_002","title":"Обо мне: проницательность","description":"Я оценила бесчисленное множество редких артефактов через призму «времени». Чтобы управлять антикварным магазином, нужен наметанный глаз… Что? В последнее время я часто ошибаюсь? Хм-м… Может, потому что Прелесть так надежна, и я чересчур расслабилась…","language":"Английский","audioUrl":"/nte-meta/game-audio/add18edc54d5ce156c49.ogg"},{"id":"ja-Play_Vo_Char_NPC009_DodgeCombo_001","title":"Серия критических уклонений I","description":"Я вижу все твои уловки насквозь!","language":"Японский","audioUrl":"/nte-meta/game-audio/97643ec1995e18ae4b56.ogg"},{"id":"ja-Play_Vo_Char_NPC009_SSC_002","title":"Особое переключение II — Адлер","description":"Помоги мне приглядеть за малышами.","language":"Японский","audioUrl":"/nte-meta/game-audio/e24f00854562cf459396.ogg"},{"id":"ja-Play_Vo_Char_NPC009_SSC_003","title":"Особое переключение I — Сакири","description":"Только смотри, не спускай глаз с Кирумару!","language":"Японский","audioUrl":"/nte-meta/game-audio/80fe0dfd5dbf3a4a2d2d.ogg"},{"id":"ja-Play_Vo_Char_NPC009_weather_003","title":"Холодно","description":"В этом городе не так уж плохо даже в холодный сезон… и снег идет редко. Честно говоря, иногда я немного скучаю по дому.","language":"Японский","audioUrl":"/nte-meta/game-audio/f72bc58e047ff0d24287.ogg"},{"id":"ja-Play_Vo_Char_NPC009_windfall_006","title":"Неожиданная добыча VI","description":"Сегодня мне здорово везет!","language":"Японский","audioUrl":"/nte-meta/game-audio/4eb318b8915d244f073c.ogg"},{"id":"en-Play_Vo_Char_NPC009_fh_001","title":"Исцеление I","description":"Как хорошее вино.","language":"Английский","audioUrl":"/nte-meta/game-audio/68ad3f9d65fb2cf2a084.ogg"},{"id":"ja-Play_Vo_Char_NPC009_Switch_001","title":"Переключение I","description":"А вот и я!","language":"Японский","audioUrl":"/nte-meta/game-audio/5470537e6f29f902144a.ogg"},{"id":"en-Play_Vo_Char_NPC009_SSC_011","title":"Особое переключение I — Ноль","description":"Не тронь мою прелесть!","language":"Английский","audioUrl":"/nte-meta/game-audio/46f948cd4227b68b48df.ogg"},{"id":"en-Play_Vo_Char_NPC009_windfall_002","title":"Неожиданная добыча II","description":"Как по мне, это подлинная вещь…","language":"Английский","audioUrl":"/nte-meta/game-audio/1ce5eb4f257005e083ef.ogg"},{"id":"en-Play_Vo_Char_NPC009_aoe_UI_005","title":"Сверхспособность V","description":"Луна зашла.","language":"Английский","audioUrl":"/nte-meta/game-audio/c8d242d0198451a22711.ogg"},{"id":"en-Play_Vo_Char_NPC009_hp_001","title":"Низкий уровень здоровья I","description":"Всему свое время и место…","language":"Английский","audioUrl":"/nte-meta/game-audio/0e7175e05c3d40771636.ogg"},{"id":"en-Play_Vo_Char_NPC009_SSC_003","title":"Особое переключение I — Сакири","description":"Только смотри, не спускай глаз с Кирумару!","language":"Английский","audioUrl":"/nte-meta/game-audio/ea4d6d7095d60010f7a8.ogg"},{"id":"en-Play_Vo_Char_NPC009_kill_002","title":"Убийство II","description":"Увидимся.","language":"Английский","audioUrl":"/nte-meta/game-audio/8c1d31d2d4cf8638300c.ogg"},{"id":"en-Play_Vo_Char_NPC009_Parry_001","title":"Парирование I","description":"Не хватает мощности!","language":"Английский","audioUrl":"/nte-meta/game-audio/939d9c15b6d0861a0219.ogg"},{"id":"ja-Play_Vo_Char_NPC009_SSC_009","title":"Особое переключение I — Эдгар","description":"Давай поскорее с этим закончим.","language":"Японский","audioUrl":"/nte-meta/game-audio/00e73944eb7d9664a5fe.ogg"},{"id":"ja-Play_Vo_Char_NPC009_weather_002","title":"Дождливо","description":"Под шум дождя… У меня родилась отличная идея… Наш двор кажется пустоватым, может, сделаем в нем пруд с карпами?","language":"Японский","audioUrl":"/nte-meta/game-audio/613fbbf2f25033b1e5ff.ogg"},{"id":"en-Play_Vo_Char_NPC009_about_004","title":"О Тайгедо","description":"Когда я нашла Тайгедо, то пришла в полный восторг. Думала, смогу сэкономить на покупке ТВ. Но теперь дети захватили его, смотрят аниме и все такое… Эх. Однажды, когда разбогатею, куплю телевизор во всю стену.","language":"Английский","audioUrl":"/nte-meta/game-audio/d8c4a626f82ecb058eb3.ogg"},{"id":"en-Play_Vo_Char_NPC009_ug_002","title":"Вознесение персонажа II","description":"Тратить нужно с умом. Адлер, принеси мне ту бутылку, что я хранила!","language":"Английский","audioUrl":"/nte-meta/game-audio/471a23acdd1051dcbbaa.ogg"},{"id":"ja-Play_Vo_Char_NPC009_containment_001","title":"Сдерживание I","description":"Посмотрим… чего это стоит?","language":"Японский","audioUrl":"/nte-meta/game-audio/0e70d3087e3b5d900261.ogg"},{"id":"ja-Play_Vo_Char_NPC009_DodgeCombo_002","title":"Серия критических уклонений II","description":"Тебе правда нужно больше практики.","language":"Японский","audioUrl":"/nte-meta/game-audio/9d363fd8c18c324f5a6e.ogg"},{"id":"ja-Play_Vo_Char_NPC009_TeammateDown_004","title":"Поражен товарищ по команде – Даффодил","description":"Спи, моя маленькая Дафф…","language":"Японский","audioUrl":"/nte-meta/game-audio/4304400b8df2a5b5db97.ogg"},{"id":"en-Play_Vo_Char_NPC009_talk_002","title":"Тема: руководство по сделкам","description":"В торговых условиях «Эйбона» есть несколько строк, о которых не следует сообщать клиентам… Да, знаю. Когда я писала их впервые, я просто изливала на бумагу то, что чувствовала… Всё же торговля подразумевает честность, разве не так? Если что-то кажется неуместным, просто зачеркни, прежде чем показывать клиенту. Перепечатывать не нужно. Типографии в наши дни — форменный грабеж… Таким магазинчикам, как «Эйбон», трудно выжить в этом враждебном мире…","language":"Английский","audioUrl":"/nte-meta/game-audio/e04df7981b11e0bc5a83.ogg"},{"id":"ja-Play_Vo_Char_NPC009_about_002","title":"О Даффодил","description":"Дафф сама по себе почти не пьет, но если поднять бокал и пригласить её присоединиться, её уже не остановить. Я как-то сказала ей — после тоста нужно выпить хотя бы полбокала, это базовый этикет. Хе-хе… а потом… начинается веселье. Она отнюдь не такая стойкая, как считает.","language":"Японский","audioUrl":"/nte-meta/game-audio/a287b5e212f9170c7743.ogg"},{"id":"ja-Play_Vo_Char_NPC009_SSC_005","title":"Особое переключение I — Наналли","description":"Ну и забот с тобой…","language":"Японский","audioUrl":"/nte-meta/game-audio/2c8f00a311dfb244f95e.ogg"},{"id":"ja-Play_Vo_Char_NPC009_struck_001","title":"Урон I","description":"Т-с.","language":"Японский","audioUrl":"/nte-meta/game-audio/fa6a87da1364a7fe8217.ogg"},{"id":"ja-Play_Vo_Char_NPC009_ug_003","title":"Вознесение персонажа III","description":"Возможно, «сейчас» самый памятный момент из всех… кто знает?","language":"Японский","audioUrl":"/nte-meta/game-audio/5c889e5a641883388380.ogg"},{"id":"ja-Play_Vo_Char_NPC009_windfall_004","title":"Неожиданная добыча IV","description":"Такое сокровище — и просто попало к тебе в руки?","language":"Японский","audioUrl":"/nte-meta/game-audio/f1d1c9f48d7ffd19282a.ogg"},{"id":"en-Play_Vo_Char_NPC009_greet_002","title":"Дневное приветствие","description":"Ах… самое сонное время дня. Я, пожалуй, отдохну в каком-нибудь прохладном месте.","language":"Английский","audioUrl":"/nte-meta/game-audio/db55de1cba8a85270172.ogg"},{"id":"en-Play_Vo_Char_NPC009_weather_002","title":"Дождливо","description":"Под шум дождя… У меня родилась отличная идея… Наш двор кажется пустоватым, может, сделаем в нем пруд с карпами?","language":"Английский","audioUrl":"/nte-meta/game-audio/9d7b56ef3634d3b05664.ogg"},{"id":"en-Play_Vo_Char_NPC009_skill_003","title":"Навык перенаправления III","description":"Есть ещё порох в пороховницах, да?","language":"Английский","audioUrl":"/nte-meta/game-audio/de0cb72a8b7663efb3fb.ogg"},{"id":"en-Play_Vo_Char_NPC009_SSC_005","title":"Особое переключение I — Наналли","description":"Ну и забот с тобой…","language":"Английский","audioUrl":"/nte-meta/game-audio/6b4e256ef39d044ddc51.ogg"},{"id":"en-Play_Vo_Char_NPC009_Switch_001","title":"Переключение I","description":"А вот и я!","language":"Английский","audioUrl":"/nte-meta/game-audio/d195aa87b22054b356f4.ogg"},{"id":"ja-Play_Vo_Char_NPC009_about_001","title":"Об Адлере","description":"Смотри, смотри, смотри… Видишь морщинки у Адлера вокруг глаз? Лезут, как грибы после дождя, с самого открытия. Мелкие хулиганки не представляют, как мы, взрослые, переживаем за них.","language":"Японский","audioUrl":"/nte-meta/game-audio/269a77a5cc3331c68186.ogg"},{"id":"ja-Play_Vo_Char_NPC009_Fly_001","title":"Планирование I","description":"Ладно, приступим!","language":"Японский","audioUrl":"/nte-meta/game-audio/78dd13786e2add8a74ca.ogg"},{"id":"ja-Play_Vo_Char_NPC009_self_001","title":"Обо мне: способности эспера","description":"«Время» — это не просто путь. Это ещё и… точка зрения.","language":"Японский","audioUrl":"/nte-meta/game-audio/fc8227c5ac3bd3619088.ogg"},{"id":"ja-Play_Vo_Char_NPC009_Switch_003","title":"Переключение III","description":"Не волнуйся, у нас полно времени.","language":"Японский","audioUrl":"/nte-meta/game-audio/ddee4580c256100ee3e5.ogg"},{"id":"en-Play_Vo_Char_NPC009_aoe_UI_003","title":"Сверхспособность III","description":"И так течет время.","language":"Английский","audioUrl":"/nte-meta/game-audio/e408f7c5e7c34c20c375.ogg"},{"id":"en-Play_Vo_Char_NPC009_Fly_002","title":"Планирование II","description":"Фух!","language":"Английский","audioUrl":"/nte-meta/game-audio/f3fa35a58c1a9e09bd42.ogg"},{"id":"en-Play_Vo_Char_NPC009_skill_001","title":"Навык перенаправления I","description":"Небольшая показуха.","language":"Английский","audioUrl":"/nte-meta/game-audio/2fd5bc15ce6cd746c83d.ogg"},{"id":"en-Play_Vo_Char_NPC009_weather_004","title":"Жарко","description":"Уф, ну и жара… Сообщи, когда будешь брать охлажденное саке, ладно? А то оно быстро нагреется.","language":"Английский","audioUrl":"/nte-meta/game-audio/8f75282a842fbc0e2ff4.ogg"},{"id":"ja-Play_Vo_Char_NPC009_about_008","title":"Об антикварном магазине Эйбон","description":"Следовало догадаться, что это никчемное место. Дешевая аренда завела меня в тупик — бизнесу конец! Так зачем было открывать «Эйбон» здесь? Хех, потому что такого понятия, как «следовало догадаться», не существует. Это судьба.","language":"Японский","audioUrl":"/nte-meta/game-audio/d503d8009a21f6989f0d.ogg"},{"id":"ja-Play_Vo_Char_NPC009_chat_002","title":"Чат: фонсы","description":"Фонс, фонс, фонс… Кто придумал это название? Чем больше произношу его, тем лучше оно звучит… «Фонс»… какое прекрасное слово.","language":"Японский","audioUrl":"/nte-meta/game-audio/c1fc3e062e01cb2bcb4a.ogg"},{"id":"en-Play_Vo_Char_NPC009_DodgeCombo_002","title":"Серия критических уклонений II","description":"Тебе правда нужно больше практики.","language":"Английский","audioUrl":"/nte-meta/game-audio/8c62942792f8a719f0a7.ogg"},{"id":"en-Play_Vo_Char_NPC009_fh_002","title":"Исцеление II","description":"М-м-м… вот это хорошо.","language":"Английский","audioUrl":"/nte-meta/game-audio/d8c203517fa6d4b4d6c1.ogg"},{"id":"en-Play_Vo_Char_NPC009_SSC_001","title":"Особое переключение I — Адлер","description":"Отличная работа.","language":"Английский","audioUrl":"/nte-meta/game-audio/b45e3aa8f22203e32054.ogg"},{"id":"ja-Play_Vo_Char_NPC009_SSC_007","title":"Особое переключение I — Даффодил","description":"Просто держись позади меня.","language":"Японский","audioUrl":"/nte-meta/game-audio/7fb435449336c4e3c690.ogg"},{"id":"ja-Play_Vo_Char_NPC009_SSC_008","title":"Особое переключение II — Даффодил","description":"Давай я тебе помогу.","language":"Японский","audioUrl":"/nte-meta/game-audio/662a37985e058a6cb5ef.ogg"},{"id":"ja-Play_Vo_Char_NPC009_TeammateDown_002","title":"Поражен товарищ по команде – Сакири","description":"Видишь, что происходит, когда ты пытаешься показать крутость?","language":"Японский","audioUrl":"/nte-meta/game-audio/b8c7e1c68d9b75ceadea.ogg"},{"id":"en-Play_Vo_Char_NPC009_aoe_UI_006","title":"Сверхспособность VI","description":"Хех…","language":"Английский","audioUrl":"/nte-meta/game-audio/b24559de5b1e3b65e996.ogg"},{"id":"en-Play_Vo_Char_NPC009_containment_001","title":"Сдерживание I","description":"Посмотрим… чего это стоит?","language":"Английский","audioUrl":"/nte-meta/game-audio/ca68142517386f54f528.ogg"},{"id":"en-Play_Vo_Char_NPC009_gift_002","title":"Подарок получен II","description":"Это подлинник! Теперь у нас в коллекции ещё одно сокровище!","language":"Английский","audioUrl":"/nte-meta/game-audio/248fddb27015f022a855.ogg"},{"id":"ja-Play_Vo_Char_NPC009_about_005","title":"О Наналли","description":"Наналли! Что ты опять сломала?! Почему счета за твои проделки приходят мне без предупреждения?!.. Куда делась эта мелкая негодница… Т-с, Адлер! Слушай, месяц.. арг-х, может, неделя! Никаких яичных рулетов для нее. Может в этот раз запомнит… И не подсовывай ей их тайком!","language":"Японский","audioUrl":"/nte-meta/game-audio/d15fb7adc0bd194fb781.ogg"},{"id":"ja-Play_Vo_Char_NPC009_about_006","title":"Об Эдгаре","description":"Эдгар — такой тихий и послушный мальчик. Любит книги, не требует многого. Как его родителям удалось так хорошо его воспитать? Нужно взять на заметку…","language":"Японский","audioUrl":"/nte-meta/game-audio/872c26abd3a0404578ab.ogg"},{"id":"ja-Play_Vo_Char_NPC009_self_002","title":"Обо мне: проницательность","description":"Я оценила бесчисленное множество редких артефактов через призму «времени». Чтобы управлять антикварным магазином, нужен наметанный глаз… Что? В последнее время я часто ошибаюсь? Хм-м… Может, потому что Прелесть так надежна, и я чересчур расслабилась…","language":"Японский","audioUrl":"/nte-meta/game-audio/2a8018ac40e4820b17ca.ogg"},{"id":"en-Play_Vo_Char_NPC009_deploy_001","title":"Отправка II","description":"Не могу позволить, чтобы с сотрудниками «Эйбона» обращались столь бесцеремонно.","language":"Английский","audioUrl":"/nte-meta/game-audio/920962c550cac1ef6491.ogg"},{"id":"ja-Play_Vo_Char_NPC009_aoe_UI_002","title":"Сверхспособность II","description":"Это место притягивает к себе приливы и отливы мира.","language":"Японский","audioUrl":"/nte-meta/game-audio/b7e4000bee0fe9ee4481.ogg"},{"id":"en-Play_Vo_Char_NPC009_hstruck_001","title":"Сильный урон I","description":"Совсем неплохо.","language":"Английский","audioUrl":"/nte-meta/game-audio/327d6b10a55c574b9b3d.ogg"},{"id":"en-Play_Vo_Char_NPC009_SSC_002","title":"Особое переключение II — Адлер","description":"Помоги мне приглядеть за малышами.","language":"Английский","audioUrl":"/nte-meta/game-audio/d2b1f0d8d5addc5b707b.ogg"},{"id":"en-Play_Vo_Char_NPC009_TeammateDown_005","title":"Поражен товарищ по команде – Эдгар","description":"Молодец, ты старался изо всех сил.","language":"Английский","audioUrl":"/nte-meta/game-audio/3c05bd3befa8ebbdf079.ogg"},{"id":"ja-Play_Vo_Char_NPC009_Parry_002","title":"Парирование II","description":"Мягкое прикосновение берет верх над силой.","language":"Японский","audioUrl":"/nte-meta/game-audio/514cf09db8235a129985.ogg"},{"id":"en-Play_Vo_Char_NPC009_about_003","title":"О Сакири","description":"Сакири — умница. У неё есть потенциал, когда-нибудь она сможет стать отличной хозяйкой магазина. Но эта привычка подрывать мой авторитет? Нужно будет как следует с этим разобраться…","language":"Английский","audioUrl":"/nte-meta/game-audio/6c5f00e02734f2ae3dcd.ogg"},{"id":"en-Play_Vo_Char_NPC009_gift_004","title":"Подарок получен IV","description":"Ну, мы же семья, да? Не стесняйся!","language":"Английский","audioUrl":"/nte-meta/game-audio/37e79882b2d964bbd621.ogg"},{"id":"ja-Play_Vo_Char_NPC009_talk_003","title":"Тема: договор о поручении","description":"Эй, Прелесть, помоги мне. Я подумываю о том, чтобы добавить в форму поручения новый пункт… что-то типа «В случае запроса оценки аномалии у нашего штатного оценщика взимается комиссия в размере 50 %». Что думаешь?.. Ты качаешь головой? Ладно — 80 %! Договорились! Эй, Прелесть, помоги мне. Я подумываю о том, чтобы добавить в форму поручения новый пункт… что-то типа «В случае запроса оценки аномалии у нашей штатной оценщицы взимается комиссия в размере 50 %». Что думаешь?.. Ты качаешь головой? Ладно — 80 %! Договорились!","language":"Японский","audioUrl":"/nte-meta/game-audio/2c0060479ba857b0cb4b.ogg"},{"id":"ja-Play_Vo_Char_NPC009_greet_001","title":"Утреннее приветствие","description":"Кто это?! Один из этих сопляков или Тайгедо?! Топает по лестнице среди ночи… Сегодня их ждет урок.","language":"Японский","audioUrl":"/nte-meta/game-audio/32b6ddd3983e18d0c5a0.ogg"},{"id":"ja-Play_Vo_Char_NPC009_TeammateDown_006","title":"Поражен товарищ по команде – Ноль","description":"Моя прелесть… Я отомщу за тебя!","language":"Японский","audioUrl":"/nte-meta/game-audio/7672adc2aa9adfb9e8df.ogg"},{"id":"ja-Play_Vo_Char_NPC009_ug_002","title":"Вознесение персонажа II","description":"Тратить нужно с умом. Адлер, принеси мне ту бутылку, что я хранила!","language":"Японский","audioUrl":"/nte-meta/game-audio/b55c09e9d12806354aff.ogg"},{"id":"ja-Play_Vo_Char_NPC009_vexation_001","title":"Проблемы","description":"Почему счет за коммуналку такой огромный… Эдгар, примени свою маленькую светлую голову и ещё раз проверь эти цифры… Что?! Коммерческие тарифы?! Т-с… столько лет, а я узнаю об этом лишь сейчас…","language":"Японский","audioUrl":"/nte-meta/game-audio/c6e9c81363e41cbcaa20.ogg"},{"id":"ja-Play_Vo_Char_NPC009_anomaly_003","title":"Нуллификация I","description":"Сойдет на время.","language":"Японский","audioUrl":"/nte-meta/game-audio/2472a15c39257b6fe3f3.ogg"},{"id":"ja-Play_Vo_Char_NPC009_aoe_UI_006","title":"Сверхспособность VI","description":"Хех…","language":"Японский","audioUrl":"/nte-meta/game-audio/e261af7daa50adbe063b.ogg"},{"id":"en-Play_Vo_Char_NPC009_dead_001","title":"Потеря сознания I","description":"Жаль… момент был неудачный…","language":"Английский","audioUrl":"/nte-meta/game-audio/6496d50b42811dda86ba.ogg"},{"id":"en-Play_Vo_Char_NPC009_SSC_004","title":"Особое переключение II — Сакири","description":"Сколько же от тебя шума!","language":"Английский","audioUrl":"/nte-meta/game-audio/9d319be7a34615f02d8b.ogg"},{"id":"en-Play_Vo_Char_NPC009_windfall_006","title":"Неожиданная добыча VI","description":"Сегодня мне здорово везет!","language":"Английский","audioUrl":"/nte-meta/game-audio/0e5ccd3d4af2cfd5b7c3.ogg"},{"id":"ja-Play_Vo_Char_NPC009_gift_001","title":"Подарок получен I","description":"Ого! Где ты это раздобыл? У тебя отличный вкус — мне очень нравится! Ого! Где ты это раздобыла? У тебя отличный вкус — мне очень нравится!","language":"Японский","audioUrl":"/nte-meta/game-audio/c7cbb43645af73d40bfc.ogg"},{"id":"ja-Play_Vo_Char_NPC009_greet_003","title":"Вечернее приветствие","description":"Сегодняшний доход… как, мы снова в минусе?","language":"Японский","audioUrl":"/nte-meta/game-audio/e23ecb9f0b09c931dfbe.ogg"},{"id":"ja-Play_Vo_Char_NPC009_QTE_003","title":"Атака на входе III","description":"Покажем им выход.","language":"Японский","audioUrl":"/nte-meta/game-audio/8654945a15f7ba791a7b.ogg"},{"id":"en-Play_Vo_Char_NPC009_Fly_001","title":"Планирование I","description":"Ладно, приступим!","language":"Английский","audioUrl":"/nte-meta/game-audio/9226a3f99797db102585.ogg"},{"id":"ja-Play_Vo_Char_NPC009_about_003","title":"О Сакири","description":"Сакири — умница. У неё есть потенциал, когда-нибудь она сможет стать отличной хозяйкой магазина. Но эта привычка подрывать мой авторитет? Нужно будет как следует с этим разобраться…","language":"Японский","audioUrl":"/nte-meta/game-audio/3facc4cf966ea5cd99b7.ogg"},{"id":"ja-Play_Vo_Char_NPC009_QTE_001","title":"Атака на входе I","description":"Как грубо.","language":"Японский","audioUrl":"/nte-meta/game-audio/9a044cc7df086d812b85.ogg"},{"id":"ja-Play_Vo_Char_NPC009_struck_002","title":"Урон II","description":"Ш-ш.","language":"Японский","audioUrl":"/nte-meta/game-audio/c8ad2ea7d777a300c00d.ogg"},{"id":"en-Play_Vo_Char_NPC009_SSC_010","title":"Особое переключение II — Эдгар","description":"Не нагружай себя слишком сильно.","language":"Английский","audioUrl":"/nte-meta/game-audio/04606d605ed141626ad4.ogg"},{"id":"en-Play_Vo_Char_NPC009_vexation_001","title":"Проблемы","description":"Почему счет за коммуналку такой огромный… Эдгар, примени свою маленькую светлую голову и ещё раз проверь эти цифры… Что?! Коммерческие тарифы?! Т-с… столько лет, а я узнаю об этом лишь сейчас…","language":"Английский","audioUrl":"/nte-meta/game-audio/e803522e4f80d93ef38e.ogg"},{"id":"ja-Play_Vo_Char_NPC009_dead_002","title":"Потеря сознания II","description":"Настал… мой час…","language":"Японский","audioUrl":"/nte-meta/game-audio/5e080c1e96520a6827c7.ogg"},{"id":"en-Play_Vo_Char_NPC009_gift_003","title":"Подарок получен III","description":"Прелесть, ты и правда очень стараешься… Я это ценю!","language":"Английский","audioUrl":"/nte-meta/game-audio/37c3230a261585c2695e.ogg"},{"id":"en-Play_Vo_Char_NPC009_hstruck_002","title":"Сильный урон II","description":"Как банально.","language":"Английский","audioUrl":"/nte-meta/game-audio/a60d419c2f0132a07099.ogg"},{"id":"en-Play_Vo_Char_NPC009_meet_001","title":"Первая встреча","description":"Новое лицо… Гость…? Погоди… это моя прелесть?! Ах… так голова кружится, не могу разобрать… нужно принять лекарство от похмелья…Новое лицо… Гостья…? Погоди… это моя прелесть?! Ах… так голова кружится, не могу разобрать… нужно принять лекарство от похмелья…","language":"Английский","audioUrl":"/nte-meta/game-audio/b9d582ae7ecea5839741.ogg"},{"id":"ja-Play_Vo_Char_NPC009_meet_001","title":"Первая встреча","description":"Новое лицо… Гость…? Погоди… это моя прелесть?! Ах… так голова кружится, не могу разобрать… нужно принять лекарство от похмелья…Новое лицо… Гостья…? Погоди… это моя прелесть?! Ах… так голова кружится, не могу разобрать… нужно принять лекарство от похмелья…","language":"Японский","audioUrl":"/nte-meta/game-audio/a6034f924c14f63e6287.ogg"},{"id":"ja-Play_Vo_Char_NPC009_skill_002","title":"Навык перенаправления II","description":"Дай взглянуть поближе.","language":"Японский","audioUrl":"/nte-meta/game-audio/b325d54aa30fba6991a9.ogg"},{"id":"en-Play_Vo_Char_NPC009_greet_001","title":"Утреннее приветствие","description":"Кто это?! Один из этих сопляков или Тайгедо?! Топает по лестнице среди ночи… Сегодня их ждет урок.","language":"Английский","audioUrl":"/nte-meta/game-audio/e1dfa5f810efb9a08aca.ogg"},{"id":"en-Play_Vo_Char_NPC009_hp_003","title":"Низкий уровень здоровья III","description":"Выпей что-нибудь, чтобы немного согреться…","language":"Английский","audioUrl":"/nte-meta/game-audio/b19bde644cb6edabd536.ogg"},{"id":"en-Play_Vo_Char_NPC009_kill_001","title":"Убийство I","description":"Теперь ведешь себя, как следует?","language":"Английский","audioUrl":"/nte-meta/game-audio/191062b36860bb25a4a4.ogg"},{"id":"en-Play_Vo_Char_NPC009_Switch_003","title":"Переключение III","description":"Не волнуйся, у нас полно времени.","language":"Английский","audioUrl":"/nte-meta/game-audio/5002a028ef9bc799be3f.ogg"},{"id":"ja-Play_Vo_Char_NPC009_aoe_UI_003","title":"Сверхспособность III","description":"И так течет время.","language":"Японский","audioUrl":"/nte-meta/game-audio/3f8309f01fee06955599.ogg"},{"id":"ja-Play_Vo_Char_NPC009_hp_002","title":"Низкий уровень здоровья II","description":"Бесит. Цена по-прежнему слишком низкая.","language":"Японский","audioUrl":"/nte-meta/game-audio/79a96bcc42f1e2a1b760.ogg"},{"id":"ja-Play_Vo_Char_NPC009_TeammateDown_003","title":"Поражен товарищ по команде – Наналли","description":"Тебе ещё предстоит пройти долгий путь.","language":"Японский","audioUrl":"/nte-meta/game-audio/c811890c4b5117e7adf9.ogg"},{"id":"ja-Play_Vo_Char_NPC009_SSC_001","title":"Особое переключение I — Адлер","description":"Отличная работа.","language":"Японский","audioUrl":"/nte-meta/game-audio/14e6726baa7d86ddb91b.ogg"},{"id":"en-Play_Vo_Char_NPC009_aoe_UI_004","title":"Сверхспособность IV","description":"Уже прибываю.","language":"Английский","audioUrl":"/nte-meta/game-audio/46eb9cd16d57734a335d.ogg"},{"id":"ja-Play_Vo_Char_NPC009_dead_001","title":"Потеря сознания I","description":"Жаль… момент был неудачный…","language":"Японский","audioUrl":"/nte-meta/game-audio/031258b3eb06197a9ef5.ogg"},{"id":"ja-Play_Vo_Char_NPC009_deploy_002","title":"Отправка I","description":"Время вернуть себе репутацию… и немного размяться.","language":"Японский","audioUrl":"/nte-meta/game-audio/ce2028e790c53b65ac3c.ogg"},{"id":"ja-Play_Vo_Char_NPC009_gift_004","title":"Подарок получен IV","description":"Ну, мы же семья, да? Не стесняйся!","language":"Японский","audioUrl":"/nte-meta/game-audio/9b9477f5ff233ba0bb1d.ogg"},{"id":"en-Play_Vo_Char_NPC009_TeammateDown_006","title":"Поражен товарищ по команде – Ноль","description":"Моя прелесть… Я отомщу за тебя!","language":"Английский","audioUrl":"/nte-meta/game-audio/0a76a4a742815b3443a6.ogg"},{"id":"en-Play_Vo_Char_NPC009_windfall_003","title":"Неожиданная добыча III","description":"Игнорировать выгодную сделку? Это просто хамство.","language":"Английский","audioUrl":"/nte-meta/game-audio/6335113a6d86e5a4e19a.ogg"},{"id":"ja-Play_Vo_Char_NPC009_about_004","title":"О Тайгедо","description":"Когда я нашла Тайгедо, то пришла в полный восторг. Думала, смогу сэкономить на покупке ТВ. Но теперь дети захватили его, смотрят аниме и все такое… Эх. Однажды, когда разбогатею, куплю телевизор во всю стену.","language":"Японский","audioUrl":"/nte-meta/game-audio/449207a372b67e20904c.ogg"},{"id":"en-Play_Vo_Char_NPC009_about_001","title":"Об Адлере","description":"Смотри, смотри, смотри… Видишь морщинки у Адлера вокруг глаз? Лезут, как грибы после дождя, с самого открытия. Мелкие хулиганки не представляют, как мы, взрослые, переживаем за них.","language":"Английский","audioUrl":"/nte-meta/game-audio/cb644726b7d1d141e8d8.ogg"},{"id":"en-Play_Vo_Char_NPC009_aoe_UI_001","title":"Сверхспособность I","description":"Это займет всего мгновение.","language":"Английский","audioUrl":"/nte-meta/game-audio/fa361ef4d2b812137c87.ogg"},{"id":"en-Play_Vo_Char_NPC009_greet_004","title":"Спокойной ночи","description":"Отличный напиток… Пф-ф, «Бокал уже пуст»? Да, я заметила. Просто взгляни на этот лунный свет. Он бесплатный. И да, добавка не ограничена, разве не так? Наполни снова, до краев.","language":"Английский","audioUrl":"/nte-meta/game-audio/6ad1a7ed45eb100e1754.ogg"},{"id":"ja-Play_Vo_Char_NPC009_aoe_UI_005","title":"Сверхспособность V","description":"Луна зашла.","language":"Японский","audioUrl":"/nte-meta/game-audio/92683d14265f91dc39d4.ogg"},{"id":"en-Play_Vo_Char_NPC009_SSC_006","title":"Особое переключение II — Наналли","description":"Очередной бардак разгребать?","language":"Английский","audioUrl":"/nte-meta/game-audio/ab5f7d1a90451fc7b83f.ogg"},{"id":"ja-Play_Vo_Char_NPC009_containment_002","title":"Сдерживание II","description":"Хм… достойное состояние.","language":"Японский","audioUrl":"/nte-meta/game-audio/159b937bd6c2742c0afb.ogg"},{"id":"en-Play_Vo_Char_NPC009_SSC_007","title":"Особое переключение I — Даффодил","description":"Просто держись позади меня.","language":"Английский","audioUrl":"/nte-meta/game-audio/b3d27e7da7c6e2d01ab9.ogg"},{"id":"en-Play_Vo_Char_NPC009_SSC_009","title":"Особое переключение I — Эдгар","description":"Давай поскорее с этим закончим.","language":"Английский","audioUrl":"/nte-meta/game-audio/12396d44859fbee11069.ogg"},{"id":"en-Play_Vo_Char_NPC009_SSC_012","title":"Особое переключение II — Ноль","description":"В самый раз.","language":"Английский","audioUrl":"/nte-meta/game-audio/799089aa33392b12d0f0.ogg"},{"id":"en-Play_Vo_Char_NPC009_struck_001","title":"Урон I","description":"Т-с.","language":"Английский","audioUrl":"/nte-meta/game-audio/7487c0b22ec781d0f0dc.ogg"},{"id":"ja-Play_Vo_Char_NPC009_greet_004","title":"Спокойной ночи","description":"Отличный напиток… Пф-ф, «Бокал уже пуст»? Да, я заметила. Просто взгляни на этот лунный свет. Он бесплатный. И да, добавка не ограничена, разве не так? Наполни снова, до краев.","language":"Японский","audioUrl":"/nte-meta/game-audio/e416dde6ceaadbdb34af.ogg"},{"id":"ja-Play_Vo_Char_NPC009_Parry_001","title":"Парирование I","description":"Не хватает мощности!","language":"Японский","audioUrl":"/nte-meta/game-audio/a3333f3ff44219fd2a8b.ogg"},{"id":"en-Play_Vo_Char_NPC009_hobby_001","title":"Хобби","description":"В наши дни любое хобби стоит денег. Честно говоря, мне веселее болтать с Дафф. Немного выпить, немного её подразнить, наслаждаться реакцией… вот это отличное развлечение.","language":"Английский","audioUrl":"/nte-meta/game-audio/fcbc762f96d4df296e98.ogg"},{"id":"ja-Play_Vo_Char_NPC009_gift_002","title":"Подарок получен II","description":"Это подлинник! Теперь у нас в коллекции ещё одно сокровище!","language":"Японский","audioUrl":"/nte-meta/game-audio/17490aec6ba118b4fd8d.ogg"},{"id":"en-Play_Vo_Char_NPC009_DodgeCombo_001","title":"Серия критических уклонений I","description":"Я вижу все твои уловки насквозь!","language":"Английский","audioUrl":"/nte-meta/game-audio/e3fba7e74fe2e1a6e5d9.ogg"},{"id":"en-Play_Vo_Char_NPC009_talk_003","title":"Тема: договор о поручении","description":"Эй, Прелесть, помоги мне. Я подумываю о том, чтобы добавить в форму поручения новый пункт… что-то типа «В случае запроса оценки аномалии у нашего штатного оценщика взимается комиссия в размере 50 %». Что думаешь?.. Ты качаешь головой? Ладно — 80 %! Договорились! Эй, Прелесть, помоги мне. Я подумываю о том, чтобы добавить в форму поручения новый пункт… что-то типа «В случае запроса оценки аномалии у нашей штатной оценщицы взимается комиссия в размере 50 %». Что думаешь?.. Ты качаешь головой? Ладно — 80 %! Договорились!","language":"Английский","audioUrl":"/nte-meta/game-audio/62c25b6582940a8b1d3c.ogg"},{"id":"ja-Play_Vo_Char_NPC009_SSC_010","title":"Особое переключение II — Эдгар","description":"Не нагружай себя слишком сильно.","language":"Японский","audioUrl":"/nte-meta/game-audio/fbdbc092cad936e3ec89.ogg"},{"id":"en-Play_Vo_Char_NPC009_windfall_004","title":"Неожиданная добыча IV","description":"Такое сокровище — и просто попало к тебе в руки?","language":"Английский","audioUrl":"/nte-meta/game-audio/fa906b6176942c7ade8a.ogg"},{"id":"ja-Play_Vo_Char_NPC009_hobby_001","title":"Хобби","description":"В наши дни любое хобби стоит денег. Честно говоря, мне веселее болтать с Дафф. Немного выпить, немного её подразнить, наслаждаться реакцией… вот это отличное развлечение.","language":"Японский","audioUrl":"/nte-meta/game-audio/eb0961854bf49081979a.ogg"},{"id":"en-Play_Vo_Char_NPC009_about_007","title":"Об Альфарде","description":"Будь начеку с директором. Не позволяй ей застать тебя врасплох. Не хочу оказаться на очередном «родительском собрании». Каждый раз, когда она натягивает на себя ледяную физиономию, даже гостевой диван премиум-класса начинает казаться жестким… Серьезно, старый обшарпанный диванчик дома куда комфортнее.","language":"Английский","audioUrl":"/nte-meta/game-audio/484e30bf6610dc34e60a.ogg"},{"id":"en-Play_Vo_Char_NPC009_dead_003","title":"Потеря сознания III","description":"Хех… Вижу старые времена…","language":"Английский","audioUrl":"/nte-meta/game-audio/a7008133238e61d1407e.ogg"},{"id":"ja-Play_Vo_Char_NPC009_gift_003","title":"Подарок получен III","description":"Прелесть, ты и правда очень стараешься… Я это ценю!","language":"Японский","audioUrl":"/nte-meta/game-audio/912f898de3674e4c8300.ogg"},{"id":"ja-Play_Vo_Char_NPC009_hstruck_001","title":"Сильный урон I","description":"Совсем неплохо.","language":"Японский","audioUrl":"/nte-meta/game-audio/81a49567b9cdd79e621c.ogg"},{"id":"en-Play_Vo_Char_NPC009_QTE_003","title":"Атака на входе III","description":"Покажем им выход.","language":"Английский","audioUrl":"/nte-meta/game-audio/3f76d3f814f61c905108.ogg"},{"id":"ja-Play_Vo_Char_NPC009_aoe_UI_001","title":"Сверхспособность I","description":"Это займет всего мгновение.","language":"Японский","audioUrl":"/nte-meta/game-audio/f1194d10d215bf48acff.ogg"},{"id":"en-Play_Vo_Char_NPC009_chat_003","title":"Чат: охота за сокровищами","description":"Присмотри за магазином, я отправляюсь на блошиный рынок в Районе мостов… Зачем? Хех, за сокровищами, конечно.","language":"Английский","audioUrl":"/nte-meta/game-audio/b2cd87b43f6f8b9c82d1.ogg"},{"id":"en-Play_Vo_Char_NPC009_TeammateDown_003","title":"Поражен товарищ по команде – Наналли","description":"Тебе ещё предстоит пройти долгий путь.","language":"Английский","audioUrl":"/nte-meta/game-audio/88a28287d418f1f8be32.ogg"},{"id":"en-Play_Vo_Char_NPC009_weather_001","title":"Солнечно","description":"Я — не то что эти дети с бесконечным запасом энергии, которые носятся дни напролет. Я дождусь приятной облачной погоды, чтобы снова выйти наружу.","language":"Английский","audioUrl":"/nte-meta/game-audio/3e2e8fac757dead29f04.ogg"},{"id":"ja-Play_Vo_Char_NPC009_self_003","title":"Обо мне: собственница","description":"Что значит «я не занимаюсь управлением»? Какой сопляк тебе это сказал? Я всегда следила за ассортиментом «Эйбона». И кроме того, повседневной работой управляет Адлер. Моя задача — принимать стратегические решения! Вот что делает настоящий лидер.","language":"Японский","audioUrl":"/nte-meta/game-audio/7ac8571d60e34b324bf0.ogg"},{"id":"ja-Play_Vo_Char_NPC009_SSC_004","title":"Особое переключение II — Сакири","description":"Сколько же от тебя шума!","language":"Японский","audioUrl":"/nte-meta/game-audio/b2f31f0059a9010edba3.ogg"},{"id":"ja-Play_Vo_Char_NPC009_windfall_001","title":"Неожиданная добыча I","description":"А вот и деньги!","language":"Японский","audioUrl":"/nte-meta/game-audio/8f1990d3b459db4e15aa.ogg"},{"id":"en-Play_Vo_Char_NPC009_about_005","title":"О Наналли","description":"Наналли! Что ты опять сломала?! Почему счета за твои проделки приходят мне без предупреждения?!.. Куда делась эта мелкая негодница… Т-с, Адлер! Слушай, месяц.. арг-х, может, неделя! Никаких яичных рулетов для нее. Может в этот раз запомнит… И не подсовывай ей их тайком!","language":"Английский","audioUrl":"/nte-meta/game-audio/7df9e312eb045396e63e.ogg"},{"id":"en-Play_Vo_Char_NPC009_talk_001","title":"Тема: аномалия «Депрессивный денди»","description":"Если тебе скучно, поболтай с той картиной. Постарайся вести себя естественно и скажи что-нибудь приятное. Мне надоело слушать её жалобы о том, что лицо потрескалось. В последний раз, когда я проходила мимо, она даже попросила, чтобы я нанесла крем для лица между мазками! Абсурд!","language":"Английский","audioUrl":"/nte-meta/game-audio/2ee52ed85b1a59867d45.ogg"},{"id":"ja-Play_Vo_Char_NPC009_Switch_002","title":"Переключение II","description":"Тебе что-то нужно?..","language":"Японский","audioUrl":"/nte-meta/game-audio/2e372367a48e457642bf.ogg"},{"id":"en-Play_Vo_Char_NPC009_anomaly_003","title":"Нуллификация I","description":"Сойдет на время.","language":"Английский","audioUrl":"/nte-meta/game-audio/e580eab79edbea6b675d.ogg"},{"id":"en-Play_Vo_Char_NPC009_chat_001","title":"Чат: репутация","description":"Выполняя задания, защищай репутацию нашего магазина. Кхм… И для протокола — меня абсолютно не волнуют низкие рейтинги «Эйбона» на Хьелп. Всего лишь цифры на экране! Реальная благодарность от реальных клиентов — вот что важно!","language":"Английский","audioUrl":"/nte-meta/game-audio/0c59feb5e43273fec863.ogg"},{"id":"en-Play_Vo_Char_NPC009_skill_002","title":"Навык перенаправления II","description":"Дай взглянуть поближе.","language":"Английский","audioUrl":"/nte-meta/game-audio/620296ca10cb117c8795.ogg"},{"id":"ja-Play_Vo_Char_NPC009_windfall_002","title":"Неожиданная добыча II","description":"Как по мне, это подлинная вещь…","language":"Японский","audioUrl":"/nte-meta/game-audio/998e55e721d96947668e.ogg"},{"id":"ja-Play_Vo_Char_NPC009_windfall_005","title":"Неожиданная добыча V","description":"Кому какое дело, чего это стоит? Что нашли — то наше!","language":"Японский","audioUrl":"/nte-meta/game-audio/8baa08c55f17300a8c03.ogg"},{"id":"ja-Play_Vo_Char_NPC009_skill_003","title":"Навык перенаправления III","description":"Есть ещё порох в пороховницах, да?","language":"Японский","audioUrl":"/nte-meta/game-audio/5034f6039167f756fe5d.ogg"},{"id":"en-Play_Vo_Char_NPC009_containment_002","title":"Сдерживание II","description":"Хм… достойное состояние.","language":"Английский","audioUrl":"/nte-meta/game-audio/0e7b038cad009ed94753.ogg"},{"id":"en-Play_Vo_Char_NPC009_gift_001","title":"Подарок получен I","description":"Ого! Где ты это раздобыл? У тебя отличный вкус — мне очень нравится! Ого! Где ты это раздобыла? У тебя отличный вкус — мне очень нравится!","language":"Английский","audioUrl":"/nte-meta/game-audio/c4e1d1487246c9d1233b.ogg"},{"id":"en-Play_Vo_Char_NPC009_Parry_002","title":"Парирование II","description":"Мягкое прикосновение берет верх над силой.","language":"Английский","audioUrl":"/nte-meta/game-audio/98935883df21d0166708.ogg"},{"id":"ja-Play_Vo_Char_NPC009_SSC_012","title":"Особое переключение II — Ноль","description":"В самый раз.","language":"Японский","audioUrl":"/nte-meta/game-audio/648c38376828de535a5c.ogg"},{"id":"en-Play_Vo_Char_NPC009_struck_002","title":"Урон II","description":"Ш-ш.","language":"Английский","audioUrl":"/nte-meta/game-audio/084fc66157dc98cf3ccd.ogg"},{"id":"ja-Play_Vo_Char_NPC009_hstruck_002","title":"Сильный урон II","description":"Как банально.","language":"Японский","audioUrl":"/nte-meta/game-audio/96c7b59da9828bd87514.ogg"},{"id":"en-Play_Vo_Char_NPC009_deploy_002","title":"Отправка I","description":"Время вернуть себе репутацию… и немного размяться.","language":"Английский","audioUrl":"/nte-meta/game-audio/6256c4a768f72ed28b9c.ogg"},{"id":"ja-Play_Vo_Char_NPC009_greet_002","title":"Дневное приветствие","description":"Ах… самое сонное время дня. Я, пожалуй, отдохну в каком-нибудь прохладном месте.","language":"Японский","audioUrl":"/nte-meta/game-audio/c75105d848cc11c87658.ogg"},{"id":"ja-Play_Vo_Char_NPC009_kill_002","title":"Убийство II","description":"Увидимся.","language":"Японский","audioUrl":"/nte-meta/game-audio/01fcb286551c1e762233.ogg"},{"id":"ja-Play_Vo_Char_NPC009_talk_001","title":"Тема: аномалия «Депрессивный денди»","description":"Если тебе скучно, поболтай с той картиной. Постарайся вести себя естественно и скажи что-нибудь приятное. Мне надоело слушать её жалобы о том, что лицо потрескалось. В последний раз, когда я проходила мимо, она даже попросила, чтобы я нанесла крем для лица между мазками! Абсурд!","language":"Японский","audioUrl":"/nte-meta/game-audio/f92a1aa2c7e86d9c4b2f.ogg"},{"id":"ja-Play_Vo_Char_NPC009_talk_002","title":"Тема: руководство по сделкам","description":"В торговых условиях «Эйбона» есть несколько строк, о которых не следует сообщать клиентам… Да, знаю. Когда я писала их впервые, я просто изливала на бумагу то, что чувствовала… Всё же торговля подразумевает честность, разве не так? Если что-то кажется неуместным, просто зачеркни, прежде чем показывать клиенту. Перепечатывать не нужно. Типографии в наши дни — форменный грабеж… Таким магазинчикам, как «Эйбон», трудно выжить в этом враждебном мире…","language":"Японский","audioUrl":"/nte-meta/game-audio/d2697699e1f5e45e065a.ogg"},{"id":"ja-Play_Vo_Char_NPC009_weather_004","title":"Жарко","description":"Уф, ну и жара… Сообщи, когда будешь брать охлажденное саке, ладно? А то оно быстро нагреется.","language":"Японский","audioUrl":"/nte-meta/game-audio/2c43da8ce55bcef7464e.ogg"},{"id":"en-Play_Vo_Char_NPC009_QTE_002","title":"Атака на входе II","description":"Как грубо.","language":"Английский","audioUrl":"/nte-meta/game-audio/188e3cc2bd058da20352.ogg"},{"id":"en-Play_Vo_Char_NPC009_Switch_002","title":"Переключение II","description":"Тебе что-то нужно?..","language":"Английский","audioUrl":"/nte-meta/game-audio/15a9d8f73bfd5e25ab15.ogg"},{"id":"en-Play_Vo_Char_NPC009_weather_003","title":"Холодно","description":"В этом городе не так уж плохо даже в холодный сезон… и снег идет редко. Честно говоря, иногда я немного скучаю по дому.","language":"Английский","audioUrl":"/nte-meta/game-audio/4fb87919db4855f897f1.ogg"},{"id":"en-Play_Vo_Char_NPC009_about_008","title":"Об антикварном магазине Эйбон","description":"Следовало догадаться, что это никчемное место. Дешевая аренда завела меня в тупик — бизнесу конец! Так зачем было открывать «Эйбон» здесь? Хех, потому что такого понятия, как «следовало догадаться», не существует. Это судьба.","language":"Английский","audioUrl":"/nte-meta/game-audio/c0abdd23f8571ff06191.ogg"},{"id":"ja-Play_Vo_Char_NPC009_fh_001","title":"Исцеление I","description":"Как хорошее вино.","language":"Японский","audioUrl":"/nte-meta/game-audio/67fb14b942ca35d54fc4.ogg"},{"id":"ja-Play_Vo_Char_NPC009_fh_002","title":"Исцеление II","description":"М-м-м… вот это хорошо.","language":"Японский","audioUrl":"/nte-meta/game-audio/1d6ff629ab4dad42358e.ogg"},{"id":"ja-Play_Vo_Char_NPC009_TeammateDown_001","title":"Поражен товарищ по команде – Адлер","description":"Ничто не остается неизменным вечно…","language":"Японский","audioUrl":"/nte-meta/game-audio/43b0e5e442a6b51e8dbe.ogg"},{"id":"ja-Play_Vo_Char_NPC009_TeammateDown_005","title":"Поражен товарищ по команде – Эдгар","description":"Молодец, ты старался изо всех сил.","language":"Японский","audioUrl":"/nte-meta/game-audio/b77cf6a7952a5fc6e931.ogg"},{"id":"ja-Play_Vo_Char_NPC009_anomaly_004","title":"Нуллификация II","description":"Ещё одно задание выполнено.","language":"Японский","audioUrl":"/nte-meta/game-audio/53d5732a35be3eb4309a.ogg"},{"id":"ja-Play_Vo_Char_NPC009_weather_001","title":"Солнечно","description":"Я — не то что эти дети с бесконечным запасом энергии, которые носятся дни напролет. Я дождусь приятной облачной погоды, чтобы снова выйти наружу.","language":"Японский","audioUrl":"/nte-meta/game-audio/badd7d3c3ea2dda99d57.ogg"},{"id":"en-Play_Vo_Char_NPC009_aoe_UI_002","title":"Сверхспособность II","description":"Это место притягивает к себе приливы и отливы мира.","language":"Английский","audioUrl":"/nte-meta/game-audio/84e217aa9b74ab27fb24.ogg"},{"id":"en-Play_Vo_Char_NPC009_QTE_001","title":"Атака на входе I","description":"Как грубо.","language":"Английский","audioUrl":"/nte-meta/game-audio/7dfd778ff7080ca1188d.ogg"},{"id":"ja-Play_Vo_Char_NPC009_hp_003","title":"Низкий уровень здоровья III","description":"Выпей что-нибудь, чтобы немного согреться…","language":"Японский","audioUrl":"/nte-meta/game-audio/be9f9543ae2e79240b50.ogg"},{"id":"en-Play_Vo_Char_NPC009_greet_003","title":"Вечернее приветствие","description":"Сегодняшний доход… как, мы снова в минусе?","language":"Английский","audioUrl":"/nte-meta/game-audio/33b0662ed21482bff410.ogg"},{"id":"en-Play_Vo_Char_NPC009_ug_003","title":"Вознесение персонажа III","description":"Возможно, «сейчас» самый памятный момент из всех… кто знает?","language":"Английский","audioUrl":"/nte-meta/game-audio/905a800922c66b2780d2.ogg"},{"id":"en-Play_Vo_Char_NPC009_windfall_005","title":"Неожиданная добыча V","description":"Кому какое дело, чего это стоит? Что нашли — то наше!","language":"Английский","audioUrl":"/nte-meta/game-audio/309b270d74b376753209.ogg"},{"id":"ja-Play_Vo_Char_NPC009_kill_001","title":"Убийство I","description":"Теперь ведешь себя, как следует?","language":"Японский","audioUrl":"/nte-meta/game-audio/9dcbda464276589ac1fb.ogg"},{"id":"ja-Play_Vo_Char_NPC009_QTE_002","title":"Атака на входе II","description":"Как грубо.","language":"Японский","audioUrl":"/nte-meta/game-audio/da776587be9394c622ce.ogg"},{"id":"en-Play_Vo_Char_NPC009_self_003","title":"Обо мне: собственница","description":"Что значит «я не занимаюсь управлением»? Какой сопляк тебе это сказал? Я всегда следила за ассортиментом «Эйбона». И кроме того, повседневной работой управляет Адлер. Моя задача — принимать стратегические решения! Вот что делает настоящий лидер.","language":"Английский","audioUrl":"/nte-meta/game-audio/9c085cd6a8757f93f826.ogg"},{"id":"en-Play_Vo_Char_NPC009_windfall_001","title":"Неожиданная добыча I","description":"А вот и деньги!","language":"Английский","audioUrl":"/nte-meta/game-audio/be555005078c205afb4f.ogg"},{"id":"ja-Play_Vo_Char_NPC009_chat_003","title":"Чат: охота за сокровищами","description":"Присмотри за магазином, я отправляюсь на блошиный рынок в Районе мостов… Зачем? Хех, за сокровищами, конечно.","language":"Японский","audioUrl":"/nte-meta/game-audio/00bb208832b3e65daabe.ogg"},{"id":"ja-Play_Vo_Char_NPC009_hp_001","title":"Низкий уровень здоровья I","description":"Всему свое время и место…","language":"Японский","audioUrl":"/nte-meta/game-audio/8932b356bbbaf6cc6cb9.ogg"},{"id":"en-Play_Vo_Char_NPC009_TeammateDown_004","title":"Поражен товарищ по команде – Даффодил","description":"Спи, моя маленькая Дафф…","language":"Английский","audioUrl":"/nte-meta/game-audio/fb2dac7d265cf87b5198.ogg"},{"id":"ja-Play_Vo_Char_NPC009_aoe_UI_004","title":"Сверхспособность IV","description":"Уже прибываю.","language":"Японский","audioUrl":"/nte-meta/game-audio/9e1edfdb7838f02892e2.ogg"},{"id":"ja-Play_Vo_Char_NPC009_skill_001","title":"Навык перенаправления I","description":"Небольшая показуха.","language":"Японский","audioUrl":"/nte-meta/game-audio/ea014ae4443200c4d10b.ogg"},{"id":"en-Play_Vo_Char_NPC009_dead_002","title":"Потеря сознания II","description":"Настал… мой час…","language":"Английский","audioUrl":"/nte-meta/game-audio/b0337fdbe9099f6fce94.ogg"},{"id":"en-Play_Vo_Char_NPC009_hp_002","title":"Низкий уровень здоровья II","description":"Бесит. Цена по-прежнему слишком низкая.","language":"Английский","audioUrl":"/nte-meta/game-audio/b330a40b3419ae2f1dd2.ogg"},{"id":"en-Play_Vo_Char_NPC009_TeammateDown_001","title":"Поражен товарищ по команде – Адлер","description":"Ничто не остается неизменным вечно…","language":"Английский","audioUrl":"/nte-meta/game-audio/d3a2f2892cba99e543ee.ogg"},{"id":"en-Play_Vo_Char_NPC009_ug_001","title":"Вознесение персонажа I","description":"Я бы сказала… вселенная могла бы начать действовать во благо этого места.","language":"Английский","audioUrl":"/nte-meta/game-audio/e97bb4afbb7ffff1279e.ogg"},{"id":"ja-Play_Vo_Char_NPC009_SSC_006","title":"Особое переключение II — Наналли","description":"Очередной бардак разгребать?","language":"Японский","audioUrl":"/nte-meta/game-audio/4c20e3c56f7a75b7e739.ogg"},{"id":"en-Play_Vo_Char_NPC009_about_006","title":"Об Эдгаре","description":"Эдгар — такой тихий и послушный мальчик. Любит книги, не требует многого. Как его родителям удалось так хорошо его воспитать? Нужно взять на заметку…","language":"Английский","audioUrl":"/nte-meta/game-audio/bdc158971644a4fc6b6f.ogg"},{"id":"ja-Play_Vo_Char_NPC009_about_007","title":"Об Альфарде","description":"Будь начеку с директором. Не позволяй ей застать тебя врасплох. Не хочу оказаться на очередном «родительском собрании». Каждый раз, когда она натягивает на себя ледяную физиономию, даже гостевой диван премиум-класса начинает казаться жестким… Серьезно, старый обшарпанный диванчик дома куда комфортнее.","language":"Японский","audioUrl":"/nte-meta/game-audio/a4d712bc06871566ffc9.ogg"},{"id":"ja-Play_Vo_Char_NPC009_chat_001","title":"Чат: репутация","description":"Выполняя задания, защищай репутацию нашего магазина. Кхм… И для протокола — меня абсолютно не волнуют низкие рейтинги «Эйбона» на Хьелп. Всего лишь цифры на экране! Реальная благодарность от реальных клиентов — вот что важно!","language":"Японский","audioUrl":"/nte-meta/game-audio/6848891c84eae3d6695b.ogg"},{"id":"ja-Play_Vo_Char_NPC009_ug_001","title":"Вознесение персонажа I","description":"Я бы сказала… вселенная могла бы начать действовать во благо этого места.","language":"Японский","audioUrl":"/nte-meta/game-audio/ecfa18bb6fcf4cc5d312.ogg"},{"id":"ja-Play_Vo_Char_NPC009_windfall_003","title":"Неожиданная добыча III","description":"Игнорировать выгодную сделку? Это просто хамство.","language":"Японский","audioUrl":"/nte-meta/game-audio/a2f566f566546a2139cc.ogg"},{"id":"ja-Play_Vo_Char_NPC009_dead_003","title":"Потеря сознания III","description":"Хех… Вижу старые времена…","language":"Японский","audioUrl":"/nte-meta/game-audio/923b223e732d26d9394a.ogg"}]') WHERE character_id='hotori' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-23 13:53:58');

UPDATE character_profiles SET voice_lines_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(voice_lines_json) UNION ALL SELECT value FROM json_each('[{"id":"ja-Play_Vo_Char_NPC009_deploy_001","title":"Отправка II","description":"Не могу позволить, чтобы с сотрудниками «Эйбона» обращались столь бесцеремонно.","language":"Японский","audioUrl":"/nte-meta/game-audio/0010726ba4b4a4d24fdd.ogg"},{"id":"ja-Play_Vo_Char_NPC009_SSC_011","title":"Особое переключение I — Ноль","description":"Не тронь мою прелесть!","language":"Японский","audioUrl":"/nte-meta/game-audio/323e9b59b85e74318edf.ogg"},{"id":"en-Play_Vo_Char_NPC009_chat_002","title":"Чат: фонсы","description":"Фонс, фонс, фонс… Кто придумал это название? Чем больше произношу его, тем лучше оно звучит… «Фонс»… какое прекрасное слово.","language":"Английский","audioUrl":"/nte-meta/game-audio/2cbac4b291c7f30083bd.ogg"},{"id":"en-Play_Vo_Char_NPC009_self_001","title":"Обо мне: способности эспера","description":"«Время» — это не просто путь. Это ещё и… точка зрения.","language":"Английский","audioUrl":"/nte-meta/game-audio/59a2ece4b060fcc43a44.ogg"},{"id":"en-Play_Vo_Char_NPC009_TeammateDown_002","title":"Поражен товарищ по команде – Сакири","description":"Видишь, что происходит, когда ты пытаешься показать крутость?","language":"Английский","audioUrl":"/nte-meta/game-audio/b8b60220ab76e3971307.ogg"},{"id":"ja-Play_Vo_Char_NPC009_Fly_002","title":"Планирование II","description":"Фух!","language":"Японский","audioUrl":"/nte-meta/game-audio/3a7ce2d3ffee7fb4852c.ogg"},{"id":"en-Play_Vo_Char_NPC009_about_002","title":"О Даффодил","description":"Дафф сама по себе почти не пьет, но если поднять бокал и пригласить её присоединиться, её уже не остановить. Я как-то сказала ей — после тоста нужно выпить хотя бы полбокала, это базовый этикет. Хе-хе… а потом… начинается веселье. Она отнюдь не такая стойкая, как считает.","language":"Английский","audioUrl":"/nte-meta/game-audio/fc110ae5c306c8a6cc23.ogg"},{"id":"en-Play_Vo_Char_NPC009_SSC_008","title":"Особое переключение II — Даффодил","description":"Давай я тебе помогу.","language":"Английский","audioUrl":"/nte-meta/game-audio/ca267fe6bdf742734699.ogg"},{"id":"hotori-voice-source-en","title":"Hotori Voice Records — Английский","language":"Английский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=3kVJaEinOG0","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."},{"id":"hotori-voice-source-ja","title":"Hotori Voice Records — Японский","language":"Японский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=3kVJaEinOG0","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."},{"id":"hotori-voice-source-ko","title":"Hotori Voice Records — Корейский","language":"Корейский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=3kVJaEinOG0","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."},{"id":"hotori-voice-source-zh","title":"Hotori Voice Records — Китайский","language":"Китайский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=3kVJaEinOG0","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."}]'))) WHERE character_id='hotori' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-23 13:53:58');

UPDATE character_profiles SET abilities_json=json('[{"id":"ability-1qewgz","name":"Авторитет лавочника","type":"Навык поддержки","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/skills/Jin_QTE.png","description":"Пора преподать невоспитанным гостям урок вежливости. Бросает зонт, нанося 1 экземпляр урона космоса по области.\n\nДля Хотори это всего лишь небольшая демонстрация её способностей — но недовольные клиенты, которые пришли устроить скандал, сразу понимают, почему этот маленький скромный магазинчик осмеливается ставить такие строгие условия.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"}]},{"id":"ability-1w0fnxr","name":"Лунный стиль Мисти","type":"Базовая атака","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/skills/Jin_Melee.png","description":"Базовая атака: Лунный стиль Мисти\n\nПроводит до 5 последовательных атак своим оружием, нанося урон космоса.\n\nБазовая атака: Незакрытые часы\n\nКогда Хотори развернута, появляются Незакрытые часы. Медленно вращает их стрелку по часовой стрелке, накапливая энергию. Максимум энергии, которую могут накопить Незакрытые часы, равен 120 ед.\n\nБазовая атака: Плещущие волны\n\nУдерживайте базовую атаку в бою для запуска. Изящно устремляется вперед и атакует, нанося 4 экземпляра урона космоса по области.\n\nБазовая атака: Полумесяц\n\nВзмахивает своим оружием в воздухе и пикирует, нанося 1 экземпляр урона космоса по области при ударе. Урон увеличивается в зависимости от высоты падения (до 100 %).\n\nКритический контрудар: половина момента\n\nСрабатывает при использовании «Лунного стиля Мисти» после критического уклонения. Мгновенно поднимает зонт для контратаки, нанося 1 экземпляр урона космоса и снижая Разрушение.\n\n«Наконец-то появился простак, который действительно хочет что-то купить… но если бы не Хотори, которая отказывается сдвинуться с места, то…. в продажах в этом месяце не красовался бы большой жирный нуль».\n\n«Этот маленький сопляк… вы видели, какую он хотел выторговать цену? Небось, думает, что наш «Эйбон» — какой-то благотворительный фонд! Я его ещё пожалел, не стал звать Дафф, чтобы привести его в чувство!»","attributes":[{"id":"parameter-0","label":"Множитель 1-го удара","value":"1: 20 % · 2: 21.6 % · 3: 23.3 % · 4: 25.2 % · 5: 27.2 % · 6: 29.4 % · 7: 31.7 % · 8: 34.3 % · 9: 37 % · 10: 40 % · 11: 43.2 % · 12: 46.6 % · 13: 50.4 %"},{"id":"parameter-1","label":"Множитель 2-го удара","value":"1: 35.3 %+4.4 %*2+72.2 % · 2: 38.1 %+4.8 %*2+78 % · 3: 41.2 %+5.1 %*2+84.2 % · 4: 44.5 %+5.5 %*2+91 % · 5: 48 %+6 %*2+98.2 % · 6: 51.9 %+6.5 %*2+106.1 % · 7: 56 %+7 %*2+114.6 % · 8: 60.5 %+7.5 %*2+123.7 % · 9: 65.3 %+8.1 %*2+133.6 % · 10: 70.6 %+8.8 %*2+144.3 % · 11: 76.2 %+9.5 %*2+155.9 % · 12: 82.3 %+10.3 %*2+168.3 % · 13: 88.9 %+11.1 %*2+181.8 %"},{"id":"parameter-2","label":"Множитель 3-го удара","value":"1: 11.3 %*5 · 2: 12.2 %*5 · 3: 13.2 %*5 · 4: 14.2 %*5 · 5: 15.4 %*5 · 6: 16.6 %*5 · 7: 17.9 %*5 · 8: 19.4 %*5 · 9: 20.9 %*5 · 10: 22.6 %*5 · 11: 24.4 %*5 · 12: 26.3 %*5 · 13: 28.5 %*5"},{"id":"parameter-3","label":"Множитель 4-го удара","value":"1: 14.2 %*2+66.6 % · 2: 15.3 %*2+71.9 % · 3: 16.6 %*2+77.7 % · 4: 17.9 %*2+83.9 % · 5: 19.3 %*2+90.6 % · 6: 20.9 %*2+97.9 % · 7: 22.5 %*2+105.7 % · 8: 24.3 %*2+114.1 % · 9: 26.3 %*2+123.3 % · 10: 28.4 %*2+133.1 % · 11: 30.7 %*2+143.8 % · 12: 33.1 %*2+155.3 % · 13: 35.8 %*2+167.7 %"},{"id":"parameter-4","label":"Множитель 5-го удара","value":"1: 24.3 %+45.1 % · 2: 26.2 %+48.7 % · 3: 28.3 %+52.6 % · 4: 30.6 %+56.8 % · 5: 33.1 %+61.4 % · 6: 35.7 %+66.3 % · 7: 38.6 %+71.6 % · 8: 41.6 %+77.3 % · 9: 45 %+83.5 % · 10: 48.6 %+90.2 % · 11: 52.5 %+97.4 % · 12: 56.7 %+105.2 % · 13: 61.2 %+113.6 %"},{"id":"parameter-6","label":"Лимит энергии","value":"120"},{"id":"parameter-7","label":"Восстановление энергии в секунду","value":"6"},{"id":"parameter-8","label":"Множитель урона последующей атаки","value":"1: 24 % *4 · 2: 25.9 % *4 · 3: 28 % *4 · 4: 30.2 % *4 · 5: 32.7 % *4 · 6: 35.3 % *4 · 7: 38.1 % *4 · 8: 41.1 % *4 · 9: 44.4 % *4 · 10: 48 % *4 · 11: 51.8 % *4 · 12: 56 % *4 · 13: 60.4 % *4"},{"id":"parameter-9","label":"Множитель урона атаки в падении","value":"1: 48 % · 2: 51.8 % · 3: 56 % · 4: 60.5 % · 5: 65.3 % · 6: 70.5 % · 7: 76.2 % · 8: 82.3 % · 9: 88.8 % · 10: 96 % · 11: 103.6 % · 12: 111.9 % · 13: 120.9 %"},{"id":"parameter-10","label":"Множитель критического контрудара","value":"1: 158 % · 2: 170.6 % · 3: 184.3 % · 4: 199 % · 5: 215 % · 6: 232.2 % · 7: 250.7 % · 8: 270.8 % · 9: 292.4 % · 10: 315.8 % · 11: 341.1 % · 12: 368.4 % · 13: 397.9 %"}]},{"id":"ability-7z7mk5","name":"Гребень призрачной орхидеи","type":"Пассивный навык","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/skills/Jin_Pas1.png","description":"Усиление цветения: атаки Бутонов жизни не приостанавливаются во время остановки времени.\n\nЧто ж — когда эта хозяйка, которая может без умолку болтать о сущих мелочах, наконец затихает и мирно сидит, потягивая вино и любуясь луной, вы замечаете… как она элегантна и изящна.","attributes":[]},{"id":"wotpack-1gw006a","name":"Ритуал ледяного снега","type":"Черта персонажа","iconUrl":"/nte-meta/game-assets/23ba20bdb32fb18c49ee.webp","description":"вне боя зажмите б/а, чтобы полностью остановить время. Эффект прекращается при повторном удерживании кнопки или когда энергия «часов» заканчивается.","attributes":[]},{"id":"ability-50ov40","name":"Мировой прилив","type":"Сверхспособность","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/skills/Jin_UltraSkillA.png","description":"«Мировой прилив» не имеет перезарядки и не требует энергии сверхспособности.\n\nПри полной энергии Незакрытых часов Хотори может выпустить «Мировой прилив», нанося 10 экземпляров урона космоса по области, одновременно извлекая катану из рукояти зонта и меняя боевую стойку. Затем время вокруг почти замирает на некоторый период, а переключение персонажей блокируется. Вход в остановку времени очищает все полученные дебаффы контроля времени и предоставляет иммунитет к дебаффам контроля времени на весь период остановки. При наличии записей «Настоящего воспроизведения» все записанные атаки воспроизводятся по 1 разу (после чего записи очищаются).\n\nВо время остановки времени стрелка Незакрытых часов продолжает перематываться. Атаки катаной Хотори накапливают уровни комбо с ростом урона за каждый удар. При 10 уровнях комбо наносится финальный удар. Остановка времени завершается при полной перемотке стрелки или после финального удара.\n\nТогда направляйся же к предопределенному будущему.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 17 %*6+130.3 %+44.3 %+261.6 %*2 · 2: 18.4 %*6+140.7 %+47.8 %+282.5 %*2 · 3: 19.8 %*6+152 %+51.7 %+305.1 %*2 · 4: 21.4 %*6+164.1 %+55.8 %+329.5 %*2 · 5: 23.1 %*6+177.3 %+60.3 %+355.9 %*2 · 6: 25 %*6+191.5 %+65.1 %+384.4 %*2 · 7: 27 %*6+206.8 %+70.3 %+415.1 %*2 · 8: 29.1 %*6+223.3 %+75.9 %+448.3 %*2 · 9: 31.5 %*6+241.2 %+82 %+484.2 %*2 · 10: 34 %*6+260.5 %+88.6 %+522.9 %*2 · 11: 36.7 %*6+281.3 %+95.6 %+564.8 %*2 · 12: 39.6 %*6+303.8 %+103.3 %+610 %*2 · 13: 42.8 %*6+328.1 %+111.6 %+658.8 %*2"},{"id":"parameter-1","label":"Длительность остановки времени","value":"10 сек."},{"id":"parameter-2","label":"Множитель 1-го удара катаны","value":"1: 38.1 % · 2: 41.1 % · 3: 44.4 % · 4: 48 % · 5: 51.8 % · 6: 56 % · 7: 60.5 % · 8: 65.3 % · 9: 70.5 % · 10: 76.2 % · 11: 82.3 % · 12: 88.8 % · 13: 95.9 %"},{"id":"parameter-3","label":"Множитель 2-го удара катаны","value":"1: 23.4 %+63.7 % · 2: 25.3 %+68.8 % · 3: 27.3 %+74.3 % · 4: 29.5 %+80.2 % · 5: 31.8 %+86.7 % · 6: 34.4 %+93.6 % · 7: 37.1 %+101.1 % · 8: 40.1 %+109.2 % · 9: 43.3 %+117.9 % · 10: 46.8 %+127.3 % · 11: 50.5 %+137.5 % · 12: 54.6 %+148.5 % · 13: 58.9 %+160.4 %"},{"id":"parameter-4","label":"Множитель 3-го удара катаны","value":"1: 9.2 %*3+44.5 % · 2: 9.9 %*3+48.1 % · 3: 10.7 %*3+51.9 % · 4: 11.6 %*3+56.1 % · 5: 12.5 %*3+60.5 % · 6: 13.5 %*3+65.4 % · 7: 14.6 %*3+70.6 % · 8: 15.8 %*3+76.3 % · 9: 17 %*3+82.4 % · 10: 18.4 %*3+89 % · 11: 19.9 %*3+96.1 % · 12: 21.5 %*3+103.8 % · 13: 23.2 %*3+112.1 %"},{"id":"parameter-5","label":"Множитель 4-го удара катаны","value":"1: 25.5 %+29.7 %+25.4 %+42.4 % · 2: 27.5 %+32.1 %+27.4 %+45.8 % · 3: 29.7 %+34.6 %+29.6 %+49.5 % · 4: 32.1 %+37.4 %+32 %+53.4 % · 5: 34.7 %+40.4 %+34.6 %+57.7 % · 6: 37.5 %+43.6 %+37.3 %+62.3 % · 7: 40.5 %+47.1 %+40.3 %+67.3 % · 8: 43.7 %+50.9 %+43.5 %+72.7 % · 9: 47.2 %+55 %+47 %+78.5 % · 10: 51 %+59.4 %+50.8 %+84.8 % · 11: 55.1 %+64.1 %+54.8 %+91.5 % · 12: 59.5 %+69.2 %+59.2 %+98.9 % · 13: 64.2 %+74.8 %+64 %+106.8 %"},{"id":"parameter-6","label":"Множитель 5-го удара катаны","value":"1: 8.5 %+221.1 % · 2: 9.2 %+238.8 % · 3: 9.9 %+257.9 % · 4: 10.7 %+278.5 % · 5: 11.6 %+300.8 % · 6: 12.5 %+324.9 % · 7: 13.5 %+350.9 % · 8: 14.6 %+378.9 % · 9: 15.7 %+409.2 % · 10: 17 %+442 % · 11: 18.4 %+477.3 % · 12: 19.8 %+515.5 % · 13: 21.4 %+556.8 %"},{"id":"parameter-7","label":"Множитель урона финишера","value":"1: 300 % · 2: 324 % · 3: 349.9 % · 4: 377.9 % · 5: 408.1 % · 6: 440.8 % · 7: 476.1 % · 8: 514.1 % · 9: 555.3 % · 10: 599.7 % · 11: 647.7 % · 12: 699.5 % · 13: 755.5 %"}]},{"id":"ability-1jw6hua","name":"Настоящее воспроизведение","type":"Навык","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/skills/Jin_Skill.png","description":"«Настоящее воспроизведение» не имеет перезарядки.\n\nХотори может применить «Настоящее воспроизведение», потратив 60 ед. энергии Незакрытых часов, если единиц энергии больше 60. Наносит 7 экземпляров урона космоса по области. Записывает используемые союзниками навыки поддержки и навыки перенаправления в течение следующих 5 сек. За один раз можно записать до 3 моментов использования, каждый персонаж может быть записан только один раз.\n\nВо время использования стрелка Незакрытых часов непрерывно перематывается назад. Запись прекращается, когда стрелка достигает определённого положения. При досрочном завершении записи перемотка продолжается до фиксированного положения. Запись сбрасывается при входе в бой или выходе из него. Повторное использование «Настоящего воспроизведения» перезаписывает предыдущую запись.\n\nНаблюдение и свидетельство","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 40 %*6+60.1 % · 2: 43.2 %*6+64.9 % · 3: 46.7 %*6+70.1 % · 4: 50.4 %*6+75.7 % · 5: 54.4 %*6+81.8 % · 6: 58.8 %*6+88.3 % · 7: 63.5 %*6+95.4 % · 8: 68.6 %*6+103 % · 9: 74 %*6+111.2 % · 10: 80 %*6+120.1 % · 11: 86.4 %*6+129.8 % · 12: 93.3 %*6+140.1 % · 13: 100.7 %*6+151.3 %"}]},{"id":"ability-1p50728","name":"Все сокровища под небесами","type":"Пассивный навык","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/skills/Jin_Pas2.png","description":"Увеличивает коэффициент урона финального удара Мирового прилива на 100 %.\n\nТвое здоровье! Будем праздновать! Давайте… давайте снова праздновать! Мои сокровища… мои драгоценные сокровища… теперь они все мои! Договорились… договорились! Хе-хе-хе… ик!.. охраняй их… для меня… хр-р-р…","attributes":[]},{"id":"09e7e74c-1d51-40c6-8867-093fe8f00821","name":"Охота за сокровищами","type":"Повседневный навык","iconUrl":"/nte-meta/game-assets/dbaa2a93db202cd3e691.webp","description":"- Ур.1\nУвеличивает количество предметов аукциона на 1 в каждом аукционе.\nМатериалы:\nСемя без снов×2\nФонс×100\n- Ур.2\nДает 1 дополнительную возможность обновить некупленные предметы аукциона в каждом аукционе.\nМатериалы:\nСемя без снов×6\nФонс×300\n- Ур.3\nУвеличивает количество предметов аукциона на 2 в каждом аукционе.\nМатериалы:\nСемя без снов×10\nФонс×720\n- Ур.4\nУ вас будет 2 возможности обновить некупленные предметы аукциона.\nМатериалы:\nСемя без снов×16\nФонс×1 400\n- Ур.5\nУвеличивает количество предметов аукциона на 3 в каждом аукционе.\nМатериалы:\nСемя без снов×24\nФонс×10 000","attributes":[{"id":"city-0","label":"Уровень 1","value":"Увеличивает количество предметов аукциона на 1 в каждом аукционе."},{"id":"city-1","label":"Уровень 2","value":"Дает 1 дополнительную возможность обновить некупленные предметы аукциона в каждом аукционе."},{"id":"city-2","label":"Уровень 3","value":"Увеличивает количество дополнительных предметов на каждом аукционе до 2."},{"id":"city-3","label":"Уровень 4","value":"У вас будет 2 возможности обновить некупленные предметы аукциона."},{"id":"city-4","label":"Уровень 5","value":"Увеличивает количество дополнительных предметов на каждом аукционе до 3."}]},{"id":"City_Ability_jin_01","name":"Деньги – что это такое","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/cf361c7f6b7bb5282e23.webp","description":"В режиме подборки владельца каждая подача правильного блюда клиенту (кроме Данзабуру) повышает цены до конца раунда. Не более 15 раз за раунд.","attributes":[{"id":"city-0","label":"Уровень 1","value":"В режиме подборки владельца каждая подача правильного блюда клиенту (кроме Данзабуру) повышает цены до конца раунда. Не более 15 раз за раунд."},{"id":"city-1","label":"Уровень 2","value":"Хотори дополнительно увеличивает цены блюд на 0"},{"id":"city-3","label":"Уровень 4","value":"Хотори дополнительно увеличивает привлекательность блюд на 0"},{"id":"city-4","label":"Уровень 5","value":"Хотори дополнительно увеличивает цены блюд на 0"}]}]') WHERE character_id='hotori' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-23 13:53:58');

UPDATE character_profiles SET skins_json=json('[{"id":"skin-4wy3fp","name":"Рекреационный двор","description":"Домашняя одежда Хотори. Удобный и лёгкий, ведь когда сидишь дома без дела, комфорт — главное.\n«Нежная птичья трель поутру».","imageUrl":"https://interactivemap.app/neverness-to-everness/database/assets/illustrations/YH_UI_shizhuang_big_xun2.png"},{"id":"skin-jsnnsx","name":"Бесценная орхидея","description":"Сшитый на заказ наряд в стиле призрачной орхидеи, который Хотори приобрела на остаток первичных инвестиций в открытие магазина… И не смогла с ним расстаться, даже когда ей пришлось продать машину из-за долгов. Видимо, он ей очень нравится.","imageUrl":"https://interactivemap.app/neverness-to-everness/database/assets/illustrations/YH_UI_shizhuang_big_xun3.png"},{"id":"skin-78zihs","name":"Под яркой луной","description":"По слухам, это кастомный наряд, созданный известным дизайнером специально для Хотори. На деньги от его продажи можно было бы открыть ещё десять «Эйбонов».\n«Под яркой луной орхидеи плачут в тишине, а вокруг бесконечно струится туман.»","imageUrl":"https://interactivemap.app/neverness-to-everness/database/assets/illustrations/YH_UI_shizhuang_big_xun.png"}]') WHERE character_id='hotori' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-23 13:53:58');

