UPDATE character_profiles SET skins_json=json('[{"id":"Fashion_1055_0","name":"Песнь иволги","description":"Платье, пропитанное ароматом роз, и широкополая шляпа, из-под которой виднеется лишь загадочный блеск глаз.","imageUrl":"/nte-meta/game-assets/3ef2136ec9e11fac23e0.webp"},{"id":"Fashion_1055_nighty","name":"Время самодисциплины","description":"Домашняя одежда Цзююань. Выглядит просто, но это дизайнерский костюм.\n\n«Вдох… выдох… потянись, пусть разум обретёт покой…»","imageUrl":"/nte-meta/game-assets/468f1f7f30fbc9f049fc.webp"}]') WHERE character_id='jiuyuan' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:10:34');

