UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Солнце, солнце, к тебе взываю!","iconUrl":"/nte-meta/game-assets/b8a3ee01b66c1a69be28.webp","description":"Увеличивает вместимость хранения зерна и зерна в долг на 10 %."},{"level":2,"kind":"awakening","name":"Фейерверки в тишине","iconUrl":"/nte-meta/game-assets/642095e2d231153edc51.webp","description":"Пока Чиз находится в состоянии «Избыток», каждую секунду начисляются проценты в размере 10 % от текущего количества зерна."},{"level":3,"kind":"awakening","name":"Если бы не было больше дождей","iconUrl":"/nte-meta/game-assets/6848bcde6b6c54a446e1.webp","description":"Увеличивает шанс на рост цены зерна на 50 %."},{"level":4,"kind":"awakening","name":"Онигири, бинты и фонс","iconUrl":"/nte-meta/game-assets/ac05a238a1e4a08f75ab.webp","description":"Увеличивает эффективность приобретения зерна на 20 %."},{"level":5,"kind":"awakening","name":"Пустые страницы дневника","iconUrl":"/nte-meta/game-assets/406a32487ed3af7d6c96.webp","description":"В начале боя Чиз мгновенно пополняет запас зерна до 100 % вместимости."},{"level":6,"kind":"awakening","name":"Тридцать три дня","iconUrl":"/nte-meta/game-assets/96fca88def1f25a38a49.webp","description":"Увеличивает бонусный урон космоса от зерна на 15 %."},{"level":3,"kind":"resonance","name":"Родные и близкие","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Увеличивает эффективность сбора зерна на дополнительные 50 %, пока действует состояние «Долг»."},{"level":6,"kind":"resonance","name":"Возвращение домой","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Когда Чиз наносит урон, снижает сопротивление космосу цели на 10 %."}]') WHERE character_id='chiz' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:12:29');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"ja-Play_Vo_Char_NPC026_chat_003","title":"Чат: Зарплата","description":"О, самая последняя модель…? Подумаю об этом, когда получу следующую зарплату.","language":"Японский","audioUrl":"/nte-meta/game-audio/e93defd47b8ba9590026.ogg"},{"id":"ja-Play_Vo_Char_NPC026_greet_001","title":"Утреннее приветствие","description":"Д-доброе утро! Ты, эм, хочешь что-нибудь поесть? Может, сэндвич? Или кофе? Или, эм, вообще что угодно… В-в общем, дай я приготовлю завтрак!","language":"Японский","audioUrl":"/nte-meta/game-audio/1ea80f40561d3d4e7a39.ogg"},{"id":"en-Play_Vo_Char_NPC026_anomaly_001","title":"Нуллификация I","description":"Спокойной ночи.","language":"Английский","audioUrl":"/nte-meta/game-audio/9eea1c341e131ada14ca.ogg"},{"id":"en-Play_Vo_Char_NPC026_kill_001","title":"Убийство I","description":"П-прости!","language":"Английский","audioUrl":"/nte-meta/game-audio/03e5bf27cb937dd19174.ogg"},{"id":"en-Play_Vo_Char_NPC026_meet_001","title":"Первая встреча","description":"Привет, я Чиз. Я работаю в банке «Розовые лапки», мой номер сотрудника 018888, проживаю по адресу: Променад Кайлен, Камелот-авеню, в районе Нью-Херланд… Ой, я слишком много болтаю? П-Простите!","language":"Английский","audioUrl":"/nte-meta/game-audio/3f9f207607c8be4f4e98.ogg"},{"id":"en-Play_Vo_Char_NPC026_Switch_003","title":"Переключение III","description":"Пожалуйста… доверьтесь мне!","language":"Английский","audioUrl":"/nte-meta/game-audio/c17645bdeacbde088ab8.ogg"},{"id":"ja-Play_Vo_Char_NPC026_containment_001","title":"Сдерживание I","description":"Так пойдёт?","language":"Японский","audioUrl":"/nte-meta/game-audio/53ab993b4e6ddeb0c205.ogg"},{"id":"en-Play_Vo_Char_NPC026_greet_004","title":"Спокойной ночи","description":"У нас в деревне всегда говорят: «Спокойная ночь без снов — залог удачного дня». Спокойной ночи. Надеюсь, завтра будет твой счастливый день.","language":"Английский","audioUrl":"/nte-meta/game-audio/8f059ad0d55a428e48dd.ogg"},{"id":"en-Play_Vo_Char_NPC026_ug_003","title":"Вознесение персонажа III","description":"В конце концов, мне удалось это сделать.","language":"Английский","audioUrl":"/nte-meta/game-audio/839dcdb1df6f88807166.ogg"},{"id":"ja-Play_Vo_Char_NPC026_chat_001","title":"Чат: Бабл-чай","description":"А, мне большой молочный чай с чёрным сахаром, крем-брюле, кокосовым желе, пудингом и сиропом «boba base», без льда, максимально сладкий… нет, подожди, э-э…!","language":"Японский","audioUrl":"/nte-meta/game-audio/21c44cbf915f76aed10e.ogg"},{"id":"en-Play_Vo_Char_NPC026_hp_002","title":"Низкий уровень здоровья II","description":"Я к этому привыкла.","language":"Английский","audioUrl":"/nte-meta/game-audio/a7f79eb5d07a4ec34771.ogg"},{"id":"en-Play_Vo_Char_NPC026_struck_002","title":"Урон II","description":"Да это всего лишь царапина.","language":"Английский","audioUrl":"/nte-meta/game-audio/61e45bcf25417012359c.ogg"},{"id":"ja-Play_Vo_Char_NPC026_greet_004","title":"Спокойной ночи","description":"У нас в деревне всегда говорят: «Спокойная ночь без снов — залог удачного дня». Спокойной ночи. Надеюсь, завтра будет твой счастливый день.","language":"Японский","audioUrl":"/nte-meta/game-audio/a4e456acf31becb565da.ogg"},{"id":"ja-Play_Vo_Char_NPC026_weather_002","title":"Дождливо","description":"Ой нет, дождь пошёл… Так и простудиться недолго. Пожалуйста, эм, постарайся не замёрзнуть, ладно?","language":"Японский","audioUrl":"/nte-meta/game-audio/70aecfe4505b456493db.ogg"},{"id":"en-Play_Vo_Char_NPC026_greet_001","title":"Утреннее приветствие","description":"Д-доброе утро! Ты, эм, хочешь что-нибудь поесть? Может, сэндвич? Или кофе? Или, эм, вообще что угодно… В-в общем, дай я приготовлю завтрак!","language":"Английский","audioUrl":"/nte-meta/game-audio/aa8de206aabfc2f9cf95.ogg"},{"id":"ja-Play_Vo_Char_NPC026_hp_001","title":"Низкий уровень здоровья I","description":"Всё в порядке, не беспокойся обо мне…","language":"Японский","audioUrl":"/nte-meta/game-audio/72c2d4663031e347c0fa.ogg"},{"id":"ja-Play_Vo_Char_NPC026_Parry_001","title":"Парирование I","description":"Отбила!","language":"Японский","audioUrl":"/nte-meta/game-audio/ffb9b3d147c47a837cb8.ogg"},{"id":"en-Play_Vo_Char_NPC026_anomaly_002","title":"Нуллификация II","description":"…теперь можно и домой.","language":"Английский","audioUrl":"/nte-meta/game-audio/46a5b27b6df1c81cdc0d.ogg"},{"id":"en-Play_Vo_Char_NPC026_self_002","title":"Обо мне: способность эспера","description":"С-способности эспера… они… д-действительно помогают. Супер п-практичные, о-очень полезные. Я-я эспер, так что… так что благодаря… этим способностям мне удалось переехать в Этеро. А ещё… благодаря моим способностям было совсем несложно найти работу. Быть эспером здесь… з-здорово. Мне здесь нравится.","language":"Английский","audioUrl":"/nte-meta/game-audio/cd4e468a56c6bdcd3d51.ogg"},{"id":"ja-Play_Vo_Char_NPC026_anomaly_002","title":"Нуллификация II","description":"…теперь можно и домой.","language":"Японский","audioUrl":"/nte-meta/game-audio/e060da7972123fdddeb4.ogg"},{"id":"en-Play_Vo_Char_NPC026_chat_002","title":"Чат: Выходные","description":"Хочешь сходить на озеро Калтроп в эти выходные? Я уже давно никуда не выбиралась… Н-нет, забудь. Мне лучше остаться дома.","language":"Английский","audioUrl":"/nte-meta/game-audio/9dc75690a089437ee89a.ogg"},{"id":"en-Play_Vo_Char_NPC026_DodgeCombo_002","title":"Серия критических уклонений II","description":"С моей юбкой… всё в порядке.","language":"Английский","audioUrl":"/nte-meta/game-audio/3d5d2d108180264c90f1.ogg"},{"id":"en-Play_Vo_Char_NPC026_Parry_001","title":"Парирование I","description":"Отбила!","language":"Английский","audioUrl":"/nte-meta/game-audio/5ba02b9a106f855a77bb.ogg"},{"id":"en-Play_Vo_Char_NPC026_Parry_002","title":"Парирование II","description":"Промаха не было!","language":"Английский","audioUrl":"/nte-meta/game-audio/afe95752f5a2a60daffc.ogg"},{"id":"ja-Play_Vo_Char_NPC026_meet_001","title":"Первая встреча","description":"Привет, я Чиз. Я работаю в банке «Розовые лапки», мой номер сотрудника 018888, проживаю по адресу: Променад Кайлен, Камелот-авеню, в районе Нью-Херланд… Ой, я слишком много болтаю? П-Простите!","language":"Японский","audioUrl":"/nte-meta/game-audio/cd7c6a2bf481dd5505a0.ogg"},{"id":"ja-Play_Vo_Char_NPC026_windfall_006","title":"Неожиданная добыча VI","description":"Я-я должна оставить это у себя?","language":"Японский","audioUrl":"/nte-meta/game-audio/2986b344f8bffb483bc9.ogg"},{"id":"en-Play_Vo_Char_NPC026_about_001","title":"Про Дворжака","description":"Семья Дворжак… они какие‑то… ну, необычные, что ли? Нет-нет, честно, я ничего плохого не имею в виду! Когда я впервые попала в Этеро, они приютили меня в своём временном убежище. Благодаря их фонду я смогла получить образование. Потом я устроилась в банк «Розовые лапки». По сути, почти все в Этеро — и местные, и приезжие — хоть раз да получили от них помощь. Такое чувство, что Дворжаки всё время просто… раздают деньги. И при этом вообще ничего не требуют взамен. Может, это и делает их хорошими людьми.","language":"Английский","audioUrl":"/nte-meta/game-audio/4433ef01a5ce0bc296ef.ogg"},{"id":"en-Play_Vo_Char_NPC026_aoe_UI_001","title":"Сверхспособность I","description":"Сотрудник номер 018888 к вашим услугам!","language":"Английский","audioUrl":"/nte-meta/game-audio/491e3966424f314f5e30.ogg"},{"id":"en-Play_Vo_Char_NPC026_containment_002","title":"Сдерживание II","description":"Я… сделала это правильно?","language":"Английский","audioUrl":"/nte-meta/game-audio/a7156a4d65c6730547ea.ogg"},{"id":"en-Play_Vo_Char_NPC026_self_003","title":"Обо мне: бинты","description":"Выглядит… не очень? Раньше я была… плоха во всём, постоянно получала травмы… Н-но сейчас я стала лучше! Я уже не так часто травмируюсь. Просто… мои старые шрамы некрасивые, вот я их и прикрыла. Коллега посоветовал эти бинты. Они мягкие и дышащие, так что не вызывают неприятных ощущений. Пожалуйста, не переживай за меня. Все раны уже зажили и больше не болят.","language":"Английский","audioUrl":"/nte-meta/game-audio/5c965f548aa9824445bd.ogg"},{"id":"ja-Play_Vo_Char_NPC026_fh_002","title":"Исцеление II","description":"Так тепло…","language":"Японский","audioUrl":"/nte-meta/game-audio/2418aa130749dd0df34e.ogg"},{"id":"ja-Play_Vo_Char_NPC026_skill_001","title":"Навык перенаправления I","description":"Договорились.","language":"Японский","audioUrl":"/nte-meta/game-audio/d87e3788cc02f4065fa0.ogg"},{"id":"en-Play_Vo_Char_NPC026_deploy_001","title":"Отправка I","description":"Ты правда выбрал меня? Уверен? Ты правда выбрала меня? Уверена?","language":"Английский","audioUrl":"/nte-meta/game-audio/4710f6d46289bca902ac.ogg"},{"id":"en-Play_Vo_Char_NPC026_struck_001","title":"Урон I","description":"Я в порядке.","language":"Английский","audioUrl":"/nte-meta/game-audio/9ac83742ec7a898918d7.ogg"},{"id":"ja-Play_Vo_Char_NPC026_containment_002","title":"Сдерживание II","description":"Я… сделала это правильно?","language":"Японский","audioUrl":"/nte-meta/game-audio/16d178f3c36a5b3f4e9f.ogg"},{"id":"ja-Play_Vo_Char_NPC026_hobby_001","title":"Хобби","description":"Мне нравятся фонсы… хм, правда. Фонсы — это ведь необходимая вещь, понимаешь? Еда, лекарства, одежда… ничего из этого не возникает из ниоткуда. За всё надо платить. Но иногда я думаю, а действительно ли фонсы настолько важны… То есть, как только я накоплю достаточно, чтобы вернуться домой, может, они уже не будут так много значить. Хотя всё равно, это огромная сумма. Скорее всего, мне придётся работать в банке «Розовые лапки» до самой пенсии.","language":"Японский","audioUrl":"/nte-meta/game-audio/35c516ad4469e1ce0873.ogg"},{"id":"ja-Play_Vo_Char_NPC026_hstruck_001","title":"Сильный урон I","description":"Я не задержу тебя…","language":"Японский","audioUrl":"/nte-meta/game-audio/260def1d1b7aa8592ab9.ogg"},{"id":"ja-Play_Vo_Char_NPC026_aoe_UI_003","title":"Сверхспособность III","description":"Теперь у вас есть страховка от несчастных случаев.","language":"Японский","audioUrl":"/nte-meta/game-audio/e42b0b047c6aede34807.ogg"},{"id":"ja-Play_Vo_Char_NPC026_hp_002","title":"Низкий уровень здоровья II","description":"Я к этому привыкла.","language":"Японский","audioUrl":"/nte-meta/game-audio/1922ed554f6da1c7da38.ogg"},{"id":"en-Play_Vo_Char_NPC026_weather_001","title":"Солнечно","description":"Солнышко такое тёплое… Сейчас бы просто закрыть глаза и уснуть.","language":"Английский","audioUrl":"/nte-meta/game-audio/bede1f4baffe60ae8c80.ogg"},{"id":"en-Play_Vo_Char_NPC026_gift_001","title":"Подарок получен I","description":"М-мне очень нравится! П-правда!","language":"Английский","audioUrl":"/nte-meta/game-audio/3191bca5ef80979e91fc.ogg"},{"id":"en-Play_Vo_Char_NPC026_vexation_001","title":"Проблемы","description":"Проблемы, да… Когда я только устроилась в банк «Розовые лапки», у меня вообще ничего не получалось… Я не преувеличиваю, это правда. Я стояла в этом шикарном холле в своей новой форме и не могла заговорить ни с кем. Я так боялась всё испортить, что даже думала уволиться. А потом… появилась Колинсна. Она… невероятная, как солнце, прорвавшееся сквозь тучи. Если бы я только могла светить хотя бы вполовину так же ярко, как она… Я понимаю, что до неё мне очень далеко, но, честно говоря, я довольна своей жизнью такой, какая она есть.","language":"Английский","audioUrl":"/nte-meta/game-audio/e9a4029ff77a4ec0d3a1.ogg"},{"id":"ja-Play_Vo_Char_NPC026_fh_001","title":"Исцеление I","description":"Гораздо, гораздо лучше. С-спасибо.","language":"Японский","audioUrl":"/nte-meta/game-audio/c223862fe671764fb1b4.ogg"},{"id":"ja-Play_Vo_Char_NPC026_Parry_002","title":"Парирование II","description":"Промаха не было!","language":"Японский","audioUrl":"/nte-meta/game-audio/52c7129f9807f7efc245.ogg"},{"id":"en-Play_Vo_Char_NPC026_greet_002","title":"Дневное приветствие","description":"Добрый день. Тебе нужен перерыв? У нас есть… целых два часа на обед.","language":"Английский","audioUrl":"/nte-meta/game-audio/b61098a8235c5c2fb990.ogg"},{"id":"ja-Play_Vo_Char_NPC026_dead_002","title":"Потеря сознания II","description":"Мне так холодно и так одиноко…","language":"Японский","audioUrl":"/nte-meta/game-audio/c18fa33540a6dbfc58ad.ogg"},{"id":"ja-Play_Vo_Char_NPC026_self_002","title":"Обо мне: способность эспера","description":"С-способности эспера… они… д-действительно помогают. Супер п-практичные, о-очень полезные. Я-я эспер, так что… так что благодаря… этим способностям мне удалось переехать в Этеро. А ещё… благодаря моим способностям было совсем несложно найти работу. Быть эспером здесь… з-здорово. Мне здесь нравится.","language":"Японский","audioUrl":"/nte-meta/game-audio/12c38d6b5d8453a99ff5.ogg"},{"id":"ja-Play_Vo_Char_NPC026_weather_003","title":"Холодно","description":"Уф… как же холодно. В такое время лучше всего прижаться к родным — ничто не согревает быстрее.","language":"Японский","audioUrl":"/nte-meta/game-audio/3eecc1c3334802143767.ogg"},{"id":"ja-Play_Vo_Char_NPC026_greet_003","title":"Вечернее приветствие","description":"Секундочку, я почти закончила! Эй… может, поужинаем вместе?","language":"Японский","audioUrl":"/nte-meta/game-audio/20a1d3adb42b986f06b0.ogg"},{"id":"ja-Play_Vo_Char_NPC026_aoe_UI_002","title":"Сверхспособность II","description":"С-спасибо, что выбрали банк «Розовые лапки»!","language":"Японский","audioUrl":"/nte-meta/game-audio/af47107f571af0bd89a4.ogg"},{"id":"en-Play_Vo_Char_NPC026_DodgeCombo_001","title":"Серия критических уклонений I","description":"Фух, я увернулась!","language":"Английский","audioUrl":"/nte-meta/game-audio/fd9ca669be310eee1123.ogg"},{"id":"en-Play_Vo_Char_NPC026_Fly_001","title":"Планирование I","description":"Мои ноги… не касаются земли…","language":"Английский","audioUrl":"/nte-meta/game-audio/7a91e7252614b67ca330.ogg"},{"id":"ja-Play_Vo_Char_NPC026_skill_003","title":"Навык перенаправления III","description":"Покупаю на росте!","language":"Японский","audioUrl":"/nte-meta/game-audio/e7000dc674b0dfcbc282.ogg"},{"id":"ja-Play_Vo_Char_NPC026_vexation_001","title":"Проблемы","description":"Проблемы, да… Когда я только устроилась в банк «Розовые лапки», у меня вообще ничего не получалось… Я не преувеличиваю, это правда. Я стояла в этом шикарном холле в своей новой форме и не могла заговорить ни с кем. Я так боялась всё испортить, что даже думала уволиться. А потом… появилась Колинсна. Она… невероятная, как солнце, прорвавшееся сквозь тучи. Если бы я только могла светить хотя бы вполовину так же ярко, как она… Я понимаю, что до неё мне очень далеко, но, честно говоря, я довольна своей жизнью такой, какая она есть.","language":"Японский","audioUrl":"/nte-meta/game-audio/4dd74c4edcdcbf14071d.ogg"},{"id":"ja-Play_Vo_Char_NPC026_weather_004","title":"Жарко","description":"Скучаю по кондиционеру в банке «Розовые лапки». Там всегда так холодно, будто этот холод у них дармовой.","language":"Японский","audioUrl":"/nte-meta/game-audio/1206d52e032423e5a700.ogg"},{"id":"en-Play_Vo_Char_NPC026_dead_001","title":"Потеря сознания I","description":"Мама, я хочу домой…","language":"Английский","audioUrl":"/nte-meta/game-audio/f7227c5aea5591cfcdbe.ogg"},{"id":"en-Play_Vo_Char_NPC026_windfall_001","title":"Неожиданная добыча I","description":"Можно… я это возьму?","language":"Английский","audioUrl":"/nte-meta/game-audio/0241d916b51bdbd6165e.ogg"},{"id":"ja-Play_Vo_Char_NPC026_about_001","title":"Про Дворжака","description":"Семья Дворжак… они какие‑то… ну, необычные, что ли? Нет-нет, честно, я ничего плохого не имею в виду! Когда я впервые попала в Этеро, они приютили меня в своём временном убежище. Благодаря их фонду я смогла получить образование. Потом я устроилась в банк «Розовые лапки». По сути, почти все в Этеро — и местные, и приезжие — хоть раз да получили от них помощь. Такое чувство, что Дворжаки всё время просто… раздают деньги. И при этом вообще ничего не требуют взамен. Может, это и делает их хорошими людьми.","language":"Японский","audioUrl":"/nte-meta/game-audio/8f2b00923e2e9938f0aa.ogg"},{"id":"ja-Play_Vo_Char_NPC026_dead_003","title":"Потеря сознания III","description":"Я всё ещё… недостаточно хороша…","language":"Японский","audioUrl":"/nte-meta/game-audio/a6dff358a00683f740fc.ogg"},{"id":"ja-Play_Vo_Char_NPC026_DodgeCombo_002","title":"Серия критических уклонений II","description":"С моей юбкой… всё в порядке.","language":"Японский","audioUrl":"/nte-meta/game-audio/9e46b0fd89e3e82bdf70.ogg"},{"id":"ja-Play_Vo_Char_NPC026_gift_003","title":"Подарок получен III","description":"Это м-мне? Спасибо!","language":"Японский","audioUrl":"/nte-meta/game-audio/5c57e527840a14e5246e.ogg"},{"id":"ja-Play_Vo_Char_NPC026_windfall_005","title":"Неожиданная добыча V","description":"Неужели мне… действительно так повезло?","language":"Японский","audioUrl":"/nte-meta/game-audio/cd7ca6666b2a3ee0cde6.ogg"},{"id":"ja-Play_Vo_Char_NPC026_greet_002","title":"Дневное приветствие","description":"Добрый день. Тебе нужен перерыв? У нас есть… целых два часа на обед.","language":"Японский","audioUrl":"/nte-meta/game-audio/808605604164af840dba.ogg"},{"id":"ja-Play_Vo_Char_NPC026_dead_001","title":"Потеря сознания I","description":"Мама, я хочу домой…","language":"Японский","audioUrl":"/nte-meta/game-audio/f569bcddf45f9a9d0b93.ogg"},{"id":"ja-Play_Vo_Char_NPC026_QTE_003","title":"Атака на входе III","description":"Успела!","language":"Японский","audioUrl":"/nte-meta/game-audio/44d9f7ba9ec2465c3cb6.ogg"},{"id":"en-Play_Vo_Char_NPC026_chat_003","title":"Чат: Зарплата","description":"О, самая последняя модель…? Подумаю об этом, когда получу следующую зарплату.","language":"Английский","audioUrl":"/nte-meta/game-audio/a25a814e85627321a438.ogg"},{"id":"ja-Play_Vo_Char_NPC026_gift_004","title":"Подарок получен IV","description":"Я… я тоже обязательно подарю тебе что-нибудь! П-прими потом мой подарок, пожалуйста!","language":"Японский","audioUrl":"/nte-meta/game-audio/7d1a829d64cf75a75a15.ogg"},{"id":"en-Play_Vo_Char_NPC026_dead_003","title":"Потеря сознания III","description":"Я всё ещё… недостаточно хороша…","language":"Английский","audioUrl":"/nte-meta/game-audio/9d892ca6cd09e2b6e972.ogg"},{"id":"en-Play_Vo_Char_NPC026_deploy_002","title":"Отправка II","description":"Я… я постараюсь изо всех сил!","language":"Английский","audioUrl":"/nte-meta/game-audio/dce7f23be8e6340eeb96.ogg"},{"id":"en-Play_Vo_Char_NPC026_weather_002","title":"Дождливо","description":"Ой нет, дождь пошёл… Так и простудиться недолго. Пожалуйста, эм, постарайся не замёрзнуть, ладно?","language":"Английский","audioUrl":"/nte-meta/game-audio/a41bed605f398566904d.ogg"},{"id":"en-Play_Vo_Char_NPC026_weather_003","title":"Холодно","description":"Уф… как же холодно. В такое время лучше всего прижаться к родным — ничто не согревает быстрее.","language":"Английский","audioUrl":"/nte-meta/game-audio/63985a1da1850f32cd99.ogg"},{"id":"en-Play_Vo_Char_NPC026_gift_003","title":"Подарок получен III","description":"Это м-мне? Спасибо!","language":"Английский","audioUrl":"/nte-meta/game-audio/e40fed8e040b76b61c2c.ogg"},{"id":"ja-Play_Vo_Char_NPC026_Switch_001","title":"Переключение I","description":"П-предоставь это мне!","language":"Японский","audioUrl":"/nte-meta/game-audio/31fd6a02f5eee08ebf1f.ogg"},{"id":"ja-Play_Vo_Char_NPC026_QTE_001","title":"Атака на входе I","description":"И-иду!","language":"Японский","audioUrl":"/nte-meta/game-audio/986b40187a6b443d099f.ogg"},{"id":"ja-Play_Vo_Char_NPC026_self_001","title":"Обо мне: склонность к накоплению","description":"Когда я нахожу вещи, которые мне нравятся, я в итоге… начинаю собирать и собирать их…в огромном количестве. Но я клянусь, все они хранятся аккуратно и по полочкам. Это просто… привычка. Как будто мне спокойнее, когда у меня есть огромная куча всяких вещей вместе.","language":"Японский","audioUrl":"/nte-meta/game-audio/bd136c52101f757d94da.ogg"},{"id":"ja-Play_Vo_Char_NPC026_struck_001","title":"Урон I","description":"Я в порядке.","language":"Японский","audioUrl":"/nte-meta/game-audio/46f957e7698671dd3b58.ogg"},{"id":"ja-Play_Vo_Char_NPC026_Switch_003","title":"Переключение III","description":"Пожалуйста… доверьтесь мне!","language":"Японский","audioUrl":"/nte-meta/game-audio/afeccda4b0ad5bbf67ed.ogg"},{"id":"ja-Play_Vo_Char_NPC026_ug_001","title":"Вознесение персонажа I","description":"Вау, какое странное чувство…","language":"Японский","audioUrl":"/nte-meta/game-audio/66ace1056bb4ff94b579.ogg"},{"id":"ja-Play_Vo_Char_NPC026_ug_003","title":"Вознесение персонажа III","description":"В конце концов, мне удалось это сделать.","language":"Японский","audioUrl":"/nte-meta/game-audio/2d0395ec5d97d234b62e.ogg"},{"id":"en-Play_Vo_Char_NPC026_kill_002","title":"Убийство II","description":"Никто не пострадал?","language":"Английский","audioUrl":"/nte-meta/game-audio/5db07189c504cd5af3b3.ogg"},{"id":"en-Play_Vo_Char_NPC026_QTE_002","title":"Атака на входе II","description":"Осторожно, столкновение!","language":"Английский","audioUrl":"/nte-meta/game-audio/87ee7ce39143ea962372.ogg"},{"id":"ja-Play_Vo_Char_NPC026_hp_003","title":"Низкий уровень здоровья III","description":"Не больно. Не больно.","language":"Японский","audioUrl":"/nte-meta/game-audio/4baaaf5342bcd31b0eea.ogg"},{"id":"ja-Play_Vo_Char_NPC026_talk_003","title":"Тема: мини-маркет","description":"Если зайти в «Два-Четыре» ночью, они иногда продают рисовые шарики со скидкой. На вкус они такие же, как утренние, но стоят гораздо дешевле. Идеально для ночного перекуса. Единственный минус — их нужно съесть в тот же день, а то они быстро портятся. Эм… я-я тоже неплохо делаю рисовые шарики. Как насчёт того, чтобы… попробовать?","language":"Японский","audioUrl":"/nte-meta/game-audio/ddab07a3e3f73584aa98.ogg"},{"id":"en-Play_Vo_Char_NPC026_aoe_UI_003","title":"Сверхспособность III","description":"Теперь у вас есть страховка от несчастных случаев.","language":"Английский","audioUrl":"/nte-meta/game-audio/e7ccfef35198edfafd97.ogg"},{"id":"en-Play_Vo_Char_NPC026_talk_003","title":"Тема: мини-маркет","description":"Если зайти в «Два-Четыре» ночью, они иногда продают рисовые шарики со скидкой. На вкус они такие же, как утренние, но стоят гораздо дешевле. Идеально для ночного перекуса. Единственный минус — их нужно съесть в тот же день, а то они быстро портятся. Эм… я-я тоже неплохо делаю рисовые шарики. Как насчёт того, чтобы… попробовать?","language":"Английский","audioUrl":"/nte-meta/game-audio/5579e949e8ca9d2aca90.ogg"},{"id":"ja-Play_Vo_Char_NPC026_deploy_001","title":"Отправка I","description":"Ты правда выбрал меня? Уверен? Ты правда выбрала меня? Уверена?","language":"Японский","audioUrl":"/nte-meta/game-audio/ad5f77f0dc08bab05f91.ogg"},{"id":"ja-Play_Vo_Char_NPC026_windfall_003","title":"Неожиданная добыча III","description":"Деньги — вещь ценная… их нужно беречь.","language":"Японский","audioUrl":"/nte-meta/game-audio/18da6fb98e05854bb359.ogg"},{"id":"en-Play_Vo_Char_NPC026_greet_003","title":"Вечернее приветствие","description":"Секундочку, я почти закончила! Эй… может, поужинаем вместе?","language":"Английский","audioUrl":"/nte-meta/game-audio/ea510b0a768fc2e3d8aa.ogg"},{"id":"en-Play_Vo_Char_NPC026_windfall_004","title":"Неожиданная добыча IV","description":"Если ты хочешь положить их в банк «Розовые лапки», я бы посоветовала… Ой, п-прости!","language":"Английский","audioUrl":"/nte-meta/game-audio/6162f477883329c376d0.ogg"},{"id":"ja-Play_Vo_Char_NPC026_talk_002","title":"Тема: фильмы","description":"Когда я не на работе, я дома смотрю фильмы. Почти все из них интересные, потому что они переносят меня в места, где я никогда не была. Я… я почти не путешествовала, так что каждый раз, когда смотрю фильм, невольно думаю, как бы мне хотелось побывать в этих местах, если бы я только могла. В одном документальном фильме даже показали мой родной город… Эм, кажется, я слишком много говорю. Просто… забудь, что я сказала. Может… мы как‑нибудь посмотрим фильм вместе? Если с тобой, то даже ужастик… было бы нормально!","language":"Японский","audioUrl":"/nte-meta/game-audio/7e8c34e8eda4af430c16.ogg"},{"id":"en-Play_Vo_Char_NPC026_dead_002","title":"Потеря сознания II","description":"Мне так холодно и так одиноко…","language":"Английский","audioUrl":"/nte-meta/game-audio/5e26018de515bc505456.ogg"},{"id":"en-Play_Vo_Char_NPC026_QTE_001","title":"Атака на входе I","description":"И-иду!","language":"Английский","audioUrl":"/nte-meta/game-audio/29b95c8472dcb15d33e5.ogg"},{"id":"ja-Play_Vo_Char_NPC026_gift_002","title":"Подарок получен II","description":"С-спасибо! П-прости… Я… я даже не знаю, что сказать… Я буду хранить его и беречь очень-очень долго!","language":"Японский","audioUrl":"/nte-meta/game-audio/4ac70897017423be5521.ogg"},{"id":"en-Play_Vo_Char_NPC026_hobby_001","title":"Хобби","description":"Мне нравятся фонсы… хм, правда. Фонсы — это ведь необходимая вещь, понимаешь? Еда, лекарства, одежда… ничего из этого не возникает из ниоткуда. За всё надо платить. Но иногда я думаю, а действительно ли фонсы настолько важны… То есть, как только я накоплю достаточно, чтобы вернуться домой, может, они уже не будут так много значить. Хотя всё равно, это огромная сумма. Скорее всего, мне придётся работать в банке «Розовые лапки» до самой пенсии.","language":"Английский","audioUrl":"/nte-meta/game-audio/e9f7bf3454bf239531fb.ogg"},{"id":"en-Play_Vo_Char_NPC026_skill_001","title":"Навык перенаправления I","description":"Договорились.","language":"Английский","audioUrl":"/nte-meta/game-audio/4a4c959e908588542713.ogg"},{"id":"en-Play_Vo_Char_NPC026_chat_001","title":"Чат: Бабл-чай","description":"А, мне большой молочный чай с чёрным сахаром, крем-брюле, кокосовым желе, пудингом и сиропом «boba base», без льда, максимально сладкий… нет, подожди, э-э…!","language":"Английский","audioUrl":"/nte-meta/game-audio/7cc1393796ffc30114ee.ogg"},{"id":"en-Play_Vo_Char_NPC026_hp_003","title":"Низкий уровень здоровья III","description":"Не больно. Не больно.","language":"Английский","audioUrl":"/nte-meta/game-audio/1bf2905534e54004a01b.ogg"},{"id":"en-Play_Vo_Char_NPC026_Switch_002","title":"Переключение II","description":"Я справлюсь!","language":"Английский","audioUrl":"/nte-meta/game-audio/129aa4f8f1f225ed0797.ogg"},{"id":"ja-Play_Vo_Char_NPC026_windfall_002","title":"Неожиданная добыча II","description":"Э-э, давай я… помогу тебе с этим.","language":"Японский","audioUrl":"/nte-meta/game-audio/67a28e03e330ccc90bb1.ogg"},{"id":"en-Play_Vo_Char_NPC026_aoe_UI_002","title":"Сверхспособность II","description":"С-спасибо, что выбрали банк «Розовые лапки»!","language":"Английский","audioUrl":"/nte-meta/game-audio/c6ed8199a434fedbabea.ogg"},{"id":"ja-Play_Vo_Char_NPC026_Fly_002","title":"Планирование II","description":"Эх… мы уже на месте?","language":"Японский","audioUrl":"/nte-meta/game-audio/00fe838c581a600f7ce5.ogg"},{"id":"en-Play_Vo_Char_NPC026_fh_001","title":"Исцеление I","description":"Гораздо, гораздо лучше. С-спасибо.","language":"Английский","audioUrl":"/nte-meta/game-audio/3c2b576465d459715bd6.ogg"},{"id":"en-Play_Vo_Char_NPC026_skill_003","title":"Навык перенаправления III","description":"Покупаю на росте!","language":"Английский","audioUrl":"/nte-meta/game-audio/147875ee39ab7ae56ab6.ogg"},{"id":"en-Play_Vo_Char_NPC026_weather_004","title":"Жарко","description":"Скучаю по кондиционеру в банке «Розовые лапки». Там всегда так холодно, будто этот холод у них дармовой.","language":"Английский","audioUrl":"/nte-meta/game-audio/203e26d1f287c8ee27ed.ogg"},{"id":"ja-Play_Vo_Char_NPC026_QTE_002","title":"Атака на входе II","description":"Осторожно, столкновение!","language":"Японский","audioUrl":"/nte-meta/game-audio/1db09bcbd1759d0e05ce.ogg"},{"id":"ja-Play_Vo_Char_NPC026_talk_001","title":"Тема: аномалии","description":"Этеро… замечательный город. Обычные люди, аномалии и эсперы здесь живут вместе, на равных. Тут спокойно и безопасно. У меня дома всё совсем не так. Большинство аномалий опасны, и от них нужно держаться подальше. Хотя… некоторые из них съедобны… Ой, прости, наверное, это не очень интересно. Но если тебе любопытно… мы можем поговорить об этом как-нибудь позже.","language":"Японский","audioUrl":"/nte-meta/game-audio/d4c3ba6a5aca540e6537.ogg"},{"id":"en-Play_Vo_Char_NPC026_Fly_002","title":"Планирование II","description":"Эх… мы уже на месте?","language":"Английский","audioUrl":"/nte-meta/game-audio/ead535d4c6c5784b11f5.ogg"},{"id":"ja-Play_Vo_Char_NPC026_DodgeCombo_001","title":"Серия критических уклонений I","description":"Фух, я увернулась!","language":"Японский","audioUrl":"/nte-meta/game-audio/b35f001af739ab40a85c.ogg"},{"id":"ja-Play_Vo_Char_NPC026_Fly_001","title":"Планирование I","description":"Мои ноги… не касаются земли…","language":"Японский","audioUrl":"/nte-meta/game-audio/a4b46d9c8ebf9ef8dfec.ogg"},{"id":"en-Play_Vo_Char_NPC026_Switch_001","title":"Переключение I","description":"П-предоставь это мне!","language":"Английский","audioUrl":"/nte-meta/game-audio/980597be90ff4e215664.ogg"},{"id":"ja-Play_Vo_Char_NPC026_gift_001","title":"Подарок получен I","description":"М-мне очень нравится! П-правда!","language":"Японский","audioUrl":"/nte-meta/game-audio/68c16650289cfb2819db.ogg"},{"id":"ja-Play_Vo_Char_NPC026_deploy_002","title":"Отправка II","description":"Я… я постараюсь изо всех сил!","language":"Японский","audioUrl":"/nte-meta/game-audio/59042d4ebf3db2b72cba.ogg"},{"id":"ja-Play_Vo_Char_NPC026_kill_002","title":"Убийство II","description":"Никто не пострадал?","language":"Японский","audioUrl":"/nte-meta/game-audio/4b73a26c42987f4778ab.ogg"},{"id":"en-Play_Vo_Char_NPC026_QTE_003","title":"Атака на входе III","description":"Успела!","language":"Английский","audioUrl":"/nte-meta/game-audio/efe5344a742c869a12df.ogg"},{"id":"ja-Play_Vo_Char_NPC026_skill_002","title":"Навык перенаправления II","description":"Добавляю позиции!","language":"Японский","audioUrl":"/nte-meta/game-audio/af26e2b225c088310100.ogg"},{"id":"en-Play_Vo_Char_NPC026_ug_002","title":"Вознесение персонажа II","description":"Стану ли я… полезнее?","language":"Английский","audioUrl":"/nte-meta/game-audio/ecda232ac4e56b72f54a.ogg"},{"id":"en-Play_Vo_Char_NPC026_windfall_005","title":"Неожиданная добыча V","description":"Неужели мне… действительно так повезло?","language":"Английский","audioUrl":"/nte-meta/game-audio/afcf08f21e3571a94f58.ogg"},{"id":"ja-Play_Vo_Char_NPC026_chat_002","title":"Чат: Выходные","description":"Хочешь сходить на озеро Калтроп в эти выходные? Я уже давно никуда не выбиралась… Н-нет, забудь. Мне лучше остаться дома.","language":"Японский","audioUrl":"/nte-meta/game-audio/c0ac3ad55cfc016de93d.ogg"},{"id":"ja-Play_Vo_Char_NPC026_Switch_002","title":"Переключение II","description":"Я справлюсь!","language":"Японский","audioUrl":"/nte-meta/game-audio/7f1558311c634379ef55.ogg"},{"id":"ja-Play_Vo_Char_NPC026_struck_002","title":"Урон II","description":"Да это всего лишь царапина.","language":"Японский","audioUrl":"/nte-meta/game-audio/fe1f115bd6e491284ce5.ogg"},{"id":"en-Play_Vo_Char_NPC026_skill_002","title":"Навык перенаправления II","description":"Добавляю позиции!","language":"Английский","audioUrl":"/nte-meta/game-audio/a4247aa0bf136533010b.ogg"},{"id":"en-Play_Vo_Char_NPC026_ug_001","title":"Вознесение персонажа I","description":"Вау, какое странное чувство…","language":"Английский","audioUrl":"/nte-meta/game-audio/e3a1bf8f580256237c17.ogg"},{"id":"en-Play_Vo_Char_NPC026_windfall_006","title":"Неожиданная добыча VI","description":"Я-я должна оставить это у себя?","language":"Английский","audioUrl":"/nte-meta/game-audio/f78e482efabfcab9b62d.ogg"},{"id":"ja-Play_Vo_Char_NPC026_self_003","title":"Обо мне: бинты","description":"Выглядит… не очень? Раньше я была… плоха во всём, постоянно получала травмы… Н-но сейчас я стала лучше! Я уже не так часто травмируюсь. Просто… мои старые шрамы некрасивые, вот я их и прикрыла. Коллега посоветовал эти бинты. Они мягкие и дышащие, так что не вызывают неприятных ощущений. Пожалуйста, не переживай за меня. Все раны уже зажили и больше не болят.","language":"Японский","audioUrl":"/nte-meta/game-audio/4619414aed8c8fac7d09.ogg"},{"id":"ja-Play_Vo_Char_NPC026_weather_001","title":"Солнечно","description":"Солнышко такое тёплое… Сейчас бы просто закрыть глаза и уснуть.","language":"Японский","audioUrl":"/nte-meta/game-audio/d532df9188f5b403c8e7.ogg"},{"id":"ja-Play_Vo_Char_NPC026_windfall_001","title":"Неожиданная добыча I","description":"Можно… я это возьму?","language":"Японский","audioUrl":"/nte-meta/game-audio/52d95ba1523a586a4859.ogg"},{"id":"en-Play_Vo_Char_NPC026_gift_004","title":"Подарок получен IV","description":"Я… я тоже обязательно подарю тебе что-нибудь! П-прими потом мой подарок, пожалуйста!","language":"Английский","audioUrl":"/nte-meta/game-audio/b287bd69fc198438c354.ogg"},{"id":"ja-Play_Vo_Char_NPC026_hstruck_002","title":"Сильный урон II","description":"Прости, я…","language":"Японский","audioUrl":"/nte-meta/game-audio/feda82d9aaccde696844.ogg"},{"id":"en-Play_Vo_Char_NPC026_hstruck_002","title":"Сильный урон II","description":"Прости, я…","language":"Английский","audioUrl":"/nte-meta/game-audio/989ae27148b6114307aa.ogg"},{"id":"en-Play_Vo_Char_NPC026_fh_002","title":"Исцеление II","description":"Так тепло…","language":"Английский","audioUrl":"/nte-meta/game-audio/4ae162fab27983c939cb.ogg"},{"id":"en-Play_Vo_Char_NPC026_talk_001","title":"Тема: аномалии","description":"Этеро… замечательный город. Обычные люди, аномалии и эсперы здесь живут вместе, на равных. Тут спокойно и безопасно. У меня дома всё совсем не так. Большинство аномалий опасны, и от них нужно держаться подальше. Хотя… некоторые из них съедобны… Ой, прости, наверное, это не очень интересно. Но если тебе любопытно… мы можем поговорить об этом как-нибудь позже.","language":"Английский","audioUrl":"/nte-meta/game-audio/efc5830131dbaea8fe41.ogg"},{"id":"en-Play_Vo_Char_NPC026_talk_002","title":"Тема: фильмы","description":"Когда я не на работе, я дома смотрю фильмы. Почти все из них интересные, потому что они переносят меня в места, где я никогда не была. Я… я почти не путешествовала, так что каждый раз, когда смотрю фильм, невольно думаю, как бы мне хотелось побывать в этих местах, если бы я только могла. В одном документальном фильме даже показали мой родной город… Эм, кажется, я слишком много говорю. Просто… забудь, что я сказала. Может… мы как‑нибудь посмотрим фильм вместе? Если с тобой, то даже ужастик… было бы нормально!","language":"Английский","audioUrl":"/nte-meta/game-audio/8e777cb6fce216583d84.ogg"},{"id":"ja-Play_Vo_Char_NPC026_kill_001","title":"Убийство I","description":"П-прости!","language":"Японский","audioUrl":"/nte-meta/game-audio/f08a71dbb8a408741786.ogg"},{"id":"en-Play_Vo_Char_NPC026_gift_002","title":"Подарок получен II","description":"С-спасибо! П-прости… Я… я даже не знаю, что сказать… Я буду хранить его и беречь очень-очень долго!","language":"Английский","audioUrl":"/nte-meta/game-audio/2aec99bded5ceb4200aa.ogg"},{"id":"en-Play_Vo_Char_NPC026_windfall_002","title":"Неожиданная добыча II","description":"Э-э, давай я… помогу тебе с этим.","language":"Английский","audioUrl":"/nte-meta/game-audio/d15569601271a66884cc.ogg"},{"id":"ja-Play_Vo_Char_NPC026_anomaly_001","title":"Нуллификация I","description":"Спокойной ночи.","language":"Японский","audioUrl":"/nte-meta/game-audio/7fd02a6bb97457a9dfa8.ogg"},{"id":"ja-Play_Vo_Char_NPC026_windfall_004","title":"Неожиданная добыча IV","description":"Если ты хочешь положить их в банк «Розовые лапки», я бы посоветовала… Ой, п-прости!","language":"Японский","audioUrl":"/nte-meta/game-audio/18f80c7d086625747944.ogg"},{"id":"en-Play_Vo_Char_NPC026_hp_001","title":"Низкий уровень здоровья I","description":"Всё в порядке, не беспокойся обо мне…","language":"Английский","audioUrl":"/nte-meta/game-audio/00974b1e7645186d5fbb.ogg"},{"id":"ja-Play_Vo_Char_NPC026_aoe_UI_001","title":"Сверхспособность I","description":"Сотрудник номер 018888 к вашим услугам!","language":"Японский","audioUrl":"/nte-meta/game-audio/11a4dc2ecf0c51a65d6d.ogg"},{"id":"en-Play_Vo_Char_NPC026_containment_001","title":"Сдерживание I","description":"Так пойдёт?","language":"Английский","audioUrl":"/nte-meta/game-audio/4e30de3298f3118534f0.ogg"},{"id":"en-Play_Vo_Char_NPC026_hstruck_001","title":"Сильный урон I","description":"Я не задержу тебя…","language":"Английский","audioUrl":"/nte-meta/game-audio/01f72331f00651b284fb.ogg"},{"id":"en-Play_Vo_Char_NPC026_self_001","title":"Обо мне: склонность к накоплению","description":"Когда я нахожу вещи, которые мне нравятся, я в итоге… начинаю собирать и собирать их…в огромном количестве. Но я клянусь, все они хранятся аккуратно и по полочкам. Это просто… привычка. Как будто мне спокойнее, когда у меня есть огромная куча всяких вещей вместе.","language":"Английский","audioUrl":"/nte-meta/game-audio/82dce6990f03c9e4a550.ogg"},{"id":"en-Play_Vo_Char_NPC026_windfall_003","title":"Неожиданная добыча III","description":"Деньги — вещь ценная… их нужно беречь.","language":"Английский","audioUrl":"/nte-meta/game-audio/2fe0ddcc854e70bebec6.ogg"},{"id":"ja-Play_Vo_Char_NPC026_ug_002","title":"Вознесение персонажа II","description":"Стану ли я… полезнее?","language":"Японский","audioUrl":"/nte-meta/game-audio/d94ebe0729314d856567.ogg"},{"id":"a02bb7df-11c6-44c2-a863-230018d41023","title":"Chiz Voice Records / Profile Voice Lines — Английский","language":"Английский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=y94feRER9KI","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."},{"id":"4185d575-985c-4dd5-bd43-917a8e832e83","title":"Chiz Voice Records / Profile Voice Lines — Японский","language":"Японский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=y94feRER9KI","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."},{"id":"22a96d05-27fd-4fce-9d19-fbc0376b9a6c","title":"Chiz Voice Records / Profile Voice Lines — Корейский","language":"Корейский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=y94feRER9KI","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."},{"id":"5957934e-3181-4f75-b413-fd5439af6451","title":"Chiz Voice Records / Profile Voice Lines — Китайский","language":"Китайский","audioUrl":"","sourceUrl":"https://www.youtube.com/watch?v=y94feRER9KI","description":"Видео-источник для ручной проверки реплик. Прямой аудиофайл редактор добавляет отдельно."}]') WHERE character_id='chiz' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:12:29');

UPDATE character_profiles SET abilities_json=json('[{"id":"GA_Chiichan073_Passive_2","name":"Накопительство","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/b581e6a74d0e059e78d1.webp","description":"Находясь на поле, повышает эффективность зарядки Чиз на 20 %.\n\nПрошлое — бездонная пропасть. Сколько камней туда ни бросай, обратно не прилетает ни единого звука.","attributes":[]},{"id":"GA_Chiichan073_Skill","name":"Превосходство Розовых лапок","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/fd2980896233bbc7ced0.webp","description":"Больше — значит веселее, больше — значит лучше. Накапливает заряды навыка перенаправления. Максимум — 3 заряда.\n\nНажмите навык перенаправления, чтобы потратить 1 заряд и использовать навык «Без зерна», нанося урон космоса один раз. Нажимайте навык перенаправления несколько раз подряд, чтобы потратить заряды и последовательно применить навыки «Без зерна», «Половина зерна» и «Цельное зерно» — до 3 применений подряд.\n\nКогда Чиз находится в состоянии «Избыток», нажатие активирует навык «Превосходство Розовых лапок», нанося дополнительный урон космоса в зависимости от текущего количества зерна при использовании навыка перенаправления. Крит не срабатывает.\n\nУдерживайте навык перенаправления, чтобы потратить 2 заряда и применить навыки «Без зерна» и «Половина зерна». Во время действия навыка «Половина зерна» происходит постоянное потребление зерна, что наносит дополнительный непрерывный урон космоса в зависимости от количества израсходованного зерна. Крит не срабатывает. Когда навык «Половина зерна» завершается, расходуется всё доступное зерно (включая всё зерно в долг в состоянии «Долг»). Нажмите навык перенаправления ещё раз, чтобы потратить 1 заряд, досрочно завершить навык «Половина зерна» и применить навык «Цельное зерно» без потребления зерна. Непрерывно удерживайте навык перенаправления, чтобы потратить 3 заряда, израсходовать всё доступное зерно (включая всё зерно в долг в состоянии «Долг») и последовательно применить навыки «Без зерна», «Половина зерна» и «Цельное зерно».\n\nНаходясь в состоянии «Избыток», удерживайте, чтобы применить навык «Превосходство Розовых лапок», нанося дополнительный урон космоса навыком «Без зерна» в зависимости от оставшегося зерна. Крит не срабатывает.\n\nНадпись на форзаце руководства для сотрудников банка «Розовые лапки»: «Посвящается великолепному лорду Ладону».","attributes":[{"id":"parameter-0","label":"Множитель урона без зерна","value":"1: 19 %+40 % · 2: 20.5 %+43.2 % · 3: 22.2 %+46.7 % · 4: 23.9 %+50.4 % · 5: 25.8 %+54.4 % · 6: 27.9 %+58.8 % · 7: 30.2 %+63.5 % · 8: 32.6 %+68.6 % · 9: 35.2 %+74 % · 10: 38 %+80 % · 11: 41 %+86.4 % · 12: 44.3 %+93.3 % · 13: 47.8 %+100.7 %"},{"id":"parameter-1","label":"Множитель урона от удара с половиной зерна","value":"1: 53.2 % *2 · 2: 57.5 % *2 · 3: 62.1 % *2 · 4: 67 % *2 · 5: 72.4 % *2 · 6: 78.2 % *2 · 7: 84.4 % *2 · 8: 91.2 % *2 · 9: 98.5 % *2 · 10: 106.3 % *2 · 11: 114.9 % *2 · 12: 124 % *2 · 13: 134 % *2"},{"id":"parameter-2","label":"Множитель урона каждого удара с половиной зерна","value":"1: 25 % · 2: 27 % · 3: 29.2 % · 4: 31.5 % · 5: 34 % · 6: 36.7 % · 7: 39.7 % · 8: 42.8 % · 9: 46.3 % · 10: 50 % · 11: 54 % · 12: 58.3 % · 13: 63 %"},{"id":"parameter-3","label":"Множитель урона с цельным зерном","value":"1: 28.3 %+41.8 % *3 · 2: 30.6 %+45.1 % *3 · 3: 33 %+48.8 % *3 · 4: 35.6 %+52.7 % *3 · 5: 38.5 %+56.9 % *3 · 6: 41.6 %+61.4 % *3 · 7: 44.9 %+66.3 % *3 · 8: 48.5 %+71.6 % *3 · 9: 52.4 %+77.4 % *3 · 10: 56.6 %+83.6 % *3 · 11: 61.1 %+90.2 % *3 · 12: 66 %+97.5 % *3 · 13: 71.3 %+105.3 % *3"},{"id":"parameter-4","label":"Бонусный урон за каждую единицу зерна","value":"1"},{"id":"parameter-5","label":"Стоимость удара с половиной зерна","value":"6.25 % зерна"},{"id":"parameter-6","label":"Бонусный урон за каждую израсходованную единицу зерна","value":"3"}]},{"id":"GA_Chiichan073_Passive_1","name":"Болезнь Ханахаки","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/d32e58d7793c43c04a96.webp","description":"Усиление зарядки: даёт активным персонажам дополнительно 4 ед. энергии сверхспособности.\n\nТоска… подобна белой птице, что взлетает из раны. Жаль, что ты её не увидишь.","attributes":[]},{"id":"GA_Chiichan073_Melee","name":"Меч изгнанника","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/5aceac2f785c927067de.webp","description":"Базовая атака: Меч изгнанника\nПроводит до 5 последовательных атак коротким посохом, нанося урон космоса. Каждое попадание даёт зерно.\n\nБазовая атака: Пустошь\nУдерживайте кнопку Пустоши, чтобы бросить сахарные шарики для поглощения цели. Наносит 2 удара урона космоса, даёт определённое количество зерна и фонсов. Срабатывает не чаще 1 раза в 2,5 сек.\n\nУдерживайте кнопку навыка Пустоши во время любой атаки Меча изгнанника, чтобы выполнить последующую атаку, нанести 2 удара урона космоса и предоставить определённое количество зерна и фонсов.\n\nДаёт дополнительные фонсы, если этот навык побеждает цель.\n\nТаким способом можно заработать до 250 000 фонсов. Повышение уровня магната до 25 увеличивает лимит до 500 000. После достижения дневного лимита за каждое использование даётся 1 фонс. После достижения общего лимита таким способом больше нельзя получить фонсы.\n\nБазовая атака: Полные кладовые\nНажмите базовую атаку, находясь в воздухе, чтобы пикировать вниз, нанося 1 удар урона космоса по области при ударе, при этом предоставляя определённое количество зерна. Урон увеличивается в зависимости от высоты падения (до 100 %).\n\nКритический контрудар: момент Мински\nАктивируется при нажатии на кнопку базовой атаки после критического уклонения. Прыгает, чтобы уклониться, и взмахивает посохом, запуская в цель сахарные шарики, которые наносят 1 удар урона космоса, снижают показатель разрушения цели и дают зерно.\n\nНефрит для изобильных времён, зерно — для худых.","attributes":[{"id":"parameter-0","label":"Множитель 1-го удара","value":"1: 34.5 % · 2: 37.3 % · 3: 40.2 % · 4: 43.5 % · 5: 46.9 % · 6: 50.7 % · 7: 54.7 % · 8: 59.1 % · 9: 63.9 % · 10: 69 % · 11: 74.5 % · 12: 80.4 % · 13: 86.9 %"},{"id":"parameter-1","label":"Множитель 2-го удара","value":"1: 17.1 % *3 · 2: 18.5 % *3 · 3: 19.9 % *3 · 4: 21.5 % *3 · 5: 23.3 % *3 · 6: 25.1 % *3 · 7: 27.1 % *3 · 8: 29.3 % *3 · 9: 31.7 % *3 · 10: 34.2 % *3 · 11: 36.9 % *3 · 12: 39.9 % *3 · 13: 43.1 % *3"},{"id":"parameter-2","label":"Множитель 3-го удара","value":"1: 56 % · 2: 60.5 % · 3: 65.3 % · 4: 70.5 % · 5: 76.2 % · 6: 82.3 % · 7: 88.9 % · 8: 96 % · 9: 103.7 % · 10: 111.9 % · 11: 120.9 % · 12: 130.6 % · 13: 141 %"},{"id":"parameter-3","label":"Множитель 4-го удара","value":"1: 20.9 % *5 · 2: 22.6 % *5 · 3: 24.4 % *5 · 4: 26.3 % *5 · 5: 28.4 % *5 · 6: 30.7 % *5 · 7: 33.2 % *5 · 8: 35.8 % *5 · 9: 38.7 % *5 · 10: 41.8 % *5 · 11: 45.1 % *5 · 12: 48.7 % *5 · 13: 52.6 % *5"},{"id":"parameter-4","label":"Множитель 5-го удара","value":"1: 39.7 % *2 · 2: 42.9 % *2 · 3: 46.3 % *2 · 4: 50 % *2 · 5: 54 % *2 · 6: 58.3 % *2 · 7: 63 % *2 · 8: 68 % *2 · 9: 73.5 % *2 · 10: 79.4 % *2 · 11: 85.7 % *2 · 12: 92.6 % *2 · 13: 100 % *2"},{"id":"parameter-7","label":"Множитель урона последующей атаки (удерживайте кнопку базовой атаки)","value":"1: 96 % *2 · 2: 103.7 % *2 · 3: 112 % *2 · 4: 120.9 % *2 · 5: 130.6 % *2 · 6: 141.1 % *2 · 7: 152.3 % *2 · 8: 164.5 % *2 · 9: 177.7 % *2 · 10: 191.9 % *2 · 11: 207.3 % *2 · 12: 223.8 % *2 · 13: 241.7 % *2"},{"id":"parameter-9","label":"Множитель урона последующей атаки (удержание)","value":"1: 77.5 % *2 · 2: 83.7 % *2 · 3: 90.4 % *2 · 4: 97.6 % *2 · 5: 105.4 % *2 · 6: 113.9 % *2 · 7: 123 % *2 · 8: 132.8 % *2 · 9: 143.4 % *2 · 10: 154.9 % *2 · 11: 167.3 % *2 · 12: 180.7 % *2 · 13: 195.2 % *2"},{"id":"parameter-14","label":"Множитель урона атаки в падении","value":"1: 90 % · 2: 97.2 % · 3: 105 % · 4: 113.4 % · 5: 122.4 % · 6: 132.2 % · 7: 142.8 % · 8: 154.2 % · 9: 166.6 % · 10: 179.9 % · 11: 194.3 % · 12: 209.8 % · 13: 226.6 %"},{"id":"parameter-16","label":"Множитель критического контрудара","value":"1: 30 %+60 % · 2: 32.4 %+64.8 % · 3: 35 %+70 % · 4: 37.8 %+75.6 % · 5: 40.8 %+81.6 % · 6: 44.1 %+88.2 % · 7: 47.6 %+95.2 % · 8: 51.4 %+102.8 % · 9: 55.5 %+111.1 % · 10: 60 %+119.9 % · 11: 64.8 %+129.5 % · 12: 69.9 %+139.9 % · 13: 75.5 %+151.1 %"}]},{"id":"GA_Chiichan073_QTE","name":"Временное вступление","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/9bf25557ae402a0e3d49.webp","description":"Надеюсь, я у-успею…\n\nСахарные шарики подхватывают Чиз и врезаются в цель, нанося 1 удар урона космоса.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"}]},{"id":"GA_Chiichan073_UltraSkill","name":"Игра с нулевой суммой","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/104735f0c27a5aa88034.webp","description":"Пути назад нет — бери максимум. Бросает сахарные шарики для атаки, нанося один раз урон космоса по области, и входит на Зерновой рынок на 7 сек. Урон от первого Зерна прибыли во время этого периода гарантированно наносит критический удар.\n\nПосле применения «Игры с нулевой суммой» конвертирует всё оставшееся Зерно в долг в Зерно и переходит в состояние Избытка. Инвестирует всё Зерно на Зерновой рынок. После этого нажмите «Превосходство Розовых лапок», чтобы получить Зерно на основе текущих колебаний Цены зерна во время расчёта Зерна прибыли. Удерживайте «Превосходство Розовых лапок», чтобы активировать расчёт Зерна прибыли один раз на основе цены Зерна в момент первой активации.\n\nКогда действие Зернового рынка заканчивается, покидает Зерновой рынок, и всё текущее Зерно будет в первую очередь направлено на погашение зернового долга.\n\nДаёт доступ к Зерновому рынку, даже находясь в состоянии Долга и когда есть Зерно в долг.\n\nВ этой битве победу одержу только я.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 44.6 % *4 + 44.7 % + 277.1 % · 2: 48.2 % *4 + 48.3 % + 299.3 % · 3: 52 % *4 + 52.1 % + 323.2 % · 4: 56.2 % *4 + 56.3 % + 349.1 % · 5: 60.7 % *4 + 60.8 % + 377 % · 6: 65.5 % *4 + 65.7 % + 407.2 % · 7: 70.8 % *4 + 70.9 % + 439.7 % · 8: 76.4 % *4 + 76.6 % + 474.9 % · 9: 82.6 % *4 + 82.7 % + 512.9 % · 10: 89.2 % *4 + 89.4 % + 553.9 % · 11: 96.3 % *4 + 96.5 % + 598.2 % · 12: 104 % *4 + 104.2 % + 646.1 % · 13: 112.3 % *4 + 112.6 % + 697.8 %"}]}]') WHERE character_id='chiz' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:12:29');

UPDATE character_profiles SET skins_json=json('[{"id":"Fashion_1073_nighty","name":"Весенний день в бархате","description":"Домашняя одежда Чиз. Нежная, не раздражающая кожу ткань — лучший вариант для выходного дня дома.\n\n«Я и завтра не собираюсь выходить, но… хочется, чтобы солнышко выглянуло!»","imageUrl":"/nte-meta/game-assets/ee06e23dfae83efc9f0c.webp"},{"id":"Fashion_1073_1","name":"Изумрудная грация","description":"Сценический костюм для ежегодного гала-концерта банка «Розовые лапки». В то время у господина Джованни появилась странная одержимость одним чёрно-белым животным\n\n«Так… мы что, теперь сотрудничаем с \"Панда-хотпот\"?»","imageUrl":"/nte-meta/game-assets/9ba74d375f07d6a06710.webp"},{"id":"Fashion_1073_0","name":"Будничные пузыри","description":"Обновлённая форма сотрудника банка «Розовые лапки», переработанная в соответствии с фирменной цветовой гаммой бренда. Чиз каждое утро тратит не меньше часа, чтобы её наряд был безупречно чистым и идеально выглаженным.","imageUrl":"/nte-meta/game-assets/6e87ceefa9e9d9af9804.webp"}]') WHERE character_id='chiz' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:12:29');

