UPDATE character_profiles SET voice_actors_json=json('[{"language":"Китайский","name":"唐夏芳"},{"language":"Английский","name":"Anne Yatco"},{"language":"Японский","name":"田所あずさ"},{"language":"Корейский","name":"차영희"},{"language":"Японский","name":"Azusa Tadokoro (田所あずさ)"},{"language":"Китайский","name":"Tang Xiafang (唐夏芳)"},{"language":"Корейский","name":"Cha Young-hee (차영희)"}]') WHERE character_id='ec50ff3d-4340-4dad-89b4-1e14b95d6c21' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-08-25 11:17:01');

UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Дождливая аллея","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1076_1.png","description":"Урон Шинку игнорирует 12 % защиты цели."},{"level":2,"kind":"awakening","name":"Предрассветная тренировочная площадка","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1076_2.png","description":"После попадания сверхспособностью Шинку снижает сопротивление цели урону космоса на 10 % на 20 сек."},{"level":3,"kind":"awakening","name":"Закатный пляж","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1076_3.png","description":"Позволяет Угрожающему взгляду оставаться активным после смены персонажа и даёт Шинку возможность накапливать уровни Угрожающего взгляда, когда она не находится на поле боя."},{"level":4,"kind":"awakening","name":"Снежный склон","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1076_4.png","description":"Увеличивает максимальное количество уровней Угрожающего взгляда до 16. Когда Угрожающий взгляд достигает 16 уровней, активируемый Мгновенный удар усиливается и получает дополнительные свойства Мгновенного удара от ответного удара или критического контрудара: вызывает принудительное отбрасывание и оглушение цели (не действует против боссов) и наносит дополнительный урон в размере 20 % от урона Мгновенного удара."},{"level":5,"kind":"awakening","name":"Комната смеха","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1076_5.png","description":"Во время действия Бушующего багрянца увеличивает защиту Шинку на 50 % и её устойчивость к прерываниям на 50 %, а также восстанавливает ей ОЗ в размере 300 % от её базовой атаки после применения Алого спуска."},{"level":6,"kind":"awakening","name":"Драконье сокровище","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/mindscape/1076_6.png","description":"Увеличивает множители урона навыков Шинку «Алый спуск», «Багровый суд» и «Приговор драконьего пламени» на 30 %, а также позволяет навыкам «Алый спуск» и «Багровый суд» притягивать цели в области действия."},{"level":3,"kind":"resonance","name":"Пробуждённая решимость","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень базовой атаки, навыка перенаправления и сверхспособности на 1. Дополнительно увеличивает наносимый урон на 30 % во время действия Бушующего багрянца."},{"level":6,"kind":"resonance","name":"Багровый герой","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Увеличивает шанс крит. удара Шинку на 10 %; кроме того, нанося урон, она игнорирует 15 % защиты цели."}]') WHERE character_id='ec50ff3d-4340-4dad-89b4-1e14b95d6c21' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-08-25 11:17:01');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"en-Play_Vo_Char_NPC032_self_002","title":"Обо мне: отношения","description":"«Я в Бюро всегда работаю в одиночку»? Да эта дурёха-кошка просто треплет языком… Ну, чисто технически я ведь не могу остаться одна, если она постоянно таскает нас с Ирой за собой, разве нет?","language":"Английский","audioUrl":"/nte-meta/game-audio/d7c4f3b8c97e58e79f0b.ogg"},{"id":"ja-Play_Vo_Char_NPC032_struck_002","title":"Урон II","description":"Всего лишь царапина.","language":"Японский","audioUrl":"/nte-meta/game-audio/332f108bfedaa5115ad1.ogg"},{"id":"ja-Play_Vo_Char_NPC032_ultraskill_UI_003","title":"Сверхспособность III","description":"Бесит… заткнитесь, заткнитесь, заТКНИтеСЬ, ЗАТКНИТЕСЬ!","language":"Японский","audioUrl":"/nte-meta/game-audio/cd3c15ce40ef2dc28931.ogg"},{"id":"en-Play_Vo_Char_NPC032_about_005","title":"Об ОС-2","description":"Когда меня только перевели в ОС-2, я думала, сначала мне будет трудно, но благодаря Минт коллеги быстро меня приняли за свою. Зато на первом же задании я чуть крупно не облажалась. Хорошо, что Ирой оказалась рядом и помогла… Кхм, надо бы угостить коллег чем-нибудь из «Безумного кота».","language":"Английский","audioUrl":"/nte-meta/game-audio/3e33933fc98c6ca60005.ogg"},{"id":"en-Play_Vo_Char_NPC032_ug_002","title":"Вознесение персонажа II","description":"Это может сулить проблемы, но стать сильнее — в любом случае к лучшему.","language":"Английский","audioUrl":"/nte-meta/game-audio/5870aabb1089ca2db896.ogg"},{"id":"en-Play_Vo_Char_NPC032S_skill_006","title":"Навык перенаправления VI","description":"Высвобождаю всю свою ярость!","language":"Английский","audioUrl":"/nte-meta/game-audio/3aa97e8334ca7609404a.ogg"},{"id":"ja-Play_Vo_Char_NPC032_deploy_001","title":"Отправка I","description":"Самого сильного я возьму на себя.","language":"Японский","audioUrl":"/nte-meta/game-audio/966626616ffc8879b38e.ogg"},{"id":"ja-Play_Vo_Char_NPC032_gift_003","title":"Подарок получен III","description":"Спасибо. Добавлю это к своим сокровищам.","language":"Японский","audioUrl":"/nte-meta/game-audio/59ac118841709f7b368c.ogg"},{"id":"en-Play_Vo_Char_NPC032_weather_002","title":"Дождливо","description":"Опять дождь. Тьфу, сплошная морока…","language":"Английский","audioUrl":"/nte-meta/game-audio/362db7dd167d5139b8db.ogg"},{"id":"ja-Play_Vo_Char_NPC032_anomaly_003","title":"Нуллификация I","description":"Какая морока…","language":"Японский","audioUrl":"/nte-meta/game-audio/867b970631d03ac04317.ogg"},{"id":"en-Play_Vo_Char_NPC032_struck_001","title":"Урон I","description":"Тц, совсем расслабилась…","language":"Английский","audioUrl":"/nte-meta/game-audio/e3736603181641f81ab9.ogg"},{"id":"ja-Play_Vo_Char_NPC032_gift_004","title":"Подарок получен IV","description":"Могу чем-нибудь помочь?","language":"Японский","audioUrl":"/nte-meta/game-audio/33c0aa8077b6dfae1f83.ogg"},{"id":"en-Play_Vo_Char_NPC032_QTE_003","title":"Атака на входе III","description":"Твоей решимости… недостаточно!","language":"Английский","audioUrl":"/nte-meta/game-audio/b0215e4ecbf7eb32fcc0.ogg"},{"id":"en-Play_Vo_Char_NPC032S_skill_004","title":"Навык перенаправления IV","description":"Я должна… пустить в ход когти!","language":"Английский","audioUrl":"/nte-meta/game-audio/9d980930fe222b23608c.ogg"},{"id":"ja-Play_Vo_Char_NPC032_dead_002","title":"Потеря сознания II","description":"Неужели это конец?..","language":"Японский","audioUrl":"/nte-meta/game-audio/f30ec5ebc0848a4ac0a8.ogg"},{"id":"ja-Play_Vo_Char_NPC032_QTE_003","title":"Атака на входе III","description":"Твоей решимости… недостаточно!","language":"Японский","audioUrl":"/nte-meta/game-audio/26843942efcb7f4a7caf.ogg"},{"id":"en-Play_Vo_Char_NPC032_windfall_001","title":"Неожиданная добыча I","description":"Везучий денёк. Надо бы заскочить в DSD.","language":"Английский","audioUrl":"/nte-meta/game-audio/30163c158494a8b218da.ogg"},{"id":"ja-Play_Vo_Char_NPC032_about_005","title":"Об ОС-2","description":"Когда меня только перевели в ОС-2, я думала, сначала мне будет трудно, но благодаря Минт коллеги быстро меня приняли за свою. Зато на первом же задании я чуть крупно не облажалась. Хорошо, что Ирой оказалась рядом и помогла… Кхм, надо бы угостить коллег чем-нибудь из «Безумного кота».","language":"Японский","audioUrl":"/nte-meta/game-audio/630cc04883f4a89f83c3.ogg"},{"id":"ja-Play_Vo_Char_NPC032_dead_001","title":"Потеря сознания I","description":"Оно и к лучшему…","language":"Японский","audioUrl":"/nte-meta/game-audio/fd48f8e5841faa455271.ogg"},{"id":"en-Play_Vo_Char_NPC032_about_001","title":"О Минт I","description":"Минт-«сенпай» абсолютно не умеет читать атмосферу. Стоит тебе попытаться отдалиться, как она тут же лезет с разговорами. Эх, ну не могу я бросить эту дурёху-кошку одну.","language":"Английский","audioUrl":"/nte-meta/game-audio/5c9b7982a9229784fea9.ogg"},{"id":"en-Play_Vo_Char_NPC032_greet_001","title":"Утреннее приветствие","description":"Доброе утро. Погляжу, ты прям горишь энтузиазмом. Может, подменишь меня в патруле, а?","language":"Английский","audioUrl":"/nte-meta/game-audio/40096e7a22569e4fb42d.ogg"},{"id":"en-Play_Vo_Char_NPC032_greet_003","title":"Вечернее приветствие","description":"Хоть бы сегодня вечером не запрягли сдавать какой-нибудь срочный отчёт…","language":"Английский","audioUrl":"/nte-meta/game-audio/5d91f4a98591d708656c.ogg"},{"id":"en-Play_Vo_Char_NPC032_hp_003","title":"Низкий уровень здоровья III","description":"Столько хлопот…","language":"Английский","audioUrl":"/nte-meta/game-audio/a72e0ce0f90c3ae8e8f9.ogg"},{"id":"en-Play_Vo_Char_NPC032_fh_001","title":"Исцеление I","description":"Я так классно себя чувствую, что и Всадника без головы в одиночку завалю.","language":"Английский","audioUrl":"/nte-meta/game-audio/a28d5582af43f240548e.ogg"},{"id":"en-Play_Vo_Char_NPC032_about_002","title":"О Минт II","description":"Эта дурёха-кошка никогда не скрывает своих истинных мыслей и чувств. Даже не знаю, хвалить её за это или просто назвать непрошибаемой… И всё же, будь все вокруг такими же прямолинейными, как Минт, жить стало бы гораздо проще.","language":"Английский","audioUrl":"/nte-meta/game-audio/aeff1c25121b2175f525.ogg"},{"id":"en-Play_Vo_Char_NPC032_Fly_001","title":"Планирование I","description":"Вот бы мне крылья…","language":"Английский","audioUrl":"/nte-meta/game-audio/273d0b2ccc1ba022d8d5.ogg"},{"id":"en-Play_Vo_Char_NPC032_talk_002","title":"Тема: скитания","description":"Если у меня нет планов, я люблю просто гулять куда глаза глядят. Забредаю в случайные места, и если вижу что-то интересное, то обязательно забираю себе. В детстве я называла это «охотой за сокровищами». И ведь ничего не изменилось, верно?","language":"Английский","audioUrl":"/nte-meta/game-audio/88d9a8e55212462d2d94.ogg"},{"id":"ja-Play_Vo_Char_NPC032_about_003","title":"Об Ирой I","description":"Как коллега, Ирой — практически идеал. Нас, наверное, поставили в пару потому, что когда я теряю контроль, она умеет успокаивать меня своими снами. В одном из них я как раз и увидела… ай, забудь. В общем, обычным человеком я её не считаю, но нашей работе это никак не мешает.","language":"Японский","audioUrl":"/nte-meta/game-audio/ac78c61f3fa21fedf131.ogg"},{"id":"ja-Play_Vo_Char_NPC032_skill_003","title":"Навык перенаправления III","description":"Попробуй заблокируй… если сможешь!","language":"Японский","audioUrl":"/nte-meta/game-audio/c1836f1542419e6faf14.ogg"},{"id":"en-Play_Vo_Char_NPC032_chat_003","title":"Чат: слухи","description":"У меня нет крыльев, я не изрыгаю пламя и уж точно не хватаю врагов, чтобы покружить в небе, а потом ударить их со всей дури о землю. Серьёзно, кто эту чушь вообще выдумал?..","language":"Английский","audioUrl":"/nte-meta/game-audio/73e38fdf8591f66e07a5.ogg"},{"id":"en-Play_Vo_Char_NPC032_ultraskill_UI_003","title":"Сверхспособность III","description":"Бесит… заткнитесь, заткнитесь, заТКНИтеСЬ, ЗАТКНИТЕСЬ!","language":"Английский","audioUrl":"/nte-meta/game-audio/bfcfda8a6584cb42ec3b.ogg"},{"id":"en-Play_Vo_Char_NPC032_windfall_003","title":"Неожиданная добыча III","description":"Какая ценная добыча меня ждёт?","language":"Английский","audioUrl":"/nte-meta/game-audio/f21d3e0948b1293968ee.ogg"},{"id":"ja-Play_Vo_Char_NPC032_TeammateDown_003","title":"Поражен товарищ по команде – Ноль","description":"Оценщик, только не вздумай сдаваться! Оценщица, только не вздумай сдаваться!","language":"Японский","audioUrl":"/nte-meta/game-audio/3dbf95606a493f0be409.ogg"},{"id":"ja-Play_Vo_Char_NPC032_ug_003","title":"Вознесение персонажа III","description":"Недостаточно… Мне нужно больше сил!..","language":"Японский","audioUrl":"/nte-meta/game-audio/8a650638c0e2f6ca6e8d.ogg"},{"id":"en-Play_Vo_Char_NPC032_about_003","title":"Об Ирой I","description":"Как коллега, Ирой — практически идеал. Нас, наверное, поставили в пару потому, что когда я теряю контроль, она умеет успокаивать меня своими снами. В одном из них я как раз и увидела… ай, забудь. В общем, обычным человеком я её не считаю, но нашей работе это никак не мешает.","language":"Английский","audioUrl":"/nte-meta/game-audio/5a984f7d8411aacbb6c9.ogg"},{"id":"ja-Play_Vo_Char_NPC032_weather_001","title":"Солнечно","description":"При такой хорошей погоде, может, ещё и Минт на площади встретим.","language":"Японский","audioUrl":"/nte-meta/game-audio/71eca2f32e8942359fce.ogg"},{"id":"en-Play_Vo_Char_NPC032_dead_002","title":"Потеря сознания II","description":"Неужели это конец?..","language":"Английский","audioUrl":"/nte-meta/game-audio/a4e5a1960d307cb13b74.ogg"},{"id":"en-Play_Vo_Char_NPC032_QTE_001","title":"Атака на входе I","description":"Кончай с этим!","language":"Английский","audioUrl":"/nte-meta/game-audio/6e75db9952ec71efe1d2.ogg"},{"id":"en-Play_Vo_Char_NPC032_ug_003","title":"Вознесение персонажа III","description":"Недостаточно… Мне нужно больше сил!..","language":"Английский","audioUrl":"/nte-meta/game-audio/cf48e8a80ca2d889f1d8.ogg"},{"id":"ja-Play_Vo_Char_NPC032S_ultraskill_UI_004","title":"Сверхспособность IV","description":"Это конец!..","language":"Японский","audioUrl":"/nte-meta/game-audio/50f303bb8eb098b9bc09.ogg"},{"id":"en-Play_Vo_Char_NPC032_kill_002","title":"Убийство II","description":"Я ожидала от тебя большего.","language":"Английский","audioUrl":"/nte-meta/game-audio/13c0a7131940e7db1709.ogg"},{"id":"ja-Play_Vo_Char_NPC032_meet_001","title":"Первая встреча","description":"Я Шинку из ОС-2. Ты ведь Какао, верно? Минт о тебе часто рассказывала. Рада знакомству. Надеюсь, я не доставлю тебе столько же хлопот, сколько эта дурёха-кошка.","language":"Японский","audioUrl":"/nte-meta/game-audio/beb368f9a1002944d4d7.ogg"},{"id":"ja-Play_Vo_Char_NPC032_ug_002","title":"Вознесение персонажа II","description":"Это может сулить проблемы, но стать сильнее — в любом случае к лучшему.","language":"Японский","audioUrl":"/nte-meta/game-audio/10021d8107f8057d1f63.ogg"},{"id":"ja-Play_Vo_Char_NPC032_ultraskill_UI_001","title":"Сверхспособность I","description":"Эти паразиты…","language":"Японский","audioUrl":"/nte-meta/game-audio/fba350969a7c9e1c776b.ogg"},{"id":"ja-Play_Vo_Char_NPC032_windfall_006","title":"Неожиданная добыча VI","description":"Мне нужно сдать это в Офис безопасности?","language":"Японский","audioUrl":"/nte-meta/game-audio/a782284be810cdeb21e3.ogg"},{"id":"en-Play_Vo_Char_NPC032_containment_002","title":"Сдерживание II","description":"Сдерживание завершено. Всё прошло как по маслу.","language":"Английский","audioUrl":"/nte-meta/game-audio/0e2ca3a293778544673f.ogg"},{"id":"en-Play_Vo_Char_NPC032_TeammateDown_003","title":"Поражен товарищ по команде – Ноль","description":"Оценщик, только не вздумай сдаваться! Оценщица, только не вздумай сдаваться!","language":"Английский","audioUrl":"/nte-meta/game-audio/b20034bb0594a363506a.ogg"},{"id":"en-Play_Vo_Char_NPC032_windfall_006","title":"Неожиданная добыча VI","description":"Мне нужно сдать это в Офис безопасности?","language":"Английский","audioUrl":"/nte-meta/game-audio/9f7bf953aacc101f5596.ogg"},{"id":"ja-Play_Vo_Char_NPC032S_ultraskill_UI_006","title":"Сверхспособность VI","description":"Замышляешь побег? Даже не думай!","language":"Японский","audioUrl":"/nte-meta/game-audio/b3a6a749e4dbc149c88f.ogg"},{"id":"en-Play_Vo_Char_NPC032_DodgeCombo_002","title":"Серия критических уклонений II","description":"Промахи недопустимы.","language":"Английский","audioUrl":"/nte-meta/game-audio/58b9daf8f20be5e76115.ogg"},{"id":"en-Play_Vo_Char_NPC032_hp_001","title":"Низкий уровень здоровья I","description":"Чёрт… нужно подлечиться.","language":"Английский","audioUrl":"/nte-meta/game-audio/8badbc4e992edb4045cc.ogg"},{"id":"ja-Play_Vo_Char_NPC032_windfall_002","title":"Неожиданная добыча II","description":"Нашла кое-что полезное. Очень даже неплохо.","language":"Японский","audioUrl":"/nte-meta/game-audio/d5db73e78493e8380392.ogg"},{"id":"en-Play_Vo_Char_NPC032S_ultraskill_UI_004","title":"Сверхспособность IV","description":"Это конец!..","language":"Английский","audioUrl":"/nte-meta/game-audio/fd058d2a6a3f484fe334.ogg"},{"id":"ja-Play_Vo_Char_NPC032_skill_002","title":"Навык перенаправления II","description":"Одним махом!..","language":"Японский","audioUrl":"/nte-meta/game-audio/cb1b83e89ac095bc11a6.ogg"},{"id":"en-Play_Vo_Char_NPC032_gift_003","title":"Подарок получен III","description":"Спасибо. Добавлю это к своим сокровищам.","language":"Английский","audioUrl":"/nte-meta/game-audio/f76a7783616d5ab0d30e.ogg"},{"id":"ja-Play_Vo_Char_NPC032_chat_001","title":"Чат: драконьи рога","description":"В бою от рогов толку меньше, чем от хвоста, но они хотя бы не доставляют мне столько хлопот. Ну, разве что когда я измеряю свой рост.","language":"Японский","audioUrl":"/nte-meta/game-audio/6364d3011fd2831212f3.ogg"},{"id":"ja-Play_Vo_Char_NPC032_Parry_002","title":"Парирование II","description":"Можешь бить и посильнее.","language":"Японский","audioUrl":"/nte-meta/game-audio/437179d3ced69dfc92fa.ogg"},{"id":"en-Play_Vo_Char_NPC032_weather_004","title":"Жарко","description":"Сейчас бы фруктового льда…","language":"Английский","audioUrl":"/nte-meta/game-audio/32f1d9350dcfd21ac3da.ogg"},{"id":"ja-Play_Vo_Char_NPC032_greet_002","title":"Дневное приветствие","description":"Хочешь поесть рамен? Тут есть одна старая лапшичная, куда я постоянно забегала ещё во времена учёбы. Готовят там невероятно вкусно.","language":"Японский","audioUrl":"/nte-meta/game-audio/17fe8b71f5ea701bc181.ogg"},{"id":"en-Play_Vo_Char_NPC032_SSC_mint_001","title":"Особое переключение — Минт","description":"Ладно-ладно, Минт-«сенпай».","language":"Английский","audioUrl":"/nte-meta/game-audio/9d056aa36ff60f331e49.ogg"},{"id":"en-Play_Vo_Char_NPC032_Switch_002","title":"Переключение II","description":"Так, дальше я сама!..","language":"Английский","audioUrl":"/nte-meta/game-audio/639cbca996a348819d21.ogg"},{"id":"en-Play_Vo_Char_NPC032_windfall_002","title":"Неожиданная добыча II","description":"Нашла кое-что полезное. Очень даже неплохо.","language":"Английский","audioUrl":"/nte-meta/game-audio/03eff8b834792a011fbf.ogg"},{"id":"ja-Play_Vo_Char_NPC032_containment_001","title":"Сдерживание I","description":"Не шевелись и дай мне делать свою работу.","language":"Японский","audioUrl":"/nte-meta/game-audio/eabbcbcaf59e9c542074.ogg"},{"id":"ja-Play_Vo_Char_NPC032_greet_003","title":"Вечернее приветствие","description":"Хоть бы сегодня вечером не запрягли сдавать какой-нибудь срочный отчёт…","language":"Японский","audioUrl":"/nte-meta/game-audio/1b85cbfc0a0f11ccf46a.ogg"},{"id":"ja-Play_Vo_Char_NPC032_TeammateDown_002","title":"Поражён товарищ по команде — Ирой","description":"Передохни. Я заставлю их заплатить!..","language":"Японский","audioUrl":"/nte-meta/game-audio/49d319f0742962c1fc77.ogg"},{"id":"en-Play_Vo_Char_NPC032_meet_001","title":"Первая встреча","description":"Я Шинку из ОС-2. Ты ведь Какао, верно? Минт о тебе часто рассказывала. Рада знакомству. Надеюсь, я не доставлю тебе столько же хлопот, сколько эта дурёха-кошка.","language":"Английский","audioUrl":"/nte-meta/game-audio/b3f50d7d3163213e3709.ogg"},{"id":"ja-Play_Vo_Char_NPC032_fh_002","title":"Исцеление II","description":"Я в отличной форме. Ещё враги есть?","language":"Японский","audioUrl":"/nte-meta/game-audio/c19c9bb2911efd23c88b.ogg"},{"id":"ja-Play_Vo_Char_NPC032S_ultraskill_UI_005","title":"Сверхспособность V","description":"Тебе отсюда не уйти!","language":"Японский","audioUrl":"/nte-meta/game-audio/7acc438bf4dff4f0d66b.ogg"},{"id":"en-Play_Vo_Char_NPC032_deploy_002","title":"Отправка II","description":"Не волнуйся. Я буду держать себя в руках.","language":"Английский","audioUrl":"/nte-meta/game-audio/62753c6bc56f8df6fa5d.ogg"},{"id":"ja-Play_Vo_Char_NPC032_fh_001","title":"Исцеление I","description":"Я так классно себя чувствую, что и Всадника без головы в одиночку завалю.","language":"Японский","audioUrl":"/nte-meta/game-audio/a1f051195cb4dc867f3e.ogg"},{"id":"en-Play_Vo_Char_NPC032_greet_004","title":"Спокойной ночи","description":"Уже поздно. Тебе ведь не нужно провожать меня до дома, правда? Увидимся завтра, спокойной ночи.","language":"Английский","audioUrl":"/nte-meta/game-audio/8b3dba5be817afc65f49.ogg"},{"id":"ja-Play_Vo_Char_NPC032_Switch_001","title":"Переключение I","description":"Назад!","language":"Японский","audioUrl":"/nte-meta/game-audio/2d5bd012a344337cfc84.ogg"},{"id":"en-Play_Vo_Char_NPC032S_ultraskill_UI_005","title":"Сверхспособность V","description":"Тебе отсюда не уйти!","language":"Английский","audioUrl":"/nte-meta/game-audio/4484bc716b6e0e0aade3.ogg"},{"id":"ja-Play_Vo_Char_NPC032_about_006","title":"О Бюро по борьбе с аномалиями","description":"Сразу проясню: я не пытаюсь очернить своих коллег. Я лишь к тому, что в ББА полно странных личностей, в особенности среди сотрудников ОС и ТОИ, чья работа связана с выездами и ликвидацией опасных аномалий. Если подумать, мне удалось прижиться в Бюро и многому научиться у прежнего капитана именно потому, что «обычных людей» здесь отродясь не водилось.","language":"Японский","audioUrl":"/nte-meta/game-audio/492f5a1d748af63c1bd0.ogg"},{"id":"ja-Play_Vo_Char_NPC032_containment_002","title":"Сдерживание II","description":"Сдерживание завершено. Всё прошло как по маслу.","language":"Японский","audioUrl":"/nte-meta/game-audio/8edeab06a36b1cd820e5.ogg"},{"id":"en-Play_Vo_Char_NPC032_windfall_005","title":"Неожиданная добыча V","description":"Это что, благословение Накупеды?","language":"Английский","audioUrl":"/nte-meta/game-audio/630efd3c371702d8d5f1.ogg"},{"id":"en-Play_Vo_Char_NPC032S_skill_005","title":"Навык перенаправления V","description":"Доиграешься… вот тогда и узнаешь!","language":"Английский","audioUrl":"/nte-meta/game-audio/514cc2ef9318b0359edf.ogg"},{"id":"ja-Play_Vo_Char_NPC032_skill_001","title":"Навык перенаправления I","description":"Этого недостаточно.","language":"Японский","audioUrl":"/nte-meta/game-audio/1cba6baec9022c750c82.ogg"},{"id":"ja-Play_Vo_Char_NPC032_talk_001","title":"Тема: ОС","description":"Этот «Новый протокол безопасности при сдерживании» — сплошная головная боль. Там столько правил, что на каждом задании мне приходится дважды думать, прежде чем что-то сделать. Но с другой стороны, приучить себя соблюдать эти раздражающие ограничения, когда мои способности выходят из-под контроля — именно ради этого я здесь.","language":"Японский","audioUrl":"/nte-meta/game-audio/cd0dba6d0ba21dee3973.ogg"},{"id":"en-Play_Vo_Char_NPC032_gift_004","title":"Подарок получен IV","description":"Могу чем-нибудь помочь?","language":"Английский","audioUrl":"/nte-meta/game-audio/4dea1beeb937009bb031.ogg"},{"id":"ja-Play_Vo_Char_NPC032_kill_001","title":"Убийство I","description":"Уже всё?","language":"Японский","audioUrl":"/nte-meta/game-audio/ad0a35bfff3ef6d7ba68.ogg"},{"id":"ja-Play_Vo_Char_NPC032S_skill_005","title":"Навык перенаправления V","description":"Доиграешься… вот тогда и узнаешь!","language":"Японский","audioUrl":"/nte-meta/game-audio/8134927f126390e25f49.ogg"},{"id":"en-Play_Vo_Char_NPC032_containment_001","title":"Сдерживание I","description":"Не шевелись и дай мне делать свою работу.","language":"Английский","audioUrl":"/nte-meta/game-audio/b546c520ae0597418bd0.ogg"},{"id":"ja-Play_Vo_Char_NPC032_struck_001","title":"Урон I","description":"Тц, совсем расслабилась…","language":"Японский","audioUrl":"/nte-meta/game-audio/84341dbff9fc28da08bd.ogg"},{"id":"ja-Play_Vo_Char_NPC032_vexation_001","title":"Проблемы","description":"С деньгами сейчас туговато. Так не хочется трогать заначку…","language":"Японский","audioUrl":"/nte-meta/game-audio/3e0ed1187f5ad07337a4.ogg"},{"id":"en-Play_Vo_Char_NPC032_about_004","title":"Об Ирой II","description":"У каждого есть история, о которой не хочется рассказывать. Раньше я тоже всё держала в себе. И Овцетенна сейчас поступает так же. Понятия не имею, что она пережила, но я обязана хотя бы просто её поддержать — как когда-то моя команда поддержала меня в битве с Багровым драконом. А наши вечные споры? Я была бы рада обойтись без них, но, похоже, у настоящих друзей без этого не обходится.","language":"Английский","audioUrl":"/nte-meta/game-audio/7762afda9cd0500a1447.ogg"},{"id":"en-Play_Vo_Char_NPC032_anomaly_003","title":"Нуллификация I","description":"Какая морока…","language":"Английский","audioUrl":"/nte-meta/game-audio/fc027a177df6e1229283.ogg"},{"id":"en-Play_Vo_Char_NPC032_weather_001","title":"Солнечно","description":"При такой хорошей погоде, может, ещё и Минт на площади встретим.","language":"Английский","audioUrl":"/nte-meta/game-audio/d967a78e1544d79234c8.ogg"},{"id":"ja-Play_Vo_Char_NPC032_hp_001","title":"Низкий уровень здоровья I","description":"Чёрт… нужно подлечиться.","language":"Японский","audioUrl":"/nte-meta/game-audio/82985a47274cd63ec0f9.ogg"},{"id":"ja-Play_Vo_Char_NPC032_talk_003","title":"Тема: Накупеда","description":"Накупеда — настоящий эксперт по сбережению монет: просто закидывает их в фонтан и держит на виду. Неудивительно, что эта аномалия всегда такая счастливая. Может, и мне так попробовать?","language":"Японский","audioUrl":"/nte-meta/game-audio/5e4967eb0421f8251341.ogg"},{"id":"en-Play_Vo_Char_NPC032_kill_001","title":"Убийство I","description":"Уже всё?","language":"Английский","audioUrl":"/nte-meta/game-audio/bb7abad817ad7f1c8020.ogg"},{"id":"ja-Play_Vo_Char_NPC032_hstruck_002","title":"Сильный урон II","description":"…Я верну тебе должок!","language":"Японский","audioUrl":"/nte-meta/game-audio/c504e24aac34a97a3d77.ogg"},{"id":"ja-Play_Vo_Char_NPC032_windfall_003","title":"Неожиданная добыча III","description":"Какая ценная добыча меня ждёт?","language":"Японский","audioUrl":"/nte-meta/game-audio/3599f61d0339e44f4af8.ogg"},{"id":"en-Play_Vo_Char_NPC032_self_001","title":"Обо мне: способность эспера","description":"Мой прежний капитан как-то назвал эту силу проклятием. Пускай она и дарует мощь, но способна погубить всё, что мне дорого. Помню, как вся извелась, когда случайно ранила друга… Но теперь я наконец всё поняла. Я приму эту силу и сделаю её частью себя. Лишь бы никогда больше не презирать себя за слабость в моменты, когда обязана быть сильной.","language":"Английский","audioUrl":"/nte-meta/game-audio/9e331cfd47fb507a716c.ogg"},{"id":"ja-Play_Vo_Char_NPC032_weather_002","title":"Дождливо","description":"Опять дождь. Тьфу, сплошная морока…","language":"Японский","audioUrl":"/nte-meta/game-audio/660c755e8a4d00eef912.ogg"},{"id":"en-Play_Vo_Char_NPC032_anomaly_004","title":"Нуллификация II","description":"Значит, хочешь по-плохому.","language":"Английский","audioUrl":"/nte-meta/game-audio/9bd51ae5b3a362ac4f14.ogg"},{"id":"ja-Play_Vo_Char_NPC032_kill_002","title":"Убийство II","description":"Я ожидала от тебя большего.","language":"Японский","audioUrl":"/nte-meta/game-audio/343e4a33d74af91699da.ogg"},{"id":"en-Play_Vo_Char_NPC032_DodgeCombo_001","title":"Серия критических уклонений I","description":"Не поспеваешь за мной?","language":"Английский","audioUrl":"/nte-meta/game-audio/c9f3e78ebcfe195c29e7.ogg"},{"id":"ja-Play_Vo_Char_NPC032_about_004","title":"Об Ирой II","description":"У каждого есть история, о которой не хочется рассказывать. Раньше я тоже всё держала в себе. И Овцетенна сейчас поступает так же. Понятия не имею, что она пережила, но я обязана хотя бы просто её поддержать — как когда-то моя команда поддержала меня в битве с Багровым драконом. А наши вечные споры? Я была бы рада обойтись без них, но, похоже, у настоящих друзей без этого не обходится.","language":"Японский","audioUrl":"/nte-meta/game-audio/ccce3836e0c7721ee83b.ogg"},{"id":"ja-Play_Vo_Char_NPC032_hobby_001","title":"Хобби","description":"Я коллекционирую всё, что мне приглянется: от сверхсекретных лимитированных тиражей таинственных коробок-коллабораций DSD с «Герцогом К» до бракованных выпусков «Недельной фантазии»… Да я даже могу просто подобрать прикольный камушек на пляже. Хочешь взглянуть? Пожалуй, оставим это до следующего раза.","language":"Японский","audioUrl":"/nte-meta/game-audio/3c6ee515d9e7217a6ec1.ogg"},{"id":"en-Play_Vo_Char_NPC032_ultraskill_UI_001","title":"Сверхспособность I","description":"Эти паразиты…","language":"Английский","audioUrl":"/nte-meta/game-audio/dc526c20325f7faeffff.ogg"},{"id":"ja-Play_Vo_Char_NPC032_Parry_001","title":"Парирование I","description":"И это всё, что ты можешь?","language":"Японский","audioUrl":"/nte-meta/game-audio/0f8e66128c5a0648df25.ogg"},{"id":"ja-Play_Vo_Char_NPC032_SSC_mint_001","title":"Особое переключение — Минт","description":"Ладно-ладно, Минт-«сенпай».","language":"Японский","audioUrl":"/nte-meta/game-audio/11ab8e08904a48752be0.ogg"},{"id":"en-Play_Vo_Char_NPC032_self_003","title":"Обо мне: побуждение","description":"Мои способности эспера дают о себе знать не только в бою. Даже в обычной жизни я могу внезапно выкинуть что-нибудь неуместное. Это не так опасно, как во время сражения, но я понятия не имею, что могу натворить в следующий раз, — а это сулит неприятности.","language":"Английский","audioUrl":"/nte-meta/game-audio/579ebfa2b144080a8e06.ogg"},{"id":"en-Play_Vo_Char_NPC032_Parry_002","title":"Парирование II","description":"Можешь бить и посильнее.","language":"Английский","audioUrl":"/nte-meta/game-audio/1df18678f746381576e9.ogg"},{"id":"ja-Play_Vo_Char_NPC032_chat_002","title":"Чат: винтажный магазин","description":"Я тут в Bagel заметила, что в Этеро недавно открылось несколько винтажных магазинчиков. Давай сходим туда, как будет время.","language":"Японский","audioUrl":"/nte-meta/game-audio/b087ba65ec605d6c5db6.ogg"},{"id":"ja-Play_Vo_Char_NPC032_Switch_003","title":"Переключение III","description":"Ну давай, сразимся!","language":"Японский","audioUrl":"/nte-meta/game-audio/f923e30bf1daa150a55b.ogg"},{"id":"en-Play_Vo_Char_NPC032_hobby_001","title":"Хобби","description":"Я коллекционирую всё, что мне приглянется: от сверхсекретных лимитированных тиражей таинственных коробок-коллабораций DSD с «Герцогом К» до бракованных выпусков «Недельной фантазии»… Да я даже могу просто подобрать прикольный камушек на пляже. Хочешь взглянуть? Пожалуй, оставим это до следующего раза.","language":"Английский","audioUrl":"/nte-meta/game-audio/f2bf4c36756e2c30eb2b.ogg"},{"id":"ja-Play_Vo_Char_NPC032_DodgeCombo_001","title":"Серия критических уклонений I","description":"Не поспеваешь за мной?","language":"Японский","audioUrl":"/nte-meta/game-audio/90ed7cacf5980d7423ab.ogg"},{"id":"ja-Play_Vo_Char_NPC032_TeammateDown_001","title":"Поражен товарищ по команде – Минт","description":"Дурёха-кошка, не надрывайся!","language":"Японский","audioUrl":"/nte-meta/game-audio/92fb95b785a580b86825.ogg"},{"id":"ja-Play_Vo_Char_NPC032_ug_001","title":"Вознесение персонажа I","description":"Теперь я могу сражаться с более сильными врагами.","language":"Японский","audioUrl":"/nte-meta/game-audio/7716bf326006fe4ceb7e.ogg"},{"id":"ja-Play_Vo_Char_NPC032_windfall_004","title":"Неожиданная добыча IV","description":"Надеюсь, я не растрачу на это всю свою удачу.","language":"Японский","audioUrl":"/nte-meta/game-audio/5f25cc33d9a9c496d014.ogg"},{"id":"en-Play_Vo_Char_NPC032_Fly_002","title":"Планирование II","description":"Спускаюсь по короткому пути.","language":"Английский","audioUrl":"/nte-meta/game-audio/2e1af5f7a7b04399501a.ogg"},{"id":"en-Play_Vo_Char_NPC032_skill_001","title":"Навык перенаправления I","description":"Этого недостаточно.","language":"Английский","audioUrl":"/nte-meta/game-audio/d23c198f7d636e66bb2e.ogg"},{"id":"en-Play_Vo_Char_NPC032_skill_002","title":"Навык перенаправления II","description":"Одним махом!..","language":"Английский","audioUrl":"/nte-meta/game-audio/90a54ce48c805e00c20d.ogg"},{"id":"ja-Play_Vo_Char_NPC032_gift_002","title":"Подарок получен II","description":"А ты знаешь, что мне нравится.","language":"Японский","audioUrl":"/nte-meta/game-audio/8dcf57921d923dab2a9f.ogg"},{"id":"ja-Play_Vo_Char_NPC032_talk_002","title":"Тема: скитания","description":"Если у меня нет планов, я люблю просто гулять куда глаза глядят. Забредаю в случайные места, и если вижу что-то интересное, то обязательно забираю себе. В детстве я называла это «охотой за сокровищами». И ведь ничего не изменилось, верно?","language":"Японский","audioUrl":"/nte-meta/game-audio/10fcc7ef8516ebabe763.ogg"},{"id":"ja-Play_Vo_Char_NPC032_windfall_001","title":"Неожиданная добыча I","description":"Везучий денёк. Надо бы заскочить в DSD.","language":"Японский","audioUrl":"/nte-meta/game-audio/372557e5826a73b401d0.ogg"},{"id":"en-Play_Vo_Char_NPC032_QTE_002","title":"Атака на входе II","description":"Я заставлю тебя замолчать!","language":"Английский","audioUrl":"/nte-meta/game-audio/a306170734e4c966dd3e.ogg"},{"id":"ja-Play_Vo_Char_NPC032_DodgeCombo_002","title":"Серия критических уклонений II","description":"Промахи недопустимы.","language":"Японский","audioUrl":"/nte-meta/game-audio/e1d7e89db3ec6866019d.ogg"},{"id":"en-Play_Vo_Char_NPC032_chat_001","title":"Чат: драконьи рога","description":"В бою от рогов толку меньше, чем от хвоста, но они хотя бы не доставляют мне столько хлопот. Ну, разве что когда я измеряю свой рост.","language":"Английский","audioUrl":"/nte-meta/game-audio/3fc9d222fc77282851d9.ogg"},{"id":"ja-Play_Vo_Char_NPC032_QTE_002","title":"Атака на входе II","description":"Я заставлю тебя замолчать!","language":"Японский","audioUrl":"/nte-meta/game-audio/a4031cb60216a70c05d4.ogg"},{"id":"en-Play_Vo_Char_NPC032_hp_002","title":"Низкий уровень здоровья II","description":"Всё нормально, я ещё могу сражаться.","language":"Английский","audioUrl":"/nte-meta/game-audio/a1100305553713d16518.ogg"},{"id":"en-Play_Vo_Char_NPC032_hstruck_002","title":"Сильный урон II","description":"…Я верну тебе должок!","language":"Английский","audioUrl":"/nte-meta/game-audio/6c24c3626cb298ffce88.ogg"},{"id":"ja-Play_Vo_Char_NPC032_gift_001","title":"Подарок получен I","description":"!.. Смотри, не пожалей, что подарил это мне.!.. Смотри, не пожалей, что подарила это мне.","language":"Японский","audioUrl":"/nte-meta/game-audio/bc8bec3fc0df64064666.ogg"},{"id":"ja-Play_Vo_Char_NPC032_greet_001","title":"Утреннее приветствие","description":"Доброе утро. Погляжу, ты прям горишь энтузиазмом. Может, подменишь меня в патруле, а?","language":"Японский","audioUrl":"/nte-meta/game-audio/54082ca054110deffdf7.ogg"},{"id":"ja-Play_Vo_Char_NPC032_QTE_001","title":"Атака на входе I","description":"Кончай с этим!","language":"Японский","audioUrl":"/nte-meta/game-audio/8cf049658775dbca52b0.ogg"},{"id":"ja-Play_Vo_Char_NPC032_windfall_005","title":"Неожиданная добыча V","description":"Это что, благословение Накупеды?","language":"Японский","audioUrl":"/nte-meta/game-audio/c2ef570c0f2a65efe79b.ogg"},{"id":"en-Play_Vo_Char_NPC032_Parry_001","title":"Парирование I","description":"И это всё, что ты можешь?","language":"Английский","audioUrl":"/nte-meta/game-audio/5ee9c65f49a2a2a74f07.ogg"},{"id":"ja-Play_Vo_Char_NPC032_self_001","title":"Обо мне: способность эспера","description":"Мой прежний капитан как-то назвал эту силу проклятием. Пускай она и дарует мощь, но способна погубить всё, что мне дорого. Помню, как вся извелась, когда случайно ранила друга… Но теперь я наконец всё поняла. Я приму эту силу и сделаю её частью себя. Лишь бы никогда больше не презирать себя за слабость в моменты, когда обязана быть сильной.","language":"Японский","audioUrl":"/nte-meta/game-audio/621b3ca4e24ed2f94223.ogg"},{"id":"en-Play_Vo_Char_NPC032_about_006","title":"О Бюро по борьбе с аномалиями","description":"Сразу проясню: я не пытаюсь очернить своих коллег. Я лишь к тому, что в ББА полно странных личностей, в особенности среди сотрудников ОС и ТОИ, чья работа связана с выездами и ликвидацией опасных аномалий. Если подумать, мне удалось прижиться в Бюро и многому научиться у прежнего капитана именно потому, что «обычных людей» здесь отродясь не водилось.","language":"Английский","audioUrl":"/nte-meta/game-audio/bf61f690d25b0e574f49.ogg"},{"id":"en-Play_Vo_Char_NPC032_hstruck_001","title":"Сильный урон I","description":"Уф!.. Теперь моя очередь!","language":"Английский","audioUrl":"/nte-meta/game-audio/8f764710664d1623b2ec.ogg"},{"id":"en-Play_Vo_Char_NPC032_Switch_003","title":"Переключение III","description":"Ну давай, сразимся!","language":"Английский","audioUrl":"/nte-meta/game-audio/f94173540a4fa9386be3.ogg"},{"id":"en-Play_Vo_Char_NPC032_vexation_001","title":"Проблемы","description":"С деньгами сейчас туговато. Так не хочется трогать заначку…","language":"Английский","audioUrl":"/nte-meta/game-audio/01f2bbada330e6e23248.ogg"},{"id":"ja-Play_Vo_Char_NPC032_chat_003","title":"Чат: слухи","description":"У меня нет крыльев, я не изрыгаю пламя и уж точно не хватаю врагов, чтобы покружить в небе, а потом ударить их со всей дури о землю. Серьёзно, кто эту чушь вообще выдумал?..","language":"Японский","audioUrl":"/nte-meta/game-audio/4d2c9f9652dd477cddd0.ogg"},{"id":"ja-Play_Vo_Char_NPC032_self_003","title":"Обо мне: побуждение","description":"Мои способности эспера дают о себе знать не только в бою. Даже в обычной жизни я могу внезапно выкинуть что-нибудь неуместное. Это не так опасно, как во время сражения, но я понятия не имею, что могу натворить в следующий раз, — а это сулит неприятности.","language":"Японский","audioUrl":"/nte-meta/game-audio/168910c36d9a5bd0ba38.ogg"},{"id":"ja-Play_Vo_Char_NPC032_weather_003","title":"Холодно","description":"Не то чтобы мне холодно… но давай покончим со всеми делами поскорее.","language":"Японский","audioUrl":"/nte-meta/game-audio/9cdac92a078c64b2e0f2.ogg"},{"id":"ja-Play_Vo_Char_NPC032S_skill_006","title":"Навык перенаправления VI","description":"Высвобождаю всю свою ярость!","language":"Японский","audioUrl":"/nte-meta/game-audio/aeca7f5a93485716d2f2.ogg"},{"id":"en-Play_Vo_Char_NPC032_chat_002","title":"Чат: винтажный магазин","description":"Я тут в Bagel заметила, что в Этеро недавно открылось несколько винтажных магазинчиков. Давай сходим туда, как будет время.","language":"Английский","audioUrl":"/nte-meta/game-audio/85c64c21f7f5c06b2e9e.ogg"},{"id":"ja-Play_Vo_Char_NPC032S_skill_004","title":"Навык перенаправления IV","description":"Я должна… пустить в ход когти!","language":"Японский","audioUrl":"/nte-meta/game-audio/3b10efc0d83d85fa7342.ogg"},{"id":"en-Play_Vo_Char_NPC032_ug_001","title":"Вознесение персонажа I","description":"Теперь я могу сражаться с более сильными врагами.","language":"Английский","audioUrl":"/nte-meta/game-audio/8903e72aab66f91dcbca.ogg"},{"id":"ja-Play_Vo_Char_NPC032_about_002","title":"О Минт II","description":"Эта дурёха-кошка никогда не скрывает своих истинных мыслей и чувств. Даже не знаю, хвалить её за это или просто назвать непрошибаемой… И всё же, будь все вокруг такими же прямолинейными, как Минт, жить стало бы гораздо проще.","language":"Японский","audioUrl":"/nte-meta/game-audio/2fde97e1ffad6a9f29ca.ogg"},{"id":"ja-Play_Vo_Char_NPC032_SSC_yly_002","title":"Особое переключение: Ирой","description":"Овцетенна, прикрой меня.","language":"Японский","audioUrl":"/nte-meta/game-audio/7f953a21188e247190ba.ogg"},{"id":"ja-Play_Vo_Char_NPC032_hp_002","title":"Низкий уровень здоровья II","description":"Всё нормально, я ещё могу сражаться.","language":"Японский","audioUrl":"/nte-meta/game-audio/a3a68bd304019450b5c1.ogg"},{"id":"en-Play_Vo_Char_NPC032_weather_003","title":"Холодно","description":"Не то чтобы мне холодно… но давай покончим со всеми делами поскорее.","language":"Английский","audioUrl":"/nte-meta/game-audio/3171728a5f06919384c6.ogg"},{"id":"en-Play_Vo_Char_NPC032_fh_002","title":"Исцеление II","description":"Я в отличной форме. Ещё враги есть?","language":"Английский","audioUrl":"/nte-meta/game-audio/74301bfd70b4aba26105.ogg"},{"id":"en-Play_Vo_Char_NPC032_greet_002","title":"Дневное приветствие","description":"Хочешь поесть рамен? Тут есть одна старая лапшичная, куда я постоянно забегала ещё во времена учёбы. Готовят там невероятно вкусно.","language":"Английский","audioUrl":"/nte-meta/game-audio/685ab751aa98abe5d64c.ogg"},{"id":"en-Play_Vo_Char_NPC032_struck_002","title":"Урон II","description":"Всего лишь царапина.","language":"Английский","audioUrl":"/nte-meta/game-audio/956e935b0864b27e438d.ogg"},{"id":"ja-Play_Vo_Char_NPC032_about_001","title":"О Минт I","description":"Минт-«сенпай» абсолютно не умеет читать атмосферу. Стоит тебе попытаться отдалиться, как она тут же лезет с разговорами. Эх, ну не могу я бросить эту дурёху-кошку одну.","language":"Японский","audioUrl":"/nte-meta/game-audio/fbeed3c1532bbe1801a0.ogg"},{"id":"ja-Play_Vo_Char_NPC032_Fly_001","title":"Планирование I","description":"Вот бы мне крылья…","language":"Японский","audioUrl":"/nte-meta/game-audio/0d87929e81a5205a0902.ogg"},{"id":"en-Play_Vo_Char_NPC032_skill_003","title":"Навык перенаправления III","description":"Попробуй заблокируй… если сможешь!","language":"Английский","audioUrl":"/nte-meta/game-audio/c0113474608b44bccb33.ogg"},{"id":"en-Play_Vo_Char_NPC032S_ultraskill_UI_006","title":"Сверхспособность VI","description":"Замышляешь побег? Даже не думай!","language":"Английский","audioUrl":"/nte-meta/game-audio/6ec6244ea78e068d57fc.ogg"},{"id":"ja-Play_Vo_Char_NPC032_anomaly_004","title":"Нуллификация II","description":"Значит, хочешь по-плохому.","language":"Японский","audioUrl":"/nte-meta/game-audio/c4ef4878f2625987adf3.ogg"},{"id":"ja-Play_Vo_Char_NPC032_greet_004","title":"Спокойной ночи","description":"Уже поздно. Тебе ведь не нужно провожать меня до дома, правда? Увидимся завтра, спокойной ночи.","language":"Японский","audioUrl":"/nte-meta/game-audio/088d9816f56b69d922b1.ogg"},{"id":"ja-Play_Vo_Char_NPC032_weather_004","title":"Жарко","description":"Сейчас бы фруктового льда…","language":"Японский","audioUrl":"/nte-meta/game-audio/e9f62c8f49633d08fbbf.ogg"},{"id":"en-Play_Vo_Char_NPC032_talk_001","title":"Тема: ОС","description":"Этот «Новый протокол безопасности при сдерживании» — сплошная головная боль. Там столько правил, что на каждом задании мне приходится дважды думать, прежде чем что-то сделать. Но с другой стороны, приучить себя соблюдать эти раздражающие ограничения, когда мои способности выходят из-под контроля — именно ради этого я здесь.","language":"Английский","audioUrl":"/nte-meta/game-audio/f5765ec4ec9daf0e4c37.ogg"},{"id":"ja-Play_Vo_Char_NPC032_dead_003","title":"Потеря сознания III","description":"Я не могу пасть здесь…","language":"Японский","audioUrl":"/nte-meta/game-audio/986746a64daaed19a0c9.ogg"},{"id":"en-Play_Vo_Char_NPC032_Switch_001","title":"Переключение I","description":"Назад!","language":"Английский","audioUrl":"/nte-meta/game-audio/c84abfb95cb2cffba2c8.ogg"},{"id":"en-Play_Vo_Char_NPC032_TeammateDown_002","title":"Поражён товарищ по команде — Ирой","description":"Передохни. Я заставлю их заплатить!..","language":"Английский","audioUrl":"/nte-meta/game-audio/2cb35135bad6d269b4ad.ogg"},{"id":"en-Play_Vo_Char_NPC032_ultraskill_UI_002","title":"Сверхспособность II","description":"Назад! Не лезьте под раздачу!","language":"Английский","audioUrl":"/nte-meta/game-audio/67722e4cc5b1c1d14d97.ogg"},{"id":"ja-Play_Vo_Char_NPC032_Fly_002","title":"Планирование II","description":"Спускаюсь по короткому пути.","language":"Японский","audioUrl":"/nte-meta/game-audio/3b385d0cbccb4d4c7fb0.ogg"},{"id":"ja-Play_Vo_Char_NPC032_hp_003","title":"Низкий уровень здоровья III","description":"Столько хлопот…","language":"Японский","audioUrl":"/nte-meta/game-audio/599ca157a6a8bb643918.ogg"},{"id":"ja-Play_Vo_Char_NPC032_hstruck_001","title":"Сильный урон I","description":"Уф!.. Теперь моя очередь!","language":"Японский","audioUrl":"/nte-meta/game-audio/b1359e6dfa60908cb301.ogg"},{"id":"en-Play_Vo_Char_NPC032_dead_003","title":"Потеря сознания III","description":"Я не могу пасть здесь…","language":"Английский","audioUrl":"/nte-meta/game-audio/8e33f517edc1c5fb7b54.ogg"},{"id":"en-Play_Vo_Char_NPC032_TeammateDown_001","title":"Поражен товарищ по команде – Минт","description":"Дурёха-кошка, не надрывайся!","language":"Английский","audioUrl":"/nte-meta/game-audio/3d86b01ebd27b14462ba.ogg"},{"id":"ja-Play_Vo_Char_NPC032_SSC_zero_003","title":"Особое переключение — Ноль","description":"Оценщик, это Шинку.Оценщица, это Шинку.","language":"Японский","audioUrl":"/nte-meta/game-audio/41b627ab2eeb4ec806cb.ogg"},{"id":"en-Play_Vo_Char_NPC032_deploy_001","title":"Отправка I","description":"Самого сильного я возьму на себя.","language":"Английский","audioUrl":"/nte-meta/game-audio/eda5b3d8df3ffcaa2e5b.ogg"},{"id":"en-Play_Vo_Char_NPC032_gift_002","title":"Подарок получен II","description":"А ты знаешь, что мне нравится.","language":"Английский","audioUrl":"/nte-meta/game-audio/83d49b06affa67d8cd0e.ogg"},{"id":"en-Play_Vo_Char_NPC032_SSC_zero_003","title":"Особое переключение — Ноль","description":"Оценщик, это Шинку.Оценщица, это Шинку.","language":"Английский","audioUrl":"/nte-meta/game-audio/f14442ae17d6e8e5c591.ogg"},{"id":"en-Play_Vo_Char_NPC032_talk_003","title":"Тема: Накупеда","description":"Накупеда — настоящий эксперт по сбережению монет: просто закидывает их в фонтан и держит на виду. Неудивительно, что эта аномалия всегда такая счастливая. Может, и мне так попробовать?","language":"Английский","audioUrl":"/nte-meta/game-audio/4497a6a95ff376bd672d.ogg"},{"id":"en-Play_Vo_Char_NPC032_windfall_004","title":"Неожиданная добыча IV","description":"Надеюсь, я не растрачу на это всю свою удачу.","language":"Английский","audioUrl":"/nte-meta/game-audio/dd5a2cda22b029d0eca3.ogg"},{"id":"en-Play_Vo_Char_NPC032_dead_001","title":"Потеря сознания I","description":"Оно и к лучшему…","language":"Английский","audioUrl":"/nte-meta/game-audio/f126cddf46a971ae637b.ogg"},{"id":"en-Play_Vo_Char_NPC032_gift_001","title":"Подарок получен I","description":"!.. Смотри, не пожалей, что подарил это мне.!.. Смотри, не пожалей, что подарила это мне.","language":"Английский","audioUrl":"/nte-meta/game-audio/4e2b58985ade536dfc70.ogg"},{"id":"en-Play_Vo_Char_NPC032_SSC_yly_002","title":"Особое переключение: Ирой","description":"Овцетенна, прикрой меня.","language":"Английский","audioUrl":"/nte-meta/game-audio/7647487cfe1f4b3754d2.ogg"},{"id":"ja-Play_Vo_Char_NPC032_deploy_002","title":"Отправка II","description":"Не волнуйся. Я буду держать себя в руках.","language":"Японский","audioUrl":"/nte-meta/game-audio/22aca8d173adcbd1aa91.ogg"},{"id":"ja-Play_Vo_Char_NPC032_self_002","title":"Обо мне: отношения","description":"«Я в Бюро всегда работаю в одиночку»? Да эта дурёха-кошка просто треплет языком… Ну, чисто технически я ведь не могу остаться одна, если она постоянно таскает нас с Ирой за собой, разве нет?","language":"Японский","audioUrl":"/nte-meta/game-audio/1759324bb7d8c804e8c5.ogg"},{"id":"ja-Play_Vo_Char_NPC032_Switch_002","title":"Переключение II","description":"Так, дальше я сама!..","language":"Японский","audioUrl":"/nte-meta/game-audio/5b13ba2b06e66e75b34b.ogg"},{"id":"ja-Play_Vo_Char_NPC032_ultraskill_UI_002","title":"Сверхспособность II","description":"Назад! Не лезьте под раздачу!","language":"Японский","audioUrl":"/nte-meta/game-audio/6541abb326145e6d399d.ogg"}]') WHERE character_id='ec50ff3d-4340-4dad-89b4-1e14b95d6c21' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-08-25 11:17:01');

