UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Любящий аномалии наблюдатель","iconUrl":"/nte-meta/game-assets/bc8347fd570cd2e651c9.webp","description":"Даёт Эдгару 1 Ключ истины, когда любой товарищ по команде использует навык поддержки."},{"level":2,"kind":"awakening","name":"Стажер-охотник за аномалиями","iconUrl":"/nte-meta/game-assets/d04a0b978c02b1f282ac.webp","description":"Ограничивает продление перезарядки от навыка «Дикое течение» до 3 сек."},{"level":3,"kind":"awakening","name":"Один из детективов «Эйбона»","iconUrl":"/nte-meta/game-assets/3d385c8f8e31f8f2df90.webp","description":"Повышает эффективность исцеления «Дикого течения» на 15 % для союзников, у которых осталось менее 30 % ОЗ."},{"level":4,"kind":"awakening","name":"Опытный стратег","iconUrl":"/nte-meta/game-assets/151540667f5b34ea7d2b.webp","description":"+50 % к урону «Дикого течения»"},{"level":5,"kind":"awakening","name":"Хранитель света магазина древностей","iconUrl":"/nte-meta/game-assets/80aad324c1aa32cda16e.webp","description":"+20 % к макс. ОЗ Эдгара"},{"level":6,"kind":"awakening","name":"Гость с планеты Любопытство","iconUrl":"/nte-meta/game-assets/efc079b76915a1f57a80.webp","description":"Даёт 15 % к защите всем союзникам в радиусе действия Поминок по Финнегану."},{"level":3,"kind":"resonance","name":"Гонка за знаниями","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень навыков «Дикое течение», «Поминки по Финнегану» и «Вес знаний» на 1."},{"level":6,"kind":"resonance","name":"Острая проницательность","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Эдгар волнуется за союзников, и его мысли путаются. За каждую потерю любым товарищем по команде ОЗ в размере 3 % от его макс. ОЗ Эдгар получает 1 заряд «Поминок по Финнегану» (не более 20 зарядов). После применения «Поминок по Финнегану» счётчик преобразованных зарядов обнуляется."}]') WHERE character_id='edgar' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:25:55');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"en-Play_Vo_Char_NPC012_chat_003","title":"Чат: аномалия","description":"Мне нравятся аномалии. Я вступил в Эйбон, потому что хотел узнать о них больше. Для начала я могу наблюдать за Тайгедо вблизи…","language":"Английский","audioUrl":"/nte-meta/game-audio/09ea8e51ace9ad4c3ff3.ogg"},{"id":"en-Play_Vo_Char_NPC012_greet_004","title":"Спокойной ночи","description":"В детстве мама рассказывала мне сказку об Облачных Овцах. Когда ребёнок засыпает, Облачные Овцы взбивают ему подушку, чтобы он спокойно проспал всю ночь. Но Облачные Овцы ложатся рано, так что если ложиться слишком поздно, они уже могут спать на луне. Всё же надеюсь, что ты встретишь их сегодня ночью. Спокойной ночи.","language":"Английский","audioUrl":"/nte-meta/game-audio/d6645dc4142d6dcbd90c.ogg"},{"id":"ja-Play_Vo_Char_NPC012_skill_002","title":"Навык перенаправления II","description":"Делаю, что могу.","language":"Японский","audioUrl":"/nte-meta/game-audio/dc5fd1ed23f75ac841c3.ogg"},{"id":"en-Play_Vo_Char_NPC012_about_003","title":"О Сакири","description":"Кирумару довольно тяжёлый… Сакири, должно быть, очень сильная.","language":"Английский","audioUrl":"/nte-meta/game-audio/ce4c05c4ce4525bd4e92.ogg"},{"id":"ja-Play_Vo_Char_NPC012_ug_002","title":"Вознесение персонажа II","description":"Ещё так многому нужно научиться.","language":"Японский","audioUrl":"/nte-meta/game-audio/b6f7df27f0fa25ac9539.ogg"},{"id":"ja-Play_Vo_Char_NPC012_SSC_003","title":"Особое переключение — Сакири","description":"Сакири, дай Кирумару спокойно переварить еду.","language":"Японский","audioUrl":"/nte-meta/game-audio/cc2836cb5f4e1d19988d.ogg"},{"id":"ja-Play_Vo_Char_NPC012_windfall_001","title":"Неожиданная добыча I","description":"Готово.","language":"Японский","audioUrl":"/nte-meta/game-audio/fa333d8c7cb90a1c1cbd.ogg"},{"id":"ja-Play_Vo_Char_NPC012_windfall_003","title":"Неожиданная добыча III","description":"Хотори это точно понравится.","language":"Японский","audioUrl":"/nte-meta/game-audio/81c46e0045e7522e9cfc.ogg"},{"id":"en-Play_Vo_Char_NPC012_ug_002","title":"Вознесение персонажа II","description":"Ещё так многому нужно научиться.","language":"Английский","audioUrl":"/nte-meta/game-audio/f279e4121e60161a9f44.ogg"},{"id":"ja-Play_Vo_Char_NPC012_DodgeCombo_002","title":"Серия критических уклонений II","description":"Мне следует держать дистанцию.","language":"Японский","audioUrl":"/nte-meta/game-audio/ab680f8186ed94a6f0f9.ogg"},{"id":"ja-Play_Vo_Char_NPC012_gift_002","title":"Подарок получен II","description":"Мне очень нравится. Спасибо за все твои старания!","language":"Японский","audioUrl":"/nte-meta/game-audio/af7c4e09818f80a544be.ogg"},{"id":"ja-Play_Vo_Char_NPC012_greet_003","title":"Вечернее приветствие","description":"Ещё один продуктивный день. Я многому научился.","language":"Японский","audioUrl":"/nte-meta/game-audio/70a9b46f59dd48c97343.ogg"},{"id":"en-Play_Vo_Char_NPC012_ug_001","title":"Вознесение персонажа I","description":"Мои знания множатся.","language":"Английский","audioUrl":"/nte-meta/game-audio/99fc90c286b945afc293.ogg"},{"id":"en-Play_Vo_Char_NPC012_Fly_002","title":"Планирование II","description":"Фух, давай поскорее приземлимся.","language":"Английский","audioUrl":"/nte-meta/game-audio/679f9e455b62c2e97910.ogg"},{"id":"en-Play_Vo_Char_NPC012_talk_001","title":"Тема: Фриззл","description":"Кстати, Фриззлы — это любимая аномалия чаек?","language":"Английский","audioUrl":"/nte-meta/game-audio/2b5231a013d68569eec6.ogg"},{"id":"ja-Play_Vo_Char_NPC012_about_002","title":"О Хотори","description":"Хотори всегда говорит, что в работе с антиквариатом главное — иметь наметанный глаз. Но что это вообще значит? Ни в одной книге это толком не объясняют… Или это просто тот самый опыт, который приходит, когда постоянно копаешься в старинных вещах?","language":"Японский","audioUrl":"/nte-meta/game-audio/d8b758ab6dc6ee81f51c.ogg"},{"id":"en-Play_Vo_Char_NPC012_deploy_002","title":"Отправка II","description":"Я выложусь по полной.","language":"Английский","audioUrl":"/nte-meta/game-audio/a5233e366b99207fb318.ogg"},{"id":"en-Play_Vo_Char_NPC012_TeammateDown_005","title":"Поражен товарищ по команде – Адлер","description":"Адлер! Нет…","language":"Английский","audioUrl":"/nte-meta/game-audio/d93786a43dde87993022.ogg"},{"id":"ja-Play_Vo_Char_NPC012_about_001","title":"Об Адлере","description":"Я хочу быть таким же организованным и внимательным к мелочам, как Адлер. Мне ещё многому предстоит научиться.","language":"Японский","audioUrl":"/nte-meta/game-audio/f56c7c3a7d6289721843.ogg"},{"id":"ja-Play_Vo_Char_NPC012_talk_001","title":"Тема: Фриззл","description":"Кстати, Фриззлы — это любимая аномалия чаек?","language":"Японский","audioUrl":"/nte-meta/game-audio/4e356dfcafd76b12b06a.ogg"},{"id":"ja-Play_Vo_Char_NPC012_hp_003","title":"Низкий уровень здоровья III","description":"Ай… больно.","language":"Японский","audioUrl":"/nte-meta/game-audio/366102dd3112cb13e0b8.ogg"},{"id":"ja-Play_Vo_Char_NPC012_Switch_001","title":"Переключение I","description":"А вот и я.","language":"Японский","audioUrl":"/nte-meta/game-audio/d8b637726e626c509131.ogg"},{"id":"en-Play_Vo_Char_NPC012_DodgeCombo_001","title":"Серия критических уклонений I","description":"Уклонился!","language":"Английский","audioUrl":"/nte-meta/game-audio/c5daa51f0b5991627e15.ogg"},{"id":"ja-Play_Vo_Char_NPC012_about_004","title":"О Кирумару","description":"Вообще-то давно хотелось заглянуть в желудок Кирумару. Кирумару не против, но Сакири не разрешает…","language":"Японский","audioUrl":"/nte-meta/game-audio/846b43970968b6c94ea4.ogg"},{"id":"ja-Play_Vo_Char_NPC012_QTE_002","title":"Атака на входе II","description":"Слабое место.","language":"Японский","audioUrl":"/nte-meta/game-audio/b52cb3f702955cbc0774.ogg"},{"id":"ja-Play_Vo_Char_NPC012_TeammateDown_005","title":"Поражен товарищ по команде – Адлер","description":"Адлер! Нет…","language":"Японский","audioUrl":"/nte-meta/game-audio/f592667c9a766a60d9a4.ogg"},{"id":"en-Play_Vo_Char_NPC012_gift_001","title":"Подарок получен I","description":"Оценщик, ты часом не умеешь ещё и читать мысли своей способностью эспера? Оценщица, ты часом не умеешь ещё и читать мысли своей способностью эспера?","language":"Английский","audioUrl":"/nte-meta/game-audio/f83b84c6f892b22c1a80.ogg"},{"id":"en-Play_Vo_Char_NPC012_windfall_006","title":"Неожиданная добыча VI","description":"Кирумару точно это заинтересует.","language":"Английский","audioUrl":"/nte-meta/game-audio/dc71e0caaebbc6892c39.ogg"},{"id":"ja-Play_Vo_Char_NPC012_talk_004","title":"Тема: Данзабуру","description":"Данзабуру могут принимать человеческий облик, чтобы воровать. Но их маскировку легко раскусить: даже превращаясь в человека, они всё равно носят свою фирменную красную салфетку. Когда стоишь за прилавком, внимательнее следи за такими «покупателями».","language":"Японский","audioUrl":"/nte-meta/game-audio/a11cb0d2475a1897054c.ogg"},{"id":"ja-Play_Vo_Char_NPC012_windfall_002","title":"Неожиданная добыча II","description":"Оценщик должен это увидеть.Оценщица должна это увидеть.","language":"Японский","audioUrl":"/nte-meta/game-audio/2b14baf52e06c3bfd86f.ogg"},{"id":"ja-Play_Vo_Char_NPC012_chat_002","title":"Чат: чемодан","description":"Хотелось бы, чтобы он был полегче. Это и есть тот самый вес знаний?","language":"Японский","audioUrl":"/nte-meta/game-audio/571c1e1c6a5723755372.ogg"},{"id":"en-Play_Vo_Char_NPC012_dead_003","title":"Потеря сознания III","description":"Как такое вообще возможно…?","language":"Английский","audioUrl":"/nte-meta/game-audio/d122bf25d31b49d2bb01.ogg"},{"id":"ja-Play_Vo_Char_NPC012_aoe_UI_001","title":"Сверхспособность I","description":"Позволь мне вылечить тебя.","language":"Японский","audioUrl":"/nte-meta/game-audio/7fa9cdc60183d0943dcc.ogg"},{"id":"en-Play_Vo_Char_NPC012_anomaly_004","title":"Нуллификация II","description":"Мы ещё увидимся… правда?","language":"Английский","audioUrl":"/nte-meta/game-audio/061a018b4582c3202e96.ogg"},{"id":"en-Play_Vo_Char_NPC012_Parry_001","title":"Парирование I","description":"Самое время.","language":"Английский","audioUrl":"/nte-meta/game-audio/0d0c4b113d8a03fc08ba.ogg"},{"id":"en-Play_Vo_Char_NPC012_windfall_002","title":"Неожиданная добыча II","description":"Оценщик должен это увидеть.Оценщица должна это увидеть.","language":"Английский","audioUrl":"/nte-meta/game-audio/963c00ea5008e2970247.ogg"},{"id":"en-Play_Vo_Char_NPC012_gift_003","title":"Подарок получен III","description":"С-спасибо.","language":"Английский","audioUrl":"/nte-meta/game-audio/9fabec390d0a8de19617.ogg"},{"id":"en-Play_Vo_Char_NPC012_SSC_005","title":"Особое переключение — Адлер","description":"Адлер, мне ещё многому нужно у тебя научиться.","language":"Английский","audioUrl":"/nte-meta/game-audio/bb35aa28ee11392e6752.ogg"},{"id":"en-Play_Vo_Char_NPC012_talk_004","title":"Тема: Данзабуру","description":"Данзабуру могут принимать человеческий облик, чтобы воровать. Но их маскировку легко раскусить: даже превращаясь в человека, они всё равно носят свою фирменную красную салфетку. Когда стоишь за прилавком, внимательнее следи за такими «покупателями».","language":"Английский","audioUrl":"/nte-meta/game-audio/ee4dabaf48b201d16434.ogg"},{"id":"en-Play_Vo_Char_NPC012_TeammateDown_004","title":"Поражен товарищ по команде – Хотори","description":"Хотори…? Как такое вообще возможно…!","language":"Английский","audioUrl":"/nte-meta/game-audio/f2acee226cb2850146bb.ogg"},{"id":"ja-Play_Vo_Char_NPC012_about_006","title":"О Даффодил","description":"Когда я с Даффодил, даже если мы мало говорим, никогда не бывает неловко. Может… нам обоим просто нравится покой и тишина?","language":"Японский","audioUrl":"/nte-meta/game-audio/164d50b4679034c8106c.ogg"},{"id":"ja-Play_Vo_Char_NPC012_fh_002","title":"Исцеление II","description":"Освежающе.","language":"Японский","audioUrl":"/nte-meta/game-audio/08fef01a88cf05997eda.ogg"},{"id":"ja-Play_Vo_Char_NPC012_ug_003","title":"Вознесение персонажа III","description":"Хочу помочь.","language":"Японский","audioUrl":"/nte-meta/game-audio/18ad50fcf3a0155867aa.ogg"},{"id":"ja-Play_Vo_Char_NPC012_vexation_001","title":"Проблемы","description":"В последнее время моё зрение ухудшилось. Наналли сказала, что если я и дальше буду читать в полумраке, тоже буду ходить в очках, как она…","language":"Японский","audioUrl":"/nte-meta/game-audio/9798762927c5b545b170.ogg"},{"id":"en-Play_Vo_Char_NPC012_windfall_005","title":"Неожиданная добыча V","description":"Это могло бы помочь Адлеру.","language":"Английский","audioUrl":"/nte-meta/game-audio/b1f51e0c9765c74e811b.ogg"},{"id":"ja-Play_Vo_Char_NPC012_gift_001","title":"Подарок получен I","description":"Оценщик, ты часом не умеешь ещё и читать мысли своей способностью эспера? Оценщица, ты часом не умеешь ещё и читать мысли своей способностью эспера?","language":"Японский","audioUrl":"/nte-meta/game-audio/d36579e237a6302fde91.ogg"},{"id":"ja-Play_Vo_Char_NPC012_greet_001","title":"Утреннее приветствие","description":"Доброе утро. Какие у тебя планы на сегодня? Можно с тобой?","language":"Японский","audioUrl":"/nte-meta/game-audio/84348d68a875f9a94be8.ogg"},{"id":"en-Play_Vo_Char_NPC012_anomaly_003","title":"Нуллификация I","description":"В следующий раз нужно придумать, как это сдержать…","language":"Английский","audioUrl":"/nte-meta/game-audio/3e1515094f8568f15f3f.ogg"},{"id":"en-Play_Vo_Char_NPC012_kill_001","title":"Убийство I","description":"Проблема решена.","language":"Английский","audioUrl":"/nte-meta/game-audio/dbd55b4ab60804337632.ogg"},{"id":"en-Play_Vo_Char_NPC012_SSC_002","title":"Особое переключение — Наналли","description":"Давайте сражаться как одна семья.","language":"Английский","audioUrl":"/nte-meta/game-audio/75178b42e8813eb4932e.ogg"},{"id":"en-Play_Vo_Char_NPC012_aoe_UI_001","title":"Сверхспособность I","description":"Позволь мне вылечить тебя.","language":"Английский","audioUrl":"/nte-meta/game-audio/fc1e50ae3c66be94049e.ogg"},{"id":"en-Play_Vo_Char_NPC012_gift_002","title":"Подарок получен II","description":"Мне очень нравится. Спасибо за все твои старания!","language":"Английский","audioUrl":"/nte-meta/game-audio/4c79875977e1db67cabe.ogg"},{"id":"en-Play_Vo_Char_NPC012_hobby_001","title":"Хобби","description":"Чтение и наблюдение за аномалиями.","language":"Английский","audioUrl":"/nte-meta/game-audio/a562dfaf24a042ccc851.ogg"},{"id":"en-Play_Vo_Char_NPC012_hstruck_002","title":"Сильный урон II","description":"…у меня голова кружится.","language":"Английский","audioUrl":"/nte-meta/game-audio/100154e701104a8ac745.ogg"},{"id":"en-Play_Vo_Char_NPC012_vexation_001","title":"Проблемы","description":"В последнее время моё зрение ухудшилось. Наналли сказала, что если я и дальше буду читать в полумраке, тоже буду ходить в очках, как она…","language":"Английский","audioUrl":"/nte-meta/game-audio/3998dd4b9a140465fdad.ogg"},{"id":"ja-Play_Vo_Char_NPC012_hstruck_002","title":"Сильный урон II","description":"…у меня голова кружится.","language":"Японский","audioUrl":"/nte-meta/game-audio/3bb145bbc4615ebfd369.ogg"},{"id":"ja-Play_Vo_Char_NPC012_talk_003","title":"Тема: Бонзита","description":"Вечно всё забываю, всё время любопытно…? Хм…","language":"Японский","audioUrl":"/nte-meta/game-audio/6d4a16e2a2b0a21dca2b.ogg"},{"id":"ja-Play_Vo_Char_NPC012_TeammateDown_002","title":"Поражен товарищ по команде – Наналли","description":"Наналли, отдохни немного.","language":"Японский","audioUrl":"/nte-meta/game-audio/7ce3c199536b2d712ee0.ogg"},{"id":"en-Play_Vo_Char_NPC012_struck_001","title":"Урон I","description":"М-м.","language":"Английский","audioUrl":"/nte-meta/game-audio/b68ac76ec7e2f84f983c.ogg"},{"id":"en-Play_Vo_Char_NPC012_TeammateDown_006","title":"Поражен товарищ по команде – Даффодил","description":"Уф, Даффодил…","language":"Английский","audioUrl":"/nte-meta/game-audio/d2464614f18b122c3284.ogg"},{"id":"ja-Play_Vo_Char_NPC012_self_001","title":"Обо мне: способность эспера","description":"Это, конечно, не какая‑то суперспособность, но Хотори сказала: «Не дай этим курьерам тебя 