UPDATE character_profiles SET awakenings_json=json('[{"level":1,"kind":"awakening","name":"Цветущий взгляд","iconUrl":"/nte-meta/game-assets/bdfec20becc0f3e272f9.webp","description":"Наносит 1 дополнительный удар с уроном в размере 200 % от Атака по противникам более низкого уровня при первом попадании. Этот урон игнорирует 75 % защиты цели."},{"level":2,"kind":"awakening","name":"В поисках призвания","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"После успешного применения «Оценки и гравировки» вы получаете 8 ед. энергии сверхспособности."},{"level":3,"kind":"awakening","name":"Записи об аномалиях","iconUrl":"/nte-meta/game-assets/0609f4bbdf4963557939.webp","description":"Сверхспособность «Деление на ноль»: шанс критического удара увеличивается на 50 %."},{"level":4,"kind":"awakening","name":"Неопределённые факторы","iconUrl":"/nte-meta/game-assets/ddcaefad752fd749bb31.webp","description":"Урон от сверхспособности «Деление на ноль» увеличивается на 0,1 % за каждое 1 очко базовой атаки Зеро, вплоть до максимума в 25 %."},{"level":5,"kind":"awakening","name":"Теопнеустос","iconUrl":"/nte-meta/game-assets/9f451966e85111da5de8.webp","description":"Увеличивает Атака Зеро на 10 % на 20 сек. при применении навыка поддержки."},{"level":6,"kind":"awakening","name":"Обманчивое освобождение","iconUrl":"/nte-meta/game-assets/b913d2ee16e5a95fb33a.webp","description":"Доп. коэффициент урона «Оценки и гравировки» увеличивается до 300 % от атаки."},{"level":3,"kind":"resonance","name":"Распознавание","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень навыков «Оценка», «Оценка и гравировка» и «Деление на ноль» на 1."},{"level":6,"kind":"resonance","name":"Нулевое отображение","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Когда Ноль запускает любой цикл эспера космоса, атака всей команды увеличивается на 12 % на 20 сек."}]') WHERE character_id='esper-zero' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-28 14:58:37');

UPDATE character_profiles SET abilities_json=json('[{"id":"GA_Female051_UltraSkill","name":"Деление на ноль","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/498d8117fd2f3573fbc1.webp","description":"Танцуя, я разрываю связи между Нексусами, что вижу лишь я. Наносит несколько ударов урона космоса по области.\n\nЯ чувствую нексус аномалии, связанный невидимыми, неслышимыми, неосязаемыми узами… Все они мгновенно разрубаются одним изящным ударом.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 132.7 % + 5.3 % *4 + 177.5 % + 168.6 % · 2: 143.3 % + 5.7 % *4 + 191.7 % + 182.1 % · 3: 154.8 % + 6.2 % *4 + 207 % + 196.7 % · 4: 167.2 % + 6.7 % *4 + 223.6 % + 212.4 % · 5: 180.5 % + 7.2 % *4 + 241.5 % + 229.4 % · 6: 195 % + 7.8 % *4 + 260.8 % + 247.7 % · 7: 210.6 % + 8.4 % *4 + 281.7 % + 267.5 % · 8: 227.4 % + 9.1 % *4 + 304.2 % + 289 % · 9: 245.6 % + 9.8 % *4 + 328.5 % + 312.1 % · 10: 265.3 % + 10.6 % *4 + 354.8 % + 337 % · 11: 286.5 % + 11.4 % *4 + 383.2 % + 364 % · 12: 309.4 % + 12.4 % *4 + 413.9 % + 393.1 % · 13: 334.2 % + 13.3 % *4 + 447 % + 424.6 %"}]},{"id":"GA_Female051_Skill","name":"Оценка и гравировка","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/46d11502e8d986fe3f62.webp","description":"Промах, враг раскрыт! Совершает 3 быстрых удара оружием, затем прыгает в воздух для зарядки и применяет Пушку эспера, нанося 1 удар урона космоса по области. Дополнительно наносит первому пораженному противнику, чей уровень ниже уровня Ноль, 1 удар урона космоса.\n\nОчерченная тонкими штрихами сюрреалистическая сцена возникает словно из ниоткуда…","attributes":[{"id":"parameter-0","label":"Множитель удара оружием","value":"1: 20 %+20 %+125.6 %+134.4 % · 2: 21.6 %+21.6 %+135.6 %+145.2 % · 3: 23.3 %+23.3 %+146.5 %+156.8 % · 4: 25.2 %+25.2 %+158.2 %+169.3 % · 5: 27.2 %+27.2 %+170.9 %+182.8 % · 6: 29.4 %+29.4 %+184.5 %+197.5 % · 7: 31.7 %+31.7 %+199.3 %+213.3 % · 8: 34.3 %+34.3 %+215.3 %+230.3 % · 9: 37 %+37 %+232.5 %+248.8 % · 10: 40 %+40 %+251.1 %+268.7 % · 11: 43.2 %+43.2 %+271.2 %+290.2 % · 12: 46.6 %+46.6 %+292.9 %+313.4 % · 13: 50.4 %+50.4 %+316.3 %+338.4 %"},{"id":"parameter-1","label":"Множитель доп. урона","value":"1: 200 % · 2: 200 % · 3: 200 % · 4: 200 % · 5: 200 % · 6: 200 % · 7: 200 % · 8: 200 % · 9: 200 % · 10: 200 % · 11: 200 % · 12: 200 % · 13: 200 %"}]}]') WHERE character_id='esper-zero' AND updated_at<='2026-10-22 19:27:33' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-28 14:58:37');

